window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["其他"] = {"zhuanlifashishixize":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国专利法》（以下简称专利法），制定本细则。"},{"i":2,"n":"第二条","txt":"专利法和本细则规定的各种手续，应当以书面形式或者国务院专利行政部门规定的其他形式办理。以电子数据交换等方式能够有形地表现所载内容，并可以随时调取查用的数据电文（以下统称电子形式），视为书面形式。"},{"i":3,"n":"第三条","txt":"依照专利法和本细则规定提交的各种文件应当使用中文；国家有统一规定的科技术语的，应当采用规范词；外国人名、地名和科技术语没有统一中文译文的，应当注明原文。"},{"i":4,"n":"第四条","txt":"向国务院专利行政部门邮寄的各种文件，以寄出的邮戳日为递交日；邮戳日不清晰的，除当事人能够提出证明外，以国务院专利行政部门收到日为递交日。"},{"i":5,"n":"第五条","txt":"专利法和本细则规定的各种期限开始的当日不计算在期限内，自下一日开始计算。期限以年或者月计算的，以其最后一月的相应日为期限届满日；该月无相应日的，以该月最后一日为期限届满日；期限届满日是法定休假日的，以休假日后的第一个工作日为期限届满日。"},{"i":6,"n":"第六条","txt":"当事人因不可抗拒的事由而延误专利法或者本细则规定的期限或者国务院专利行政部门指定的期限，导致其权利丧失的，自障碍消除之日起2个月内且自期限届满之日起2年内，可以向国务院专利行政部门请求恢复权利。"},{"i":7,"n":"第七条","txt":"专利申请涉及国防利益需要保密的，由国防专利机构受理并进行审查；国务院专利行政部门受理的专利申请涉及国防利益需要保密的，应当及时移交国防专利机构进行审查。经国防专利机构审查没有发现驳回理由的，由国务院专利行政部门作出授予国防专利权的决定。"},{"i":8,"n":"第八条","txt":"专利法第十九条所称在中国完成的发明或者实用新型，是指技术方案的实质性内容在中国境内完成的发明或者实用新型。"},{"i":9,"n":"第九条","txt":"国务院专利行政部门收到依照本细则第八条规定递交的请求后，经过审查认为该发明或者实用新型可能涉及国家安全或者重大利益需要保密的，应当在请求递交日起2个月内向申请人发出保密审查通知；情况复杂的，可以延长2个月。"},{"i":10,"n":"第十条","txt":"专利法第五条所称违反法律的发明创造，不包括仅其实施为法律所禁止的发明创造。"},{"i":11,"n":"第十一条","txt":"申请专利应当遵循诚实信用原则。提出各类专利申请应当以真实发明创造活动为基础，不得弄虚作假。"},{"i":12,"n":"第十二条","txt":"除专利法第二十八条和第四十二条规定的情形外，专利法所称申请日，有优先权的，指优先权日。"},{"i":13,"n":"第十三条","txt":"专利法第六条所称执行本单位的任务所完成的职务发明创造，是指："},{"i":14,"n":"第十四条","txt":"专利法所称发明人或者设计人，是指对发明创造的实质性特点作出创造性贡献的人。在完成发明创造过程中，只负责组织工作的人、为物质技术条件的利用提供方便的人或者从事其他辅助工作的人，不是发明人或者设计人。"},{"i":15,"n":"第十五条","txt":"除依照专利法第十条规定转让专利权外，专利权因其他事由发生转移的，当事人应当凭有关证明文件或者法律文书向国务院专利行政部门办理专利权转移手续。"},{"i":16,"n":"第十六条","txt":"专利工作应当贯彻党和国家知识产权战略部署，提升我国专利创造、运用、保护、管理和服务水平，支持全面创新，促进创新型国家建设。"},{"i":17,"n":"第十七条","txt":"申请专利的，应当向国务院专利行政部门提交申请文件。申请文件应当符合规定的要求。"},{"i":18,"n":"第十八条","txt":"依照专利法第十八条第一款的规定委托专利代理机构在中国申请专利和办理其他专利事务的，涉及下列事务，申请人或者专利权人可以自行办理："},{"i":19,"n":"第十九条","txt":"发明、实用新型或者外观设计专利申请的请求书应当写明下列事项："},{"i":20,"n":"第二十条","txt":"发明或者实用新型专利申请的说明书应当写明发明或者实用新型的名称，该名称应当与请求书中的名称一致。说明书应当包括下列内容："},{"i":21,"n":"第二十一条","txt":"发明或者实用新型的几幅附图应当按照“图1，图2，……”顺序编号排列。"},{"i":22,"n":"第二十二条","txt":"权利要求书应当记载发明或者实用新型的技术特征。"},{"i":23,"n":"第二十三条","txt":"权利要求书应当有独立权利要求，也可以有从属权利要求。"},{"i":24,"n":"第二十四条","txt":"发明或者实用新型的独立权利要求应当包括前序部分和特征部分，按照下列规定撰写："},{"i":25,"n":"第二十五条","txt":"发明或者实用新型的从属权利要求应当包括引用部分和限定部分，按照下列规定撰写："},{"i":26,"n":"第二十六条","txt":"说明书摘要应当写明发明或者实用新型专利申请所公开内容的概要，即写明发明或者实用新型的名称和所属技术领域，并清楚地反映所要解决的技术问题、解决该问题的技术方案的要点以及主要用途。"},{"i":27,"n":"第二十七条","txt":"申请专利的发明涉及新的生物材料，该生物材料公众不能得到，并且对该生物材料的说明不足以使所属领域的技术人员实施其发明的，除应当符合专利法和本细则的有关规定外，申请人还应当办理下列手续："},{"i":28,"n":"第二十八条","txt":"发明专利申请人依照本细则第二十七条的规定保藏生物材料样品的，在发明专利申请公布后，任何单位或者个人需要将该专利申请所涉及的生物材料作为实验目的使用的，应当向国务院专利行政部门提出请求，并写明下列事项："},{"i":29,"n":"第二十九条","txt":"专利法所称遗传资源，是指取自人体、动物、植物或者微生物等含有遗传功能单位并具有实际或者潜在价值的材料和利用此类材料产生的遗传信息；专利法所称依赖遗传资源完成的发明创造，是指利用了遗传资源的遗传功能完成的发明创造。"},{"i":30,"n":"第三十条","txt":"申请人应当就每件外观设计产品所需要保护的内容提交有关图片或者照片。"},{"i":31,"n":"第三十一条","txt":"外观设计的简要说明应当写明外观设计产品的名称、用途，外观设计的设计要点，并指定一幅最能表明设计要点的图片或者照片。省略视图或者请求保护色彩的，应当在简要说明中写明。"},{"i":32,"n":"第三十二条","txt":"国务院专利行政部门认为必要时，可以要求外观设计专利申请人提交使用外观设计的产品样品或者模型。样品或者模型的体积不得超过30厘米×30厘米×30厘米，重量不得超过15公斤。易腐、易损或者危险品不得作为样品或者模型提交。"},{"i":33,"n":"第三十三条","txt":"专利法第二十四条第（二）项所称中国政府承认的国际展览会，是指国际展览会公约规定的在国际展览局注册或者由其认可的国际展览会。"},{"i":34,"n":"第三十四条","txt":"申请人依照专利法第三十条的规定要求外国优先权的，申请人提交的在先申请文件副本应当经原受理机构证明。依照国务院专利行政部门与该受理机构签订的协议，国务院专利行政部门通过电子交换等途径获得在先申请文件副本的，视为申请人提交了经该受理机构证明的在先申请文件副本。要求本国优先权，申请人在请求书中写明在先申请的申请日和申请号的，视为提交了在先申请文件副本。"},{"i":35,"n":"第三十五条","txt":"申请人在一件专利申请中，可以要求一项或者多项优先权；要求多项优先权的，该申请的优先权期限从最早的优先权日起计算。"},{"i":36,"n":"第三十六条","txt":"申请人超出专利法第二十九条规定的期限，向国务院专利行政部门就相同主题提出发明或者实用新型专利申请，有正当理由的，可以在期限届满之日起2个月内请求恢复优先权。"},{"i":37,"n":"第三十七条","txt":"发明或者实用新型专利申请人要求了优先权的，可以自优先权日起16个月内或者自申请日起4个月内，请求在请求书中增加或者改正优先权要求。"},{"i":38,"n":"第三十八条","txt":"在中国没有经常居所或者营业所的申请人，申请专利或者要求外国优先权的，国务院专利行政部门认为必要时，可以要求其提供下列文件："},{"i":39,"n":"第三十九条","txt":"依照专利法第三十一条第一款规定，可以作为一件专利申请提出的属于一个总的发明构思的两项以上的发明或者实用新型，应当在技术上相互关联，包含一个或者多个相同或者相应的特定技术特征，其中特定技术特征是指每一项发明或者实用新型作为整体，对现有技术作出贡献的技术特征。"},{"i":40,"n":"第四十条","txt":"依照专利法第三十一条第二款规定，将同一产品的多项相似外观设计作为一件申请提出的，对该产品的其他设计应当与简要说明中指定的基本设计相似。一件外观设计专利申请中的相似外观设计不得超过10项。"},{"i":41,"n":"第四十一条","txt":"申请人撤回专利申请的，应当向国务院专利行政部门提出声明，写明发明创造的名称、申请号和申请日。"},{"i":42,"n":"第四十二条","txt":"在初步审查、实质审查、复审和无效宣告程序中，实施审查和审理的人员有下列情形之一的，应当自行回避，当事人或者其他利害关系人可以要求其回避："},{"i":43,"n":"第四十三条","txt":"国务院专利行政部门收到发明或者实用新型专利申请的请求书、说明书（实用新型必须包括附图）和权利要求书，或者外观设计专利申请的请求书、外观设计的图片或者照片和简要说明后，应当明确申请日、给予申请号，并通知申请人。"},{"i":44,"n":"第四十四条","txt":"专利申请文件有下列情形之一的，国务院专利行政部门不予受理，并通知申请人："},{"i":45,"n":"第四十五条","txt":"发明或者实用新型专利申请缺少或者错误提交权利要求书、说明书或者权利要求书、说明书的部分内容，但申请人在递交日要求了优先权的，可以自递交日起2个月内或者在国务院专利行政部门指定的期限内以援引在先申请文件的方式补交。补交的文件符合有关规定的，以首次提交文件的递交日为申请日。"},{"i":46,"n":"第四十六条","txt":"说明书中写有对附图的说明但无附图或者缺少部分附图的，申请人应当在国务院专利行政部门指定的期限内补交附图或者声明取消对附图的说明。申请人补交附图的，以向国务院专利行政部门提交或者邮寄附图之日为申请日；取消对附图的说明的，保留原申请日。"},{"i":47,"n":"第四十七条","txt":"两个以上的申请人同日（指申请日；有优先权的，指优先权日）分别就同样的发明创造申请专利的，应当在收到国务院专利行政部门的通知后自行协商确定申请人。"},{"i":48,"n":"第四十八条","txt":"一件专利申请包括两项以上发明、实用新型或者外观设计的，申请人可以在本细则第六十条第一款规定的期限届满前，向国务院专利行政部门提出分案申请；但是，专利申请已经被驳回、撤回或者视为撤回的，不能提出分案申请。"},{"i":49,"n":"第四十九条","txt":"依照本细则第四十八条规定提出的分案申请，可以保留原申请日，享有优先权的，可以保留优先权日，但是不得超出原申请记载的范围。"},{"i":50,"n":"第五十条","txt":"专利法第三十四条和第四十条所称初步审查，是指审查专利申请是否具备专利法第二十六条或者第二十七条规定的文件和其他必要的文件，这些文件是否符合规定的格式，并审查下列各项："},{"i":51,"n":"第五十一条","txt":"除专利申请文件外，申请人向国务院专利行政部门提交的与专利申请有关的其他文件有下列情形之一的，视为未提交："},{"i":52,"n":"第五十二条","txt":"申请人请求早日公布其发明专利申请的，应当向国务院专利行政部门声明。国务院专利行政部门对该申请进行初步审查后，除予以驳回的外，应当立即将申请予以公布。"},{"i":53,"n":"第五十三条","txt":"申请人写明使用外观设计的产品及其所属类别的，应当使用国务院专利行政部门公布的外观设计产品分类表。未写明使用外观设计的产品所属类别或者所写的类别不确切的，国务院专利行政部门可以予以补充或者修改。"},{"i":54,"n":"第五十四条","txt":"自发明专利申请公布之日起至公告授予专利权之日止，任何人均可以对不符合专利法规定的专利申请向国务院专利行政部门提出意见，并说明理由。"},{"i":55,"n":"第五十五条","txt":"发明专利申请人因有正当理由无法提交专利法第三十六条规定的检索资料或者审查结果资料的，应当向国务院专利行政部门声明，并在得到有关资料后补交。"},{"i":56,"n":"第五十六条","txt":"国务院专利行政部门依照专利法第三十五条第二款的规定对专利申请自行进行审查时，应当通知申请人。"},{"i":57,"n":"第五十七条","txt":"发明专利申请人在提出实质审查请求时以及在收到国务院专利行政部门发出的发明专利申请进入实质审查阶段通知书之日起的3个月内，可以对发明专利申请主动提出修改。"},{"i":58,"n":"第五十八条","txt":"发明或者实用新型专利申请的说明书或者权利要求书的修改部分，除个别文字修改或者增删外，应当按照规定格式提交替换页。外观设计专利申请的图片或者照片的修改，应当按照规定提交替换页。"},{"i":59,"n":"第五十九条","txt":"依照专利法第三十八条的规定，发明专利申请经实质审查应当予以驳回的情形是指："},{"i":60,"n":"第六十条","txt":"国务院专利行政部门发出授予专利权的通知后，申请人应当自收到通知之日起2个月内办理登记手续。申请人按期办理登记手续的，国务院专利行政部门应当授予专利权，颁发专利证书，并予以公告。"},{"i":61,"n":"第六十一条","txt":"保密专利申请经审查没有发现驳回理由的，国务院专利行政部门应当作出授予保密专利权的决定，颁发保密专利证书，登记保密专利权的有关事项。"},{"i":62,"n":"第六十二条","txt":"授予实用新型或者外观设计专利权的决定公告后，专利法第六十六条规定的专利权人、利害关系人、被控侵权人可以请求国务院专利行政部门作出专利权评价报告。申请人可以在办理专利权登记手续时请求国务院专利行政部门作出专利权评价报告。"},{"i":63,"n":"第六十三条","txt":"国务院专利行政部门应当自收到专利权评价报告请求书后2个月内作出专利权评价报告，但申请人在办理专利权登记手续时请求作出专利权评价报告的，国务院专利行政部门应当自公告授予专利权之日起2个月内作出专利权评价报告。"},{"i":64,"n":"第六十四条","txt":"国务院专利行政部门对专利公告、专利单行本中出现的错误，一经发现，应当及时更正，并对所作更正予以公告。"},{"i":65,"n":"第六十五条","txt":"依照专利法第四十一条的规定向国务院专利行政部门请求复审的，应当提交复审请求书，说明理由，必要时还应当附具有关证据。"},{"i":66,"n":"第六十六条","txt":"请求人在提出复审请求或者在对国务院专利行政部门的复审通知书作出答复时，可以修改专利申请文件；但是，修改应当仅限于消除驳回决定或者复审通知书指出的缺陷。"},{"i":67,"n":"第六十七条","txt":"国务院专利行政部门进行复审后，认为复审请求不符合专利法和本细则有关规定或者专利申请存在其他明显违反专利法和本细则有关规定情形的，应当通知复审请求人，要求其在指定期限内陈述意见。期满未答复的，该复审请求视为撤回；经陈述意见或者进行修改后，国务院专利行政部门认为仍不符合专利法和本细则有关规定的，应当作出驳回复审请求的复审决定。"},{"i":68,"n":"第六十八条","txt":"复审请求人在国务院专利行政部门作出决定前，可以撤回其复审请求。"},{"i":69,"n":"第六十九条","txt":"依照专利法第四十五条的规定，请求宣告专利权无效或者部分无效的，应当向国务院专利行政部门提交专利权无效宣告请求书和必要的证据一式两份。无效宣告请求书应当结合提交的所有证据，具体说明无效宣告请求的理由，并指明每项理由所依据的证据。"},{"i":70,"n":"第七十条","txt":"专利权无效宣告请求不符合专利法第十八条第一款或者本细则第六十九条规定的，国务院专利行政部门不予受理。"},{"i":71,"n":"第七十一条","txt":"在国务院专利行政部门受理无效宣告请求后，请求人可以在提出无效宣告请求之日起1个月内增加理由或者补充证据。逾期增加理由或者补充证据的，国务院专利行政部门可以不予考虑。"},{"i":72,"n":"第七十二条","txt":"国务院专利行政部门应当将专利权无效宣告请求书和有关文件的副本送交专利权人，要求其在指定的期限内陈述意见。"},{"i":73,"n":"第七十三条","txt":"在无效宣告请求的审查过程中，发明或者实用新型专利的专利权人可以修改其权利要求书，但是不得扩大原专利的保护范围。国务院专利行政部门在修改后的权利要求基础上作出维持专利权有效或者宣告专利权部分无效的决定的，应当公告修改后的权利要求。"},{"i":74,"n":"第七十四条","txt":"国务院专利行政部门根据当事人的请求或者案情需要，可以决定对无效宣告请求进行口头审理。"},{"i":75,"n":"第七十五条","txt":"在无效宣告请求审查程序中，国务院专利行政部门指定的期限不得延长。"},{"i":76,"n":"第七十六条","txt":"国务院专利行政部门对无效宣告的请求作出决定前，无效宣告请求人可以撤回其请求。"},{"i":77,"n":"第七十七条","txt":"依照专利法第四十二条第二款的规定请求给予专利权期限补偿的，专利权人应当自公告授予专利权之日起3个月内向国务院专利行政部门提出。"},{"i":78,"n":"第七十八条","txt":"依照专利法第四十二条第二款的规定给予专利权期限补偿的，补偿期限按照发明专利在授权过程中不合理延迟的实际天数计算。"},{"i":79,"n":"第七十九条","txt":"专利法第四十二条第二款规定的由申请人引起的不合理延迟包括以下情形："},{"i":80,"n":"第八十条","txt":"专利法第四十二条第三款所称新药相关发明专利是指符合规定的新药产品专利、制备方法专利、医药用途专利。"},{"i":81,"n":"第八十一条","txt":"依照专利法第四十二条第三款的规定请求给予新药相关发明专利权期限补偿的，应当符合下列要求，自该新药在中国获得上市许可之日起3个月内向国务院专利行政部门提出："},{"i":82,"n":"第八十二条","txt":"依照专利法第四十二条第三款的规定给予专利权期限补偿的，补偿期限按照该专利申请日至该新药在中国获得上市许可之日的间隔天数减去5年，在符合专利法第四十二条第三款规定的基础上确定。"},{"i":83,"n":"第八十三条","txt":"新药相关发明专利在专利权期限补偿期间，该专利的保护范围限于该新药及其经批准的适应症相关技术方案；在保护范围内，专利权人享有的权利和承担的义务与专利权期限补偿前相同。"},{"i":84,"n":"第八十四条","txt":"国务院专利行政部门对依照专利法第四十二条第二款、第三款的规定提出的专利权期限补偿请求进行审查后，认为符合补偿条件的，作出给予期限补偿的决定，并予以登记和公告；不符合补偿条件的，作出不予期限补偿的决定，并通知提出请求的专利权人。"},{"i":85,"n":"第八十五条","txt":"专利权人自愿声明对其专利实行开放许可的，应当在公告授予专利权后提出。"},{"i":86,"n":"第八十六条","txt":"专利权有下列情形之一的，专利权人不得对其实行开放许可："},{"i":87,"n":"第八十七条","txt":"通过开放许可达成专利实施许可的，专利权人或者被许可人应当凭能够证明达成许可的书面文件向国务院专利行政部门备案。"},{"i":88,"n":"第八十八条","txt":"专利权人不得通过提供虚假材料、隐瞒事实等手段，作出开放许可声明或者在开放许可实施期间获得专利年费减免。"},{"i":89,"n":"第八十九条","txt":"专利法第五十三条第（一）项所称未充分实施其专利，是指专利权人及其被许可人实施其专利的方式或者规模不能满足国内对专利产品或者专利方法的需求。"},{"i":90,"n":"第九十条","txt":"请求给予强制许可的，应当向国务院专利行政部门提交强制许可请求书，说明理由并附具有关证明文件。"},{"i":91,"n":"第九十一条","txt":"依照专利法第六十二条的规定，请求国务院专利行政部门裁决使用费数额的，当事人应当提出裁决请求书，并附具双方不能达成协议的证明文件。国务院专利行政部门应当自收到请求书之日起3个月内作出裁决，并通知当事人。"},{"i":92,"n":"第九十二条","txt":"被授予专利权的单位可以与发明人、设计人约定或者在其依法制定的规章制度中规定专利法第十五条规定的奖励、报酬的方式和数额。鼓励被授予专利权的单位实行产权激励，采取股权、期权、分红等方式，使发明人或者设计人合理分享创新收益。"},{"i":93,"n":"第九十三条","txt":"被授予专利权的单位未与发明人、设计人约定也未在其依法制定的规章制度中规定专利法第十五条规定的奖励的方式和数额的，应当自公告授予专利权之日起3个月内发给发明人或者设计人奖金。一项发明专利的奖金最低不少于4000元；一项实用新型专利或者外观设计专利的奖金最低不少于1500元。"},{"i":94,"n":"第九十四条","txt":"被授予专利权的单位未与发明人、设计人约定也未在其依法制定的规章制度中规定专利法第十五条规定的报酬的方式和数额的，应当依照《中华人民共和国促进科技成果转化法》的规定，给予发明人或者设计人合理的报酬。"},{"i":95,"n":"第九十五条","txt":"省、自治区、直辖市人民政府管理专利工作的部门以及专利管理工作量大又有实际处理能力的地级市、自治州、盟、地区和直辖市的区人民政府管理专利工作的部门，可以处理和调解专利纠纷。"},{"i":96,"n":"第九十六条","txt":"有下列情形之一的，属于专利法第七十条所称的在全国有重大影响的专利侵权纠纷："},{"i":97,"n":"第九十七条","txt":"当事人请求处理专利侵权纠纷或者调解专利纠纷的，由被请求人所在地或者侵权行为地的管理专利工作的部门管辖。"},{"i":98,"n":"第九十八条","txt":"在处理专利侵权纠纷过程中，被请求人提出无效宣告请求并被国务院专利行政部门受理的，可以请求管理专利工作的部门中止处理。"},{"i":99,"n":"第九十九条","txt":"专利权人依照专利法第十六条的规定，在其专利产品或者该产品的包装上标明专利标识的，应当按照国务院专利行政部门规定的方式予以标明。"},{"i":100,"n":"第一百条","txt":"申请人或者专利权人违反本细则第十一条、第八十八条规定的，由县级以上负责专利执法的部门予以警告，可以处10万元以下的罚款。"},{"i":101,"n":"第一百零一条","txt":"下列行为属于专利法第六十八条规定的假冒专利的行为："},{"i":102,"n":"第一百零二条","txt":"除专利法第六十五条规定的外，管理专利工作的部门应当事人请求，可以对下列专利纠纷进行调解："},{"i":103,"n":"第一百零三条","txt":"当事人因专利申请权或者专利权的归属发生纠纷，已请求管理专利工作的部门调解或者向人民法院起诉的，可以请求国务院专利行政部门中止有关程序。"},{"i":104,"n":"第一百零四条","txt":"人民法院在审理民事案件中裁定对专利申请权或者专利权采取保全措施的，国务院专利行政部门应当在收到写明申请号或者专利号的裁定书和协助执行通知书之日中止被保全的专利申请权或者专利权的有关程序。保全期限届满，人民法院没有裁定继续采取保全措施的，国务院专利行政部门自行恢复有关程序。"},{"i":105,"n":"第一百零五条","txt":"国务院专利行政部门根据本细则第一百零三条和第一百零四条规定中止有关程序，是指暂停专利申请的初步审查、实质审查、复审程序，授予专利权程序和专利权无效宣告程序；暂停办理放弃、变更、转移专利权或者专利申请权手续，专利权质押手续以及专利权期限届满前的终止手续等。"},{"i":106,"n":"第一百零六条","txt":"国务院专利行政部门设置专利登记簿，登记下列与专利申请和专利权有关的事项："},{"i":107,"n":"第一百零七条","txt":"国务院专利行政部门定期出版专利公报，公布或者公告下列内容："},{"i":108,"n":"第一百零八条","txt":"国务院专利行政部门应当提供专利公报、发明专利申请单行本以及发明专利、实用新型专利、外观设计专利单行本，供公众免费查阅。"},{"i":109,"n":"第一百零九条","txt":"国务院专利行政部门负责按照互惠原则与其他国家、地区的专利机关或者区域性专利组织交换专利文献。"},{"i":110,"n":"第一百一十条","txt":"向国务院专利行政部门申请专利和办理其他手续时，应当缴纳下列费用："},{"i":111,"n":"第一百一十一条","txt":"专利法和本细则规定的各种费用，应当严格按照规定缴纳。"},{"i":112,"n":"第一百一十二条","txt":"申请人应当自申请日起2个月内或者在收到受理通知书之日起15日内缴纳申请费、公布印刷费和必要的申请附加费；期满未缴纳或者未缴足的，其申请视为撤回。"},{"i":113,"n":"第一百一十三条","txt":"当事人请求实质审查或者复审的，应当在专利法及本细则规定的相关期限内缴纳费用；期满未缴纳或者未缴足的，视为未提出请求。"},{"i":114,"n":"第一百一十四条","txt":"申请人办理登记手续时，应当缴纳授予专利权当年的年费；期满未缴纳或者未缴足的，视为未办理登记手续。"},{"i":115,"n":"第一百一十五条","txt":"授予专利权当年以后的年费应当在上一年度期满前缴纳。专利权人未缴纳或者未缴足的，国务院专利行政部门应当通知专利权人自应当缴纳年费期满之日起6个月内补缴，同时缴纳滞纳金；滞纳金的金额按照每超过规定的缴费时间1个月，加收当年全额年费的5%计算；期满未缴纳的，专利权自应当缴纳年费期满之日起终止。"},{"i":116,"n":"第一百一十六条","txt":"恢复权利请求费应当在本细则规定的相关期限内缴纳；期满未缴纳或者未缴足的，视为未提出请求。"},{"i":117,"n":"第一百一十七条","txt":"申请人或者专利权人缴纳本细则规定的各种费用有困难的，可以按照规定向国务院专利行政部门提出减缴的请求。减缴的办法由国务院财政部门会同国务院发展改革部门、国务院专利行政部门规定。"},{"i":118,"n":"第一百一十八条","txt":"国务院专利行政部门根据专利法第十九条规定，受理按照专利合作条约提出的专利国际申请。"},{"i":119,"n":"第一百一十九条","txt":"按照专利合作条约已确定国际申请日并指定中国的国际申请，视为向国务院专利行政部门提出的专利申请，该国际申请日视为专利法第二十八条所称的申请日。"},{"i":120,"n":"第一百二十条","txt":"国际申请的申请人应当在专利合作条约第二条所称的优先权日（本章简称优先权日）起30个月内，向国务院专利行政部门办理进入中国国家阶段的手续；申请人未在该期限内办理该手续的，在缴纳宽限费后，可以在自优先权日起32个月内办理进入中国国家阶段的手续。"},{"i":121,"n":"第一百二十一条","txt":"申请人依照本细则第一百二十条的规定办理进入中国国家阶段的手续的，应当符合下列要求："},{"i":122,"n":"第一百二十二条","txt":"国际申请有下列情形之一的，其在中国的效力终止："},{"i":123,"n":"第一百二十三条","txt":"国际申请在国际阶段作过修改，申请人要求以经修改的申请文件为基础进行审查的，应当自进入日起2个月内提交修改部分的中文译文。在该期间内未提交中文译文的，对申请人在国际阶段提出的修改，国务院专利行政部门不予考虑。"},{"i":124,"n":"第一百二十四条","txt":"国际申请涉及的发明创造有专利法第二十四条第（二）项或者第（三）项所列情形之一，在提出国际申请时作过声明的，申请人应当在进入中国国家阶段的书面声明中予以说明，并自进入日起2个月内提交本细则第三十三条第三款规定的有关证明文件；未予说明或者期满未提交证明文件的，其申请不适用专利法第二十四条的规定。"},{"i":125,"n":"第一百二十五条","txt":"申请人按照专利合作条约的规定，对生物材料样品的保藏已作出说明的，视为已经满足了本细则第二十七条第（三）项的要求。申请人应当在进入中国国家阶段声明中指明记载生物材料样品保藏事项的文件以及在该文件中的具体记载位置。"},{"i":126,"n":"第一百二十六条","txt":"国际申请涉及的发明创造依赖遗传资源完成的，申请人应当在国际申请进入中国国家阶段的书面声明中予以说明，并填写国务院专利行政部门制定的表格。"},{"i":127,"n":"第一百二十七条","txt":"申请人在国际阶段已要求一项或者多项优先权，在进入中国国家阶段时该优先权要求继续有效的，视为已经依照专利法第三十条的规定提出了书面声明。"},{"i":128,"n":"第一百二十八条","txt":"国际申请的申请日在优先权期限届满之后2个月内，在国际阶段受理局已经批准恢复优先权的，视为已经依照本细则第三十六条的规定提出了恢复优先权请求；在国际阶段申请人未请求恢复优先权，或者提出了恢复优先权请求但受理局未批准，申请人有正当理由的，可以自进入日起2个月内向国务院专利行政部门请求恢复优先权。"},{"i":129,"n":"第一百二十九条","txt":"在优先权日起30个月期满前要求国务院专利行政部门提前处理和审查国际申请的，申请人除应当办理进入中国国家阶段手续外，还应当依照专利合作条约第二十三条第二款规定提出请求。国际局尚未向国务院专利行政部门传送国际申请的，申请人应当提交经确认的国际申请副本。"},{"i":130,"n":"第一百三十条","txt":"要求获得实用新型专利权的国际申请，申请人可以自进入日起2个月内对专利申请文件主动提出修改。"},{"i":131,"n":"第一百三十一条","txt":"申请人发现提交的说明书、权利要求书或者附图中的文字的中文译文存在错误的，可以在下列规定期限内依照原始国际申请文本提出改正："},{"i":132,"n":"第一百三十二条","txt":"对要求获得发明专利权的国际申请，国务院专利行政部门经初步审查认为符合专利法和本细则有关规定的，应当在专利公报上予以公布；国际申请以中文以外的文字提出的，应当公布申请文件的中文译文。"},{"i":133,"n":"第一百三十三条","txt":"国际申请包含两项以上发明或者实用新型的，申请人可以自进入日起，依照本细则第四十八条第一款的规定提出分案申请。"},{"i":134,"n":"第一百三十四条","txt":"国际申请在国际阶段被有关国际单位拒绝给予国际申请日或者宣布视为撤回的，申请人在收到通知之日起2个月内，可以请求国际局将国际申请档案中任何文件的副本转交国务院专利行政部门，并在该期限内向国务院专利行政部门办理本细则第一百二十条规定的手续，国务院专利行政部门应当在接到国际局传送的文件后，对国际单位作出的决定是否正确进行复查。"},{"i":135,"n":"第一百三十五条","txt":"基于国际申请授予的专利权，由于译文错误，致使依照专利法第六十四条规定确定的保护范围超出国际申请的原文所表达的范围的，以依据原文限制后的保护范围为准；致使保护范围小于国际申请的原文所表达的范围的，以授权时的保护范围为准。"},{"i":136,"n":"第一百三十六条","txt":"国务院专利行政部门根据专利法第十九条第二款、第三款规定，处理按照工业品外观设计国际注册海牙协定（1999年文本）（以下简称海牙协定）提出的外观设计国际注册申请。"},{"i":137,"n":"第一百三十七条","txt":"按照海牙协定已确定国际注册日并指定中国的外观设计国际申请，视为向国务院专利行政部门提出的外观设计专利申请，该国际注册日视为专利法第二十八条所称的申请日。"},{"i":138,"n":"第一百三十八条","txt":"国际局公布外观设计国际申请后，国务院专利行政部门对外观设计国际申请进行审查，并将审查结果通知国际局。"},{"i":139,"n":"第一百三十九条","txt":"国际局公布的外观设计国际申请中包括一项或者多项优先权的，视为已经依照专利法第三十条的规定提出了书面声明。"},{"i":140,"n":"第一百四十条","txt":"外观设计国际申请涉及的外观设计有专利法第二十四条第（二）项或者第（三）项所列情形的，应当在提出外观设计国际申请时声明，并自外观设计国际申请公布之日起2个月内提交本细则第三十三条第三款规定的有关证明文件。"},{"i":141,"n":"第一百四十一条","txt":"一件外观设计国际申请包括两项以上外观设计的，申请人可以自外观设计国际申请公布之日起2个月内，向国务院专利行政部门提出分案申请，并缴纳费用。"},{"i":142,"n":"第一百四十二条","txt":"国际局公布的外观设计国际申请中包括含设计要点的说明书的，视为已经依照本细则第三十一条的规定提交了简要说明。"},{"i":143,"n":"第一百四十三条","txt":"外观设计国际申请经国务院专利行政部门审查后没有发现驳回理由的，由国务院专利行政部门作出给予保护的决定，通知国际局。"},{"i":144,"n":"第一百四十四条","txt":"已在国际局办理权利变更手续的，申请人应当向国务院专利行政部门提供有关证明材料。"},{"i":145,"n":"第一百四十五条","txt":"经国务院专利行政部门同意，任何人均可以查阅或者复制已经公布或者公告的专利申请的案卷和专利登记簿，并可以请求国务院专利行政部门出具专利登记簿副本。"},{"i":146,"n":"第一百四十六条","txt":"向国务院专利行政部门提交申请文件或者办理各种手续，应当由申请人、专利权人、其他利害关系人或者其代表人签字或者盖章；委托专利代理机构的，由专利代理机构盖章。"},{"i":147,"n":"第一百四十七条","txt":"向国务院专利行政部门邮寄有关申请或者专利权的文件，应当使用挂号信函，不得使用包裹。"},{"i":148,"n":"第一百四十八条","txt":"国务院专利行政部门根据专利法和本细则制定专利审查指南。"},{"i":149,"n":"第一百四十九条","txt":"本细则自2001年7月1日起施行。1992年12月12日国务院批准修订、1992年12月21日中国专利局发布的《中华人民共和国专利法实施细则》同时废止。"}],"gerensuodeshuifashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国个人所得税法》（以下简称个人所得税法），制定本条例。"},{"i":2,"n":"第二条","txt":"个人所得税法所称在中国境内有住所，是指因户籍、家庭、经济利益关系而在中国境内习惯性居住；所称从中国境内和境外取得的所得，分别是指来源于中国境内的所得和来源于中国境外的所得。"},{"i":3,"n":"第三条","txt":"除国务院财政、税务主管部门另有规定外，下列所得，不论支付地点是否在中国境内，均为来源于中国境内的所得："},{"i":4,"n":"第四条","txt":"在中国境内无住所的个人，在中国境内居住累计满183天的年度连续不满六年的，经向主管税务机关备案，其来源于中国境外且由境外单位或者个人支付的所得，免予缴纳个人所得税；在中国境内居住累计满183天的任一年度中有一次离境超过30天的，其在中国境内居住累计满183天的年度的连续年限重新起算。"},{"i":5,"n":"第五条","txt":"在中国境内无住所的个人，在一个纳税年度内在中国境内居住累计不超过90天的，其来源于中国境内的所得，由境外雇主支付并且不由该雇主在中国境内的机构、场所负担的部分，免予缴纳个人所得税。"},{"i":6,"n":"第六条","txt":"个人所得税法规定的各项个人所得的范围："},{"i":7,"n":"第七条","txt":"对股票转让所得征收个人所得税的办法，由国务院另行规定，并报全国人民代表大会常务委员会备案。"},{"i":8,"n":"第八条","txt":"个人所得的形式，包括现金、实物、有价证券和其他形式的经济利益；所得为实物的，应当按照取得的凭证上所注明的价格计算应纳税所得额，无凭证的实物或者凭证上所注明的价格明显偏低的，参照市场价格核定应纳税所得额；所得为有价证券的，根据票面价格和市场价格核定应纳税所得额；所得为其他形式的经济利益的，参照市场价格核定应纳税所得额。"},{"i":9,"n":"第九条","txt":"个人所得税法第四条第一款第二项所称国债利息，是指个人持有中华人民共和国财政部发行的债券而取得的利息；所称国家发行的金融债券利息，是指个人持有经国务院批准发行的金融债券而取得的利息。"},{"i":10,"n":"第十条","txt":"个人所得税法第四条第一款第三项所称按照国家统一规定发给的补贴、津贴，是指按照国务院规定发给的政府特殊津贴、院士津贴，以及国务院规定免予缴纳个人所得税的其他补贴、津贴。"},{"i":11,"n":"第十一条","txt":"个人所得税法第四条第一款第四项所称福利费，是指根据国家有关规定，从企业、事业单位、国家机关、社会组织提留的福利费或者工会经费中支付给个人的生活补助费；所称救济金，是指各级人民政府民政部门支付给个人的生活困难补助费。"},{"i":12,"n":"第十二条","txt":"个人所得税法第四条第一款第八项所称依照有关法律规定应予免税的各国驻华使馆、领事馆的外交代表、领事官员和其他人员的所得，是指依照《中华人民共和国外交特权与豁免条例》和《中华人民共和国领事特权与豁免条例》规定免税的所得。"},{"i":13,"n":"第十三条","txt":"个人所得税法第六条第一款第一项所称依法确定的其他扣除，包括个人缴付符合国家规定的企业年金、职业年金，个人购买符合国家规定的商业健康保险、税收递延型商业养老保险的支出，以及国务院规定可以扣除的其他项目。"},{"i":14,"n":"第十四条","txt":"个人所得税法第六条第一款第二项、第四项、第六项所称每次，分别按照下列方法确定："},{"i":15,"n":"第十五条","txt":"个人所得税法第六条第一款第三项所称成本、费用，是指生产、经营活动中发生的各项直接支出和分配计入成本的间接费用以及销售费用、管理费用、财务费用；所称损失，是指生产、经营活动中发生的固定资产和存货的盘亏、毁损、报废损失，转让财产损失，坏账损失，自然灾害等不可抗力因素造成的损失以及其他损失。"},{"i":16,"n":"第十六条","txt":"个人所得税法第六条第一款第五项规定的财产原值，按照下列方法确定："},{"i":17,"n":"第十七条","txt":"财产转让所得，按照一次转让财产的收入额减除财产原值和合理费用后的余额计算纳税。"},{"i":18,"n":"第十八条","txt":"两个以上的个人共同取得同一项目收入的，应当对每个人取得的收入分别按照个人所得税法的规定计算纳税。"},{"i":19,"n":"第十九条","txt":"个人所得税法第六条第三款所称个人将其所得对教育、扶贫、济困等公益慈善事业进行捐赠，是指个人将其所得通过中国境内的公益性社会组织、国家机关向教育、扶贫、济困等公益慈善事业的捐赠；所称应纳税所得额，是指计算扣除捐赠额之前的应纳税所得额。"},{"i":20,"n":"第二十条","txt":"居民个人从中国境内和境外取得的综合所得、经营所得，应当分别合并计算应纳税额；从中国境内和境外取得的其他所得，应当分别单独计算应纳税额。"},{"i":21,"n":"第二十一条","txt":"个人所得税法第七条所称已在境外缴纳的个人所得税税额，是指居民个人来源于中国境外的所得，依照该所得来源国家（地区）的法律应当缴纳并且实际已经缴纳的所得税税额。"},{"i":22,"n":"第二十二条","txt":"居民个人申请抵免已在境外缴纳的个人所得税税额，应当提供境外税务机关出具的税款所属年度的有关纳税凭证。"},{"i":23,"n":"第二十三条","txt":"个人所得税法第八条第二款规定的利息，应当按照税款所属纳税申报期最后一日中国人民银行公布的与补税期间同期的人民币贷款基准利率计算，自税款纳税申报期满次日起至补缴税款期限届满之日止按日加收。纳税人在补缴税款期限届满前补缴税款的，利息加收至补缴税款之日。"},{"i":24,"n":"第二十四条","txt":"扣缴义务人向个人支付应税款项时，应当依照个人所得税法规定预扣或者代扣税款，按时缴库，并专项记载备查。"},{"i":25,"n":"第二十五条","txt":"取得综合所得需要办理汇算清缴的情形包括："},{"i":26,"n":"第二十六条","txt":"个人所得税法第十条第二款所称全员全额扣缴申报，是指扣缴义务人在代扣税款的次月十五日内，向主管税务机关报送其支付所得的所有个人的有关信息、支付所得数额、扣除事项和数额、扣缴税款的具体数额和总额以及其他相关涉税信息资料。"},{"i":27,"n":"第二十七条","txt":"纳税人办理纳税申报的地点以及其他有关事项的具体办法，由国务院税务主管部门制定。"},{"i":28,"n":"第二十八条","txt":"居民个人取得工资、薪金所得时，可以向扣缴义务人提供专项附加扣除有关信息，由扣缴义务人扣缴税款时减除专项附加扣除。纳税人同时从两处以上取得工资、薪金所得，并由扣缴义务人减除专项附加扣除的，对同一专项附加扣除项目，在一个纳税年度内只能选择从一处取得的所得中减除。"},{"i":29,"n":"第二十九条","txt":"纳税人可以委托扣缴义务人或者其他单位和个人办理汇算清缴。"},{"i":30,"n":"第三十条","txt":"扣缴义务人应当按照纳税人提供的信息计算办理扣缴申报，不得擅自更改纳税人提供的信息。"},{"i":31,"n":"第三十一条","txt":"纳税人申请退税时提供的汇算清缴信息有错误的，税务机关应当告知其更正；纳税人更正的，税务机关应当及时办理退税。"},{"i":32,"n":"第三十二条","txt":"所得为人民币以外货币的，按照办理纳税申报或者扣缴申报的上一月最后一日人民币汇率中间价，折合成人民币计算应纳税所得额。年度终了后办理汇算清缴的，对已经按月、按季或者按次预缴税款的人民币以外货币所得，不再重新折算；对应当补缴税款的所得部分，按照上一纳税年度最后一日人民币汇率中间价，折合成人民币计算应纳税所得额。"},{"i":33,"n":"第三十三条","txt":"税务机关按照个人所得税法第十七条的规定付给扣缴义务人手续费，应当填开退还书；扣缴义务人凭退还书，按照国库管理有关规定办理退库手续。"},{"i":34,"n":"第三十四条","txt":"个人所得税纳税申报表、扣缴个人所得税报告表和个人所得税完税凭证式样，由国务院税务主管部门统一制定。"},{"i":35,"n":"第三十五条","txt":"军队人员个人所得税征收事宜，按照有关规定执行。"},{"i":36,"n":"第三十六条","txt":"本条例自2019年1月1日起施行。"}],"qiyesuodeshuifashishitiaoli-2":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国企业所得税法》（以下简称企业所得税法）的规定，制定本条例。"},{"i":2,"n":"第二条","txt":"企业所得税法第一条所称个人独资企业、合伙企业，是指依照中国法律、行政法规成立的个人独资企业、合伙企业。"},{"i":3,"n":"第三条","txt":"企业所得税法第二条所称依法在中国境内成立的企业，包括依照中国法律、行政法规在中国境内成立的企业、事业单位、社会团体以及其他取得收入的组织。"},{"i":4,"n":"第四条","txt":"企业所得税法第二条所称实际管理机构，是指对企业的生产经营、人员、账务、财产等实施实质性全面管理和控制的机构。"},{"i":5,"n":"第五条","txt":"企业所得税法第二条第三款所称机构、场所，是指在中国境内从事生产经营活动的机构、场所，包括："},{"i":6,"n":"第六条","txt":"企业所得税法第三条所称所得，包括销售货物所得、提供劳务所得、转让财产所得、股息红利等权益性投资所得、利息所得、租金所得、特许权使用费所得、接受捐赠所得和其他所得。"},{"i":7,"n":"第七条","txt":"企业所得税法第三条所称来源于中国境内、境外的所得，按照以下原则确定："},{"i":8,"n":"第八条","txt":"企业所得税法第三条所称实际联系，是指非居民企业在中国境内设立的机构、场所拥有据以取得所得的股权、债权，以及拥有、管理、控制据以取得所得的财产等。"},{"i":9,"n":"第九条","txt":"企业应纳税所得额的计算，以权责发生制为原则，属于当期的收入和费用，不论款项是否收付，均作为当期的收入和费用；不属于当期的收入和费用，即使款项已经在当期收付，均不作为当期的收入和费用。本条例和国务院财政、税务主管部门另有规定的除外。"},{"i":10,"n":"第十条","txt":"企业所得税法第五条所称亏损，是指企业依照企业所得税法和本条例的规定将每一纳税年度的收入总额减除不征税收入、免税收入和各项扣除后小于零的数额。"},{"i":11,"n":"第十一条","txt":"企业所得税法第五十五条所称清算所得，是指企业的全部资产可变现价值或者交易价格减除资产净值、清算费用以及相关税费等后的余额。"},{"i":12,"n":"第十二条","txt":"企业所得税法第六条所称企业取得收入的货币形式，包括现金、存款、应收账款、应收票据、准备持有至到期的债券投资以及债务的豁免等。"},{"i":13,"n":"第十三条","txt":"企业所得税法第六条所称企业以非货币形式取得的收入，应当按照公允价值确定收入额。"},{"i":14,"n":"第十四条","txt":"企业所得税法第六条第（一）项所称销售货物收入，是指企业销售商品、产品、原材料、包装物、低值易耗品以及其他存货取得的收入。"},{"i":15,"n":"第十五条","txt":"企业所得税法第六条第（二）项所称提供劳务收入，是指企业从事建筑安装、修理修配、交通运输、仓储租赁、金融保险、邮电通信、咨询经纪、文化体育、科学研究、技术服务、教育培训、餐饮住宿、中介代理、卫生保健、社区服务、旅游、娱乐、加工以及其他劳务服务活动取得的收入。"},{"i":16,"n":"第十六条","txt":"企业所得税法第六条第（三）项所称转让财产收入，是指企业转让固定资产、生物资产、无形资产、股权、债权等财产取得的收入。"},{"i":17,"n":"第十七条","txt":"企业所得税法第六条第（四）项所称股息、红利等权益性投资收益，是指企业因权益性投资从被投资方取得的收入。"},{"i":18,"n":"第十八条","txt":"企业所得税法第六条第（五）项所称利息收入，是指企业将资金提供他人使用但不构成权益性投资，或者因他人占用本企业资金取得的收入，包括存款利息、贷款利息、债券利息、欠款利息等收入。"},{"i":19,"n":"第十九条","txt":"企业所得税法第六条第（六）项所称租金收入，是指企业提供固定资产、包装物或者其他有形资产的使用权取得的收入。"},{"i":20,"n":"第二十条","txt":"企业所得税法第六条第（七）项所称特许权使用费收入，是指企业提供专利权、非专利技术、商标权、著作权以及其他特许权的使用权取得的收入。"},{"i":21,"n":"第二十一条","txt":"企业所得税法第六条第（八）项所称接受捐赠收入，是指企业接受的来自其他企业、组织或者个人无偿给予的货币性资产、非货币性资产。"},{"i":22,"n":"第二十二条","txt":"企业所得税法第六条第（九）项所称其他收入，是指企业取得的除企业所得税法第六条第（一）项至第（八）项规定的收入外的其他收入，包括企业资产溢余收入、逾期未退包装物押金收入、确实无法偿付的应付款项、已作坏账损失处理后又收回的应收款项、债务重组收入、补贴收入、违约金收入、汇兑收益等。"},{"i":23,"n":"第二十三条","txt":"企业的下列生产经营业务可以分期确认收入的实现："},{"i":24,"n":"第二十四条","txt":"采取产品分成方式取得收入的，按照企业分得产品的日期确认收入的实现，其收入额按照产品的公允价值确定。"},{"i":25,"n":"第二十五条","txt":"企业发生非货币性资产交换，以及将货物、财产、劳务用于捐赠、偿债、赞助、集资、广告、样品、职工福利或者利润分配等用途的，应当视同销售货物、转让财产或者提供劳务，但国务院财政、税务主管部门另有规定的除外。"},{"i":26,"n":"第二十六条","txt":"企业所得税法第七条第（一）项所称财政拨款，是指各级人民政府对纳入预算管理的事业单位、社会团体等组织拨付的财政资金，但国务院和国务院财政、税务主管部门另有规定的除外。"},{"i":27,"n":"第二十七条","txt":"企业所得税法第八条所称有关的支出，是指与取得收入直接相关的支出。"},{"i":28,"n":"第二十八条","txt":"企业发生的支出应当区分收益性支出和资本性支出。收益性支出在发生当期直接扣除；资本性支出应当分期扣除或者计入有关资产成本，不得在发生当期直接扣除。"},{"i":29,"n":"第二十九条","txt":"企业所得税法第八条所称成本，是指企业在生产经营活动中发生的销售成本、销货成本、业务支出以及其他耗费。"},{"i":30,"n":"第三十条","txt":"企业所得税法第八条所称费用，是指企业在生产经营活动中发生的销售费用、管理费用和财务费用，已经计入成本的有关费用除外。"},{"i":31,"n":"第三十一条","txt":"企业所得税法第八条所称税金，是指企业发生的除企业所得税和允许抵扣的增值税以外的各项税金及其附加。"},{"i":32,"n":"第三十二条","txt":"企业所得税法第八条所称损失，是指企业在生产经营活动中发生的固定资产和存货的盘亏、毁损、报废损失，转让财产损失，呆账损失，坏账损失，自然灾害等不可抗力因素造成的损失以及其他损失。"},{"i":33,"n":"第三十三条","txt":"企业所得税法第八条所称其他支出，是指除成本、费用、税金、损失外，企业在生产经营活动中发生的与生产经营活动有关的、合理的支出。"},{"i":34,"n":"第三十四条","txt":"企业发生的合理的工资薪金支出，准予扣除。"},{"i":35,"n":"第三十五条","txt":"企业依照国务院有关主管部门或者省级人民政府规定的范围和标准为职工缴纳的基本养老保险费、基本医疗保险费、失业保险费、工伤保险费、生育保险费等基本社会保险费和住房公积金，准予扣除。"},{"i":36,"n":"第三十六条","txt":"除企业依照国家有关规定为特殊工种职工支付的人身安全保险费和国务院财政、税务主管部门规定可以扣除的其他商业保险费外，企业为投资者或者职工支付的商业保险费，不得扣除。"},{"i":37,"n":"第三十七条","txt":"企业在生产经营活动中发生的合理的不需要资本化的借款费用，准予扣除。"},{"i":38,"n":"第三十八条","txt":"企业在生产经营活动中发生的下列利息支出，准予扣除："},{"i":39,"n":"第三十九条","txt":"企业在货币交易中，以及纳税年度终了时将人民币以外的货币性资产、负债按照期末即期人民币汇率中间价折算为人民币时产生的汇兑损失，除已经计入有关资产成本以及与向所有者进行利润分配相关的部分外，准予扣除。"},{"i":40,"n":"第四十条","txt":"企业发生的职工福利费支出，不超过工资薪金总额14%的部分，准予扣除。"},{"i":41,"n":"第四十一条","txt":"企业拨缴的工会经费，不超过工资薪金总额2%的部分，准予扣除。"},{"i":42,"n":"第四十二条","txt":"除国务院财政、税务主管部门另有规定外，企业发生的职工教育经费支出，不超过工资薪金总额2.5%的部分，准予扣除；超过部分，准予在以后纳税年度结转扣除。"},{"i":43,"n":"第四十三条","txt":"企业发生的与生产经营活动有关的业务招待费支出，按照发生额的60%扣除，但最高不得超过当年销售（营业）收入的5‰。"},{"i":44,"n":"第四十四条","txt":"企业发生的符合条件的广告费和业务宣传费支出，除国务院财政、税务主管部门另有规定外，不超过当年销售（营业）收入15%的部分，准予扣除；超过部分，准予在以后纳税年度结转扣除。"},{"i":45,"n":"第四十五条","txt":"企业依照法律、行政法规有关规定提取的用于环境保护、生态恢复等方面的专项资金，准予扣除。上述专项资金提取后改变用途的，不得扣除。"},{"i":46,"n":"第四十六条","txt":"企业参加财产保险，按照规定缴纳的保险费，准予扣除。"},{"i":47,"n":"第四十七条","txt":"企业根据生产经营活动的需要租入固定资产支付的租赁费，按照以下方法扣除："},{"i":48,"n":"第四十八条","txt":"企业发生的合理的劳动保护支出，准予扣除。"},{"i":49,"n":"第四十九条","txt":"企业之间支付的管理费、企业内营业机构之间支付的租金和特许权使用费，以及非银行企业内营业机构之间支付的利息，不得扣除。"},{"i":50,"n":"第五十条","txt":"非居民企业在中国境内设立的机构、场所，就其中国境外总机构发生的与该机构、场所生产经营有关的费用，能够提供总机构出具的费用汇集范围、定额、分配依据和方法等证明文件，并合理分摊的，准予扣除。"},{"i":51,"n":"第五十一条","txt":"企业所得税法第九条所称公益性捐赠，是指企业通过公益性社会组织或者县级以上人民政府及其部门，用于符合法律规定的慈善活动、公益事业的捐赠。"},{"i":52,"n":"第五十二条","txt":"本条例第五十一条所称公益性社会组织，是指同时符合下列条件的慈善组织以及其他社会组织："},{"i":53,"n":"第五十三条","txt":"企业当年发生以及以前年度结转的公益性捐赠支出，不超过年度利润总额12%的部分，准予扣除。"},{"i":54,"n":"第五十四条","txt":"企业所得税法第十条第（六）项所称赞助支出，是指企业发生的与生产经营活动无关的各种非广告性质支出。"},{"i":55,"n":"第五十五条","txt":"企业所得税法第十条第（七）项所称未经核定的准备金支出，是指不符合国务院财政、税务主管部门规定的各项资产减值准备、风险准备等准备金支出。"},{"i":56,"n":"第五十六条","txt":"企业的各项资产，包括固定资产、生物资产、无形资产、长期待摊费用、投资资产、存货等，以历史成本为计税基础。"},{"i":57,"n":"第五十七条","txt":"企业所得税法第十一条所称固定资产，是指企业为生产产品、提供劳务、出租或者经营管理而持有的、使用时间超过12个月的非货币性资产，包括房屋、建筑物、机器、机械、运输工具以及其他与生产经营活动有关的设备、器具、工具等。"},{"i":58,"n":"第五十八条","txt":"固定资产按照以下方法确定计税基础："},{"i":59,"n":"第五十九条","txt":"固定资产按照直线法计算的折旧，准予扣除。"},{"i":60,"n":"第六十条","txt":"除国务院财政、税务主管部门另有规定外，固定资产计算折旧的最低年限如下："},{"i":61,"n":"第六十一条","txt":"从事开采石油、天然气等矿产资源的企业，在开始商业性生产前发生的费用和有关固定资产的折耗、折旧方法，由国务院财政、税务主管部门另行规定。"},{"i":62,"n":"第六十二条","txt":"生产性生物资产按照以下方法确定计税基础："},{"i":63,"n":"第六十三条","txt":"生产性生物资产按照直线法计算的折旧，准予扣除。"},{"i":64,"n":"第六十四条","txt":"生产性生物资产计算折旧的最低年限如下："},{"i":65,"n":"第六十五条","txt":"企业所得税法第十二条所称无形资产，是指企业为生产产品、提供劳务、出租或者经营管理而持有的、没有实物形态的非货币性长期资产，包括专利权、商标权、著作权、土地使用权、非专利技术、商誉等。"},{"i":66,"n":"第六十六条","txt":"无形资产按照以下方法确定计税基础："},{"i":67,"n":"第六十七条","txt":"无形资产按照直线法计算的摊销费用，准予扣除。"},{"i":68,"n":"第六十八条","txt":"企业所得税法第十三条第（一）项和第（二）项所称固定资产的改建支出，是指改变房屋或者建筑物结构、延长使用年限等发生的支出。"},{"i":69,"n":"第六十九条","txt":"企业所得税法第十三条第（三）项所称固定资产的大修理支出，是指同时符合下列条件的支出："},{"i":70,"n":"第七十条","txt":"企业所得税法第十三条第（四）项所称其他应当作为长期待摊费用的支出，自支出发生月份的次月起，分期摊销，摊销年限不得低于3年。"},{"i":71,"n":"第七十一条","txt":"企业所得税法第十四条所称投资资产，是指企业对外进行权益性投资和债权性投资形成的资产。"},{"i":72,"n":"第七十二条","txt":"企业所得税法第十五条所称存货，是指企业持有以备出售的产品或者商品、处在生产过程中的在产品、在生产或者提供劳务过程中耗用的材料和物料等。"},{"i":73,"n":"第七十三条","txt":"企业使用或者销售的存货的成本计算方法，可以在先进先出法、加权平均法、个别计价法中选用一种。计价方法一经选用，不得随意变更。"},{"i":74,"n":"第七十四条","txt":"企业所得税法第十六条所称资产的净值和第十九条所称财产净值，是指有关资产、财产的计税基础减除已经按照规定扣除的折旧、折耗、摊销、准备金等后的余额。"},{"i":75,"n":"第七十五条","txt":"除国务院财政、税务主管部门另有规定外，企业在重组过程中，应当在交易发生时确认有关资产的转让所得或者损失，相关资产应当按照交易价格重新确定计税基础。"},{"i":76,"n":"第七十六条","txt":"企业所得税法第二十二条规定的应纳税额的计算公式为："},{"i":77,"n":"第七十七条","txt":"企业所得税法第二十三条所称已在境外缴纳的所得税税额，是指企业来源于中国境外的所得依照中国境外税收法律以及相关规定应当缴纳并已经实际缴纳的企业所得税性质的税款。"},{"i":78,"n":"第七十八条","txt":"企业所得税法第二十三条所称抵免限额，是指企业来源于中国境外的所得，依照企业所得税法和本条例的规定计算的应纳税额。除国务院财政、税务主管部门另有规定外，该抵免限额应当分国（地区）不分项计算，计算公式如下："},{"i":79,"n":"第七十九条","txt":"企业所得税法第二十三条所称5个年度，是指从企业取得的来源于中国境外的所得，已经在中国境外缴纳的企业所得税性质的税额超过抵免限额的当年的次年起连续5个纳税年度。"},{"i":80,"n":"第八十条","txt":"企业所得税法第二十四条所称直接控制，是指居民企业直接持有外国企业20%以上股份。"},{"i":81,"n":"第八十一条","txt":"企业依照企业所得税法第二十三条、第二十四条的规定抵免企业所得税税额时，应当提供中国境外税务机关出具的税款所属年度的有关纳税凭证。"},{"i":82,"n":"第八十二条","txt":"企业所得税法第二十六条第（一）项所称国债利息收入，是指企业持有国务院财政部门发行的国债取得的利息收入。"},{"i":83,"n":"第八十三条","txt":"企业所得税法第二十六条第（二）项所称符合条件的居民企业之间的股息、红利等权益性投资收益，是指居民企业直接投资于其他居民企业取得的投资收益。企业所得税法第二十六条第（二）项和第（三）项所称股息、红利等权益性投资收益，不包括连续持有居民企业公开发行并上市流通的股票不足12个月取得的投资收益。"},{"i":84,"n":"第八十四条","txt":"企业所得税法第二十六条第（四）项所称符合条件的非营利组织，是指同时符合下列条件的组织："},{"i":85,"n":"第八十五条","txt":"企业所得税法第二十六条第（四）项所称符合条件的非营利组织的收入，不包括非营利组织从事营利性活动取得的收入，但国务院财政、税务主管部门另有规定的除外。"},{"i":86,"n":"第八十六条","txt":"企业所得税法第二十七条第（一）项规定的企业从事农、林、牧、渔业项目的所得，可以免征、减征企业所得税，是指："},{"i":87,"n":"第八十七条","txt":"企业所得税法第二十七条第（二）项所称国家重点扶持的公共基础设施项目，是指《公共基础设施项目企业所得税优惠目录》规定的港口码头、机场、铁路、公路、城市公共交通、电力、水利等项目。"},{"i":88,"n":"第八十八条","txt":"企业所得税法第二十七条第（三）项所称符合条件的环境保护、节能节水项目，包括公共污水处理、公共垃圾处理、沼气综合开发利用、节能减排技术改造、海水淡化等。项目的具体条件和范围由国务院财政、税务主管部门商国务院有关部门制订，报国务院批准后公布施行。"},{"i":89,"n":"第八十九条","txt":"依照本条例第八十七条和第八十八条规定享受减免税优惠的项目，在减免税期限内转让的，受让方自受让之日起，可以在剩余期限内享受规定的减免税优惠；减免税期限届满后转让的，受让方不得就该项目重复享受减免税优惠。"},{"i":90,"n":"第九十条","txt":"企业所得税法第二十七条第（四）项所称符合条件的技术转让所得免征、减征企业所得税，是指一个纳税年度内，居民企业技术转让所得不超过500万元的部分，免征企业所得税；超过500万元的部分，减半征收企业所得税。"},{"i":91,"n":"第九十一条","txt":"非居民企业取得企业所得税法第二十七条第（五）项规定的所得，减按10%的税率征收企业所得税。"},{"i":92,"n":"第九十二条","txt":"企业所得税法第二十八条第一款所称符合条件的小型微利企业，是指从事国家非限制和禁止行业，并符合下列条件的企业："},{"i":93,"n":"第九十三条","txt":"企业所得税法第二十八条第二款所称国家需要重点扶持的高新技术企业，是指拥有核心自主知识产权，并同时符合下列条件的企业："},{"i":94,"n":"第九十四条","txt":"企业所得税法第二十九条所称民族自治地方，是指依照《中华人民共和国民族区域自治法》的规定，实行民族区域自治的自治区、自治州、自治县。"},{"i":95,"n":"第九十五条","txt":"企业所得税法第三十条第（一）项所称研究开发费用的加计扣除，是指企业为开发新技术、新产品、新工艺发生的研究开发费用，未形成无形资产计入当期损益的，在按照规定据实扣除的基础上，按照研究开发费用的50%加计扣除；形成无形资产的，按照无形资产成本的150%摊销。"},{"i":96,"n":"第九十六条","txt":"企业所得税法第三十条第（二）项所称企业安置残疾人员所支付的工资的加计扣除，是指企业安置残疾人员的，在按照支付给残疾职工工资据实扣除的基础上，按照支付给残疾职工工资的100%加计扣除。残疾人员的范围适用《中华人民共和国残疾人保障法》的有关规定。"},{"i":97,"n":"第九十七条","txt":"企业所得税法第三十一条所称抵扣应纳税所得额，是指创业投资企业采取股权投资方式投资于未上市的中小高新技术企业2年以上的，可以按照其投资额的70%在股权持有满2年的当年抵扣该创业投资企业的应纳税所得额；当年不足抵扣的，可以在以后纳税年度结转抵扣。"},{"i":98,"n":"第九十八条","txt":"企业所得税法第三十二条所称可以采取缩短折旧年限或者采取加速折旧的方法的固定资产，包括："},{"i":99,"n":"第九十九条","txt":"企业所得税法第三十三条所称减计收入，是指企业以《资源综合利用企业所得税优惠目录》规定的资源作为主要原材料，生产国家非限制和禁止并符合国家和行业相关标准的产品取得的收入，减按90%计入收入总额。"},{"i":100,"n":"第一百条","txt":"企业所得税法第三十四条所称税额抵免，是指企业购置并实际使用《环境保护专用设备企业所得税优惠目录》、《节能节水专用设备企业所得税优惠目录》和《安全生产专用设备企业所得税优惠目录》规定的环境保护、节能节水、安全生产等专用设备的，该专用设备的投资额的10%可以从企业当年的应纳税额中抵免；当年不足抵免的，可以在以后5个纳税年度结转抵免。"},{"i":101,"n":"第一百零一条","txt":"本章第八十七条、第九十九条、第一百条规定的企业所得税优惠目录，由国务院财政、税务主管部门商国务院有关部门制订，报国务院批准后公布施行。"},{"i":102,"n":"第一百零二条","txt":"企业同时从事适用不同企业所得税待遇的项目的，其优惠项目应当单独计算所得，并合理分摊企业的期间费用；没有单独计算的，不得享受企业所得税优惠。"},{"i":103,"n":"第一百零三条","txt":"依照企业所得税法对非居民企业应当缴纳的企业所得税实行源泉扣缴的，应当依照企业所得税法第十九条的规定计算应纳税所得额。"},{"i":104,"n":"第一百零四条","txt":"企业所得税法第三十七条所称支付人，是指依照有关法律规定或者合同约定对非居民企业直接负有支付相关款项义务的单位或者个人。"},{"i":105,"n":"第一百零五条","txt":"企业所得税法第三十七条所称支付，包括现金支付、汇拨支付、转账支付和权益兑价支付等货币支付和非货币支付。"},{"i":106,"n":"第一百零六条","txt":"企业所得税法第三十八条规定的可以指定扣缴义务人的情形，包括："},{"i":107,"n":"第一百零七条","txt":"企业所得税法第三十九条所称所得发生地，是指依照本条例第七条规定的原则确定的所得发生地。在中国境内存在多处所得发生地的，由纳税人选择其中之一申报缴纳企业所得税。"},{"i":108,"n":"第一百零八条","txt":"企业所得税法第三十九条所称该纳税人在中国境内其他收入，是指该纳税人在中国境内取得的其他各种来源的收入。"},{"i":109,"n":"第一百零九条","txt":"企业所得税法第四十一条所称关联方，是指与企业有下列关联关系之一的企业、其他组织或者个人："},{"i":110,"n":"第一百一十条","txt":"企业所得税法第四十一条所称独立交易原则，是指没有关联关系的交易各方，按照公平成交价格和营业常规进行业务往来遵循的原则。"},{"i":111,"n":"第一百一十一条","txt":"企业所得税法第四十一条所称合理方法，包括："},{"i":112,"n":"第一百一十二条","txt":"企业可以依照企业所得税法第四十一条第二款的规定，按照独立交易原则与其关联方分摊共同发生的成本，达成成本分摊协议。"},{"i":113,"n":"第一百一十三条","txt":"企业所得税法第四十二条所称预约定价安排，是指企业就其未来年度关联交易的定价原则和计算方法，向税务机关提出申请，与税务机关按照独立交易原则协商、确认后达成的协议。"},{"i":114,"n":"第一百一十四条","txt":"企业所得税法第四十三条所称相关资料，包括："},{"i":115,"n":"第一百一十五条","txt":"税务机关依照企业所得税法第四十四条的规定核定企业的应纳税所得额时，可以采用下列方法："},{"i":116,"n":"第一百一十六条","txt":"企业所得税法第四十五条所称中国居民，是指根据《中华人民共和国个人所得税法》的规定，就其从中国境内、境外取得的所得在中国缴纳个人所得税的个人。"},{"i":117,"n":"第一百一十七条","txt":"企业所得税法第四十五条所称控制，包括："},{"i":118,"n":"第一百一十八条","txt":"企业所得税法第四十五条所称实际税负明显低于企业所得税法第四条第一款规定税率水平，是指低于企业所得税法第四条第一款规定税率的50%。"},{"i":119,"n":"第一百一十九条","txt":"企业所得税法第四十六条所称债权性投资，是指企业直接或者间接从关联方获得的，需要偿还本金和支付利息或者需要以其他具有支付利息性质的方式予以补偿的融资。"},{"i":120,"n":"第一百二十条","txt":"企业所得税法第四十七条所称不具有合理商业目的，是指以减少、免除或者推迟缴纳税款为主要目的。"},{"i":121,"n":"第一百二十一条","txt":"税务机关根据税收法律、行政法规的规定，对企业作出特别纳税调整的，应当对补征的税款，自税款所属纳税年度的次年6月1日起至补缴税款之日止的期间，按日加收利息。"},{"i":122,"n":"第一百二十二条","txt":"企业所得税法第四十八条所称利息，应当按照税款所属纳税年度中国人民银行公布的与补税期间同期的人民币贷款基准利率加5个百分点计算。"},{"i":123,"n":"第一百二十三条","txt":"企业与其关联方之间的业务往来，不符合独立交易原则，或者企业实施其他不具有合理商业目的安排的，税务机关有权在该业务发生的纳税年度起10年内，进行纳税调整。"},{"i":124,"n":"第一百二十四条","txt":"企业所得税法第五十条所称企业登记注册地，是指企业依照国家有关规定登记注册的住所地。"},{"i":125,"n":"第一百二十五条","txt":"企业汇总计算并缴纳企业所得税时，应当统一核算应纳税所得额，具体办法由国务院财政、税务主管部门另行制定。"},{"i":126,"n":"第一百二十六条","txt":"企业所得税法第五十一条所称主要机构、场所，应当同时符合下列条件："},{"i":127,"n":"第一百二十七条","txt":"企业所得税分月或者分季预缴，由税务机关具体核定。"},{"i":128,"n":"第一百二十八条","txt":"企业在纳税年度内无论盈利或者亏损，都应当依照企业所得税法第五十四条规定的期限，向税务机关报送预缴企业所得税纳税申报表、年度企业所得税纳税申报表、财务会计报告和税务机关规定应当报送的其他有关资料。"},{"i":129,"n":"第一百二十九条","txt":"企业所得以人民币以外的货币计算的，预缴企业所得税时，应当按照月度或者季度最后一日的人民币汇率中间价，折合成人民币计算应纳税所得额。年度终了汇算清缴时，对已经按照月度或者季度预缴税款的，不再重新折合计算，只就该纳税年度内未缴纳企业所得税的部分，按照纳税年度最后一日的人民币汇率中间价，折合成人民币计算应纳税所得额。"},{"i":130,"n":"第一百三十条","txt":"企业所得税法第五十七条第一款所称本法公布前已经批准设立的企业，是指企业所得税法公布前已经完成登记注册的企业。"},{"i":131,"n":"第一百三十一条","txt":"在香港特别行政区、澳门特别行政区和台湾地区成立的企业，参照适用企业所得税法第二条第二款、第三款的有关规定。"},{"i":132,"n":"第一百三十二条","txt":"本条例自2008年1月1日起施行。1991年6月30日国务院发布的《中华人民共和国外商投资企业和外国企业所得税法实施细则》和1994年2月4日财政部发布的《中华人民共和国企业所得税暂行条例实施细则》同时废止。"}],"qiyesuodeshuifashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国企业所得税法》（以下简称企业所得税法）的规定，制定本条例。"},{"i":2,"n":"第二条","txt":"企业所得税法第一条所称个人独资企业、合伙企业，是指依照中国法律、行政法规成立的个人独资企业、合伙企业。"},{"i":3,"n":"第三条","txt":"企业所得税法第二条所称依法在中国境内成立的企业，包括依照中国法律、行政法规在中国境内成立的企业、事业单位、社会团体以及其他取得收入的组织。"},{"i":4,"n":"第四条","txt":"企业所得税法第二条所称实际管理机构，是指对企业的生产经营、人员、账务、财产等实施实质性全面管理和控制的机构。"},{"i":5,"n":"第五条","txt":"企业所得税法第二条第三款所称机构、场所，是指在中国境内从事生产经营活动的机构、场所，包括："},{"i":6,"n":"第六条","txt":"企业所得税法第三条所称所得，包括销售货物所得、提供劳务所得、转让财产所得、股息红利等权益性投资所得、利息所得、租金所得、特许权使用费所得、接受捐赠所得和其他所得。"},{"i":7,"n":"第七条","txt":"企业所得税法第三条所称来源于中国境内、境外的所得，按照以下原则确定："},{"i":8,"n":"第八条","txt":"企业所得税法第三条所称实际联系，是指非居民企业在中国境内设立的机构、场所拥有据以取得所得的股权、债权，以及拥有、管理、控制据以取得所得的财产等。"},{"i":9,"n":"第九条","txt":"企业应纳税所得额的计算，以权责发生制为原则，属于当期的收入和费用，不论款项是否收付，均作为当期的收入和费用；不属于当期的收入和费用，即使款项已经在当期收付，均不作为当期的收入和费用。本条例和国务院财政、税务主管部门另有规定的除外。"},{"i":10,"n":"第十条","txt":"企业所得税法第五条所称亏损，是指企业依照企业所得税法和本条例的规定将每一纳税年度的收入总额减除不征税收入、免税收入和各项扣除后小于零的数额。"},{"i":11,"n":"第十一条","txt":"企业所得税法第五十五条所称清算所得，是指企业的全部资产可变现价值或者交易价格减除资产净值、清算费用以及相关税费等后的余额。"},{"i":12,"n":"第十二条","txt":"企业所得税法第六条所称企业取得收入的货币形式，包括现金、存款、应收账款、应收票据、准备持有至到期的债券投资以及债务的豁免等。"},{"i":13,"n":"第十三条","txt":"企业所得税法第六条所称企业以非货币形式取得的收入，应当按照公允价值确定收入额。"},{"i":14,"n":"第十四条","txt":"企业所得税法第六条第（一）项所称销售货物收入，是指企业销售商品、产品、原材料、包装物、低值易耗品以及其他存货取得的收入。"},{"i":15,"n":"第十五条","txt":"企业所得税法第六条第（二）项所称提供劳务收入，是指企业从事建筑安装、修理修配、交通运输、仓储租赁、金融保险、邮电通信、咨询经纪、文化体育、科学研究、技术服务、教育培训、餐饮住宿、中介代理、卫生保健、社区服务、旅游、娱乐、加工以及其他劳务服务活动取得的收入。"},{"i":16,"n":"第十六条","txt":"企业所得税法第六条第（三）项所称转让财产收入，是指企业转让固定资产、生物资产、无形资产、股权、债权等财产取得的收入。"},{"i":17,"n":"第十七条","txt":"企业所得税法第六条第（四）项所称股息、红利等权益性投资收益，是指企业因权益性投资从被投资方取得的收入。"},{"i":18,"n":"第十八条","txt":"企业所得税法第六条第（五）项所称利息收入，是指企业将资金提供他人使用但不构成权益性投资，或者因他人占用本企业资金取得的收入，包括存款利息、贷款利息、债券利息、欠款利息等收入。"},{"i":19,"n":"第十九条","txt":"企业所得税法第六条第（六）项所称租金收入，是指企业提供固定资产、包装物或者其他有形资产的使用权取得的收入。"},{"i":20,"n":"第二十条","txt":"企业所得税法第六条第（七）项所称特许权使用费收入，是指企业提供专利权、非专利技术、商标权、著作权以及其他特许权的使用权取得的收入。"},{"i":21,"n":"第二十一条","txt":"企业所得税法第六条第（八）项所称接受捐赠收入，是指企业接受的来自其他企业、组织或者个人无偿给予的货币性资产、非货币性资产。"},{"i":22,"n":"第二十二条","txt":"企业所得税法第六条第（九）项所称其他收入，是指企业取得的除企业所得税法第六条第（一）项至第（八）项规定的收入外的其他收入，包括企业资产溢余收入、逾期未退包装物押金收入、确实无法偿付的应付款项、已作坏账损失处理后又收回的应收款项、债务重组收入、补贴收入、违约金收入、汇兑收益等。"},{"i":23,"n":"第二十三条","txt":"企业的下列生产经营业务可以分期确认收入的实现："},{"i":24,"n":"第二十四条","txt":"采取产品分成方式取得收入的，按照企业分得产品的日期确认收入的实现，其收入额按照产品的公允价值确定。"},{"i":25,"n":"第二十五条","txt":"企业发生非货币性资产交换，以及将货物、财产、劳务用于捐赠、偿债、赞助、集资、广告、样品、职工福利或者利润分配等用途的，应当视同销售货物、转让财产或者提供劳务，但国务院财政、税务主管部门另有规定的除外。"},{"i":26,"n":"第二十六条","txt":"企业所得税法第七条第（一）项所称财政拨款，是指各级人民政府对纳入预算管理的事业单位、社会团体等组织拨付的财政资金，但国务院和国务院财政、税务主管部门另有规定的除外。"},{"i":27,"n":"第二十七条","txt":"企业所得税法第八条所称有关的支出，是指与取得收入直接相关的支出。"},{"i":28,"n":"第二十八条","txt":"企业发生的支出应当区分收益性支出和资本性支出。收益性支出在发生当期直接扣除；资本性支出应当分期扣除或者计入有关资产成本，不得在发生当期直接扣除。"},{"i":29,"n":"第二十九条","txt":"企业所得税法第八条所称成本，是指企业在生产经营活动中发生的销售成本、销货成本、业务支出以及其他耗费。"},{"i":30,"n":"第三十条","txt":"企业所得税法第八条所称费用，是指企业在生产经营活动中发生的销售费用、管理费用和财务费用，已经计入成本的有关费用除外。"},{"i":31,"n":"第三十一条","txt":"企业所得税法第八条所称税金，是指企业发生的除企业所得税和允许抵扣的增值税以外的各项税金及其附加。"},{"i":32,"n":"第三十二条","txt":"企业所得税法第八条所称损失，是指企业在生产经营活动中发生的固定资产和存货的盘亏、毁损、报废损失，转让财产损失，呆账损失，坏账损失，自然灾害等不可抗力因素造成的损失以及其他损失。"},{"i":33,"n":"第三十三条","txt":"企业所得税法第八条所称其他支出，是指除成本、费用、税金、损失外，企业在生产经营活动中发生的与生产经营活动有关的、合理的支出。"},{"i":34,"n":"第三十四条","txt":"企业发生的合理的工资薪金支出，准予扣除。"},{"i":35,"n":"第三十五条","txt":"企业依照国务院有关主管部门或者省级人民政府规定的范围和标准为职工缴纳的基本养老保险费、基本医疗保险费、失业保险费、工伤保险费、生育保险费等基本社会保险费和住房公积金，准予扣除。"},{"i":36,"n":"第三十六条","txt":"除企业依照国家有关规定为特殊工种职工支付的人身安全保险费和国务院财政、税务主管部门规定可以扣除的其他商业保险费外，企业为投资者或者职工支付的商业保险费，不得扣除。"},{"i":37,"n":"第三十七条","txt":"企业在生产经营活动中发生的合理的不需要资本化的借款费用，准予扣除。"},{"i":38,"n":"第三十八条","txt":"企业在生产经营活动中发生的下列利息支出，准予扣除："},{"i":39,"n":"第三十九条","txt":"企业在货币交易中，以及纳税年度终了时将人民币以外的货币性资产、负债按照期末即期人民币汇率中间价折算为人民币时产生的汇兑损失，除已经计入有关资产成本以及与向所有者进行利润分配相关的部分外，准予扣除。"},{"i":40,"n":"第四十条","txt":"企业发生的职工福利费支出，不超过工资薪金总额14%的部分，准予扣除。"},{"i":41,"n":"第四十一条","txt":"企业拨缴的工会经费，不超过工资薪金总额2%的部分，准予扣除。"},{"i":42,"n":"第四十二条","txt":"除国务院财政、税务主管部门另有规定外，企业发生的职工教育经费支出，不超过工资薪金总额2.5%的部分，准予扣除；超过部分，准予在以后纳税年度结转扣除。"},{"i":43,"n":"第四十三条","txt":"企业发生的与生产经营活动有关的业务招待费支出，按照发生额的60%扣除，但最高不得超过当年销售（营业）收入的5‰。"},{"i":44,"n":"第四十四条","txt":"企业发生的符合条件的广告费和业务宣传费支出，除国务院财政、税务主管部门另有规定外，不超过当年销售（营业）收入15%的部分，准予扣除；超过部分，准予在以后纳税年度结转扣除。"},{"i":45,"n":"第四十五条","txt":"企业依照法律、行政法规有关规定提取的用于环境保护、生态恢复等方面的专项资金，准予扣除。上述专项资金提取后改变用途的，不得扣除。"},{"i":46,"n":"第四十六条","txt":"企业参加财产保险，按照规定缴纳的保险费，准予扣除。"},{"i":47,"n":"第四十七条","txt":"企业根据生产经营活动的需要租入固定资产支付的租赁费，按照以下方法扣除："},{"i":48,"n":"第四十八条","txt":"企业发生的合理的劳动保护支出，准予扣除。"},{"i":49,"n":"第四十九条","txt":"企业之间支付的管理费、企业内营业机构之间支付的租金和特许权使用费，以及非银行企业内营业机构之间支付的利息，不得扣除。"},{"i":50,"n":"第五十条","txt":"非居民企业在中国境内设立的机构、场所，就其中国境外总机构发生的与该机构、场所生产经营有关的费用，能够提供总机构出具的费用汇集范围、定额、分配依据和方法等证明文件，并合理分摊的，准予扣除。"},{"i":51,"n":"第五十一条","txt":"企业所得税法第九条所称公益性捐赠，是指企业通过公益性社会组织或者县级以上人民政府及其部门，用于符合法律规定的慈善活动、公益事业的捐赠。"},{"i":52,"n":"第五十二条","txt":"本条例第五十一条所称公益性社会组织，是指同时符合下列条件的慈善组织以及其他社会组织："},{"i":53,"n":"第五十三条","txt":"企业当年发生以及以前年度结转的公益性捐赠支出，不超过年度利润总额12%的部分，准予扣除。"},{"i":54,"n":"第五十四条","txt":"企业所得税法第十条第（六）项所称赞助支出，是指企业发生的与生产经营活动无关的各种非广告性质支出。"},{"i":55,"n":"第五十五条","txt":"企业所得税法第十条第（七）项所称未经核定的准备金支出，是指不符合国务院财政、税务主管部门规定的各项资产减值准备、风险准备等准备金支出。"},{"i":56,"n":"第五十六条","txt":"企业的各项资产，包括固定资产、生物资产、无形资产、长期待摊费用、投资资产、存货等，以历史成本为计税基础。"},{"i":57,"n":"第五十七条","txt":"企业所得税法第十一条所称固定资产，是指企业为生产产品、提供劳务、出租或者经营管理而持有的、使用时间超过12个月的非货币性资产，包括房屋、建筑物、机器、机械、运输工具以及其他与生产经营活动有关的设备、器具、工具等。"},{"i":58,"n":"第五十八条","txt":"固定资产按照以下方法确定计税基础："},{"i":59,"n":"第五十九条","txt":"固定资产按照直线法计算的折旧，准予扣除。"},{"i":60,"n":"第六十条","txt":"除国务院财政、税务主管部门另有规定外，固定资产计算折旧的最低年限如下："},{"i":61,"n":"第六十一条","txt":"从事开采石油、天然气等矿产资源的企业，在开始商业性生产前发生的费用和有关固定资产的折耗、折旧方法，由国务院财政、税务主管部门另行规定。"},{"i":62,"n":"第六十二条","txt":"生产性生物资产按照以下方法确定计税基础："},{"i":63,"n":"第六十三条","txt":"生产性生物资产按照直线法计算的折旧，准予扣除。"},{"i":64,"n":"第六十四条","txt":"生产性生物资产计算折旧的最低年限如下："},{"i":65,"n":"第六十五条","txt":"企业所得税法第十二条所称无形资产，是指企业为生产产品、提供劳务、出租或者经营管理而持有的、没有实物形态的非货币性长期资产，包括专利权、商标权、著作权、土地使用权、非专利技术、商誉等。"},{"i":66,"n":"第六十六条","txt":"无形资产按照以下方法确定计税基础："},{"i":67,"n":"第六十七条","txt":"无形资产按照直线法计算的摊销费用，准予扣除。"},{"i":68,"n":"第六十八条","txt":"企业所得税法第十三条第（一）项和第（二）项所称固定资产的改建支出，是指改变房屋或者建筑物结构、延长使用年限等发生的支出。"},{"i":69,"n":"第六十九条","txt":"企业所得税法第十三条第（三）项所称固定资产的大修理支出，是指同时符合下列条件的支出："},{"i":70,"n":"第七十条","txt":"企业所得税法第十三条第（四）项所称其他应当作为长期待摊费用的支出，自支出发生月份的次月起，分期摊销，摊销年限不得低于3年。"},{"i":71,"n":"第七十一条","txt":"企业所得税法第十四条所称投资资产，是指企业对外进行权益性投资和债权性投资形成的资产。"},{"i":72,"n":"第七十二条","txt":"企业所得税法第十五条所称存货，是指企业持有以备出售的产品或者商品、处在生产过程中的在产品、在生产或者提供劳务过程中耗用的材料和物料等。"},{"i":73,"n":"第七十三条","txt":"企业使用或者销售的存货的成本计算方法，可以在先进先出法、加权平均法、个别计价法中选用一种。计价方法一经选用，不得随意变更。"},{"i":74,"n":"第七十四条","txt":"企业所得税法第十六条所称资产的净值和第十九条所称财产净值，是指有关资产、财产的计税基础减除已经按照规定扣除的折旧、折耗、摊销、准备金等后的余额。"},{"i":75,"n":"第七十五条","txt":"除国务院财政、税务主管部门另有规定外，企业在重组过程中，应当在交易发生时确认有关资产的转让所得或者损失，相关资产应当按照交易价格重新确定计税基础。"},{"i":76,"n":"第七十六条","txt":"企业所得税法第二十二条规定的应纳税额的计算公式为："},{"i":77,"n":"第七十七条","txt":"企业所得税法第二十三条所称已在境外缴纳的所得税税额，是指企业来源于中国境外的所得依照中国境外税收法律以及相关规定应当缴纳并已经实际缴纳的企业所得税性质的税款。"},{"i":78,"n":"第七十八条","txt":"企业所得税法第二十三条所称抵免限额，是指企业来源于中国境外的所得，依照企业所得税法和本条例的规定计算的应纳税额。除国务院财政、税务主管部门另有规定外，该抵免限额应当分国（地区）不分项计算，计算公式如下："},{"i":79,"n":"第七十九条","txt":"企业所得税法第二十三条所称5个年度，是指从企业取得的来源于中国境外的所得，已经在中国境外缴纳的企业所得税性质的税额超过抵免限额的当年的次年起连续5个纳税年度。"},{"i":80,"n":"第八十条","txt":"企业所得税法第二十四条所称直接控制，是指居民企业直接持有外国企业20%以上股份。"},{"i":81,"n":"第八十一条","txt":"企业依照企业所得税法第二十三条、第二十四条的规定抵免企业所得税税额时，应当提供中国境外税务机关出具的税款所属年度的有关纳税凭证。"},{"i":82,"n":"第八十二条","txt":"企业所得税法第二十六条第（一）项所称国债利息收入，是指企业持有国务院财政部门发行的国债取得的利息收入。"},{"i":83,"n":"第八十三条","txt":"企业所得税法第二十六条第（二）项所称符合条件的居民企业之间的股息、红利等权益性投资收益，是指居民企业直接投资于其他居民企业取得的投资收益。企业所得税法第二十六条第（二）项和第（三）项所称股息、红利等权益性投资收益，不包括连续持有居民企业公开发行并上市流通的股票不足12个月取得的投资收益。"},{"i":84,"n":"第八十四条","txt":"企业所得税法第二十六条第（四）项所称符合条件的非营利组织，是指同时符合下列条件的组织："},{"i":85,"n":"第八十五条","txt":"企业所得税法第二十六条第（四）项所称符合条件的非营利组织的收入，不包括非营利组织从事营利性活动取得的收入，但国务院财政、税务主管部门另有规定的除外。"},{"i":86,"n":"第八十六条","txt":"企业所得税法第二十七条第（一）项规定的企业从事农、林、牧、渔业项目的所得，可以免征、减征企业所得税，是指："},{"i":87,"n":"第八十七条","txt":"企业所得税法第二十七条第（二）项所称国家重点扶持的公共基础设施项目，是指《公共基础设施项目企业所得税优惠目录》规定的港口码头、机场、铁路、公路、城市公共交通、电力、水利等项目。"},{"i":88,"n":"第八十八条","txt":"企业所得税法第二十七条第（三）项所称符合条件的环境保护、节能节水项目，包括公共污水处理、公共垃圾处理、沼气综合开发利用、节能减排技术改造、海水淡化等。项目的具体条件和范围由国务院财政、税务主管部门商国务院有关部门制订，报国务院批准后公布施行。"},{"i":89,"n":"第八十九条","txt":"依照本条例第八十七条和第八十八条规定享受减免税优惠的项目，在减免税期限内转让的，受让方自受让之日起，可以在剩余期限内享受规定的减免税优惠；减免税期限届满后转让的，受让方不得就该项目重复享受减免税优惠。"},{"i":90,"n":"第九十条","txt":"企业所得税法第二十七条第（四）项所称符合条件的技术转让所得免征、减征企业所得税，是指一个纳税年度内，居民企业技术转让所得不超过500万元的部分，免征企业所得税；超过500万元的部分，减半征收企业所得税。"},{"i":91,"n":"第九十一条","txt":"非居民企业取得企业所得税法第二十七条第（五）项规定的所得，减按10%的税率征收企业所得税。"},{"i":92,"n":"第九十二条","txt":"企业所得税法第二十八条第一款所称符合条件的小型微利企业，是指从事国家非限制和禁止行业，并符合下列条件的企业："},{"i":93,"n":"第九十三条","txt":"企业所得税法第二十八条第二款所称国家需要重点扶持的高新技术企业，是指拥有核心自主知识产权，并同时符合下列条件的企业："},{"i":94,"n":"第九十四条","txt":"企业所得税法第二十九条所称民族自治地方，是指依照《中华人民共和国民族区域自治法》的规定，实行民族区域自治的自治区、自治州、自治县。"},{"i":95,"n":"第九十五条","txt":"企业所得税法第三十条第（一）项所称研究开发费用的加计扣除，是指企业为开发新技术、新产品、新工艺发生的研究开发费用，未形成无形资产计入当期损益的，在按照规定据实扣除的基础上，按照研究开发费用的50%加计扣除；形成无形资产的，按照无形资产成本的150%摊销。"},{"i":96,"n":"第九十六条","txt":"企业所得税法第三十条第（二）项所称企业安置残疾人员所支付的工资的加计扣除，是指企业安置残疾人员的，在按照支付给残疾职工工资据实扣除的基础上，按照支付给残疾职工工资的100%加计扣除。残疾人员的范围适用《中华人民共和国残疾人保障法》的有关规定。"},{"i":97,"n":"第九十七条","txt":"企业所得税法第三十一条所称抵扣应纳税所得额，是指创业投资企业采取股权投资方式投资于未上市的中小高新技术企业2年以上的，可以按照其投资额的70%在股权持有满2年的当年抵扣该创业投资企业的应纳税所得额；当年不足抵扣的，可以在以后纳税年度结转抵扣。"},{"i":98,"n":"第九十八条","txt":"企业所得税法第三十二条所称可以采取缩短折旧年限或者采取加速折旧的方法的固定资产，包括："},{"i":99,"n":"第九十九条","txt":"企业所得税法第三十三条所称减计收入，是指企业以《资源综合利用企业所得税优惠目录》规定的资源作为主要原材料，生产国家非限制和禁止并符合国家和行业相关标准的产品取得的收入，减按90%计入收入总额。"},{"i":100,"n":"第一百条","txt":"企业所得税法第三十四条所称税额抵免，是指企业购置并实际使用《环境保护专用设备企业所得税优惠目录》、《节能节水专用设备企业所得税优惠目录》和《安全生产专用设备企业所得税优惠目录》规定的环境保护、节能节水、安全生产等专用设备的，该专用设备的投资额的10%可以从企业当年的应纳税额中抵免；当年不足抵免的，可以在以后5个纳税年度结转抵免。"},{"i":101,"n":"第一百零一条","txt":"本章第八十七条、第九十九条、第一百条规定的企业所得税优惠目录，由国务院财政、税务主管部门商国务院有关部门制订，报国务院批准后公布施行。"},{"i":102,"n":"第一百零二条","txt":"企业同时从事适用不同企业所得税待遇的项目的，其优惠项目应当单独计算所得，并合理分摊企业的期间费用；没有单独计算的，不得享受企业所得税优惠。"},{"i":103,"n":"第一百零三条","txt":"依照企业所得税法对非居民企业应当缴纳的企业所得税实行源泉扣缴的，应当依照企业所得税法第十九条的规定计算应纳税所得额。"},{"i":104,"n":"第一百零四条","txt":"企业所得税法第三十七条所称支付人，是指依照有关法律规定或者合同约定对非居民企业直接负有支付相关款项义务的单位或者个人。"},{"i":105,"n":"第一百零五条","txt":"企业所得税法第三十七条所称支付，包括现金支付、汇拨支付、转账支付和权益兑价支付等货币支付和非货币支付。"},{"i":106,"n":"第一百零六条","txt":"企业所得税法第三十八条规定的可以指定扣缴义务人的情形，包括："},{"i":107,"n":"第一百零七条","txt":"企业所得税法第三十九条所称所得发生地，是指依照本条例第七条规定的原则确定的所得发生地。在中国境内存在多处所得发生地的，由纳税人选择其中之一申报缴纳企业所得税。"},{"i":108,"n":"第一百零八条","txt":"企业所得税法第三十九条所称该纳税人在中国境内其他收入，是指该纳税人在中国境内取得的其他各种来源的收入。"},{"i":109,"n":"第一百零九条","txt":"企业所得税法第四十一条所称关联方，是指与企业有下列关联关系之一的企业、其他组织或者个人："},{"i":110,"n":"第一百一十条","txt":"企业所得税法第四十一条所称独立交易原则，是指没有关联关系的交易各方，按照公平成交价格和营业常规进行业务往来遵循的原则。"},{"i":111,"n":"第一百一十一条","txt":"企业所得税法第四十一条所称合理方法，包括："},{"i":112,"n":"第一百一十二条","txt":"企业可以依照企业所得税法第四十一条第二款的规定，按照独立交易原则与其关联方分摊共同发生的成本，达成成本分摊协议。"},{"i":113,"n":"第一百一十三条","txt":"企业所得税法第四十二条所称预约定价安排，是指企业就其未来年度关联交易的定价原则和计算方法，向税务机关提出申请，与税务机关按照独立交易原则协商、确认后达成的协议。"},{"i":114,"n":"第一百一十四条","txt":"企业所得税法第四十三条所称相关资料，包括："},{"i":115,"n":"第一百一十五条","txt":"税务机关依照企业所得税法第四十四条的规定核定企业的应纳税所得额时，可以采用下列方法："},{"i":116,"n":"第一百一十六条","txt":"企业所得税法第四十五条所称中国居民，是指根据《中华人民共和国个人所得税法》的规定，就其从中国境内、境外取得的所得在中国缴纳个人所得税的个人。"},{"i":117,"n":"第一百一十七条","txt":"企业所得税法第四十五条所称控制，包括："},{"i":118,"n":"第一百一十八条","txt":"企业所得税法第四十五条所称实际税负明显低于企业所得税法第四条第一款规定税率水平，是指低于企业所得税法第四条第一款规定税率的50%。"},{"i":119,"n":"第一百一十九条","txt":"企业所得税法第四十六条所称债权性投资，是指企业直接或者间接从关联方获得的，需要偿还本金和支付利息或者需要以其他具有支付利息性质的方式予以补偿的融资。"},{"i":120,"n":"第一百二十条","txt":"企业所得税法第四十七条所称不具有合理商业目的，是指以减少、免除或者推迟缴纳税款为主要目的。"},{"i":121,"n":"第一百二十一条","txt":"税务机关根据税收法律、行政法规的规定，对企业作出特别纳税调整的，应当对补征的税款，自税款所属纳税年度的次年6月1日起至补缴税款之日止的期间，按日加收利息。"},{"i":122,"n":"第一百二十二条","txt":"企业所得税法第四十八条所称利息，应当按照税款所属纳税年度中国人民银行公布的与补税期间同期的人民币贷款基准利率加5个百分点计算。"},{"i":123,"n":"第一百二十三条","txt":"企业与其关联方之间的业务往来，不符合独立交易原则，或者企业实施其他不具有合理商业目的安排的，税务机关有权在该业务发生的纳税年度起10年内，进行纳税调整。"},{"i":124,"n":"第一百二十四条","txt":"企业所得税法第五十条所称企业登记注册地，是指企业依照国家有关规定登记注册的住所地。"},{"i":125,"n":"第一百二十五条","txt":"企业汇总计算并缴纳企业所得税时，应当统一核算应纳税所得额，具体办法由国务院财政、税务主管部门另行制定。"},{"i":126,"n":"第一百二十六条","txt":"企业所得税法第五十一条所称主要机构、场所，应当同时符合下列条件："},{"i":127,"n":"第一百二十七条","txt":"企业所得税分月或者分季预缴，由税务机关具体核定。"},{"i":128,"n":"第一百二十八条","txt":"企业在纳税年度内无论盈利或者亏损，都应当依照企业所得税法第五十四条规定的期限，向税务机关报送预缴企业所得税纳税申报表、年度企业所得税纳税申报表、财务会计报告和税务机关规定应当报送的其他有关资料。"},{"i":129,"n":"第一百二十九条","txt":"企业所得以人民币以外的货币计算的，预缴企业所得税时，应当按照月度或者季度最后一日的人民币汇率中间价，折合成人民币计算应纳税所得额。年度终了汇算清缴时，对已经按照月度或者季度预缴税款的，不再重新折合计算，只就该纳税年度内未缴纳企业所得税的部分，按照纳税年度最后一日的人民币汇率中间价，折合成人民币计算应纳税所得额。"},{"i":130,"n":"第一百三十条","txt":"企业所得税法第五十七条第一款所称本法公布前已经批准设立的企业，是指企业所得税法公布前已经完成登记注册的企业。"},{"i":131,"n":"第一百三十一条","txt":"在香港特别行政区、澳门特别行政区和台湾地区成立的企业，参照适用企业所得税法第二条第二款、第三款的有关规定。"},{"i":132,"n":"第一百三十二条","txt":"本条例自2008年1月1日起施行。1991年6月30日国务院发布的《中华人民共和国外商投资企业和外国企业所得税法实施细则》和1994年2月4日财政部发布的《中华人民共和国企业所得税暂行条例实施细则》同时废止。"}],"chuanranbingfangzhifashishibanfa":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国传染病防治法》（以下简称《传染病防治法》）的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"国家对传染病实行预防为主的方针，各级政府在制定社会经济发展规划时，必须包括传染病防治目标，并组织有关部门共同实施。"},{"i":3,"n":"第三条","txt":"各级政府卫生行政部门对传染病防治工作实施统一监督管理。"},{"i":4,"n":"第四条","txt":"各级各类卫生防疫机构按照专业分工承担传染病监测管理的责任和范围，由省级政府卫生行政部门确定。"},{"i":5,"n":"第五条","txt":"各级各类医疗保健机构承担传染病防治管理的责任和范围，由当地政府卫生行政部门确定。"},{"i":6,"n":"第六条","txt":"各级政府对预防、控制传染病做出显著成绩和贡献的单位和个人，应当给予奖励。"},{"i":7,"n":"第七条","txt":"各级政府应当组织有关部门，开展传染病预防知识和防治措施的卫生健康教育。"},{"i":8,"n":"第八条","txt":"各级政府组织开展爱国卫生活动。"},{"i":9,"n":"第九条","txt":"集中式供水必须符合国家《生活饮用水卫生标准》。"},{"i":10,"n":"第十条","txt":"地方各级政府应当有计划地建设和改造公共卫生设施。"},{"i":11,"n":"第十一条","txt":"国家实行有计划的预防接种制度。"},{"i":12,"n":"第十二条","txt":"国家对儿童实行预防接种证制度。"},{"i":13,"n":"第十三条","txt":"各级各类医疗保健机构的预防保健组织或者人员，在本单位及责任地段内承担下列工作："},{"i":14,"n":"第十四条","txt":"医疗保健机构必须按照国务院卫生行政部门的有关规定，严格执行消毒隔离制度，防止医院内感染和医源性感染。"},{"i":15,"n":"第十五条","txt":"卫生防疫机构和从事致病性微生物实验的科研、教学、生产等单位必须做到："},{"i":16,"n":"第十六条","txt":"传染病的菌（毒）种分为下列三类："},{"i":17,"n":"第十七条","txt":"国家对传染病菌（毒）种的保藏、携带、运输实行严格管理："},{"i":18,"n":"第十八条","txt":"对患有下列传染病的病人或者病原携带者予以必要的隔离治疗，直至医疗保健机构证明其不具有传染性时，方可恢复工作："},{"i":19,"n":"第十九条","txt":"从事饮水、饮食、整容、保育等易使传染病扩散工作的从业人员，必须按照国家有关规定取得健康合格证后方可上岗。"},{"i":20,"n":"第二十条","txt":"招用流动人员二百人以上的用工单位，应当向当地政府卫生行政部门指定的卫生防疫机构报告，并按照要求采取预防控制传染病的卫生措施。"},{"i":21,"n":"第二十一条","txt":"被甲类传染病病原体污染的污水、污物、粪便，有关单位和个人必须在卫生防疫人员的指导监督下，按照下列要求进行处理："},{"i":22,"n":"第二十二条","txt":"被伤寒和副伤寒、细菌性痢疾、脊髓灰质炎、病毒性肝炎病原体污染的水、物品、粪便，有关单位和个人应当按照下列要求进行处理："},{"i":23,"n":"第二十三条","txt":"出售、运输被传染病病原体污染或者来自疫区可能被传染病病原体污染的皮毛、旧衣物及生活用品等，必须按照卫生防疫机构的要求进行必要的卫生处理。"},{"i":24,"n":"第二十四条","txt":"用于预防传染病的菌苗、疫苗等生物制品，由各省、自治区、直辖市卫生防疫机构统一向生物制品生产单位订购，其他任何单位和个人不得经营。"},{"i":25,"n":"第二十五条","txt":"凡从事可能导致经血液传播传染病的美容、整容等单位和个人，必须执行国务院卫生行政部门的有关规定。"},{"i":26,"n":"第二十六条","txt":"血站（库）、生物制品生产单位，必须严格执行国务院卫生行政部门的有关规定，保证血液、血液制品的质量，防止因输入血液、血液制品引起病毒性肝炎、艾滋病、疟疾等疾病的发生。任何单位和个人不准使用国务院卫生行政部门禁止进口的血液和血液制品。"},{"i":27,"n":"第二十七条","txt":"生产、经营、使用消毒药剂和消毒器械、卫生用品、卫生材料、一次性医疗器材、隐形眼镜、人造器官等必须符合国家有关标准，不符合国家有关标准的不得生产、经营和使用。"},{"i":28,"n":"第二十八条","txt":"发现人畜共患传染病已在人、畜间流行时，卫生行政部门与畜牧兽医部门应当深入疫区，按照职责分别对人、畜开展防治工作。"},{"i":29,"n":"第二十九条","txt":"狂犬病的防治管理工作按照下列规定分工负责："},{"i":30,"n":"第三十条","txt":"自然疫源地或者可能是自然疫源地的地区计划兴建大型建设项目时，建设单位在设计任务书批准后，应当向当地卫生防疫机构申请对施工环境进行卫生调查，并根据卫生防疫机构的意见采取必要的卫生防疫措施后，方可办理开工手续。"},{"i":31,"n":"第三十一条","txt":"卫生防疫机构接到在自然疫源地和可能是自然疫源地范围内兴办大型建设项目的建设单位的卫生调查申请后，应当及时组成调查组到现场进行调查，并提出该地区自然环境中可能存在的传染病病种、流行范围、流行强度及预防措施等意见和结论。"},{"i":32,"n":"第三十二条","txt":"在自然疫源地或者可能是自然疫源地内施工的建设单位，应当设立预防保健组织负责施工期间的卫生防疫工作。"},{"i":33,"n":"第三十三条","txt":"凡在生产、工作中接触传染病病原体的工作人员，可以按照国家有关规定申领卫生防疫津贴。"},{"i":34,"n":"第三十四条","txt":"执行职务的医疗保健人员、卫生防疫人员为责任疫情报告人。"},{"i":35,"n":"第三十五条","txt":"责任疫情报告人发现甲类传染病和乙类传染病中的艾滋病、肺炭疽的病人、病原携带者和疑似传染病病人时，城镇于六小时内，农村于十二小时内，以最快的通讯方式向发病地的卫生防疫机构报告，并同时报出传染病报告卡。"},{"i":36,"n":"第三十六条","txt":"传染病暴发、流行时，责任疫情报告人应当以最快的通讯方式向当地卫生防疫机构报告疫情。接到疫情报告的卫生防疫机构应当以最快的通讯方式报告上级卫生防疫机构和当地政府卫生行政部门，卫生行政部门接到报告后，应当立即报告当地政府。"},{"i":37,"n":"第三十七条","txt":"流动人员中的传染病病人、病原携带者和疑似传染病病人的传染病报告、处理由诊治地负责，其疫情登记、统计由户口所在地负责。"},{"i":38,"n":"第三十八条","txt":"铁路、交通、民航、厂（场）矿的卫生防疫机构，应当定期向所在地卫生行政部门指定的卫生防疫机构报告疫情。"},{"i":39,"n":"第三十九条","txt":"军队的传染病疫情，由中国人民解放军卫生主管部门根据军队有关规定向国务院卫生行政部门报告。"},{"i":40,"n":"第四十条","txt":"国境口岸所在地卫生行政部门指定的卫生防疫机构和港口、机场、铁路卫生防疫机构和国境卫生检疫机关在发现国境卫生检疫法规定的检疫传染病时，应当互相通报疫情。"},{"i":41,"n":"第四十一条","txt":"各级政府卫生行政部门指定的卫生防疫机构应当对辖区内各类医疗保健机构的疫情登记报告和管理情况定期进行核实、检查、指导。"},{"i":42,"n":"第四十二条","txt":"传染病报告卡片邮寄信封应当印有明显的“红十字”标志及写明××卫生防疫机构收的字样。"},{"i":43,"n":"第四十三条","txt":"医务人员未经县级以上政府卫生行政部门批准，不得将就诊的淋病、梅毒、麻风病、艾滋病病人和艾滋病病原携带者及其家属的姓名、住址和个人病史公开。"},{"i":44,"n":"第四十四条","txt":"卫生防疫机构和医疗保健机构传染病的疫情处理实行分级分工管理。"},{"i":45,"n":"第四十五条","txt":"艾滋病的监测管理按照国务院有关规定执行。"},{"i":46,"n":"第四十六条","txt":"淋病、梅毒病人应当在医疗保健机构、卫生防疫机构接受治疗。尚未治愈前，不得进入公共浴池、游泳池。"},{"i":47,"n":"第四十七条","txt":"医疗保健机构或者卫生防疫机构在诊治中发现甲类传染病的疑似病人，应当在二日内作出明确诊断。"},{"i":48,"n":"第四十八条","txt":"甲类传染病病人和病原携带者以及乙类传染病中的艾滋病、淋病、梅毒病人的密切接触者必须按照有关规定接受检疫、医学检查和防治措施。"},{"i":49,"n":"第四十九条","txt":"甲类传染病疑似病人或者病原携带者的密切接触者，经留验排除是病人或者病原携带者后，留验期间的工资福利待遇由所属单位按出勤照发。"},{"i":50,"n":"第五十条","txt":"发现甲类传染病病人、病原携带者或者疑似病人的污染场所，卫生防疫机构接到疫情报告后，应立即进行严格的卫生处理。"},{"i":51,"n":"第五十一条","txt":"地方各级政府卫生行政部门发现本地区发生从未有过的传染病或者国家已宣布消除的传染病时，应当立即采取措施，必要时，向当地政府报告。"},{"i":52,"n":"第五十二条","txt":"在传染病暴发、流行区域，当地政府应当根据传染病疫情控制的需要，组织卫生、医药、公安、工商、交通、水利、城建、农业、商业、民政、邮电、广播电视等部门采取下列预防、控制措施："},{"i":53,"n":"第五十三条","txt":"县级以上政府接到下一级政府关于采取《传染病防治法》第二十五条规定的紧急措施报告时，应当在二十四小时内做出决定。下一级政府在上一级政府作出决定前，必要时，可以临时采取《传染病防治法》第二十五条第一款第（一）、（四）项紧急措施，但不得超过二十四小时。"},{"i":54,"n":"第五十四条","txt":"撤销采取《传染病防治法》第二十五条紧急措施的条件是："},{"i":55,"n":"第五十五条","txt":"因患鼠疫、霍乱和炭疽病死亡的病人尸体，由治疗病人的医疗单位负责消毒处理，处理后应当立即火化。"},{"i":56,"n":"第五十六条","txt":"医疗保健机构、卫生防疫机构经县级以上政府卫生行政部门的批准可以对传染病病人尸体或者疑似传染病病人的尸体进行解剖查验。"},{"i":57,"n":"第五十七条","txt":"卫生防疫机构处理传染病疫情的人员，可以凭当地政府卫生行政部门出具的处理疫情证明及有效的身份证明，优先在铁路、交通、民航部门购票，铁路、交通、民航部门应当保证售给最近一次通往目的地的车、船、机票。"},{"i":58,"n":"第五十八条","txt":"用于传染病监督控制的车辆，其标志由国务院卫生行政部门会同有关部门统一制定。任何单位和个人不得阻拦依法执行处理疫情任务的车辆和人员。"},{"i":59,"n":"第五十九条","txt":"地方各级政府卫生行政部门、卫生防疫机构和受国务院卫生行政部门委托的其他有关部门卫生主管机构推荐的传染病管理监督员，由省级以上政府卫生行政部门聘任并发给证件。"},{"i":60,"n":"第六十条","txt":"传染病管理监督员执行下列任务："},{"i":61,"n":"第六十一条","txt":"各级各类医疗保健机构内设立的传染病管理检查员，由本单位推荐，经县级以上政府卫生行政部门或受国务院卫生行政部门委托的其他部门卫生主管机构批准并发给证件。"},{"i":62,"n":"第六十二条","txt":"传染病管理检查员执行下列任务："},{"i":63,"n":"第六十三条","txt":"传染病管理监督员、传染病管理检查员执行任务时，有关单位和个人必须给予协助。"},{"i":64,"n":"第六十四条","txt":"传染病管理监督员的解聘和传染病管理检查员资格的取消，由原发证机关决定，并通知其所在单位和个人。"},{"i":65,"n":"第六十五条","txt":"县级以上政府卫生行政部门和受国务院卫生行政部门委托的部门，可以成立传染病技术鉴定组织。"},{"i":66,"n":"第六十六条","txt":"有下列行为之一的，由县级以上政府卫生行政部门责令限期改正，可以处五千元以下的罚款；情节较严重的，可以处五千元以上二万元以下的罚款，对主管人员和直接责任人员由其所在单位或者上级机关给予行政处分："},{"i":67,"n":"第六十七条","txt":"在自然疫源地和可能是自然疫源地的地区兴建大型建设项目未经卫生调查即进行施工的，由县级以上政府卫生行政部门责令限期改正，可以处二千元以上二万元以下的罚款。"},{"i":68,"n":"第六十八条","txt":"单位和个人出售、运输被传染病病原体污染和来自疫区可能被传染病病原体污染的皮毛、旧衣物及生活用品的，由县级以上政府卫生行政部门责令限期进行卫生处理，可以处出售金额一倍以下的罚款；造成传染病流行的，根据情节，可以处相当出售金额三倍以下的罚款，危害严重，出售金额不满二千元的，以二千元计算；对主管人员和直接责任人员由所在单位或者上级机关给予行政处分。"},{"i":69,"n":"第六十九条","txt":"单位和个人非法经营、出售用于预防传染病菌苗、疫苗等生物制品的，县级以上政府卫生行政部门可以处相当出售金额三倍以下的罚款，危害严重，出售金额不满五千元的，以五千元计算；对主管人员和直接责任人员由所在单位或者上级机关根据情节，可以给予行政处分。"},{"i":70,"n":"第七十条","txt":"有下列行为之一的单位和个人，县级以上政府卫生行政部门报请同级政府批准，对单位予以通报批评；对主管人员和直接责任人员由所在单位或者上级机关给予行政处分："},{"i":71,"n":"第七十一条","txt":"执行职务的医疗保健人员、卫生防疫人员和责任单位，不报、漏报、迟报传染病疫情的，由县级以上政府卫生行政部门责令限期改正，对主管人员和直接责任人员由其所在单位或者上级机关根据情节，可以给予行政处分。"},{"i":72,"n":"第七十二条","txt":"县级政府卫生行政部门可以作出处一万元以下罚款的决定；决定处一万元以上罚款的，须报上一级政府卫生行政部门批准。"},{"i":73,"n":"第七十三条","txt":"《传染病防治法》及本办法的用语含义如下："},{"i":74,"n":"第七十四条","txt":"省、自治区、直辖市政府可以根据《传染病防治法》和本办法制定实施细则。"},{"i":75,"n":"第七十五条","txt":"本办法由国务院卫生行政部门负责解释。"},{"i":76,"n":"第七十六条","txt":"本办法自发布之日起施行。"}],"baoshouguojiamimifashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国保守国家秘密法》（以下简称保密法）的规定，制定本条例。"},{"i":2,"n":"第二条","txt":"坚持和加强中国共产党对保守国家秘密（以下简称保密）工作的领导。"},{"i":3,"n":"第三条","txt":"国家保密行政管理部门主管全国的保密工作。县级以上地方各级保密行政管理部门在上级保密行政管理部门指导下，主管本行政区域的保密工作。"},{"i":4,"n":"第四条","txt":"中央国家机关在其职权范围内管理或者指导本系统的保密工作，监督执行保密法律法规，可以根据实际情况制定或者会同有关部门制定主管业务方面的保密规定。"},{"i":5,"n":"第五条","txt":"国家机关和涉及国家秘密的单位（以下简称机关、单位）不得将依法应当公开的事项确定为国家秘密，不得将涉及国家秘密的信息公开。"},{"i":6,"n":"第六条","txt":"机关、单位实行保密工作责任制，承担本机关、本单位保密工作主体责任。机关、单位主要负责人对本机关、本单位的保密工作负总责，分管保密工作的负责人和分管业务工作的负责人在职责范围内对保密工作负领导责任，工作人员对本岗位的保密工作负直接责任。"},{"i":7,"n":"第七条","txt":"县级以上人民政府应当加强保密基础设施建设和关键保密科学技术产品的配备。"},{"i":8,"n":"第八条","txt":"保密行政管理部门履行职责所需的经费，应当列入本级预算。机关、单位开展保密工作所需经费应当列入本机关、本单位的年度预算或者年度收支计划。"},{"i":9,"n":"第九条","txt":"保密行政管理部门应当组织开展经常性的保密宣传教育。干部教育培训主管部门应当会同保密行政管理部门履行干部保密教育培训工作职责。干部教育培训机构应当将保密教育纳入教学体系。教育行政部门应当推动保密教育纳入国民教育体系。宣传部门应当指导鼓励大众传播媒介充分发挥作用，普及保密知识，宣传保密法治，推动全社会增强保密意识。"},{"i":10,"n":"第十条","txt":"保密行政管理部门应当按照国家有关规定完善激励保障机制，加强专门人才队伍建设、专业培训和装备配备，提升保密工作专业化能力和水平。教育行政部门应当加强保密相关学科专业建设指导和支持。"},{"i":11,"n":"第十一条","txt":"对有下列表现之一的组织和个人，应当按照国家有关规定给予表彰和奖励："},{"i":12,"n":"第十二条","txt":"国家秘密及其密级的具体范围（以下称保密事项范围）应当明确规定国家秘密具体事项的名称、密级、保密期限、知悉范围和产生层级。"},{"i":13,"n":"第十三条","txt":"有定密权限的机关、单位应当依据本行业、本领域以及相关行业、领域保密事项范围，制定国家秘密事项一览表，并报同级保密行政管理部门备案。国家秘密事项一览表应当根据保密事项范围及时修订。"},{"i":14,"n":"第十四条","txt":"机关、单位主要负责人为本机关、本单位法定定密责任人，根据工作需要，可以明确本机关、本单位其他负责人、内设机构负责人或者其他人员为指定定密责任人。"},{"i":15,"n":"第十五条","txt":"定密责任人在职责范围内承担国家秘密确定、变更和解除工作，指导、监督职责范围内的定密工作。具体职责是："},{"i":16,"n":"第十六条","txt":"中央国家机关、省级机关以及设区的市级机关可以根据保密工作需要或者有关机关、单位申请，在国家保密行政管理部门规定的定密权限、授权范围内作出定密授权。"},{"i":17,"n":"第十七条","txt":"机关、单位应当在国家秘密产生的同时，由承办人依据有关保密事项范围拟定密级、保密期限和知悉范围，报定密责任人审核批准，并采取相应保密措施。"},{"i":18,"n":"第十八条","txt":"机关、单位执行上级确定的国家秘密事项或者办理其他机关、单位确定的国家秘密事项，有下列情形之一的，应当根据所执行、办理的国家秘密事项的密级、保密期限和知悉范围派生定密："},{"i":19,"n":"第十九条","txt":"机关、单位对所产生的国家秘密，应当按照保密事项范围的规定确定具体的保密期限或者解密时间；不能确定的，应当确定解密条件。"},{"i":20,"n":"第二十条","txt":"机关、单位应当依法限定国家秘密的知悉范围，对知悉机密级以上国家秘密的人员，应当作出记录。"},{"i":21,"n":"第二十一条","txt":"国家秘密载体以及属于国家秘密的设备、产品（以下简称密品）的明显部位应当作出国家秘密标志。国家秘密标志应当标注密级、保密期限。国家秘密的密级或者保密期限发生变更的，应当及时对原国家秘密标志作出变更。"},{"i":22,"n":"第二十二条","txt":"机关、单位对所确定的国家秘密，认为符合保密法有关解除或者变更规定的，应当及时解除或者变更。"},{"i":23,"n":"第二十三条","txt":"机关、单位被撤销或者合并、分立的，该机关、单位所确定国家秘密的变更和解除，由承担其职能的机关、单位负责；没有相应机关、单位的，由其上级机关、单位或者同级保密行政管理部门指定的机关、单位负责。"},{"i":24,"n":"第二十四条","txt":"机关、单位发现本机关、本单位国家秘密的确定、变更和解除不当的，应当及时纠正；上级机关、单位发现下级机关、单位国家秘密的确定、变更和解除不当的，应当及时通知其纠正，也可以直接纠正。"},{"i":25,"n":"第二十五条","txt":"机关、单位对符合保密法的规定，但保密事项范围没有规定的不明确事项，应当先行拟定密级、保密期限和知悉范围，采取相应的保密措施，并自拟定之日起10个工作日内报有关部门确定。拟定为绝密级的事项和中央国家机关拟定的机密级、秘密级的事项，报国家保密行政管理部门确定；其他机关、单位拟定的机密级、秘密级的事项，报省、自治区、直辖市保密行政管理部门确定。"},{"i":26,"n":"第二十六条","txt":"机关、单位对已确定的国家秘密事项是否属于国家秘密或者属于何种密级有不同意见的，可以向原定密机关、单位提出异议，由原定密机关、单位作出决定。"},{"i":27,"n":"第二十七条","txt":"国家秘密载体管理应当遵守下列规定："},{"i":28,"n":"第二十八条","txt":"销毁国家秘密载体，应当符合国家保密规定和标准，确保销毁的国家秘密信息无法还原。"},{"i":29,"n":"第二十九条","txt":"绝密级国家秘密载体管理还应当遵守下列规定："},{"i":30,"n":"第三十条","txt":"机关、单位应当依法对密品的研制、生产、试验、运输、使用、保存、维修、销毁等进行管理。"},{"i":31,"n":"第三十一条","txt":"机关、单位应当依法确定保密要害部门、部位，报同级保密行政管理部门确认，严格保密管理。"},{"i":32,"n":"第三十二条","txt":"涉密信息系统按照涉密程度分为绝密级、机密级、秘密级。机关、单位应当根据涉密信息系统存储、处理信息的最高密级确定保护等级，按照分级保护要求采取相应的安全保密防护措施。"},{"i":33,"n":"第三十三条","txt":"涉密信息系统应当由国家保密行政管理部门设立或者授权的机构进行检测评估，并经设区的市级以上保密行政管理部门审查合格，方可投入使用。"},{"i":34,"n":"第三十四条","txt":"机关、单位应当加强信息系统、信息设备的运行维护、使用管理，指定专门机构或者人员负责运行维护、安全保密管理和安全审计，按照国家保密规定建设保密自监管设施，定期开展安全保密检查和风险评估，配合保密行政管理部门排查预警事件，及时发现并处置安全保密风险隐患。"},{"i":35,"n":"第三十五条","txt":"机关、单位应当按照国家保密规定，对绝密级信息系统每年至少开展一次安全保密风险评估，对机密级及以下信息系统每两年至少开展一次安全保密风险评估。机关、单位涉密信息系统的密级、使用范围和使用环境等发生变化可能产生新的安全保密风险隐患的，应当按照国家保密规定和标准采取相应防护措施，并开展安全保密风险评估。"},{"i":36,"n":"第三十六条","txt":"研制、生产、采购、配备用于保护国家秘密的安全保密产品和保密技术装备应当符合国家保密规定和标准。"},{"i":37,"n":"第三十七条","txt":"研制生产单位应当为用于保护国家秘密的安全保密产品和保密技术装备持续提供维修维护服务，建立漏洞、缺陷发现和处理机制，不得在安全保密产品和保密技术装备中设置恶意程序。"},{"i":38,"n":"第三十八条","txt":"国家保密行政管理部门组织其设立或者授权的机构开展用于保护国家秘密的安全保密产品和保密技术装备抽检、复检，发现不符合国家保密规定和标准的，应当责令整改；存在重大缺陷或者重大泄密隐患的，应当责令采取停止销售、召回产品等补救措施，相关单位应当配合。"},{"i":39,"n":"第三十九条","txt":"网络运营者应当遵守保密法律法规和国家有关规定，建立保密违法行为投诉、举报、发现、处置制度，完善受理和处理工作机制，制定泄密应急预案。发生泄密事件时，网络运营者应当立即启动应急预案，采取补救措施，并向保密行政管理部门或者公安机关、国家安全机关报告。"},{"i":40,"n":"第四十条","txt":"网络运营者对保密行政管理部门依法实施的保密违法案件调查和预警事件排查，应当予以配合。"},{"i":41,"n":"第四十一条","txt":"机关、单位应当加强对互联网使用的保密管理。机关、单位工作人员使用智能终端产品等应当符合国家保密规定，不得违反有关规定使用非涉密信息系统、信息设备存储、处理、传输国家秘密。"},{"i":42,"n":"第四十二条","txt":"机关、单位应当健全信息公开保密审查工作机制，明确审查机构，规范审查程序，按照先审查、后公开的原则，对拟公开的信息逐项进行保密审查。"},{"i":43,"n":"第四十三条","txt":"机关、单位应当承担涉密数据安全保护责任，涉密数据收集、存储、使用、加工、传输、提供等处理活动应当符合国家保密规定。"},{"i":44,"n":"第四十四条","txt":"机关、单位向境外或者向境外在中国境内设立的组织、机构提供国家秘密，任用、聘用的境外人员因工作需要知悉国家秘密的，应当按照国家保密规定办理，进行审查评估，签订保密协议，督促落实保密管理要求。"},{"i":45,"n":"第四十五条","txt":"举办会议或者其他活动涉及国家秘密的，主办单位应当采取下列保密措施，承办、参加单位和人员应当配合："},{"i":46,"n":"第四十六条","txt":"保密行政管理部门及其他主管部门应当加强对涉密军事设施及其他重要涉密单位周边区域保密管理工作的指导和监督，建立协调机制，加强军地协作，组织督促整改，有关机关、单位应当配合，及时发现并消除安全保密风险隐患。"},{"i":47,"n":"第四十七条","txt":"从事涉及国家秘密业务（以下简称涉密业务）的企业事业单位应当符合下列条件："},{"i":48,"n":"第四十八条","txt":"从事国家秘密载体制作、复制、维修、销毁，涉密信息系统集成，武器装备科研生产，或者涉密军事设施建设等涉密业务的企业事业单位，应当由保密行政管理部门单独或者会同有关部门进行保密审查，取得保密资质。"},{"i":49,"n":"第四十九条","txt":"机关、单位采购涉及国家秘密的工程、货物、服务，或者委托企业事业单位从事涉密业务，应当根据国家保密规定确定密级，并符合国家保密规定和标准。机关、单位应当与有关单位、个人签订保密协议，提出保密要求，采取保密措施，实施全过程管理。"},{"i":50,"n":"第五十条","txt":"机关、单位应当依法确定涉密岗位，对拟任用、聘用到涉密岗位工作的人员进行上岗前保密审查，确认其是否具备在涉密岗位工作的条件和能力。未通过保密审查的，不得任用、聘用到涉密岗位工作。"},{"i":51,"n":"第五十一条","txt":"涉密人员应当遵守保密法律法规和本机关、本单位保密制度，严格遵守保密纪律、履行保密承诺，接受保密管理，不得以任何方式泄露国家秘密。"},{"i":52,"n":"第五十二条","txt":"机关、单位组织人事部门会同保密工作机构负责涉密人员保密管理工作。机关、单位保密工作机构应当对涉密人员履行保密责任情况开展经常性的监督检查，会同组织人事部门加强保密教育培训。"},{"i":53,"n":"第五十三条","txt":"涉密人员离岗离职应当遵守有关法律法规规定；离岗离职前，应当接受保密提醒谈话，签订离岗离职保密承诺书。机关、单位应当开展保密教育提醒，清退国家秘密载体、涉密设备，取消涉密信息系统访问权限，确定脱密期期限。涉密人员在脱密期内就业、出境应当遵守国家保密规定。涉密人员不得利用知悉的国家秘密为有关组织、个人提供服务或者谋取利益。"},{"i":54,"n":"第五十四条","txt":"涉密人员擅自离职或者脱密期内严重违反国家保密规定的，机关、单位应当及时报告同级保密行政管理部门，由保密行政管理部门会同有关部门依法采取处置措施。"},{"i":55,"n":"第五十五条","txt":"机关、单位应当建立健全涉密人员权益保障制度，按照国家有关规定给予因履行保密义务导致合法权益受到影响和限制的人员相应待遇或者补偿。"},{"i":56,"n":"第五十六条","txt":"机关、单位应当向同级保密行政管理部门报送本机关、本单位年度保密工作情况。下级保密行政管理部门应当向上级保密行政管理部门报送本行政区域年度保密工作情况。"},{"i":57,"n":"第五十七条","txt":"国家建立和完善保密标准体系。国家保密行政管理部门依照法律、行政法规的规定制定国家保密标准；相关学会、协会等社会团体可以制定团体标准；相关企业可以制定企业标准。"},{"i":58,"n":"第五十八条","txt":"机关、单位应当对遵守保密法律法规和相关制度情况开展自查自评。保密行政管理部门依法对下列情况进行检查："},{"i":59,"n":"第五十九条","txt":"保密行政管理部门依法开展保密检查和案件调查处理，查阅有关材料、询问人员、记录情况，对有关设施、设备、文件资料等登记保存，进行保密技术检测，应当遵守国家有关规定和程序。"},{"i":60,"n":"第六十条","txt":"保密行政管理部门对涉嫌保密违法的线索和案件，应当依法及时调查处理或者组织、督促有关机关、单位调查处理；发现需要采取补救措施的，应当立即责令有关机关、单位和人员停止违法行为，采取有效补救措施。调查工作结束后，有违反保密法律法规的事实，需要追究责任的，保密行政管理部门应当依法作出行政处罚决定或者提出处理建议；涉嫌犯罪的，应当依法移送监察机关、司法机关处理。有关机关、单位应当及时将处理结果书面告知同级保密行政管理部门。"},{"i":61,"n":"第六十一条","txt":"机关、单位发现国家秘密已经泄露或者可能泄露的，应当立即采取补救措施，并在24小时内向同级保密行政管理部门和上级主管部门报告。"},{"i":62,"n":"第六十二条","txt":"保密行政管理部门收缴非法获取、持有的国家秘密载体，应当进行登记并出具清单，查清密级、数量、来源、扩散范围等，并采取相应的保密措施。"},{"i":63,"n":"第六十三条","txt":"办理涉嫌泄密案件的地方各级监察机关、司法机关申请国家秘密和情报鉴定的，向所在省、自治区、直辖市保密行政管理部门提出；办理涉嫌泄密案件的中央一级监察机关、司法机关申请国家秘密和情报鉴定的，向国家保密行政管理部门提出。"},{"i":64,"n":"第六十四条","txt":"设区的市级以上保密行政管理部门应当建立监测预警制度，分析研判保密工作有关情况，配备监测预警设施和相应工作力量，发现、识别、处置安全保密风险隐患，及时发出预警通报。"},{"i":65,"n":"第六十五条","txt":"保密行政管理部门和其他相关部门应当在保密工作中加强协调配合，及时通报情况。"},{"i":66,"n":"第六十六条","txt":"保密行政管理部门及其工作人员应当按照法定的职权和程序开展工作，做到严格规范公正文明执法，依法接受监督。"},{"i":67,"n":"第六十七条","txt":"机关、单位违反保密法律法规发生泄密案件，有下列情形之一的，根据情节轻重，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任："},{"i":68,"n":"第六十八条","txt":"在保密检查或者保密违法案件调查处理中，有关机关、单位及其工作人员拒不配合，弄虚作假，隐匿、销毁证据，或者以其他方式逃避、妨碍保密检查或者保密违法案件调查处理的，对直接负责的主管人员和其他直接责任人员依法给予处分；不适用处分的人员，由保密行政管理部门督促其主管部门予以处理。"},{"i":69,"n":"第六十九条","txt":"网络运营者违反保密法律法规，有下列情形之一的，由保密行政管理等部门按照各自职责分工责令限期整改，给予警告或者通报批评；情节严重的，处5万元以上50万元以下罚款，对直接负责的主管人员和其他直接责任人员处1万元以上10万元以下罚款："},{"i":70,"n":"第七十条","txt":"用于保护国家秘密的安全保密产品和保密技术装备不符合国家保密规定和标准，有下列情形之一的，由保密行政管理等部门对研制生产单位给予警告或者通报批评，责令有关检测机构取消合格证书；有违法所得的，没收违法所得："},{"i":71,"n":"第七十一条","txt":"从事涉密业务的企业事业单位违反保密法律法规及国家保密规定的，由保密行政管理部门责令限期整改，给予警告或者通报批评；有违法所得的，没收违法所得。"},{"i":72,"n":"第七十二条","txt":"保密行政管理部门未依法履行职责，或者滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":73,"n":"第七十三条","txt":"中央国家机关应当结合工作实际制定本行业、本领域工作秘密事项具体范围，报国家保密行政管理部门备案。"},{"i":74,"n":"第七十四条","txt":"本条例自2024年9月1日起施行。"}],"junshisheshibaohufashishibanfa":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国军事设施保护法》（以下简称军事设施保护法）的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"设有军事设施的地方，县级以上地方人民政府和驻地有关军事机关共同成立军事设施保护委员会，负责协调、指导本行政区域内的军事设施保护工作。"},{"i":3,"n":"第三条","txt":"军事设施保护委员会履行下列职责："},{"i":4,"n":"第四条","txt":"中国人民解放军总参谋部在国务院和中央军事委员会的领导下，主管全国的军事设施保护工作，指导各级军事设施保护委员会的工作。"},{"i":5,"n":"第五条","txt":"国务院有关部门在各自的职责范围内，负责军事设施保护的有关工作，并协助军事机关落实军事设施保护措施。"},{"i":6,"n":"第六条","txt":"军事机关应当向驻地人民政府介绍军事设施的有关情况，听取驻地人民政府的意见；地方人民政府应当向驻地军事机关介绍经济建设的有关情况，听取驻地军事机关的意见。"},{"i":7,"n":"第七条","txt":"各级人民政府和军事机关对在军事设施保护工作中做出显著成绩的组织和个人，给予表彰、奖励。"},{"i":8,"n":"第八条","txt":"军事禁区、军事管理区的确定及其范围的划定，以及军事禁区外围安全控制范围的划定，依照军事设施保护法和国务院、中央军事委员会的有关规定办理。"},{"i":9,"n":"第九条","txt":"在水域军事禁区内，禁止非军用船只进入，禁止建筑、设置非军事设施，禁止从事水产养殖、捕捞以及其他有碍军用舰船行动和安全保密的活动。"},{"i":10,"n":"第十条","txt":"在水域军事管理区内，禁止建筑、设置非军事设施，禁止从事水产养殖；从事捕捞或者其他活动，不得影响军用舰船的行动。"},{"i":11,"n":"第十一条","txt":"划为军事管理区的军民合用港口的水域，实行军地分区管理；在地方管理的水域内需要新建非军事设施的，必须事先征得有关军事设施管理单位的同意。"},{"i":12,"n":"第十二条","txt":"军事禁区、军事管理区应当设立标志牌。标志牌的样式、质地和规格由省、自治区、直辖市军事设施保护委员会规定，标志牌由县级以上地方人民政府负责设立。"},{"i":13,"n":"第十三条","txt":"军事设施保护法所称作战工程，包括坑道、永备工事以及配套的专用道路、桥涵以及水源、供电、战备用房等附属设施。"},{"i":14,"n":"第十四条","txt":"未划入军事禁区、军事管理区的作战工程应当在作战工程外围划定安全保护范围。作战工程的安全保护范围，根据工程部署、地形和当地经济建设情况，由省军区或者作战工程管理单位的上级军级以上主管军事机关提出方案，报军区和省、自治区、直辖市人民政府批准。"},{"i":15,"n":"第十五条","txt":"作战工程安全保护范围的划定，不影响安全保护范围内的土地及其附着物的所有权、使用权，安全保护范围内的单位、居民可以照常生产、生活，但不得危害军事设施的安全保密和使用效能。"},{"i":16,"n":"第十六条","txt":"在作战工程安全保护范围内，禁止开山采石、采矿、爆破，禁止采伐林木；修筑建筑物、构筑物、道路和进行农田水利基本建设，应当征得作战工程管理单位的上级主管军事机关和当地军事设施保护委员会同意，并不得影响作战工程的安全保密和使用效能。"},{"i":17,"n":"第十七条","txt":"禁止私自开启封闭的作战工程，禁止破坏作战工程的伪装，禁止阻断入出作战工程的通道。"},{"i":18,"n":"第十八条","txt":"新建工程和建设项目，确实难以避开作战工程的，应当按照国家有关规定提出拆除或者迁建、改建作战工程的申请；申请未获批准，不得拆除或者迁建、改建作战工程。"},{"i":19,"n":"第十九条","txt":"本办法所称军用机场净空，是指为保证军用飞机（含直升机）起飞、着陆和复飞的安全，在飞行场地周围划定的限制物体高度的空间区域。"},{"i":20,"n":"第二十条","txt":"在军用机场净空保护区域内，禁止修建超出机场净空标准的建筑物、构筑物或者其他设施。"},{"i":21,"n":"第二十一条","txt":"在军用机场净空保护区域内种植植物，设置灯光或者物体，排放烟尘、粉尘、火焰、废气或者从事其他类似活动，不得影响飞行安全和机场助航设施的使用效能。"},{"i":22,"n":"第二十二条","txt":"军用机场管理单位应当了解当地城市规划和村庄、集镇规划和高大建筑项目建设计划，提供军用机场净空保护技术咨询。"},{"i":23,"n":"第二十三条","txt":"在军用机场净空保护区域内建设高大建筑物、构筑物或者其他设施的，建设单位必须在申请立项前书面征求军用机场管理单位的军级以上主管军事机关的意见；未征求军事机关意见或者建设项目设计高度超过军用机场净空保护标准的，国务院有关部门、地方人民政府有关部门不予办理建设许可手续。"},{"i":24,"n":"第二十四条","txt":"军用机场管理单位应当定期检查机场净空保护情况，发现擅自修建超过军用机场净空保护标准的建筑物、构筑物或者其他设施的，应当及时向上级和当地军事设施保护委员会报告。"},{"i":25,"n":"第二十五条","txt":"在军用机场侧净空保护区域内原有自然障碍物附近新建高大建筑物、构筑物或者其他设施，必须符合国家有关机场净空的规定。"},{"i":26,"n":"第二十六条","txt":"军民合用机场以及由军队管理的保留旧机场、公路飞行跑道的净空保护工作，适用军用机场净空保护的有关规定。"},{"i":27,"n":"第二十七条","txt":"军事设施保护法所称军用通信、输电线路包括："},{"i":28,"n":"第二十八条","txt":"军事设施保护法所称军用输油、输水管道，是指专供军队使用的地面或者地下、水下输油、输水管道和管道沿线的加压站、计量站、处理场、油库、阀室、标志物以及其他附属设施。"},{"i":29,"n":"第二十九条","txt":"军用通信、输电线路和军用输油、输水管道（以下简称军用管线）管理单位，应当加强维护管理工作，坚持巡查和测试检查制度；必要时，可以组织武装巡查，发现问题，及时处理。"},{"i":30,"n":"第三十条","txt":"地方各级人民政府和驻地军事机关，应当根据实际情况组织军用管线沿线群众实行军民联防护线，采取委托看管、分段负责等形式，保护军用管线的安全。"},{"i":31,"n":"第三十一条","txt":"地下军用管线应当设立路由标石或者永久性标志，易遭损坏的路段（部位）应当设置标志牌。水下军用管线应当在海图上标明。"},{"i":32,"n":"第三十二条","txt":"军用管线的具体保护要求以及军用管线与其他设施相互妨碍的处理，按照国务院、中央军事委员会的有关规定执行。"},{"i":33,"n":"第三十三条","txt":"本办法所称军用无线电固定设施电磁环境（以下简称军用电磁环境），是指为保证军用无线电收（发）信、侦察、测向、雷达、导航定位等固定设施正常工作，在其周围划定的限制电磁干扰信号和电磁障碍物体的区域。"},{"i":34,"n":"第三十四条","txt":"在军用电磁环境保护范围内，禁止建设、设置或者使用发射、辐射电磁信号的设备和电磁障碍物体。"},{"i":35,"n":"第三十五条","txt":"地方在军用电磁环境保护范围内安排建设项目，对军用电磁环境可能产生影响的，应当按照规定征求有关军事机关的意见；必要时，可以由军事设施管理单位和地方有关部门共同对其干扰程度和电磁障碍物的影响情况进行测试和论证。"},{"i":36,"n":"第三十六条","txt":"各级人民政府有关部门审批和验收军用电磁环境保护范围内的建设项目，应当审查发射、辐射电磁信号设备和电磁障碍物的状况，以及征求军事机关意见的情况；未征求军事机关意见或者不符合国家电磁环境保护标准的，不予办理建设或者使用许可手续。"},{"i":37,"n":"第三十七条","txt":"军用无线电固定设施管理单位，应当掌握军用电磁环境保护情况，发现问题及时向上级军事机关和当地军事设施保护委员会报告。"},{"i":38,"n":"第三十八条","txt":"本办法所称边防设施，是指边防巡逻路、边境铁丝网（铁栅栏）、边境监控设备、边境管理辅助标志以及边防直升机起降场、边防船艇停泊点等由边防部队使用、管理的军事设施。"},{"i":39,"n":"第三十九条","txt":"任何组织或者个人未经边防设施管理单位同意，不得擅自拆除或者移动边防设施。"},{"i":40,"n":"第四十条","txt":"边境地区开辟口岸、互市贸易区、旅游景点或者修建道路、管线、桥梁等项目涉及边防设施的，应当按照有关规定征求军事机关的意见；需要迁建、改建边防设施的，应当报有关省、自治区、直辖市军事设施保护委员会批准；迁建、改建的边防设施的位置、质量、标准必须符合国家有关规定。"},{"i":41,"n":"第四十一条","txt":"军用测量标志的保护，依照国家有关法律、法规的规定办理。"},{"i":42,"n":"第四十二条","txt":"军事设施管理单位执勤人员遇有军事设施保护法第三十条所列违法行为，可以采取下列强制措施，予以制止："},{"i":43,"n":"第四十三条","txt":"违反本办法第九条、第十条、第十一条的规定，在水域军事禁区、军事管理区内或者军民合用港口的水域建筑、设置非军事设施的，由城市规划、交通、渔业行政主管部门依据各自的职权责令停止兴建活动；已建成的，责令限期拆除。"},{"i":44,"n":"第四十四条","txt":"违反本办法第九条、第十条的规定，擅自进入水域军事禁区，在水域军事禁区内从事水产养殖、捕捞，或者在水域军事管理区内从事水产养殖的，由交通、渔业行政主管部门依据各自的职权给予警告，责令离开，可以没收渔具、渔获物。"},{"i":45,"n":"第四十五条","txt":"违反本办法第十六条的规定，在作战工程安全保护范围内开山采石、采矿、爆破、采伐林木的，由公安机关以及国土资源、林业行政主管部门依据各自的职权责令停止违法行为，没收采出的产品和违法所得；造成损失的，依法赔偿损失。"},{"i":46,"n":"第四十六条","txt":"违反本办法第十六条的规定，擅自在作战工程安全保护范围内修筑建筑物、构筑物、道路或者进行农田水利基本建设的，由城市规划、交通、农业行政主管部门依据各自的职权给予警告，责令限期改正；造成损失的，依法赔偿损失。"},{"i":47,"n":"第四十七条","txt":"违反本办法第十七条的规定，破坏作战工程封闭伪装，阻断作战工程通道，或者将作战工程用于堆物、种植、养殖的，由公安机关责令停止违法行为，限期恢复原状；造成损失的，依法赔偿损失。"},{"i":48,"n":"第四十八条","txt":"违反本办法第二十条、第二十五条的规定，在军用机场净空保护区域内修建超出军用机场净空保护标准的建筑物、构筑物或者其他设施的，由城市规划行政主管部门责令限期拆除超高部分。"},{"i":49,"n":"第四十九条","txt":"违反本办法第三十四条的规定，在军用电磁环境保护范围内建设、设置或者使用发射、辐射电磁信号的设备和电磁障碍物体的，由城市规划、信息产业行政主管部门依据各自的职权给予警告，责令限期改正；拒不改正的，查封干扰设备或者强制拆除障碍物。"},{"i":50,"n":"第五十条","txt":"违反本办法第十八条、第三十九条、第四十条的规定，擅自拆除、迁建、改建作战工程、边防设施或者擅自移动边防设施的，由城市规划行政主管部门责令停止违法行为，限期恢复原状；造成损失的，依法赔偿损失。"},{"i":51,"n":"第五十一条","txt":"违反本办法，构成违反治安管理行为的，由公安机关依法处罚；构成犯罪的，依法追究刑事责任。"},{"i":52,"n":"第五十二条","txt":"中国人民武装警察部队所属军事设施的保护，适用军事设施保护法和本办法。"},{"i":53,"n":"第五十三条","txt":"本办法自公布之日起施行。"}],"laodonghetongfashishitiaoli":[{"i":1,"n":"第一条","txt":"为了贯彻实施《中华人民共和国劳动合同法》（以下简称劳动合同法），制定本条例。"},{"i":2,"n":"第二条","txt":"各级人民政府和县级以上人民政府劳动行政等有关部门以及工会等组织，应当采取措施，推动劳动合同法的贯彻实施，促进劳动关系的和谐。"},{"i":3,"n":"第三条","txt":"依法成立的会计师事务所、律师事务所等合伙组织和基金会，属于劳动合同法规定的用人单位。"},{"i":4,"n":"第四条","txt":"劳动合同法规定的用人单位设立的分支机构，依法取得营业执照或者登记证书的，可以作为用人单位与劳动者订立劳动合同；未依法取得营业执照或者登记证书的，受用人单位委托可以与劳动者订立劳动合同。"},{"i":5,"n":"第五条","txt":"自用工之日起一个月内，经用人单位书面通知后，劳动者不与用人单位订立书面劳动合同的，用人单位应当书面通知劳动者终止劳动关系，无需向劳动者支付经济补偿，但是应当依法向劳动者支付其实际工作时间的劳动报酬。"},{"i":6,"n":"第六条","txt":"用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当依照劳动合同法第八十二条的规定向劳动者每月支付两倍的工资，并与劳动者补订书面劳动合同；劳动者不与用人单位订立书面劳动合同的，用人单位应当书面通知劳动者终止劳动关系，并依照劳动合同法第四十七条的规定支付经济补偿。"},{"i":7,"n":"第七条","txt":"用人单位自用工之日起满一年未与劳动者订立书面劳动合同的，自用工之日起满一个月的次日至满一年的前一日应当依照劳动合同法第八十二条的规定向劳动者每月支付两倍的工资，并视为自用工之日起满一年的当日已经与劳动者订立无固定期限劳动合同，应当立即与劳动者补订书面劳动合同。"},{"i":8,"n":"第八条","txt":"劳动合同法第七条规定的职工名册，应当包括劳动者姓名、性别、公民身份号码、户籍地址及现住址、联系方式、用工形式、用工起始时间、劳动合同期限等内容。"},{"i":9,"n":"第九条","txt":"劳动合同法第十四条第二款规定的连续工作满10年的起始时间，应当自用人单位用工之日起计算，包括劳动合同法施行前的工作年限。"},{"i":10,"n":"第十条","txt":"劳动者非因本人原因从原用人单位被安排到新用人单位工作的，劳动者在原用人单位的工作年限合并计算为新用人单位的工作年限。原用人单位已经向劳动者支付经济补偿的，新用人单位在依法解除、终止劳动合同计算支付经济补偿的工作年限时，不再计算劳动者在原用人单位的工作年限。"},{"i":11,"n":"第十一条","txt":"除劳动者与用人单位协商一致的情形外，劳动者依照劳动合同法第十四条第二款的规定，提出订立无固定期限劳动合同的，用人单位应当与其订立无固定期限劳动合同。对劳动合同的内容，双方应当按照合法、公平、平等自愿、协商一致、诚实信用的原则协商确定；对协商不一致的内容，依照劳动合同法第十八条的规定执行。"},{"i":12,"n":"第十二条","txt":"地方各级人民政府及县级以上地方人民政府有关部门为安置就业困难人员提供的给予岗位补贴和社会保险补贴的公益性岗位，其劳动合同不适用劳动合同法有关无固定期限劳动合同的规定以及支付经济补偿的规定。"},{"i":13,"n":"第十三条","txt":"用人单位与劳动者不得在劳动合同法第四十四条规定的劳动合同终止情形之外约定其他的劳动合同终止条件。"},{"i":14,"n":"第十四条","txt":"劳动合同履行地与用人单位注册地不一致的，有关劳动者的最低工资标准、劳动保护、劳动条件、职业危害防护和本地区上年度职工月平均工资标准等事项，按照劳动合同履行地的有关规定执行；用人单位注册地的有关标准高于劳动合同履行地的有关标准，且用人单位与劳动者约定按照用人单位注册地的有关规定执行的，从其约定。"},{"i":15,"n":"第十五条","txt":"劳动者在试用期的工资不得低于本单位相同岗位最低档工资的80%或者不得低于劳动合同约定工资的80%，并不得低于用人单位所在地的最低工资标准。"},{"i":16,"n":"第十六条","txt":"劳动合同法第二十二条第二款规定的培训费用，包括用人单位为了对劳动者进行专业技术培训而支付的有凭证的培训费用、培训期间的差旅费用以及因培训产生的用于该劳动者的其他直接费用。"},{"i":17,"n":"第十七条","txt":"劳动合同期满，但是用人单位与劳动者依照劳动合同法第二十二条的规定约定的服务期尚未到期的，劳动合同应当续延至服务期满；双方另有约定的，从其约定。"},{"i":18,"n":"第十八条","txt":"有下列情形之一的，依照劳动合同法规定的条件、程序，劳动者可以与用人单位解除固定期限劳动合同、无固定期限劳动合同或者以完成一定工作任务为期限的劳动合同："},{"i":19,"n":"第十九条","txt":"有下列情形之一的，依照劳动合同法规定的条件、程序，用人单位可以与劳动者解除固定期限劳动合同、无固定期限劳动合同或者以完成一定工作任务为期限的劳动合同："},{"i":20,"n":"第二十条","txt":"用人单位依照劳动合同法第四十条的规定，选择额外支付劳动者一个月工资解除劳动合同的，其额外支付的工资应当按照该劳动者上一个月的工资标准确定。"},{"i":21,"n":"第二十一条","txt":"劳动者达到法定退休年龄的，劳动合同终止。"},{"i":22,"n":"第二十二条","txt":"以完成一定工作任务为期限的劳动合同因任务完成而终止的，用人单位应当依照劳动合同法第四十七条的规定向劳动者支付经济补偿。"},{"i":23,"n":"第二十三条","txt":"用人单位依法终止工伤职工的劳动合同的，除依照劳动合同法第四十七条的规定支付经济补偿外，还应当依照国家有关工伤保险的规定支付一次性工伤医疗补助金和伤残就业补助金。"},{"i":24,"n":"第二十四条","txt":"用人单位出具的解除、终止劳动合同的证明，应当写明劳动合同期限、解除或者终止劳动合同的日期、工作岗位、在本单位的工作年限。"},{"i":25,"n":"第二十五条","txt":"用人单位违反劳动合同法的规定解除或者终止劳动合同，依照劳动合同法第八十七条的规定支付了赔偿金的，不再支付经济补偿。赔偿金的计算年限自用工之日起计算。"},{"i":26,"n":"第二十六条","txt":"用人单位与劳动者约定了服务期，劳动者依照劳动合同法第三十八条的规定解除劳动合同的，不属于违反服务期的约定，用人单位不得要求劳动者支付违约金。"},{"i":27,"n":"第二十七条","txt":"劳动合同法第四十七条规定的经济补偿的月工资按照劳动者应得工资计算，包括计时工资或者计件工资以及奖金、津贴和补贴等货币性收入。劳动者在劳动合同解除或者终止前12个月的平均工资低于当地最低工资标准的，按照当地最低工资标准计算。劳动者工作不满12个月的，按照实际工作的月数计算平均工资。"},{"i":28,"n":"第二十八条","txt":"用人单位或者其所属单位出资或者合伙设立的劳务派遣单位，向本单位或者所属单位派遣劳动者的，属于劳动合同法第六十七条规定的不得设立的劳务派遣单位。"},{"i":29,"n":"第二十九条","txt":"用工单位应当履行劳动合同法第六十二条规定的义务，维护被派遣劳动者的合法权益。"},{"i":30,"n":"第三十条","txt":"劳务派遣单位不得以非全日制用工形式招用被派遣劳动者。"},{"i":31,"n":"第三十一条","txt":"劳务派遣单位或者被派遣劳动者依法解除、终止劳动合同的经济补偿，依照劳动合同法第四十六条、第四十七条的规定执行。"},{"i":32,"n":"第三十二条","txt":"劳务派遣单位违法解除或者终止被派遣劳动者的劳动合同的，依照劳动合同法第四十八条的规定执行。"},{"i":33,"n":"第三十三条","txt":"用人单位违反劳动合同法有关建立职工名册规定的，由劳动行政部门责令限期改正；逾期不改正的，由劳动行政部门处2000元以上2万元以下的罚款。"},{"i":34,"n":"第三十四条","txt":"用人单位依照劳动合同法的规定应当向劳动者每月支付两倍的工资或者应当向劳动者支付赔偿金而未支付的，劳动行政部门应当责令用人单位支付。"},{"i":35,"n":"第三十五条","txt":"用工单位违反劳动合同法和本条例有关劳务派遣规定的，由劳动行政部门和其他有关主管部门责令改正；情节严重的，以每位被派遣劳动者1000元以上5000元以下的标准处以罚款；给被派遣劳动者造成损害的，劳务派遣单位和用工单位承担连带赔偿责任。"},{"i":36,"n":"第三十六条","txt":"对违反劳动合同法和本条例的行为的投诉、举报，县级以上地方人民政府劳动行政部门依照《劳动保障监察条例》的规定处理。"},{"i":37,"n":"第三十七条","txt":"劳动者与用人单位因订立、履行、变更、解除或者终止劳动合同发生争议的，依照《中华人民共和国劳动争议调解仲裁法》的规定处理。"},{"i":38,"n":"第三十八条","txt":"本条例自公布之日起施行。"}],"fanjiandiefashishixize":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国反间谍法》（以下简称《反间谍法》），制定本实施细则。"},{"i":2,"n":"第二条","txt":"国家安全机关负责本细则的实施。"},{"i":3,"n":"第三条","txt":"《反间谍法》所称“境外机构、组织”包括境外机构、组织在中华人民共和国境内设立的分支（代表）机构和分支组织；所称“境外个人”包括居住在中华人民共和国境内不具有中华人民共和国国籍的人。"},{"i":4,"n":"第四条","txt":"《反间谍法》所称“间谍组织代理人”，是指受间谍组织或者其成员的指使、委托、资助，进行或者授意、指使他人进行危害中华人民共和国国家安全活动的人。"},{"i":5,"n":"第五条","txt":"《反间谍法》所称“敌对组织”，是指敌视中华人民共和国人民民主专政的政权和社会主义制度，危害国家安全的组织。"},{"i":6,"n":"第六条","txt":"《反间谍法》所称“资助”实施危害中华人民共和国国家安全的间谍行为，是指境内外机构、组织、个人的下列行为："},{"i":7,"n":"第七条","txt":"《反间谍法》所称“勾结”实施危害中华人民共和国国家安全的间谍行为，是指境内外组织、个人的下列行为："},{"i":8,"n":"第八条","txt":"下列行为属于《反间谍法》第三十九条所称“间谍行为以外的其他危害国家安全行为”："},{"i":9,"n":"第九条","txt":"境外个人被认为入境后可能进行危害中华人民共和国国家安全活动的，国务院国家安全主管部门可以决定其在一定时期内不得入境。"},{"i":10,"n":"第十条","txt":"对背叛祖国、危害国家安全的犯罪嫌疑人，依据《反间谍法》第八条的规定，国家安全机关可以通缉、追捕。"},{"i":11,"n":"第十一条","txt":"国家安全机关依法执行反间谍工作任务时，有权向有关组织和人员调查询问有关情况。"},{"i":12,"n":"第十二条","txt":"国家安全机关工作人员依法执行反间谍工作任务时，对发现身份不明、有危害国家安全行为的嫌疑人员，可以检查其随带物品。"},{"i":13,"n":"第十三条","txt":"国家安全机关执行反间谍工作紧急任务的车辆，可以配置特别通行标志和警灯、警报器。"},{"i":14,"n":"第十四条","txt":"国家安全机关工作人员依法执行反间谍工作任务的行为，不受其他组织和个人的非法干涉。"},{"i":15,"n":"第十五条","txt":"机关、团体和其他组织对本单位的人员进行维护国家安全的教育，动员、组织本单位的人员防范、制止间谍行为的工作，应当接受国家安全机关的协调和指导。"},{"i":16,"n":"第十六条","txt":"下列情形属于《反间谍法》第七条所称“重大贡献”："},{"i":17,"n":"第十七条","txt":"《反间谍法》第二十四条所称“非法持有属于国家秘密的文件、资料和其他物品”是指："},{"i":18,"n":"第十八条","txt":"《反间谍法》第二十五条所称“专用间谍器材”，是指进行间谍活动特殊需要的下列器材："},{"i":19,"n":"第十九条","txt":"实施危害国家安全的行为，由有关部门依法予以处分，国家安全机关也可以予以警告；构成犯罪的，依法追究刑事责任。"},{"i":20,"n":"第二十条","txt":"下列情形属于《反间谍法》第二十七条所称“立功表现”："},{"i":21,"n":"第二十一条","txt":"有证据证明知道他人有间谍行为，或者经国家安全机关明确告知他人有危害国家安全的犯罪行为，在国家安全机关向其调查有关情况、收集有关证据时，拒绝提供的，依照《反间谍法》第二十九条的规定处理。"},{"i":22,"n":"第二十二条","txt":"国家安全机关依法执行反间谍工作任务时，公民和组织依法有义务提供便利条件或者其他协助，拒不提供或者拒不协助，构成故意阻碍国家安全机关依法执行反间谍工作任务的，依照《反间谍法》第三十条的规定处罚。"},{"i":23,"n":"第二十三条","txt":"故意阻碍国家安全机关依法执行反间谍工作任务，造成国家安全机关工作人员人身伤害或者财物损失的，应当依法承担赔偿责任，并由司法机关或者国家安全机关依照《反间谍法》第三十条的规定予以处罚。"},{"i":24,"n":"第二十四条","txt":"对涉嫌间谍行为的人员，国家安全机关可以决定其在一定期限内不得出境。对违反《反间谍法》的境外个人，国务院国家安全主管部门可以决定限期离境或者驱逐出境，并决定其不得入境的期限。被驱逐出境的境外个人，自被驱逐出境之日起10年内不得入境。"},{"i":25,"n":"第二十五条","txt":"国家安全机关、公安机关依照法律、行政法规和国家有关规定，履行防范、制止和惩治间谍行为以外的其他危害国家安全行为的职责，适用本细则的有关规定。"},{"i":26,"n":"第二十六条","txt":"本细则自公布之日起施行。1994年6月4日国务院发布的《中华人民共和国国家安全法实施细则》同时废止。"}],"taiwantongbaotouzibaohufashishixize":[{"i":1,"n":"第一条","txt":"为了保护和鼓励台湾同胞投资，促进海峡两岸的经济发展，实施《中华人民共和国台湾同胞投资保护法》，制定本实施细则。"},{"i":2,"n":"第二条","txt":"本实施细则所称台湾同胞投资是指台湾地区的公司、企业、其他经济组织或者个人作为投资者在其他省、自治区和直辖市（以下简称大陆）的投资。"},{"i":3,"n":"第三条","txt":"国家依法保护台湾同胞投资。"},{"i":4,"n":"第四条","txt":"国家依法鼓励台湾同胞投资。"},{"i":5,"n":"第五条","txt":"台湾同胞投资适用《中华人民共和国台湾同胞投资保护法》和本实施细则；《中华人民共和国台湾同胞投资保护法》和本实施细则未规定的，比照适用国家有关涉外经济法律、行政法规。"},{"i":6,"n":"第六条","txt":"台湾同胞投资，应当与国家国民经济和社会发展规划相适应，符合国家产业政策和投资导向的要求，比照适用国家关于指导外商投资方向的规定。"},{"i":7,"n":"第七条","txt":"台湾同胞投资者可以用可自由兑换货币、机器设备或者其他实物、工业产权、非专利技术等作为投资。"},{"i":8,"n":"第八条","txt":"台湾同胞投资，可以依法采用下列投资形式："},{"i":9,"n":"第九条","txt":"台湾同胞投资者进行投资，需要审批的，依照国家有关法律、行政法规规定的程序办理审批手续。"},{"i":10,"n":"第十条","txt":"审批机关审批台湾同胞投资，应当提高办事效率，减少管理层次，简化审批程序，做到管理制度统一、公开、透明。"},{"i":11,"n":"第十一条","txt":"台湾同胞投资企业依照国家有关法律、行政法规的规定，享受税收优惠待遇。"},{"i":12,"n":"第十二条","txt":"投资于大陆中西部地区的台湾同胞投资项目，可以按照国家有关规定给予鼓励或者适当放宽限制。"},{"i":13,"n":"第十三条","txt":"台湾同胞投资企业符合贷款原则的，可以按照国家有关规定给予必要的信贷支持。"},{"i":14,"n":"第十四条","txt":"台湾同胞投资者个人及其随行家属和台湾同胞投资企业中的台湾同胞职工及其随行家属，可以依照国家有关法律、行政法规的规定，向公安机关申请办理一定期限多次入出境手续和相应期限的暂住手续。台湾同胞投资企业中的外籍职工的入出境和暂住手续，依照国家有关法律、行政法规的规定办理。"},{"i":15,"n":"第十五条","txt":"台湾同胞投资者个人的子女和台湾同胞投资企业中的台湾同胞职工的子女，可以按照国家有关规定进入大陆的小学、中学和高等学校接受教育。"},{"i":16,"n":"第十六条","txt":"台湾同胞投资企业依法享有经营管理的自主权。"},{"i":17,"n":"第十七条","txt":"台湾同胞投资企业在购买机器设备、原材料及辅料等物资以及获得水、电、热、货物运输、劳务、广告、通信等服务方面，享有与大陆其他同类企业同等的待遇。"},{"i":18,"n":"第十八条","txt":"台湾同胞投资者投资的财产、工业产权、投资收益和其他合法权益，可以依法转让和继承。"},{"i":19,"n":"第十九条","txt":"台湾同胞投资者依法获得的投资收益、其他合法收入和清算后的资金，可以依法汇回台湾或者汇往境外。"},{"i":20,"n":"第二十条","txt":"台湾同胞投资者可以委托亲友或者他人作为其投资的代理人，代理人应当持有具有法律效力的授权委托书。"},{"i":21,"n":"第二十一条","txt":"国家机关对台湾同胞投资企业收费的项目和标准，应当与大陆其他同类企业相同。任何机关或者单位不得对台湾同胞投资企业另立收费项目或者提高收费标准。"},{"i":22,"n":"第二十二条","txt":"国家对台湾同胞投资者的投资不实行国有化和征收；在特殊情况下，根据社会公共利益的需要，对台湾同胞投资者的投资可以依照法律程序实行征收，并给予相应的补偿。补偿相当于该投资在征收决定前一刻的价值，包括从征收之日起至支付之日止按合理利率计算的利息，并可以依法兑换外汇、汇回台湾或者汇往境外。"},{"i":23,"n":"第二十三条","txt":"国家依法保护台湾同胞投资者个人及其随行家属和台湾同胞投资企业中的台湾同胞职工及其随行家属的人身自由和人身安全。除依照国家有关法律规定办理的外，不得对台湾同胞采取限制人身自由的强制措施。"},{"i":24,"n":"第二十四条","txt":"在台湾同胞投资企业集中的地区，可以依法成立台湾同胞投资企业协会。"},{"i":25,"n":"第二十五条","txt":"各级人民政府应当对台湾同胞投资提供优质、规范、方便的服务。各级人民政府台湾事务办事机构应当做好台湾同胞投资的法律宣传与咨询、投诉受理和纠纷解决等工作。"},{"i":26,"n":"第二十六条","txt":"台湾同胞投资者、台湾同胞投资企业、台湾同胞投资企业协会认为行政机关或者行政机关工作人员的具体行政行为侵犯其合法权益的，可以依照国家有关法律、行政法规的规定，申请行政复议或者提起行政诉讼。"},{"i":27,"n":"第二十七条","txt":"台湾同胞投资者与大陆的公司、企业、其他经济组织或者个人之间发生的与投资有关的争议，当事人可以通过协商或者调解解决。"},{"i":28,"n":"第二十八条","txt":"台湾同胞以其设在其他国家或者地区的公司、企业或者其他经济组织作为投资者在大陆投资的，可以比照适用本实施细则。"},{"i":29,"n":"第二十九条","txt":"本实施细则自发布之日起施行。"}],"shangbiaofashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国商标法》（以下简称商标法），制定本条例。"},{"i":2,"n":"第二条","txt":"本条例有关商品商标的规定，适用于服务商标。"},{"i":3,"n":"第三条","txt":"商标持有人依照商标法第十三条规定请求驰名商标保护的，应当提交其商标构成驰名商标的证据材料。商标局、商标评审委员会应当依照商标法第十四条的规定，根据审查、处理案件的需要以及当事人提交的证据材料，对其商标驰名情况作出认定。"},{"i":4,"n":"第四条","txt":"商标法第十六条规定的地理标志，可以依照商标法和本条例的规定，作为证明商标或者集体商标申请注册。"},{"i":5,"n":"第五条","txt":"当事人委托商标代理机构申请商标注册或者办理其他商标事宜，应当提交代理委托书。代理委托书应当载明代理内容及权限；外国人或者外国企业的代理委托书还应当载明委托人的国籍。"},{"i":6,"n":"第六条","txt":"申请商标注册或者办理其他商标事宜，应当使用中文。"},{"i":7,"n":"第七条","txt":"商标局、商标评审委员会工作人员有下列情形之一的，应当回避，当事人或者利害关系人可以要求其回避："},{"i":8,"n":"第八条","txt":"以商标法第二十二条规定的数据电文方式提交商标注册申请等有关文件，应当按照商标局或者商标评审委员会的规定通过互联网提交。"},{"i":9,"n":"第九条","txt":"除本条例第十八条规定的情形外，当事人向商标局或者商标评审委员会提交文件或者材料的日期，直接递交的，以递交日为准；邮寄的，以寄出的邮戳日为准；邮戳日不清晰或者没有邮戳的，以商标局或者商标评审委员会实际收到日为准，但是当事人能够提出实际邮戳日证据的除外。通过邮政企业以外的快递企业递交的，以快递企业收寄日为准；收寄日不明确的，以商标局或者商标评审委员会实际收到日为准，但是当事人能够提出实际收寄日证据的除外。以数据电文方式提交的，以进入商标局或者商标评审委员会电子系统的日期为准。"},{"i":10,"n":"第十条","txt":"商标局或者商标评审委员会的各种文件，可以通过邮寄、直接递交、数据电文或者其他方式送达当事人；以数据电文方式送达当事人的，应当经当事人同意。当事人委托商标代理机构的，文件送达商标代理机构视为送达当事人。"},{"i":11,"n":"第十一条","txt":"下列期间不计入商标审查、审理期限："},{"i":12,"n":"第十二条","txt":"除本条第二款规定的情形外，商标法和本条例规定的各种期限开始的当日不计算在期限内。期限以年或者月计算的，以期限最后一月的相应日为期限届满日；该月无相应日的，以该月最后一日为期限届满日；期限届满日是节假日的，以节假日后的第一个工作日为期限届满日。"},{"i":13,"n":"第十三条","txt":"申请商标注册，应当按照公布的商品和服务分类表填报。每一件商标注册申请应当向商标局提交《商标注册申请书》1份、商标图样1份；以颜色组合或者着色图样申请商标注册的，应当提交着色图样，并提交黑白稿1份；不指定颜色的，应当提交黑白图样。"},{"i":14,"n":"第十四条","txt":"申请商标注册的，申请人应当提交其身份证明文件。商标注册申请人的名义与所提交的证明文件应当一致。"},{"i":15,"n":"第十五条","txt":"商品或者服务项目名称应当按照商品和服务分类表中的类别号、名称填写；商品或者服务项目名称未列入商品和服务分类表的，应当附送对该商品或者服务的说明。"},{"i":16,"n":"第十六条","txt":"共同申请注册同一商标或者办理其他共有商标事宜的，应当在申请书中指定一个代表人；没有指定代表人的，以申请书中顺序排列的第一人为代表人。"},{"i":17,"n":"第十七条","txt":"申请人变更其名义、地址、代理人、文件接收人或者删减指定的商品的，应当向商标局办理变更手续。"},{"i":18,"n":"第十八条","txt":"商标注册的申请日期以商标局收到申请文件的日期为准。"},{"i":19,"n":"第十九条","txt":"两个或者两个以上的申请人，在同一种商品或者类似商品上，分别以相同或者近似的商标在同一天申请注册的，各申请人应当自收到商标局通知之日起30日内提交其申请注册前在先使用该商标的证据。同日使用或者均未使用的，各申请人可以自收到商标局通知之日起30日内自行协商，并将书面协议报送商标局；不愿协商或者协商不成的，商标局通知各申请人以抽签的方式确定一个申请人，驳回其他人的注册申请。商标局已经通知但申请人未参加抽签的，视为放弃申请，商标局应当书面通知未参加抽签的申请人。"},{"i":20,"n":"第二十条","txt":"依照商标法第二十五条规定要求优先权的，申请人提交的第一次提出商标注册申请文件的副本应当经受理该申请的商标主管机关证明，并注明申请日期和申请号。"},{"i":21,"n":"第二十一条","txt":"商标局对受理的商标注册申请，依照商标法及本条例的有关规定进行审查，对符合规定或者在部分指定商品上使用商标的注册申请符合规定的，予以初步审定，并予以公告；对不符合规定或者在部分指定商品上使用商标的注册申请不符合规定的，予以驳回或者驳回在部分指定商品上使用商标的注册申请，书面通知申请人并说明理由。"},{"i":22,"n":"第二十二条","txt":"商标局对一件商标注册申请在部分指定商品上予以驳回的，申请人可以将该申请中初步审定的部分申请分割成另一件申请，分割后的申请保留原申请的申请日期。"},{"i":23,"n":"第二十三条","txt":"依照商标法第二十九条规定，商标局认为对商标注册申请内容需要说明或者修正的，申请人应当自收到商标局通知之日起15日内作出说明或者修正。"},{"i":24,"n":"第二十四条","txt":"对商标局初步审定予以公告的商标提出异议的，异议人应当向商标局提交下列商标异议材料一式两份并标明正、副本："},{"i":25,"n":"第二十五条","txt":"商标局收到商标异议申请书后，经审查，符合受理条件的，予以受理，向申请人发出受理通知书。"},{"i":26,"n":"第二十六条","txt":"商标异议申请有下列情形的，商标局不予受理，书面通知申请人并说明理由："},{"i":27,"n":"第二十七条","txt":"商标局应当将商标异议材料副本及时送交被异议人，限其自收到商标异议材料副本之日起30日内答辩。被异议人不答辩的，不影响商标局作出决定。"},{"i":28,"n":"第二十八条","txt":"商标法第三十五条第三款和第三十六条第一款所称不予注册决定，包括在部分指定商品上不予注册决定。"},{"i":29,"n":"第二十九条","txt":"商标注册申请人或者商标注册人依照商标法第三十八条规定提出更正申请的，应当向商标局提交更正申请书。符合更正条件的，商标局核准后更正相关内容；不符合更正条件的，商标局不予核准，书面通知申请人并说明理由。"},{"i":30,"n":"第三十条","txt":"变更商标注册人名义、地址或者其他注册事项的，应当向商标局提交变更申请书。变更商标注册人名义的，还应当提交有关登记机关出具的变更证明文件。商标局核准的，发给商标注册人相应证明，并予以公告；不予核准的，应当书面通知申请人并说明理由。"},{"i":31,"n":"第三十一条","txt":"转让注册商标的，转让人和受让人应当向商标局提交转让注册商标申请书。转让注册商标申请手续应当由转让人和受让人共同办理。商标局核准转让注册商标申请的，发给受让人相应证明，并予以公告。"},{"i":32,"n":"第三十二条","txt":"注册商标专用权因转让以外的继承等其他事由发生移转的，接受该注册商标专用权的当事人应当凭有关证明文件或者法律文书到商标局办理注册商标专用权移转手续。"},{"i":33,"n":"第三十三条","txt":"注册商标需要续展注册的，应当向商标局提交商标续展注册申请书。商标局核准商标注册续展申请的，发给相应证明并予以公告。"},{"i":34,"n":"第三十四条","txt":"商标法第二十一条规定的商标国际注册，是指根据《商标国际注册马德里协定》（以下简称马德里协定）、《商标国际注册马德里协定有关议定书》（以下简称马德里议定书）及《商标国际注册马德里协定及该协定有关议定书的共同实施细则》的规定办理的马德里商标国际注册。"},{"i":35,"n":"第三十五条","txt":"以中国为原属国申请商标国际注册的，应当在中国设有真实有效的营业所，或者在中国有住所，或者拥有中国国籍。"},{"i":36,"n":"第三十六条","txt":"符合本条例第三十五条规定的申请人，其商标已在商标局获得注册的，可以根据马德里协定申请办理该商标的国际注册。"},{"i":37,"n":"第三十七条","txt":"以中国为原属国申请商标国际注册的，应当通过商标局向世界知识产权组织国际局（以下简称国际局）申请办理。"},{"i":38,"n":"第三十八条","txt":"通过商标局向国际局申请商标国际注册及办理其他有关申请的，应当提交符合国际局和商标局要求的申请书和相关材料。"},{"i":39,"n":"第三十九条","txt":"商标国际注册申请指定的商品或者服务不得超出国内基础申请或者基础注册的商品或者服务的范围。"},{"i":40,"n":"第四十条","txt":"商标国际注册申请手续不齐备或者未按照规定填写申请书的，商标局不予受理，申请日不予保留。"},{"i":41,"n":"第四十一条","txt":"通过商标局向国际局申请商标国际注册及办理其他有关申请的，应当按照规定缴纳费用。"},{"i":42,"n":"第四十二条","txt":"商标局在马德里协定或者马德里议定书规定的驳回期限（以下简称驳回期限）内，依照商标法和本条例的有关规定对指定中国的领土延伸申请进行审查，作出决定，并通知国际局。商标局在驳回期限内未发出驳回或者部分驳回通知的，该领土延伸申请视为核准。"},{"i":43,"n":"第四十三条","txt":"指定中国的领土延伸申请人，要求将三维标志、颜色组合、声音标志作为商标保护或者要求保护集体商标、证明商标的，自该商标在国际局国际注册簿登记之日起3个月内，应当通过依法设立的商标代理机构，向商标局提交本条例第十三条规定的相关材料。未在上述期限内提交相关材料的，商标局驳回该领土延伸申请。"},{"i":44,"n":"第四十四条","txt":"世界知识产权组织对商标国际注册有关事项进行公告，商标局不再另行公告。"},{"i":45,"n":"第四十五条","txt":"对指定中国的领土延伸申请，自世界知识产权组织《国际商标公告》出版的次月1日起3个月内，符合商标法第三十三条规定条件的异议人可以向商标局提出异议申请。"},{"i":46,"n":"第四十六条","txt":"在中国获得保护的国际注册商标，有效期自国际注册日或者后期指定日起算。在有效期届满前，注册人可以向国际局申请续展，在有效期内未申请续展的，可以给予6个月的宽展期。商标局收到国际局的续展通知后，依法进行审查。国际局通知未续展的，注销该国际注册商标。"},{"i":47,"n":"第四十七条","txt":"指定中国的领土延伸申请办理转让的，受让人应当在缔约方境内有真实有效的营业所，或者在缔约方境内有住所，或者是缔约方国民。"},{"i":48,"n":"第四十八条","txt":"指定中国的领土延伸申请办理删减，删减后的商品或者服务不符合中国有关商品或者服务分类要求或者超出原指定商品或者服务范围的，商标局作出该删减在中国无效的决定，并向国际局作出声明。"},{"i":49,"n":"第四十九条","txt":"依照商标法第四十九条第二款规定申请撤销国际注册商标，应当自该商标国际注册申请的驳回期限届满之日起满3年后向商标局提出申请；驳回期限届满时仍处在驳回复审或者异议相关程序的，应当自商标局或者商标评审委员会作出的准予注册决定生效之日起满3年后向商标局提出申请。"},{"i":50,"n":"第五十条","txt":"商标法和本条例下列条款的规定不适用于办理商标国际注册相关事宜："},{"i":51,"n":"第五十一条","txt":"商标评审是指商标评审委员会依照商标法第三十四条、第三十五条、第四十四条、第四十五条、第五十四条的规定审理有关商标争议事宜。当事人向商标评审委员会提出商标评审申请，应当有明确的请求、事实、理由和法律依据，并提供相应证据。"},{"i":52,"n":"第五十二条","txt":"商标评审委员会审理不服商标局驳回商标注册申请决定的复审案件，应当针对商标局的驳回决定和申请人申请复审的事实、理由、请求及评审时的事实状态进行审理。"},{"i":53,"n":"第五十三条","txt":"商标评审委员会审理不服商标局不予注册决定的复审案件，应当针对商标局的不予注册决定和申请人申请复审的事实、理由、请求及原异议人提出的意见进行审理。"},{"i":54,"n":"第五十四条","txt":"商标评审委员会审理依照商标法第四十四条、第四十五条规定请求宣告注册商标无效的案件，应当针对当事人申请和答辩的事实、理由及请求进行审理。"},{"i":55,"n":"第五十五条","txt":"商标评审委员会审理不服商标局依照商标法第四十四条第一款规定作出宣告注册商标无效决定的复审案件，应当针对商标局的决定和申请人申请复审的事实、理由及请求进行审理。"},{"i":56,"n":"第五十六条","txt":"商标评审委员会审理不服商标局依照商标法第四十九条规定作出撤销或者维持注册商标决定的复审案件，应当针对商标局作出撤销或者维持注册商标决定和当事人申请复审时所依据的事实、理由及请求进行审理。"},{"i":57,"n":"第五十七条","txt":"申请商标评审，应当向商标评审委员会提交申请书，并按照对方当事人的数量提交相应份数的副本；基于商标局的决定书申请复审的，还应当同时附送商标局的决定书副本。"},{"i":58,"n":"第五十八条","txt":"商标评审委员会受理商标评审申请后应当及时将申请书副本送交对方当事人，限其自收到申请书副本之日起30日内答辩；期满未答辩的，不影响商标评审委员会的评审。"},{"i":59,"n":"第五十九条","txt":"当事人需要在提出评审申请或者答辩后补充有关证据材料的，应当在申请书或者答辩书中声明，并自提交申请书或者答辩书之日起3个月内提交；期满未提交的，视为放弃补充有关证据材料。但是，在期满后生成或者当事人有其他正当理由未能在期满前提交的证据，在期满后提交的，商标评审委员会将证据交对方当事人并质证后可以采信。"},{"i":60,"n":"第六十条","txt":"商标评审委员会根据当事人的请求或者实际需要，可以决定对评审申请进行口头审理。"},{"i":61,"n":"第六十一条","txt":"申请人在商标评审委员会作出决定、裁定前，可以书面向商标评审委员会要求撤回申请并说明理由，商标评审委员会认为可以撤回的，评审程序终止。"},{"i":62,"n":"第六十二条","txt":"申请人撤回商标评审申请的，不得以相同的事实和理由再次提出评审申请。商标评审委员会对商标评审申请已经作出裁定或者决定的，任何人不得以相同的事实和理由再次提出评审申请。但是，经不予注册复审程序予以核准注册后向商标评审委员会提起宣告注册商标无效的除外。"},{"i":63,"n":"第六十三条","txt":"使用注册商标，可以在商品、商品包装、说明书或者其他附着物上标明“注册商标”或者注册标记。"},{"i":64,"n":"第六十四条","txt":"《商标注册证》遗失或者破损的，应当向商标局提交补发《商标注册证》申请书。《商标注册证》遗失的，应当在《商标公告》上刊登遗失声明。破损的《商标注册证》，应当在提交补发申请时交回商标局。"},{"i":65,"n":"第六十五条","txt":"有商标法第四十九条规定的注册商标成为其核定使用的商品通用名称情形的，任何单位或者个人可以向商标局申请撤销该注册商标，提交申请时应当附送证据材料。商标局受理后应当通知商标注册人，限其自收到通知之日起2个月内答辩；期满未答辩的，不影响商标局作出决定。"},{"i":66,"n":"第六十六条","txt":"有商标法第四十九条规定的注册商标无正当理由连续3年不使用情形的，任何单位或者个人可以向商标局申请撤销该注册商标，提交申请时应当说明有关情况。商标局受理后应当通知商标注册人，限其自收到通知之日起2个月内提交该商标在撤销申请提出前使用的证据材料或者说明不使用的正当理由；期满未提供使用的证据材料或者证据材料无效并没有正当理由的，由商标局撤销其注册商标。"},{"i":67,"n":"第六十七条","txt":"下列情形属于商标法第四十九条规定的正当理由："},{"i":68,"n":"第六十八条","txt":"商标局、商标评审委员会撤销注册商标或者宣告注册商标无效，撤销或者宣告无效的理由仅及于部分指定商品的，对在该部分指定商品上使用的商标注册予以撤销或者宣告无效。"},{"i":69,"n":"第六十九条","txt":"许可他人使用其注册商标的，许可人应当在许可合同有效期内向商标局备案并报送备案材料。备案材料应当说明注册商标使用许可人、被许可人、许可期限、许可使用的商品或者服务范围等事项。"},{"i":70,"n":"第七十条","txt":"以注册商标专用权出质的，出质人与质权人应当签订书面质权合同，并共同向商标局提出质权登记申请，由商标局公告。"},{"i":71,"n":"第七十一条","txt":"违反商标法第四十三条第二款规定的，由工商行政管理部门责令限期改正；逾期不改正的，责令停止销售，拒不停止销售的，处10万元以下的罚款。"},{"i":72,"n":"第七十二条","txt":"商标持有人依照商标法第十三条规定请求驰名商标保护的，可以向工商行政管理部门提出请求。经商标局依照商标法第十四条规定认定为驰名商标的，由工商行政管理部门责令停止违反商标法第十三条规定使用商标的行为，收缴、销毁违法使用的商标标识；商标标识与商品难以分离的，一并收缴、销毁。"},{"i":73,"n":"第七十三条","txt":"商标注册人申请注销其注册商标或者注销其商标在部分指定商品上的注册的，应当向商标局提交商标注销申请书，并交回原《商标注册证》。"},{"i":74,"n":"第七十四条","txt":"注册商标被撤销或者依照本条例第七十三条的规定被注销的，原《商标注册证》作废，并予以公告；撤销该商标在部分指定商品上的注册的，或者商标注册人申请注销其商标在部分指定商品上的注册的，重新核发《商标注册证》，并予以公告。"},{"i":75,"n":"第七十五条","txt":"为侵犯他人商标专用权提供仓储、运输、邮寄、印制、隐匿、经营场所、网络商品交易平台等，属于商标法第五十七条第六项规定的提供便利条件。"},{"i":76,"n":"第七十六条","txt":"在同一种商品或者类似商品上将与他人注册商标相同或者近似的标志作为商品名称或者商品装潢使用，误导公众的，属于商标法第五十七条第二项规定的侵犯注册商标专用权的行为。"},{"i":77,"n":"第七十七条","txt":"对侵犯注册商标专用权的行为，任何人可以向工商行政管理部门投诉或者举报。"},{"i":78,"n":"第七十八条","txt":"计算商标法第六十条规定的违法经营额，可以考虑下列因素："},{"i":79,"n":"第七十九条","txt":"下列情形属于商标法第六十条规定的能证明该商品是自己合法取得的情形："},{"i":80,"n":"第八十条","txt":"销售不知道是侵犯注册商标专用权的商品，能证明该商品是自己合法取得并说明提供者的，由工商行政管理部门责令停止销售，并将案件情况通报侵权商品提供者所在地工商行政管理部门。"},{"i":81,"n":"第八十一条","txt":"涉案注册商标权属正在商标局、商标评审委员会审理或者人民法院诉讼中，案件结果可能影响案件定性的，属于商标法第六十二条第三款规定的商标权属存在争议。"},{"i":82,"n":"第八十二条","txt":"在查处商标侵权案件过程中，工商行政管理部门可以要求权利人对涉案商品是否为权利人生产或者其许可生产的产品进行辨认。"},{"i":83,"n":"第八十三条","txt":"商标法所称商标代理，是指接受委托人的委托，以委托人的名义办理商标注册申请、商标评审或者其他商标事宜。"},{"i":84,"n":"第八十四条","txt":"商标法所称商标代理机构，包括经工商行政管理部门登记从事商标代理业务的服务机构和从事商标代理业务的律师事务所。"},{"i":85,"n":"第八十五条","txt":"商标法所称商标代理从业人员，是指在商标代理机构中从事商标代理业务的工作人员。"},{"i":86,"n":"第八十六条","txt":"商标代理机构向商标局、商标评审委员会提交的有关申请文件，应当加盖该代理机构公章并由相关商标代理从业人员签字。"},{"i":87,"n":"第八十七条","txt":"商标代理机构申请注册或者受让其代理服务以外的其他商标，商标局不予受理。"},{"i":88,"n":"第八十八条","txt":"下列行为属于商标法第六十八条第一款第二项规定的以其他不正当手段扰乱商标代理市场秩序的行为："},{"i":89,"n":"第八十九条","txt":"商标代理机构有商标法第六十八条规定行为的，由行为人所在地或者违法行为发生地县级以上工商行政管理部门进行查处并将查处情况通报商标局。"},{"i":90,"n":"第九十条","txt":"商标局、商标评审委员会依照商标法第六十八条规定停止受理商标代理机构办理商标代理业务的，可以作出停止受理该商标代理机构商标代理业务6个月以上直至永久停止受理的决定。停止受理商标代理业务的期间届满，商标局、商标评审委员会应当恢复受理。"},{"i":91,"n":"第九十一条","txt":"工商行政管理部门应当加强对商标代理行业组织的监督和指导。"},{"i":92,"n":"第九十二条","txt":"连续使用至1993年7月1日的服务商标，与他人在相同或者类似的服务上已注册的服务商标相同或者近似的，可以继续使用；但是，1993年7月1日后中断使用3年以上的，不得继续使用。"},{"i":93,"n":"第九十三条","txt":"商标注册用商品和服务分类表，由商标局制定并公布。"},{"i":94,"n":"第九十四条","txt":"商标局设置《商标注册簿》，记载注册商标及有关注册事项。"},{"i":95,"n":"第九十五条","txt":"《商标注册证》及相关证明是权利人享有注册商标专用权的凭证。《商标注册证》记载的注册事项，应当与《商标注册簿》一致；记载不一致的，除有证据证明《商标注册簿》确有错误外，以《商标注册簿》为准。"},{"i":96,"n":"第九十六条","txt":"商标局发布《商标公告》，刊发商标注册及其他有关事项。"},{"i":97,"n":"第九十七条","txt":"申请商标注册或者办理其他商标事宜，应当缴纳费用。缴纳费用的项目和标准，由国务院财政部门、国务院价格主管部门分别制定。"},{"i":98,"n":"第九十八条","txt":"本条例自2014年5月1日起施行。"}],"guojingweishengjianyifashishixize":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国国境卫生检疫法》（以下称《国境卫生检疫法》）的规定，制定本细则。"},{"i":2,"n":"第二条","txt":"《国境卫生检疫法》和本细则所称："},{"i":3,"n":"第三条","txt":"卫生检疫机关在国境口岸工作的范围，是指为国境口岸服务的涉外宾馆、饭店、俱乐部，为入境、出境交通工具提供饮食、服务的单位和对入境、出境人员、交通工具、集装箱和货物实施检疫、监测、卫生监督的场所。"},{"i":4,"n":"第四条","txt":"入境、出境的人员、交通工具和集装箱，以及可能传播检疫传染病的行李、货物、邮包等，均应当按照本细则的规定接受检疫，经卫生检疫机关许可，方准入境或者出境。"},{"i":5,"n":"第五条","txt":"卫生检疫机关发现染疫人时，应当立即将其隔离，防止任何人遭受感染，并按照本细则第八章的规定处理。"},{"i":6,"n":"第六条","txt":"卫生检疫机关应当阻止染疫人、染疫嫌疑人出境，但是对来自国外并且在到达时受就地诊验的人，本人要求出境的，可以准许出境；如果乘交通工具出境，检疫医师应当将这种情况在出境检疫证上签注，同时通知交通工具负责人采取必要的预防措施。"},{"i":7,"n":"第七条","txt":"在国境口岸以及停留在该场所的入境、出境交通工具上，所有非因意外伤害而死亡并死因不明的尸体，必须经卫生检疫机关查验，并签发尸体移运许可证后，方准移运。"},{"i":8,"n":"第八条","txt":"来自国内疫区的交通工具，或者在国内航行中发现检疫传染病、疑似检疫传染病，或者有人非因意外伤害而死亡并死因不明的，交通工具负责人应当向到达的国境口岸卫生检疫机关报告，接受临时检疫。"},{"i":9,"n":"第九条","txt":"在国内或者国外检疫传染病大流行的时候，国务院卫生行政部门应当立即报请国务院决定采取下列检疫措施的一部或者全部："},{"i":10,"n":"第十条","txt":"入境、出境的集装箱、货物、废旧物等物品在到达口岸的时候，承运人、代理人或者货主，必须向卫生检疫机关申报并接受卫生检疫。对来自疫区的、被传染病污染的以及可能传播检疫传染病或者发现与人类健康有关的啮齿动物和病媒昆虫的集装箱、货物、废旧物等物品，应当实施消毒、除鼠、除虫或者其他必要的卫生处理。"},{"i":11,"n":"第十一条","txt":"入境、出境的微生物、人体组织、生物制品、血液及其制品等特殊物品的携带人、托运人或者邮递人，必须向卫生检疫机关申报并接受卫生检疫，凭卫生检疫机关签发的特殊物品审批单办理通关手续。未经卫生检疫机关许可，不准入境、出境。"},{"i":12,"n":"第十二条","txt":"入境、出境的旅客、员工个人携带或者托运可能传播传染病的行李和物品，应当接受卫生检查。卫生检疫机关对来自疫区或者被传染病污染的各种食品、饮料、水产品等应当实施卫生处理或者销毁，并签发卫生处理证明。"},{"i":13,"n":"第十三条","txt":"卫生检疫机关对应当实施卫生检疫的邮包进行卫生检查和必要的卫生处理时，邮政部门应予配合。未经卫生检疫机关许可，邮政部门不得运递。"},{"i":14,"n":"第十四条","txt":"卫生检疫单、证的种类、式样和签发办法，由海关总署规定。"},{"i":15,"n":"第十五条","txt":"在国境口岸以及停留在国境口岸的交通工具上，发现检疫传染病、疑似检疫传染病，或者有人非因意外伤害而死亡并死因不明时，国境口岸有关单位以及交通工具的负责人，应当立即向卫生检疫机关报告。"},{"i":16,"n":"第十六条","txt":"卫生检疫机关发现检疫传染病、监测传染病、疑似检疫传染病时，应当向当地卫生行政部门和卫生防疫机构通报；发现检疫传染病时，还应当用最快的办法向国务院卫生行政部门报告。"},{"i":17,"n":"第十七条","txt":"在国内或者国外某一地区发生检疫传染病流行时，国务院卫生行政部门可以宣布该地区为疫区。"},{"i":18,"n":"第十八条","txt":"卫生检疫机关根据工作需要，可以设立派出机构。卫生检疫机关的设立、合并或者撤销，按照有关规定执行。"},{"i":19,"n":"第十九条","txt":"卫生检疫机关的职责："},{"i":20,"n":"第二十条","txt":"国境口岸卫生监督员的职责："},{"i":21,"n":"第二十一条","txt":"卫生检疫机关工作人员、国境口岸卫生监督员在执行任务时，应当穿着检疫制服，佩戴检疫标志；卫生检疫机关的交通工具在执行任务期间，应当悬挂检疫旗帜。"},{"i":22,"n":"第二十二条","txt":"船舶的入境检疫，必须在港口的检疫锚地或者经卫生检疫机关同意的指定地点实施。"},{"i":23,"n":"第二十三条","txt":"船舶代理应当在受入境检疫的船舶到达以前，尽早向卫生检疫机关通知下列事项："},{"i":24,"n":"第二十四条","txt":"受入境检疫的船舶，在航行中，发现检疫传染病、疑似检疫传染病，或者有人非因意外伤害而死亡并死因不明的，船长必须立即向实施检疫港口的卫生检疫机关报告下列事项："},{"i":25,"n":"第二十五条","txt":"受入境检疫的船舶，必须按照下列规定悬挂检疫信号等候查验，在卫生检疫机关发给入境检疫证前，不得降下检疫信号。"},{"i":26,"n":"第二十六条","txt":"悬挂检疫信号的船舶，除引航员和经卫生检疫机关许可的人员外，其他人员不准上船，不准装卸行李、货物、邮包等物品，其他船舶不准靠近；船上的人员，除因船舶遇险外，未经卫生检疫机关许可，不准离船；引航员不得将船引离检疫锚地。"},{"i":27,"n":"第二十七条","txt":"申请电讯检疫的船舶，首先向卫生检疫机关申请卫生检查，合格者发给卫生证书。该证书自签发之日起12个月内可以申请电讯检疫。"},{"i":28,"n":"第二十八条","txt":"持有效卫生证书的船舶在入境前24小时，应当向卫生检疫机关报告下列事项："},{"i":29,"n":"第二十九条","txt":"对船舶的入境检疫，在日出后到日落前的时间内实施；凡具备船舶夜航条件，夜间可靠离码头和装卸作业的港口口岸，应实行24小时检疫。对来自疫区的船舶，不实行夜间检疫。"},{"i":30,"n":"第三十条","txt":"受入境检疫船舶的船长，在检疫医师到达船上时，必须提交由船长签字或者有船医附签的航海健康申报书、船员名单、旅客名单、载货申报单，并出示除鼠证书或者免予除鼠证书。"},{"i":31,"n":"第三十一条","txt":"船舶实施入境查验完毕以后，对没有染疫的船舶，检疫医师应当立即签发入境检疫证；如果该船有受卫生处理或者限制的事项，应当在入境检疫证上签注，并按照签注事项办理。对染疫船舶、染疫嫌疑船舶，除通知港务监督机关外，对该船舶还应当发给卫生处理通知书，该船舶上的引航员和经卫生检疫机关许可上船的人员应当视同员工接受有关卫生处理，在卫生处理完毕以后，再发给入境检疫证。"},{"i":32,"n":"第三十二条","txt":"船舶代理应当在受出境检疫的船舶启航以前，尽早向卫生检疫机关通知下列事项："},{"i":33,"n":"第三十三条","txt":"受出境检疫的船舶，船长应当向卫生检疫机关出示除鼠证书或者免予除鼠证书和其他有关检疫证件。检疫医师可以向船长、船医提出有关船员、旅客健康情况和船上卫生情况的询问，船长、船医对上述询问应当如实回答。"},{"i":34,"n":"第三十四条","txt":"对船舶实施出境检疫完毕以后，检疫医师应当按照检疫结果立即签发出境检疫证，如果因卫生处理不能按原定时间启航，应当及时通知港务监督机关。"},{"i":35,"n":"第三十五条","txt":"对船舶实施出境检疫完毕以后，除引航员和经卫生检疫机关许可的人员外，其他人员不准上船，不准装卸行李、货物、邮包等物品。如果违反上述规定，该船舶必须重新实施出境检疫。"},{"i":36,"n":"第三十六条","txt":"航空器在飞行中，不得向下投掷或者任其坠下能传播传染病的任何物品。"},{"i":37,"n":"第三十七条","txt":"实施卫生检疫机场的航空站，应当在受入境检疫的航空器到达以前，尽早向卫生检疫机关通知下列事项："},{"i":38,"n":"第三十八条","txt":"受入境检疫的航空器，如果在飞行中发现检疫传染病、疑似检疫传染病，或者有人非因意外伤害而死亡并死因不明时，机长应当立即通知到达机场的航空站，向卫生检疫机关报告下列事项："},{"i":39,"n":"第三十九条","txt":"受入境检疫的航空器到达机场以后，检疫医师首先登机。机长或者其授权的代理人，必须向卫生检疫机关提交总申报单、旅客名单、货物仓单和有效的灭蚊证书，以及其他有关检疫证件；对检疫医师提出的有关航空器上卫生状况的询问，机长或者其授权的代理人应当如实回答。在检疫没有结束之前，除经卫生检疫机关许可外，任何人不得上下航空器，不准装卸行李、货物、邮包等物品。"},{"i":40,"n":"第四十条","txt":"入境旅客必须在指定的地点，接受入境查验，同时用书面或者口头回答检疫医师提出的有关询问。在此期间，入境旅客不得离开查验场所。"},{"i":41,"n":"第四十一条","txt":"对入境航空器查验完毕以后，根据查验结果，对没有染疫的航空器，检疫医师应当签发入境检疫证；如果该航空器有受卫生处理或者限制的事项，应当在入境检疫证上签注，由机长或者其授权的代理人负责执行；对染疫或者有染疫嫌疑的航空器，除通知航空站外，对该航空器应当发给卫生处理通知单，在规定的卫生处理完毕以后，再发给入境检疫证。"},{"i":42,"n":"第四十二条","txt":"实施卫生检疫机场的航空站，应当在受出境检疫的航空器起飞以前，尽早向卫生检疫机关提交总申报单、货物仓单和其他有关检疫证件，并通知下列事项："},{"i":43,"n":"第四十三条","txt":"对出境航空器查验完毕以后，如果没有染疫，检疫医师应当签发出境检疫证或者在必要的卫生处理完毕以后，再发给出境检疫证；如果该航空器因卫生处理不能按原定时间起飞，应当及时通知航空站。"},{"i":44,"n":"第四十四条","txt":"实施卫生检疫的车站，应当在受入境检疫的列车到达之前，尽早向卫生检疫机关通知下列事项："},{"i":45,"n":"第四十五条","txt":"受入境检疫的列车和其他车辆到达车站、关口后，检疫医师首先登车，列车长或者其他车辆负责人，应当口头或者书面向卫生检疫机关申报该列车或者其他车辆上人员的健康情况，对检疫医师提出有关卫生状况和人员健康的询问，应当如实回答。"},{"i":46,"n":"第四十六条","txt":"受入境检疫的列车和其他车辆到达车站、关口，在实施入境检疫而未取得入境检疫证以前，未经卫生检疫机关许可，任何人不准上下列车或者其他车辆，不准装卸行李、货物、邮包等物品。"},{"i":47,"n":"第四十七条","txt":"实施卫生检疫的车站，应当在受出境检疫列车发车以前，尽早向卫生检疫机关通知下列事项："},{"i":48,"n":"第四十八条","txt":"应当受入境、出境检疫的列车和其他车辆，如果在行程中发现检疫传染病、疑似检疫传染病，或者有人非因意外伤害而死亡并死因不明的，列车或者其他车辆到达车站、关口时，列车长或者其他车辆负责人应当向卫生检疫机关报告。"},{"i":49,"n":"第四十九条","txt":"受入境、出境检疫的列车，在查验中发现检疫传染病或者疑似检疫传染病，或者因受卫生处理不能按原定时间发车，卫生检疫机关应当及时通知车站的站长。如果列车在原停车地点不宜实施卫生处理，站长可以选择站内其他地点实施卫生处理。在处理完毕之前，未经卫生检疫机关许可，任何人不准上下列车，不准装卸行李、货物、邮包等物品。"},{"i":50,"n":"第五十条","txt":"对列车或者其他车辆实施入境、出境检疫完毕后，检疫医师应当根据检疫结果分别签发入境、出境检疫证，或者在必要的卫生处理完毕后，再分别签发入境、出境检疫证。"},{"i":51,"n":"第五十一条","txt":"徒步入境、出境的人员，必须首先在指定的场所接受入境、出境查验，未经卫生检疫机关许可，不准离开指定的场所。"},{"i":52,"n":"第五十二条","txt":"受入境、出境检疫的列车以及其他车辆，载有来自疫区、有染疫或者染疫嫌疑或者夹带能传播传染病的病媒昆虫和啮齿动物的货物，应当接受卫生检查和必要的卫生处理。"},{"i":53,"n":"第五十三条","txt":"卫生检疫机关的工作人员在实施卫生处理时，必须注意下列事项："},{"i":54,"n":"第五十四条","txt":"入境、出境的集装箱、行李、货物、邮包等物品需要卫生处理的，由卫生检疫机关实施。"},{"i":55,"n":"第五十五条","txt":"由国外起运经过中华人民共和国境内的货物，如果不在境内换装，除发生在流行病学上有重要意义的事件，需要实施卫生处理外，在一般情况下不实施卫生处理。"},{"i":56,"n":"第五十六条","txt":"卫生检疫机关对入境、出境的废旧物品和曾行驶于境外港口的废旧交通工具，根据污染程度，分别实施消毒、除鼠、除虫，对污染严重的实施销毁。"},{"i":57,"n":"第五十七条","txt":"入境、出境的尸体、骸骨托运人或者代理人应当申请卫生检疫，并出示死亡证明或者其他有关证件，对不符合卫生要求的，必须接受卫生检疫机关实施的卫生处理。经卫生检疫合格后，方准运进或者运出。"},{"i":58,"n":"第五十八条","txt":"卫生检疫机关对已在到达本口岸前的其他口岸实施卫生处理的交通工具不再重复实施卫生处理。但有下列情形之一的，仍需实施卫生处理："},{"i":59,"n":"第五十九条","txt":"在国境口岸或者交通工具上发现啮齿动物有反常死亡或者死因不明的，国境口岸有关单位或者交通工具的负责人，必须立即向卫生检疫机关报告，迅速查明原因，实施卫生处理。"},{"i":60,"n":"第六十条","txt":"国际航行船舶的船长，必须每隔6个月向卫生检疫机关申请一次鼠患检查，卫生检疫机关根据检查结果实施除鼠或者免予除鼠，并且分别发给除鼠证书或者免予除鼠证书。该证书自签发之日起6个月内有效。"},{"i":61,"n":"第六十一条","txt":"卫生检疫机关只有在下列之一情况下，经检查确认船舶无鼠害的，方可签发免予除鼠证书："},{"i":62,"n":"第六十二条","txt":"对船舶的鼠患检查或者除鼠，应当尽量在船舶空舱的时候进行。如果船舶因故不宜按期进行鼠患检查或者蒸熏除鼠，并且该船又开往便于实施鼠患检查或者蒸熏除鼠的港口，可以准许该船原有的除鼠证书或者免予除鼠证书的有效期延长1个月，并签发延长证明。"},{"i":63,"n":"第六十三条","txt":"对国际航行的船舶，按照国家规定的标准，应当用蒸熏的方法除鼠时，如果该船的除鼠证书或者免予除鼠证书尚未失效，除该船染有鼠疫或者鼠疫嫌疑外，卫生检疫机关应当将除鼠理由通知船长。船长应当按照要求执行。"},{"i":64,"n":"第六十四条","txt":"船舶在港口停靠期间，船长应当负责采取下列的措施："},{"i":65,"n":"第六十五条","txt":"在国境口岸停留的国内航行的船舶如果存在鼠患，船方应当进行除鼠。根据船方申请，也可由卫生检疫机关实施除鼠。"},{"i":66,"n":"第六十六条","txt":"国务院卫生行政部门认为必要时，可以要求来自国外或者国外某些地区的人员在入境时，向卫生检疫机关出示有效的某种预防接种证书或者健康证明。"},{"i":67,"n":"第六十七条","txt":"预防接种的有效期如下："},{"i":68,"n":"第六十八条","txt":"鼠疫的潜伏期为6日。"},{"i":69,"n":"第六十九条","txt":"船舶、航空器在到达时，有下列情形之一的，为染有鼠疫："},{"i":70,"n":"第七十条","txt":"船舶在到达时，有下列情形之一的，为染有鼠疫嫌疑："},{"i":71,"n":"第七十一条","txt":"对染有鼠疫的船舶、航空器应当实施下列卫生处理："},{"i":72,"n":"第七十二条","txt":"对染有鼠疫嫌疑的船舶，应当实施本细则第七十一条第（二）至第（六）项规定的卫生处理。"},{"i":73,"n":"第七十三条","txt":"对没有染疫的船舶、航空器，如果来自鼠疫疫区，卫生检疫机关认为必要时，可以实施下列卫生处理："},{"i":74,"n":"第七十四条","txt":"对到达的时候载有鼠疫病例的列车和其他车辆，应当实施下列卫生处理："},{"i":75,"n":"第七十五条","txt":"霍乱潜伏期为5日。"},{"i":76,"n":"第七十六条","txt":"船舶在到达的时候载有霍乱病例，或者在到达前5日以内，船上曾经有霍乱病例发生，为染有霍乱。"},{"i":77,"n":"第七十七条","txt":"航空器在到达的时候载有霍乱病例，为染有霍乱。"},{"i":78,"n":"第七十八条","txt":"对染有霍乱的船舶、航空器，应当实施下列卫生处理："},{"i":79,"n":"第七十九条","txt":"对染有霍乱嫌疑的船舶、航空器应当实施下列卫生处理："},{"i":80,"n":"第八十条","txt":"对没有染疫的船舶、航空器，如果来自霍乱疫区，卫生检疫机关认为必要时，可以实施下列卫生处理："},{"i":81,"n":"第八十一条","txt":"对到达时载有霍乱病例的列车和其他车辆应当实施下列卫生处理："},{"i":82,"n":"第八十二条","txt":"对来自霍乱疫区的或者染有霍乱嫌疑的交通工具，卫生检疫机关认为必要时，可以实施除虫、消毒；如果交通工具载有水产品、水果、蔬菜、饮料及其他食品，除装在密封容器内没有被污染外，未经卫生检疫机关许可，不准卸下，必要时可以实施卫生处理。"},{"i":83,"n":"第八十三条","txt":"对来自霍乱疫区的水产品、水果、蔬菜、饮料以及装有这些制品的邮包，卫生检疫机关在查验时，为了判明是否被污染，可以抽样检验，必要时可以实施卫生处理。"},{"i":84,"n":"第八十四条","txt":"黄热病的潜伏期为6日。"},{"i":85,"n":"第八十五条","txt":"来自黄热病疫区的人员，在入境时，必须向卫生检疫机关出示有效的黄热病预防接种证书。"},{"i":86,"n":"第八十六条","txt":"航空器到达时载有黄热病病例，为染有黄热病。"},{"i":87,"n":"第八十七条","txt":"来自黄热病疫区的航空器，应当出示在疫区起飞前的灭蚊证书；如果在到达时不出示灭蚊证书，或者卫生检疫机关认为出示的灭蚊证书不符合要求，并且在航空器上发现活蚊，为染有黄热病嫌疑。"},{"i":88,"n":"第八十八条","txt":"船舶在到达时载有黄热病病例，或者在航行中曾经有黄热病病例发生，为染有黄热病。"},{"i":89,"n":"第八十九条","txt":"对染有黄热病的船舶、航空器，应当实施下列卫生处理："},{"i":90,"n":"第九十条","txt":"对染有黄热病嫌疑的船舶、航空器，应当实施本细则第八十九条第（二）至第（四）项规定的卫生处理。"},{"i":91,"n":"第九十一条","txt":"对没有染疫的船舶、航空器，如果来自黄热病疫区，卫生检疫机关认为必要时，可以实施本细则第八十九条第（三）项规定的卫生处理。"},{"i":92,"n":"第九十二条","txt":"对到达的时候载有黄热病病例的列车和其他车辆，或者来自黄热病疫区的列车和其他车辆，应当实施本细则第八十九条第（一）、第（四）项规定的卫生处理；对列车、车辆彻底杀灭成蚊及其虫卵、幼虫；对无有效黄热病预防接种证书的员工、旅客，应当实施本细则第八十五条规定的卫生处理。"},{"i":93,"n":"第九十三条","txt":"卫生检疫机关对受就地诊验的人员，应当发给就地诊验记录簿，必要的时候，可以在该人员出具履行就地诊验的保证书以后，再发给其就地诊验记录簿。"},{"i":94,"n":"第九十四条","txt":"卫生检疫机关应当将受就地诊验人员的情况，用最快的方法通知受就地诊验人员的旅行停留地的卫生检疫机关或者其他医疗卫生单位。"},{"i":95,"n":"第九十五条","txt":"受留验的人员必须在卫生检疫机关指定的场所接受留验；但是有下列情形之一的，经卫生检疫机关同意，可以在船上留验："},{"i":96,"n":"第九十六条","txt":"受留验的人员在留验期间如果出现检疫传染病的症状，卫生检疫机关应当立即对该人员实施隔离，对与其接触的其他受留验的人员，应当实施必要的卫生处理，并且从卫生处理完毕时算起，重新计算留验时间。"},{"i":97,"n":"第九十七条","txt":"入境、出境的交通工具、人员、食品、饮用水和其他物品以及病媒昆虫、动物，均为传染病监测的对象。"},{"i":98,"n":"第九十八条","txt":"传染病监测内容是："},{"i":99,"n":"第九十九条","txt":"卫生检疫机关应当阻止患有严重精神病、传染性肺结核病或者有可能对公共卫生造成重大危害的其他传染病的外国人入境。"},{"i":100,"n":"第一百条","txt":"受入境、出境检疫的人员，必须根据检疫医师的要求，如实填报健康申明卡，出示某种有效的传染病预防接种证书、健康证明或者其他有关证件。"},{"i":101,"n":"第一百零一条","txt":"卫生检疫机关对国境口岸的涉外宾馆、饭店内居住的入境、出境人员及工作人员实施传染病监测，并区别情况采取必要的预防、控制措施。"},{"i":102,"n":"第一百零二条","txt":"凡申请出境居住1年以上的中国籍人员，必须持有卫生检疫机关签发的健康证明。中国公民出境、入境管理机关凭卫生检疫机关签发的健康证明办理出境手续。"},{"i":103,"n":"第一百零三条","txt":"卫生检疫机关在国境口岸内设立传染病监测点时，有关单位应当给予协助并提供方便。"},{"i":104,"n":"第一百零四条","txt":"卫生检疫机关依照《国境卫生检疫法》第十八条、第十九条规定的内容，对国境口岸和交通工具实施卫生监督。"},{"i":105,"n":"第一百零五条","txt":"对国境口岸的卫生要求是："},{"i":106,"n":"第一百零六条","txt":"对交通工具的卫生要求是："},{"i":107,"n":"第一百零七条","txt":"对饮用水、食品及从业人员的卫生要求是："},{"i":108,"n":"第一百零八条","txt":"国境口岸有关单位和交通工具负责人应当遵守下列事项："},{"i":109,"n":"第一百零九条","txt":"《国境卫生检疫法》和本细则所规定的应当受行政处罚的行为是指："},{"i":110,"n":"第一百一十条","txt":"具有本细则第一百零九条所列第（一）至第（五）项行为的，处以警告或者100元以上5000元以下的罚款；"},{"i":111,"n":"第一百一十一条","txt":"卫生检疫机关在收取罚款时，应当出具正式的罚款收据。罚款全部上交国库。"},{"i":112,"n":"第一百一十二条","txt":"国境卫生检疫机关实施卫生检疫的收费标准，由海关总署会同国务院财政、物价部门共同制定。"},{"i":113,"n":"第一百一十三条","txt":"本细则自发布之日起施行。"}],"tudiguanlifashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国土地管理法》（以下简称《土地管理法》），制定本条例。"},{"i":2,"n":"第二条","txt":"国家建立国土空间规划体系。"},{"i":3,"n":"第三条","txt":"国土空间规划应当细化落实国家发展规划提出的国土空间开发保护要求，统筹布局农业、生态、城镇等功能空间，划定落实永久基本农田、生态保护红线和城镇开发边界。"},{"i":4,"n":"第四条","txt":"土地调查应当包括下列内容："},{"i":5,"n":"第五条","txt":"国务院自然资源主管部门会同有关部门制定土地等级评定标准。"},{"i":6,"n":"第六条","txt":"县级以上人民政府自然资源主管部门应当加强信息化建设，建立统一的国土空间基础信息平台，实行土地管理全流程信息化管理，对土地利用状况进行动态监测，与发展改革、住房和城乡建设等有关部门建立土地管理信息共享机制，依法公开土地管理信息。"},{"i":7,"n":"第七条","txt":"县级以上人民政府自然资源主管部门应当加强地籍管理，建立健全地籍数据库。"},{"i":8,"n":"第八条","txt":"国家实行占用耕地补偿制度。在国土空间规划确定的城市和村庄、集镇建设用地范围内经依法批准占用耕地，以及在国土空间规划确定的城市和村庄、集镇建设用地范围外的能源、交通、水利、矿山、军事设施等建设项目经依法批准占用耕地的，分别由县级人民政府、农村集体经济组织和建设单位负责开垦与所占用耕地的数量和质量相当的耕地；没有条件开垦或者开垦的耕地不符合要求的，应当按照省、自治区、直辖市的规定缴纳耕地开垦费，专款用于开垦新的耕地。"},{"i":9,"n":"第九条","txt":"禁止任何单位和个人在国土空间规划确定的禁止开垦的范围内从事土地开发活动。"},{"i":10,"n":"第十条","txt":"县级人民政府应当按照国土空间规划关于统筹布局农业、生态、城镇等功能空间的要求，制定土地整理方案，促进耕地保护和土地节约集约利用。"},{"i":11,"n":"第十一条","txt":"县级以上地方人民政府应当采取措施，预防和治理耕地土壤流失、污染，有计划地改造中低产田，建设高标准农田，提高耕地质量，保护黑土地等优质耕地，并依法对建设所占用耕地耕作层的土壤利用作出合理安排。"},{"i":12,"n":"第十二条","txt":"国家对耕地实行特殊保护，严守耕地保护红线，严格控制耕地转为林地、草地、园地等其他农用地，并建立耕地保护补偿制度，具体办法和耕地保护补偿实施步骤由国务院自然资源主管部门会同有关部门规定。"},{"i":13,"n":"第十三条","txt":"省、自治区、直辖市人民政府对本行政区域耕地保护负总责，其主要负责人是本行政区域耕地保护的第一责任人。"},{"i":14,"n":"第十四条","txt":"建设项目需要使用土地的，应当符合国土空间规划、土地利用年度计划和用途管制以及节约资源、保护生态环境的要求，并严格执行建设用地标准，优先使用存量建设用地，提高建设用地使用效率。"},{"i":15,"n":"第十五条","txt":"各级人民政府应当依据国民经济和社会发展规划及年度计划、国土空间规划、国家产业政策以及城乡建设、土地利用的实际状况等，加强土地利用计划管理，实行建设用地总量控制，推动城乡存量建设用地开发利用，引导城镇低效用地再开发，落实建设用地标准控制制度，开展节约集约用地评价，推广应用节地技术和节地模式。"},{"i":16,"n":"第十六条","txt":"县级以上地方人民政府自然资源主管部门应当将本级人民政府确定的年度建设用地供应总量、结构、时序、地块、用途等在政府网站上向社会公布，供社会公众查阅。"},{"i":17,"n":"第十七条","txt":"建设单位使用国有土地，应当以有偿使用方式取得；但是，法律、行政法规规定可以以划拨方式取得的除外。"},{"i":18,"n":"第十八条","txt":"国有土地使用权出让、国有土地租赁等应当依照国家有关规定通过公开的交易平台进行交易，并纳入统一的公共资源交易平台体系。除依法可以采取协议方式外，应当采取招标、拍卖、挂牌等竞争性方式确定土地使用者。"},{"i":19,"n":"第十九条","txt":"《土地管理法》第五十五条规定的新增建设用地的土地有偿使用费，是指国家在新增建设用地中应取得的平均土地纯收益。"},{"i":20,"n":"第二十条","txt":"建设项目施工、地质勘查需要临时使用土地的，应当尽量不占或者少占耕地。"},{"i":21,"n":"第二十一条","txt":"抢险救灾、疫情防控等急需使用土地的，可以先行使用土地。其中，属于临时用地的，用后应当恢复原状并交还原土地使用者使用，不再办理用地审批手续；属于永久性建设用地的，建设单位应当在不晚于应急处置工作结束六个月内申请补办建设用地审批手续。"},{"i":22,"n":"第二十二条","txt":"具有重要生态功能的未利用地应当依法划入生态保护红线，实施严格保护。"},{"i":23,"n":"第二十三条","txt":"在国土空间规划确定的城市和村庄、集镇建设用地范围内，为实施该规划而将农用地转为建设用地的，由市、县人民政府组织自然资源等部门拟订农用地转用方案，分批次报有批准权的人民政府批准。"},{"i":24,"n":"第二十四条","txt":"建设项目确需占用国土空间规划确定的城市和村庄、集镇建设用地范围外的农用地，涉及占用永久基本农田的，由国务院批准；不涉及占用永久基本农田的，由国务院或者国务院授权的省、自治区、直辖市人民政府批准。具体按照下列规定办理："},{"i":25,"n":"第二十五条","txt":"建设项目需要使用土地的，建设单位原则上应当一次申请，办理建设用地审批手续，确需分期建设的项目，可以根据可行性研究报告确定的方案，分期申请建设用地，分期办理建设用地审批手续。建设过程中用地范围确需调整的，应当依法办理建设用地审批手续。"},{"i":26,"n":"第二十六条","txt":"需要征收土地，县级以上地方人民政府认为符合《土地管理法》第四十五条规定的，应当发布征收土地预公告，并开展拟征收土地现状调查和社会稳定风险评估。"},{"i":27,"n":"第二十七条","txt":"县级以上地方人民政府应当依据社会稳定风险评估结果，结合土地现状调查情况，组织自然资源、财政、农业农村、人力资源和社会保障等有关部门拟定征地补偿安置方案。"},{"i":28,"n":"第二十八条","txt":"征地补偿安置方案拟定后，县级以上地方人民政府应当在拟征收土地所在的乡（镇）和村、村民小组范围内公告，公告时间不少于三十日。"},{"i":29,"n":"第二十九条","txt":"县级以上地方人民政府根据法律、法规规定和听证会等情况确定征地补偿安置方案后，应当组织有关部门与拟征收土地的所有权人、使用权人签订征地补偿安置协议。征地补偿安置协议示范文本由省、自治区、直辖市人民政府制定。"},{"i":30,"n":"第三十条","txt":"县级以上地方人民政府完成本条例规定的征地前期工作后，方可提出征收土地申请，依照《土地管理法》第四十六条的规定报有批准权的人民政府批准。"},{"i":31,"n":"第三十一条","txt":"征收土地申请经依法批准后，县级以上地方人民政府应当自收到批准文件之日起十五个工作日内在拟征收土地所在的乡（镇）和村、村民小组范围内发布征收土地公告，公布征收范围、征收时间等具体工作安排，对个别未达成征地补偿安置协议的应当作出征地补偿安置决定，并依法组织实施。"},{"i":32,"n":"第三十二条","txt":"省、自治区、直辖市应当制定公布区片综合地价，确定征收农用地的土地补偿费、安置补助费标准，并制定土地补偿费、安置补助费分配办法。"},{"i":33,"n":"第三十三条","txt":"农村居民点布局和建设用地规模应当遵循节约集约、因地制宜的原则合理规划。县级以上地方人民政府应当按照国家规定安排建设用地指标，合理保障本行政区域农村村民宅基地需求。"},{"i":34,"n":"第三十四条","txt":"农村村民申请宅基地的，应当以户为单位向农村集体经济组织提出申请；没有设立农村集体经济组织的，应当向所在的村民小组或者村民委员会提出申请。宅基地申请依法经农村村民集体讨论通过并在本集体范围内公示后，报乡（镇）人民政府审核批准。"},{"i":35,"n":"第三十五条","txt":"国家允许进城落户的农村村民依法自愿有偿退出宅基地。乡（镇）人民政府和农村集体经济组织、村民委员会等应当将退出的宅基地优先用于保障该农村集体经济组织成员的宅基地需求。"},{"i":36,"n":"第三十六条","txt":"依法取得的宅基地和宅基地上的农村村民住宅及其附属设施受法律保护。"},{"i":37,"n":"第三十七条","txt":"国土空间规划应当统筹并合理安排集体经营性建设用地布局和用途，依法控制集体经营性建设用地规模，促进集体经营性建设用地的节约集约利用。"},{"i":38,"n":"第三十八条","txt":"国土空间规划确定为工业、商业等经营性用途，且已依法办理土地所有权登记的集体经营性建设用地，土地所有权人可以通过出让、出租等方式交由单位或者个人在一定年限内有偿使用。"},{"i":39,"n":"第三十九条","txt":"土地所有权人拟出让、出租集体经营性建设用地的，市、县人民政府自然资源主管部门应当依据国土空间规划提出拟出让、出租的集体经营性建设用地的规划条件，明确土地界址、面积、用途和开发建设强度等。"},{"i":40,"n":"第四十条","txt":"土地所有权人应当依据规划条件、产业准入和生态环境保护要求等，编制集体经营性建设用地出让、出租等方案，并依照《土地管理法》第六十三条的规定，由本集体经济组织形成书面意见，在出让、出租前不少于十个工作日报市、县人民政府。市、县人民政府认为该方案不符合规划条件或者产业准入和生态环境保护要求等的，应当在收到方案后五个工作日内提出修改意见。土地所有权人应当按照市、县人民政府的意见进行修改。"},{"i":41,"n":"第四十一条","txt":"土地所有权人应当依据集体经营性建设用地出让、出租等方案，以招标、拍卖、挂牌或者协议等方式确定土地使用者，双方应当签订书面合同，载明土地界址、面积、用途、规划条件、使用期限、交易价款支付、交地时间和开工竣工期限、产业准入和生态环境保护要求，约定提前收回的条件、补偿方式、土地使用权届满续期和地上建筑物、构筑物等附着物处理方式，以及违约责任和解决争议的方法等，并报市、县人民政府自然资源主管部门备案。未依法将规划条件、产业准入和生态环境保护要求纳入合同的，合同无效；造成损失的，依法承担民事责任。合同示范文本由国务院自然资源主管部门制定。"},{"i":42,"n":"第四十二条","txt":"集体经营性建设用地使用者应当按照约定及时支付集体经营性建设用地价款，并依法缴纳相关税费，对集体经营性建设用地使用权以及依法利用集体经营性建设用地建造的建筑物、构筑物及其附属设施的所有权，依法申请办理不动产登记。"},{"i":43,"n":"第四十三条","txt":"通过出让等方式取得的集体经营性建设用地使用权依法转让、互换、出资、赠与或者抵押的，双方应当签订书面合同，并书面通知土地所有权人。"},{"i":44,"n":"第四十四条","txt":"国家自然资源督察机构根据授权对省、自治区、直辖市人民政府以及国务院确定的城市人民政府下列土地利用和土地管理情况进行督察："},{"i":45,"n":"第四十五条","txt":"国家自然资源督察机构进行督察时，有权向有关单位和个人了解督察事项有关情况，有关单位和个人应当支持、协助督察机构工作，如实反映情况，并提供有关材料。"},{"i":46,"n":"第四十六条","txt":"被督察的地方人民政府违反土地管理法律、行政法规，或者落实国家有关土地管理重大决策不力的，国家自然资源督察机构可以向被督察的地方人民政府下达督察意见书，地方人民政府应当认真组织整改，并及时报告整改情况；国家自然资源督察机构可以约谈被督察的地方人民政府有关负责人，并可以依法向监察机关、任免机关等有关机关提出追究相关责任人责任的建议。"},{"i":47,"n":"第四十七条","txt":"土地管理监督检查人员应当经过培训，经考核合格，取得行政执法证件后，方可从事土地管理监督检查工作。"},{"i":48,"n":"第四十八条","txt":"自然资源主管部门、农业农村主管部门按照职责分工进行监督检查时，可以采取下列措施："},{"i":49,"n":"第四十九条","txt":"依照《土地管理法》第七十三条的规定给予处分的，应当按照管理权限由责令作出行政处罚决定或者直接给予行政处罚的上级人民政府自然资源主管部门或者其他任免机关、单位作出。"},{"i":50,"n":"第五十条","txt":"县级以上人民政府自然资源主管部门应当会同有关部门建立信用监管、动态巡查等机制，加强对建设用地供应交易和供后开发利用的监管，对建设用地市场重大失信行为依法实施惩戒，并依法公开相关信息。"},{"i":51,"n":"第五十一条","txt":"违反《土地管理法》第三十七条的规定，非法占用永久基本农田发展林果业或者挖塘养鱼的，由县级以上人民政府自然资源主管部门责令限期改正；逾期不改正的，按占用面积处耕地开垦费2倍以上5倍以下的罚款；破坏种植条件的，依照《土地管理法》第七十五条的规定处罚。"},{"i":52,"n":"第五十二条","txt":"违反《土地管理法》第五十七条的规定，在临时使用的土地上修建永久性建筑物的，由县级以上人民政府自然资源主管部门责令限期拆除，按占用面积处土地复垦费5倍以上10倍以下的罚款；逾期不拆除的，由作出行政决定的机关依法申请人民法院强制执行。"},{"i":53,"n":"第五十三条","txt":"违反《土地管理法》第六十五条的规定，对建筑物、构筑物进行重建、扩建的，由县级以上人民政府自然资源主管部门责令限期拆除；逾期不拆除的，由作出行政决定的机关依法申请人民法院强制执行。"},{"i":54,"n":"第五十四条","txt":"依照《土地管理法》第七十四条的规定处以罚款的，罚款额为违法所得的10%以上50%以下。"},{"i":55,"n":"第五十五条","txt":"依照《土地管理法》第七十五条的规定处以罚款的，罚款额为耕地开垦费的5倍以上10倍以下；破坏黑土地等优质耕地的，从重处罚。"},{"i":56,"n":"第五十六条","txt":"依照《土地管理法》第七十六条的规定处以罚款的，罚款额为土地复垦费的2倍以上5倍以下。"},{"i":57,"n":"第五十七条","txt":"依照《土地管理法》第七十七条的规定处以罚款的，罚款额为非法占用土地每平方米100元以上1000元以下。"},{"i":58,"n":"第五十八条","txt":"依照《土地管理法》第七十四条、第七十七条的规定，县级以上人民政府自然资源主管部门没收在非法转让或者非法占用的土地上新建的建筑物和其他设施的，应当于九十日内交由本级人民政府或者其指定的部门依法管理和处置。"},{"i":59,"n":"第五十九条","txt":"依照《土地管理法》第八十一条的规定处以罚款的，罚款额为非法占用土地每平方米100元以上500元以下。"},{"i":60,"n":"第六十条","txt":"依照《土地管理法》第八十二条的规定处以罚款的，罚款额为违法所得的10%以上30%以下。"},{"i":61,"n":"第六十一条","txt":"阻碍自然资源主管部门、农业农村主管部门的工作人员依法执行职务，构成违反治安管理行为的，依法给予治安管理处罚。"},{"i":62,"n":"第六十二条","txt":"违反土地管理法律、法规规定，阻挠国家建设征收土地的，由县级以上地方人民政府责令交出土地；拒不交出土地的，依法申请人民法院强制执行。"},{"i":63,"n":"第六十三条","txt":"违反本条例规定，侵犯农村村民依法取得的宅基地权益的，责令限期改正，对有关责任单位通报批评、给予警告；造成损失的，依法承担赔偿责任；对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":64,"n":"第六十四条","txt":"贪污、侵占、挪用、私分、截留、拖欠征地补偿安置费用和其他有关费用的，责令改正，追回有关款项，限期退还违法所得，对有关责任单位通报批评、给予警告；造成损失的，依法承担赔偿责任；对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":65,"n":"第六十五条","txt":"各级人民政府及自然资源主管部门、农业农村主管部门工作人员玩忽职守、滥用职权、徇私舞弊的，依法给予处分。"},{"i":66,"n":"第六十六条","txt":"违反本条例规定，构成犯罪的，依法追究刑事责任。"},{"i":67,"n":"第六十七条","txt":"本条例自2021年9月1日起施行。"}],"zengzhishuifashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国增值税法》（以下简称增值税法），制定本条例。"},{"i":2,"n":"第二条","txt":"增值税法第三条所称货物，包括有形动产、电力、热力、气体等。"},{"i":3,"n":"第三条","txt":"增值税法第三条所称单位，包括企业、行政机关、事业单位、军事单位、社会组织及其他单位。"},{"i":4,"n":"第四条","txt":"增值税法第四条第四项所称服务、无形资产在境内消费，是指下列情形："},{"i":5,"n":"第五条","txt":"纳税人开具增值税专用发票，应当分别列明销售额和增值税税额。"},{"i":6,"n":"第六条","txt":"适用一般计税方法的纳税人为一般纳税人。"},{"i":7,"n":"第七条","txt":"自然人属于小规模纳税人。不经常发生应税交易且主要业务不属于应税交易范围的非企业单位，可以选择按照小规模纳税人纳税。"},{"i":8,"n":"第八条","txt":"增值税法第十条第四项所称出口货物，是指向海关报关实际离境并销售给境外单位或者个人的货物，以及国务院规定的视同出口的货物。"},{"i":9,"n":"第九条","txt":"境内单位或者个人跨境销售下列服务、无形资产，税率为零："},{"i":10,"n":"第十条","txt":"增值税法第十三条所称应税交易，应当同时符合下列条件："},{"i":11,"n":"第十一条","txt":"增值税法第十六条所称增值税扣税凭证，应当符合国务院税务主管部门的有关规定，具体包括增值税专用发票、海关进口增值税专用缴款书、完税凭证、农产品收购发票、农产品销售发票以及其他具有进项税额抵扣功能的扣税凭证。"},{"i":12,"n":"第十二条","txt":"纳税人凭增值税扣税凭证从销项税额中抵扣的进项税额，包括："},{"i":13,"n":"第十三条","txt":"纳税人按照一般计税方法计算缴纳增值税的，因销售折让、中止或者退回而退还给购买方的增值税税额，应当从当期的销项税额中扣减；因销售折让、中止或者退回而收回的增值税税额，应当从当期的进项税额中扣减。"},{"i":14,"n":"第十四条","txt":"纳税人按照简易计税方法计算缴纳增值税的，因销售折让、中止或者退回而退还给购买方的销售额，应当从当期销售额中扣减。扣减当期销售额后仍有多缴税款的，可以从以后的应纳税额中扣减或者按规定申请退还。"},{"i":15,"n":"第十五条","txt":"增值税法第十七条所称全部价款，不包括纳税人代为收取的下列税费或者款项："},{"i":16,"n":"第十六条","txt":"纳税人采用销售额和增值税税额合并定价方法的，按照下列公式计算销售额："},{"i":17,"n":"第十七条","txt":"纳税人以人民币以外的货币结算销售额的，在折合成人民币计算时，折合率可以选择销售额发生的当日或者当月1日有效的人民币汇率中间价。纳税人确定折合率后，12个月内不得变更。"},{"i":18,"n":"第十八条","txt":"纳税人发生增值税法第二十条规定情形的，税务机关可以按顺序依照下列方法核定销售额："},{"i":19,"n":"第十九条","txt":"增值税法第二十二条第三项所称非正常损失，是指因管理不善造成货物被盗、丢失、霉烂变质，以及因违反法律法规造成货物或者不动产被依法没收、销毁、拆除等情形。"},{"i":20,"n":"第二十条","txt":"纳税人的交际应酬消费属于增值税法所称个人消费。"},{"i":21,"n":"第二十一条","txt":"纳税人购进贷款服务的利息支出，及其向贷款方支付的与该贷款服务直接相关的投融资顾问费、手续费、咨询费等费用支出，对应的进项税额暂不得从销项税额中抵扣。"},{"i":22,"n":"第二十二条","txt":"纳税人购进货物、服务、无形资产、不动产，用于同时符合下列情形的非应税交易（以下统称不得抵扣非应税交易），对应的进项税额不得从销项税额中抵扣："},{"i":23,"n":"第二十三条","txt":"一般纳税人购进货物（不含固定资产）、服务，用于简易计税方法计税项目、免征增值税项目和不得抵扣非应税交易而无法划分不得抵扣的进项税额的，应当按照销售额或者收入占比逐期计算当期不得抵扣的进项税额，并于次年1月的纳税申报期内进行全年汇总清算。"},{"i":24,"n":"第二十四条","txt":"已抵扣进项税额的购进货物（不含固定资产）、服务，发生增值税法第二十二条第三项至第五项规定情形的，应当将对应的进项税额从当期进项税额中扣减；无法确定对应的进项税额的，按照当期实际成本计算应扣减的进项税额。"},{"i":25,"n":"第二十五条","txt":"一般纳税人取得的固定资产、无形资产或者不动产（以下统称长期资产），既用于一般计税方法计税项目，又用于简易计税方法计税项目、免征增值税项目、不得抵扣非应税交易、集体福利或者个人消费（以下统称五类不允许抵扣项目）的，属于用作混合用途的长期资产，对应的进项税额依照增值税法和下列规定处理："},{"i":26,"n":"第二十六条","txt":"增值税法第二十四条第一款第一项所称农业生产者，是指从事农业生产的单位和个人；农产品，是指初级农产品。"},{"i":27,"n":"第二十七条","txt":"增值税法第二十四条第一款第二项所称医疗机构，是指依据有关规定设立的具有医疗机构执业资格的机构，包括军队、武警部队各级各类医疗机构，不包括营利性美容医疗机构。"},{"i":28,"n":"第二十八条","txt":"增值税法第二十四条第一款第三项所称古旧图书，是指向社会收购的古书和旧书。"},{"i":29,"n":"第二十九条","txt":"增值税法第二十四条第一款第七项所称托儿所、幼儿园，是指依据有关规定设立的取得托育或者学前教育资格的机构，其免征增值税的收入是指有关收费标准规定以内的保育费、保育教育费；养老机构，是指依据有关规定设立的为老年人提供集中住宿和照料护理服务的各类养老机构；残疾人服务机构，是指依据有关规定设立的专门为残疾人提供相关服务的机构。"},{"i":30,"n":"第三十条","txt":"增值税法第二十四条第一款第八项所称学校，是指依据有关规定设立的提供学历教育的机构，以及技工学校、高级技工学校、技师学院。"},{"i":31,"n":"第三十一条","txt":"增值税法第二十四条第一款第九项所称门票收入，是指第一道门票收入。"},{"i":32,"n":"第三十二条","txt":"增值税优惠政策的适用范围、标准、条件等应当依法及时向社会公开。"},{"i":33,"n":"第三十三条","txt":"国务院财政、税务主管部门应当适时研究和评估增值税优惠政策执行效果，对不再适应国民经济和社会发展需要的优惠政策，及时报请国务院予以调整完善。"},{"i":34,"n":"第三十四条","txt":"单位以承包、承租、挂靠方式经营，承包人、承租人、挂靠人以发包人、出租人、被挂靠人名义对外经营并由发包人、出租人、被挂靠人承担相关法律责任的，发包人、出租人、被挂靠人为纳税人；其他情形下，承包人、承租人、挂靠人为纳税人。"},{"i":35,"n":"第三十五条","txt":"自然人发生符合规定的应税交易，支付价款的境内单位为扣缴义务人。代扣代缴的具体操作办法，由国务院财政、税务主管部门制定。"},{"i":36,"n":"第三十六条","txt":"除本条例另有规定外，单位和个体工商户年应征增值税销售额超过小规模纳税人标准的，应当向主管税务机关办理一般纳税人登记，并自超过小规模纳税人标准的当期起按照一般计税方法计算缴纳增值税。"},{"i":37,"n":"第三十七条","txt":"纳税人发生应税交易，应当向购买方开具发票。有下列情形之一的，不得开具增值税专用发票："},{"i":38,"n":"第三十八条","txt":"纳税人发生应税交易，开具增值税专用发票后，发生开票有误或者销售折让、中止、退回等情形的，应当按照国务院税务主管部门的规定进行作废处理或者开具红字增值税专用发票；未按规定进行作废处理或者开具红字增值税专用发票的，不得依照本条例第十三条和第十四条的规定扣减销项税额或者销售额。"},{"i":39,"n":"第三十九条","txt":"增值税法第二十八条第一款第一项所称收讫销售款项，是指纳税人发生应税交易过程中或者完成后收到款项；取得销售款项索取凭据的当日，是指书面合同确定的付款日期，未签订书面合同或者书面合同未确定付款日期的，是指应税交易完成的当日，即货物发出、服务完成、金融商品所有权转移、无形资产转让完成或者不动产转让完成的当日。"},{"i":40,"n":"第四十条","txt":"增值税法第二十八条第一款第二项所称完成视同应税交易的当日，是指货物发出、金融商品所有权转移、无形资产转让完成或者不动产转让完成的当日。"},{"i":41,"n":"第四十一条","txt":"纳税人出口货物，报关出口日期早于增值税法第二十八条第一款第一项、第二项规定的纳税义务发生时间的，纳税义务发生时间为货物报关出口的当日。"},{"i":42,"n":"第四十二条","txt":"增值税法第二十九条第一项所称经省级以上财政、税务主管部门批准可以由总机构汇总申报纳税，是指有固定生产经营场所的纳税人，总机构和分支机构不在同一省（自治区、直辖市）内的，经国务院财政、税务主管部门批准，可以由总机构汇总向总机构所在地的主管税务机关申报纳税；总机构和分支机构在同一省（自治区、直辖市）内但不在同一县（市、区、旗）内的，经省（自治区、直辖市）财政、税务主管部门批准，可以由总机构汇总向总机构所在地的主管税务机关申报纳税。"},{"i":43,"n":"第四十三条","txt":"下列纳税人可以适用增值税法第三十条规定的以一个季度为一个计税期间："},{"i":44,"n":"第四十四条","txt":"按次纳税的纳税人，销售额达到起征点的，应当自纳税义务发生之日起至次年6月30日前申报纳税。"},{"i":45,"n":"第四十五条","txt":"下列情形应当按规定预缴税款："},{"i":46,"n":"第四十六条","txt":"经省级以上财政、税务主管部门批准由总机构汇总申报纳税的，批准部门可以规定由分支机构预缴税款。"},{"i":47,"n":"第四十七条","txt":"纳税人出口货物或者跨境销售服务、无形资产（以下统称出口业务），依照增值税法第三十三条的规定申报办理退（免）税的，按照国务院规定的出口退税率，通过免抵退税办法或者免退税办法计算退（免）税额，经税务机关审核通过后，办理退（免）税。"},{"i":48,"n":"第四十八条","txt":"纳税人适用退（免）税、免征增值税的出口业务，应当按照规定期限申报；逾期未申报的，按照视同向境内销售的规定缴纳增值税。"},{"i":49,"n":"第四十九条","txt":"纳税人适用退（免）税的出口业务，可以放弃退（免）税，选择免征增值税或者缴纳增值税，自放弃退（免）税之日次月起，适用退（免）税的出口业务免征增值税或者按规定缴纳增值税。"},{"i":50,"n":"第五十条","txt":"办理退（免）税的出口业务发生销售折让、中止或者退回等情形的，纳税人应当缴回已退（免）税款。"},{"i":51,"n":"第五十一条","txt":"增值税出口退（免）税的具体操作办法，由国务院财政、税务主管部门制定。"},{"i":52,"n":"第五十二条","txt":"税务机关可以依法向有关单位和个人获取与出口税收征收管理相关的物流、报关、货物运输代理、资金结算等信息，有关单位和个人应当予以提供。税务机关及其工作人员应当对相关信息予以保密，不得用于税收征收管理以外的用途。法律、行政法规另有规定的，从其规定。"},{"i":53,"n":"第五十三条","txt":"纳税人实施不具有合理商业目的的安排而减少、免除、推迟缴纳增值税税款，或者提前退税、多退税款的，税务机关可以依照《中华人民共和国税收征收管理法》和有关行政法规的规定予以调整。"},{"i":54,"n":"第五十四条","txt":"本条例自2026年1月1日起施行。"}],"waishangtouzifashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国外商投资法》（以下简称外商投资法），制定本条例。"},{"i":2,"n":"第二条","txt":"国家鼓励和促进外商投资，保护外商投资合法权益，规范外商投资管理，持续优化外商投资环境，推进更高水平对外开放。"},{"i":3,"n":"第三条","txt":"外商投资法第二条第二款第一项、第三项所称其他投资者，包括中国的自然人在内。"},{"i":4,"n":"第四条","txt":"外商投资准入负面清单（以下简称负面清单）由国务院投资主管部门会同国务院商务主管部门等有关部门提出，报国务院发布或者报国务院批准后由国务院投资主管部门、商务主管部门发布。"},{"i":5,"n":"第五条","txt":"国务院商务主管部门、投资主管部门以及其他有关部门按照职责分工，密切配合、相互协作，共同做好外商投资促进、保护和管理工作。"},{"i":6,"n":"第六条","txt":"政府及其有关部门在政府资金安排、土地供应、税费减免、资质许可、标准制定、项目申报、人力资源政策等方面，应当依法平等对待外商投资企业和内资企业。"},{"i":7,"n":"第七条","txt":"制定与外商投资有关的行政法规、规章、规范性文件，或者政府及其有关部门起草与外商投资有关的法律、地方性法规，应当根据实际情况，采取书面征求意见以及召开座谈会、论证会、听证会等多种形式，听取外商投资企业和有关商会、协会等方面的意见和建议；对反映集中或者涉及外商投资企业重大权利义务问题的意见和建议，应当通过适当方式反馈采纳的情况。"},{"i":8,"n":"第八条","txt":"各级人民政府应当按照政府主导、多方参与的原则，建立健全外商投资服务体系，不断提升外商投资服务能力和水平。"},{"i":9,"n":"第九条","txt":"政府及其有关部门应当通过政府网站、全国一体化在线政务服务平台集中列明有关外商投资的法律、法规、规章、规范性文件、政策措施和投资项目信息，并通过多种途径和方式加强宣传、解读，为外国投资者和外商投资企业提供咨询、指导等服务。"},{"i":10,"n":"第十条","txt":"外商投资法第十三条所称特殊经济区域，是指经国家批准设立、实行更大力度的对外开放政策措施的特定区域。"},{"i":11,"n":"第十一条","txt":"国家根据国民经济和社会发展需要，制定鼓励外商投资产业目录，列明鼓励和引导外国投资者投资的特定行业、领域、地区。鼓励外商投资产业目录由国务院投资主管部门会同国务院商务主管部门等有关部门拟订，报国务院批准后由国务院投资主管部门、商务主管部门发布。"},{"i":12,"n":"第十二条","txt":"外国投资者、外商投资企业可以依照法律、行政法规或者国务院的规定，享受财政、税收、金融、用地等方面的优惠待遇。"},{"i":13,"n":"第十三条","txt":"外商投资企业依法和内资企业平等参与国家标准、行业标准、地方标准和团体标准的制定、修订工作。外商投资企业可以根据需要自行制定或者与其他企业联合制定企业标准。"},{"i":14,"n":"第十四条","txt":"国家制定的强制性标准对外商投资企业和内资企业平等适用，不得专门针对外商投资企业适用高于强制性标准的技术要求。"},{"i":15,"n":"第十五条","txt":"政府及其有关部门不得阻挠和限制外商投资企业自由进入本地区和本行业的政府采购市场。"},{"i":16,"n":"第十六条","txt":"外商投资企业可以依照《中华人民共和国政府采购法》（以下简称政府采购法）及其实施条例的规定，就政府采购活动事项向采购人、采购代理机构提出询问、质疑，向政府采购监督管理部门投诉。采购人、采购代理机构、政府采购监督管理部门应当在规定的时限内作出答复或者处理决定。"},{"i":17,"n":"第十七条","txt":"政府采购监督管理部门和其他有关部门应当加强对政府采购活动的监督检查，依法纠正和查处对外商投资企业实行差别待遇或者歧视待遇等违法违规行为。"},{"i":18,"n":"第十八条","txt":"外商投资企业可以依法在中国境内或者境外通过公开发行股票、公司债券等证券，以及公开或者非公开发行其他融资工具、借用外债等方式进行融资。"},{"i":19,"n":"第十九条","txt":"县级以上地方人民政府可以根据法律、行政法规、地方性法规的规定，在法定权限内制定费用减免、用地指标保障、公共服务提供等方面的外商投资促进和便利化政策措施。"},{"i":20,"n":"第二十条","txt":"有关主管部门应当编制和公布外商投资指引，为外国投资者和外商投资企业提供服务和便利。外商投资指引应当包括投资环境介绍、外商投资办事指南、投资项目信息以及相关数据信息等内容，并及时更新。"},{"i":21,"n":"第二十一条","txt":"国家对外国投资者的投资不实行征收。"},{"i":22,"n":"第二十二条","txt":"外国投资者在中国境内的出资、利润、资本收益、资产处置所得、取得的知识产权许可使用费、依法获得的补偿或者赔偿、清算所得等，可以依法以人民币或者外汇自由汇入、汇出，任何单位和个人不得违法对币种、数额以及汇入、汇出的频次等进行限制。"},{"i":23,"n":"第二十三条","txt":"国家加大对知识产权侵权行为的惩处力度，持续强化知识产权执法，推动建立知识产权快速协同保护机制，健全知识产权纠纷多元化解决机制，平等保护外国投资者和外商投资企业的知识产权。"},{"i":24,"n":"第二十四条","txt":"行政机关（包括法律、法规授权的具有管理公共事务职能的组织，下同）及其工作人员不得利用实施行政许可、行政检查、行政处罚、行政强制以及其他行政手段，强制或者变相强制外国投资者、外商投资企业转让技术。"},{"i":25,"n":"第二十五条","txt":"行政机关依法履行职责，确需外国投资者、外商投资企业提供涉及商业秘密的材料、信息的，应当限定在履行职责所必需的范围内，并严格控制知悉范围，与履行职责无关的人员不得接触有关材料、信息。"},{"i":26,"n":"第二十六条","txt":"政府及其有关部门制定涉及外商投资的规范性文件，应当按照国务院的规定进行合法性审核。"},{"i":27,"n":"第二十七条","txt":"外商投资法第二十五条所称政策承诺，是指地方各级人民政府及其有关部门在法定权限内，就外国投资者、外商投资企业在本地区投资所适用的支持政策、享受的优惠待遇和便利条件等作出的书面承诺。政策承诺的内容应当符合法律、法规规定。"},{"i":28,"n":"第二十八条","txt":"地方各级人民政府及其有关部门应当履行向外国投资者、外商投资企业依法作出的政策承诺以及依法订立的各类合同，不得以行政区划调整、政府换届、机构或者职能调整以及相关责任人更替等为由违约毁约。因国家利益、社会公共利益需要改变政策承诺、合同约定的，应当依照法定权限和程序进行，并依法对外国投资者、外商投资企业因此受到的损失及时予以公平、合理的补偿。"},{"i":29,"n":"第二十九条","txt":"县级以上人民政府及其有关部门应当按照公开透明、高效便利的原则，建立健全外商投资企业投诉工作机制，及时处理外商投资企业或者其投资者反映的问题，协调完善相关政策措施。"},{"i":30,"n":"第三十条","txt":"外商投资企业或者其投资者认为行政机关及其工作人员的行政行为侵犯其合法权益，通过外商投资企业投诉工作机制申请协调解决的，有关方面进行协调时可以向被申请的行政机关及其工作人员了解情况，被申请的行政机关及其工作人员应当予以配合。协调结果应当以书面形式及时告知申请人。"},{"i":31,"n":"第三十一条","txt":"对外商投资企业或者其投资者通过外商投资企业投诉工作机制反映或者申请协调解决问题，任何单位和个人不得压制或者打击报复。"},{"i":32,"n":"第三十二条","txt":"外商投资企业可以依法成立商会、协会。除法律、法规另有规定外，外商投资企业有权自主决定参加或者退出商会、协会，任何单位和个人不得干预。"},{"i":33,"n":"第三十三条","txt":"负面清单规定禁止投资的领域，外国投资者不得投资。负面清单规定限制投资的领域，外国投资者进行投资应当符合负面清单规定的股权要求、高级管理人员要求等限制性准入特别管理措施。"},{"i":34,"n":"第三十四条","txt":"有关主管部门在依法履行职责过程中，对外国投资者拟投资负面清单内领域，但不符合负面清单规定的，不予办理许可、企业登记注册等相关事项；涉及固定资产投资项目核准的，不予办理相关核准事项。"},{"i":35,"n":"第三十五条","txt":"外国投资者在依法需要取得许可的行业、领域进行投资的，除法律、行政法规另有规定外，负责实施许可的有关主管部门应当按照与内资一致的条件和程序，审核外国投资者的许可申请，不得在许可条件、申请材料、审核环节、审核时限等方面对外国投资者设置歧视性要求。"},{"i":36,"n":"第三十六条","txt":"外商投资需要办理投资项目核准、备案的，按照国家有关规定执行。"},{"i":37,"n":"第三十七条","txt":"外商投资企业的登记注册，由国务院市场监督管理部门或者其授权的地方人民政府市场监督管理部门依法办理。国务院市场监督管理部门应当公布其授权的市场监督管理部门名单。"},{"i":38,"n":"第三十八条","txt":"外国投资者或者外商投资企业应当通过企业登记系统以及企业信用信息公示系统向商务主管部门报送投资信息。国务院商务主管部门、市场监督管理部门应当做好相关业务系统的对接和工作衔接，并为外国投资者或者外商投资企业报送投资信息提供指导。"},{"i":39,"n":"第三十九条","txt":"外商投资信息报告的内容、范围、频次和具体流程，由国务院商务主管部门会同国务院市场监督管理部门等有关部门按照确有必要、高效便利的原则确定并公布。商务主管部门、其他有关部门应当加强信息共享，通过部门信息共享能够获得的投资信息，不得再行要求外国投资者或者外商投资企业报送。"},{"i":40,"n":"第四十条","txt":"国家建立外商投资安全审查制度，对影响或者可能影响国家安全的外商投资进行安全审查。"},{"i":41,"n":"第四十一条","txt":"政府和有关部门及其工作人员有下列情形之一的，依法依规追究责任："},{"i":42,"n":"第四十二条","txt":"政府采购的采购人、采购代理机构以不合理的条件对外商投资企业实行差别待遇或者歧视待遇的，依照政府采购法及其实施条例的规定追究其法律责任；影响或者可能影响中标、成交结果的，依照政府采购法及其实施条例的规定处理。"},{"i":43,"n":"第四十三条","txt":"行政机关及其工作人员利用行政手段强制或者变相强制外国投资者、外商投资企业转让技术的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":44,"n":"第四十四条","txt":"外商投资法施行前依照《中华人民共和国中外合资经营企业法》、《中华人民共和国外资企业法》、《中华人民共和国中外合作经营企业法》设立的外商投资企业（以下称现有外商投资企业），在外商投资法施行后5年内，可以依照《中华人民共和国公司法》、《中华人民共和国合伙企业法》等法律的规定调整其组织形式、组织机构等，并依法办理变更登记，也可以继续保留原企业组织形式、组织机构等。"},{"i":45,"n":"第四十五条","txt":"现有外商投资企业办理组织形式、组织机构等变更登记的具体事宜，由国务院市场监督管理部门规定并公布。国务院市场监督管理部门应当加强对变更登记工作的指导，负责办理变更登记的市场监督管理部门应当通过多种方式优化服务，为企业办理变更登记提供便利。"},{"i":46,"n":"第四十六条","txt":"现有外商投资企业的组织形式、组织机构等依法调整后，原合营、合作各方在合同中约定的股权或者权益转让办法、收益分配办法、剩余财产分配办法等，可以继续按照约定办理。"},{"i":47,"n":"第四十七条","txt":"外商投资企业在中国境内投资，适用外商投资法和本条例的有关规定。"},{"i":48,"n":"第四十八条","txt":"香港特别行政区、澳门特别行政区投资者在内地投资，参照外商投资法和本条例执行；法律、行政法规或者国务院另有规定的，从其规定。"},{"i":49,"n":"第四十九条","txt":"本条例自2020年1月1日起施行。《中华人民共和国中外合资经营企业法实施条例》、《中外合资经营企业合营期限暂行规定》、《中华人民共和国外资企业法实施细则》、《中华人民共和国中外合作经营企业法实施细则》同时废止。"}],"shenjifashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国审计法》（以下简称审计法）的规定，制定本条例。"},{"i":2,"n":"第二条","txt":"审计法所称审计，是指审计机关依法独立检查被审计单位的会计凭证、会计账簿、财务会计报告以及其他与财政收支、财务收支有关的资料和资产，监督财政收支、财务收支真实、合法和效益的行为。"},{"i":3,"n":"第三条","txt":"审计法所称财政收支，是指依照《中华人民共和国预算法》和国家其他有关规定，纳入预算管理的收入和支出，以及下列财政资金中未纳入预算管理的收入和支出："},{"i":4,"n":"第四条","txt":"审计法所称财务收支，是指国有的金融机构、企业事业组织以及依法应当接受审计机关审计监督的其他单位，按照国家财务会计制度的规定，实行会计核算的各项收入和支出。"},{"i":5,"n":"第五条","txt":"审计机关依照审计法和本条例以及其他有关法律、法规规定的职责、权限和程序进行审计监督。"},{"i":6,"n":"第六条","txt":"任何单位和个人对依法应当接受审计机关审计监督的单位违反国家规定的财政收支、财务收支行为，有权向审计机关举报。审计机关接到举报，应当依法及时处理。"},{"i":7,"n":"第七条","txt":"审计署在国务院总理领导下，主管全国的审计工作，履行审计法和国务院规定的职责。"},{"i":8,"n":"第八条","txt":"省、自治区人民政府设有派出机关的，派出机关的审计机关对派出机关和省、自治区人民政府审计机关负责并报告工作，审计业务以省、自治区人民政府审计机关领导为主。"},{"i":9,"n":"第九条","txt":"审计机关派出机构依照法律、法规和审计机关的规定，在审计机关的授权范围内开展审计工作，不受其他行政机关、社会团体和个人的干涉。"},{"i":10,"n":"第十条","txt":"审计机关编制年度经费预算草案的依据主要包括："},{"i":11,"n":"第十一条","txt":"审计人员实行审计专业技术资格制度，具体按照国家有关规定执行。"},{"i":12,"n":"第十二条","txt":"审计人员办理审计事项，有下列情形之一的，应当申请回避，被审计单位也有权申请审计人员回避："},{"i":13,"n":"第十三条","txt":"地方各级审计机关正职和副职负责人的任免，应当事先征求上一级审计机关的意见。"},{"i":14,"n":"第十四条","txt":"审计机关负责人在任职期间没有下列情形之一的，不得随意撤换："},{"i":15,"n":"第十五条","txt":"审计机关对本级人民政府财政部门具体组织本级预算执行的情况，本级预算收入征收部门征收预算收入的情况，与本级人民政府财政部门直接发生预算缴款、拨款关系的部门、单位的预算执行情况和决算，下级人民政府的预算执行情况和决算，以及其他财政收支情况，依法进行审计监督。经本级人民政府批准，审计机关对其他取得财政资金的单位和项目接受、运用财政资金的真实、合法和效益情况，依法进行审计监督。"},{"i":16,"n":"第十六条","txt":"审计机关对本级预算收入和支出的执行情况进行审计监督的内容包括："},{"i":17,"n":"第十七条","txt":"审计法第十七条所称审计结果报告，应当包括下列内容："},{"i":18,"n":"第十八条","txt":"审计署对中央银行及其分支机构履行职责所发生的各项财务收支，依法进行审计监督。"},{"i":19,"n":"第十九条","txt":"审计法第二十一条所称国有资本占控股地位或者主导地位的企业、金融机构，包括："},{"i":20,"n":"第二十条","txt":"审计法第二十二条所称政府投资和以政府投资为主的建设项目，包括："},{"i":21,"n":"第二十一条","txt":"审计法第二十三条所称社会保障基金，包括社会保险、社会救助、社会福利基金以及发展社会保障事业的其他专项基金；所称社会捐赠资金，包括来源于境内外的货币、有价证券和实物等各种形式的捐赠。"},{"i":22,"n":"第二十二条","txt":"审计法第二十四条所称国际组织和外国政府援助、贷款项目，包括："},{"i":23,"n":"第二十三条","txt":"审计机关可以依照审计法和本条例规定的审计程序、方法以及国家其他有关规定，对预算管理或者国有资产管理使用等与国家财政收支有关的特定事项，向有关地方、部门、单位进行专项审计调查。"},{"i":24,"n":"第二十四条","txt":"审计机关根据被审计单位的财政、财务隶属关系，确定审计管辖范围；不能根据财政、财务隶属关系确定审计管辖范围的，根据国有资产监督管理关系，确定审计管辖范围。"},{"i":25,"n":"第二十五条","txt":"各级审计机关应当按照确定的审计管辖范围进行审计监督。"},{"i":26,"n":"第二十六条","txt":"依法属于审计机关审计监督对象的单位的内部审计工作，应当接受审计机关的业务指导和监督。"},{"i":27,"n":"第二十七条","txt":"审计机关进行审计或者专项审计调查时，有权对社会审计机构出具的相关审计报告进行核查。"},{"i":28,"n":"第二十八条","txt":"审计机关依法进行审计监督时，被审计单位应当依照审计法第三十一条规定，向审计机关提供与财政收支、财务收支有关的资料。被审计单位负责人应当对本单位提供资料的真实性和完整性作出书面承诺。"},{"i":29,"n":"第二十九条","txt":"各级人民政府财政、税务以及其他部门（含直属单位）应当向本级审计机关报送下列资料："},{"i":30,"n":"第三十条","txt":"审计机关依照审计法第三十三条规定查询被审计单位在金融机构的账户的，应当持县级以上人民政府审计机关负责人签发的协助查询单位账户通知书；查询被审计单位以个人名义在金融机构的存款的，应当持县级以上人民政府审计机关主要负责人签发的协助查询个人存款通知书。有关金融机构应当予以协助，并提供证明材料，审计机关和审计人员负有保密义务。"},{"i":31,"n":"第三十一条","txt":"审计法第三十四条所称违反国家规定取得的资产，包括："},{"i":32,"n":"第三十二条","txt":"审计机关依照审计法第三十四条规定封存被审计单位有关资料和违反国家规定取得的资产的，应当持县级以上人民政府审计机关负责人签发的封存通知书，并在依法收集与审计事项相关的证明材料或者采取其他措施后解除封存。封存的期限为7日以内；有特殊情况需要延长的，经县级以上人民政府审计机关负责人批准，可以适当延长，但延长的期限不得超过7日。"},{"i":33,"n":"第三十三条","txt":"审计机关依照审计法第三十六条规定，可以就有关审计事项向政府有关部门通报或者向社会公布对被审计单位的审计、专项审计调查结果。"},{"i":34,"n":"第三十四条","txt":"审计机关应当根据法律、法规和国家其他有关规定，按照本级人民政府和上级审计机关的要求，确定年度审计工作重点，编制年度审计项目计划。"},{"i":35,"n":"第三十五条","txt":"审计机关应当根据年度审计项目计划，组成审计组，调查了解被审计单位的有关情况，编制审计方案，并在实施审计3日前，向被审计单位送达审计通知书。"},{"i":36,"n":"第三十六条","txt":"审计法第三十八条所称特殊情况，包括："},{"i":37,"n":"第三十七条","txt":"审计人员实施审计时，应当按照下列规定办理："},{"i":38,"n":"第三十八条","txt":"审计人员向有关单位和个人调查取得的证明材料，应当有提供者的签名或者盖章；不能取得提供者签名或者盖章的，审计人员应当注明原因。"},{"i":39,"n":"第三十九条","txt":"审计组向审计机关提出审计报告前，应当书面征求被审计单位意见。被审计单位应当自接到审计组的审计报告之日起10日内，提出书面意见；10日内未提出书面意见的，视同无异议。"},{"i":40,"n":"第四十条","txt":"审计机关有关业务机构和专门机构或者人员对审计组的审计报告以及相关审计事项进行复核、审理后，由审计机关按照下列规定办理："},{"i":41,"n":"第四十一条","txt":"审计机关在审计中发现损害国家利益和社会公共利益的事项，但处理、处罚依据又不明确的，应当向本级人民政府和上一级审计机关报告。"},{"i":42,"n":"第四十二条","txt":"被审计单位应当按照审计机关规定的期限和要求执行审计决定。对应当上缴的款项，被审计单位应当按照财政管理体制和国家有关规定缴入国库或者财政专户。审计决定需要有关主管机关、单位协助执行的，审计机关应当书面提请协助执行。"},{"i":43,"n":"第四十三条","txt":"上级审计机关应当对下级审计机关的审计业务依法进行监督。"},{"i":44,"n":"第四十四条","txt":"审计机关进行专项审计调查时，应当向被调查的地方、部门、单位出示专项审计调查的书面通知，并说明有关情况；有关地方、部门、单位应当接受调查，如实反映情况，提供有关资料。"},{"i":45,"n":"第四十五条","txt":"审计机关应当按照国家有关规定建立、健全审计档案制度。"},{"i":46,"n":"第四十六条","txt":"审计机关送达审计文书，可以直接送达，也可以邮寄送达或者以其他方式送达。直接送达的，以被审计单位在送达回证上注明的签收日期或者见证人证明的收件日期为送达日期；邮寄送达的，以邮政回执上注明的收件日期为送达日期；以其他方式送达的，以签收或者收件日期为送达日期。"},{"i":47,"n":"第四十七条","txt":"被审计单位违反审计法和本条例的规定，拒绝、拖延提供与审计事项有关的资料，或者提供的资料不真实、不完整，或者拒绝、阻碍检查的，由审计机关责令改正，可以通报批评，给予警告；拒不改正的，对被审计单位可以处5万元以下的罚款，对直接负责的主管人员和其他直接责任人员，可以处2万元以下的罚款，审计机关认为应当给予处分的，向有关主管机关、单位提出给予处分的建议；构成犯罪的，依法追究刑事责任。"},{"i":48,"n":"第四十八条","txt":"对本级各部门（含直属单位）和下级人民政府违反预算的行为或者其他违反国家规定的财政收支行为，审计机关在法定职权范围内，依照法律、行政法规的规定，区别情况采取审计法第四十五条规定的处理措施。"},{"i":49,"n":"第四十九条","txt":"对被审计单位违反国家规定的财务收支行为，审计机关在法定职权范围内，区别情况采取审计法第四十五条规定的处理措施，可以通报批评，给予警告；有违法所得的，没收违法所得，并处违法所得1倍以上5倍以下的罚款；没有违法所得的，可以处5万元以下的罚款；对直接负责的主管人员和其他直接责任人员，可以处2万元以下的罚款，审计机关认为应当给予处分的，向有关主管机关、单位提出给予处分的建议；构成犯罪的，依法追究刑事责任。"},{"i":50,"n":"第五十条","txt":"审计机关在作出较大数额罚款的处罚决定前，应当告知被审计单位和有关人员有要求举行听证的权利。较大数额罚款的具体标准由审计署规定。"},{"i":51,"n":"第五十一条","txt":"审计机关提出的对被审计单位给予处理、处罚的建议以及对直接负责的主管人员和其他直接责任人员给予处分的建议，有关主管机关、单位应当依法及时作出决定，并将结果书面通知审计机关。"},{"i":52,"n":"第五十二条","txt":"被审计单位对审计机关依照审计法第十六条、第十七条和本条例第十五条规定进行审计监督作出的审计决定不服的，可以自审计决定送达之日起60日内，提请审计机关的本级人民政府裁决，本级人民政府的裁决为最终决定。"},{"i":53,"n":"第五十三条","txt":"除本条例第五十二条规定的可以提请裁决的审计决定外，被审计单位对审计机关作出的其他审计决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":54,"n":"第五十四条","txt":"被审计单位应当将审计决定执行情况书面报告审计机关。审计机关应当检查审计决定的执行情况。"},{"i":55,"n":"第五十五条","txt":"审计人员滥用职权、徇私舞弊、玩忽职守，或者泄露所知悉的国家秘密、商业秘密的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":56,"n":"第五十六条","txt":"本条例所称以上、以下，包括本数。"},{"i":57,"n":"第五十七条","txt":"实施经济责任审计的规定，另行制定。"},{"i":58,"n":"第五十八条","txt":"本条例自2010年5月1日起施行。"}],"duiwaiguojichuanboguanliguize":[{"i":1,"n":"第一条","txt":"为维护中华人民共和国的主权，维持港口和沿海水域的秩序，保证航行安全，防止水域污染，特制定本规则。"},{"i":2,"n":"第二条","txt":"在中华人民共和国港口和沿海水域航行的外国籍船舶（以下简称船舶）应遵守本规则以及中华人民共和国一切有关法令、规章和规定。中华人民共和国政府设置在港口的港务监督认为有必要对船舶进行检查时，船舶应接受检查。"},{"i":3,"n":"第三条","txt":"船长或船舶所有人应在船舶预定到达港口一星期之前，通过外轮代理公司填具规定的表报，向港务监督办理进口申请批准手续，并在到达港口之前二十四小时（航程不足二十四小时的，在驶离前一港口时），将预计到港时间，前、后吃水等情况通过外轮代理公司向港务监督报告。如预计到港时间有变化，应随时报告。船舶在航行途中，因遇险、发生故障、船员或旅客患急病等特殊情况，需临时进港或返航，应事先向港务监督报告。"},{"i":4,"n":"第四条","txt":"船舶进出港口或在港内航行、移泊，必须由港务监督指派引航员引航。有关引航的具体事项，应按照中华人民共和国交通部颁发的《海港引航工作规定》办理。"},{"i":5,"n":"第五条","txt":"船舶抵港后，应即呈报进口报告书及其它有关表报，同时交验船舶证书及有关文书，并接受检查。船舶出港前，应呈报出口报告书及其它有关表报，经检查发给出口许可证后，才可出口。"},{"i":6,"n":"第六条","txt":"船舶上的武器、弹药，应在船舶抵港后由港务监督予以封存。无线电报发射机、无线电话发射机、火箭信号、火焰信号、信号枪，只有在危急情况下才可以使用，但在使用后必须向港务监督报告。"},{"i":7,"n":"第七条","txt":"港内禁止射击、游泳、钓鱼、鸣放鞭炮或焰火以及其它危及港口安全秩序的行为。"},{"i":8,"n":"第八条","txt":"船舶有下列情况之一者，港务监督有权在一定期间内禁止其出港或令其停航、改航、返航："},{"i":9,"n":"第九条","txt":"航行在中华人民共和国港口和沿海水域的船舶，不得进行危害中华人民共和国安全和权益的活动，并应遵守有关海峡、水道、航线和禁航区的规定。"},{"i":10,"n":"第十条","txt":"船舶在港内不得以危及其它船舶和港口设施安全的速度航行。"},{"i":11,"n":"第十一条","txt":"船舶附属的艇（筏），除了救生以外，不准在港内航行。"},{"i":12,"n":"第十二条","txt":"船舶在港内航行、移泊时，船上的艇（筏）、吊货杆和舷梯等，不得伸出舷外。"},{"i":13,"n":"第十三条","txt":"需要进入中华人民共和国对外轮开放的港口避风或临时停泊的船舶应向港务监督申请批准，申请内容包括：船名、呼号、国籍、船公司名称、出发港、目的港、船位、航速、吃水、船体颜色、烟囱颜色和标志，并应在指定的地点避风。"},{"i":14,"n":"第十四条","txt":"船舶在港内停泊，必须留有足以保证船舶安全操纵的船员值班，遇有台风警报等紧急情况，全体船员必须立即回船采取防范、应急等措施。"},{"i":15,"n":"第十五条","txt":"船舶在船员、旅客和其他人员上下之处设置的舷梯必须稳固，并有栏杆或攀索，软梯必须牢固安全，夜间应有足够的照明。"},{"i":16,"n":"第十六条","txt":"船舶需要活车时，必须注意尾部周围环境，在不危及其他船舶和港口设施安全的情况下才可进行。"},{"i":17,"n":"第十七条","txt":"停泊在港内的船舶，其两舷可能影响其他船舶、码头或人员上下的出水口必须加盖复罩。"},{"i":18,"n":"第十八条","txt":"船舶的灯光不得影响其他船舶的航行安全，船上射向航道的强灯光，应予以遮蔽。"},{"i":19,"n":"第十九条","txt":"船舶对装卸操作应提供安全良好的条件，装卸设备应具有合格证书，保持良好的技术状态。"},{"i":20,"n":"第二十条","txt":"船舶进行下列事项，应事先向港务监督申请批准："},{"i":21,"n":"第二十一条","txt":"船舶熏蒸，应采取严密的安全措施，并应悬挂港口规定的信号。"},{"i":22,"n":"第二十二条","txt":"为了维护港口和船舶的安全，需要在港内的船舶移泊或提前、推迟开航，船舶应遵守港务监督的决定。"},{"i":23,"n":"第二十三条","txt":"船舶在中华人民共和国港口和沿海水域航行、停泊，白天应悬挂船籍国的国旗，进出港口和移泊应加挂船名呼号旗和港口规定的有关信号。"},{"i":24,"n":"第二十四条","txt":"船舶在进出港口和锚泊时，应注意港口信号台的呼号和信号，在使用视觉信号时，应遵守中华人民共和国沿海港口信号规定。沿海港口未曾规定的信号，应依照《国际信号规则》办理。"},{"i":25,"n":"第二十五条","txt":"船舶在港内除因航行安全必须外，不得随意鸣放声号。需要试笛时，应事先向港务监督报告。"},{"i":26,"n":"第二十六条","txt":"船舶在港内使用甚高频无线电话，应遵守中华人民共和国交通部颁发的《关于外轮使用甚高频无线电话暂行办法》。"},{"i":27,"n":"第二十七条","txt":"船舶装卸、载运危险货物，应悬挂规定的信号，遵守有关危险货物运输管理的规定，采取必要的安全措施，特别是性能相抵触的货物，不许混装，严禁爆炸物品与发火物、易燃物品装载于同一舱内。"},{"i":28,"n":"第二十八条","txt":"船舶载运爆炸物品、剧毒物品、放射性物品、压缩气体和液化气体、氧化剂、自燃物品、遇水燃烧物品、易燃液体、易燃固体和酸性腐蚀物品等一级烈性危险货物，应详细列具品名、性质、包装数量和装载位置，并且附具危险货物性质说明书，在预定到达港口三天之前，通过外轮代理公司向港务监督申请办理签证，经许可后才可进港、起卸或者过境。出口船舶载运上述危险货物，应在开始装载的三天以前，申请办理签证，经许可后才可装运。"},{"i":29,"n":"第二十九条","txt":"船舶申请签发装运出口危险货物安全装载证明书，应在开始装载三天之前向港务监督提出书面申请，写明危险货物的品名、性质、包装、数量、装载位置（并且附具货物装载图）、中途港和目的港等事项并在港务监督指定的泊位进行装载。"},{"i":30,"n":"第三十条","txt":"船舶航行应遵守航行规定，维护航行秩序，如船舶发生意外事故有沉没危险时，应立即向港务监督报告，并尽力采取有效措施，驶离航道，避免妨碍交通和危及其他船舶。如果船舶已经沉没，船方应及时在沉没地点设置临时信号标志。"},{"i":31,"n":"第三十一条","txt":"对沉没在港口或沿海水域的船舶或其他物体的打捞，均按照《中华人民共和国打捞沉船、沉物管理办法》办理。港务监督可视具体情况，通知沉船沉物所有人限期打捞清除，或立即组织打捞或解体清除，全部责任和费用应由沉船沉物所有人承担。"},{"i":32,"n":"第三十二条","txt":"船舶发现或捞获沉、浮物体，应报告或送交港务监督处理，由港务监督酌情给予奖励。"},{"i":33,"n":"第三十三条","txt":"船舶在港内需要倾倒垃圾等废弃物，应显示港口规定的信号招用垃圾船（车）。"},{"i":34,"n":"第三十四条","txt":"船舶应爱护航道设备和助航标志，如损坏了助航标志、港口建筑或其他设施，应立即向港务监督报告，并应负责恢复原状或偿付恢复原状所需费用。"},{"i":35,"n":"第三十五条","txt":"在中华人民共和国的港口和沿海水域，禁止船舶任意排放油类、油性混合物，以及其他有害的污染物质和废弃物。"},{"i":36,"n":"第三十六条","txt":"船舶排放压舱水、洗舱水、舱底水，必须向港务监督申请批准。如果船舶来自有疫情的港口，应经过卫生检疫机关卫生处理。装运危险货物和其他有害污染物船舱的污水、洗舱水，应经有关卫生部门鉴定合格后，方可在指定地点排放。"},{"i":37,"n":"第三十七条","txt":"凡油轮和使用燃油的船舶，应备有油类记录簿，并且按照记录簿各项规定及时如实记载。"},{"i":38,"n":"第三十八条","txt":"如船舶在港口和沿海水域发生污染事故，应将经过情况分别记入油类记录簿和航海日志，并立即向港务监督报告，同时必须采取有效的措施防止扩散。如需采用化学剂处理，应提供化学成份说明书，向港务监督申请批准。"},{"i":39,"n":"第三十九条","txt":"本章未列事项，按照中华人民共和国有关防止水域污染的规定办理。"},{"i":40,"n":"第四十条","txt":"严禁在货舱以及易于引起船舶火警的场所吸烟和弄火。"},{"i":41,"n":"第四十一条","txt":"船舶加油和油船装卸作业，应采取严密的防火安全措施。"},{"i":42,"n":"第四十二条","txt":"船舶在港内进行烧焊等工程，应事先清理周围环境，采取严密防范措施，配备消防设备，并且在施工前后进行检查。对油舱及其邻近部位还必须卸完全部油料，清除残油，彻底通风，排除其内部易燃气体，并取得合格证明之后，才可以烧焊。"},{"i":43,"n":"第四十三条","txt":"船舶失火或发生海难，应立即将出事地点和本船吨位、吃水、载货、受损和需要某种援助等情况报告港务监督。"},{"i":44,"n":"第四十四条","txt":"港务监督在必要时，可动员和指挥在港内或沿海水域的船舶参加救助遇难船舶，在不影响本船安全的情况下，被动员的船舶有责任尽力救助。"},{"i":45,"n":"第四十五条","txt":"港务监督或救助部门的负责人员到达现场，遇难船舶的船长应立即报告失事情况及已经采取的措施，提供救助必需的资料和方便，并且可以提出有关救助的建议。港务监督为维护安全秩序作出的决定，有关方面必须遵守。"},{"i":46,"n":"第四十六条","txt":"船舶发生海损事故，应尽速用电报或无线电话向港务监督报出扼要报告。在港区以外发出的海损事故，船长应在船舶进入第一港口四十八小时内，向港务监督递交海损事故报告书；在港区内发生的海损事故，船长应在二十四小时内向港务监督递交海损事故报告书。"},{"i":47,"n":"第四十七条","txt":"船舶在中华人民共和国港口和沿海水域造成人命、财产损害事故时，应积极救助受害的船舶和人员，及时向港务监督报告，并接受调查和处理。如果肇事者见危不救，隐匿逃遁，将从严处理。"},{"i":48,"n":"第四十八条","txt":"船舶发生船员死亡事故，应立即向港务监督报告。在港内由于船方或港方人员的过失，造成对方损害或伤亡事故等，应保留现场，双方都应及时向港务监督报告。如果发生纠纷，当事的任何一方，都可以向港务监督申请调查处理，涉及刑事范围的，由中华人民共和国司法机关处理。"},{"i":49,"n":"第四十九条","txt":"本章未列事项，按照中华人民共和国交通部颁发的《海损事故调查和处理规则》办理。"},{"i":50,"n":"第五十条","txt":"凡违反本规则以及中华人民共和国一切有关法令、规章和规定者，港务监督得按其性质、情节分别给予警告、罚款等处分，性质恶劣、情节严重者移交司法机关处理。"},{"i":51,"n":"第五十一条","txt":"受处分者如果对所受处分不服，可以在接到通告的次日起十五日之内，向中华人民共和国港务监督局提出申诉。但在没有变更决定之前，原处分仍为有效。"},{"i":52,"n":"第五十二条","txt":"关于船舶避碰，本规则和中华人民共和国其他有关规定中未列事项，依照中华人民共和国施行的《国际海上避碰规则》办理。"},{"i":53,"n":"第五十三条","txt":"本规则由中华人民共和国国务院批准施行，中华人民共和国交通部一九五七年三月十二日颁发的《中华人民共和国对外国籍船舶进出港口管理办法》同时废止。"}],"guiqiaoqiaojuanquanyibaohufashishibanfa":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国归侨侨眷权益保护法》的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"归侨、侨眷的身份，由其常住户口所在地的县级以上地方人民政府负责侨务工作的机构根据本人申请审核认定。"},{"i":3,"n":"第三条","txt":"华侨、归侨去世后或者华侨身份改变后，其国内眷属原依法认定的侨眷身份不变。"},{"i":4,"n":"第四条","txt":"县级以上地方各级人民政府应当重视和加强归侨、侨眷合法权益保护工作。"},{"i":5,"n":"第五条","txt":"华侨要求回国定居的，按照国家有关出入境管理的规定核发回国定居证明。"},{"i":6,"n":"第六条","txt":"地方人民政府和有关部门对回国定居的华侨，按照国家有关规定给予安置。"},{"i":7,"n":"第七条","txt":"中华全国归国华侨联合会以及地方归国华侨联合会按照其章程开展活动，维护归侨、侨眷的合法权益。"},{"i":8,"n":"第八条","txt":"各级人民政府核拨给安置归侨的农场、林场等企业的专项经费应当专款专用，任何组织和个人不得挪用、截留或者私分。"},{"i":9,"n":"第九条","txt":"安置归侨的农场、林场等企业合法使用的土地、山林、滩涂、水面等资源，企业依法享有使用权，其拥有的生产资料、经营的作物、生产的产品，任何组织或者个人不得侵占、损害；国家依法征收或者征用安置归侨的农场、林场的土地的，依法给予补偿。"},{"i":10,"n":"第十条","txt":"在安置归侨的农场、林场等企业所在的地方设置的学校、医疗保健机构，应当纳入地方人民政府的教育、卫生规划，统一管理。"},{"i":11,"n":"第十一条","txt":"国家依法维护归侨、侨眷的社会保障权益。用人单位和归侨、侨眷应当依法参加当地的社会保险，缴纳社会保险费。参加社会保险的归侨、侨眷依法享受社会保险待遇。"},{"i":12,"n":"第十二条","txt":"归侨、侨眷依法投资开发荒山、荒地、滩涂，或者从事农业、林业、牧业、渔业生产，有关地方人民政府应当给予支持。"},{"i":13,"n":"第十三条","txt":"归侨、侨眷在国内兴办公益事业，各级人民政府及其有关部门应当给予支持，其合法权益受法律保护。"},{"i":14,"n":"第十四条","txt":"国家依法保护归侨、侨眷在国内私有房屋的所有权。归侨、侨眷对其私有房屋，依法享有占有、使用、收益和处分的权利，任何组织或者个人不得侵犯。"},{"i":15,"n":"第十五条","txt":"租赁归侨、侨眷的私有房屋，须由出租人和承租人签订租赁合同，并到房屋所在地的房产管理部门登记备案。租赁合同终止时，承租人应当将房屋退还出租人。"},{"i":16,"n":"第十六条","txt":"依法拆迁归侨、侨眷私有房屋的，拆迁人应当按照国家有关房屋拆迁管理的规定给予货币补偿或者实行房屋产权调换。按照政府规定的租金标准出租的归侨、侨眷的私有房屋被拆迁的，补偿安置的办法由国务院建设主管部门会同有关部门规定。"},{"i":17,"n":"第十七条","txt":"华侨子女回国就读实施义务教育的学校，应当视同当地居民子女办理入学手续；归侨学生、归侨子女和华侨在国内的子女报考国家举办的非义务教育的学校，教育等有关部门应当按照国家有关规定结合本地区实际情况给予照顾。"},{"i":18,"n":"第十八条","txt":"侨汇是归侨、侨眷的合法收入，其所有权受法律保护，任何组织或者个人不得侵占、延迟支付、强行借贷或者非法冻结、没收。"},{"i":19,"n":"第十九条","txt":"归侨、侨眷需要赴境外处分财产或者接受遗产、遗赠、赠与的，有关部门和我国驻外国的外交（领事）机构或者外交部授权的其他驻外机构，可以根据归侨、侨眷的请求提供必要的协助。"},{"i":20,"n":"第二十条","txt":"归侨、侨眷的通信自由和通信秘密受法律保护，任何组织或者个人不得非法开拆、隐匿、毁弃或者盗窃归侨、侨眷的邮件。归侨、侨眷的给据邮件丢失、损毁、内件短少的，邮政部门应当依法赔偿。"},{"i":21,"n":"第二十一条","txt":"归侨、侨眷申请出境的，有关主管部门应当在规定的期限内依法办理手续。"},{"i":22,"n":"第二十二条","txt":"归侨、侨眷按照国家有关探亲规定享受出境探亲待遇。"},{"i":23,"n":"第二十三条","txt":"按照国家规定退休（离休）的归侨、侨眷获准出境定居的，按照国家规定享受的退休（离休）待遇不变。其养老金可以委托他人领取，但需每年向原工作单位或者负责支付养老金的社会保险经办机构提供由我国驻其所在国的外交（领事）机构或者所在国公证机构出具的本人生存证明文件。"},{"i":24,"n":"第二十四条","txt":"归侨、侨眷在获得前往国家（地区）的入境签证前，所在工作单位或者学校不得因其申请出境而对其免职、辞退、解除劳动关系、停发工资或者责令退学，并且不得收取保证金、抵押金。"},{"i":25,"n":"第二十五条","txt":"归侨、侨眷出境探亲或者定居的，按照规定可以兑换外汇；出境定居的，其领取的社会保险金、住房公积金可以按照规定兑换外汇汇出或者携带出境。"},{"i":26,"n":"第二十六条","txt":"我国驻外国的外交（领事）机构根据我国缔结或者参加的国际条约或者国际惯例，保护归侨、侨眷在境外的合法权益。"},{"i":27,"n":"第二十七条","txt":"归侨、侨眷的合法权益受到侵害的，有权要求有关主管部门依法处理，或者向人民法院起诉。对有经济困难的归侨、侨眷，当地法律援助机构应当依法为其提供法律援助。各级归国华侨联合会应当给予支持和帮助。"},{"i":28,"n":"第二十八条","txt":"经办侨务专项经费的机构、人员，违反本办法规定，挪用、截留、私分侨务专项经费的，对直接负责的主管人员和其他直接责任人员依法给予行政处分或者纪律处分；构成犯罪的，依法追究刑事责任。被挪用、截留、私分的侨务专项经费，由其主管部门责令追回。"},{"i":29,"n":"第二十九条","txt":"国家机关工作人员滥用职权、玩忽职守、徇私舞弊，致使归侨、侨眷合法权益受到损害的，对直接负责的主管人员和其他直接责任人员依法给予行政处分或者纪律处分；构成犯罪的，依法追究刑事责任。"},{"i":30,"n":"第三十条","txt":"本办法自2004年7月1日起施行。1993年7月19日国务院发布的《中华人民共和国归侨侨眷权益保护法实施办法》同时废止。"}],"zhaobiaotoubiaofashishitiaoli":[{"i":1,"n":"第一条","txt":"为了规范招标投标活动，根据《中华人民共和国招标投标法》（以下简称招标投标法），制定本条例。"},{"i":2,"n":"第二条","txt":"招标投标法第三条所称工程建设项目，是指工程以及与工程建设有关的货物、服务。"},{"i":3,"n":"第三条","txt":"依法必须进行招标的工程建设项目的具体范围和规模标准，由国务院发展改革部门会同国务院有关部门制订，报国务院批准后公布施行。"},{"i":4,"n":"第四条","txt":"国务院发展改革部门指导和协调全国招标投标工作，对国家重大建设项目的工程招标投标活动实施监督检查。国务院工业和信息化、住房城乡建设、交通运输、铁道、水利、商务等部门，按照规定的职责分工对有关招标投标活动实施监督。"},{"i":5,"n":"第五条","txt":"设区的市级以上地方人民政府可以根据实际需要，建立统一规范的招标投标交易场所，为招标投标活动提供服务。招标投标交易场所不得与行政监督部门存在隶属关系，不得以营利为目的。"},{"i":6,"n":"第六条","txt":"禁止国家工作人员以任何方式非法干涉招标投标活动。"},{"i":7,"n":"第七条","txt":"按照国家有关规定需要履行项目审批、核准手续的依法必须进行招标的项目，其招标范围、招标方式、招标组织形式应当报项目审批、核准部门审批、核准。项目审批、核准部门应当及时将审批、核准确定的招标范围、招标方式、招标组织形式通报有关行政监督部门。"},{"i":8,"n":"第八条","txt":"国有资金占控股或者主导地位的依法必须进行招标的项目，应当公开招标；但有下列情形之一的，可以邀请招标："},{"i":9,"n":"第九条","txt":"除招标投标法第六十六条规定的可以不进行招标的特殊情况外，有下列情形之一的，可以不进行招标："},{"i":10,"n":"第十条","txt":"招标投标法第十二条第二款规定的招标人具有编制招标文件和组织评标能力，是指招标人具有与招标项目规模和复杂程度相适应的技术、经济等方面的专业人员。"},{"i":11,"n":"第十一条","txt":"国务院住房城乡建设、商务、发展改革、工业和信息化等部门，按照规定的职责分工对招标代理机构依法实施监督管理。"},{"i":12,"n":"第十二条","txt":"招标代理机构应当拥有一定数量的具备编制招标文件、组织评标等相应能力的专业人员。"},{"i":13,"n":"第十三条","txt":"招标代理机构在招标人委托的范围内开展招标代理业务，任何单位和个人不得非法干涉。"},{"i":14,"n":"第十四条","txt":"招标人应当与被委托的招标代理机构签订书面委托合同，合同约定的收费标准应当符合国家有关规定。"},{"i":15,"n":"第十五条","txt":"公开招标的项目，应当依照招标投标法和本条例的规定发布招标公告、编制招标文件。"},{"i":16,"n":"第十六条","txt":"招标人应当按照资格预审公告、招标公告或者投标邀请书规定的时间、地点发售资格预审文件或者招标文件。资格预审文件或者招标文件的发售期不得少于5日。"},{"i":17,"n":"第十七条","txt":"招标人应当合理确定提交资格预审申请文件的时间。依法必须进行招标的项目提交资格预审申请文件的时间，自资格预审文件停止发售之日起不得少于5日。"},{"i":18,"n":"第十八条","txt":"资格预审应当按照资格预审文件载明的标准和方法进行。"},{"i":19,"n":"第十九条","txt":"资格预审结束后，招标人应当及时向资格预审申请人发出资格预审结果通知书。未通过资格预审的申请人不具有投标资格。"},{"i":20,"n":"第二十条","txt":"招标人采用资格后审办法对投标人进行资格审查的，应当在开标后由评标委员会按照招标文件规定的标准和方法对投标人的资格进行审查。"},{"i":21,"n":"第二十一条","txt":"招标人可以对已发出的资格预审文件或者招标文件进行必要的澄清或者修改。澄清或者修改的内容可能影响资格预审申请文件或者投标文件编制的，招标人应当在提交资格预审申请文件截止时间至少3日前，或者投标截止时间至少15日前，以书面形式通知所有获取资格预审文件或者招标文件的潜在投标人；不足3日或者15日的，招标人应当顺延提交资格预审申请文件或者投标文件的截止时间。"},{"i":22,"n":"第二十二条","txt":"潜在投标人或者其他利害关系人对资格预审文件有异议的，应当在提交资格预审申请文件截止时间2日前提出；对招标文件有异议的，应当在投标截止时间10日前提出。招标人应当自收到异议之日起3日内作出答复；作出答复前，应当暂停招标投标活动。"},{"i":23,"n":"第二十三条","txt":"招标人编制的资格预审文件、招标文件的内容违反法律、行政法规的强制性规定，违反公开、公平、公正和诚实信用原则，影响资格预审结果或者潜在投标人投标的，依法必须进行招标的项目的招标人应当在修改资格预审文件或者招标文件后重新招标。"},{"i":24,"n":"第二十四条","txt":"招标人对招标项目划分标段的，应当遵守招标投标法的有关规定，不得利用划分标段限制或者排斥潜在投标人。依法必须进行招标的项目的招标人不得利用划分标段规避招标。"},{"i":25,"n":"第二十五条","txt":"招标人应当在招标文件中载明投标有效期。投标有效期从提交投标文件的截止之日起算。"},{"i":26,"n":"第二十六条","txt":"招标人在招标文件中要求投标人提交投标保证金的，投标保证金不得超过招标项目估算价的2%。投标保证金有效期应当与投标有效期一致。"},{"i":27,"n":"第二十七条","txt":"招标人可以自行决定是否编制标底。一个招标项目只能有一个标底。标底必须保密。"},{"i":28,"n":"第二十八条","txt":"招标人不得组织单个或者部分潜在投标人踏勘项目现场。"},{"i":29,"n":"第二十九条","txt":"招标人可以依法对工程以及与工程建设有关的货物、服务全部或者部分实行总承包招标。以暂估价形式包括在总承包范围内的工程、货物、服务属于依法必须进行招标的项目范围且达到国家规定规模标准的，应当依法进行招标。"},{"i":30,"n":"第三十条","txt":"对技术复杂或者无法精确拟定技术规格的项目，招标人可以分两阶段进行招标。"},{"i":31,"n":"第三十一条","txt":"招标人终止招标的，应当及时发布公告，或者以书面形式通知被邀请的或者已经获取资格预审文件、招标文件的潜在投标人。已经发售资格预审文件、招标文件或者已经收取投标保证金的，招标人应当及时退还所收取的资格预审文件、招标文件的费用，以及所收取的投标保证金及银行同期存款利息。"},{"i":32,"n":"第三十二条","txt":"招标人不得以不合理的条件限制、排斥潜在投标人或者投标人。"},{"i":33,"n":"第三十三条","txt":"投标人参加依法必须进行招标的项目的投标，不受地区或者部门的限制，任何单位和个人不得非法干涉。"},{"i":34,"n":"第三十四条","txt":"与招标人存在利害关系可能影响招标公正性的法人、其他组织或者个人，不得参加投标。"},{"i":35,"n":"第三十五条","txt":"投标人撤回已提交的投标文件，应当在投标截止时间前书面通知招标人。招标人已收取投标保证金的，应当自收到投标人书面撤回通知之日起5日内退还。"},{"i":36,"n":"第三十六条","txt":"未通过资格预审的申请人提交的投标文件，以及逾期送达或者不按照招标文件要求密封的投标文件，招标人应当拒收。"},{"i":37,"n":"第三十七条","txt":"招标人应当在资格预审公告、招标公告或者投标邀请书中载明是否接受联合体投标。"},{"i":38,"n":"第三十八条","txt":"投标人发生合并、分立、破产等重大变化的，应当及时书面告知招标人。投标人不再具备资格预审文件、招标文件规定的资格条件或者其投标影响招标公正性的，其投标无效。"},{"i":39,"n":"第三十九条","txt":"禁止投标人相互串通投标。"},{"i":40,"n":"第四十条","txt":"有下列情形之一的，视为投标人相互串通投标："},{"i":41,"n":"第四十一条","txt":"禁止招标人与投标人串通投标。"},{"i":42,"n":"第四十二条","txt":"使用通过受让或者租借等方式获取的资格、资质证书投标的，属于招标投标法第三十三条规定的以他人名义投标。"},{"i":43,"n":"第四十三条","txt":"提交资格预审申请文件的申请人应当遵守招标投标法和本条例有关投标人的规定。"},{"i":44,"n":"第四十四条","txt":"招标人应当按照招标文件规定的时间、地点开标。"},{"i":45,"n":"第四十五条","txt":"国家实行统一的评标专家专业分类标准和管理办法。具体标准和办法由国务院发展改革部门会同国务院有关部门制定。"},{"i":46,"n":"第四十六条","txt":"除招标投标法第三十七条第三款规定的特殊招标项目外，依法必须进行招标的项目，其评标委员会的专家成员应当从评标专家库内相关专业的专家名单中以随机抽取方式确定。任何单位和个人不得以明示、暗示等任何方式指定或者变相指定参加评标委员会的专家成员。"},{"i":47,"n":"第四十七条","txt":"招标投标法第三十七条第三款所称特殊招标项目，是指技术复杂、专业性强或者国家有特殊要求，采取随机抽取方式确定的专家难以保证胜任评标工作的项目。"},{"i":48,"n":"第四十八条","txt":"招标人应当向评标委员会提供评标所必需的信息，但不得明示或者暗示其倾向或者排斥特定投标人。"},{"i":49,"n":"第四十九条","txt":"评标委员会成员应当依照招标投标法和本条例的规定，按照招标文件规定的评标标准和方法，客观、公正地对投标文件提出评审意见。招标文件没有规定的评标标准和方法不得作为评标的依据。"},{"i":50,"n":"第五十条","txt":"招标项目设有标底的，招标人应当在开标时公布。标底只能作为评标的参考，不得以投标报价是否接近标底作为中标条件，也不得以投标报价超过标底上下浮动范围作为否决投标的条件。"},{"i":51,"n":"第五十一条","txt":"有下列情形之一的，评标委员会应当否决其投标："},{"i":52,"n":"第五十二条","txt":"投标文件中有含义不明确的内容、明显文字或者计算错误，评标委员会认为需要投标人作出必要澄清、说明的，应当书面通知该投标人。投标人的澄清、说明应当采用书面形式，并不得超出投标文件的范围或者改变投标文件的实质性内容。"},{"i":53,"n":"第五十三条","txt":"评标完成后，评标委员会应当向招标人提交书面评标报告和中标候选人名单。中标候选人应当不超过3个，并标明排序。"},{"i":54,"n":"第五十四条","txt":"依法必须进行招标的项目，招标人应当自收到评标报告之日起3日内公示中标候选人，公示期不得少于3日。"},{"i":55,"n":"第五十五条","txt":"国有资金占控股或者主导地位的依法必须进行招标的项目，招标人应当确定排名第一的中标候选人为中标人。排名第一的中标候选人放弃中标、因不可抗力不能履行合同、不按照招标文件要求提交履约保证金，或者被查实存在影响中标结果的违法行为等情形，不符合中标条件的，招标人可以按照评标委员会提出的中标候选人名单排序依次确定其他中标候选人为中标人，也可以重新招标。"},{"i":56,"n":"第五十六条","txt":"中标候选人的经营、财务状况发生较大变化或者存在违法行为，招标人认为可能影响其履约能力的，应当在发出中标通知书前由原评标委员会按照招标文件规定的标准和方法审查确认。"},{"i":57,"n":"第五十七条","txt":"招标人和中标人应当依照招标投标法和本条例的规定签订书面合同，合同的标的、价款、质量、履行期限等主要条款应当与招标文件和中标人的投标文件的内容一致。招标人和中标人不得再行订立背离合同实质性内容的其他协议。"},{"i":58,"n":"第五十八条","txt":"招标文件要求中标人提交履约保证金的，中标人应当按照招标文件的要求提交。履约保证金不得超过中标合同金额的10%。"},{"i":59,"n":"第五十九条","txt":"中标人应当按照合同约定履行义务，完成中标项目。中标人不得向他人转让中标项目，也不得将中标项目肢解后分别向他人转让。"},{"i":60,"n":"第六十条","txt":"投标人或者其他利害关系人认为招标投标活动不符合法律、行政法规规定的，可以自知道或者应当知道之日起10日内向有关行政监督部门投诉。投诉应当有明确的请求和必要的证明材料。"},{"i":61,"n":"第六十一条","txt":"投诉人就同一事项向两个以上有权受理的行政监督部门投诉的，由最先收到投诉的行政监督部门负责处理。"},{"i":62,"n":"第六十二条","txt":"行政监督部门处理投诉，有权查阅、复制有关文件、资料，调查有关情况，相关单位和人员应当予以配合。必要时，行政监督部门可以责令暂停招标投标活动。"},{"i":63,"n":"第六十三条","txt":"招标人有下列限制或者排斥潜在投标人行为之一的，由有关行政监督部门依照招标投标法第五十一条的规定处罚："},{"i":64,"n":"第六十四条","txt":"招标人有下列情形之一的，由有关行政监督部门责令改正，可以处10万元以下的罚款："},{"i":65,"n":"第六十五条","txt":"招标代理机构在所代理的招标项目中投标、代理投标或者向该项目投标人提供咨询的，接受委托编制标底的中介机构参加受托编制标底项目的投标或者为该项目的投标人编制投标文件、提供咨询的，依照招标投标法第五十条的规定追究法律责任。"},{"i":66,"n":"第六十六条","txt":"招标人超过本条例规定的比例收取投标保证金、履约保证金或者不按照规定退还投标保证金及银行同期存款利息的，由有关行政监督部门责令改正，可以处5万元以下的罚款；给他人造成损失的，依法承担赔偿责任。"},{"i":67,"n":"第六十七条","txt":"投标人相互串通投标或者与招标人串通投标的，投标人向招标人或者评标委员会成员行贿谋取中标的，中标无效；构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依照招标投标法第五十三条的规定处罚。投标人未中标的，对单位的罚款金额按照招标项目合同金额依照招标投标法规定的比例计算。"},{"i":68,"n":"第六十八条","txt":"投标人以他人名义投标或者以其他方式弄虚作假骗取中标的，中标无效；构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依照招标投标法第五十四条的规定处罚。依法必须进行招标的项目的投标人未中标的，对单位的罚款金额按照招标项目合同金额依照招标投标法规定的比例计算。"},{"i":69,"n":"第六十九条","txt":"出让或者出租资格、资质证书供他人投标的，依照法律、行政法规的规定给予行政处罚；构成犯罪的，依法追究刑事责任。"},{"i":70,"n":"第七十条","txt":"依法必须进行招标的项目的招标人不按照规定组建评标委员会，或者确定、更换评标委员会成员违反招标投标法和本条例规定的，由有关行政监督部门责令改正，可以处10万元以下的罚款，对单位直接负责的主管人员和其他直接责任人员依法给予处分；违法确定或者更换的评标委员会成员作出的评审结论无效，依法重新进行评审。"},{"i":71,"n":"第七十一条","txt":"评标委员会成员有下列行为之一的，由有关行政监督部门责令改正；情节严重的，禁止其在一定期限内参加依法必须进行招标的项目的评标；情节特别严重的，取消其担任评标委员会成员的资格："},{"i":72,"n":"第七十二条","txt":"评标委员会成员收受投标人的财物或者其他好处的，没收收受的财物，处3000元以上5万元以下的罚款，取消担任评标委员会成员的资格，不得再参加依法必须进行招标的项目的评标；构成犯罪的，依法追究刑事责任。"},{"i":73,"n":"第七十三条","txt":"依法必须进行招标的项目的招标人有下列情形之一的，由有关行政监督部门责令改正，可以处中标项目金额10‰以下的罚款；给他人造成损失的，依法承担赔偿责任；对单位直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":74,"n":"第七十四条","txt":"中标人无正当理由不与招标人订立合同，在签订合同时向招标人提出附加条件，或者不按照招标文件要求提交履约保证金的，取消其中标资格，投标保证金不予退还。对依法必须进行招标的项目的中标人，由有关行政监督部门责令改正，可以处中标项目金额10‰以下的罚款。"},{"i":75,"n":"第七十五条","txt":"招标人和中标人不按照招标文件和中标人的投标文件订立合同，合同的主要条款与招标文件、中标人的投标文件的内容不一致，或者招标人、中标人订立背离合同实质性内容的协议的，由有关行政监督部门责令改正，可以处中标项目金额5‰以上10‰以下的罚款。"},{"i":76,"n":"第七十六条","txt":"中标人将中标项目转让给他人的，将中标项目肢解后分别转让给他人的，违反招标投标法和本条例规定将中标项目的部分主体、关键性工作分包给他人的，或者分包人再次分包的，转让、分包无效，处转让、分包项目金额5‰以上10‰以下的罚款；有违法所得的，并处没收违法所得；可以责令停业整顿；情节严重的，由工商行政管理机关吊销营业执照。"},{"i":77,"n":"第七十七条","txt":"投标人或者其他利害关系人捏造事实、伪造材料或者以非法手段取得证明材料进行投诉，给他人造成损失的，依法承担赔偿责任。"},{"i":78,"n":"第七十八条","txt":"国家建立招标投标信用制度。有关行政监督部门应当依法公告对招标人、招标代理机构、投标人、评标委员会成员等当事人违法行为的行政处理决定。"},{"i":79,"n":"第七十九条","txt":"项目审批、核准部门不依法审批、核准项目招标范围、招标方式、招标组织形式的，对单位直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":80,"n":"第八十条","txt":"国家工作人员利用职务便利，以直接或者间接、明示或者暗示等任何方式非法干涉招标投标活动，有下列情形之一的，依法给予记过或者记大过处分；情节严重的，依法给予降级或者撤职处分；情节特别严重的，依法给予开除处分；构成犯罪的，依法追究刑事责任："},{"i":81,"n":"第八十一条","txt":"依法必须进行招标的项目的招标投标活动违反招标投标法和本条例的规定，对中标结果造成实质性影响，且不能采取补救措施予以纠正的，招标、投标、中标无效，应当依法重新招标或者评标。"},{"i":82,"n":"第八十二条","txt":"招标投标协会按照依法制定的章程开展活动，加强行业自律和服务。"},{"i":83,"n":"第八十三条","txt":"政府采购的法律、行政法规对政府采购货物、服务的招标投标另有规定的，从其规定。"},{"i":84,"n":"第八十四条","txt":"本条例自2012年2月1日起施行。"}],"zhengfucaigoufashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国政府采购法》（以下简称政府采购法），制定本条例。"},{"i":2,"n":"第二条","txt":"政府采购法第二条所称财政性资金是指纳入预算管理的资金。"},{"i":3,"n":"第三条","txt":"集中采购目录包括集中采购机构采购项目和部门集中采购项目。"},{"i":4,"n":"第四条","txt":"政府采购法所称集中采购，是指采购人将列入集中采购目录的项目委托集中采购机构代理采购或者进行部门集中采购的行为；所称分散采购，是指采购人将采购限额标准以上的未列入集中采购目录的项目自行采购或者委托采购代理机构代理采购的行为。"},{"i":5,"n":"第五条","txt":"省、自治区、直辖市人民政府或者其授权的机构根据实际情况，可以确定分别适用于本行政区域省级、设区的市级、县级的集中采购目录和采购限额标准。"},{"i":6,"n":"第六条","txt":"国务院财政部门应当根据国家的经济和社会发展政策，会同国务院有关部门制定政府采购政策，通过制定采购需求标准、预留采购份额、价格评审优惠、优先采购等措施，实现节约能源、保护环境、扶持不发达地区和少数民族地区、促进中小企业发展等目标。"},{"i":7,"n":"第七条","txt":"政府采购工程以及与工程建设有关的货物、服务，采用招标方式采购的，适用《中华人民共和国招标投标法》及其实施条例；采用其他方式采购的，适用政府采购法及本条例。"},{"i":8,"n":"第八条","txt":"政府采购项目信息应当在省级以上人民政府财政部门指定的媒体上发布。采购项目预算金额达到国务院财政部门规定标准的，政府采购项目信息应当在国务院财政部门指定的媒体上发布。"},{"i":9,"n":"第九条","txt":"在政府采购活动中，采购人员及相关人员与供应商有下列利害关系之一的，应当回避："},{"i":10,"n":"第十条","txt":"国家实行统一的政府采购电子交易平台建设标准，推动利用信息网络进行电子化政府采购活动。"},{"i":11,"n":"第十一条","txt":"采购人在政府采购活动中应当维护国家利益和社会公共利益，公正廉洁，诚实守信，执行政府采购政策，建立政府采购内部管理制度，厉行节约，科学合理确定采购需求。"},{"i":12,"n":"第十二条","txt":"政府采购法所称采购代理机构，是指集中采购机构和集中采购机构以外的采购代理机构。"},{"i":13,"n":"第十三条","txt":"采购代理机构应当建立完善的政府采购内部监督管理制度，具备开展政府采购业务所需的评审条件和设施。"},{"i":14,"n":"第十四条","txt":"采购代理机构不得以不正当手段获取政府采购代理业务，不得与采购人、供应商恶意串通操纵政府采购活动。"},{"i":15,"n":"第十五条","txt":"采购人、采购代理机构应当根据政府采购政策、采购预算、采购需求编制采购文件。"},{"i":16,"n":"第十六条","txt":"政府采购法第二十条规定的委托代理协议，应当明确代理采购的范围、权限和期限等具体事项。"},{"i":17,"n":"第十七条","txt":"参加政府采购活动的供应商应当具备政府采购法第二十二条第一款规定的条件，提供下列材料："},{"i":18,"n":"第十八条","txt":"单位负责人为同一人或者存在直接控股、管理关系的不同供应商，不得参加同一合同项下的政府采购活动。"},{"i":19,"n":"第十九条","txt":"政府采购法第二十二条第一款第五项所称重大违法记录，是指供应商因违法经营受到刑事处罚或者责令停产停业、吊销许可证或者执照、较大数额罚款等行政处罚。"},{"i":20,"n":"第二十条","txt":"采购人或者采购代理机构有下列情形之一的，属于以不合理的条件对供应商实行差别待遇或者歧视待遇："},{"i":21,"n":"第二十一条","txt":"采购人或者采购代理机构对供应商进行资格预审的，资格预审公告应当在省级以上人民政府财政部门指定的媒体上发布。已进行资格预审的，评审阶段可以不再对供应商资格进行审查。资格预审合格的供应商在评审阶段资格发生变化的，应当通知采购人和采购代理机构。"},{"i":22,"n":"第二十二条","txt":"联合体中有同类资质的供应商按照联合体分工承担相同工作的，应当按照资质等级较低的供应商确定资质等级。"},{"i":23,"n":"第二十三条","txt":"采购人采购公开招标数额标准以上的货物或者服务，符合政府采购法第二十九条、第三十条、第三十一条、第三十二条规定情形或者有需要执行政府采购政策等特殊情况的，经设区的市级以上人民政府财政部门批准，可以依法采用公开招标以外的采购方式。"},{"i":24,"n":"第二十四条","txt":"列入集中采购目录的项目，适合实行批量集中采购的，应当实行批量集中采购，但紧急的小额零星货物项目和有特殊要求的服务、工程项目除外。"},{"i":25,"n":"第二十五条","txt":"政府采购工程依法不进行招标的，应当依照政府采购法和本条例规定的竞争性谈判或者单一来源采购方式采购。"},{"i":26,"n":"第二十六条","txt":"政府采购法第三十条第三项规定的情形，应当是采购人不可预见的或者非因采购人拖延导致的；第四项规定的情形，是指因采购艺术品或者因专利、专有技术或者因服务的时间、数量事先不能确定等导致不能事先计算出价格总额。"},{"i":27,"n":"第二十七条","txt":"政府采购法第三十一条第一项规定的情形，是指因货物或者服务使用不可替代的专利、专有技术，或者公共服务项目具有特殊要求，导致只能从某一特定供应商处采购。"},{"i":28,"n":"第二十八条","txt":"在一个财政年度内，采购人将一个预算项目下的同一品目或者类别的货物、服务采用公开招标以外的方式多次采购，累计资金数额超过公开招标数额标准的，属于以化整为零方式规避公开招标，但项目预算调整或者经批准采用公开招标以外方式采购除外。"},{"i":29,"n":"第二十九条","txt":"采购人应当根据集中采购目录、采购限额标准和已批复的部门预算编制政府采购实施计划，报本级人民政府财政部门备案。"},{"i":30,"n":"第三十条","txt":"采购人或者采购代理机构应当在招标文件、谈判文件、询价通知书中公开采购项目预算金额。"},{"i":31,"n":"第三十一条","txt":"招标文件的提供期限自招标文件开始发出之日起不得少于5个工作日。"},{"i":32,"n":"第三十二条","txt":"采购人或者采购代理机构应当按照国务院财政部门制定的招标文件标准文本编制招标文件。"},{"i":33,"n":"第三十三条","txt":"招标文件要求投标人提交投标保证金的，投标保证金不得超过采购项目预算金额的2%。投标保证金应当以支票、汇票、本票或者金融机构、担保机构出具的保函等非现金形式提交。投标人未按照招标文件要求提交投标保证金的，投标无效。"},{"i":34,"n":"第三十四条","txt":"政府采购招标评标方法分为最低评标价法和综合评分法。"},{"i":35,"n":"第三十五条","txt":"谈判文件不能完整、明确列明采购需求，需要由供应商提供最终设计方案或者解决方案的，在谈判结束后，谈判小组应当按照少数服从多数的原则投票推荐3家以上供应商的设计方案或者解决方案，并要求其在规定时间内提交最后报价。"},{"i":36,"n":"第三十六条","txt":"询价通知书应当根据采购需求确定政府采购合同条款。在询价过程中，询价小组不得改变询价通知书所确定的政府采购合同条款。"},{"i":37,"n":"第三十七条","txt":"政府采购法第三十八条第五项、第四十条第四项所称质量和服务相等，是指供应商提供的产品质量和服务均能满足采购文件规定的实质性要求。"},{"i":38,"n":"第三十八条","txt":"达到公开招标数额标准，符合政府采购法第三十一条第一项规定情形，只能从唯一供应商处采购的，采购人应当将采购项目信息和唯一供应商名称在省级以上人民政府财政部门指定的媒体上公示，公示期不得少于5个工作日。"},{"i":39,"n":"第三十九条","txt":"除国务院财政部门规定的情形外，采购人或者采购代理机构应当从政府采购评审专家库中随机抽取评审专家。"},{"i":40,"n":"第四十条","txt":"政府采购评审专家应当遵守评审工作纪律，不得泄露评审文件、评审情况和评审中获悉的商业秘密。"},{"i":41,"n":"第四十一条","txt":"评标委员会、竞争性谈判小组或者询价小组成员应当按照客观、公正、审慎的原则，根据采购文件规定的评审程序、评审方法和评审标准进行独立评审。采购文件内容违反国家有关强制性规定的，评标委员会、竞争性谈判小组或者询价小组应当停止评审并向采购人或者采购代理机构说明情况。"},{"i":42,"n":"第四十二条","txt":"采购人、采购代理机构不得向评标委员会、竞争性谈判小组或者询价小组的评审专家作倾向性、误导性的解释或者说明。"},{"i":43,"n":"第四十三条","txt":"采购代理机构应当自评审结束之日起2个工作日内将评审报告送交采购人。采购人应当自收到评审报告之日起5个工作日内在评审报告推荐的中标或者成交候选人中按顺序确定中标或者成交供应商。"},{"i":44,"n":"第四十四条","txt":"除国务院财政部门规定的情形外，采购人、采购代理机构不得以任何理由组织重新评审。采购人、采购代理机构按照国务院财政部门的规定组织重新评审的，应当书面报告本级人民政府财政部门。"},{"i":45,"n":"第四十五条","txt":"采购人或者采购代理机构应当按照政府采购合同规定的技术、服务、安全标准组织对供应商履约情况进行验收，并出具验收书。验收书应当包括每一项技术、服务、安全标准的履约情况。"},{"i":46,"n":"第四十六条","txt":"政府采购法第四十二条规定的采购文件，可以用电子档案方式保存。"},{"i":47,"n":"第四十七条","txt":"国务院财政部门应当会同国务院有关部门制定政府采购合同标准文本。"},{"i":48,"n":"第四十八条","txt":"采购文件要求中标或者成交供应商提交履约保证金的，供应商应当以支票、汇票、本票或者金融机构、担保机构出具的保函等非现金形式提交。履约保证金的数额不得超过政府采购合同金额的10%。"},{"i":49,"n":"第四十九条","txt":"中标或者成交供应商拒绝与采购人签订合同的，采购人可以按照评审报告推荐的中标或者成交候选人名单排序，确定下一候选人为中标或者成交供应商，也可以重新开展政府采购活动。"},{"i":50,"n":"第五十条","txt":"采购人应当自政府采购合同签订之日起2个工作日内，将政府采购合同在省级以上人民政府财政部门指定的媒体上公告，但政府采购合同中涉及国家秘密、商业秘密的内容除外。"},{"i":51,"n":"第五十一条","txt":"采购人应当按照政府采购合同规定，及时向中标或者成交供应商支付采购资金。"},{"i":52,"n":"第五十二条","txt":"采购人或者采购代理机构应当在3个工作日内对供应商依法提出的询问作出答复。"},{"i":53,"n":"第五十三条","txt":"政府采购法第五十二条规定的供应商应知其权益受到损害之日，是指："},{"i":54,"n":"第五十四条","txt":"询问或者质疑事项可能影响中标、成交结果的，采购人应当暂停签订合同，已经签订合同的，应当中止履行合同。"},{"i":55,"n":"第五十五条","txt":"供应商质疑、投诉应当有明确的请求和必要的证明材料。供应商投诉的事项不得超出已质疑事项的范围。"},{"i":56,"n":"第五十六条","txt":"财政部门处理投诉事项采用书面审查的方式，必要时可以进行调查取证或者组织质证。"},{"i":57,"n":"第五十七条","txt":"投诉人捏造事实、提供虚假材料或者以非法手段取得证明材料进行投诉的，财政部门应当予以驳回。"},{"i":58,"n":"第五十八条","txt":"财政部门处理投诉事项，需要检验、检测、鉴定、专家评审以及需要投诉人补正材料的，所需时间不计算在投诉处理期限内。"},{"i":59,"n":"第五十九条","txt":"政府采购法第六十三条所称政府采购项目的采购标准，是指项目采购所依据的经费预算标准、资产配置标准和技术、服务标准等。"},{"i":60,"n":"第六十条","txt":"除政府采购法第六十六条规定的考核事项外，财政部门对集中采购机构的考核事项还包括："},{"i":61,"n":"第六十一条","txt":"采购人发现采购代理机构有违法行为的，应当要求其改正。采购代理机构拒不改正的，采购人应当向本级人民政府财政部门报告，财政部门应当依法处理。"},{"i":62,"n":"第六十二条","txt":"省级以上人民政府财政部门应当对政府采购评审专家库实行动态管理，具体管理办法由国务院财政部门制定。"},{"i":63,"n":"第六十三条","txt":"各级人民政府财政部门和其他有关部门应当加强对参加政府采购活动的供应商、采购代理机构、评审专家的监督管理，对其不良行为予以记录，并纳入统一的信用信息平台。"},{"i":64,"n":"第六十四条","txt":"各级人民政府财政部门对政府采购活动进行监督检查，有权查阅、复制有关文件、资料，相关单位和人员应当予以配合。"},{"i":65,"n":"第六十五条","txt":"审计机关、监察机关以及其他有关部门依法对政府采购活动实施监督，发现采购当事人有违法行为的，应当及时通报财政部门。"},{"i":66,"n":"第六十六条","txt":"政府采购法第七十一条规定的罚款，数额为10万元以下。"},{"i":67,"n":"第六十七条","txt":"采购人有下列情形之一的，由财政部门责令限期改正，给予警告，对直接负责的主管人员和其他直接责任人员依法给予处分，并予以通报："},{"i":68,"n":"第六十八条","txt":"采购人、采购代理机构有下列情形之一的，依照政府采购法第七十一条、第七十八条的规定追究法律责任："},{"i":69,"n":"第六十九条","txt":"集中采购机构有下列情形之一的，由财政部门责令限期改正，给予警告，有违法所得的，并处没收违法所得，对直接负责的主管人员和其他直接责任人员依法给予处分，并予以通报："},{"i":70,"n":"第七十条","txt":"采购人员与供应商有利害关系而不依法回避的，由财政部门给予警告，并处2000元以上2万元以下的罚款。"},{"i":71,"n":"第七十一条","txt":"有政府采购法第七十一条、第七十二条规定的违法行为之一，影响或者可能影响中标、成交结果的，依照下列规定处理："},{"i":72,"n":"第七十二条","txt":"供应商有下列情形之一的，依照政府采购法第七十七条第一款的规定追究法律责任："},{"i":73,"n":"第七十三条","txt":"供应商捏造事实、提供虚假材料或者以非法手段取得证明材料进行投诉的，由财政部门列入不良行为记录名单，禁止其1至3年内参加政府采购活动。"},{"i":74,"n":"第七十四条","txt":"有下列情形之一的，属于恶意串通，对供应商依照政府采购法第七十七条第一款的规定追究法律责任，对采购人、采购代理机构及其工作人员依照政府采购法第七十二条的规定追究法律责任："},{"i":75,"n":"第七十五条","txt":"政府采购评审专家未按照采购文件规定的评审程序、评审方法和评审标准进行独立评审或者泄露评审文件、评审情况的，由财政部门给予警告，并处2000元以上2万元以下的罚款；影响中标、成交结果的，处2万元以上5万元以下的罚款，禁止其参加政府采购评审活动。"},{"i":76,"n":"第七十六条","txt":"政府采购当事人违反政府采购法和本条例规定，给他人造成损失的，依法承担民事责任。"},{"i":77,"n":"第七十七条","txt":"财政部门在履行政府采购监督管理职责中违反政府采购法和本条例规定，滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员依法给予处分；直接负责的主管人员和其他直接责任人员构成犯罪的，依法追究刑事责任。"},{"i":78,"n":"第七十八条","txt":"财政管理实行省直接管理的县级人民政府可以根据需要并报经省级人民政府批准，行使政府采购法和本条例规定的设区的市级人民政府批准变更采购方式的职权。"},{"i":79,"n":"第七十九条","txt":"本条例自2015年3月1日起施行。"}],"wenwubaohufashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国文物保护法》（以下简称文物保护法），制定本实施条例。"},{"i":2,"n":"第二条","txt":"国家重点文物保护专项补助经费和地方文物保护专项经费，由县级以上人民政府文物行政主管部门、投资主管部门、财政部门按照国家有关规定共同实施管理。任何单位或者个人不得侵占、挪用。"},{"i":3,"n":"第三条","txt":"国有的博物馆、纪念馆、文物保护单位等的事业性收入，应当用于下列用途："},{"i":4,"n":"第四条","txt":"文物行政主管部门和教育、科技、新闻出版、广播电视行政主管部门，应当做好文物保护的宣传教育工作。"},{"i":5,"n":"第五条","txt":"国务院文物行政主管部门和省、自治区、直辖市人民政府文物行政主管部门，应当制定文物保护的科学技术研究规划，采取有效措施，促进文物保护科技成果的推广和应用，提高文物保护的科学技术水平。"},{"i":6,"n":"第六条","txt":"有文物保护法第十二条所列事迹之一的单位或者个人，由人民政府及其文物行政主管部门、有关部门给予精神鼓励或者物质奖励。"},{"i":7,"n":"第七条","txt":"历史文化名城，由国务院建设行政主管部门会同国务院文物行政主管部门报国务院核定公布。"},{"i":8,"n":"第八条","txt":"全国重点文物保护单位和省级文物保护单位自核定公布之日起1年内，由省、自治区、直辖市人民政府划定必要的保护范围，作出标志说明，建立记录档案，设置专门机构或者指定专人负责管理。"},{"i":9,"n":"第九条","txt":"文物保护单位的保护范围，是指对文物保护单位本体及周围一定范围实施重点保护的区域。"},{"i":10,"n":"第十条","txt":"文物保护单位的标志说明，应当包括文物保护单位的级别、名称、公布机关、公布日期、立标机关、立标日期等内容。民族自治地区的文物保护单位的标志说明，应当同时用规范汉字和当地通用的少数民族文字书写。"},{"i":11,"n":"第十一条","txt":"文物保护单位的记录档案，应当包括文物保护单位本体记录等科学技术资料和有关文献记载、行政管理等内容。"},{"i":12,"n":"第十二条","txt":"古文化遗址、古墓葬、石窟寺和属于国家所有的纪念建筑物、古建筑，被核定公布为文物保护单位的，由县级以上地方人民政府设置专门机构或者指定机构负责管理。其他文物保护单位，由县级以上地方人民政府设置专门机构或者指定机构、专人负责管理；指定专人负责管理的，可以采取聘请文物保护员的形式。"},{"i":13,"n":"第十三条","txt":"文物保护单位的建设控制地带，是指在文物保护单位的保护范围外，为保护文物保护单位的安全、环境、历史风貌对建设项目加以限制的区域。"},{"i":14,"n":"第十四条","txt":"全国重点文物保护单位的建设控制地带，经省、自治区、直辖市人民政府批准，由省、自治区、直辖市人民政府的文物行政主管部门会同城乡规划行政主管部门划定并公布。"},{"i":15,"n":"第十五条","txt":"承担文物保护单位的修缮、迁移、重建工程的单位，应当同时取得文物行政主管部门发给的相应等级的文物保护工程资质证书和建设行政主管部门发给的相应等级的资质证书。其中，不涉及建筑活动的文物保护单位的修缮、迁移、重建，应当由取得文物行政主管部门发给的相应等级的文物保护工程资质证书的单位承担。"},{"i":16,"n":"第十六条","txt":"申领文物保护工程资质证书，应当具备下列条件："},{"i":17,"n":"第十七条","txt":"申领文物保护工程资质证书，应当向省、自治区、直辖市人民政府文物行政主管部门或者国务院文物行政主管部门提出申请。省、自治区、直辖市人民政府文物行政主管部门或者国务院文物行政主管部门应当自收到申请之日起30个工作日内作出批准或者不批准的决定。决定批准的，发给相应等级的文物保护工程资质证书；决定不批准的，应当书面通知当事人并说明理由。文物保护工程资质等级的分级标准和审批办法，由国务院文物行政主管部门制定。"},{"i":18,"n":"第十八条","txt":"文物行政主管部门在审批文物保护单位的修缮计划和工程设计方案前，应当征求上一级人民政府文物行政主管部门的意见。"},{"i":19,"n":"第十九条","txt":"危害全国重点文物保护单位安全或者破坏其历史风貌的建筑物、构筑物，由省、自治区、直辖市人民政府负责调查处理。"},{"i":20,"n":"第二十条","txt":"申请从事考古发掘的单位，取得考古发掘资质证书，应当具备下列条件："},{"i":21,"n":"第二十一条","txt":"申领考古发掘资质证书，应当向国务院文物行政主管部门提出申请。国务院文物行政主管部门应当自收到申请之日起30个工作日内作出批准或者不批准的决定。决定批准的，发给考古发掘资质证书；决定不批准的，应当书面通知当事人并说明理由。"},{"i":22,"n":"第二十二条","txt":"考古发掘项目实行项目负责人负责制度。"},{"i":23,"n":"第二十三条","txt":"配合建设工程进行的考古调查、勘探、发掘，由省、自治区、直辖市人民政府文物行政主管部门组织实施。跨省、自治区、直辖市的建设工程范围内的考古调查、勘探、发掘，由建设工程所在地的有关省、自治区、直辖市人民政府文物行政主管部门联合组织实施；其中，特别重要的建设工程范围内的考古调查、勘探、发掘，由国务院文物行政主管部门组织实施。"},{"i":24,"n":"第二十四条","txt":"国务院文物行政主管部门应当自收到文物保护法第三十条第一款规定的发掘计划之日起30个工作日内作出批准或者不批准决定。决定批准的，发给批准文件；决定不批准的，应当书面通知当事人并说明理由。"},{"i":25,"n":"第二十五条","txt":"考古调查、勘探、发掘所需经费的范围和标准，按照国家有关规定执行。"},{"i":26,"n":"第二十六条","txt":"从事考古发掘的单位应当在考古发掘完成之日起30个工作日内向省、自治区、直辖市人民政府文物行政主管部门和国务院文物行政主管部门提交结项报告，并于提交结项报告之日起3年内向省、自治区、直辖市人民政府文物行政主管部门和国务院文物行政主管部门提交考古发掘报告。"},{"i":27,"n":"第二十七条","txt":"从事考古发掘的单位提交考古发掘报告后，经省、自治区、直辖市人民政府文物行政主管部门批准，可以保留少量出土文物作为科研标本，并应当于提交发掘报告之日起6个月内将其他出土文物移交给由省、自治区、直辖市人民政府文物行政主管部门指定的国有的博物馆、图书馆或者其他国有文物收藏单位收藏。"},{"i":28,"n":"第二十八条","txt":"文物收藏单位应当建立馆藏文物的接收、鉴定、登记、编目和档案制度，库房管理制度，出入库、注销和统计制度，保养、修复和复制制度。"},{"i":29,"n":"第二十九条","txt":"县级人民政府文物行政主管部门应当将本行政区域内的馆藏文物档案，按照行政隶属关系报设区的市、自治州级人民政府文物行政主管部门或者省、自治区、直辖市人民政府文物行政主管部门备案；设区的市、自治州级人民政府文物行政主管部门应当将本行政区域内的馆藏文物档案，报省、自治区、直辖市人民政府文物行政主管部门备案；省、自治区、直辖市人民政府文物行政主管部门应当将本行政区域内的一级文物藏品档案，报国务院文物行政主管部门备案。"},{"i":30,"n":"第三十条","txt":"文物收藏单位之间借用馆藏文物，借用人应当对借用的馆藏文物采取必要的保护措施，确保文物的安全。"},{"i":31,"n":"第三十一条","txt":"国有文物收藏单位未依照文物保护法第三十六条的规定建立馆藏文物档案并将馆藏文物档案报主管的文物行政主管部门备案的，不得交换、借用馆藏文物。"},{"i":32,"n":"第三十二条","txt":"修复、复制、拓印馆藏二级文物和馆藏三级文物的，应当报省、自治区、直辖市人民政府文物行政主管部门批准；修复、复制、拓印馆藏一级文物的，应当报国务院文物行政主管部门批准。"},{"i":33,"n":"第三十三条","txt":"从事馆藏文物修复、复制、拓印的单位，应当具备下列条件："},{"i":34,"n":"第三十四条","txt":"从事馆藏文物修复、复制、拓印，应当向省、自治区、直辖市人民政府文物行政主管部门提出申请。省、自治区、直辖市人民政府文物行政主管部门应当自收到申请之日起30个工作日内作出批准或者不批准的决定。决定批准的，发给相应等级的资质证书；决定不批准的，应当书面通知当事人并说明理由。"},{"i":35,"n":"第三十五条","txt":"为制作出版物、音像制品等拍摄馆藏文物的，应当征得文物收藏单位同意，并签署拍摄协议，明确文物保护措施和责任。文物收藏单位应当自拍摄工作完成后10个工作日内，将拍摄情况向文物行政主管部门报告。"},{"i":36,"n":"第三十六条","txt":"馆藏文物被盗、被抢或者丢失的，文物收藏单位应当立即向公安机关报案，并同时向主管的文物行政主管部门报告；主管的文物行政主管部门应当在接到文物收藏单位的报告后24小时内，将有关情况报告国务院文物行政主管部门。"},{"i":37,"n":"第三十七条","txt":"国家机关和国有的企业、事业组织等收藏、保管国有文物的，应当履行下列义务："},{"i":38,"n":"第三十八条","txt":"文物收藏单位以外的公民、法人和其他组织，可以依法收藏文物，其依法收藏的文物的所有权受法律保护。"},{"i":39,"n":"第三十九条","txt":"设立文物商店，应当具备下列条件："},{"i":40,"n":"第四十条","txt":"设立文物商店，应当向省、自治区、直辖市人民政府文物行政主管部门提出申请。省、自治区、直辖市人民政府文物行政主管部门应当自收到申请之日起30个工作日内作出批准或者不批准的决定。决定批准的，发给批准文件；决定不批准的，应当书面通知当事人并说明理由。"},{"i":41,"n":"第四十一条","txt":"依法设立的拍卖企业，从事文物拍卖经营活动的，应当有5名以上取得高级文物博物专业技术职务的文物拍卖专业人员，并取得省、自治区、直辖市人民政府文物行政主管部门发给的文物拍卖许可证。"},{"i":42,"n":"第四十二条","txt":"依法设立的拍卖企业申领文物拍卖许可证，应当向省、自治区、直辖市人民政府文物行政主管部门提出申请。省、自治区、直辖市人民政府文物行政主管部门应当自收到申请之日起30个工作日内作出批准或者不批准的决定。决定批准的，发给文物拍卖许可证；决定不批准的，应当书面通知当事人并说明理由。"},{"i":43,"n":"第四十三条","txt":"文物商店购买、销售文物，经营文物拍卖的拍卖企业拍卖文物，应当记录文物的名称、图录、来源、文物的出卖人、委托人和买受人的姓名或者名称、住所、有效身份证件号码或者有效证照号码以及成交价格，并报省、自治区、直辖市人民政府文物行政主管部门备案。接受备案的文物行政主管部门应当依法为其保密，并将该记录保存75年。"},{"i":44,"n":"第四十四条","txt":"国务院文物行政主管部门指定的文物进出境审核机构，应当有5名以上取得中级以上文物博物专业技术职务的文物进出境责任鉴定人员。"},{"i":45,"n":"第四十五条","txt":"运送、邮寄、携带文物出境，应当在文物出境前依法报文物进出境审核机构审核。文物进出境审核机构应当自收到申请之日起15个工作日内作出是否允许出境的决定。"},{"i":46,"n":"第四十六条","txt":"文物进出境审核机构应当对所审核进出境文物的名称、质地、尺寸、级别，当事人的姓名或者名称、住所、有效身份证件号码或者有效证照号码，以及进出境口岸、文物去向和审核日期等内容进行登记。"},{"i":47,"n":"第四十七条","txt":"经审核允许出境的文物，由国务院文物行政主管部门发给文物出境许可证，并由文物进出境审核机构标明文物出境标识。经审核允许出境的文物，应当从国务院文物行政主管部门指定的口岸出境。海关查验文物出境标识后，凭文物出境许可证放行。"},{"i":48,"n":"第四十八条","txt":"文物出境展览的承办单位，应当在举办展览前6个月向国务院文物行政主管部门提出申请。国务院文物行政主管部门应当自收到申请之日起30个工作日内作出批准或者不批准的决定。决定批准的，发给批准文件；决定不批准的，应当书面通知当事人并说明理由。"},{"i":49,"n":"第四十九条","txt":"一级文物中的孤品和易损品，禁止出境展览。禁止出境展览文物的目录，由国务院文物行政主管部门定期公布。"},{"i":50,"n":"第五十条","txt":"文物出境展览的期限不得超过1年。因特殊需要，经原审批机关批准可以延期；但是，延期最长不得超过1年。"},{"i":51,"n":"第五十一条","txt":"文物出境展览期间，出现可能危及展览文物安全情形的，原审批机关可以决定中止或者撤销展览。"},{"i":52,"n":"第五十二条","txt":"临时进境的文物，经海关将文物加封后，交由当事人报文物进出境审核机构审核、登记。文物进出境审核机构查验海关封志完好无损后，对每件临时进境文物标明文物临时进境标识，并登记拍照。"},{"i":53,"n":"第五十三条","txt":"任何单位或者个人不得擅自剥除、更换、挪用或者损毁文物出境标识、文物临时进境标识。"},{"i":54,"n":"第五十四条","txt":"公安机关、工商行政管理、文物、海关、城乡规划、建设等有关部门及其工作人员，违反本条例规定，滥用审批权限、不履行职责或者发现违法行为不予查处的，对负有责任的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":55,"n":"第五十五条","txt":"违反本条例规定，未取得相应等级的文物保护工程资质证书，擅自承担文物保护单位的修缮、迁移、重建工程的，由文物行政主管部门责令限期改正；逾期不改正，或者造成严重后果的，处5万元以上50万元以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":56,"n":"第五十六条","txt":"违反本条例规定，未取得资质证书，擅自从事馆藏文物的修复、复制、拓印活动的，由文物行政主管部门责令停止违法活动；没收违法所得和从事违法活动的专用工具、设备；造成严重后果的，并处1万元以上10万元以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":57,"n":"第五十七条","txt":"文物保护法第六十六条第二款规定的罚款，数额为200元以下。"},{"i":58,"n":"第五十八条","txt":"违反本条例规定，未经批准擅自修复、复制、拓印馆藏珍贵文物的，由文物行政主管部门给予警告；造成严重后果的，处2000元以上2万元以下的罚款；对负有责任的主管人员和其他直接责任人员依法给予行政处分。"},{"i":59,"n":"第五十九条","txt":"考古发掘单位违反本条例规定，未在规定期限内提交结项报告或者考古发掘报告的，由省、自治区、直辖市人民政府文物行政主管部门或者国务院文物行政主管部门责令限期改正；逾期不改正的，对负有责任的主管人员和其他直接责任人员依法给予行政处分。"},{"i":60,"n":"第六十条","txt":"考古发掘单位违反本条例规定，未在规定期限内移交文物的，由省、自治区、直辖市人民政府文物行政主管部门或者国务院文物行政主管部门责令限期改正；逾期不改正，或者造成严重后果的，对负有责任的主管人员和其他直接责任人员依法给予行政处分。"},{"i":61,"n":"第六十一条","txt":"违反本条例规定，文物出境展览超过展览期限的，由国务院文物行政主管部门责令限期改正；对负有责任的主管人员和其他直接责任人员依法给予行政处分。"},{"i":62,"n":"第六十二条","txt":"依照文物保护法第六十六条、第七十三条的规定，单位被处以吊销许可证行政处罚的，应当依法到工商行政管理部门办理变更登记或者注销登记；逾期未办理的，由工商行政管理部门吊销营业执照。"},{"i":63,"n":"第六十三条","txt":"违反本条例规定，改变国有的博物馆、纪念馆、文物保护单位等的事业性收入的用途的，对负有责任的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":64,"n":"第六十四条","txt":"本条例自2003年7月1日起施行。"}],"biaozhunhuafashishitiaoli-2":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国标准化法》（以下简称《标准化法》）的规定，制定本条例。"},{"i":2,"n":"第二条","txt":"对下列需要统一的技术要求，应当制定标准："},{"i":3,"n":"第三条","txt":"国家有计划地发展标准化事业。标准化工作应当纳入各级国民经济和社会发展计划。"},{"i":4,"n":"第四条","txt":"国家鼓励采用国际标准和国外先进标准，积极参与制定国际标准。"},{"i":5,"n":"第五条","txt":"标准化工作的任务是制定标准、组织实施标准和对标准的实施进行监督。"},{"i":6,"n":"第六条","txt":"国务院标准化行政主管部门统一管理全国标准化工作，履行下列职责："},{"i":7,"n":"第七条","txt":"国务院有关行政主管部门分工管理本部门、本行业的标准化工作，履行下列职责："},{"i":8,"n":"第八条","txt":"省、自治区、直辖市人民政府标准化行政主管部门统一管理本行政区域的标准化工作，履行下列职责："},{"i":9,"n":"第九条","txt":"省、自治区、直辖市有关行政主管部门分工管理本行政区域内本部门、本行业的标准化工作，履行下列职责："},{"i":10,"n":"第十条","txt":"市、县标准化行政主管部门和有关行政主管部门的职责分工，由省、自治区、直辖市人民政府规定。"},{"i":11,"n":"第十一条","txt":"对需要在全国范围内统一的下列技术要求，应当制定国家标准（含标准样品的制作）："},{"i":12,"n":"第十二条","txt":"国家标准由国务院标准化行政主管部门编制计划，组织草拟，统一审批、编号、发布。"},{"i":13,"n":"第十三条","txt":"对没有国家标准而又需要在全国某个行业范围内统一的技术要求，可以制定行业标准（含标准样品的制作）。制定行业标准的项目由国务院有关行政主管部门确定。"},{"i":14,"n":"第十四条","txt":"行业标准由国务院有关行政主管部门编制计划，组织草拟，统一审批、编号、发布，并报国务院标准化行政主管部门备案。"},{"i":15,"n":"第十五条","txt":"对没有国家标准和行业标准而又需要在省、自治区、直辖市范围内统一的工业产品的安全、卫生要求，可以制定地方标准。制定地方标准的项目，由省、自治区、直辖市人民政府标准化行政主管部门确定。"},{"i":16,"n":"第十六条","txt":"地方标准由省、自治区、直辖市人民政府标准化行政主管部门编制计划，组织草拟，统一审批、编号、发布，并报国务院标准化行政主管部门和国务院有关行政主管部门备案。"},{"i":17,"n":"第十七条","txt":"企业生产的产品没有国家标准、行业标准和地方标准的，应当制定相应的企业标准，作为组织生产的依据。企业标准由企业组织制定（农业企业标准制定办法另定），并按省、自治区、直辖市人民政府的规定备案。"},{"i":18,"n":"第十八条","txt":"国家标准、行业标准分为强制性标准和推荐性标准。"},{"i":19,"n":"第十九条","txt":"制定标准应当发挥行业协会、科学技术研究机构和学术团体的作用。"},{"i":20,"n":"第二十条","txt":"标准实施后，制定标准的部门应当根据科学技术的发展和经济建设的需要适时进行复审。标准复审周期一般不超过五年。"},{"i":21,"n":"第二十一条","txt":"国家标准、行业标准和地方标准的代号、编号办法，由国务院标准化行政主管部门统一规定。"},{"i":22,"n":"第二十二条","txt":"标准的出版、发行办法，由制定标准的部门规定。"},{"i":23,"n":"第二十三条","txt":"从事科研、生产、经营的单位和个人，必须严格执行强制性标准。不符合强制性标准的产品，禁止生产、销售和进口。"},{"i":24,"n":"第二十四条","txt":"企业生产执行国家标准、行业标准、地方标准或企业标准，应当在产品或其说明书、包装物上标注所执行标准的代号、编号、名称。"},{"i":25,"n":"第二十五条","txt":"出口产品的技术要求由合同双方约定。"},{"i":26,"n":"第二十六条","txt":"企业研制新产品、改进产品、进行技术改造，应当符合标准化要求。"},{"i":27,"n":"第二十七条","txt":"国务院标准化行政主管部门组织或授权国务院有关行政主管部门建立行业认证机构，进行产品质量认证工作。"},{"i":28,"n":"第二十八条","txt":"国务院标准化行政主管部门统一负责全国标准实施的监督。国务院有关行政主管部门分工负责本部门、本行业的标准实施的监督。"},{"i":29,"n":"第二十九条","txt":"国家检验机构由国务院标准化行政主管部门会同国务院有关行政主管部门规划、审查。地方检验机构由省、自治区、直辖市人民政府标准化行政主管部门会同省级有关行政主管部门规划、审查。"},{"i":30,"n":"第三十条","txt":"国务院有关行政主管部门可以根据需要和国家有关规定设立检验机构，负责本行业、本部门的检验工作。"},{"i":31,"n":"第三十一条","txt":"国家机关、社会团体、企业事业单位及全体公民均有权检举、揭发违反强制性标准的行为。"},{"i":32,"n":"第三十二条","txt":"违反《标准化法》和本条例有关规定，有下列情形之一的，由标准化行政主管部门或有关行政主管部门在各自的职权范围内责令限期改进，并可通报批评："},{"i":33,"n":"第三十三条","txt":"生产不符合强制性标准的产品的，应当责令其停止生产，并没收产品，监督销毁或作必要技术处理；处以该批产品货值金额百分之二十至百分之五十的罚款；对有关责任者处以五千元以下罚款。"},{"i":34,"n":"第三十四条","txt":"生产、销售、进口不符合强制性标准的产品，造成严重后果，构成犯罪的，由司法机关依法追究直接责任人员的刑事责任。"},{"i":35,"n":"第三十五条","txt":"当事人对没收产品、没收违法所得和罚款的处罚不服的，可以在接到处罚通知之日起十五日内，向作出处罚决定的机关的上一级机关申请复议；对复议决定不服的，可以在接到复议决定之日起十五日内，向人民法院起诉。当事人也可以在接到处罚通知之日起十五日内，直接向人民法院起诉。当事人逾期不申请复议或者不向人民法院起诉又不履行处罚决定的，由作出处罚决定的机关申请人民法院强制执行。"},{"i":36,"n":"第三十六条","txt":"本条例第三十二条至第三十四条规定的处罚不免除由此产生的对他人的损害赔偿责任。受到损害的有权要求责任人赔偿损失。赔偿责任和赔偿金额纠纷可以由有关行政主管部门处理，当事人也可以直接向人民法院起诉。"},{"i":37,"n":"第三十七条","txt":"标准化工作的监督、检验、管理人员有下列行为之一的，由有关主管部门给予行政处分，构成犯罪的，由司法机关依法追究刑事责任："},{"i":38,"n":"第三十八条","txt":"罚没收入全部上缴财政。对单位的罚款，一律从其自有资金中支付，不得列入成本。对责任人的罚款，不得从公款中核销。"},{"i":39,"n":"第三十九条","txt":"军用标准化管理条例，由国务院、中央军委另行制定。"},{"i":40,"n":"第四十条","txt":"工程建设标准化管理规定，由国务院工程建设主管部门依据《标准化法》和本条例的有关规定另行制定，报国务院批准后实施。"},{"i":41,"n":"第四十一条","txt":"本条例自发布之日起施行。"}],"biaozhunhuafashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国标准化法》（以下简称《标准化法》）的规定，制定本条例。"},{"i":2,"n":"第二条","txt":"对下列需要统一的技术要求，应当制定标准："},{"i":3,"n":"第三条","txt":"国家有计划地发展标准化事业。标准化工作应当纳入各级国民经济和社会发展计划。"},{"i":4,"n":"第四条","txt":"国家鼓励采用国际标准和国外先进标准，积极参与制定国际标准。"},{"i":5,"n":"第五条","txt":"标准化工作的任务是制定标准、组织实施标准和对标准的实施进行监督。"},{"i":6,"n":"第六条","txt":"国务院标准化行政主管部门统一管理全国标准化工作，履行下列职责："},{"i":7,"n":"第七条","txt":"国务院有关行政主管部门分工管理本部门、本行业的标准化工作，履行下列职责："},{"i":8,"n":"第八条","txt":"省、自治区、直辖市人民政府标准化行政主管部门统一管理本行政区域的标准化工作，履行下列职责："},{"i":9,"n":"第九条","txt":"省、自治区、直辖市有关行政主管部门分工管理本行政区域内本部门、本行业的标准化工作，履行下列职责："},{"i":10,"n":"第十条","txt":"市、县标准化行政主管部门和有关行政主管部门的职责分工，由省、自治区、直辖市人民政府规定。"},{"i":11,"n":"第十一条","txt":"对需要在全国范围内统一的下列技术要求，应当制定国家标准（含标准样品的制作）："},{"i":12,"n":"第十二条","txt":"国家标准由国务院标准化行政主管部门编制计划，组织草拟，统一审批、编号、发布。"},{"i":13,"n":"第十三条","txt":"对没有国家标准而又需要在全国某个行业范围内统一的技术要求，可以制定行业标准（含标准样品的制作）。制定行业标准的项目由国务院有关行政主管部门确定。"},{"i":14,"n":"第十四条","txt":"行业标准由国务院有关行政主管部门编制计划，组织草拟，统一审批、编号、发布，并报国务院标准化行政主管部门备案。"},{"i":15,"n":"第十五条","txt":"对没有国家标准和行业标准而又需要在省、自治区、直辖市范围内统一的工业产品的安全、卫生要求，可以制定地方标准。制定地方标准的项目，由省、自治区、直辖市人民政府标准化行政主管部门确定。"},{"i":16,"n":"第十六条","txt":"地方标准由省、自治区、直辖市人民政府标准化行政主管部门编制计划，组织草拟，统一审批、编号、发布，并报国务院标准化行政主管部门和国务院有关行政主管部门备案。"},{"i":17,"n":"第十七条","txt":"企业生产的产品没有国家标准、行业标准和地方标准的，应当制定相应的企业标准，作为组织生产的依据。企业标准由企业组织制定（农业企业标准制定办法另定），并按省、自治区、直辖市人民政府的规定备案。"},{"i":18,"n":"第十八条","txt":"国家标准、行业标准分为强制性标准和推荐性标准。"},{"i":19,"n":"第十九条","txt":"制定标准应当发挥行业协会、科学技术研究机构和学术团体的作用。"},{"i":20,"n":"第二十条","txt":"标准实施后，制定标准的部门应当根据科学技术的发展和经济建设的需要适时进行复审。标准复审周期一般不超过五年。"},{"i":21,"n":"第二十一条","txt":"国家标准、行业标准和地方标准的代号、编号办法，由国务院标准化行政主管部门统一规定。"},{"i":22,"n":"第二十二条","txt":"标准的出版、发行办法，由制定标准的部门规定。"},{"i":23,"n":"第二十三条","txt":"从事科研、生产、经营的单位和个人，必须严格执行强制性标准。不符合强制性标准的产品，禁止生产、销售和进口。"},{"i":24,"n":"第二十四条","txt":"企业生产执行国家标准、行业标准、地方标准或企业标准，应当在产品或其说明书、包装物上标注所执行标准的代号、编号、名称。"},{"i":25,"n":"第二十五条","txt":"出口产品的技术要求由合同双方约定。"},{"i":26,"n":"第二十六条","txt":"企业研制新产品、改进产品、进行技术改造，应当符合标准化要求。"},{"i":27,"n":"第二十七条","txt":"国务院标准化行政主管部门组织或授权国务院有关行政主管部门建立行业认证机构，进行产品质量认证工作。"},{"i":28,"n":"第二十八条","txt":"国务院标准化行政主管部门统一负责全国标准实施的监督。国务院有关行政主管部门分工负责本部门、本行业的标准实施的监督。"},{"i":29,"n":"第二十九条","txt":"国家检验机构由国务院标准化行政主管部门会同国务院有关行政主管部门规划、审查。地方检验机构由省、自治区、直辖市人民政府标准化行政主管部门会同省级有关行政主管部门规划、审查。"},{"i":30,"n":"第三十条","txt":"国务院有关行政主管部门可以根据需要和国家有关规定设立检验机构，负责本行业、本部门的检验工作。"},{"i":31,"n":"第三十一条","txt":"国家机关、社会团体、企业事业单位及全体公民均有权检举、揭发违反强制性标准的行为。"},{"i":32,"n":"第三十二条","txt":"违反《标准化法》和本条例有关规定，有下列情形之一的，由标准化行政主管部门或有关行政主管部门在各自的职权范围内责令限期改进，并可通报批评："},{"i":33,"n":"第三十三条","txt":"生产不符合强制性标准的产品的，应当责令其停止生产，并没收产品，监督销毁或作必要技术处理；处以该批产品货值金额百分之二十至百分之五十的罚款；对有关责任者处以五千元以下罚款。"},{"i":34,"n":"第三十四条","txt":"生产、销售、进口不符合强制性标准的产品，造成严重后果，构成犯罪的，由司法机关依法追究直接责任人员的刑事责任。"},{"i":35,"n":"第三十五条","txt":"当事人对没收产品、没收违法所得和罚款的处罚不服的，可以在接到处罚通知之日起十五日内，向作出处罚决定的机关的上一级机关申请复议；对复议决定不服的，可以在接到复议决定之日起十五日内，向人民法院起诉。当事人也可以在接到处罚通知之日起十五日内，直接向人民法院起诉。当事人逾期不申请复议或者不向人民法院起诉又不履行处罚决定的，由作出处罚决定的机关申请人民法院强制执行。"},{"i":36,"n":"第三十六条","txt":"本条例第三十二条至第三十四条规定的处罚不免除由此产生的对他人的损害赔偿责任。受到损害的有权要求责任人赔偿损失。赔偿责任和赔偿金额纠纷可以由有关行政主管部门处理，当事人也可以直接向人民法院起诉。"},{"i":37,"n":"第三十七条","txt":"标准化工作的监督、检验、管理人员有下列行为之一的，由有关主管部门给予行政处分，构成犯罪的，由司法机关依法追究刑事责任："},{"i":38,"n":"第三十八条","txt":"罚没收入全部上缴财政。对单位的罚款，一律从其自有资金中支付，不得列入成本。对责任人的罚款，不得从公款中核销。"},{"i":39,"n":"第三十九条","txt":"军用标准化管理条例，由国务院、中央军委另行制定。"},{"i":40,"n":"第四十条","txt":"工程建设标准化管理规定，由国务院工程建设主管部门依据《标准化法》和本条例的有关规定另行制定，报国务院批准后实施。"},{"i":41,"n":"第四十一条","txt":"本条例自发布之日起施行。"}],"danganfashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国档案法》（以下简称《档案法》）的规定，制定本条例。"},{"i":2,"n":"第二条","txt":"《档案法》所称档案，其具体范围由国家档案主管部门或者国家档案主管部门会同国家有关部门确定。"},{"i":3,"n":"第三条","txt":"档案工作应当坚持和加强党的领导，全面贯彻党的路线方针政策和决策部署，健全党领导档案工作的体制机制，把党的领导贯彻到档案工作各方面和各环节。"},{"i":4,"n":"第四条","txt":"县级以上人民政府应当加强档案工作，建立健全档案机构，提供档案长久安全保管场所和设施，并将档案事业发展经费列入本级预算。"},{"i":5,"n":"第五条","txt":"国家档案馆馆藏的永久保管档案分一、二、三级管理，分级的具体标准和管理办法由国家档案主管部门制定。"},{"i":6,"n":"第六条","txt":"中央国家机关经国家档案主管部门同意，省、自治区、直辖市有关国家机关经本级档案主管部门同意，可以制定本系统专业档案的具体管理制度和办法。"},{"i":7,"n":"第七条","txt":"县级以上人民政府及其有关部门，应当加强档案宣传教育工作，普及档案知识，传播档案文化，增强全社会档案意识。"},{"i":8,"n":"第八条","txt":"国家加强档案相关专业人才培养，支持高等院校、职业学校设立档案学等相关专业。"},{"i":9,"n":"第九条","txt":"国家鼓励和支持企业事业单位、社会组织和个人等社会力量通过依法兴办实体、资助项目、从事志愿服务以及开展科学研究、技术创新和科技成果推广等形式，参与和支持档案事业的发展。"},{"i":10,"n":"第十条","txt":"有下列情形之一的，由县级以上人民政府、档案主管部门或者本单位按照国家有关规定给予表彰、奖励："},{"i":11,"n":"第十一条","txt":"国家档案主管部门依照《档案法》第八条第一款的规定，履行下列职责："},{"i":12,"n":"第十二条","txt":"县级以上地方档案主管部门依照《档案法》第八条第二款的规定，履行下列职责："},{"i":13,"n":"第十三条","txt":"乡镇人民政府依照《档案法》第八条第三款的规定，履行下列职责："},{"i":14,"n":"第十四条","txt":"机关、团体、企业事业单位和其他组织应当确定档案机构或者档案工作人员，依照《档案法》第九条第一款的规定，履行下列职责："},{"i":15,"n":"第十五条","txt":"各级各类档案馆的设置和管理应当符合国家有关规定。"},{"i":16,"n":"第十六条","txt":"国家档案馆应当配备与其职责和规模相适应的专业人员，依照《档案法》第十条的规定，履行下列职责："},{"i":17,"n":"第十七条","txt":"档案主管部门、档案馆和机关、团体、企业事业单位以及其他组织应当为档案工作人员的教育培训、职称评审、岗位聘用等创造条件，不断提高档案工作人员的专业知识水平和业务能力。"},{"i":18,"n":"第十八条","txt":"按照国家规定应当形成档案的机关、团体、企业事业单位和其他组织，应当建立档案工作责任制，确定档案工作组织结构、职责分工，落实档案工作领导责任、管理责任、执行责任，健全单位主要负责人承担档案完整与安全第一责任人职责相关制度，明确档案管理、档案基础设施建设、档案信息化等工作要求。"},{"i":19,"n":"第十九条","txt":"依照《档案法》第十三条以及国家有关规定应当归档的材料，由机关、团体、企业事业单位和其他组织的各内设机构收集齐全，规范整理，定期交本单位档案机构或者档案工作人员集中管理，任何内设机构和个人不得拒绝归档或者据为己有。"},{"i":20,"n":"第二十条","txt":"机关、团体、企业事业单位和其他组织，应当按照国家档案主管部门关于档案移交的规定，定期向有关的国家档案馆移交档案。"},{"i":21,"n":"第二十一条","txt":"档案馆可以按照国家有关规定，通过接受捐献、购买、代存、交换等方式收集档案。"},{"i":22,"n":"第二十二条","txt":"档案馆应当对所保管的档案采取下列管理措施："},{"i":23,"n":"第二十三条","txt":"县级以上人民政府应当采取措施，保障国家档案馆依法接收档案所需的库房及设施设备。"},{"i":24,"n":"第二十四条","txt":"机关、团体、企业事业单位和其他组织应当定期对本单位保管的保管期限届满的档案进行鉴定，形成鉴定工作报告。"},{"i":25,"n":"第二十五条","txt":"县级以上档案主管部门可以依托国家档案馆，对下列属于国家所有的档案中具有永久保存价值的档案分类别汇集有关目录数据："},{"i":26,"n":"第二十六条","txt":"档案馆和机关、团体、企业事业单位以及其他组织为了收集、交换散失在国外的档案、进行国际文化交流，以及适应经济建设、科学研究和科技成果推广等的需要，经国家档案主管部门或者省、自治区、直辖市档案主管部门依据职权审查批准，可以向国内外的单位或者个人赠送、交换、出售属于国家所有的档案的复制件。"},{"i":27,"n":"第二十七条","txt":"一级档案严禁出境。二级档案需要出境的，应当经国家档案主管部门审查批准。"},{"i":28,"n":"第二十八条","txt":"档案馆和机关、团体、企业事业单位以及其他组织依照《档案法》第二十四条的规定委托档案服务时，应当确定受委托的档案服务企业符合下列条件："},{"i":29,"n":"第二十九条","txt":"国家档案馆应当依照《档案法》的有关规定，分期分批向社会开放档案，并同时公布开放档案的目录。"},{"i":30,"n":"第三十条","txt":"国家档案馆应当建立馆藏档案开放审核协同机制，会同档案形成单位或者移交单位进行档案开放审核。档案形成单位或者移交单位撤销、合并、职权变更的，由有关的国家档案馆会同继续行使其职权的单位共同负责；无继续行使其职权的单位的，由有关的国家档案馆负责。"},{"i":31,"n":"第三十一条","txt":"对于《档案法》第二十七条规定的到期不宜开放的档案，经国家档案馆报同级档案主管部门同意，可以延期向社会开放。"},{"i":32,"n":"第三十二条","txt":"档案馆提供社会利用的档案，应当逐步实现以复制件代替原件。数字、缩微以及其他复制形式的档案复制件，载有档案保管单位签章标识的，具有与档案原件同等的效力。"},{"i":33,"n":"第三十三条","txt":"档案馆可以通过阅览、复制和摘录等形式，依法提供利用档案。"},{"i":34,"n":"第三十四条","txt":"机关、团体、企业事业单位和其他组织以及公民利用国家档案馆保管的未开放的档案，应当经保管该档案的国家档案馆同意，必要时，国家档案馆应当征得档案形成单位或者移交单位同意。"},{"i":35,"n":"第三十五条","txt":"《档案法》第三十二条所称档案的公布，是指通过下列形式首次向社会公开档案的全部或者部分原文："},{"i":36,"n":"第三十六条","txt":"公布属于国家所有的档案，按照下列规定办理："},{"i":37,"n":"第三十七条","txt":"国家档案馆应当根据工作需要和社会需求，开展馆藏档案的开发利用和公布，促进档案文献出版物、档案文化创意产品等的提供和传播。"},{"i":38,"n":"第三十八条","txt":"机关、团体、企业事业单位和其他组织应当加强档案信息化建设，积极推进电子档案管理信息系统建设。"},{"i":39,"n":"第三十九条","txt":"机关、团体、企业事业单位和其他组织应当采取管理措施和技术手段保证电子档案来源可靠、程序规范、要素合规，符合以下条件："},{"i":40,"n":"第四十条","txt":"机关、团体、企业事业单位和其他组织应当按照国家档案主管部门有关规定，定期向有关档案馆移交电子档案。电子档案移交接收网络以及系统环境应当符合国家关于网络安全、数据安全以及保密等的规定。不具备在线移交条件的，应当通过符合安全管理要求的存储介质向档案馆移交电子档案。"},{"i":41,"n":"第四十一条","txt":"档案馆对重要电子档案进行异地备份保管，应当采用磁介质、光介质、缩微胶片等符合安全管理要求的存储介质，定期检测载体的完好程度和数据的可读性。异地备份选址应当满足安全保密等要求。"},{"i":42,"n":"第四十二条","txt":"档案馆和机关、团体、企业事业单位以及其他组织开展传统载体档案数字化工作，应当符合国家档案主管部门有关规定，保证档案数字化成果的质量和安全。"},{"i":43,"n":"第四十三条","txt":"档案馆应当积极创造条件，按照国家有关规定建设、运行维护数字档案馆，为不同网络环境中的档案数字资源的收集、长期安全保存和有效利用提供保障。"},{"i":44,"n":"第四十四条","txt":"国家档案主管部门应当制定数据共享标准，提升档案信息共享服务水平，促进全国档案数字资源跨区域、跨层级、跨部门共享利用工作。"},{"i":45,"n":"第四十五条","txt":"国家档案馆和机关、群团组织、国有企业事业单位应当定期向同级档案主管部门报送本单位档案工作情况。"},{"i":46,"n":"第四十六条","txt":"档案主管部门对处理投诉、举报和监督检查中发现的或者有关部门移送的涉嫌档案违法的线索和案件，应当及时依法组织调查。"},{"i":47,"n":"第四十七条","txt":"县级以上档案主管部门应当加强档案行政执法队伍建设和对档案行政执法人员的教育培训。从事档案行政执法工作的人员，应当通过考试，取得行政执法证件。"},{"i":48,"n":"第四十八条","txt":"国家档案馆违反国家规定擅自扩大或者缩小档案接收范围的，或者不按照国家规定开放、提供利用档案的，由县级以上档案主管部门责令限期改正；情节严重的，由有关机关对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":49,"n":"第四十九条","txt":"单位或者个人将应当归档的材料据为己有，拒绝交档案机构、档案工作人员归档的，或者不按照国家规定向国家档案馆移交档案的，由县级以上档案主管部门责令限期改正；拒不改正的，由有关机关对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":50,"n":"第五十条","txt":"单位或者个人侵占、挪用国家档案馆的馆舍的，由县级以上档案主管部门责令限期改正；情节严重的，由有关机关对负有责任的领导人员和直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任；造成财产损失或者其他损害的，依法承担民事责任。"},{"i":51,"n":"第五十一条","txt":"档案服务企业在提供服务过程中明知存在档案安全隐患而不采取措施的，档案主管部门可以采取约谈、责令限期改正等措施。"},{"i":52,"n":"第五十二条","txt":"本条例自2024年3月1日起施行。《中华人民共和国档案法实施办法》同时废止。"}],"senlinfashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国森林法》（以下简称森林法），制定本条例。"},{"i":2,"n":"第二条","txt":"森林资源，包括森林、林木、林地以及依托森林、林木、林地生存的野生动物、植物和微生物。"},{"i":3,"n":"第三条","txt":"国家依法实行森林、林木和林地登记发证制度。依法登记的森林、林木和林地的所有权、使用权受法律保护，任何单位和个人不得侵犯。"},{"i":4,"n":"第四条","txt":"依法使用的国家所有的森林、林木和林地，按照下列规定登记："},{"i":5,"n":"第五条","txt":"集体所有的森林、林木和林地，由所有者向所在地的县级人民政府林业主管部门提出登记申请，由该县级人民政府登记造册，核发证书，确认所有权。"},{"i":6,"n":"第六条","txt":"改变森林、林木和林地所有权、使用权的，应当依法办理变更登记手续。"},{"i":7,"n":"第七条","txt":"县级以上人民政府林业主管部门应当建立森林、林木和林地权属管理档案。"},{"i":8,"n":"第八条","txt":"国家重点防护林和特种用途林，由国务院林业主管部门提出意见，报国务院批准公布；地方重点防护林和特种用途林，由省、自治区、直辖市人民政府林业主管部门提出意见，报本级人民政府批准公布；其他防护林、用材林、特种用途林以及经济林、薪炭林，由县级人民政府林业主管部门根据国家关于林种划分的规定和本级人民政府的部署组织划定，报本级人民政府批准公布。"},{"i":9,"n":"第九条","txt":"依照森林法第八条第一款第（五）项规定提取的资金，必须专门用于营造坑木、造纸等用材林，不得挪作他用。审计机关和林业主管部门应当加强监督。"},{"i":10,"n":"第十条","txt":"国务院林业主管部门向重点林区派驻的森林资源监督机构，应当加强对重点林区内森林资源保护管理的监督检查。"},{"i":11,"n":"第十一条","txt":"国务院林业主管部门应当定期监测全国森林资源消长和森林生态环境变化的情况。"},{"i":12,"n":"第十二条","txt":"制定林业长远规划，应当遵循下列原则："},{"i":13,"n":"第十三条","txt":"林业长远规划应当包括下列内容："},{"i":14,"n":"第十四条","txt":"全国林业长远规划由国务院林业主管部门会同其他有关部门编制，报国务院批准后施行。"},{"i":15,"n":"第十五条","txt":"国家依法保护森林、林木和林地经营者的合法权益。任何单位和个人不得侵占经营者依法所有的林木和使用的林地。"},{"i":16,"n":"第十六条","txt":"勘查、开采矿藏和修建道路、水利、电力、通讯等工程，需要占用或者征收、征用林地的，必须遵守下列规定："},{"i":17,"n":"第十七条","txt":"需要临时占用林地的，应当经县级以上人民政府林业主管部门批准。"},{"i":18,"n":"第十八条","txt":"森林经营单位在所经营的林地范围内修筑直接为林业生产服务的工程设施，需要占用林地的，由县级以上人民政府林业主管部门批准；修筑其他工程设施，需要将林地转为非林业建设用地的，必须依法办理建设用地审批手续。"},{"i":19,"n":"第十九条","txt":"县级以上人民政府林业主管部门应当根据森林病虫害测报中心和测报点对测报对象的调查和监测情况，定期发布长期、中期、短期森林病虫害预报，并及时提出防治方案。"},{"i":20,"n":"第二十条","txt":"国务院林业主管部门负责确定全国林木种苗检疫对象。省、自治区、直辖市人民政府林业主管部门根据本地区的需要，可以确定本省、自治区、直辖市的林木种苗补充检疫对象，报国务院林业主管部门备案。"},{"i":21,"n":"第二十一条","txt":"禁止毁林开垦、毁林采种和违反操作技术规程采脂、挖笋、掘根、剥树皮及过度修枝的毁林行为。"},{"i":22,"n":"第二十二条","txt":"25度以上的坡地应当用于植树、种草。25度以上的坡耕地应当按照当地人民政府制定的规划，逐步退耕，植树和种草。"},{"i":23,"n":"第二十三条","txt":"发生森林火灾时，当地人民政府必须立即组织军民扑救；有关部门应当积极做好扑救火灾物资的供应、运输和通讯、医疗等工作。"},{"i":24,"n":"第二十四条","txt":"森林法所称森林覆盖率，是指以行政区域为单位森林面积与土地面积的百分比。森林面积，包括郁闭度0.2以上的乔木林地面积和竹林地面积、国家特别规定的灌木林地面积、农田林网以及村旁、路旁、水旁、宅旁林木的覆盖面积。"},{"i":25,"n":"第二十五条","txt":"植树造林应当遵守造林技术规程，实行科学造林，提高林木的成活率。"},{"i":26,"n":"第二十六条","txt":"国家对造林绿化实行部门和单位负责制。"},{"i":27,"n":"第二十七条","txt":"国家保护承包造林者依法享有的林木所有权和其他合法权益。未经发包方和承包方协商一致，不得随意变更或者解除承包造林合同。"},{"i":28,"n":"第二十八条","txt":"国家所有的森林和林木以国有林业企业事业单位、农场、厂矿为单位，集体所有的森林和林木、个人所有的林木以县为单位，制定年森林采伐限额，由省、自治区、直辖市人民政府林业主管部门汇总、平衡，经本级人民政府审核后，报国务院批准；其中，重点林区的年森林采伐限额，由国务院林业主管部门报国务院批准。"},{"i":29,"n":"第二十九条","txt":"采伐森林、林木作为商品销售的，必须纳入国家年度木材生产计划；但是，农村居民采伐自留山上个人所有的薪炭林和自留地、房前屋后个人所有的零星林木除外。"},{"i":30,"n":"第三十条","txt":"申请林木采伐许可证，除应当提交申请采伐林木的所有权证书或者使用权证书外，还应当按照下列规定提交其他有关证明文件："},{"i":31,"n":"第三十一条","txt":"有下列情形之一的，不得核发林木采伐许可证："},{"i":32,"n":"第三十二条","txt":"除森林法已有明确规定的外，林木采伐许可证按照下列规定权限核发："},{"i":33,"n":"第三十三条","txt":"利用外资营造的用材林达到一定规模需要采伐的，应当在国务院批准的年森林采伐限额内，由省、自治区、直辖市人民政府林业主管部门批准，实行采伐限额单列。"},{"i":34,"n":"第三十四条","txt":"木材收购单位和个人不得收购没有林木采伐许可证或者其他合法来源证明的木材。"},{"i":35,"n":"第三十五条","txt":"从林区运出非国家统一调拨的木材，必须持有县级以上人民政府林业主管部门核发的木材运输证。"},{"i":36,"n":"第三十六条","txt":"申请木材运输证，应当提交下列证明文件："},{"i":37,"n":"第三十七条","txt":"经省、自治区、直辖市人民政府批准在林区设立的木材检查站，负责检查木材运输；无证运输木材的，木材检查站应当予以制止，可以暂扣无证运输的木材，并立即报请县级以上人民政府林业主管部门依法处理。"},{"i":38,"n":"第三十八条","txt":"盗伐森林或者其他林木，以立木材积计算不足0.5立方米或者幼树不足20株的，由县级以上人民政府林业主管部门责令补种盗伐株数10倍的树木，没收盗伐的林木或者变卖所得，并处盗伐林木价值3倍至5倍的罚款。"},{"i":39,"n":"第三十九条","txt":"滥伐森林或者其他林木，以立木材积计算不足2立方米或者幼树不足50株的，由县级以上人民政府林业主管部门责令补种滥伐株数5倍的树木，并处滥伐林木价值2倍至3倍的罚款。"},{"i":40,"n":"第四十条","txt":"违反本条例规定，收购没有林木采伐许可证或者其他合法来源证明的木材的，由县级以上人民政府林业主管部门没收非法经营的木材和违法所得，并处违法所得2倍以下的罚款。"},{"i":41,"n":"第四十一条","txt":"违反本条例规定，毁林采种或者违反操作技术规程采脂、挖笋、掘根、剥树皮及过度修枝，致使森林、林木受到毁坏的，依法赔偿损失，由县级以上人民政府林业主管部门责令停止违法行为，补种毁坏株数1倍至3倍的树木，可以处毁坏林木价值1倍至5倍的罚款；拒不补种树木或者补种不符合国家有关规定的，由县级以上人民政府林业主管部门组织代为补种，所需费用由违法者支付。"},{"i":42,"n":"第四十二条","txt":"有下列情形之一的，由县级以上人民政府林业主管部门责令限期完成造林任务；逾期未完成的，可以处应完成而未完成造林任务所需费用2倍以下的罚款；对直接负责的主管人员和其他直接责任人员，依法给予行政处分："},{"i":43,"n":"第四十三条","txt":"未经县级以上人民政府林业主管部门审核同意，擅自改变林地用途的，由县级以上人民政府林业主管部门责令限期恢复原状，并处非法改变用途林地每平方米10元至30元的罚款。"},{"i":44,"n":"第四十四条","txt":"无木材运输证运输木材的，由县级以上人民政府林业主管部门没收非法运输的木材，对货主可以并处非法运输木材价款30%以下的罚款。"},{"i":45,"n":"第四十五条","txt":"擅自移动或者毁坏林业服务标志的，由县级以上人民政府林业主管部门责令限期恢复原状；逾期不恢复原状的，由县级以上人民政府林业主管部门代为恢复，所需费用由违法者支付。"},{"i":46,"n":"第四十六条","txt":"违反本条例规定，未经批准，擅自将防护林和特种用途林改变为其他林种的，由县级以上人民政府林业主管部门收回经营者所获取的森林生态效益补偿，并处所获取森林生态效益补偿3倍以下的罚款。"},{"i":47,"n":"第四十七条","txt":"本条例中县级以上地方人民政府林业主管部门职责权限的划分，由国务院林业主管部门具体规定。"},{"i":48,"n":"第四十八条","txt":"本条例自发布之日起施行。1986年4月28日国务院批准、1986年5月10日林业部发布的《中华人民共和国森林法实施细则》同时废止。"}],"muyingbaojianfashishibanfa":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国母婴保健法》（以下简称母婴保健法），制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事母婴保健服务活动的机构及其人员应当遵守母婴保健法和本办法。"},{"i":3,"n":"第三条","txt":"母婴保健技术服务主要包括下列事项："},{"i":4,"n":"第四条","txt":"公民享有母婴保健的知情选择权。国家保障公民获得适宜的母婴保健服务的权利。"},{"i":5,"n":"第五条","txt":"母婴保健工作以保健为中心，以保障生殖健康为目的，实行保健和临床相结合，面向群体、面向基层和预防为主的方针。"},{"i":6,"n":"第六条","txt":"各级人民政府应当将母婴保健工作纳入本级国民经济和社会发展计划，为母婴保健事业的发展提供必要的经济、技术和物质条件，并对少数民族地区、贫困地区的母婴保健事业给予特殊支持。"},{"i":7,"n":"第七条","txt":"国务院卫生行政部门主管全国母婴保健工作，履行下列职责："},{"i":8,"n":"第八条","txt":"县级以上各级人民政府财政、公安、民政、教育、人力资源社会保障等部门应当在各自职责范围内，配合同级卫生行政部门做好母婴保健工作。"},{"i":9,"n":"第九条","txt":"母婴保健法第七条所称婚前卫生指导，包括下列事项："},{"i":10,"n":"第十条","txt":"在实行婚前医学检查的地区，准备结婚的男女双方在办理结婚登记前，应当到医疗、保健机构进行婚前医学检查。"},{"i":11,"n":"第十一条","txt":"从事婚前医学检查的医疗、保健机构，由其所在地县级人民政府卫生行政部门进行审查；符合条件的，在其《医疗机构执业许可证》上注明。"},{"i":12,"n":"第十二条","txt":"申请从事婚前医学检查的医疗、保健机构应当具备下列条件："},{"i":13,"n":"第十三条","txt":"婚前医学检查包括询问病史、体格及相关检查。"},{"i":14,"n":"第十四条","txt":"经婚前医学检查，医疗、保健机构应当向接受婚前医学检查的当事人出具婚前医学检查证明。"},{"i":15,"n":"第十五条","txt":"经婚前医学检查，医疗、保健机构不能确诊的，应当转到设区的市级以上人民政府卫生行政部门指定的医疗、保健机构确诊。"},{"i":16,"n":"第十六条","txt":"在实行婚前医学检查的地区，婚姻登记机关在办理结婚登记时，应当查验婚前医学检查证明或者母婴保健法第十一条规定的医学鉴定证明。"},{"i":17,"n":"第十七条","txt":"医疗、保健机构应当为育龄妇女提供有关避孕、节育、生育、不育和生殖健康的咨询和医疗保健服务。"},{"i":18,"n":"第十八条","txt":"医疗、保健机构应当为孕产妇提供下列医疗保健服务："},{"i":19,"n":"第十九条","txt":"医疗、保健机构发现孕妇患有下列严重疾病或者接触物理、化学、生物等有毒、有害因素，可能危及孕妇生命安全或者可能严重影响孕妇健康和胎儿正常发育的，应当对孕妇进行医学指导和下列必要的医学检查："},{"i":20,"n":"第二十条","txt":"孕妇有下列情形之一的，医师应当对其进行产前诊断："},{"i":21,"n":"第二十一条","txt":"母婴保健法第十八条规定的胎儿的严重遗传性疾病、胎儿的严重缺陷、孕妇患继续妊娠可能危及其生命健康和安全的严重疾病目录，由国务院卫生行政部门规定。"},{"i":22,"n":"第二十二条","txt":"生育过严重遗传性疾病或者严重缺陷患儿的，再次妊娠前，夫妻双方应当按照国家有关规定到医疗、保健机构进行医学检查。医疗、保健机构应当向当事人介绍有关遗传性疾病的知识，给予咨询、指导。对诊断患有医学上认为不宜生育的严重遗传性疾病的，医师应当向当事人说明情况，并提出医学意见。"},{"i":23,"n":"第二十三条","txt":"严禁采用技术手段对胎儿进行性别鉴定。"},{"i":24,"n":"第二十四条","txt":"国家提倡住院分娩。医疗、保健机构应当按照国务院卫生行政部门制定的技术操作规范，实施消毒接生和新生儿复苏，预防产伤及产后出血等产科并发症，降低孕产妇及围产儿发病率、死亡率。"},{"i":25,"n":"第二十五条","txt":"医疗、保健机构应当按照国家有关规定开展新生儿先天性、遗传性代谢病筛查、诊断、治疗和监测。"},{"i":26,"n":"第二十六条","txt":"医疗、保健机构应当按照规定进行新生儿访视，建立儿童保健手册（卡），定期对其进行健康检查，提供有关预防疾病、合理膳食、促进智力发育等科学知识，做好婴儿多发病、常见病防治等医疗保健服务。"},{"i":27,"n":"第二十七条","txt":"医疗、保健机构应当按照规定的程序和项目对婴儿进行预防接种。"},{"i":28,"n":"第二十八条","txt":"国家推行母乳喂养。医疗、保健机构应当为实施母乳喂养提供技术指导，为住院分娩的产妇提供必要的母乳喂养条件。"},{"i":29,"n":"第二十九条","txt":"母乳代用品产品包装标签应当在显著位置标明母乳喂养的优越性。"},{"i":30,"n":"第三十条","txt":"妇女享有国家规定的产假。有不满1周岁婴儿的妇女，所在单位应当在劳动时间内为其安排一定的哺乳时间。"},{"i":31,"n":"第三十一条","txt":"母婴保健医学技术鉴定委员会分为省、市、县三级。"},{"i":32,"n":"第三十二条","txt":"当事人对婚前医学检查、遗传病诊断、产前诊断结果有异议，需要进一步确诊的，可以自接到检查或者诊断结果之日起15日内向所在地县级或者设区的市级母婴保健医学技术鉴定委员会提出书面鉴定申请。"},{"i":33,"n":"第三十三条","txt":"母婴保健医学技术鉴定委员会进行医学鉴定时须有5名以上相关专业医学技术鉴定委员会成员参加。"},{"i":34,"n":"第三十四条","txt":"县级以上地方人民政府卫生行政部门负责本行政区域内的母婴保健监督管理工作，履行下列监督管理职责："},{"i":35,"n":"第三十五条","txt":"从事遗传病诊断、产前诊断的医疗、保健机构和人员，须经省、自治区、直辖市人民政府卫生行政部门许可；但是，从事产前诊断中产前筛查的医疗、保健机构，须经县级人民政府卫生行政部门许可。"},{"i":36,"n":"第三十六条","txt":"卫生监督人员在执行职务时，应当出示证件。"},{"i":37,"n":"第三十七条","txt":"医疗、保健机构应当根据其从事的业务，配备相应的人员和医疗设备，对从事母婴保健工作的人员加强岗位业务培训和职业道德教育，并定期对其进行检查、考核。"},{"i":38,"n":"第三十八条","txt":"医疗、保健机构应当按照国务院卫生行政部门的规定，对托幼园、所卫生保健工作进行业务指导。"},{"i":39,"n":"第三十九条","txt":"国家建立孕产妇死亡、婴儿死亡和新生儿出生缺陷监测、报告制度。"},{"i":40,"n":"第四十条","txt":"医疗、保健机构或者人员未取得母婴保健技术许可，擅自从事婚前医学检查、遗传病诊断、产前诊断、终止妊娠手术和医学技术鉴定或者出具有关医学证明的，由卫生行政部门给予警告，责令停止违法行为，没收违法所得；违法所得5000元以上的，并处违法所得3倍以上5倍以下的罚款；没有违法所得或者违法所得不足5000元的，并处5000元以上2万元以下的罚款。"},{"i":41,"n":"第四十一条","txt":"从事母婴保健技术服务的人员出具虚假医学证明文件的，依法给予行政处分；有下列情形之一的，由原发证部门撤销相应的母婴保健技术执业资格或者医师执业证书："},{"i":42,"n":"第四十二条","txt":"违反本办法规定进行胎儿性别鉴定的，由卫生行政部门给予警告，责令停止违法行为；对医疗、保健机构直接负责的主管人员和其他直接责任人员，依法给予行政处分。进行胎儿性别鉴定两次以上的或者以营利为目的进行胎儿性别鉴定的，并由原发证机关撤销相应的母婴保健技术执业资格或者医师执业证书。"},{"i":43,"n":"第四十三条","txt":"婚前医学检查证明的格式由国务院卫生行政部门规定。"},{"i":44,"n":"第四十四条","txt":"母婴保健法及本办法所称的医疗、保健机构，是指依照《医疗机构管理条例》取得卫生行政部门医疗机构执业许可的各级各类医疗机构。"},{"i":45,"n":"第四十五条","txt":"本办法自公布之日起施行。"}],"minbanjiaoyucujinfashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国民办教育促进法》（以下简称民办教育促进法），制定本条例。"},{"i":2,"n":"第二条","txt":"国家机构以外的社会组织或者个人可以利用非国家财政性经费举办各级各类民办学校；但是，不得举办实施军事、警察、政治等特殊性质教育的民办学校。"},{"i":3,"n":"第三条","txt":"各级人民政府应当依法支持和规范社会力量举办民办教育，保障民办学校依法办学、自主管理，鼓励、引导民办学校提高质量、办出特色，满足多样化教育需求。"},{"i":4,"n":"第四条","txt":"民办学校应当坚持中国共产党的领导，坚持社会主义办学方向，坚持教育公益性，对受教育者加强社会主义核心价值观教育，落实立德树人根本任务。"},{"i":5,"n":"第五条","txt":"国家机构以外的社会组织或者个人可以单独或者联合举办民办学校。联合举办民办学校的，应当签订联合办学协议，明确合作方式、各方权利义务和争议解决方式等。"},{"i":6,"n":"第六条","txt":"举办民办学校的社会组织或者个人应当有良好的信用状况。举办民办学校可以用货币出资，也可以用实物、建设用地使用权、知识产权等可以用货币估价并可以依法转让的非货币财产作价出资；但是，法律、行政法规规定不得作为出资的财产除外。"},{"i":7,"n":"第七条","txt":"实施义务教育的公办学校不得举办或者参与举办民办学校，也不得转为民办学校。其他公办学校不得举办或者参与举办营利性民办学校。但是，实施职业教育的公办学校可以吸引企业的资本、技术、管理等要素，举办或者参与举办实施职业教育的营利性民办学校。"},{"i":8,"n":"第八条","txt":"地方人民政府不得利用国有企业、公办教育资源举办或者参与举办实施义务教育的民办学校。"},{"i":9,"n":"第九条","txt":"国家鼓励企业以独资、合资、合作等方式依法举办或者参与举办实施职业教育的民办学校。"},{"i":10,"n":"第十条","txt":"举办民办学校，应当按时、足额履行出资义务。民办学校存续期间，举办者不得抽逃出资，不得挪用办学经费。"},{"i":11,"n":"第十一条","txt":"举办者依法制定学校章程，负责推选民办学校首届理事会、董事会或者其他形式决策机构的组成人员。"},{"i":12,"n":"第十二条","txt":"民办学校举办者变更的，应当签订变更协议，但不得涉及学校的法人财产，也不得影响学校发展，不得损害师生权益；现有民办学校的举办者变更的，可以根据其依法享有的合法权益与继任举办者协议约定变更收益。"},{"i":13,"n":"第十三条","txt":"同时举办或者实际控制多所民办学校的，举办者或者实际控制人应当具备与其所开展办学活动相适应的资金、人员、组织机构等条件与能力，并对所举办民办学校承担管理和监督职责。"},{"i":14,"n":"第十四条","txt":"实施国家认可的教育考试、职业资格考试和职业技能等级考试等考试的机构，举办或者参与举办与其所实施的考试相关的民办学校应当符合国家有关规定。"},{"i":15,"n":"第十五条","txt":"设立民办学校的审批权限，依照有关法律、法规的规定执行。"},{"i":16,"n":"第十六条","txt":"国家鼓励民办学校利用互联网技术在线实施教育活动。"},{"i":17,"n":"第十七条","txt":"民办学校的举办者在获得筹设批准书之日起3年内完成筹设的，可以提出正式设立申请。"},{"i":18,"n":"第十八条","txt":"申请正式设立实施学历教育的民办学校的，审批机关受理申请后，应当组织专家委员会评议，由专家委员会提出咨询意见。"},{"i":19,"n":"第十九条","txt":"民办学校的章程应当规定下列主要事项："},{"i":20,"n":"第二十条","txt":"民办学校只能使用一个名称。"},{"i":21,"n":"第二十一条","txt":"民办学校开办资金、注册资本应当与学校类型、层次、办学规模相适应。民办学校正式设立时，开办资金、注册资本应当缴足。"},{"i":22,"n":"第二十二条","txt":"对批准正式设立的民办学校，审批机关应当颁发办学许可证，并向社会公告。"},{"i":23,"n":"第二十三条","txt":"民办学校增设校区应当向审批机关申请地址变更；设立分校应当向分校所在地审批机关单独申请办学许可，并报原审批机关备案。"},{"i":24,"n":"第二十四条","txt":"民办学校依照有关法律、行政法规的规定申请法人登记，登记机关应当依法予以办理。"},{"i":25,"n":"第二十五条","txt":"民办学校理事会、董事会或者其他形式决策机构的负责人应当具有中华人民共和国国籍，具有政治权利和完全民事行为能力，在中国境内定居，品行良好，无故意犯罪记录或者教育领域不良从业记录。"},{"i":26,"n":"第二十六条","txt":"民办学校的理事会、董事会或者其他形式决策机构应当由举办者或者其代表、校长、党组织负责人、教职工代表等共同组成。鼓励民办学校理事会、董事会或者其他形式决策机构吸收社会公众代表，根据需要设独立理事或者独立董事。实施义务教育的民办学校理事会、董事会或者其他形式决策机构组成人员应当具有中华人民共和国国籍，且应当有审批机关委派的代表。"},{"i":27,"n":"第二十七条","txt":"民办学校应当设立监督机构。监督机构应当有党的基层组织代表，且教职工代表不少于1／3。教职工人数少于20人的民办学校可以只设1至2名监事。"},{"i":28,"n":"第二十八条","txt":"民办学校校长依法独立行使教育教学和行政管理职权。"},{"i":29,"n":"第二十九条","txt":"民办学校依照法律、行政法规和国家有关规定，自主开展教育教学活动；使用境外教材的，应当符合国家有关规定。"},{"i":30,"n":"第三十条","txt":"民办学校应当按照招生简章或者招生广告的承诺，开设相应课程，开展教育教学活动，保证教育教学质量。"},{"i":31,"n":"第三十一条","txt":"实施学前教育、学历教育的民办学校享有与同级同类公办学校同等的招生权，可以在审批机关核定的办学规模内，自主确定招生的标准和方式，与公办学校同期招生。"},{"i":32,"n":"第三十二条","txt":"实施高等学历教育的民办学校符合学位授予条件的，依照有关法律、行政法规的规定经审批同意后，可以获得相应的学位授予资格。"},{"i":33,"n":"第三十三条","txt":"民办学校聘任的教师或者教学人员应当具备相应的教师资格或者其他相应的专业资格、资质。"},{"i":34,"n":"第三十四条","txt":"民办学校自主招聘教师和其他工作人员，并应当与所招聘人员依法签订劳动或者聘用合同，明确双方的权利义务等。"},{"i":35,"n":"第三十五条","txt":"民办学校应当建立教师培训制度，为受聘教师接受相应的思想政治培训和业务培训提供条件。"},{"i":36,"n":"第三十六条","txt":"民办学校应当依法保障教职工待遇，按照学校登记的法人类型，按时足额支付工资，足额缴纳社会保险费和住房公积金。国家鼓励民办学校按照有关规定为教职工建立职业年金或者企业年金等补充养老保险。"},{"i":37,"n":"第三十七条","txt":"教育行政部门应当会同有关部门建立民办幼儿园、中小学专任教师劳动、聘用合同备案制度，建立统一档案，记录教师的教龄、工龄，在培训、考核、专业技术职务评聘、表彰奖励、权利保护等方面，统筹规划、统一管理，与公办幼儿园、中小学聘任的教师平等对待。"},{"i":38,"n":"第三十八条","txt":"实施学历教育的民办学校应当依法建立学籍和教学管理制度，并报主管部门备案。"},{"i":39,"n":"第三十九条","txt":"民办学校及其教师、职员、受教育者申请政府设立的有关科研项目、课题等，享有与同级同类公办学校及其教师、职员、受教育者同等的权利。相关项目管理部门应当按规定及时足额拨付科研项目、课题资金。"},{"i":40,"n":"第四十条","txt":"教育行政部门、人力资源社会保障行政部门和其他有关部门，组织有关的评奖评优、文艺体育活动和课题、项目招标，应当为民办学校及其教师、职员、受教育者提供同等的机会。"},{"i":41,"n":"第四十一条","txt":"民办学校应当依照《中华人民共和国会计法》和国家统一的会计制度进行会计核算，编制财务会计报告。"},{"i":42,"n":"第四十二条","txt":"民办学校应当建立办学成本核算制度，基于办学成本和市场需求等因素，遵循公平、合法和诚实信用原则，考虑经济效益与社会效益，合理确定收费项目和标准。对公办学校参与举办、使用国有资产或者接受政府生均经费补助的非营利性民办学校，省、自治区、直辖市人民政府可以对其收费制定最高限价。"},{"i":43,"n":"第四十三条","txt":"民办学校资产中的国有资产的监督、管理，按照国家有关规定执行。"},{"i":44,"n":"第四十四条","txt":"非营利性民办学校收取费用、开展活动的资金往来，应当使用在有关主管部门备案的账户。有关主管部门应当对该账户实施监督。"},{"i":45,"n":"第四十五条","txt":"实施义务教育的民办学校不得与利益关联方进行交易。其他民办学校与利益关联方进行交易的，应当遵循公开、公平、公允的原则，合理定价、规范决策，不得损害国家利益、学校利益和师生权益。"},{"i":46,"n":"第四十六条","txt":"在每个会计年度结束时，民办学校应当委托会计师事务所对年度财务报告进行审计。非营利性民办学校应当从经审计的年度非限定性净资产增加额中，营利性民办学校应当从经审计的年度净收益中，按不低于年度非限定性净资产增加额或者净收益的10％的比例提取发展基金，用于学校的发展。"},{"i":47,"n":"第四十七条","txt":"县级以上地方人民政府应当建立民办教育工作联席会议制度。教育、人力资源社会保障、民政、市场监督管理等部门应当根据职责会同有关部门建立民办学校年度检查和年度报告制度，健全日常监管机制。"},{"i":48,"n":"第四十八条","txt":"审批机关应当及时公开民办学校举办者情况、办学条件等审批信息。"},{"i":49,"n":"第四十九条","txt":"教育行政部门及有关部门应当制定实施学前教育、学历教育民办学校的信息公示清单，监督民办学校定期向社会公开办学条件、教育质量等有关信息。"},{"i":50,"n":"第五十条","txt":"民办学校终止的，应当交回办学许可证，向登记机关办理注销登记，并向社会公告。"},{"i":51,"n":"第五十一条","txt":"国务院教育督导机构及省、自治区、直辖市人民政府负责教育督导的机构应当对县级以上地方人民政府及其有关部门落实支持和规范民办教育发展法定职责的情况进行督导、检查。"},{"i":52,"n":"第五十二条","txt":"各级人民政府及有关部门应当依法健全对民办学校的支持政策，优先扶持办学质量高、特色明显、社会效益显著的民办学校。"},{"i":53,"n":"第五十三条","txt":"民办学校可以依法以捐赠者的姓名、名称命名学校的校舍或者其他教育教学设施、生活设施。捐赠者对民办学校发展做出特殊贡献的，实施高等学历教育的民办学校经国务院教育行政部门按照国家规定的条件批准，其他民办学校经省、自治区、直辖市人民政府教育行政部门或者人力资源社会保障行政部门按照国家规定的条件批准，可以以捐赠者的姓名或者名称作为学校校名。"},{"i":54,"n":"第五十四条","txt":"民办学校享受国家规定的税收优惠政策；其中，非营利性民办学校享受与公办学校同等的税收优惠政策。"},{"i":55,"n":"第五十五条","txt":"地方人民政府在制定闲置校园综合利用方案时，应当考虑当地民办教育发展需求。"},{"i":56,"n":"第五十六条","txt":"在西部地区、边远地区和少数民族地区举办的民办学校申请贷款用于学校自身发展的，享受国家相关的信贷优惠政策。"},{"i":57,"n":"第五十七条","txt":"县级以上地方人民政府可以根据本行政区域的具体情况，设立民办教育发展专项资金，用于支持民办学校提高教育质量和办学水平、奖励举办者等。"},{"i":58,"n":"第五十八条","txt":"县级人民政府根据本行政区域实施学前教育、义务教育或者其他公共教育服务的需要，可以与民办学校签订协议，以购买服务等方式，委托其承担相应教育任务。"},{"i":59,"n":"第五十九条","txt":"县级以上地方人民政府可以采取政府补贴、以奖代补等方式鼓励、支持非营利性民办学校保障教师待遇。"},{"i":60,"n":"第六十条","txt":"国家鼓励、支持保险机构设立适合民办学校的保险产品，探索建立行业互助保险等机制，为民办学校重大事故处理、终止善后、教职工权益保障等事项提供风险保障。"},{"i":61,"n":"第六十一条","txt":"除民办教育促进法和本条例规定的支持与奖励措施外，省、自治区、直辖市人民政府还可以根据实际情况，制定本地区促进民办教育发展的支持与奖励措施。"},{"i":62,"n":"第六十二条","txt":"民办学校举办者及实际控制人、决策机构或者监督机构组成人员有下列情形之一的，由县级以上人民政府教育行政部门、人力资源社会保障行政部门或者其他有关部门依据职责分工责令限期改正，有违法所得的，退还所收费用后没收违法所得；情节严重的，1至5年内不得新成为民办学校举办者或实际控制人、决策机构或者监督机构组成人员；情节特别严重、社会影响恶劣的，永久不得新成为民办学校举办者或实际控制人、决策机构或者监督机构组成人员；构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任："},{"i":63,"n":"第六十三条","txt":"民办学校有下列情形之一的，依照民办教育促进法第六十二条规定给予处罚："},{"i":64,"n":"第六十四条","txt":"民办学校有民办教育促进法第六十二条或者本条例第六十三条规定的违法情形的，由县级以上人民政府教育行政部门、人力资源社会保障行政部门或者其他有关部门依据职责分工对学校决策机构负责人、校长及直接责任人予以警告；情节严重的，1至5年内不得新成为民办学校决策机构负责人或者校长；情节特别严重、社会影响恶劣的，永久不得新成为民办学校决策机构负责人或者校长。"},{"i":65,"n":"第六十五条","txt":"违反本条例规定举办、参与举办民办学校或者在民办学校筹设期内招生的，依照民办教育促进法第六十四条规定给予处罚。"},{"i":66,"n":"第六十六条","txt":"本条例所称现有民办学校，是指2016年11月7日《全国人民代表大会常务委员会关于修改〈中华人民共和国民办教育促进法〉的决定》公布前设立的民办学校。"},{"i":67,"n":"第六十七条","txt":"本条例规定的支持与奖励措施适用于中外合作办学机构。"},{"i":68,"n":"第六十八条","txt":"本条例自2021年9月1日起施行。"}],"xiaofeizhequanyibaohufashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国消费者权益保护法》（以下简称消费者权益保护法）等法律，制定本条例。"},{"i":2,"n":"第二条","txt":"消费者权益保护工作坚持中国共产党的领导，坚持以人民为中心，遵循合法、公平、高效的原则。"},{"i":3,"n":"第三条","txt":"国家加大消费者合法权益保护力度，建立和完善经营者守法、行业自律、消费者参与、政府监管和社会监督相结合的消费者权益保护共同治理体系。"},{"i":4,"n":"第四条","txt":"国家统筹推进消费环境建设，营造安全放心的消费环境，增强消费对经济发展的基础性作用。"},{"i":5,"n":"第五条","txt":"国家加强消费商品和服务的标准体系建设，鼓励经营者制定实施严于国家标准或者行业标准的企业标准，不断提升商品和服务质量。"},{"i":6,"n":"第六条","txt":"国家倡导文明、健康、绿色的消费理念和消费方式，反对奢侈浪费。"},{"i":7,"n":"第七条","txt":"消费者在购买商品、使用商品或者接受服务时，依法享有人身和财产安全不受损害的权利。"},{"i":8,"n":"第八条","txt":"消费者认为经营者提供的商品或者服务可能存在缺陷，有危及人身、财产安全危险的，可以向经营者或者有关行政部门反映情况或者提出建议。"},{"i":9,"n":"第九条","txt":"经营者应当采用通俗易懂的方式，真实、全面地向消费者提供商品或者服务相关信息，不得通过虚构经营者资质、资格或者所获荣誉，虚构商品或者服务交易信息、经营数据，篡改、编造、隐匿用户评价等方式，进行虚假或者引人误解的宣传，欺骗、误导消费者。"},{"i":10,"n":"第十条","txt":"经营者应当按照国家有关规定，以显著方式标明商品的品名、价格和计价单位或者服务的项目、内容、价格和计价方法等信息，做到价签价目齐全、内容真实准确、标识清晰醒目。"},{"i":11,"n":"第十一条","txt":"消费者享有自主选择商品或者服务的权利。经营者不得以暴力、胁迫、限制人身自由等方式或者利用技术手段，强制或者变相强制消费者购买商品或者接受服务，或者排除、限制消费者选择其他经营者提供的商品或者服务。经营者通过搭配、组合等方式提供商品或者服务的，应当以显著方式提请消费者注意。"},{"i":12,"n":"第十二条","txt":"经营者以商业宣传、产品推荐、实物展示或者通知、声明、店堂告示等方式提供商品或者服务，对商品或者服务的数量、质量、价格、售后服务、责任承担等作出承诺的，应当向购买商品或者接受服务的消费者履行其所承诺的内容。"},{"i":13,"n":"第十三条","txt":"经营者应当在其经营场所的显著位置标明其真实名称和标记。"},{"i":14,"n":"第十四条","txt":"经营者通过网络直播等方式提供商品或者服务的，应当依法履行消费者权益保护相关义务。"},{"i":15,"n":"第十五条","txt":"经营者不得通过虚假或者引人误解的宣传，虚构或者夸大商品或者服务的治疗、保健、养生等功效，诱导老年人等消费者购买明显不符合其实际需求的商品或者服务。"},{"i":16,"n":"第十六条","txt":"经营者提供网络游戏服务的，应当符合国家关于网络游戏服务相关时段、时长、功能和内容等方面的规定和标准，针对未成年人设置相应的时间管理、权限管理、消费管理等功能，在注册、登录等环节严格进行用户核验，依法保护未成年人身心健康。"},{"i":17,"n":"第十七条","txt":"经营者使用格式条款的，应当遵守消费者权益保护法第二十六条的规定。经营者不得利用格式条款不合理地免除或者减轻其责任、加重消费者的责任或者限制消费者依法变更或者解除合同、选择诉讼或者仲裁解决消费争议、选择其他经营者的商品或者服务等权利。"},{"i":18,"n":"第十八条","txt":"经营者与消费者约定承担退货、更换、修理等义务的有效期限不得低于国家有关规定的要求。有效期限自经营者向消费者交付商品或者提供服务完结之日起计算，需要经营者另行安装的商品，有效期限自商品安装完成之日起计算。经营者向消费者履行更换义务后，承担更换、修理等义务的有效期限自更换完成之日起重新计算。经营者修理的时间不计入上述有效期限。"},{"i":19,"n":"第十九条","txt":"经营者通过网络、电视、电话、邮购等方式销售商品的，应当遵守消费者权益保护法第二十五条规定，不得擅自扩大不适用无理由退货的商品范围。"},{"i":20,"n":"第二十条","txt":"经营者提供商品或者服务时收取押金的，应当事先与消费者约定退还押金的方式、程序和时限，不得对退还押金设置不合理条件。"},{"i":21,"n":"第二十一条","txt":"经营者决定停业或者迁移服务场所的，应当提前30日在其经营场所、网站、网店首页等的醒目位置公告经营者的有效联系方式等信息。"},{"i":22,"n":"第二十二条","txt":"经营者以收取预付款方式提供商品或者服务的，应当与消费者订立书面合同，约定商品或者服务的具体内容、价款或者费用、预付款退还方式、违约责任等事项。"},{"i":23,"n":"第二十三条","txt":"经营者应当依法保护消费者的个人信息。经营者在提供商品或者服务时，不得过度收集消费者个人信息，不得采用一次概括授权、默认授权等方式，强制或者变相强制消费者同意收集、使用与经营活动无直接关系的个人信息。"},{"i":24,"n":"第二十四条","txt":"未经消费者同意，经营者不得向消费者发送商业性信息或者拨打商业性电话。消费者同意接收商业性信息或者商业性电话的，经营者应当提供明确、便捷的取消方式。消费者选择取消的，经营者应当立即停止发送商业性信息或者拨打商业性电话。"},{"i":25,"n":"第二十五条","txt":"各级人民政府应当加强对消费者权益保护工作的指导，组织、协调、督促有关行政部门落实消费者权益保护工作职责，提升消费者权益保护工作的法治化水平。"},{"i":26,"n":"第二十六条","txt":"消费者与经营者发生消费者权益争议的，可以向市场监督管理部门或者其他有关行政部门投诉。"},{"i":27,"n":"第二十七条","txt":"市场监督管理部门或者其他有关行政部门应当畅通和规范消费者投诉、举报渠道，完善投诉、举报处理流程，依法及时受理和处理投诉、举报，加强对投诉、举报信息的分析应用，开展消费预警和风险提示。"},{"i":28,"n":"第二十八条","txt":"市场监督管理部门和其他有关行政部门应当加强消费者权益保护工作的协同配合和信息共享，依照法律、法规的规定，在各自的职责范围内，对经营者提供的商品和服务实施抽查检验等监管措施，及时查处侵害消费者合法权益的行为。"},{"i":29,"n":"第二十九条","txt":"市场监督管理部门和其他有关行政部门应当加强消费领域信用体系建设，依法公示有关行政许可、行政处罚、抽查检验结果、消费投诉等信息，依法对违法失信经营者实施惩戒。"},{"i":30,"n":"第三十条","txt":"有关行政部门应当加强消费知识的宣传普及，倡导文明、健康、绿色消费，提高消费者依法、理性维权的意识和能力；加强对经营者的普法宣传、行政指导和合规指引，提高经营者依法经营的意识。"},{"i":31,"n":"第三十一条","txt":"国家完善绿色消费的标准、认证和信息披露体系，鼓励经营者对商品和服务作出绿色消费方面的信息披露或者承诺，依法查处虚假信息披露和承诺的行为。"},{"i":32,"n":"第三十二条","txt":"行业协会商会等组织应当加强行业自律，引导、督促经营者守法诚信经营，制定的行业规则、自律规则、示范合同和相关标准等应当有利于保护消费者合法权益。"},{"i":33,"n":"第三十三条","txt":"国家鼓励、支持一切组织和个人对损害消费者合法权益的行为进行社会监督。"},{"i":34,"n":"第三十四条","txt":"消费者协会和其他依法成立的消费者组织应当按照消费者权益保护法的规定履行职责。"},{"i":35,"n":"第三十五条","txt":"各级人民政府应当加强消费者协会组织建设，对消费者协会履行职责予以必要的经费等支持。"},{"i":36,"n":"第三十六条","txt":"有关行政部门应当认真听取消费者协会的意见和建议。对于消费者协会向有关行政部门反映的侵害消费者合法权益的问题，有关行政部门应当及时调查处理并予以回复；对于立案查处的案件，有关行政部门应当将处理结果告知消费者协会。"},{"i":37,"n":"第三十七条","txt":"消费者协会应当加强消费普法宣传和消费引导，向消费者提供消费维权服务与支持，提高消费者维护自身合法权益的能力。"},{"i":38,"n":"第三十八条","txt":"消费者协会可以组织开展比较试验、消费调查、消费评议、投诉信息公示、对投诉商品提请鉴定、发布消费提示警示等，反映商品和服务状况、消费者意见和消费维权情况。"},{"i":39,"n":"第三十九条","txt":"消费者协会可以就消费者权益保护事项向有关经营者、行业组织提出改进意见或者进行指导谈话，加强消费者、经营者、行业组织、专业机构、有关行政部门等各相关方的组织协调，推动解决涉及消费者合法权益保护的重要问题。"},{"i":40,"n":"第四十条","txt":"消费者协会可以就消费者投诉的损害消费者合法权益的行为开展调查，与有关经营者核实情况，约请有关经营者到场陈述事实意见、提供证据资料等。"},{"i":41,"n":"第四十一条","txt":"对侵害众多消费者合法权益的行为，中国消费者协会以及在省、自治区、直辖市设立的消费者协会，可以向人民法院提起诉讼。"},{"i":42,"n":"第四十二条","txt":"消费者应当文明、理性消费，提高自我保护意识，依法维护自身合法权益，在发生消费争议时依法维权。"},{"i":43,"n":"第四十三条","txt":"各级人民政府市场监督管理部门和其他有关行政部门应当推动、健全消费争议多元化解决机制，引导消费者依法通过协商、调解、投诉、仲裁、诉讼等方式维护自身合法权益。"},{"i":44,"n":"第四十四条","txt":"经营者应当建立便捷、高效的投诉处理机制，及时解决消费争议。"},{"i":45,"n":"第四十五条","txt":"消费者和经营者发生消费争议，请求消费者协会或者依法成立的其他调解组织进行调解的，相关组织应当及时处理。"},{"i":46,"n":"第四十六条","txt":"消费者和经营者发生消费争议向市场监督管理部门或者其他有关行政部门投诉的，应当提供真实身份信息，有明确的被投诉人、具体的投诉请求和事实依据。"},{"i":47,"n":"第四十七条","txt":"因消费争议需要对商品或者服务质量进行鉴定、检测的，消费者和经营者可以协商确定鉴定、检测机构。无法协商一致的，受理消费者投诉的市场监督管理部门或者其他有关行政部门可以指定鉴定、检测机构。"},{"i":48,"n":"第四十八条","txt":"经营者提供商品或者服务，违反消费者权益保护法和本条例有关规定，侵害消费者合法权益的，依法承担民事责任。"},{"i":49,"n":"第四十九条","txt":"经营者提供商品或者服务有欺诈行为的，消费者有权根据消费者权益保护法第五十五条第一款的规定要求经营者予以赔偿。但是，商品或者服务的标签标识、说明书、宣传材料等存在不影响商品或者服务质量且不会对消费者造成误导的瑕疵的除外。"},{"i":50,"n":"第五十条","txt":"经营者违反本条例第十条至第十四条、第十六条、第十七条、第十九条至第二十一条规定，其他有关法律、法规对处罚机关和处罚方式有规定的，依照法律、法规的规定执行；法律、法规未作规定的，由市场监督管理部门或者其他有关行政部门责令改正，可以根据情节单处或者并处警告、没收违法所得、处以违法所得1倍以上5倍以下的罚款，没有违法所得的，处以30万元以下的罚款；情节严重的，责令停业整顿、吊销营业执照。"},{"i":51,"n":"第五十一条","txt":"经营者主动消除或者减轻违法行为危害后果的，违法行为轻微并及时改正且没有造成危害后果的，或者初次违法且危害后果轻微并及时改正的，依照《中华人民共和国行政处罚法》的规定从轻、减轻或者不予处罚。"},{"i":52,"n":"第五十二条","txt":"有关行政部门工作人员未按照本条例规定履行消费者权益保护职责，玩忽职守或者包庇经营者侵害消费者合法权益的行为的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":53,"n":"第五十三条","txt":"本条例自2024年7月1日起施行。"}],"yuyefashishixize":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国渔业法》（以下简称《渔业法》）第三十四条的规定，制定本实施细则。"},{"i":2,"n":"第二条","txt":"《渔业法》及本实施细则中下列用语的含义是："},{"i":3,"n":"第三条","txt":"国家对渔业的监督管理，实行统一领导、分级管理。"},{"i":4,"n":"第四条","txt":"“机动渔船底拖网禁渔区线”内侧海域的渔业，由有关省、自治区、直辖市人民政府渔业行政主管部门协商划定监督管理范围；划定监督管理范围有困难的，可划叠区或者共管区管理，必要时由国务院渔业行政主管部门决定。"},{"i":5,"n":"第五条","txt":"渔场和渔汛生产，应当以渔业资源可捕量为依据，按照有利于保护、增殖和合理利用渔业资源，优先安排邻近地区、兼顾其他地区的原则，统筹安排。"},{"i":6,"n":"第六条","txt":"国务院渔业行政主管部门的渔政渔港监督管理机构，代表国家行使渔政渔港监督管理权。"},{"i":7,"n":"第七条","txt":"渔政检查人员有权对各种渔业及渔业船舶的证件、渔船、渔具、渔获物和捕捞方法，进行检查。"},{"i":8,"n":"第八条","txt":"渔业行政主管部门及其所属的渔政监督管理机构，应当与公安、海监、交通、环保、工商行政管理等有关部门相互协作，监督检查渔业法规的施行。"},{"i":9,"n":"第九条","txt":"群众性护渔管理组织，应当在当地县级以上人民政府渔业行政主管部门的业务指导下，依法开展护渔管理工作。"},{"i":10,"n":"第十条","txt":"使用全民所有的水面、滩涂，从事养殖生产的全民所有制单位和集体所有制单位，应当向县级以上地方人民政府申请养殖使用证。"},{"i":11,"n":"第十一条","txt":"领取养殖使用证的单位，无正当理由未从事养殖生产，或者放养量低于当地同类养殖水域平均放养量60%的，应当视为荒芜。"},{"i":12,"n":"第十二条","txt":"全民所有的水面、滩涂中的鱼、虾、蟹、贝、藻类的自然产卵场、繁殖场、索饵场及重要的洄游通道必须予以保护，不得划作养殖场所。"},{"i":13,"n":"第十三条","txt":"国家建设征用集体所有的水面、滩涂，按照国家土地管理法规办理。"},{"i":14,"n":"第十四条","txt":"近海渔场与外海渔场的划分："},{"i":15,"n":"第十五条","txt":"国家对捕捞业，实行捕捞许可制度。"},{"i":16,"n":"第十六条","txt":"在中华人民共和国管辖水域，外商投资的渔业企业，未经国务院有关主管部门批准，不得从事近海捕捞业。"},{"i":17,"n":"第十七条","txt":"有下列情形之一的，不得发放捕捞许可证："},{"i":18,"n":"第十八条","txt":"娱乐性游钓和在尚未养殖、管理的滩涂手工采集零星水产品的，不必申请捕捞许可证，但应当加强管理，防止破坏渔业资源。具体管理办法由县级以上人民政府制定。"},{"i":19,"n":"第十九条","txt":"因科学研究等特殊需要，在禁渔区、禁渔期捕捞，或者使用禁用的渔具、捕捞方法，或者捕捞重点保护的渔业资源品种，必须经省级以上人民政府渔业行政主管部门批准。"},{"i":20,"n":"第二十条","txt":"禁止使用电力、鱼鹰捕鱼和敲䑩作业。在特定水域确有必要使用电力或者鱼鹰捕鱼时，必须经省、自治区、直辖市人民政府渔业行政主管部门批准。"},{"i":21,"n":"第二十一条","txt":"县级以上人民政府渔业行政主管部门，应当依照本实施细则第三条规定的管理权限，确定重点保护的渔业资源品种及采捕标准。在重要鱼、虾、蟹、贝、藻类，以及其他重要水生生物的产卵场、索饵场、越冬场和洄游通道，规定禁渔区和禁渔期，禁止使用或者限制使用的渔具和捕捞方法，最小网目尺寸，以及制定其他保护渔业资源的措施。"},{"i":22,"n":"第二十二条","txt":"在“机动渔船底拖网禁渔区线”内侧建造人工鱼礁的，必须经有关省、自治区、直辖市人民政府渔业行政主管部门或其授权单位批准。"},{"i":23,"n":"第二十三条","txt":"定置渔业一般不得跨县作业。县级以上人民政府渔业行政主管部门应当限制其网桩数量、作业场所，并规定禁渔期。海洋定置渔业，不得越出“机动渔船底拖网禁渔区线”。"},{"i":24,"n":"第二十四条","txt":"因养殖或者其他特殊需要，捕捞鳗鲡、鲥鱼、中华绒螯蟹、真鲷、石斑鱼等有重要经济价值的水生动物苗种或者禁捕的怀卵亲体的，必须经国务院渔业行政主管部门或者省、自治区、直辖市人民政府渔业行政主管部门批准，并领取专项许可证件，方可在指定区域和时间内，按照批准限额捕捞。捕捞其他有重要经济价值的水生动物苗种的批准权，由省、自治区、直辖市人民政府渔业行政主管部门规定。"},{"i":25,"n":"第二十五条","txt":"禁止捕捞中国对虾苗种和春季亲虾。因养殖需要中国对虾怀卵亲体的，应当限期由养殖单位自行培育，期限及管理办法由国务院渔业行政主管部门制定。"},{"i":26,"n":"第二十六条","txt":"任何单位和个人，在鱼、虾、蟹、贝幼苗的重点产区直接引水、用水的，应当采取避开幼苗的密集期、密集区，或者设置网栅等保护措施。"},{"i":27,"n":"第二十七条","txt":"各级渔业行政主管部门，应当对渔业水域污染情况进行监测；渔业环境保护监测网，应当纳入全国环境监测网络。因污染造成渔业损失的，应当由渔政渔港监督管理部门协同环保部门调查处理。"},{"i":28,"n":"第二十八条","txt":"在重点渔业水域不得从事拆船业。在其他渔业水域从事拆船业，造成渔业资源损害的，由拆船单位依照有关规定负责赔偿。"},{"i":29,"n":"第二十九条","txt":"依照《渔业法》第二十八条规定处以罚款的，按下列规定执行："},{"i":30,"n":"第三十条","txt":"依照《渔业法》第二十九条规定处以罚款的，按罚款一千元以下执行。"},{"i":31,"n":"第三十一条","txt":"依照《渔业法》第三十条规定需处以罚款的，按下列规定执行："},{"i":32,"n":"第三十二条","txt":"依照《渔业法》第三十一条规定需处以罚款的，按下列规定执行："},{"i":33,"n":"第三十三条","txt":"买卖、出租或者以其他形式非法转让以及涂改捕捞许可证的，没收违法所得，吊销捕捞许可证，可以并处一百元至一千元罚款。"},{"i":34,"n":"第三十四条","txt":"依照《渔业法》第二十八条、第三十条、第三十一条、第三十二条规定需处以罚款的，对船长或者单位负责人可以视情节另处一百元至五百元罚款。"},{"i":35,"n":"第三十五条","txt":"未按《渔业法》和本实施细则有关规定，采取保护措施，造成渔业资源损失的，围湖造田或者未经批准围垦沿海滩涂的，应当依法承担责任。"},{"i":36,"n":"第三十六条","txt":"外商投资的渔业企业，违反本实施细则第十六条规定，没收渔获物和违法所得，可以并处三千元至五万元罚款。"},{"i":37,"n":"第三十七条","txt":"外国人、外国渔船违反《渔业法》第八条规定，擅自进入中华人民共和国管辖水域从事渔业生产或者渔业资源调查活动的，渔业行政主管部门或其所属的渔政监督管理机构应当令其离开或者将其驱逐，并可处以罚款和没收渔获物、渔具。"},{"i":38,"n":"第三十八条","txt":"渔业行政主管部门或其所属的渔政监督管理机构进行处罚时，应当填发处罚决定书；处以罚款及没收渔具、渔获物和违法所得的，应当开具凭证，并在捕捞许可证上载明。"},{"i":39,"n":"第三十九条","txt":"有下列行为之一的，由公安机关依照《中华人民共和国治安管理处罚条例》的规定处罚；构成犯罪的，由司法机关依法追究刑事责任："},{"i":40,"n":"第四十条","txt":"渔政检查人员玩忽职守或者徇私枉法的，由其所在单位或者上级主管部门给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":41,"n":"第四十一条","txt":"本实施细则由农牧渔业部负责解释。"},{"i":42,"n":"第四十二条","txt":"本实施细则自发布之日起施行。"}],"yancaozhuanmaifashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国烟草专卖法》（以下简称《烟草专卖法》），制定本条例。"},{"i":2,"n":"第二条","txt":"烟草专卖是指国家对烟草专卖品的生产、销售和进出口业务实行垄断经营、统一管理的制度。"},{"i":3,"n":"第三条","txt":"烟草专卖品中的烟丝是指用烟叶、复烤烟叶、烟草薄片为原料加工制成的丝、末、粒状商品。"},{"i":4,"n":"第四条","txt":"国务院和省、自治区、直辖市的烟草专卖行政主管部门职责及领导体制，依照《烟草专卖法》第四条的规定执行。设有烟草专卖行政主管部门的市、县，由市、县烟草专卖行政主管部门主管本行政区内的烟草专卖工作，受上一级烟草专卖行政主管部门和本级人民政府的双重领导，以上一级烟草专卖行政主管部门的领导为主。"},{"i":5,"n":"第五条","txt":"国家对卷烟、雪茄烟焦油含量和用于卷烟、雪茄烟的主要添加剂实行控制。烟草制品生产企业不得违反国家有关规定使用有害的添加剂和色素。"},{"i":6,"n":"第六条","txt":"从事烟草专卖品的生产、批发、零售业务，以及经营烟草专卖品进出口业务和经营外国烟草制品购销业务的，必须依照《烟草专卖法》和本条例的规定，申请领取烟草专卖许可证。"},{"i":7,"n":"第七条","txt":"取得烟草专卖生产企业许可证，应当具备下列条件："},{"i":8,"n":"第八条","txt":"取得烟草专卖批发企业许可证，应当具备下列条件："},{"i":9,"n":"第九条","txt":"取得烟草专卖零售许可证，应当具备下列条件："},{"i":10,"n":"第十条","txt":"烟草专卖行政主管部门依照《烟草专卖法》及本条例的规定，发放烟草专卖许可证和烟草专卖品准运证并实施管理。"},{"i":11,"n":"第十一条","txt":"申请领取烟草专卖生产企业许可证的，应当向省、自治区、直辖市（以下简称省级）烟草专卖行政主管部门提出申请，由省级烟草专卖行政主管部门审查签署意见，报国务院烟草专卖行政主管部门审批发证。"},{"i":12,"n":"第十二条","txt":"申请领取烟草专卖批发企业许可证，进行跨省、自治区、直辖市经营的，应当向省级烟草专卖行政主管部门提出申请，由省级烟草专卖行政主管部门审查签署意见，报国务院烟草专卖行政主管部门审批发证。"},{"i":13,"n":"第十三条","txt":"申请领取烟草专卖零售许可证，依照《烟草专卖法》的规定办理。"},{"i":14,"n":"第十四条","txt":"烟草专卖许可证的发证机关可以定期或者不定期地对取得烟草专卖许可证的企业、个人进行检查。经检查不符合《烟草专卖法》和本条例规定条件的，烟草专卖许可证的发证机关可以责令暂停烟草专卖业务、进行整顿，直至取消其从事烟草专卖业务的资格。"},{"i":15,"n":"第十五条","txt":"国务院烟草专卖行政主管部门按照合理布局的要求，会同有关省、自治区、直辖市人民政府依据国家计划，根据良种化、区域化、规范化的原则制定烟叶种植规划。"},{"i":16,"n":"第十六条","txt":"烟叶由烟草公司或其委托单位依法统一收购。烟草公司或其委托单位根据需要，可以在国家下达烟叶收购计划的地区设立烟叶收购站（点）收购烟叶。设立烟叶收购站（点），应当经设区的市级烟草专卖行政主管部门批准。未经批准，任何单位和个人不得收购烟叶。"},{"i":17,"n":"第十七条","txt":"地方烟草专卖行政主管部门组织同级有关部门和烟叶生产者的代表组成烟叶评级小组，协调烟叶收购等级评定工作。"},{"i":18,"n":"第十八条","txt":"国家储备、出口烟叶的计划和烟叶调拨计划，由国务院计划部门下达。"},{"i":19,"n":"第十九条","txt":"设立烟草制品生产企业，应当由省级烟草专卖行政主管部门报经国务院烟草专卖行政主管部门批准，取得烟草专卖生产企业许可证，并经工商行政管理部门核准登记。"},{"i":20,"n":"第二十条","txt":"烟草制品生产企业必须严格执行国家下达的生产计划。"},{"i":21,"n":"第二十一条","txt":"禁止使用霉烂烟叶生产卷烟、雪茄烟和烟丝。"},{"i":22,"n":"第二十二条","txt":"卷烟、雪茄烟和有包装的烟丝，应当使用注册商标。"},{"i":23,"n":"第二十三条","txt":"取得烟草专卖批发企业许可证的企业，应当在许可证规定的经营范围和地域范围内，从事烟草制品的批发业务。"},{"i":24,"n":"第二十四条","txt":"无烟草专卖批发企业许可证的单位或者个人，一次销售卷烟、雪茄烟50条以上的，视为无烟草专卖批发企业许可证从事烟草制品批发业务。"},{"i":25,"n":"第二十五条","txt":"任何单位或者个人不得销售非法生产的烟草制品。"},{"i":26,"n":"第二十六条","txt":"烟草专卖生产企业和烟草专卖批发企业，不得向无烟草专卖零售许可证的单位或者个人提供烟草制品。"},{"i":27,"n":"第二十七条","txt":"在中国境内销售的卷烟、雪茄烟，应当在小包、条包上标注焦油含量级和“吸烟有害健康”的中文字样。"},{"i":28,"n":"第二十八条","txt":"国务院烟草专卖行政主管部门在必要时，可以根据市场供需情况下达省、自治区、直辖市之间的卷烟、雪茄烟调拨任务。"},{"i":29,"n":"第二十九条","txt":"严禁销售霉坏、变质的烟草制品。霉坏、变质的烟草制品，由烟草专卖行政主管部门或者有关行政管理部门监督销毁。"},{"i":30,"n":"第三十条","txt":"有关部门依法查获的假冒商标烟草制品，应当交由烟草专卖行政主管部门按照国家有关规定公开销毁，禁止以任何方式销售。"},{"i":31,"n":"第三十一条","txt":"假冒商标烟草制品的鉴别检测工作，由国务院产品质量监督管理部门和省、自治区、直辖市人民政府产品质量监督管理部门指定的烟草质量检测站进行。"},{"i":32,"n":"第三十二条","txt":"烟草专卖品准运证由省级以上烟草专卖行政主管部门或其授权的机构审批、发放。烟草专卖品准运证的管理办法由国务院烟草专卖行政主管部门制定。"},{"i":33,"n":"第三十三条","txt":"跨省、自治区、直辖市运输进口的烟草专卖品、国产烟草专用机械和烟用丝束、滤嘴棒以及分切的进口卷烟纸，应当凭国务院烟草专卖行政主管部门或其授权的机构签发的烟草专卖品准运证办理托运或者自运。"},{"i":34,"n":"第三十四条","txt":"有下列情形之一的，为无烟草专卖品准运证运输烟草专卖品："},{"i":35,"n":"第三十五条","txt":"海关监管的烟草制品的转关运输，按照国家有关海关转关运输的规定办理运输手续。"},{"i":36,"n":"第三十六条","txt":"烟草专卖批发企业和烟草制品生产企业只能从取得烟草专卖生产企业许可证的企业购买卷烟纸、滤嘴棒、烟用丝束和烟草专用机械。"},{"i":37,"n":"第三十七条","txt":"烟草专用机械的购进、出售、转让，必须经国务院烟草专卖行政主管部门批准。"},{"i":38,"n":"第三十八条","txt":"任何单位或者个人不得销售非法生产的烟草专用机械、卷烟纸、滤嘴棒及烟用丝束。"},{"i":39,"n":"第三十九条","txt":"设立外商投资的烟草专卖生产企业，应当报经国务院烟草专卖行政主管部门审查同意后，方可按照国家有关规定批准立项。"},{"i":40,"n":"第四十条","txt":"进口烟草专卖品的计划应当报国务院烟草专卖行政主管部门审查批准。"},{"i":41,"n":"第四十一条","txt":"免税进口的烟草制品应当存放在海关指定的保税仓库内，并由国务院烟草专卖行政主管部门指定的地方烟草专卖行政主管部门与海关共同加锁管理。海关凭国务院烟草专卖行政主管部门批准的免税进口计划分批核销免税进口外国烟草制品的数量。"},{"i":42,"n":"第四十二条","txt":"在海关监管区内经营免税的卷烟、雪茄烟的，只能零售，并应当在卷烟、雪茄烟的小包、条包上标注国务院烟草专卖行政主管部门规定的专门标志。"},{"i":43,"n":"第四十三条","txt":"专供出口的卷烟、雪茄烟，应当在小包、条包上标注“专供出口”中文字样。"},{"i":44,"n":"第四十四条","txt":"烟草专卖行政主管部门依法对执行《烟草专卖法》及本条例的情况进行监督、检查，查处违反《烟草专卖法》及本条例的案件，并会同国家有关部门查处烟草专卖品的走私贩私、假冒伪劣行为。"},{"i":45,"n":"第四十五条","txt":"国务院烟草专卖行政主管部门在必要时，可以根据烟草专卖工作的实际情况，在重点地区设立派出机构；省级烟草专卖行政主管部门在必要时，可以向烟草专卖品生产、经营企业派驻人员。派出机构和派驻人员在派出部门的授权范围内监督、检查烟草专卖品的生产、经营活动。"},{"i":46,"n":"第四十六条","txt":"烟草专卖行政主管部门查处违反《烟草专卖法》和本条例的案件时，可以行使下列职权："},{"i":47,"n":"第四十七条","txt":"烟草专卖行政主管部门或者烟草专卖行政主管部门会同有关部门，可以依法对非法运输烟草专卖品的活动进行检查、处理。"},{"i":48,"n":"第四十八条","txt":"人民法院和行政机关依法没收的烟草专卖品以及充抵罚金、罚款和税款的烟草专卖品，按照国家有关规定进行拍卖的，竞买人应当持有烟草专卖批发企业许可证。"},{"i":49,"n":"第四十九条","txt":"烟草专卖行政主管部门的专卖管理检查人员执行公务时，应当佩戴国务院烟草专卖行政主管部门制发的徽章，出示省级以上烟草专卖行政主管部门签发的检查证件。"},{"i":50,"n":"第五十条","txt":"对检举烟草专卖违法案件的有功单位和个人，给予奖励。"},{"i":51,"n":"第五十一条","txt":"依照《烟草专卖法》第二十八条规定处罚的，按照下列规定执行："},{"i":52,"n":"第五十二条","txt":"依照《烟草专卖法》第二十九条规定处罚的，按照下列规定执行："},{"i":53,"n":"第五十三条","txt":"依照《烟草专卖法》第三十条规定处罚的，按照下列规定执行："},{"i":54,"n":"第五十四条","txt":"依照《烟草专卖法》第三十一条规定，无烟草专卖批发企业许可证经营烟草制品批发业务的，由烟草专卖行政主管部门责令关闭或者停止经营烟草制品批发业务，没收违法所得，处以违法批发的烟草制品价值50%以上1倍以下的罚款。"},{"i":55,"n":"第五十五条","txt":"取得烟草专卖批发企业许可证的单位违反本条例第二十三条第一款的规定，超越经营范围和地域范围，从事烟草制品批发业务的，由烟草专卖行政主管部门责令暂停经营批发业务，没收违法所得，处以违法经营的烟草制品价值10%以上20%以下的罚款。"},{"i":56,"n":"第五十六条","txt":"取得烟草专卖零售许可证的企业或者个人违反本条例第二十三条第二款的规定，未在当地烟草专卖批发企业进货的，由烟草专卖行政主管部门没收违法所得，可处以进货总额5%以上10%以下的罚款。"},{"i":57,"n":"第五十七条","txt":"无烟草专卖零售许可证经营烟草制品零售业务的，由工商行政管理部门或者由工商行政管理部门根据烟草专卖行政主管部门的意见，责令停止经营烟草制品零售业务，没收违法所得，处以违法经营总额20%以上50%以下的罚款。"},{"i":58,"n":"第五十八条","txt":"违反本条例第二十五条、第三十八条第一款规定销售非法生产的烟草专卖品的，由烟草专卖行政主管部门责令停止销售，没收违法所得，处以违法销售总额20%以上50%以下的罚款，并将非法销售的烟草专卖品公开销毁。"},{"i":59,"n":"第五十九条","txt":"违反本条例规定，未取得国务院烟草专卖行政主管部门颁发的烟草专卖批发企业许可证，擅自跨省、自治区、直辖市从事烟草制品批发业务的，由烟草专卖行政主管部门处以批发总额10%以上20%以下的罚款。"},{"i":60,"n":"第六十条","txt":"违反本条例第二十六条、第三十六条第二款规定，为无烟草专卖许可证的单位或者个人提供烟草专卖品的，由烟草专卖行政主管部门没收违法所得，并处以销售总额20%以上50%以下的罚款。"},{"i":61,"n":"第六十一条","txt":"违反本条例第三十六条第一款规定，烟草专卖批发企业和烟草制品生产企业从无烟草专卖生产企业许可证的企业购买卷烟纸、滤嘴棒、烟用丝束、烟草专用机械的，由烟草专卖行政主管部门处以所购烟草专卖品价值50%以上1倍以下的罚款。"},{"i":62,"n":"第六十二条","txt":"违反本条例第四十一条规定，免税进口的烟草制品不按规定存放在烟草制品保税仓库内的，可以处烟草制品价值50%以下的罚款。"},{"i":63,"n":"第六十三条","txt":"违反本条例第四十二条规定，在海关监管区内经营免税的卷烟、雪茄烟没有在小包、条包上标注国务院烟草专卖行政主管部门规定的专门标志的，可以处非法经营总额50%以下的罚款。"},{"i":64,"n":"第六十四条","txt":"违反本条例第四十八条的规定，拍卖企业未对竞买人进行资格验证，或者不接受烟草专卖行政主管部门的监督，擅自拍卖烟草专卖品的，由烟草专卖行政主管部门处以拍卖的烟草专卖品价值20%以上50%以下的罚款，并依法取消其拍卖烟草专卖品的资格。"},{"i":65,"n":"第六十五条","txt":"电子烟等新型烟草制品参照本条例卷烟的有关规定执行。"},{"i":66,"n":"第六十六条","txt":"本条例自发布之日起施行。"}],"huanjingbaohushuifashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国环境保护税法》（以下简称环境保护税法），制定本条例。"},{"i":2,"n":"第二条","txt":"环境保护税法所附《环境保护税税目税额表》所称其他固体废物的具体范围，依照环境保护税法第六条第二款规定的程序确定。"},{"i":3,"n":"第三条","txt":"环境保护税法第五条第一款、第十二条第一款第三项规定的城乡污水集中处理场所，是指为社会公众提供生活污水处理服务的场所，不包括为工业园区、开发区等工业聚集区域内的企业事业单位和其他生产经营者提供污水处理服务的场所，以及企业事业单位和其他生产经营者自建自用的污水处理场所。"},{"i":4,"n":"第四条","txt":"达到省级人民政府确定的规模标准并且有污染物排放口的畜禽养殖场，应当依法缴纳环境保护税；依法对畜禽养殖废弃物进行综合利用和无害化处理的，不属于直接向环境排放污染物，不缴纳环境保护税。"},{"i":5,"n":"第五条","txt":"应税固体废物的计税依据，按照固体废物的排放量确定。固体废物的排放量为当期应税固体废物的产生量减去当期应税固体废物的贮存量、处置量、综合利用量的余额。"},{"i":6,"n":"第六条","txt":"纳税人有下列情形之一的，以其当期应税固体废物的产生量作为固体废物的排放量："},{"i":7,"n":"第七条","txt":"应税大气污染物、水污染物的计税依据，按照污染物排放量折合的污染当量数确定。"},{"i":8,"n":"第八条","txt":"从两个以上排放口排放应税污染物的，对每一排放口排放的应税污染物分别计算征收环境保护税；纳税人持有排污许可证的，其污染物排放口按照排污许可证载明的污染物排放口确定。"},{"i":9,"n":"第九条","txt":"属于环境保护税法第十条第二项规定情形的纳税人，自行对污染物进行监测所获取的监测数据，符合国家有关规定和监测规范的，视同环境保护税法第十条第二项规定的监测机构出具的监测数据。"},{"i":10,"n":"第十条","txt":"环境保护税法第十三条所称应税大气污染物或者水污染物的浓度值，是指纳税人安装使用的污染物自动监测设备当月自动监测的应税大气污染物浓度值的小时平均值再平均所得数值或者应税水污染物浓度值的日平均值再平均所得数值，或者监测机构当月监测的应税大气污染物、水污染物浓度值的平均值。"},{"i":11,"n":"第十一条","txt":"依照环境保护税法第十三条的规定减征环境保护税的，应当对每一排放口排放的不同应税污染物分别计算。"},{"i":12,"n":"第十二条","txt":"税务机关依法履行环境保护税纳税申报受理、涉税信息比对、组织税款入库等职责。"},{"i":13,"n":"第十三条","txt":"县级以上地方人民政府应当加强对环境保护税征收管理工作的领导，及时协调、解决环境保护税征收管理工作中的重大问题。"},{"i":14,"n":"第十四条","txt":"国务院税务、环境保护主管部门制定涉税信息共享平台技术标准以及数据采集、存储、传输、查询和使用规范。"},{"i":15,"n":"第十五条","txt":"环境保护主管部门应当通过涉税信息共享平台向税务机关交送在环境保护监督管理中获取的下列信息："},{"i":16,"n":"第十六条","txt":"税务机关应当通过涉税信息共享平台向环境保护主管部门交送下列环境保护税涉税信息："},{"i":17,"n":"第十七条","txt":"环境保护税法第十七条所称应税污染物排放地是指："},{"i":18,"n":"第十八条","txt":"纳税人跨区域排放应税污染物，税务机关对税收征收管辖有争议的，由争议各方按照有利于征收管理的原则协商解决；不能协商一致的，报请共同的上级税务机关决定。"},{"i":19,"n":"第十九条","txt":"税务机关应当依据环境保护主管部门交送的排污单位信息进行纳税人识别。"},{"i":20,"n":"第二十条","txt":"环境保护主管部门发现纳税人申报的应税污染物排放信息或者适用的排污系数、物料衡算方法有误的，应当通知税务机关处理。"},{"i":21,"n":"第二十一条","txt":"纳税人申报的污染物排放数据与环境保护主管部门交送的相关数据不一致的，按照环境保护主管部门交送的数据确定应税污染物的计税依据。"},{"i":22,"n":"第二十二条","txt":"环境保护税法第二十条第二款所称纳税人的纳税申报数据资料异常，包括但不限于下列情形："},{"i":23,"n":"第二十三条","txt":"税务机关、环境保护主管部门应当无偿为纳税人提供与缴纳环境保护税有关的辅导、培训和咨询服务。"},{"i":24,"n":"第二十四条","txt":"税务机关依法实施环境保护税的税务检查，环境保护主管部门予以配合。"},{"i":25,"n":"第二十五条","txt":"纳税人应当按照税收征收管理的有关规定，妥善保管应税污染物监测和管理的有关资料。"},{"i":26,"n":"第二十六条","txt":"本条例自2018年1月1日起施行。2003年1月2日国务院公布的《排污费征收使用管理条例》同时废止。"}],"kuangchanziyuanfashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国矿产资源法》（以下简称矿产资源法），制定本条例。"},{"i":2,"n":"第二条","txt":"国家促进矿产资源合理开发利用，加强矿产资源和生态环境保护，推动矿业高质量发展，保障矿产资源安全。"},{"i":3,"n":"第三条","txt":"矿产资源目录的确定和调整，由国务院自然资源主管部门会同国务院发展改革部门提出，报国务院批准后公布。"},{"i":4,"n":"第四条","txt":"国家加大对基础性地质调查工作的投入力度，加强基础性地质调查队伍建设，鼓励社会力量依法有序参与基础性地质调查，提升基础性地质调查工作质效。"},{"i":5,"n":"第五条","txt":"国家完善财政、金融、土地、生态环境、产业、进出口等方面政策措施，健全战略性矿产资源探产供储销全链条统筹和衔接体系，加大对战略性矿产资源勘查、开采、加工、贸易、储备等的支持力度，推进战略性矿产资源产业优化升级，提升矿产资源安全保障水平。"},{"i":6,"n":"第六条","txt":"依照矿产资源法第九条规定编制并经批准的矿产资源相关规划应当依法公布。开展地质调查以及矿产资源勘查、开采、保护和矿区生态修复等活动，应当符合矿产资源相关规划。"},{"i":7,"n":"第七条","txt":"国家坚持平等互利、合作共赢的方针，通过多种途径和方式积极促进矿产资源领域国际投资、贸易、技术等合作，维护产业链供应链安全稳定。"},{"i":8,"n":"第八条","txt":"矿业权应当通过招标、拍卖、挂牌等竞争性方式出让；对紧缺程度高、资源储量规模中型以上的战略性矿产资源，或者对勘查开采技术、生态环境保护有特殊要求的勘查区块，优先通过招标方式出让探矿权。"},{"i":9,"n":"第九条","txt":"县级以上人民政府自然资源主管部门按照规定权限组织矿业权出让。"},{"i":10,"n":"第十条","txt":"县级以上人民政府自然资源主管部门应当根据矿产资源相关规划和矿产资源供需形势等，加强对矿业权出让工作的统筹安排，对符合出让条件的及时安排出让。"},{"i":11,"n":"第十一条","txt":"对向县级以上人民政府自然资源主管部门提供可设立探矿权的区块来源的单位和个人，按照国家有关规定给予适当奖励或者补偿；参与该区块探矿权竞争性出让的，同等条件下优先取得探矿权。"},{"i":12,"n":"第十二条","txt":"通过竞争性方式出让矿业权的，矿业权出让部门应当提前在其门户网站、公共资源交易平台等公告拟出让矿业权的基本情况、出让方式、竞争规则、保证金收取、风险提示、受让人的技术能力等条件及其权利义务等事项。公告期限不少于30个工作日。"},{"i":13,"n":"第十三条","txt":"出让矿业权的，矿业权出让部门应当与依法确定的受让人以书面形式签订矿业权出让合同。"},{"i":14,"n":"第十四条","txt":"矿业权受让人应当按照国家有关规定和出让合同约定按时足额缴纳矿业权出让收益、矿业权占用费等有关费用。矿业权有关费用征收的具体办法由国务院财政部门会同国务院自然资源主管部门、国务院税务主管部门制定，报国务院批准后执行。"},{"i":15,"n":"第十五条","txt":"探矿权的期限为5年，期限届满可以续期，续期最多不超过3次，每次期限为5年。对石油、天然气以及国务院自然资源主管部门确定的其他战略性矿产资源，经国务院自然资源主管部门同意，可以根据实际情况增加续期次数。"},{"i":16,"n":"第十六条","txt":"申请矿业权续期的，矿业权人应当在矿业权期限届满前6个月至3个月内向原矿业权出让部门提出申请。原矿业权出让部门应当在矿业权期限届满前作出是否准予续期的决定。"},{"i":17,"n":"第十七条","txt":"办理探矿权续期时，应当按照国务院自然资源主管部门规定的比例核减勘查区域面积。但是，已经探明矿产资源或者符合国务院自然资源主管部门规定情形的勘查区域，不计入核减面积计算基数。"},{"i":18,"n":"第十八条","txt":"探矿权人依照矿产资源法第二十五条规定申请将其探矿权转为采矿权的，应当在探矿权期限内向原矿业权出让部门提出申请，并提交矿产资源储量报告（以下简称储量报告）等材料。原矿业权出让部门应当与该探矿权人签订采矿权出让合同，设立采矿权，但有下列情形之一的除外："},{"i":19,"n":"第十九条","txt":"矿业权可以依法转让。但是，有下列情形之一的，矿业权不得转让："},{"i":20,"n":"第二十条","txt":"矿业权转让的，受让人应当具备该矿业权出让时要求的受让人的技术能力等条件。"},{"i":21,"n":"第二十一条","txt":"矿业权转让的，转让人、受让人应当以书面形式签订矿业权转让合同，明确双方的权利和义务。矿业权转让合同应当对矿区生态修复义务履行有关事项作出明确约定。"},{"i":22,"n":"第二十二条","txt":"矿业权设立、变更、转让、抵押和消灭的，应当依法办理登记。"},{"i":23,"n":"第二十三条","txt":"矿产资源法第二十八条第一项所称国家出资勘查矿产资源，是指由中央财政或者地方财政出资，为保障国家矿产资源安全而开展的矿产资源勘查。国家出资勘查矿产资源的，凭项目任务书开展地质勘查工作，无需取得探矿权。"},{"i":24,"n":"第二十四条","txt":"建设项目施工单位在批准的作业区域和建设工期内，因施工需要采挖只能用作普通建筑材料的砂、石、黏土，无需取得采矿权。采挖的砂、石、黏土的处置应当遵守所在地省、自治区、直辖市的有关规定，不得自行处置（建设项目施工自用除外）。"},{"i":25,"n":"第二十五条","txt":"国务院自然资源主管部门会同国务院有关部门建立健全基础性地质调查技术标准和规范体系。"},{"i":26,"n":"第二十六条","txt":"省级以上人民政府自然资源主管部门应当加强基础性地质调查成果发布管理，按照规定权限统一发布基础性地质调查成果信息；信息发布前应当依法进行保密审查，不得发布涉及国家秘密、工作秘密、商业秘密的成果数据。"},{"i":27,"n":"第二十七条","txt":"省级以上人民政府自然资源主管部门应当为建设单位提供建设项目占地范围内矿产资源分布和矿业权设置情况查询服务。"},{"i":28,"n":"第二十八条","txt":"矿业权人进行矿产资源勘查、开采作业前，应当分别编制勘查方案、开采方案，报原矿业权出让部门批准，取得勘查许可证、采矿许可证；未取得相应许可证的，不得进行勘查、开采作业。"},{"i":29,"n":"第二十九条","txt":"申请勘查许可证、采矿许可证的，应当向原矿业权出让部门提交申请书、矿业权证书，以及相应的勘查方案或者开采方案等材料。原矿业权出让部门应当自受理申请之日起15个工作日内作出是否批准的决定。予以批准的，核发勘查许可证、采矿许可证；不予批准的，书面通知申请人并说明理由。"},{"i":30,"n":"第三十条","txt":"矿业权人可以在办理矿业权登记时一并申请办理勘查许可证、采矿许可证。"},{"i":31,"n":"第三十一条","txt":"勘查许可证、采矿许可证具体管理办法由国务院自然资源主管部门制定。"},{"i":32,"n":"第三十二条","txt":"矿业权人应当按照经批准的勘查方案、开采方案进行勘查、开采作业。"},{"i":33,"n":"第三十三条","txt":"矿业权人进行矿产资源勘查、开采作业前，应当依法办理建设项目核准（备案）、用地用海、生态环境、安全生产等方面相关手续；涉及军用土地的，还应当经军队团级以上单位按照中央军事委员会的相关规定报经批准。"},{"i":34,"n":"第三十四条","txt":"自然保护地范围内可以依法开展符合管控要求的基础性地质调查、战略性矿产资源远景调查和规定范围内的战略性矿产资源勘查、开采等活动，具体管理办法由国务院自然资源主管部门、林业草原主管部门制定。"},{"i":35,"n":"第三十五条","txt":"矿产资源法第三十四条第一款所称矿业用地，包括矿产资源勘查用地和矿产资源开采用地。"},{"i":36,"n":"第三十六条","txt":"矿业权人可以依法通过划拨、出让、租赁、作价出资等方式使用国有土地，也可以依法通过出让、出租等方式取得集体经营性建设用地使用权。"},{"i":37,"n":"第三十七条","txt":"勘查矿产资源可以依照土地管理法律、行政法规的规定临时使用土地。"},{"i":38,"n":"第三十八条","txt":"石油、天然气等矿产资源勘查过程中发现可供开采的石油、天然气等矿产资源的，探矿权人完成试油（气）作业，向原矿业权出让部门提交探采合一计划后，可以进行开采，并按照规定向有关能源主管部门履行备案手续。"},{"i":39,"n":"第三十九条","txt":"国务院自然资源主管部门会同国务院有关部门完善绿色矿山政策、标准规范，健全绿色矿山名录并实行动态管理。矿业权人应当加强绿色矿山规划、建设、运营和管理，推动矿山企业绿色发展。"},{"i":40,"n":"第四十条","txt":"国务院自然资源主管部门会同国务院有关部门组织制定矿产资源开采回采率、选矿回收率、综合利用率有关国家标准。"},{"i":41,"n":"第四十一条","txt":"县级以上人民政府自然资源主管部门应当会同有关部门加强矿产资源综合开采、综合利用先进适用技术、工艺、设备的推广应用，鼓励、引导采矿权人开展技术、工艺升级和设备更新，推进矿产资源综合利用产业化发展。"},{"i":42,"n":"第四十二条","txt":"国家建立矿产资源储量管理制度，加强对矿产资源储量及其变动情况的调查、核实、统计、评估等，为编制矿产资源相关规划、促进矿产资源合理开发利用、加强矿产资源保护等提供依据。"},{"i":43,"n":"第四十三条","txt":"矿业权人经过勘查工作查明可供开采的矿产资源或者在开采期间发现矿产资源储量发生重大变化的，应当编制储量报告并报送原矿业权出让部门。储量报告应当包括矿产资源的空间分布、种类、数量、质量和矿床工业指标论证等内容，并对矿石加工选冶技术性能、开采技术条件、开发经济意义等情况作出说明。"},{"i":44,"n":"第四十四条","txt":"采矿权人应当按照规定开展矿产资源储量监测，建立健全矿产资源储量台账，定期向原矿业权出让部门报告矿产资源储量变化情况和开发利用情况。"},{"i":45,"n":"第四十五条","txt":"矿山闭坑的，采矿权人应当按照国家有关规定将闭坑地质报告报送县级以上地方人民政府自然资源主管部门，并汇交有关地质资料。"},{"i":46,"n":"第四十六条","txt":"县级以上地方人民政府自然资源主管部门应当会同有关部门对本行政区域内因开采矿产资源导致的地质环境破坏、土地损毁、植被退化等生态破坏情况进行调查评价，明确矿区生态修复的重点区域、目标任务。"},{"i":47,"n":"第四十七条","txt":"采矿权人是矿区生态修复的责任人。采矿权人应当协同实施矿区生态修复与污染防治。"},{"i":48,"n":"第四十八条","txt":"对历史遗留的废弃矿区，由所在地县级以上地方人民政府自然资源主管部门确认矿区生态修复责任人；责任人灭失或者无法确认的，由所在地县级以上地方人民政府组织开展矿区生态修复，并协同开展污染治理。"},{"i":49,"n":"第四十九条","txt":"国家完善政策措施，鼓励社会资本依法参与矿区生态修复，维护参与矿区生态修复的社会资本的合法权益。"},{"i":50,"n":"第五十条","txt":"开采矿产资源前，采矿权人应当依照法律、法规和国务院自然资源主管部门的规定以及矿业权出让合同编制矿区生态修复方案，随开采方案报原矿业权出让部门批准。矿区生态修复方案应当明确生态修复的目标任务、工程布局、技术措施、时序安排、经费概算、保障措施等内容；涉及尾矿库的，还应当明确尾矿库修复的专门措施。"},{"i":51,"n":"第五十一条","txt":"矿区生态修复能够边开采、边修复或者分区、分期修复的，采矿权人应当根据矿山开采设计和工艺流程、开采进度、采矿用地范围和类型、安全生产条件以及土地损毁和生态破坏等情况，合理划分修复单元、安排修复时序，及时开展生态修复；不能边开采、边修复或者分区、分期修复的，应当在矿山闭坑前或者闭坑后的2年内完成生态修复，但开采放射性矿产资源的矿区生态修复时限可以根据实际需要确定。"},{"i":52,"n":"第五十二条","txt":"采矿权人按照矿区生态修复方案完成生态修复后，应当及时向矿区所在地县级以上地方人民政府自然资源主管部门申请验收；分区、分期完成生态修复的，应当分区、分期申请验收。"},{"i":53,"n":"第五十三条","txt":"矿区生态修复费用由采矿权人按年度提取，除法律另有规定外，矿区生态修复费用不得被查封、冻结或者划拨。"},{"i":54,"n":"第五十四条","txt":"国家按照政府主导、社会共建、多元互补、高效协同的原则，构建产品储备、产能储备和产地储备相结合的战略性矿产资源储备体系，科学合理确定储备结构、规模和布局并动态调整，发挥储备的战略保障、宏观调控和应对急需等功能。"},{"i":55,"n":"第五十五条","txt":"国务院发展改革部门统筹协调国家矿产品储备工作，定期拟订储备规划和总量计划，动态调整储备品种规模；国务院粮食和物资储备部门组织实施中央政府矿产品储备的收储、轮换和日常管理；国务院能源主管部门按照职责负责能源储备相关工作。县级以上地方人民政府按照国家有关规定，结合本地实际开展矿产品储备。"},{"i":56,"n":"第五十六条","txt":"能源战略性矿产资源产能储备的具体办法，由国务院能源主管部门会同国务院有关部门制定；其他战略性矿产资源产能储备的具体办法由国务院工业和信息化主管部门会同国务院有关部门制定。"},{"i":57,"n":"第五十七条","txt":"战略性矿产资源产地储备应当遵循科学评估、合理布局、分级管理、动态调整的原则，结合国家矿产资源开发利用和安全保障等相关规划，统筹资源禀赋、开发利用技术条件、国内外供需状况、生态区位等因素，合理确定储备规模、布局等，并对储备地开展必要的补充勘查，提升应急开采能力，与产品储备、产能储备有机衔接，形成梯次供应能力。"},{"i":58,"n":"第五十八条","txt":"国务院发展改革、工业和信息化、自然资源、粮食和物资储备、矿山安全监察等有关部门应当建立健全矿产资源供应安全预测预警工作体系，加强矿产资源供应安全相关数据信息共享和应用，对矿产品供求变化、价格波动以及安全风险状况等开展综合监测、分析、评估，及时进行预测预警。"},{"i":59,"n":"第五十九条","txt":"矿产资源法第五十五条第一款第六项所称其他必要措施，包括但不限于直接组织矿产资源开采、加工、运输、供应，征用相关矿产品、矿产品储备设施、交通运输工具，按照供应保障顺序组织实施矿产资源或者矿产品供应。"},{"i":60,"n":"第六十条","txt":"县级以上人民政府自然资源主管部门和其他有关部门应当按照职责分工，加强对矿产资源勘查、开采和矿区生态修复等活动的监督检查，依法及时查处违法行为。"},{"i":61,"n":"第六十一条","txt":"自然资源主管部门和其他有关部门及其工作人员对监督管理过程中知悉的国家秘密、工作秘密、商业秘密、个人隐私和个人信息依法负有保密义务。"},{"i":62,"n":"第六十二条","txt":"国务院自然资源主管部门按照科学合理、体现差异、简便易行的原则，建立矿产资源开发利用水平评估指标体系，并加强对评估指标运用的指导。"},{"i":63,"n":"第六十三条","txt":"国务院自然资源主管部门推动提升矿产资源监督管理信息化水平，通过全国矿产资源监督管理信息系统开展监管和服务，并与国务院有关部门加强信息共享。"},{"i":64,"n":"第六十四条","txt":"国务院自然资源主管部门根据从事矿产资源勘查单位的规模、技术能力、人才装备、信用状况等，对其实行备案和分级分类监管，引导矿产资源勘查市场规模化发展，提升专业化水平。"},{"i":65,"n":"第六十五条","txt":"矿业权人之间对勘查、开采区域发生争议时，由当事人协商解决。当事人协商不成的，由矿产资源所在地县级以上地方人民政府根据依法核定的勘查、开采区域处理；跨行政区域的勘查、开采区域争议，由共同的上一级人民政府处理。"},{"i":66,"n":"第六十六条","txt":"国家自然资源督察机构根据国务院的授权，对省、自治区、直辖市人民政府矿产资源开发利用和监督管理情况进行督察。"},{"i":67,"n":"第六十七条","txt":"阻挠、妨碍依法开展的基础性地质调查工作的，由县级以上人民政府自然资源主管部门责令改正，给予警告或者通报批评；拒不改正的，对单位处2万元以上10万元以下的罚款，对个人处1万元以上5万元以下的罚款。"},{"i":68,"n":"第六十八条","txt":"矿业权人未定期报送矿产资源储量变化情况和开发利用情况，或者在矿山闭坑后未报送闭坑地质报告的，由县级以上人民政府自然资源主管部门责令改正，处2万元以上10万元以下的罚款；情节严重的，处10万元以上50万元以下的罚款。"},{"i":69,"n":"第六十九条","txt":"矿产资源法第六十三条、第六十四条、第六十六条、第六十七条、第六十八条规定的违法行为所涉矿产资源属于战略性矿产资源的，应当从重处罚。"},{"i":70,"n":"第七十条","txt":"矿业权人未按照规定缴纳矿业权占用费的，征收机关可以责令限期缴纳，逾期不缴纳的，可以处应缴矿业权占用费3倍以下的罚款。"},{"i":71,"n":"第七十一条","txt":"建设项目施工单位自行处置因施工需要采挖的砂、石、黏土的，由县级以上人民政府自然资源主管部门责令改正，处自行处置的矿产品市场价值3倍以上5倍以下的罚款；自行处置的矿产品市场价值不足10万元的，处10万元以上30万元以下的罚款。"},{"i":72,"n":"第七十二条","txt":"未经批准开采纳入产地储备的战略性矿产资源的，依照矿产资源法第六十四条的规定从重处罚。"},{"i":73,"n":"第七十三条","txt":"违反本条例规定，造成他人人身财产损害或者生态环境损害的，依法承担民事责任；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":74,"n":"第七十四条","txt":"外商投资勘查、开采矿产资源，应当符合外商投资准入负面清单的规定。"},{"i":75,"n":"第七十五条","txt":"矿产资源及相关货物、技术、服务的进出口，应当遵守有关对外贸易、进出口管理法律、行政法规的规定；属于出口管制物项的，还应当遵守出口管制法律、行政法规的规定。"},{"i":76,"n":"第七十六条","txt":"任何国家、地区和国际组织采取或者协助、支持采取歧视性的禁止、限制或者其他类似措施，危害中华人民共和国矿产资源及相关产业链供应链安全的，国务院有关部门可以根据实际情况采取必要的反制措施。"},{"i":77,"n":"第七十七条","txt":"国家对铀（钍）矿等放射性矿产资源的勘查、开采和保护等另有规定的，依照其规定。"},{"i":78,"n":"第七十八条","txt":"2025年7月1日前依法核发的勘查许可证、采矿许可证，在有效期内继续有效。"},{"i":79,"n":"第七十九条","txt":"本条例自2026年6月15日起施行。《矿产资源监督管理暂行办法》、《矿产资源补偿费征收管理规定》、《中华人民共和国矿产资源法实施细则》、《矿产资源勘查区块登记管理办法》、《矿产资源开采登记管理办法》、《探矿权采矿权转让管理办法》同时废止。"}],"kuangshananquanfashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国矿山安全法》（以下简称《矿山安全法》），制定本条例。"},{"i":2,"n":"第二条","txt":"《矿山安全法》及本条例中下列用语的含义："},{"i":3,"n":"第三条","txt":"国家采取政策和措施，支持发展矿山安全教育，鼓励矿山安全开采技术、安全管理方法、安全设备与仪器的研究和推广，促进矿山安全科学技术进步。"},{"i":4,"n":"第四条","txt":"各级人民政府、政府有关部门或者企业事业单位对有下列情形之一的单位和个人，按照国家有关规定给予奖励："},{"i":5,"n":"第五条","txt":"矿山设计使用的地质勘探报告书，应当包括下列技术资料："},{"i":6,"n":"第六条","txt":"编制矿山建设项目的可行性研究报告和总体设计，应当对矿山开采的安全条件进行论证。"},{"i":7,"n":"第七条","txt":"根据《矿山安全法》第八条的规定，矿山建设单位在向管理矿山企业的主管部门报送审批矿山建设工程安全设施设计文件时，应当同时报送劳动行政主管部门审查；没有劳动行政主管部门的审查意见，管理矿山企业的主管部门不得批准。"},{"i":8,"n":"第八条","txt":"矿山建设工程应当按照经批准的设计文件施工，保证施工质量；工程竣工后，应当按照国家有关规定申请验收。"},{"i":9,"n":"第九条","txt":"管理矿山企业的主管部门、劳动行政主管部门应当自收到建设单位报送的矿山建设工程安全设施施工、竣工情况的综合报告之日起30日内，对矿山建设工程的安全设施进行检查；不符合矿山安全规程、行业技术规范的，不得验收，不得投入生产或者使用。"},{"i":10,"n":"第十条","txt":"矿山应当有保障安全生产、预防事故和职业危害的安全设施，并符合下列基本要求："},{"i":11,"n":"第十一条","txt":"采掘作业应当编制作业规程，规定保证作业人员安全的技术措施和组织措施，并在情况变化时及时予以修改和补充。"},{"i":12,"n":"第十二条","txt":"矿山开采应当有下列图纸资料："},{"i":13,"n":"第十三条","txt":"矿山企业应当在采矿许可证批准的范围开采，禁止越层、越界开采。"},{"i":14,"n":"第十四条","txt":"矿山使用的下列设备、器材、防护用品和安全检测仪器，应当符合国家安全标准或者行业安全标准；不符合国家安全标准或者行业安全标准的，不得使用："},{"i":15,"n":"第十五条","txt":"矿山企业应当对机电设备及其防护装置、安全检测仪器定期检查、维修，并建立技术档案，保证使用安全。"},{"i":16,"n":"第十六条","txt":"矿山作业场所空气中的有毒有害物质的浓度，不得超过国家标准或者行业标准；矿山企业应当按照国家规定的方法，按照下列要求定期检测："},{"i":17,"n":"第十七条","txt":"井下采掘作业，必须按照作业规程的规定管理顶帮。采掘作业通过地质破碎带或者其他顶帮破碎地点时，应当加强支护。"},{"i":18,"n":"第十八条","txt":"煤矿和其他有瓦斯爆炸可能性的矿井，应当严格执行瓦斯检查制度，任何人不得携带烟草和点火用具下井。"},{"i":19,"n":"第十九条","txt":"在下列条件下从事矿山开采，应当编制专门设计文件，并报管理矿山企业的主管部门批准："},{"i":20,"n":"第二十条","txt":"有自然发火可能性的矿井，应当采取下列措施："},{"i":21,"n":"第二十一条","txt":"井下采掘作业遇下列情形之一时，应当探水前进："},{"i":22,"n":"第二十二条","txt":"井下风量、风质、风速和作业环境的气候，必须符合矿山安全规程的规定。"},{"i":23,"n":"第二十三条","txt":"开采放射性矿物的矿井，必须采取下列措施，减少氡气析出量："},{"i":24,"n":"第二十四条","txt":"矿山的爆破作业和爆破材料的制造、储存、运输、试验及销毁，必须严格执行国家有关规定。"},{"i":25,"n":"第二十五条","txt":"矿山企业对地面、井下产生粉尘的作业，应当采取综合防尘措施，控制粉尘危害。"},{"i":26,"n":"第二十六条","txt":"矿山企业应当建立、健全对地面陷落区、排土场、矸石山、尾矿库的检查和维护制度；对可能发生的危害，应当采取预防措施。"},{"i":27,"n":"第二十七条","txt":"矿山企业应当按照国家有关规定关闭矿山，对关闭矿山后可能引起的危害采取预防措施。关闭矿山报告应当包括下列内容："},{"i":28,"n":"第二十八条","txt":"矿山企业应当建立、健全下列安全生产责任制："},{"i":29,"n":"第二十九条","txt":"矿长（含矿务局局长、矿山公司经理，下同）对本企业的安全生产工作负有下列责任："},{"i":30,"n":"第三十条","txt":"矿山企业应当根据需要，设置安全机构或者配备专职安全工作人员。专职安全工作人员应当经过培训，具备必要的安全专业知识和矿山安全工作经验，能胜任现场安全检查工作。"},{"i":31,"n":"第三十一条","txt":"矿长应当定期向职工代表大会或者职工大会报告下列事项，接受民主监督："},{"i":32,"n":"第三十二条","txt":"矿山企业职工享有下列权利："},{"i":33,"n":"第三十三条","txt":"矿山企业职工应当履行下列义务："},{"i":34,"n":"第三十四条","txt":"矿山企业工会有权督促企业行政方面加强职工的安全教育、培训工作，开展安全宣传活动，提高职工的安全生产意识和技术素质。"},{"i":35,"n":"第三十五条","txt":"矿山企业应当按照下列规定对职工进行安全教育、培训："},{"i":36,"n":"第三十六条","txt":"矿山企业对职工的安全教育、培训，应当包括下列内容："},{"i":37,"n":"第三十七条","txt":"瓦斯检查工、爆破工、通风工、信号工、拥罐工、电工、金属焊接（切割）工、矿井泵工、瓦斯抽放工、主扇风机操作工、主提升机操作工、绞车操作工、输送机操作工、尾矿工、安全检查工和矿内机动车司机等特种作业人员应当接受专门技术培训，经考核合格取得操作资格证书后，方可上岗作业。特种作业人员的考核、发证工作按照国家有关规定执行。"},{"i":38,"n":"第三十八条","txt":"对矿长安全资格的考核，应当包括下列内容："},{"i":39,"n":"第三十九条","txt":"矿山企业向职工发放的劳动防护用品应当是经过鉴定和检验合格的产品。劳动防护用品的发放标准由国务院劳动行政主管部门制定。"},{"i":40,"n":"第四十条","txt":"矿山企业应当每年编制矿山灾害预防和应急计划；在每季度末，应当根据实际情况对计划及时进行修改，制定相应的措施。"},{"i":41,"n":"第四十一条","txt":"矿山企业应当建立由专职的或者兼职的人员组成的矿山救护和医疗急救组织。不具备单独建立专业救护和医疗急救组织的小型矿山企业，除应当建立兼职的救护和医疗急救组织外，还应当与邻近的有专业的救护和医疗急救组织的矿山企业签订救护和急救协议，或者与邻近的矿山企业联合建立专业救护和医疗急救组织。"},{"i":42,"n":"第四十二条","txt":"矿山企业必须按照国家规定的安全条件进行生产，并安排一部分资金，用于下列改善矿山安全生产条件的项目："},{"i":43,"n":"第四十三条","txt":"县级以上各级人民政府劳动行政主管部门，应当根据矿山安全监督工作的实际需要，配备矿山安全监督人员。"},{"i":44,"n":"第四十四条","txt":"矿山安全监督人员在执行职务时，有权进入现场检查，参加有关会议，无偿调阅有关资料，向有关单位和人员了解情况。"},{"i":45,"n":"第四十五条","txt":"矿山安全监督人员执行公务时，应当出示矿山安全监督证件，秉公执法，并遵守有关规定。"},{"i":46,"n":"第四十六条","txt":"矿山发生事故后，事故现场有关人员应当立即报告矿长或者有关主管人员；矿长或者有关主管人员接到事故报告后，必须立即采取有效措施，组织抢救，防止事故扩大，尽力减少人员伤亡和财产损失。"},{"i":47,"n":"第四十七条","txt":"矿山发生重伤、死亡事故后，矿山企业应当在24小时内如实向劳动行政主管部门和管理矿山企业的主管部门报告。"},{"i":48,"n":"第四十八条","txt":"劳动行政主管部门和管理矿山企业的主管部门接到死亡事故或者一次重伤3人以上的事故报告后，应当立即报告本级人民政府，并报各自的上一级主管部门。"},{"i":49,"n":"第四十九条","txt":"发生伤亡事故，矿山企业和有关单位应当保护事故现场；因抢救事故，需要移动现场部分物品时，必须作出标志，绘制事故现场图，并详细记录；在消除现场危险，采取防范措施后，方可恢复生产。"},{"i":50,"n":"第五十条","txt":"矿山事故发生后，有关部门应当按照国家有关规定，进行事故调查处理。"},{"i":51,"n":"第五十一条","txt":"矿山事故调查处理工作应当自事故发生之日起90日内结束；遇有特殊情况，可以适当延长，但是不得超过180日。矿山事故处理结案后，应当公布处理结果。"},{"i":52,"n":"第五十二条","txt":"依照《矿山安全法》第四十条规定处以罚款的，分别按照下列规定执行："},{"i":53,"n":"第五十三条","txt":"依照《矿山安全法》第四十三条规定处以罚款的，罚款幅度为5万元以上10万元以下。"},{"i":54,"n":"第五十四条","txt":"违反本条例第十五条、第十六条、第十七条、第十八条、第十九条、第二十条、第二十一条、第二十二条、第二十三条、第二十五条规定的，由劳动行政主管部门责令改正，可以处2万元以下的罚款。"},{"i":55,"n":"第五十五条","txt":"当事人收到罚款通知书后，应当在15日内到指定的金融机构缴纳罚款；逾期不缴纳的，自逾期之日起每日加收3‰的滞纳金。"},{"i":56,"n":"第五十六条","txt":"矿山企业主管人员有下列行为之一，造成矿山事故的，按照规定给予纪律处分；构成犯罪的，由司法机关依法追究刑事责任："},{"i":57,"n":"第五十七条","txt":"国务院管理矿山企业的主管部门根据《矿山安全法》和本条例修订或者制定的矿山安全规程和行业技术规范，报国务院劳动行政主管部门备案。"},{"i":58,"n":"第五十八条","txt":"石油天然气开采的安全规定，由国务院劳动行政主管部门会同石油工业主管部门制定，报国务院批准后施行。"},{"i":59,"n":"第五十九条","txt":"本条例自发布之日起施行。"}],"shuishouzhengshouguanlifashishixize":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国税收征收管理法》（以下简称税收征管法）的规定，制定本细则。"},{"i":2,"n":"第二条","txt":"凡依法由税务机关征收的各种税收的征收管理，均适用税收征管法及本细则；税收征管法及本细则没有规定的，依照其他有关税收法律、行政法规的规定执行。"},{"i":3,"n":"第三条","txt":"任何部门、单位和个人作出的与税收法律、行政法规相抵触的决定一律无效，税务机关不得执行，并应当向上级税务机关报告。"},{"i":4,"n":"第四条","txt":"国家税务总局负责制定全国税务系统信息化建设的总体规划、技术标准、技术方案与实施办法；各级税务机关应当按照国家税务总局的总体规划、技术标准、技术方案与实施办法，做好本地区税务系统信息化建设的具体工作。"},{"i":5,"n":"第五条","txt":"税收征管法第八条所称为纳税人、扣缴义务人保密的情况，是指纳税人、扣缴义务人的商业秘密及个人隐私。纳税人、扣缴义务人的税收违法行为不属于保密范围。"},{"i":6,"n":"第六条","txt":"国家税务总局应当制定税务人员行为准则和服务规范。"},{"i":7,"n":"第七条","txt":"税务机关根据检举人的贡献大小给予相应的奖励，奖励所需资金列入税务部门年度预算，单项核定。奖励资金具体使用办法以及奖励标准，由国家税务总局会同财政部制定。"},{"i":8,"n":"第八条","txt":"税务人员在核定应纳税额、调整税收定额、进行税务检查、实施税务行政处罚、办理税务行政复议时，与纳税人、扣缴义务人或者其法定代表人、直接责任人有下列关系之一的，应当回避："},{"i":9,"n":"第九条","txt":"税收征管法第十四条所称按照国务院规定设立的并向社会公告的税务机构，是指省以下税务局的稽查局。稽查局专司偷税、逃避追缴欠税、骗税、抗税案件的查处。"},{"i":10,"n":"第十条","txt":"国家税务局、地方税务局对同一纳税人的税务登记应当采用同一代码，信息共享。"},{"i":11,"n":"第十一条","txt":"各级工商行政管理机关应当向同级国家税务局和地方税务局定期通报办理开业、变更、注销登记以及吊销营业执照的情况。"},{"i":12,"n":"第十二条","txt":"从事生产、经营的纳税人应当自领取营业执照之日起30日内，向生产、经营地或者纳税义务发生地的主管税务机关申报办理税务登记，如实填写税务登记表，并按照税务机关的要求提供有关证件、资料。"},{"i":13,"n":"第十三条","txt":"扣缴义务人应当自扣缴义务发生之日起30日内，向所在地的主管税务机关申报办理扣缴税款登记，领取扣缴税款登记证件；税务机关对已办理税务登记的扣缴义务人，可以只在其税务登记证件上登记扣缴税款事项，不再发给扣缴税款登记证件。"},{"i":14,"n":"第十四条","txt":"纳税人税务登记内容发生变化的，应当自工商行政管理机关或者其他机关办理变更登记之日起30日内，持有关证件向原税务登记机关申报办理变更税务登记。"},{"i":15,"n":"第十五条","txt":"纳税人发生解散、破产、撤销以及其他情形，依法终止纳税义务的，应当在向工商行政管理机关或者其他机关办理注销登记前，持有关证件向原税务登记机关申报办理注销税务登记；按照规定不需要在工商行政管理机关或者其他机关办理注册登记的，应当自有关机关批准或者宣告终止之日起15日内，持有关证件向原税务登记机关申报办理注销税务登记。"},{"i":16,"n":"第十六条","txt":"纳税人在办理注销税务登记前，应当向税务机关结清应纳税款、滞纳金、罚款，缴销发票、税务登记证件和其他税务证件。"},{"i":17,"n":"第十七条","txt":"从事生产、经营的纳税人应当自开立基本存款账户或者其他存款账户之日起15日内，向主管税务机关书面报告其全部账号；发生变化的，应当自变化之日起15日内，向主管税务机关书面报告。"},{"i":18,"n":"第十八条","txt":"除按照规定不需要发给税务登记证件的外，纳税人办理下列事项时，必须持税务登记证件："},{"i":19,"n":"第十九条","txt":"税务机关对税务登记证件实行定期验证和换证制度。纳税人应当在规定的期限内持有关证件到主管税务机关办理验证或者换证手续。"},{"i":20,"n":"第二十条","txt":"纳税人应当将税务登记证件正本在其生产、经营场所或者办公场所公开悬挂，接受税务机关检查。"},{"i":21,"n":"第二十一条","txt":"从事生产、经营的纳税人到外县（市）临时从事生产、经营活动的，应当持税务登记证副本和所在地税务机关填开的外出经营活动税收管理证明，向营业地税务机关报验登记，接受税务管理。"},{"i":22,"n":"第二十二条","txt":"从事生产、经营的纳税人应当自领取营业执照或者发生纳税义务之日起15日内，按照国家有关规定设置账簿。"},{"i":23,"n":"第二十三条","txt":"生产、经营规模小又确无建账能力的纳税人，可以聘请经批准从事会计代理记账业务的专业机构或者财会人员代为建账和办理账务。"},{"i":24,"n":"第二十四条","txt":"从事生产、经营的纳税人应当自领取税务登记证件之日起15日内，将其财务、会计制度或者财务、会计处理办法报送主管税务机关备案。"},{"i":25,"n":"第二十五条","txt":"扣缴义务人应当自税收法律、行政法规规定的扣缴义务发生之日起10日内，按照所代扣、代收的税种，分别设置代扣代缴、代收代缴税款账簿。"},{"i":26,"n":"第二十六条","txt":"纳税人、扣缴义务人会计制度健全，能够通过计算机正确、完整计算其收入和所得或者代扣代缴、代收代缴税款情况的，其计算机输出的完整的书面会计记录，可视同会计账簿。"},{"i":27,"n":"第二十七条","txt":"账簿、会计凭证和报表，应当使用中文。民族自治地方可以同时使用当地通用的一种民族文字。外商投资企业和外国企业可以同时使用一种外国文字。"},{"i":28,"n":"第二十八条","txt":"纳税人应当按照税务机关的要求安装、使用税控装置，并按照税务机关的规定报送有关数据和资料。"},{"i":29,"n":"第二十九条","txt":"账簿、记账凭证、报表、完税凭证、发票、出口凭证以及其他有关涉税资料应当合法、真实、完整。"},{"i":30,"n":"第三十条","txt":"税务机关应当建立、健全纳税人自行申报纳税制度。纳税人、扣缴义务人可以采取邮寄、数据电文方式办理纳税申报或者报送代扣代缴、代收代缴税款报告表。"},{"i":31,"n":"第三十一条","txt":"纳税人采取邮寄方式办理纳税申报的，应当使用统一的纳税申报专用信封，并以邮政部门收据作为申报凭据。邮寄申报以寄出的邮戳日期为实际申报日期。"},{"i":32,"n":"第三十二条","txt":"纳税人在纳税期内没有应纳税款的，也应当按照规定办理纳税申报。"},{"i":33,"n":"第三十三条","txt":"纳税人、扣缴义务人的纳税申报或者代扣代缴、代收代缴税款报告表的主要内容包括：税种、税目，应纳税项目或者应代扣代缴、代收代缴税款项目，计税依据，扣除项目及标准，适用税率或者单位税额，应退税项目及税额、应减免税项目及税额，应纳税额或者应代扣代缴、代收代缴税额，税款所属期限、延期缴纳税款、欠税、滞纳金等。"},{"i":34,"n":"第三十四条","txt":"纳税人办理纳税申报时，应当如实填写纳税申报表，并根据不同的情况相应报送下列有关证件、资料："},{"i":35,"n":"第三十五条","txt":"扣缴义务人办理代扣代缴、代收代缴税款报告时，应当如实填写代扣代缴、代收代缴税款报告表，并报送代扣代缴、代收代缴税款的合法凭证以及税务机关规定的其他有关证件、资料。"},{"i":36,"n":"第三十六条","txt":"实行定期定额缴纳税款的纳税人，可以实行简易申报、简并征期等申报纳税方式。"},{"i":37,"n":"第三十七条","txt":"纳税人、扣缴义务人按照规定的期限办理纳税申报或者报送代扣代缴、代收代缴税款报告表确有困难，需要延期的，应当在规定的期限内向税务机关提出书面延期申请，经税务机关核准，在核准的期限内办理。"},{"i":38,"n":"第三十八条","txt":"税务机关应当加强对税款征收的管理，建立、健全责任制度。"},{"i":39,"n":"第三十九条","txt":"税务机关应当将各种税收的税款、滞纳金、罚款，按照国家规定的预算科目和预算级次及时缴入国库，税务机关不得占压、挪用、截留，不得缴入国库以外或者国家规定的税款账户以外的任何账户。"},{"i":40,"n":"第四十条","txt":"税务机关应当根据方便、快捷、安全的原则，积极推广使用支票、银行卡、电子结算方式缴纳税款。"},{"i":41,"n":"第四十一条","txt":"纳税人有下列情形之一的，属于税收征管法第三十一条所称特殊困难："},{"i":42,"n":"第四十二条","txt":"纳税人需要延期缴纳税款的，应当在缴纳税款期限届满前提出申请，并报送下列材料：申请延期缴纳税款报告，当期货币资金余额情况及所有银行存款账户的对账单，资产负债表，应付职工工资和社会保险费等税务机关要求提供的支出预算。"},{"i":43,"n":"第四十三条","txt":"享受减税、免税优惠的纳税人，减税、免税期满，应当自期满次日起恢复纳税；减税、免税条件发生变化的，应当在纳税申报时向税务机关报告；不再符合减税、免税条件的，应当依法履行纳税义务；未依法纳税的，税务机关应当予以追缴。"},{"i":44,"n":"第四十四条","txt":"税务机关根据有利于税收控管和方便纳税的原则，可以按照国家有关规定委托有关单位和人员代征零星分散和异地缴纳的税收，并发给委托代征证书。受托单位和人员按照代征证书的要求，以税务机关的名义依法征收税款，纳税人不得拒绝；纳税人拒绝的，受托代征单位和人员应当及时报告税务机关。"},{"i":45,"n":"第四十五条","txt":"税收征管法第三十四条所称完税凭证，是指各种完税证、缴款书、印花税票、扣（收）税凭证以及其他完税证明。"},{"i":46,"n":"第四十六条","txt":"税务机关收到税款后，应当向纳税人开具完税凭证。纳税人通过银行缴纳税款的，税务机关可以委托银行开具完税凭证。"},{"i":47,"n":"第四十七条","txt":"纳税人有税收征管法第三十五条或者第三十七条所列情形之一的，税务机关有权采用下列任何一种方法核定其应纳税额："},{"i":48,"n":"第四十八条","txt":"税务机关负责纳税人纳税信誉等级评定工作。纳税人纳税信誉等级的评定办法由国家税务总局制定。"},{"i":49,"n":"第四十九条","txt":"承包人或者承租人有独立的生产经营权，在财务上独立核算，并定期向发包人或者出租人上缴承包费或者租金的，承包人或者承租人应当就其生产、经营收入和所得纳税，并接受税务管理；但是，法律、行政法规另有规定的除外。"},{"i":50,"n":"第五十条","txt":"纳税人有解散、撤销、破产情形的，在清算前应当向其主管税务机关报告；未结清税款的，由其主管税务机关参加清算。"},{"i":51,"n":"第五十一条","txt":"税收征管法第三十六条所称关联企业，是指有下列关系之一的公司、企业和其他经济组织："},{"i":52,"n":"第五十二条","txt":"税收征管法第三十六条所称独立企业之间的业务往来，是指没有关联关系的企业之间按照公平成交价格和营业常规所进行的业务往来。"},{"i":53,"n":"第五十三条","txt":"纳税人可以向主管税务机关提出与其关联企业之间业务往来的定价原则和计算方法，主管税务机关审核、批准后，与纳税人预先约定有关定价事项，监督纳税人执行。"},{"i":54,"n":"第五十四条","txt":"纳税人与其关联企业之间的业务往来有下列情形之一的，税务机关可以调整其应纳税额："},{"i":55,"n":"第五十五条","txt":"纳税人有本细则第五十四条所列情形之一的，税务机关可以按照下列方法调整计税收入额或者所得额："},{"i":56,"n":"第五十六条","txt":"纳税人与其关联企业未按照独立企业之间的业务往来支付价款、费用的，税务机关自该业务往来发生的纳税年度起3年内进行调整；有特殊情况的，可以自该业务往来发生的纳税年度起10年内进行调整。"},{"i":57,"n":"第五十七条","txt":"税收征管法第三十七条所称未按照规定办理税务登记从事生产、经营的纳税人，包括到外县（市）从事生产、经营而未向营业地税务机关报验登记的纳税人。"},{"i":58,"n":"第五十八条","txt":"税务机关依照税收征管法第三十七条的规定，扣押纳税人商品、货物的，纳税人应当自扣押之日起15日内缴纳税款。"},{"i":59,"n":"第五十九条","txt":"税收征管法第三十八条、第四十条所称其他财产，包括纳税人的房地产、现金、有价证券等不动产和动产。"},{"i":60,"n":"第六十条","txt":"税收征管法第三十八条、第四十条、第四十二条所称个人所扶养家属，是指与纳税人共同居住生活的配偶、直系亲属以及无生活来源并由纳税人扶养的其他亲属。"},{"i":61,"n":"第六十一条","txt":"税收征管法第三十八条、第八十八条所称担保，包括经税务机关认可的纳税保证人为纳税人提供的纳税保证，以及纳税人或者第三人以其未设置或者未全部设置担保物权的财产提供的担保。"},{"i":62,"n":"第六十二条","txt":"纳税担保人同意为纳税人提供纳税担保的，应当填写纳税担保书，写明担保对象、担保范围、担保期限和担保责任以及其他有关事项。担保书须经纳税人、纳税担保人签字盖章并经税务机关同意，方为有效。"},{"i":63,"n":"第六十三条","txt":"税务机关执行扣押、查封商品、货物或者其他财产时，应当由两名以上税务人员执行，并通知被执行人。被执行人是自然人的，应当通知被执行人本人或者其成年家属到场；被执行人是法人或者其他组织的，应当通知其法定代表人或者主要负责人到场；拒不到场的，不影响执行。"},{"i":64,"n":"第六十四条","txt":"税务机关执行税收征管法第三十七条、第三十八条、第四十条的规定，扣押、查封价值相当于应纳税款的商品、货物或者其他财产时，参照同类商品的市场价、出厂价或者评估价估算。"},{"i":65,"n":"第六十五条","txt":"对价值超过应纳税额且不可分割的商品、货物或者其他财产，税务机关在纳税人、扣缴义务人或者纳税担保人无其他可供强制执行的财产的情况下，可以整体扣押、查封、拍卖。"},{"i":66,"n":"第六十六条","txt":"税务机关执行税收征管法第三十七条、第三十八条、第四十条的规定，实施扣押、查封时，对有产权证件的动产或者不动产，税务机关可以责令当事人将产权证件交税务机关保管，同时可以向有关机关发出协助执行通知书，有关机关在扣押、查封期间不再办理该动产或者不动产的过户手续。"},{"i":67,"n":"第六十七条","txt":"对查封的商品、货物或者其他财产，税务机关可以指令被执行人负责保管，保管责任由被执行人承担。"},{"i":68,"n":"第六十八条","txt":"纳税人在税务机关采取税收保全措施后，按照税务机关规定的期限缴纳税款的，税务机关应当自收到税款或者银行转回的完税凭证之日起1日内解除税收保全。"},{"i":69,"n":"第六十九条","txt":"税务机关将扣押、查封的商品、货物或者其他财产变价抵缴税款时，应当交由依法成立的拍卖机构拍卖；无法委托拍卖或者不适于拍卖的，可以交由当地商业企业代为销售，也可以责令纳税人限期处理；无法委托商业企业销售，纳税人也无法处理的，可以由税务机关变价处理，具体办法由国家税务总局规定。国家禁止自由买卖的商品，应当交由有关单位按照国家规定的价格收购。"},{"i":70,"n":"第七十条","txt":"税收征管法第三十九条、第四十三条所称损失，是指因税务机关的责任，使纳税人、扣缴义务人或者纳税担保人的合法利益遭受的直接损失。"},{"i":71,"n":"第七十一条","txt":"税收征管法所称其他金融机构，是指信托投资公司、信用合作社、邮政储蓄机构以及经中国人民银行、中国证券监督管理委员会等批准设立的其他金融机构。"},{"i":72,"n":"第七十二条","txt":"税收征管法所称存款，包括独资企业投资人、合伙企业合伙人、个体工商户的储蓄存款以及股东资金账户中的资金等。"},{"i":73,"n":"第七十三条","txt":"从事生产、经营的纳税人、扣缴义务人未按照规定的期限缴纳或者解缴税款的，纳税担保人未按照规定的期限缴纳所担保的税款的，由税务机关发出限期缴纳税款通知书，责令缴纳或者解缴税款的最长期限不得超过15日。"},{"i":74,"n":"第七十四条","txt":"欠缴税款的纳税人或者其法定代表人在出境前未按照规定结清应纳税款、滞纳金或者提供纳税担保的，税务机关可以通知出入境管理机关阻止其出境。阻止出境的具体办法，由国家税务总局会同公安部制定。"},{"i":75,"n":"第七十五条","txt":"税收征管法第三十二条规定的加收滞纳金的起止时间，为法律、行政法规规定或者税务机关依照法律、行政法规的规定确定的税款缴纳期限届满次日起至纳税人、扣缴义务人实际缴纳或者解缴税款之日止。"},{"i":76,"n":"第七十六条","txt":"县级以上各级税务机关应当将纳税人的欠税情况，在办税场所或者广播、电视、报纸、期刊、网络等新闻媒体上定期公告。"},{"i":77,"n":"第七十七条","txt":"税收征管法第四十九条所称欠缴税款数额较大，是指欠缴税款5万元以上。"},{"i":78,"n":"第七十八条","txt":"税务机关发现纳税人多缴税款的，应当自发现之日起10日内办理退还手续；纳税人发现多缴税款，要求退还的，税务机关应当自接到纳税人退还申请之日起30日内查实并办理退还手续。"},{"i":79,"n":"第七十九条","txt":"当纳税人既有应退税款又有欠缴税款的，税务机关可以将应退税款和利息先抵扣欠缴税款；抵扣后有余额的，退还纳税人。"},{"i":80,"n":"第八十条","txt":"税收征管法第五十二条所称税务机关的责任，是指税务机关适用税收法律、行政法规不当或者执法行为违法。"},{"i":81,"n":"第八十一条","txt":"税收征管法第五十二条所称纳税人、扣缴义务人计算错误等失误，是指非主观故意的计算公式运用错误以及明显的笔误。"},{"i":82,"n":"第八十二条","txt":"税收征管法第五十二条所称特殊情况，是指纳税人或者扣缴义务人因计算错误等失误，未缴或者少缴、未扣或者少扣、未收或者少收税款，累计数额在10万元以上的。"},{"i":83,"n":"第八十三条","txt":"税收征管法第五十二条规定的补缴和追征税款、滞纳金的期限，自纳税人、扣缴义务人应缴未缴或者少缴税款之日起计算。"},{"i":84,"n":"第八十四条","txt":"审计机关、财政机关依法进行审计、检查时，对税务机关的税收违法行为作出的决定，税务机关应当执行；发现被审计、检查单位有税收违法行为的，向被审计、检查单位下达决定、意见书，责成被审计、检查单位向税务机关缴纳应当缴纳的税款、滞纳金。税务机关应当根据有关机关的决定、意见书，依照税收法律、行政法规的规定，将应收的税款、滞纳金按照国家规定的税收征收管理范围和税款入库预算级次缴入国库。"},{"i":85,"n":"第八十五条","txt":"税务机关应当建立科学的检查制度，统筹安排检查工作，严格控制对纳税人、扣缴义务人的检查次数。"},{"i":86,"n":"第八十六条","txt":"税务机关行使税收征管法第五十四条第（一）项职权时，可以在纳税人、扣缴义务人的业务场所进行；必要时，经县以上税务局（分局）局长批准，可以将纳税人、扣缴义务人以前会计年度的账簿、记账凭证、报表和其他有关资料调回税务机关检查，但是税务机关必须向纳税人、扣缴义务人开付清单，并在3个月内完整退还；有特殊情况的，经设区的市、自治州以上税务局局长批准，税务机关可以将纳税人、扣缴义务人当年的账簿、记账凭证、报表和其他有关资料调回检查，但是税务机关必须在30日内退还。"},{"i":87,"n":"第八十七条","txt":"税务机关行使税收征管法第五十四条第（六）项职权时，应当指定专人负责，凭全国统一格式的检查存款账户许可证明进行，并有责任为被检查人保守秘密。"},{"i":88,"n":"第八十八条","txt":"依照税收征管法第五十五条规定，税务机关采取税收保全措施的期限一般不得超过6个月；重大案件需要延长的，应当报国家税务总局批准。"},{"i":89,"n":"第八十九条","txt":"税务机关和税务人员应当依照税收征管法及本细则的规定行使税务检查职权。"},{"i":90,"n":"第九十条","txt":"纳税人未按照规定办理税务登记证件验证或者换证手续的，由税务机关责令限期改正，可以处2000元以下的罚款；情节严重的，处2000元以上1万元以下的罚款。"},{"i":91,"n":"第九十一条","txt":"非法印制、转借、倒卖、变造或者伪造完税凭证的，由税务机关责令改正，处2000元以上1万元以下的罚款；情节严重的，处1万元以上5万元以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":92,"n":"第九十二条","txt":"银行和其他金融机构未依照税收征管法的规定在从事生产、经营的纳税人的账户中登录税务登记证件号码，或者未按规定在税务登记证件中登录从事生产、经营的纳税人的账户账号的，由税务机关责令其限期改正，处2000元以上2万元以下的罚款；情节严重的，处2万元以上5万元以下的罚款。"},{"i":93,"n":"第九十三条","txt":"为纳税人、扣缴义务人非法提供银行账户、发票、证明或者其他方便，导致未缴、少缴税款或者骗取国家出口退税款的，税务机关除没收其违法所得外，可以处未缴、少缴或者骗取的税款1倍以下的罚款。"},{"i":94,"n":"第九十四条","txt":"纳税人拒绝代扣、代收税款的，扣缴义务人应当向税务机关报告，由税务机关直接向纳税人追缴税款、滞纳金；纳税人拒不缴纳的，依照税收征管法第六十八条的规定执行。"},{"i":95,"n":"第九十五条","txt":"税务机关依照税收征管法第五十四条第（五）项的规定，到车站、码头、机场、邮政企业及其分支机构检查纳税人有关情况时，有关单位拒绝的，由税务机关责令改正，可以处1万元以下的罚款；情节严重的，处1万元以上5万元以下的罚款。"},{"i":96,"n":"第九十六条","txt":"纳税人、扣缴义务人有下列情形之一的，依照税收征管法第七十条的规定处罚："},{"i":97,"n":"第九十七条","txt":"税务人员私分扣押、查封的商品、货物或者其他财产，情节严重，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":98,"n":"第九十八条","txt":"税务代理人违反税收法律、行政法规，造成纳税人未缴或者少缴税款的，除由纳税人缴纳或者补缴应纳税款、滞纳金外，对税务代理人处纳税人未缴或者少缴税款50%以上3倍以下的罚款。"},{"i":99,"n":"第九十九条","txt":"税务机关对纳税人、扣缴义务人及其他当事人处以罚款或者没收违法所得时，应当开付罚没凭证；未开付罚没凭证的，纳税人、扣缴义务人以及其他当事人有权拒绝给付。"},{"i":100,"n":"第一百条","txt":"税收征管法第八十八条规定的纳税争议，是指纳税人、扣缴义务人、纳税担保人对税务机关确定纳税主体、征税对象、征税范围、减税、免税及退税、适用税率、计税依据、纳税环节、纳税期限、纳税地点以及税款征收方式等具体行政行为有异议而发生的争议。"},{"i":101,"n":"第一百零一条","txt":"税务机关送达税务文书，应当直接送交受送达人。"},{"i":102,"n":"第一百零二条","txt":"送达税务文书应当有送达回证，并由受送达人或者本细则规定的其他签收人在送达回证上记明收到日期，签名或者盖章，即为送达。"},{"i":103,"n":"第一百零三条","txt":"受送达人或者本细则规定的其他签收人拒绝签收税务文书的，送达人应当在送达回证上记明拒收理由和日期，并由送达人和见证人签名或者盖章，将税务文书留在受送达人处，即视为送达。"},{"i":104,"n":"第一百零四条","txt":"直接送达税务文书有困难的，可以委托其他有关机关或者其他单位代为送达，或者邮寄送达。"},{"i":105,"n":"第一百零五条","txt":"直接或者委托送达税务文书的，以签收人或者见证人在送达回证上的签收或者注明的收件日期为送达日期；邮寄送达的，以挂号函件回执上注明的收件日期为送达日期，并视为已送达。"},{"i":106,"n":"第一百零六条","txt":"有下列情形之一的，税务机关可以公告送达税务文书，自公告之日起满30日，即视为送达："},{"i":107,"n":"第一百零七条","txt":"税务文书的格式由国家税务总局制定。本细则所称税务文书，包括："},{"i":108,"n":"第一百零八条","txt":"税收征管法及本细则所称“以上”、“以下”、“日内”、“届满”均含本数。"},{"i":109,"n":"第一百零九条","txt":"税收征管法及本细则所规定期限的最后一日是法定休假日的，以休假日期满的次日为期限的最后一日；在期限内有连续3日以上法定休假日的，按休假日天数顺延。"},{"i":110,"n":"第一百一十条","txt":"税收征管法第三十条第三款规定的代扣、代收手续费，纳入预算管理，由税务机关依照法律、行政法规的规定付给扣缴义务人。"},{"i":111,"n":"第一百一十一条","txt":"纳税人、扣缴义务人委托税务代理人代为办理税务事宜的办法，由国家税务总局规定。"},{"i":112,"n":"第一百一十二条","txt":"耕地占用税、契税、农业税、牧业税的征收管理，按照国务院的有关规定执行。"},{"i":113,"n":"第一百一十三条","txt":"本细则自2002年10月15日起施行。1993年8月4日国务院发布的《中华人民共和国税收征收管理法实施细则》同时废止。"}],"tongjifashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国统计法》（以下简称统计法），制定本条例。"},{"i":2,"n":"第二条","txt":"统计资料能够通过行政记录取得的，不得组织实施调查。通过抽样调查、重点调查能够满足统计需要的，不得组织实施全面调查。"},{"i":3,"n":"第三条","txt":"县级以上人民政府统计机构和有关部门应当加强统计规律研究，健全新兴产业等统计，完善经济、社会、科技、资源和环境统计，推进互联网、大数据、云计算等现代信息技术在统计工作中的应用，满足经济社会发展需要。"},{"i":4,"n":"第四条","txt":"地方人民政府、县级以上人民政府统计机构和有关部门应当根据国家有关规定，明确本单位防范和惩治统计造假、弄虚作假的责任主体，严格执行统计法和本条例的规定。"},{"i":5,"n":"第五条","txt":"县级以上人民政府统计机构和有关部门不得组织实施营利性统计调查。"},{"i":6,"n":"第六条","txt":"部门统计调查项目、地方统计调查项目的主要内容不得与国家统计调查项目的内容重复、矛盾。"},{"i":7,"n":"第七条","txt":"统计调查项目的制定机关（以下简称制定机关）应当就项目的必要性、可行性、科学性进行论证，征求有关地方、部门、统计调查对象和专家的意见，并由制定机关按照会议制度集体讨论决定。"},{"i":8,"n":"第八条","txt":"制定机关申请审批统计调查项目，应当以公文形式向审批机关提交统计调查项目审批申请表、项目的统计调查制度和工作经费来源说明。"},{"i":9,"n":"第九条","txt":"统计调查项目符合下列条件的，审批机关应当作出予以批准的书面决定："},{"i":10,"n":"第十条","txt":"统计调查项目涉及其他部门职责的，审批机关应当在作出审批决定前，征求相关部门的意见。"},{"i":11,"n":"第十一条","txt":"审批机关应当自受理统计调查项目审批申请之日起20日内作出决定。20日内不能作出决定的，经审批机关负责人批准可以延长10日，并应当将延长审批期限的理由告知制定机关。"},{"i":12,"n":"第十二条","txt":"制定机关申请备案统计调查项目，应当以公文形式向备案机关提交统计调查项目备案申请表和项目的统计调查制度。"},{"i":13,"n":"第十三条","txt":"统计调查项目经批准或者备案的，审批机关或者备案机关应当及时公布统计调查项目及其统计调查制度的主要内容。涉及国家秘密的统计调查项目除外。"},{"i":14,"n":"第十四条","txt":"统计调查项目有下列情形之一的，审批机关或者备案机关应当简化审批或者备案程序，缩短期限："},{"i":15,"n":"第十五条","txt":"统计法第十七条第二款规定的国家统计标准是强制执行标准。各级人民政府、县级以上人民政府统计机构和有关部门组织实施的统计调查活动，应当执行国家统计标准。"},{"i":16,"n":"第十六条","txt":"统计机构、统计人员组织实施统计调查，应当就统计调查对象的法定填报义务、主要指标涵义和有关填报要求等，向统计调查对象作出说明。"},{"i":17,"n":"第十七条","txt":"国家机关、企业事业单位或者其他组织等统计调查对象提供统计资料，应当由填报人员和单位负责人签字，并加盖公章。个人作为统计调查对象提供统计资料，应当由本人签字。统计调查制度规定不需要签字、加盖公章的除外。"},{"i":18,"n":"第十八条","txt":"县级以上人民政府统计机构、有关部门推广使用网络报送统计资料，应当采取有效的网络安全保障措施。"},{"i":19,"n":"第十九条","txt":"县级以上人民政府统计机构、有关部门和乡、镇统计人员，应当对统计调查对象提供的统计资料进行审核。统计资料不完整或者存在明显错误的，应当由统计调查对象依法予以补充或者改正。"},{"i":20,"n":"第二十条","txt":"国家统计局应当建立健全统计数据质量监控和评估制度，加强对各省、自治区、直辖市重要统计数据的监控和评估。"},{"i":21,"n":"第二十一条","txt":"县级以上人民政府统计机构、有关部门和乡、镇人民政府应当妥善保管统计调查中取得的统计资料。"},{"i":22,"n":"第二十二条","txt":"统计调查中取得的统计调查对象的原始资料，应当至少保存2年。"},{"i":23,"n":"第二十三条","txt":"统计调查对象按照国家有关规定设置的原始记录和统计台账，应当至少保存2年。"},{"i":24,"n":"第二十四条","txt":"国家统计局统计调查取得的全国性统计数据和分省、自治区、直辖市统计数据，由国家统计局公布或者由国家统计局授权其派出的调查机构或者省级人民政府统计机构公布。"},{"i":25,"n":"第二十五条","txt":"国务院有关部门统计调查取得的统计数据，由国务院有关部门按照国家有关规定和已批准或者备案的统计调查制度公布。"},{"i":26,"n":"第二十六条","txt":"已公布的统计数据按照国家有关规定需要进行修订的，县级以上人民政府统计机构和有关部门应当及时公布修订后的数据，并就修订依据和情况作出说明。"},{"i":27,"n":"第二十七条","txt":"县级以上人民政府统计机构和有关部门应当及时公布主要统计指标涵义、调查范围、调查方法、计算方法、抽样调查样本量等信息，对统计数据进行解释说明。"},{"i":28,"n":"第二十八条","txt":"公布统计资料应当按照国家有关规定进行。公布前，任何单位和个人不得违反国家有关规定对外提供，不得利用尚未公布的统计资料谋取不正当利益。"},{"i":29,"n":"第二十九条","txt":"统计法第二十五条规定的能够识别或者推断单个统计调查对象身份的资料包括："},{"i":30,"n":"第三十条","txt":"统计调查中获得的能够识别或者推断单个统计调查对象身份的资料应当依法严格管理，除作为统计执法依据外，不得直接作为对统计调查对象实施行政许可、行政处罚等具体行政行为的依据，不得用于完成统计任务以外的目的。"},{"i":31,"n":"第三十一条","txt":"国家建立健全统计信息共享机制，实现县级以上人民政府统计机构和有关部门统计调查取得的资料共享。制定机关共同制定的统计调查项目，可以共同使用获取的统计资料。"},{"i":32,"n":"第三十二条","txt":"县级以上地方人民政府统计机构受本级人民政府和上级人民政府统计机构的双重领导，在统计业务上以上级人民政府统计机构的领导为主。"},{"i":33,"n":"第三十三条","txt":"县级以上人民政府统计机构和有关部门应当完成国家统计调查任务，执行国家统计调查项目的统计调查制度，组织实施本地方、本部门的统计调查活动。"},{"i":34,"n":"第三十四条","txt":"国家机关、企业事业单位和其他组织应当加强统计基础工作，为履行法定的统计资料报送义务提供组织、人员和工作条件保障。"},{"i":35,"n":"第三十五条","txt":"对在统计工作中做出突出贡献、取得显著成绩的单位和个人，按照国家有关规定给予表彰和奖励。"},{"i":36,"n":"第三十六条","txt":"县级以上人民政府统计机构从事统计执法工作的人员，应当具备必要的法律知识和统计业务知识，参加统计执法培训，并取得由国家统计局统一印制的统计执法证。"},{"i":37,"n":"第三十七条","txt":"任何单位和个人不得拒绝、阻碍对统计工作的监督检查和对统计违法行为的查处工作，不得包庇、纵容统计违法行为。"},{"i":38,"n":"第三十八条","txt":"任何单位和个人有权向县级以上人民政府统计机构举报统计违法行为。"},{"i":39,"n":"第三十九条","txt":"县级以上人民政府统计机构负责查处统计违法行为；法律、行政法规对有关部门查处统计违法行为另有规定的，从其规定。"},{"i":40,"n":"第四十条","txt":"下列情形属于统计法第三十七条第四项规定的对严重统计违法行为失察，对地方人民政府、政府统计机构或者有关部门、单位的负责人，由任免机关或者监察机关依法给予处分，并由县级以上人民政府统计机构予以通报："},{"i":41,"n":"第四十一条","txt":"县级以上人民政府统计机构或者有关部门组织实施营利性统计调查的，由本级人民政府、上级人民政府统计机构或者本级人民政府统计机构责令改正，予以通报；有违法所得的，没收违法所得。"},{"i":42,"n":"第四十二条","txt":"地方各级人民政府、县级以上人民政府统计机构或者有关部门及其负责人，侵犯统计机构、统计人员独立行使统计调查、统计报告、统计监督职权，或者采用下发文件、会议布置以及其他方式授意、指使、强令统计调查对象或者其他单位、人员编造虚假统计资料的，由上级人民政府、本级人民政府、上级人民政府统计机构或者本级人民政府统计机构责令改正，予以通报。"},{"i":43,"n":"第四十三条","txt":"县级以上人民政府统计机构或者有关部门在组织实施统计调查活动中有下列行为之一的，由本级人民政府、上级人民政府统计机构或者本级人民政府统计机构责令改正，予以通报："},{"i":44,"n":"第四十四条","txt":"县级以上人民政府统计机构或者有关部门违反本条例第二十四条、第二十五条规定公布统计数据的，由本级人民政府、上级人民政府统计机构或者本级人民政府统计机构责令改正，予以通报。"},{"i":45,"n":"第四十五条","txt":"违反国家有关规定对外提供尚未公布的统计资料或者利用尚未公布的统计资料谋取不正当利益的，由任免机关或者监察机关依法给予处分，并由县级以上人民政府统计机构予以通报。"},{"i":46,"n":"第四十六条","txt":"统计机构及其工作人员有下列行为之一的，由本级人民政府或者上级人民政府统计机构责令改正，予以通报："},{"i":47,"n":"第四十七条","txt":"地方各级人民政府、县级以上人民政府有关部门拒绝、阻碍统计监督检查或者转移、隐匿、篡改、毁弃原始记录和凭证、统计台账、统计调查表及其他相关证明和资料的，由上级人民政府、上级人民政府统计机构或者本级人民政府统计机构责令改正，予以通报。"},{"i":48,"n":"第四十八条","txt":"地方各级人民政府、县级以上人民政府统计机构和有关部门有本条例第四十一条至第四十七条所列违法行为之一的，对直接负责的主管人员和其他直接责任人员，由任免机关或者监察机关依法给予处分。"},{"i":49,"n":"第四十九条","txt":"乡、镇人民政府有统计法第三十八条第一款、第三十九条第一款所列行为之一的，依照统计法第三十八条、第三十九条的规定追究法律责任。"},{"i":50,"n":"第五十条","txt":"下列情形属于统计法第四十一条第二款规定的情节严重行为："},{"i":51,"n":"第五十一条","txt":"统计违法行为涉嫌犯罪的，县级以上人民政府统计机构应当将案件移送司法机关处理。"},{"i":52,"n":"第五十二条","txt":"中华人民共和国境外的组织、个人需要在中华人民共和国境内进行统计调查活动的，应当委托中华人民共和国境内具有涉外统计调查资格的机构进行。涉外统计调查资格应当依法报经批准。统计调查范围限于省、自治区、直辖市行政区域内的，由省级人民政府统计机构审批；统计调查范围跨省、自治区、直辖市行政区域的，由国家统计局审批。"},{"i":53,"n":"第五十三条","txt":"国家统计局或者省级人民政府统计机构对涉外统计违法行为进行调查，有权采取统计法第三十五条规定的措施。"},{"i":54,"n":"第五十四条","txt":"对违法从事涉外统计调查活动的单位、个人，由国家统计局或者省级人民政府统计机构责令改正或者责令停止调查，有违法所得的，没收违法所得；违法所得50万元以上的，并处违法所得1倍以上3倍以下的罚款；违法所得不足50万元或者没有违法所得的，处200万元以下的罚款；情节严重的，暂停或者取消涉外统计调查资格，撤销涉外社会调查项目批准决定；构成犯罪的，依法追究刑事责任。"},{"i":55,"n":"第五十五条","txt":"本条例自2017年8月1日起施行。1987年1月19日国务院批准、1987年2月15日国家统计局公布，2000年6月2日国务院批准修订、2000年6月15日国家统计局公布，2005年12月16日国务院修订的《中华人民共和国统计法实施细则》同时废止。"}],"yaopinguanlifashishitiaoli-2":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国药品管理法》（以下简称药品管理法），制定本条例。"},{"i":2,"n":"第二条","txt":"从事药品研制、生产、经营、使用和监督管理活动，应当坚持以人民健康为中心，遵循科学规律和伦理原则，全面防控风险。"},{"i":3,"n":"第三条","txt":"国家完善药品创新体系，支持以临床价值为导向的药品研制和创新，鼓励研究和创制新药，支持新药临床推广和使用；促进中药传承创新，充分发挥中药在预防、医疗和保健中的作用；促进仿制药研发创新，提升仿制药质量和疗效。"},{"i":4,"n":"第四条","txt":"县级以上人民政府承担药品监督管理职责的部门（以下称药品监督管理部门）负责药品监督管理工作。县级以上人民政府其他有关部门在各自职责范围内负责与药品有关的监督管理工作。"},{"i":5,"n":"第五条","txt":"国务院工业和信息化主管部门、国务院商务主管部门等按照职责分工，根据国民经济和社会发展规划、药品产业发展情况制定国家药品生产、流通等行业发展相关规划和产业政策，推动药品产业结构调整和技术创新，提升产业链韧性和安全水平，促进药品产业高质量发展。国务院药品监督管理部门配合国务院工业和信息化主管部门、国务院商务主管部门等，执行国家药品行业发展相关规划和产业政策。"},{"i":6,"n":"第六条","txt":"从事药品研制活动，应当遵守药物非临床研究质量管理规范、药物临床试验质量管理规范，保证记录和数据真实、准确、完整和可追溯。"},{"i":7,"n":"第七条","txt":"以申请药品注册为目的开展药物非临床安全性评价研究活动的，应当由经过资格认定的药物非临床安全性评价研究机构实施。申请药物非临床安全性评价研究机构资格认定应当向国务院药品监督管理部门提出申请，提交证明其符合药物非临床研究质量管理规范的资料。国务院药品监督管理部门应当组织开展审查，并自受理申请之日起20个工作日内作出决定。对符合规定条件的，准予许可并发给资格证书；对不符合规定条件的，不予许可并书面说明理由。"},{"i":8,"n":"第八条","txt":"药物临床试验申办者应当选择具备相应能力的药物临床试验机构和研究者，并履行受试者保护、临床试验用药品管理、临床试验数据管理、风险管理等责任。"},{"i":9,"n":"第九条","txt":"依照药品管理法第十九条第一款规定批准开展的药物临床试验变更申办者的，应当向国务院药品监督管理部门提出申请。国务院药品监督管理部门应当自受理申请之日起20个工作日内进行审查并作出决定。"},{"i":10,"n":"第十条","txt":"以申请药品注册为目的在境外开展药品研制活动的，应当遵守药品管理法、本条例等法律、法规、规章、标准和规范的有关规定；在境外取得的研究数据，符合国务院药品监督管理部门有关规定的，可以用于申请药品注册。"},{"i":11,"n":"第十一条","txt":"以申请药品注册为目的进口研制或者检验所需的对照药品、样品的，应当经国务院药品监督管理部门批准；但是，药物临床试验批准证明文件载明的临床试验用药品可以凭批准证明文件进口。国务院药品监督管理部门应当自受理申请之日起20个工作日内进行审查并作出决定。"},{"i":12,"n":"第十二条","txt":"研制化学仿制药应当按照国务院药品监督管理部门制定的技术要求，科学选择对照药品进行对比研究；有经国务院药品监督管理部门确定的参比制剂的，应当选择参比制剂作为对照药品进行对比研究。"},{"i":13,"n":"第十三条","txt":"研制中药应当以中医药理论为指导，根据中医药理论、中药人用经验、临床试验数据等综合评价中药的安全性、有效性。评价中药的有效性应当与其临床定位相适应，体现中药的特点。"},{"i":14,"n":"第十四条","txt":"研制、生产中药应当保障中药材来源、质量的稳定性和资源的可持续利用，避免对生态环境产生不利影响；涉及野生动物、植物的，应当符合国家有关规定。"},{"i":15,"n":"第十五条","txt":"对申请注册的药品，国务院药品监督管理部门依照药品管理法第二十五条规定进行审评审批。"},{"i":16,"n":"第十六条","txt":"国务院药品监督管理部门在审批药品时，对化学原料药一并审评审批；符合条件的，对药品颁发药品注册证书，对化学原料药颁发化学原料药批准证书。仿制已注册药品使用的化学原料药的，也可以直接向国务院药品监督管理部门提出审评审批申请；符合条件的，颁发化学原料药批准证书。国务院药品监督管理部门在审评审批化学原料药时，对化学原料药的质量标准、生产工艺、标签一并核准。"},{"i":17,"n":"第十七条","txt":"药品注册证书、化学原料药批准证书有效期为5年。有效期届满，需要继续上市的，应当申请再注册。"},{"i":18,"n":"第十八条","txt":"符合国务院药品监督管理部门规定的非处方药注册情形的，药品注册申请人可以直接提出非处方药注册申请。"},{"i":19,"n":"第十九条","txt":"国家推动提高药品标准，持续提升药品质量水平。"},{"i":20,"n":"第二十条","txt":"研制药品、申请药品注册应当使用国家药品标准品、对照品。没有国家药品标准品、对照品的，药品注册申请人应当向国务院药品监督管理部门设置或者指定的药品检验机构报送药品质量标准研究所使用的原料及相关技术资料，药品检验机构应当依法研制、标定国家药品标准品、对照品。"},{"i":21,"n":"第二十一条","txt":"国家支持儿童用药品、罕见病治疗用药品的研制和创新。"},{"i":22,"n":"第二十二条","txt":"国家对含有新型化学成份的药品以及符合条件的其他药品的上市许可持有人提交的自行取得且未披露的试验数据和其他数据实施保护，任何人不得对该未披露的试验数据和其他数据进行不正当的商业利用。"},{"i":23,"n":"第二十三条","txt":"药品上市许可持有人应当建立健全药品质量保证体系，设立独立的质量管理部门，配备生产负责人、质量负责人、质量受权人。质量受权人应当独立履行药品上市放行职责。"},{"i":24,"n":"第二十四条","txt":"药品上市许可持有人应当遵守药物警戒质量管理规范，建立健全药物警戒体系，对药品不良反应及其他与用药有关的有害反应进行监测，建立风险识别、评估和控制机制。药品经营企业、医疗机构应当配合药品上市许可持有人开展药物警戒工作。"},{"i":25,"n":"第二十五条","txt":"药品上市许可持有人为境外企业的，其依照药品管理法第三十八条规定指定的中国境内企业法人应当具备相应的质量管理能力和风险控制能力，设立相应的管理部门、配备相应的人员；被指定的中国境内企业法人的相关信息应当在药品说明书中载明。"},{"i":26,"n":"第二十六条","txt":"药品上市许可持有人应当按照国务院药品监督管理部门的规定，提供语音、大字、盲文或者电子等无障碍格式版本的药品标签、说明书，方便残疾人、老年人用药。"},{"i":27,"n":"第二十七条","txt":"药品上市许可持有人应当全面评估、验证药品生产过程中的变更对药品安全性、有效性和质量可控性的影响，按照国务院药品监督管理部门的规定提出变更申请或者进行备案、报告。"},{"i":28,"n":"第二十八条","txt":"药品上市许可持有人应当持续考察已注册药品的质量、疗效和不良反应。"},{"i":29,"n":"第二十九条","txt":"中药饮片生产企业、中药配方颗粒生产企业履行药品上市许可持有人的相关义务，对中药饮片、中药配方颗粒生产、销售实行全过程管理，建立中药饮片、中药配方颗粒追溯体系，保证中药饮片、中药配方颗粒安全、有效、可追溯。"},{"i":30,"n":"第三十条","txt":"从事药品生产活动，应当向所在地省级人民政府药品监督管理部门提出申请，提交证明其符合药品管理法第四十二条规定条件的资料；从事疫苗生产活动，还应当提交证明其符合《中华人民共和国疫苗管理法》（以下简称疫苗管理法）第二十二条第三款规定条件的资料。省级人民政府药品监督管理部门应当组织开展审查，并自受理申请之日起30个工作日内作出决定。对符合规定条件的，准予许可并发给药品生产许可证；对不符合规定条件的，不予许可并书面说明理由。"},{"i":31,"n":"第三十一条","txt":"药品上市许可持有人自行生产药品的，应当取得药品生产许可证。"},{"i":32,"n":"第三十二条","txt":"药品上市许可持有人确有需要的，可以委托符合条件的药品生产企业分段生产下列药品："},{"i":33,"n":"第三十三条","txt":"有下列情形之一，超出疫苗上市许可持有人生产能力的，经国务院药品监督管理部门批准，疫苗上市许可持有人可以委托符合条件的疫苗生产企业生产或者分段生产疫苗："},{"i":34,"n":"第三十四条","txt":"生产疫苗、血液制品等生物制品，应当按照规定采用信息化手段如实记录生产、检验过程中形成的所有数据。"},{"i":35,"n":"第三十五条","txt":"在中国境内上市的药品在境外生产的，其生产活动应当符合药品管理法、本条例等法律、法规、规章、标准和规范的有关要求。境外生产的药品在境内分包装的，药品上市许可持有人向国务院药品监督管理部门备案后，实施分包装的药品生产企业可以向药品经营企业、医疗机构销售其分包装的药品。"},{"i":36,"n":"第三十六条","txt":"取得药品批准证明文件前生产的下列药品，符合药品上市放行要求的，在取得药品批准证明文件后，可以上市销售："},{"i":37,"n":"第三十七条","txt":"国家鼓励发展中药材规范化种植养殖，鼓励使用道地中药材。省级人民政府根据当地实际制定相关规划，鼓励实施中药材生产质量管理规范，推动中药材规范化种植养殖。"},{"i":38,"n":"第三十八条","txt":"生产药品使用的中药材应当符合国家药品标准、药品注册标准。没有国家药品标准、药品注册标准的，应当符合省级人民政府药品监督管理部门制定的地区性民间习用药材标准。"},{"i":39,"n":"第三十九条","txt":"中药饮片生产企业应当自行炮制中药饮片，不得委托炮制中药饮片。"},{"i":40,"n":"第四十条","txt":"中药配方颗粒生产企业应当将所生产的中药配方颗粒品种向所在地省级人民政府药品监督管理部门备案。"},{"i":41,"n":"第四十一条","txt":"从事辅料、直接接触药品的包装材料和容器生产活动，应当遵守药品生产质量管理规范的有关规定，建立健全生产质量管理体系，保证生产全过程持续符合法定要求。"},{"i":42,"n":"第四十二条","txt":"从事药品经营活动，应当向所在地县级以上地方人民政府药品监督管理部门提出申请，提交证明其符合药品管理法第五十二条规定条件的资料。县级以上地方人民政府药品监督管理部门应当组织开展审查，并自受理申请之日起20个工作日内作出决定。对符合规定条件的，准予许可并发给药品经营许可证；对不符合规定条件的，不予许可并书面说明理由。"},{"i":43,"n":"第四十三条","txt":"药品经营企业应当配备与其经营范围、规模相适应的依法经过资格认定的药师或者其他药学技术人员；但是，只经营乙类非处方药的药品零售企业，可以按照国务院药品监督管理部门的规定配备药学技术人员。"},{"i":44,"n":"第四十四条","txt":"药品上市许可持有人、药品生产企业、药品经营企业储存、运输药品，应当根据药品的包装、质量特性、温度控制要求等采取有效措施，保证储存、运输过程中的药品质量。药品上市许可持有人、药品生产企业、药品经营企业委托储存、运输药品的，应当选择具备相应能力的受托方，并对受托方进行监督。受托方应当加强药品储存、运输过程管理，采取有效措施保证药品质量。"},{"i":45,"n":"第四十五条","txt":"药品网络交易第三方平台提供者应当建立健全药品网络销售质量管理体系，设立相应的管理部门、配备药学技术人员等相关专业人员，制定并实施药品质量管理、配送管理等制度。药品网络交易第三方平台提供者应当对申请进入平台经营的药品上市许可持有人、药品经营企业的资质等进行审核，对平台展示的药品信息进行检查，对发生在平台的药品经营行为进行管理。药品网络交易第三方平台提供者应当按照规定保存审核、检查记录以及平台展示的药品信息。"},{"i":46,"n":"第四十六条","txt":"疫苗、血液制品、麻醉药品、精神药品、医疗用毒性药品、放射性药品、药品类易制毒化学品等国家实行特殊管理的药品不得通过网络销售；其他用药风险较高的药品，不得通过网络零售。具体目录由国务院药品监督管理部门制定。"},{"i":47,"n":"第四十七条","txt":"对医疗机构提出的因临床急需进口少量药品的申请，国务院药品监督管理部门应当征求国务院卫生健康主管部门的意见，及时进行审查并作出决定。国务院授权省级人民政府实施审批的，被授权的省级人民政府应当结合当地实际制定具体审批办法。"},{"i":48,"n":"第四十八条","txt":"个人携带、邮寄少量药品进境的，应当以合理自用数量为限，遵守国家关于个人物品进境管理的规定。"},{"i":49,"n":"第四十九条","txt":"医疗机构应当制定并实施药品进货检查验收、保管、使用等管理制度，设立相应的管理部门或者指定人员负责药品质量管理工作。"},{"i":50,"n":"第五十条","txt":"医疗机构应当加强对处方开具、审核和调配的管理，提高医师合理用药水平。"},{"i":51,"n":"第五十一条","txt":"医师在网络诊疗活动中不得开具本条例第四十六条规定的药品的处方。"},{"i":52,"n":"第五十二条","txt":"医疗机构应当向患者提供符合国务院卫生健康主管部门规定的处方，患者可以选择凭处方向药品零售企业购买药品。"},{"i":53,"n":"第五十三条","txt":"对正在开展临床试验的用于治疗严重危及生命且尚无有效治疗手段的疾病的药物，经医学观察可能获益，并且符合伦理原则的，经伦理委员会审查同意、患者或者其监护人签署知情同意书后，可以在开展临床试验的机构内用于其他病情相同但无法参加临床试验的患者。"},{"i":54,"n":"第五十四条","txt":"医疗机构配制制剂，应当向所在地省级人民政府药品监督管理部门提出申请，提交证明其符合药品管理法第七十五条第一款规定条件的资料。省级人民政府药品监督管理部门应当组织开展审查，并自受理申请之日起30个工作日内作出决定。对符合规定条件的，准予许可并发给医疗机构制剂许可证；对不符合规定条件的，不予许可并书面说明理由。"},{"i":55,"n":"第五十五条","txt":"医疗机构应当向所在地省级人民政府药品监督管理部门报送拟配制制剂的数据、资料和样品，经审评审批取得医疗机构制剂注册证书后，方可配制；但是，仅应用传统工艺配制的中药制剂，医疗机构向所在地省级人民政府药品监督管理部门备案后即可配制。"},{"i":56,"n":"第五十六条","txt":"临床确有需要的儿童用药品，市场上没有供应或者没有供儿童使用的剂型、规格的，由国务院卫生健康主管部门会同国务院药品监督管理部门纳入儿童常用医疗机构制剂清单，支持医疗机构配制、使用，满足儿童患者临床用药需求。"},{"i":57,"n":"第五十七条","txt":"下列药品不得作为医疗机构制剂："},{"i":58,"n":"第五十八条","txt":"医疗机构配制制剂，应当遵守医疗机构制剂配制质量管理规范，建立健全制剂配制质量管理体系，保证制剂配制全过程持续符合法定要求。医疗机构制剂配制质量管理规范由国务院药品监督管理部门制定。"},{"i":59,"n":"第五十九条","txt":"医疗机构制剂只能凭医师处方在本医疗机构使用，不得在市场上销售或者变相销售，不得发布医疗机构制剂广告。"},{"i":60,"n":"第六十条","txt":"医疗机构发现疑似药品不良反应，应当按照规定及时报告药品监督管理部门和卫生健康主管部门。"},{"i":61,"n":"第六十一条","txt":"医疗机构发现购进、使用的药品存在质量问题，应当立即采取措施控制风险，及时告知供货单位和药品上市许可持有人，并向所在地县级人民政府药品监督管理部门报告。"},{"i":62,"n":"第六十二条","txt":"药品监督管理部门和卫生健康主管部门依据各自职责，分别对药品使用环节的药品质量和药品使用行为进行监督管理。"},{"i":63,"n":"第六十三条","txt":"药品监督管理部门实施监督检查，可以采取下列措施："},{"i":64,"n":"第六十四条","txt":"国务院药品监督管理部门应当制定统一的药品追溯标准和规范。药品上市许可持有人、药品生产企业应当按照规定在药品包装上赋予追溯标识。药品上市许可持有人、药品生产企业、药品经营企业和医疗机构应当按照规定提供追溯信息，保证药品可追溯。"},{"i":65,"n":"第六十五条","txt":"国务院药品监督管理部门按照程序设置国家药品专业技术机构。省级人民政府药品监督管理部门可以根据当地药品产业发展情况和监督管理工作需要，按照程序设置地方药品专业技术机构。国家药品专业技术机构应当加强对地方药品专业技术机构的技术指导。"},{"i":66,"n":"第六十六条","txt":"药品质量抽查检验应当遵循科学、规范、公正原则。"},{"i":67,"n":"第六十七条","txt":"当事人对药品检验机构的检验结果有异议的，可以自收到药品检验结果之日起7日内申请复验。"},{"i":68,"n":"第六十八条","txt":"省级以上人民政府药品监督管理部门公告的药品质量抽查检验结果应当包括被抽检药品的品名、样品来源、标示的药品上市许可持有人和生产企业或者标示的医疗机构、产品批号、规格、检验机构、检验依据、检验结论、不符合规定项目等内容。药品质量抽查检验结果公告不当的，发布部门应当自确认不当之日起5个工作日内，在原公告范围内予以更正。"},{"i":69,"n":"第六十九条","txt":"对可能掺杂、掺假的药品，按照国家药品标准、药品注册标准规定的检验项目和检验方法无法检验的，药品检验机构可以使用国务院药品监督管理部门批准的补充检验项目和检验方法进行检验。使用补充检验项目和检验方法得出的检验结果，可以作为认定药品质量的依据。"},{"i":70,"n":"第七十条","txt":"药品监督管理部门依照药品管理法第九十九条第三款规定采取暂停生产、销售、使用、进口等风险控制措施的，药品上市许可持有人、药品生产企业、药品经营企业、医疗机构应当进行整改，消除安全隐患。药品监督管理部门评估认为符合相关要求的，应当解除已采取的风险控制措施。"},{"i":71,"n":"第七十一条","txt":"下列情形属于药品管理法第九十八条第二款第二项规定的假药："},{"i":72,"n":"第七十二条","txt":"依照药品管理法第九十八条第二款第四项规定认定假药，以及依照药品管理法第九十八条第三款第三项至第五项规定认定劣药，不需要进行药品检验。依照药品管理法第九十八条第二款、第三款的其他规定认定假药或者劣药，应当进行药品检验；但是，原料、辅料的采购和使用记录等证据能够充分证明属于假药或者劣药的，可以不进行药品检验。"},{"i":73,"n":"第七十三条","txt":"发生药品安全事件的单位应当立即采取措施防止危害扩大，并立即报告事件发生地县级人民政府药品监督管理部门。"},{"i":74,"n":"第七十四条","txt":"国家加强药品储备，实行中央和地方两级储备。具体办法由国务院工业和信息化主管部门会同国务院有关部门制定。"},{"i":75,"n":"第七十五条","txt":"国务院卫生健康主管部门会同国务院有关部门制定国家药物政策和国家基本药物制度，完善国家基本药物目录管理机制。"},{"i":76,"n":"第七十六条","txt":"市场监督管理部门加强药品生产、经营中的反垄断和反不正当竞争监督管理，依法查处垄断、不正当竞争违法行为，维护公平竞争秩序。"},{"i":77,"n":"第七十七条","txt":"药品监督管理等部门在监督管理中发现公职人员涉嫌职务违法或者职务犯罪的问题线索，应当及时移送监察机关。"},{"i":78,"n":"第七十八条","txt":"进行药品注册、实施药品注册检验和强制性检验，可以收取费用。具体收费项目、收费标准分别由国务院财政部门、国务院发展改革部门按照国家有关规定制定。"},{"i":79,"n":"第七十九条","txt":"有下列情形之一的，由县级以上地方人民政府药品监督管理部门责令限期改正，没收违法生产、销售的药品和违法所得，并处违法生产、销售的药品货值金额10倍以上20倍以下的罚款，违法生产、批发的药品货值金额不足10万元的，按10万元计算，违法零售的药品货值金额不足1万元的，按1万元计算；情节严重的，还应当责令停产停业整顿直至由原发证部门吊销药品生产许可证、药品经营许可证："},{"i":80,"n":"第八十条","txt":"有下列情形之一的，由省级人民政府药品监督管理部门责令限期改正，给予警告；逾期不改正的，处10万元以上50万元以下的罚款："},{"i":81,"n":"第八十一条","txt":"医疗机构未经批准使用其他医疗机构配制的制剂的，依照药品管理法第一百二十九条、第一百三十九条规定予以处罚。"},{"i":82,"n":"第八十二条","txt":"申请药物非临床安全性评价研究机构资格、药物临床试验许可、药品生产许可、药品经营许可、医疗机构制剂许可、药品注册等许可，提供虚假证明、数据、资料、样品或者采取其他欺骗手段的，县级以上人民政府药品监督管理部门不予受理或者不予许可，10年内不受理其相应申请，并处50万元以上500万元以下的罚款；情节严重的，还应当对法定代表人、主要负责人、直接负责的主管人员和其他责任人员处2万元以上20万元以下的罚款，禁止其10年内从事药品生产经营活动。"},{"i":83,"n":"第八十三条","txt":"已办理备案的药物临床试验机构不符合备案条件的，由省级以上人民政府药品监督管理部门责令限期改正；逾期仍不符合备案条件的，取消相关药物临床试验专业备案或者药物临床试验机构备案，禁止其1年内开展相关专业药物临床试验或者禁止其1年内开展药物临床试验。"},{"i":84,"n":"第八十四条","txt":"药品网络交易第三方平台提供者未按照规定建立健全药品网络销售质量管理体系的，由省级人民政府药品监督管理部门责令限期改正，给予警告；逾期不改正的，处10万元以上50万元以下的罚款；情节严重的，处50万元以上200万元以下的罚款。"},{"i":85,"n":"第八十五条","txt":"拒不执行药品监督管理部门依法采取的暂停生产、销售、使用、进口等风险控制措施的，由县级以上人民政府药品监督管理部门处违法生产、销售、使用、进口药品货值金额5倍以上10倍以下的罚款，货值金额不足1万元的，按1万元计算；情节严重的，还应当责令停产停业整顿直至由原发证部门吊销药品批准证明文件、药品生产许可证、药品经营许可证、医疗机构制剂许可证，对法定代表人、主要负责人、直接负责的主管人员和其他责任人员处2万元以上20万元以下的罚款。"},{"i":86,"n":"第八十六条","txt":"药品经营企业、医疗机构履行了药品管理法、疫苗管理法、本条例规定的进货检查验收等义务，有充分证据证明其不知道所销售或者使用的药品是假药、劣药的，免予处罚，但应当收缴其销售或者使用的假药、劣药；造成人身、财产或者其他损害的，依法承担赔偿责任。"},{"i":87,"n":"第八十七条","txt":"药品监督管理部门及其工作人员违反本条例规定，泄露药品上市许可持有人未披露的试验数据或者其他数据，造成药品上市许可持有人损失的，由药品监督管理部门依法承担赔偿责任；药品监督管理部门赔偿损失后，应当责令故意或者有重大过失的工作人员承担部分或者全部赔偿费用，并对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":88,"n":"第八十八条","txt":"药品注册审评所需时间以及药物非临床安全性评价研究机构资格申请、药品生产许可申请、药品经营许可申请、医疗机构制剂许可申请审查中涉及的技术审核所需时间不计入药品监督管理部门实施行政许可的期限。"},{"i":89,"n":"第八十九条","txt":"本条例自2026年5月15日起施行。"}],"yaopinguanlifashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国药品管理法》（以下简称《药品管理法》），制定本条例。"},{"i":2,"n":"第二条","txt":"国务院药品监督管理部门设置国家药品检验机构。"},{"i":3,"n":"第三条","txt":"开办药品生产企业，申办人应当向拟办企业所在地省、自治区、直辖市人民政府药品监督管理部门提出申请。省、自治区、直辖市人民政府药品监督管理部门应当自收到申请之日起30个工作日内，依据《药品管理法》第八条规定的开办条件组织验收；验收合格的，发给《药品生产许可证》。"},{"i":4,"n":"第四条","txt":"药品生产企业变更《药品生产许可证》许可事项的，应当在许可事项发生变更30日前，向原发证机关申请《药品生产许可证》变更登记；未经批准，不得变更许可事项。原发证机关应当自收到申请之日起15个工作日内作出决定。"},{"i":5,"n":"第五条","txt":"省级以上人民政府药品监督管理部门应当按照《药品生产质量管理规范》和国务院药品监督管理部门规定的实施办法和实施步骤，组织对药品生产企业的认证工作；符合《药品生产质量管理规范》的，发给认证证书。其中，生产注射剂、放射性药品和国务院药品监督管理部门规定的生物制品的药品生产企业的认证工作，由国务院药品监督管理部门负责。"},{"i":6,"n":"第六条","txt":"新开办药品生产企业、药品生产企业新建药品生产车间或者新增生产剂型的，应当自取得药品生产证明文件或者经批准正式生产之日起30日内，按照规定向药品监督管理部门申请《药品生产质量管理规范》认证。受理申请的药品监督管理部门应当自收到企业申请之日起6个月内，组织对申请企业是否符合《药品生产质量管理规范》进行认证；认证合格的，发给认证证书。"},{"i":7,"n":"第七条","txt":"国务院药品监督管理部门应当设立《药品生产质量管理规范》认证检查员库。《药品生产质量管理规范》认证检查员必须符合国务院药品监督管理部门规定的条件。进行《药品生产质量管理规范》认证，必须按照国务院药品监督管理部门的规定，从《药品生产质量管理规范》认证检查员库中随机抽取认证检查员组成认证检查组进行认证检查。"},{"i":8,"n":"第八条","txt":"《药品生产许可证》有效期为5年。有效期届满，需要继续生产药品的，持证企业应当在许可证有效期届满前6个月，按照国务院药品监督管理部门的规定申请换发《药品生产许可证》。"},{"i":9,"n":"第九条","txt":"药品生产企业生产药品所使用的原料药，必须具有国务院药品监督管理部门核发的药品批准文号或者进口药品注册证书、医药产品注册证书；但是，未实施批准文号管理的中药材、中药饮片除外。"},{"i":10,"n":"第十条","txt":"依据《药品管理法》第十三条规定，接受委托生产药品的，受托方必须是持有与其受托生产的药品相适应的《药品生产质量管理规范》认证证书的药品生产企业。"},{"i":11,"n":"第十一条","txt":"开办药品批发企业、药品零售企业，应当依据《药品管理法》的规定提出药品经营许可申请，并提交证明其符合《药品管理法》规定条件的资料。"},{"i":12,"n":"第十二条","txt":"对药品经营许可申请，应当自受理申请之日起20个工作日内作出行政许可决定。对符合规定条件的，准予许可并发给《药品经营许可证》；对不符合规定条件的，不予许可并书面说明理由。"},{"i":13,"n":"第十三条","txt":"省、自治区、直辖市人民政府药品监督管理部门和设区的市级药品监督管理机构负责组织药品经营企业的认证工作。药品经营企业应当按照国务院药品监督管理部门规定的实施办法和实施步骤，通过省、自治区、直辖市人民政府药品监督管理部门或者设区的市级药品监督管理机构组织的《药品经营质量管理规范》的认证，取得认证证书。《药品经营质量管理规范》认证证书的格式由国务院药品监督管理部门统一规定。"},{"i":14,"n":"第十四条","txt":"省、自治区、直辖市人民政府药品监督管理部门应当设立《药品经营质量管理规范》认证检查员库。《药品经营质量管理规范》认证检查员必须符合国务院药品监督管理部门规定的条件。进行《药品经营质量管理规范》认证，必须按照国务院药品监督管理部门的规定，从《药品经营质量管理规范》认证检查员库中随机抽取认证检查员组成认证检查组进行认证检查。"},{"i":15,"n":"第十五条","txt":"国家实行处方药和非处方药分类管理制度。国家根据非处方药品的安全性，将非处方药分为甲类非处方药和乙类非处方药。"},{"i":16,"n":"第十六条","txt":"药品经营企业变更《药品经营许可证》许可事项的，应当在许可事项发生变更30日前，向原发证机关申请《药品经营许可证》变更登记；未经批准，不得变更许可事项。原发证机关应当自收到企业申请之日起15个工作日内作出决定。"},{"i":17,"n":"第十七条","txt":"《药品经营许可证》有效期为5年。有效期届满，需要继续经营药品的，持证企业应当在许可证有效期届满前6个月，按照国务院药品监督管理部门的规定申请换发《药品经营许可证》。"},{"i":18,"n":"第十八条","txt":"交通不便的边远地区城乡集市贸易市场没有药品零售企业的，当地药品零售企业经所在地县（市）药品监督管理机构批准并到工商行政管理部门办理登记注册后，可以在该城乡集市贸易市场内设点并在批准经营的药品范围内销售非处方药品。"},{"i":19,"n":"第十九条","txt":"通过互联网进行药品交易的药品生产企业、药品经营企业、医疗机构及其交易的药品，必须符合《药品管理法》和本条例的规定。互联网药品交易服务的管理办法，由国务院药品监督管理部门会同国务院有关部门制定。"},{"i":20,"n":"第二十条","txt":"医疗机构设立制剂室，应当向所在地省、自治区、直辖市人民政府卫生行政部门提出申请，经审核同意后，报同级人民政府药品监督管理部门审批；省、自治区、直辖市人民政府药品监督管理部门验收合格的，予以批准，发给《医疗机构制剂许可证》。"},{"i":21,"n":"第二十一条","txt":"医疗机构变更《医疗机构制剂许可证》许可事项的，应当在许可事项发生变更30日前，依照本条例第二十条的规定向原审核、批准机关申请《医疗机构制剂许可证》变更登记；未经批准，不得变更许可事项。原审核、批准机关应当在各自收到申请之日起15个工作日内作出决定。"},{"i":22,"n":"第二十二条","txt":"《医疗机构制剂许可证》有效期为5年。有效期届满，需要继续配制制剂的，医疗机构应当在许可证有效期届满前6个月，按照国务院药品监督管理部门的规定申请换发《医疗机构制剂许可证》。"},{"i":23,"n":"第二十三条","txt":"医疗机构配制制剂，必须按照国务院药品监督管理部门的规定报送有关资料和样品，经所在地省、自治区、直辖市人民政府药品监督管理部门批准，并发给制剂批准文号后，方可配制。"},{"i":24,"n":"第二十四条","txt":"医疗机构配制的制剂不得在市场上销售或者变相销售，不得发布医疗机构制剂广告。"},{"i":25,"n":"第二十五条","txt":"医疗机构审核和调配处方的药剂人员必须是依法经资格认定的药学技术人员。"},{"i":26,"n":"第二十六条","txt":"医疗机构购进药品，必须有真实、完整的药品购进记录。药品购进记录必须注明药品的通用名称、剂型、规格、批号、有效期、生产厂商、供货单位、购货数量、购进价格、购货日期以及国务院药品监督管理部门规定的其他内容。"},{"i":27,"n":"第二十七条","txt":"医疗机构向患者提供的药品应当与诊疗范围相适应，并凭执业医师或者执业助理医师的处方调配。"},{"i":28,"n":"第二十八条","txt":"药物非临床安全性评价研究机构必须执行《药物非临床研究质量管理规范》，药物临床试验机构必须执行《药物临床试验质量管理规范》。《药物非临床研究质量管理规范》、《药物临床试验质量管理规范》由国务院药品监督管理部门分别商国务院科学技术行政部门和国务院卫生行政部门制定。"},{"i":29,"n":"第二十九条","txt":"药物临床试验、生产药品和进口药品，应当符合《药品管理法》及本条例的规定，经国务院药品监督管理部门审查批准；国务院药品监督管理部门可以委托省、自治区、直辖市人民政府药品监督管理部门对申报药物的研制情况及条件进行审查，对申报资料进行形式审查，并对试制的样品进行检验。具体办法由国务院药品监督管理部门制定。"},{"i":30,"n":"第三十条","txt":"研制新药，需要进行临床试验的，应当依照《药品管理法》第二十九条的规定，经国务院药品监督管理部门批准。"},{"i":31,"n":"第三十一条","txt":"生产已有国家标准的药品，应当按照国务院药品监督管理部门的规定，向省、自治区、直辖市人民政府药品监督管理部门或者国务院药品监督管理部门提出申请，报送有关技术资料并提供相关证明文件。省、自治区、直辖市人民政府药品监督管理部门应当自受理申请之日起30个工作日内进行审查，提出意见后报送国务院药品监督管理部门审核，并同时将审查意见通知申报方。国务院药品监督管理部门经审核符合规定的，发给药品批准文号。"},{"i":32,"n":"第三十二条","txt":"变更研制新药、生产药品和进口药品已获批准证明文件及其附件中载明事项的，应当向国务院药品监督管理部门提出补充申请；国务院药品监督管理部门经审核符合规定的，应当予以批准。其中，不改变药品内在质量的，应当向省、自治区、直辖市人民政府药品监督管理部门提出补充申请；省、自治区、直辖市人民政府药品监督管理部门经审核符合规定的，应当予以批准，并报国务院药品监督管理部门备案。不改变药品内在质量的补充申请事项由国务院药品监督管理部门制定。"},{"i":33,"n":"第三十三条","txt":"国务院药品监督管理部门根据保护公众健康的要求，可以对药品生产企业生产的新药品种设立不超过5年的监测期；在监测期内，不得批准其他企业生产和进口。"},{"i":34,"n":"第三十四条","txt":"国家对获得生产或者销售含有新型化学成份药品许可的生产者或者销售者提交的自行取得且未披露的试验数据和其他数据实施保护，任何人不得对该未披露的试验数据和其他数据进行不正当的商业利用。"},{"i":35,"n":"第三十五条","txt":"申请进口的药品，应当是在生产国家或者地区获得上市许可的药品；未在生产国家或者地区获得上市许可的，经国务院药品监督管理部门确认该药品品种安全、有效而且临床需要的，可以依照《药品管理法》及本条例的规定批准进口。"},{"i":36,"n":"第三十六条","txt":"医疗机构因临床急需进口少量药品的，应当持《医疗机构执业许可证》向国务院药品监督管理部门提出申请；经批准后，方可进口。进口的药品应当在指定医疗机构内用于特定医疗目的。"},{"i":37,"n":"第三十七条","txt":"进口药品到岸后，进口单位应当持《进口药品注册证》或者《医药产品注册证》以及产地证明原件、购货合同副本、装箱单、运单、货运发票、出厂检验报告书、说明书等材料，向口岸所在地药品监督管理部门备案。口岸所在地药品监督管理部门经审查，提交的材料符合要求的，发给《进口药品通关单》。进口单位凭《进口药品通关单》向海关办理报关验放手续。"},{"i":38,"n":"第三十八条","txt":"疫苗类制品、血液制品、用于血源筛查的体外诊断试剂以及国务院药品监督管理部门规定的其他生物制品在销售前或者进口时，应当按照国务院药品监督管理部门的规定进行检验或者审核批准；检验不合格或者未获批准的，不得销售或者进口。"},{"i":39,"n":"第三十九条","txt":"国家鼓励培育中药材。对集中规模化栽培养殖、质量可以控制并符合国务院药品监督管理部门规定条件的中药材品种，实行批准文号管理。"},{"i":40,"n":"第四十条","txt":"国务院药品监督管理部门对已批准生产、销售的药品进行再评价，根据药品再评价结果，可以采取责令修改药品说明书，暂停生产、销售和使用的措施；对不良反应大或者其他原因危害人体健康的药品，应当撤销该药品批准证明文件。"},{"i":41,"n":"第四十一条","txt":"国务院药品监督管理部门核发的药品批准文号、《进口药品注册证》、《医药产品注册证》的有效期为5年。有效期届满，需要继续生产或者进口的，应当在有效期届满前6个月申请再注册。药品再注册时，应当按照国务院药品监督管理部门的规定报送相关资料。有效期届满，未申请再注册或者经审查不符合国务院药品监督管理部门关于再注册的规定的，注销其药品批准文号、《进口药品注册证》或者《医药产品注册证》。"},{"i":42,"n":"第四十二条","txt":"非药品不得在其包装、标签、说明书及有关宣传资料上进行含有预防、治疗、诊断人体疾病等有关内容的宣传；但是，法律、行政法规另有规定的除外。"},{"i":43,"n":"第四十三条","txt":"药品生产企业使用的直接接触药品的包装材料和容器，必须符合药用要求和保障人体健康、安全的标准。"},{"i":44,"n":"第四十四条","txt":"生产中药饮片，应当选用与药品性质相适应的包装材料和容器；包装不符合规定的中药饮片，不得销售。中药饮片包装必须印有或者贴有标签。"},{"i":45,"n":"第四十五条","txt":"药品包装、标签、说明书必须依照《药品管理法》第五十四条和国务院药品监督管理部门的规定印制。"},{"i":46,"n":"第四十六条","txt":"医疗机构配制制剂所使用的直接接触药品的包装材料和容器、制剂的标签和说明书应当符合《药品管理法》第六章和本条例的有关规定，并经省、自治区、直辖市人民政府药品监督管理部门批准。"},{"i":47,"n":"第四十七条","txt":"政府价格主管部门依照《价格法》第二十八条的规定实行药品价格监测时，为掌握、分析药品价格变动和趋势，可以指定部分药品生产企业、药品经营企业和医疗机构作为价格监测定点单位；定点单位应当给予配合、支持，如实提供有关信息资料。"},{"i":48,"n":"第四十八条","txt":"发布药品广告，应当向药品生产企业所在地省、自治区、直辖市人民政府药品监督管理部门报送有关材料。省、自治区、直辖市人民政府药品监督管理部门应当自收到有关材料之日起10个工作日内作出是否核发药品广告批准文号的决定；核发药品广告批准文号的，应当同时报国务院药品监督管理部门备案。具体办法由国务院药品监督管理部门制定。"},{"i":49,"n":"第四十九条","txt":"经国务院或者省、自治区、直辖市人民政府的药品监督管理部门决定，责令暂停生产、销售和使用的药品，在暂停期间不得发布该品种药品广告；已经发布广告的，必须立即停止。"},{"i":50,"n":"第五十条","txt":"未经省、自治区、直辖市人民政府药品监督管理部门批准的药品广告，使用伪造、冒用、失效的药品广告批准文号的广告，或者因其他广告违法活动被撤销药品广告批准文号的广告，发布广告的企业、广告经营者、广告发布者必须立即停止该药品广告的发布。"},{"i":51,"n":"第五十一条","txt":"药品监督管理部门（含省级人民政府药品监督管理部门依法设立的药品监督管理机构，下同）依法对药品的研制、生产、经营、使用实施监督检查。"},{"i":52,"n":"第五十二条","txt":"药品抽样必须由两名以上药品监督检查人员实施，并按照国务院药品监督管理部门的规定进行抽样；被抽检方应当提供抽检样品，不得拒绝。"},{"i":53,"n":"第五十三条","txt":"对有掺杂、掺假嫌疑的药品，在国家药品标准规定的检验方法和检验项目不能检验时，药品检验机构可以补充检验方法和检验项目进行药品检验；经国务院药品监督管理部门批准后，使用补充检验方法和检验项目所得出的检验结果，可以作为药品监督管理部门认定药品质量的依据。"},{"i":54,"n":"第五十四条","txt":"国务院和省、自治区、直辖市人民政府的药品监督管理部门应当根据药品质量抽查检验结果，定期发布药品质量公告。药品质量公告应当包括抽验药品的品名、检品来源、生产企业、生产批号、药品规格、检验机构、检验依据、检验结果、不合格项目等内容。药品质量公告不当的，发布部门应当自确认公告不当之日起5日内，在原公告范围内予以更正。"},{"i":55,"n":"第五十五条","txt":"药品监督管理部门依法对有证据证明可能危害人体健康的药品及其有关证据材料采取查封、扣押的行政强制措施的，应当自采取行政强制措施之日起7日内作出是否立案的决定；需要检验的，应当自检验报告书发出之日起15日内作出是否立案的决定；不符合立案条件的，应当解除行政强制措施；需要暂停销售和使用的，应当由国务院或者省、自治区、直辖市人民政府的药品监督管理部门作出决定。"},{"i":56,"n":"第五十六条","txt":"药品抽查检验，不得收取任何费用。"},{"i":57,"n":"第五十七条","txt":"依据《药品管理法》和本条例的规定核发证书、进行药品注册、药品认证和实施药品审批检验及其强制性检验，可以收取费用。具体收费标准由国务院财政部门、国务院价格主管部门制定。"},{"i":58,"n":"第五十八条","txt":"药品生产企业、药品经营企业有下列情形之一的，由药品监督管理部门依照《药品管理法》第七十九条的规定给予处罚："},{"i":59,"n":"第五十九条","txt":"违反《药品管理法》第十三条的规定，擅自委托或者接受委托生产药品的，对委托方和受托方均依照《药品管理法》第七十四条的规定给予处罚。"},{"i":60,"n":"第六十条","txt":"未经批准，擅自在城乡集市贸易市场设点销售药品或者在城乡集市贸易市场设点销售的药品超出批准经营的药品范围的，依照《药品管理法》第七十三条的规定给予处罚。"},{"i":61,"n":"第六十一条","txt":"未经批准，医疗机构擅自使用其他医疗机构配制的制剂的，依照《药品管理法》第八十条的规定给予处罚。"},{"i":62,"n":"第六十二条","txt":"个人设置的门诊部、诊所等医疗机构向患者提供的药品超出规定的范围和品种的，依照《药品管理法》第七十三条的规定给予处罚。"},{"i":63,"n":"第六十三条","txt":"医疗机构使用假药、劣药的，依照《药品管理法》第七十四条、第七十五条的规定给予处罚。"},{"i":64,"n":"第六十四条","txt":"违反《药品管理法》第二十九条的规定，擅自进行临床试验的，对承担药物临床试验的机构，依照《药品管理法》第七十九条的规定给予处罚。"},{"i":65,"n":"第六十五条","txt":"药品申报者在申报临床试验时，报送虚假研制方法、质量标准、药理及毒理试验结果等有关资料和样品的，国务院药品监督管理部门对该申报药品的临床试验不予批准，对药品申报者给予警告；情节严重的，3年内不受理该药品申报者申报该品种的临床试验申请。"},{"i":66,"n":"第六十六条","txt":"生产没有国家药品标准的中药饮片，不符合省、自治区、直辖市人民政府药品监督管理部门制定的炮制规范的；医疗机构不按照省、自治区、直辖市人民政府药品监督管理部门批准的标准配制制剂的，依照《药品管理法》第七十五条的规定给予处罚。"},{"i":67,"n":"第六十七条","txt":"药品监督管理部门及其工作人员违反规定，泄露生产者、销售者为获得生产、销售含有新型化学成份药品许可而提交的未披露试验数据或者其他数据，造成申请人损失的，由药品监督管理部门依法承担赔偿责任；药品监督管理部门赔偿损失后，应当责令故意或者有重大过失的工作人员承担部分或者全部赔偿费用，并对直接责任人员依法给予行政处分。"},{"i":68,"n":"第六十八条","txt":"药品生产企业、药品经营企业生产、经营的药品及医疗机构配制的制剂，其包装、标签、说明书违反《药品管理法》及本条例规定的，依照《药品管理法》第八十六条的规定给予处罚。"},{"i":69,"n":"第六十九条","txt":"药品生产企业、药品经营企业和医疗机构变更药品生产经营许可事项，应当办理变更登记手续而未办理的，由原发证部门给予警告，责令限期补办变更登记手续；逾期不补办的，宣布其《药品生产许可证》、《药品经营许可证》和《医疗机构制剂许可证》无效；仍从事药品生产经营活动的，依照《药品管理法》第七十三条的规定给予处罚。"},{"i":70,"n":"第七十条","txt":"篡改经批准的药品广告内容的，由药品监督管理部门责令广告主立即停止该药品广告的发布，并由原审批的药品监督管理部门依照《药品管理法》第九十二条的规定给予处罚。"},{"i":71,"n":"第七十一条","txt":"发布药品广告的企业在药品生产企业所在地或者进口药品代理机构所在地以外的省、自治区、直辖市发布药品广告，未按照规定向发布地省、自治区、直辖市人民政府药品监督管理部门备案的，由发布地的药品监督管理部门责令限期改正；逾期不改正的，停止该药品品种在发布地的广告发布活动。"},{"i":72,"n":"第七十二条","txt":"未经省、自治区、直辖市人民政府药品监督管理部门批准，擅自发布药品广告的，药品监督管理部门发现后，应当通知广告监督管理部门依法查处。"},{"i":73,"n":"第七十三条","txt":"违反《药品管理法》和本条例的规定，有下列行为之一的，由药品监督管理部门在《药品管理法》和本条例规定的处罚幅度内从重处罚："},{"i":74,"n":"第七十四条","txt":"药品监督管理部门设置的派出机构，有权作出《药品管理法》和本条例规定的警告、罚款、没收违法生产、销售的药品和违法所得的行政处罚。"},{"i":75,"n":"第七十五条","txt":"药品经营企业、医疗机构未违反《药品管理法》和本条例的有关规定，并有充分证据证明其不知道所销售或者使用的药品是假药、劣药的，应当没收其销售或者使用的假药、劣药和违法所得；但是，可以免除其他行政处罚。"},{"i":76,"n":"第七十六条","txt":"依照《药品管理法》和本条例的规定没收的物品，由药品监督管理部门按照规定监督处理。"},{"i":77,"n":"第七十七条","txt":"本条例下列用语的含义："},{"i":78,"n":"第七十八条","txt":"《药品管理法》第四十一条中“首次在中国销售的药品”，是指国内或者国外药品生产企业第一次在中国销售的药品，包括不同药品生产企业生产的相同品种。"},{"i":79,"n":"第七十九条","txt":"《药品管理法》第五十九条第二款“禁止药品的生产企业、经营企业或者其代理人以任何名义给予使用其药品的医疗机构的负责人、药品采购人员、医师等有关人员以财物或者其他利益”中的“财物或者其他利益”，是指药品的生产企业、经营企业或者其代理人向医疗机构的负责人、药品采购人员、医师等有关人员提供的目的在于影响其药品采购或者药品处方行为的不正当利益。"},{"i":80,"n":"第八十条","txt":"本条例自2002年9月15日起施行。"}],"zhuzuoquanfashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国著作权法》（以下简称著作权法），制定本条例。"},{"i":2,"n":"第二条","txt":"著作权法所称作品，是指文学、艺术和科学领域内具有独创性并能以某种有形形式复制的智力成果。"},{"i":3,"n":"第三条","txt":"著作权法所称创作，是指直接产生文学、艺术和科学作品的智力活动。"},{"i":4,"n":"第四条","txt":"著作权法和本条例中下列作品的含义："},{"i":5,"n":"第五条","txt":"著作权法和本条例中下列用语的含义："},{"i":6,"n":"第六条","txt":"著作权自作品创作完成之日起产生。"},{"i":7,"n":"第七条","txt":"著作权法第二条第三款规定的首先在中国境内出版的外国人、无国籍人的作品，其著作权自首次出版之日起受保护。"},{"i":8,"n":"第八条","txt":"外国人、无国籍人的作品在中国境外首先出版后，30日内在中国境内出版的，视为该作品同时在中国境内出版。"},{"i":9,"n":"第九条","txt":"合作作品不可以分割使用的，其著作权由各合作作者共同享有，通过协商一致行使；不能协商一致，又无正当理由的，任何一方不得阻止他方行使除转让以外的其他权利，但是所得收益应当合理分配给所有合作作者。"},{"i":10,"n":"第十条","txt":"著作权人许可他人将其作品摄制成电影作品和以类似摄制电影的方法创作的作品的，视为已同意对其作品进行必要的改动，但是这种改动不得歪曲篡改原作品。"},{"i":11,"n":"第十一条","txt":"著作权法第十六条第一款关于职务作品的规定中的“工作任务”，是指公民在该法人或者该组织中应当履行的职责。"},{"i":12,"n":"第十二条","txt":"职务作品完成两年内，经单位同意，作者许可第三人以与单位使用的相同方式使用作品所获报酬，由作者与单位按约定的比例分配。"},{"i":13,"n":"第十三条","txt":"作者身份不明的作品，由作品原件的所有人行使除署名权以外的著作权。作者身份确定后，由作者或者其继承人行使著作权。"},{"i":14,"n":"第十四条","txt":"合作作者之一死亡后，其对合作作品享有的著作权法第十条第一款第五项至第十七项规定的权利无人继承又无人受遗赠的，由其他合作作者享有。"},{"i":15,"n":"第十五条","txt":"作者死亡后，其著作权中的署名权、修改权和保护作品完整权由作者的继承人或者受遗赠人保护。"},{"i":16,"n":"第十六条","txt":"国家享有著作权的作品的使用，由国务院著作权行政管理部门管理。"},{"i":17,"n":"第十七条","txt":"作者生前未发表的作品，如果作者未明确表示不发表，作者死亡后50年内，其发表权可由继承人或者受遗赠人行使；没有继承人又无人受遗赠的，由作品原件的所有人行使。"},{"i":18,"n":"第十八条","txt":"作者身份不明的作品，其著作权法第十条第一款第五项至第十七项规定的权利的保护期截止于作品首次发表后第50年的12月31日。作者身份确定后，适用著作权法第二十一条的规定。"},{"i":19,"n":"第十九条","txt":"使用他人作品的，应当指明作者姓名、作品名称；但是，当事人另有约定或者由于作品使用方式的特性无法指明的除外。"},{"i":20,"n":"第二十条","txt":"著作权法所称已经发表的作品，是指著作权人自行或者许可他人公之于众的作品。"},{"i":21,"n":"第二十一条","txt":"依照著作权法有关规定，使用可以不经著作权人许可的已经发表的作品的，不得影响该作品的正常使用，也不得不合理地损害著作权人的合法利益。"},{"i":22,"n":"第二十二条","txt":"依照著作权法第二十三条、第三十三条第二款、第四十条第三款的规定使用作品的付酬标准，由国务院著作权行政管理部门会同国务院价格主管部门制定、公布。"},{"i":23,"n":"第二十三条","txt":"使用他人作品应当同著作权人订立许可使用合同，许可使用的权利是专有使用权的，应当采取书面形式，但是报社、期刊社刊登作品除外。"},{"i":24,"n":"第二十四条","txt":"著作权法第二十四条规定的专有使用权的内容由合同约定，合同没有约定或者约定不明的，视为被许可人有权排除包括著作权人在内的任何人以同样的方式使用作品；除合同另有约定外，被许可人许可第三人行使同一权利，必须取得著作权人的许可。"},{"i":25,"n":"第二十五条","txt":"与著作权人订立专有许可使用合同、转让合同的，可以向著作权行政管理部门备案。"},{"i":26,"n":"第二十六条","txt":"著作权法和本条例所称与著作权有关的权益，是指出版者对其出版的图书和期刊的版式设计享有的权利，表演者对其表演享有的权利，录音录像制作者对其制作的录音录像制品享有的权利，广播电台、电视台对其播放的广播、电视节目享有的权利。"},{"i":27,"n":"第二十七条","txt":"出版者、表演者、录音录像制作者、广播电台、电视台行使权利，不得损害被使用作品和原作品著作权人的权利。"},{"i":28,"n":"第二十八条","txt":"图书出版合同中约定图书出版者享有专有出版权但没有明确其具体内容的，视为图书出版者享有在合同有效期限内和在合同约定的地域范围内以同种文字的原版、修订版出版图书的专有权利。"},{"i":29,"n":"第二十九条","txt":"著作权人寄给图书出版者的两份订单在6个月内未能得到履行，视为著作权法第三十二条所称图书脱销。"},{"i":30,"n":"第三十条","txt":"著作权人依照著作权法第三十三条第二款声明不得转载、摘编其作品的，应当在报纸、期刊刊登该作品时附带声明。"},{"i":31,"n":"第三十一条","txt":"著作权人依照著作权法第四十条第三款声明不得对其作品制作录音制品的，应当在该作品合法录制为录音制品时声明。"},{"i":32,"n":"第三十二条","txt":"依照著作权法第二十三条、第三十三条第二款、第四十条第三款的规定，使用他人作品的，应当自使用该作品之日起2个月内向著作权人支付报酬。"},{"i":33,"n":"第三十三条","txt":"外国人、无国籍人在中国境内的表演，受著作权法保护。"},{"i":34,"n":"第三十四条","txt":"外国人、无国籍人在中国境内制作、发行的录音制品，受著作权法保护。"},{"i":35,"n":"第三十五条","txt":"外国的广播电台、电视台根据中国参加的国际条约对其播放的广播、电视节目享有的权利，受著作权法保护。"},{"i":36,"n":"第三十六条","txt":"有著作权法第四十八条所列侵权行为，同时损害社会公共利益，非法经营额5万元以上的，著作权行政管理部门可处非法经营额1倍以上5倍以下的罚款；没有非法经营额或者非法经营额5万元以下的，著作权行政管理部门根据情节轻重，可处25万元以下的罚款。"},{"i":37,"n":"第三十七条","txt":"有著作权法第四十八条所列侵权行为，同时损害社会公共利益的，由地方人民政府著作权行政管理部门负责查处。"},{"i":38,"n":"第三十八条","txt":"本条例自2002年9月15日起施行。1991年5月24日国务院批准、1991年5月30日国家版权局发布的《中华人民共和国著作权法实施条例》同时废止。"}],"xingzhengfuyifashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国行政复议法》（以下简称行政复议法），制定本条例。"},{"i":2,"n":"第二条","txt":"行政复议机关应当对行政行为的合法性、适当性进行全面审查，保护公民、法人和其他组织的合法权益，监督和保障行政机关依法行使职权，推动行政争议实质性化解，促进从源头上预防和减少行政争议。"},{"i":3,"n":"第三条","txt":"各级行政复议机关应当认真履行行政复议职责，领导并支持本机关行政复议机构依法办理行政复议事项，依照有关规定配备、充实、调剂专职行政复议人员，保证行政复议机构的办案能力与工作任务相适应。"},{"i":4,"n":"第四条","txt":"行政复议机构依照行政复议法和本条例的规定，履行下列职责："},{"i":5,"n":"第五条","txt":"行政复议人员应当具备与履行行政复议职责相适应的政治、业务素质和道德品行。"},{"i":6,"n":"第六条","txt":"行政复议机关应当加强行政复议调解工作，支持和保障行政复议机构依法开展调解工作，有关行政机关应当予以配合。"},{"i":7,"n":"第七条","txt":"行政复议机关应当加强行政复议工作规范化建设，提升行政复议工作流程、保障等规范化水平。具体规范由国务院行政复议机构会同国务院有关部门制定。"},{"i":8,"n":"第八条","txt":"国务院行政复议机构通过统一的行政复议信息化平台，为公民、法人或者其他组织申请、参加行政复议提供便利，提高行政复议工作质效。"},{"i":9,"n":"第九条","txt":"行政复议法第十一条第十五项规定的行政复议范围包括下列情形："},{"i":10,"n":"第十条","txt":"行政复议法第十一条第十三项规定的行政协议包括下列协议："},{"i":11,"n":"第十一条","txt":"行政复议法和本条例所称的近亲属，包括配偶、父母、子女、兄弟姐妹、祖父母、外祖父母、孙子女、外孙子女和其他具有扶养、赡养关系的亲属。"},{"i":12,"n":"第十二条","txt":"个体工商户申请行政复议的，以营业执照上登记的经营者为申请人。"},{"i":13,"n":"第十三条","txt":"合伙企业申请行政复议的，应当以依法登记的企业为申请人，由执行合伙事务的合伙人代表该企业参加行政复议；其他合伙组织申请行政复议的，由全体合伙人共同申请行政复议。"},{"i":14,"n":"第十四条","txt":"公司股东会、董事会认为行政机关作出的行政行为侵犯公司合法权益的，可以以公司的名义申请行政复议。"},{"i":15,"n":"第十五条","txt":"农村集体经济组织或者依法代行农村集体经济组织职能的村民委员会、村民小组认为行政机关作出的行政行为侵犯农村集体经济组织合法权益的，可以以自己的名义申请行政复议。"},{"i":16,"n":"第十六条","txt":"业主委员会认为行政机关作出的行政行为侵犯业主共有利益的，可以以自己的名义申请行政复议。"},{"i":17,"n":"第十七条","txt":"同一行政复议案件申请人超过10人的，推选2至5名代表人参加行政复议。"},{"i":18,"n":"第十八条","txt":"行政复议法第十七条第一款规定的其他代理人，包括申请人或者第三人的近亲属、工作人员等。"},{"i":19,"n":"第十九条","txt":"符合法律援助条件的行政复议申请人申请法律援助的，应当向行政复议机构所在地或者行政争议发生地的法律援助机构提出申请。"},{"i":20,"n":"第二十条","txt":"行政机关与法律、法规、规章授权的组织以共同的名义作出同一行政行为的，共同作出行政行为的行政机关和法律、法规、规章授权的组织为共同被申请人。"},{"i":21,"n":"第二十一条","txt":"行政机关设立的派出机构、内设机构或者其他组织，未经法律、法规、规章授权，对外以自己名义作出行政行为的，该行政机关为被申请人。"},{"i":22,"n":"第二十二条","txt":"法律、法规、规章授权的组织根据授权作出行政行为的，该组织为被申请人。"},{"i":23,"n":"第二十三条","txt":"行政复议法第二十条第一款规定的行政复议申请期限的计算，依照下列规定办理："},{"i":24,"n":"第二十四条","txt":"公民、法人或者其他组织依照行政复议法第十一条第三项、第十一项、第十二项的规定申请行政机关履行法定职责，行政机关未履行的，行政复议申请期限依照下列规定计算："},{"i":25,"n":"第二十五条","txt":"行政机关作出的行政行为对公民、法人或者其他组织的权利、义务可能产生不利影响的，应当告知其申请行政复议的权利、行政复议机关和行政复议申请期限。"},{"i":26,"n":"第二十六条","txt":"行政机关未依照行政复议法第二十三条规定告知公民、法人或者其他组织先向行政复议机关申请行政复议，公民、法人或者其他组织未经行政复议直接向人民法院提起行政诉讼的，自公民、法人或者其他组织提起行政诉讼之日至人民法院驳回起诉裁定送达之日的期间不计入行政复议申请期限。"},{"i":27,"n":"第二十七条","txt":"公民、法人或者其他组织书面申请行政复议的，应当在行政复议申请书中载明下列事项，签名、盖章或者按指印，并提交身份证明材料："},{"i":28,"n":"第二十八条","txt":"申请人通过行政复议机关指定的互联网渠道申请行政复议的，行政复议申请材料到达特定系统之日，为行政复议机关收到行政复议申请之日。"},{"i":29,"n":"第二十九条","txt":"申请人提出行政复议申请时错列被申请人的，行政复议机构应当告知申请人变更被申请人。申请人不同意变更或者变更后所列被申请人仍不符合规定的，行政复议机关决定不予受理并说明理由。"},{"i":30,"n":"第三十条","txt":"行政复议法第二十三条第一款第三项规定的行政机关未履行法定职责，是指申请人向行政机关申请履行相应法定职责，该行政机关存在行政复议法第十一条第三项、第十一项、第十二项、第十四项规定的在法定期限内未受理、受理后不予答复或者不履行相应法定职责的情形。"},{"i":31,"n":"第三十一条","txt":"对行政机关认为申请公开的政府信息属于《中华人民共和国政府信息公开条例》第十四条、第十五条、第十六条规定的情形，决定全部或者部分不予公开的行为不服的，应当依照行政复议法第二十三条的规定先向行政复议机关申请行政复议，对行政复议决定不服的，可以再依法向人民法院提起行政诉讼。"},{"i":32,"n":"第三十二条","txt":"对两个以上国务院部门共同作出的行政行为不服的，依照行政复议法第二十五条的规定，可以向其中任何一个国务院部门申请行政复议，由作出行政行为的国务院部门共同作出行政复议决定。"},{"i":33,"n":"第三十三条","txt":"对行政机关设立的内设机构经法律、法规、规章授权，以自己名义作出的行政行为不服的，向设立该机构的行政机关申请行政复议；该行政机关不具有行政复议职责的，向对该行政机关有管辖权的行政复议机关申请行政复议。"},{"i":34,"n":"第三十四条","txt":"公民、法人或者其他组织认为行政机关的行政行为侵犯其合法权益提出行政复议申请，除不符合行政复议法和本条例规定的受理条件的，行政复议机关必须受理。"},{"i":35,"n":"第三十五条","txt":"行政复议法第三十条第一款第二项规定的申请人与被申请行政复议的行政行为有利害关系包括下列情形："},{"i":36,"n":"第三十六条","txt":"公民、法人或者其他组织就下列事项申请行政复议的，行政复议机关不予受理："},{"i":37,"n":"第三十七条","txt":"行政复议申请有下列情形之一，行政复议机关已经受理的，应当决定驳回行政复议申请："},{"i":38,"n":"第三十八条","txt":"作出行政处罚决定的行政机关收到申请人依照行政复议法第三十二条规定提交的行政复议申请后，认为行政处罚决定违法或者不当，需要自行纠正的，应当自收到行政复议申请之日起5个工作日内按照法定程序，采取撤销、变更行政处罚决定等方式予以纠正，并将有关情况告知申请人和行政复议机关。"},{"i":39,"n":"第三十九条","txt":"行政复议机关审理行政复议案件，应当由2名以上行政复议人员参加。适用简易程序的，可以由1名行政复议人员审理。"},{"i":40,"n":"第四十条","txt":"上级行政复议机关对下级行政复议机关管辖的行政复议案件，认为属于下列情形之一的，可以决定提级审理："},{"i":41,"n":"第四十一条","txt":"被申请人提交书面答复时，应当就行政行为合法性、适当性和申请人的行政复议请求说明相关事实和理由。"},{"i":42,"n":"第四十二条","txt":"依照行政复议法第二十四条第二款、第二十五条第一项的规定申请原级行政复议的案件，由原承办行政行为有关事项的部门或者机构提出书面答复，并提交作出行政行为的证据、依据和其他有关材料。"},{"i":43,"n":"第四十三条","txt":"因同一行政行为或者同类行政行为发生的行政复议案件，有下列情形之一的，行政复议机关可以决定合并审理："},{"i":44,"n":"第四十四条","txt":"行政复议机构认为有必要的，可以就案件相关事实当面询问当事人和其他有关人员。"},{"i":45,"n":"第四十五条","txt":"行政复议期间需要现场勘验的，有关单位、人员应当予以配合，现场勘验所用时间不计入行政复议审理期限。"},{"i":46,"n":"第四十六条","txt":"行政复议期间涉及专门事项需要鉴定的，当事人可以申请行政复议机构委托鉴定机构进行鉴定。行政复议机构审查同意的，组织当事人协商确定具备相应资格的鉴定机构；协商不成的，由行政复议机构指定。鉴定费用由当事人承担。鉴定所用时间不计入行政复议审理期限。"},{"i":47,"n":"第四十七条","txt":"被申请人有证据证明其在行政程序中依法要求申请人或者第三人提供证据，申请人或者第三人无正当理由未予提供，但在行政复议程序中提供的证据，行政复议机关不予采纳。"},{"i":48,"n":"第四十八条","txt":"当事人在调解过程中对协商条件、方案等所作的认可，不得在其后行政复议案件审理过程中作为对其不利的证据。"},{"i":49,"n":"第四十九条","txt":"行政复议机关应当为申请人、第三人及其委托代理人查阅、复制有关材料提供必要条件。"},{"i":50,"n":"第五十条","txt":"县级以上地方人民政府行政复议委员会由本级人民政府有关部门、专家、学者等共同组成，可设主任、副主任，由本级人民政府、本级行政复议机构负责人等担任。"},{"i":51,"n":"第五十一条","txt":"行政复议委员会通过召开行政复议委员会全体会议、案件咨询会议等形式履行相关职责。"},{"i":52,"n":"第五十二条","txt":"提请行政复议委员会提出咨询意见的行政复议案件，行政复议机构报请行政复议机关签发行政复议决定时，应当附具行政复议委员会咨询意见，并对行政复议委员会咨询意见的采纳情况作出说明；不采纳行政复议委员会咨询意见的，应当说明理由。"},{"i":53,"n":"第五十三条","txt":"申请人在对行政行为提出行政复议申请时尚不知道该行政行为所依据的规范性文件的，可以在行政复议机关作出行政复议决定前向行政复议机关提出对该规范性文件的附带审查申请。"},{"i":54,"n":"第五十四条","txt":"行政复议法第五十九条规定的规范性文件或者依据的相关条款超越权限或者违反上位法包括下列情形："},{"i":55,"n":"第五十五条","txt":"行政复议法第六十三条第一款第一项规定的内容不适当包括下列情形："},{"i":56,"n":"第五十六条","txt":"行政复议法第六十三条第一款第二项规定的未正确适用依据包括下列情形："},{"i":57,"n":"第五十七条","txt":"行政复议法第六十四条第一款第三项规定的适用的依据不合法包括下列情形："},{"i":58,"n":"第五十八条","txt":"行政复议机关依照行政复议法第六十四条第一款的规定责令被申请人重新作出行政行为的，被申请人应当在法律、法规、规章规定的期限内重新作出行政行为；法律、法规、规章未规定期限的，重新作出行政行为的期限为60日。"},{"i":59,"n":"第五十九条","txt":"行政复议法第六十五条第一款第二项规定的程序轻微违法包括对申请人依法享有的陈述、申辩等重要程序性权利不产生实际影响的下列情形："},{"i":60,"n":"第六十条","txt":"行政复议法第六十七条规定的重大且明显违法包括下列情形："},{"i":61,"n":"第六十一条","txt":"有下列情形之一的，行政复议机关应当决定驳回申请人的行政复议请求："},{"i":62,"n":"第六十二条","txt":"行政复议机关审理行政协议复议案件，根据行政复议法第七十一条规定的情形，作出如下决定："},{"i":63,"n":"第六十三条","txt":"行政复议机关审理行政赔偿复议案件，对于应当赔偿且能够确定赔偿方式的，应当作出具有明确赔偿内容的行政复议决定。"},{"i":64,"n":"第六十四条","txt":"有下列情形之一的，行政复议机关决定驳回申请人行政赔偿请求："},{"i":65,"n":"第六十五条","txt":"行政复议机关作出行政复议决定后，申请人以外的公民、法人或者其他组织就同一行政行为或者同样行政行为申请行政复议且符合受理条件的，行政复议机关可以在受理后根据发生法律效力的行政复议决定的内容，直接作出行政复议决定。"},{"i":66,"n":"第六十六条","txt":"县级以上地方各级人民政府应当建立健全行政复议工作责任制，支持和保障行政复议机构依法履行职责，将行政复议工作纳入本级政府目标责任制。"},{"i":67,"n":"第六十七条","txt":"县级以上地方各级人民政府应当按照职责权限，通过定期组织检查、抽查等方式，对下级人民政府行政复议工作进行检查，并及时反馈检查结果。重大事项及时按照有关规定请示报告。"},{"i":68,"n":"第六十八条","txt":"行政复议机关应当采取有效措施，支持和保障行政复议人员依法履职办案。"},{"i":69,"n":"第六十九条","txt":"行政复议机构在行政复议工作中发现法律、法规、规章、规范性文件实施中带有普遍性的问题，可以制作行政复议建议书，向有关机关提出完善制度和改进行政执法的建议。"},{"i":70,"n":"第七十条","txt":"各级行政复议机构应当定期对行政复议人员进行政治、理论和业务培训，提高行政复议人员的能力素质。"},{"i":71,"n":"第七十一条","txt":"被申请人在规定期限内未按照行政复议决定的要求重新作出行政行为，或者违反规定重新作出行政行为的，依照行政复议法第八十三条的规定追究法律责任。"},{"i":72,"n":"第七十二条","txt":"对行政复议人员及其近亲属实施报复陷害、侮辱诽谤、暴力侵害、威胁恐吓、滋事骚扰等违法行为的，依法给予处分、治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":73,"n":"第七十三条","txt":"加强行政复议与监察监督的贯通协同，健全信息共享和线索移送机制。"},{"i":74,"n":"第七十四条","txt":"公民、法人或者其他组织对行政机关作出的驳回商标申请、驳回专利申请等行为不服申请行政复议的，依照《中华人民共和国商标法》、《中华人民共和国专利法》的有关规定提出复审请求。"},{"i":75,"n":"第七十五条","txt":"公民、法人或者其他组织对海警机构的行政行为不服的，依法向上一级海警机构申请行政复议。"},{"i":76,"n":"第七十六条","txt":"行政复议机关审理行政复议案件，参照国务院行政复议机构发布的行政复议指导性案例。"},{"i":77,"n":"第七十七条","txt":"本条例自2026年7月1日起施行。"}],"jiliangfashishixize":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国计量法》的规定，制定本细则。"},{"i":2,"n":"第二条","txt":"国家实行法定计量单位制度。法定计量单位的名称、符号按照国务院关于在我国统一实行法定计量单位的有关规定执行。"},{"i":3,"n":"第三条","txt":"国家有计划地发展计量事业，用现代计量技术装备各级计量检定机构，为社会主义现代化建设服务，为工农业生产、国防建设、科学实验、国内外贸易以及人民的健康、安全提供计量保证，维护国家和人民的利益。"},{"i":4,"n":"第四条","txt":"计量基准器具（简称计量基准，下同）的使用必须具备下列条件："},{"i":5,"n":"第五条","txt":"非经国务院计量行政部门批准，任何单位和个人不得拆卸、改装计量基准，或者自行中断其计量检定工作。"},{"i":6,"n":"第六条","txt":"计量基准的量值应当与国际上的量值保持一致。国务院计量行政部门有权废除技术水平落后或者工作状况不适应需要的计量基准。"},{"i":7,"n":"第七条","txt":"计量标准器具（简称计量标准，下同）的使用，必须具备下列条件："},{"i":8,"n":"第八条","txt":"社会公用计量标准对社会上实施计量监督具有公证作用。县级以上地方人民政府计量行政部门建立的本行政区域内最高等级的社会公用计量标准，须向上一级人民政府计量行政部门申请考核；其他等级的，由当地人民政府计量行政部门主持考核。"},{"i":9,"n":"第九条","txt":"国务院有关主管部门和省、自治区、直辖市人民政府有关主管部门建立的本部门各项最高计量标准，经同级人民政府计量行政部门考核，符合本细则第七条规定条件并取得考核合格证的，由有关主管部门批准使用。"},{"i":10,"n":"第十条","txt":"企业、事业单位建立本单位各项最高计量标准，须向与其主管部门同级的人民政府计量行政部门申请考核。乡镇企业向当地县级人民政府计量行政部门申请考核。经考核符合本细则第七条规定条件并取得考核合格证的，企业、事业单位方可使用，并向其主管部门备案。"},{"i":11,"n":"第十一条","txt":"使用实行强制检定的计量标准的单位和个人，应当向主持考核该项计量标准的有关人民政府计量行政部门申请周期检定。"},{"i":12,"n":"第十二条","txt":"企业、事业单位应当配备与生产、科研、经营管理相适应的计量检测设施，制定具体的检定管理办法和规章制度，规定本单位管理的计量器具明细目录及相应的检定周期，保证使用的非强制检定的计量器具定期检定。"},{"i":13,"n":"第十三条","txt":"计量检定工作应当符合经济合理、就地就近的原则，不受行政区划和部门管辖的限制。"},{"i":14,"n":"第十四条","txt":"制造、修理计量器具的企业、事业单位和个体工商户须在固定的场所从事经营，具有符合国家规定的生产设施、检验条件、技术人员等，并满足安全要求。"},{"i":15,"n":"第十五条","txt":"凡制造在全国范围内从未生产过的计量器具新产品，必须经过定型鉴定。定型鉴定合格后，应当履行型式批准手续，颁发证书。在全国范围内已经定型，而本单位未生产过的计量器具新产品，应当进行样机试验。样机试验合格后，发给合格证书。凡未经型式批准或者未取得样机试验合格证书的计量器具，不准生产。"},{"i":16,"n":"第十六条","txt":"计量器具新产品定型鉴定，由国务院计量行政部门授权的技术机构进行；样机试验由所在地方的省级人民政府计量行政部门授权的技术机构进行。"},{"i":17,"n":"第十七条","txt":"申请计量器具新产品定型鉴定和样机试验的单位，应当提供新产品样机及有关技术文件、资料。"},{"i":18,"n":"第十八条","txt":"对企业、事业单位制造、修理计量器具的质量，各有关主管部门应当加强管理，县级以上人民政府计量行政部门有权进行监督检查，包括抽检和监督试验。凡无产品合格印、证，或者经检定不合格的计量器具，不准出厂。"},{"i":19,"n":"第十九条","txt":"外商在中国销售计量器具，须比照本细则第十五条的规定向国务院计量行政部门申请型式批准。"},{"i":20,"n":"第二十条","txt":"县级以上地方人民政府计量行政部门对当地销售的计量器具实施监督检查。凡没有产品合格印、证标志的计量器具不得销售。"},{"i":21,"n":"第二十一条","txt":"任何单位和个人不得经营销售残次计量器具零配件，不得使用残次零配件组装和修理计量器具。"},{"i":22,"n":"第二十二条","txt":"任何单位和个人不准在工作岗位上使用无检定合格印、证或者超过检定周期以及经检定不合格的计量器具。在教学示范中使用计量器具不受此限。"},{"i":23,"n":"第二十三条","txt":"国务院计量行政部门和县级以上地方人民政府计量行政部门监督和贯彻实施计量法律、法规的职责是："},{"i":24,"n":"第二十四条","txt":"县级以上人民政府计量行政部门的计量管理人员，负责执行计量监督、管理任务；计量监督员负责在规定的区域、场所巡回检查，并可根据不同情况在规定的权限内对违反计量法律、法规的行为，进行现场处理，执行行政处罚。"},{"i":25,"n":"第二十五条","txt":"县级以上人民政府计量行政部门依法设置的计量检定机构，为国家法定计量检定机构。其职责是：负责研究建立计量基准、社会公用计量标准，进行量值传递，执行强制检定和法律规定的其他检定、测试任务，起草技术规范，为实施计量监督提供技术保证，并承办有关计量监督工作。"},{"i":26,"n":"第二十六条","txt":"国家法定计量检定机构的计量检定人员，必须经考核合格。"},{"i":27,"n":"第二十七条","txt":"县级以上人民政府计量行政部门可以根据需要，采取以下形式授权其他单位的计量检定机构和技术机构，在规定的范围内执行强制检定和其他检定、测试任务："},{"i":28,"n":"第二十八条","txt":"根据本细则第二十七条规定被授权的单位，应当遵守下列规定："},{"i":29,"n":"第二十九条","txt":"为社会提供公证数据的产品质量检验机构，必须经省级以上人民政府计量行政部门计量认证。"},{"i":30,"n":"第三十条","txt":"产品质量检验机构计量认证的内容："},{"i":31,"n":"第三十一条","txt":"产品质量检验机构提出计量认证申请后，省级以上人民政府计量行政部门应指定所属的计量检定机构或者被授权的技术机构按照本细则第三十条规定的内容进行考核。考核合格后，由接受申请的省级以上人民政府计量行政部门发给计量认证合格证书。产品质量检验机构自愿签署告知承诺书并按要求提交材料的，按照告知承诺相关程序办理。未取得计量认证合格证书的，不得开展产品质量检验工作。"},{"i":32,"n":"第三十二条","txt":"省级以上人民政府计量行政部门有权对计量认证合格的产品质量检验机构，按照本细则第三十条规定的内容进行监督检查。"},{"i":33,"n":"第三十三条","txt":"已经取得计量认证合格证书的产品质量检验机构，需新增检验项目时，应按照本细则有关规定，申请单项计量认证。"},{"i":34,"n":"第三十四条","txt":"县级以上人民政府计量行政部门负责计量纠纷的调解和仲裁检定，并可根据司法机关、合同管理机关、涉外仲裁机关或者其他单位的委托，指定有关计量检定机构进行仲裁检定。"},{"i":35,"n":"第三十五条","txt":"在调解、仲裁及案件审理过程中，任何一方当事人均不得改变与计量纠纷有关的计量器具的技术状态。"},{"i":36,"n":"第三十六条","txt":"计量纠纷当事人对仲裁检定不服的，可以在接到仲裁检定通知书之日起15日内向上一级人民政府计量行政部门申诉。上一级人民政府计量行政部门进行的仲裁检定为终局仲裁检定。"},{"i":37,"n":"第三十七条","txt":"建立计量标准申请考核，使用计量器具申请检定，制造计量器具新产品申请定型和样机试验，以及申请计量认证和仲裁检定，应当缴纳费用，具体收费办法或收费标准，由国务院计量行政部门会同国家财政、物价部门统一制定。"},{"i":38,"n":"第三十八条","txt":"县级以上人民政府计量行政部门实施监督检查所进行的检定和试验不收费。被检查的单位有提供样机和检定试验条件的义务。"},{"i":39,"n":"第三十九条","txt":"县级以上人民政府计量行政部门所属的计量检定机构，为贯彻计量法律、法规，实施计量监督提供技术保证所需要的经费，按照国家财政管理体制的规定，分别列入各级财政预算。"},{"i":40,"n":"第四十条","txt":"违反本细则第二条规定，使用非法定计量单位的，责令其改正；属出版物的，责令其停止销售，可并处1000元以下的罚款。"},{"i":41,"n":"第四十一条","txt":"违反《中华人民共和国计量法》第十四条规定，制造、销售和进口非法定计量单位的计量器具的，责令其停止制造、销售和进口，没收计量器具和全部违法所得，可并处相当其违法所得10%至50%的罚款。"},{"i":42,"n":"第四十二条","txt":"部门和企业、事业单位的各项最高计量标准，未经有关人民政府计量行政部门考核合格而开展计量检定的，责令其停止使用，可并处1000元以下的罚款。"},{"i":43,"n":"第四十三条","txt":"属于强制检定范围的计量器具，未按照规定申请检定和属于非强制检定范围的计量器具未自行定期检定或者送其他计量检定机构定期检定的，以及经检定不合格继续使用的，责令其停止使用，可并处1000元以下的罚款。"},{"i":44,"n":"第四十四条","txt":"制造、销售未经型式批准或样机试验合格的计量器具新产品的，责令其停止制造、销售，封存该种新产品，没收全部违法所得，可并处3000元以下的罚款。"},{"i":45,"n":"第四十五条","txt":"制造、修理的计量器具未经出厂检定或者经检定不合格而出厂的，责令其停止出厂，没收全部违法所得；情节严重的，可并处3000元以下的罚款。"},{"i":46,"n":"第四十六条","txt":"使用不合格计量器具或者破坏计量器具准确度和伪造数据，给国家和消费者造成损失的，责令其赔偿损失，没收计量器具和全部违法所得，可并处2000元以下的罚款。"},{"i":47,"n":"第四十七条","txt":"经营销售残次计量器具零配件的，责令其停止经营销售，没收残次计量器具零配件和全部违法所得，可并处2000元以下的罚款；情节严重的，由工商行政管理部门吊销其营业执照。"},{"i":48,"n":"第四十八条","txt":"制造、销售、使用以欺骗消费者为目的的计量器具的单位和个人，没收其计量器具和全部违法所得，可并处2000元以下的罚款；构成犯罪的，对个人或者单位直接责任人员，依法追究刑事责任。"},{"i":49,"n":"第四十九条","txt":"个体工商户制造、修理国家规定范围以外的计量器具或者不按照规定场所从事经营活动的，责令其停止制造、修理，没收全部违法所得，可并处以500元以下的罚款。"},{"i":50,"n":"第五十条","txt":"未取得计量认证合格证书的产品质量检验机构，为社会提供公证数据的，责令其停止检验，可并处1000元以下的罚款。"},{"i":51,"n":"第五十一条","txt":"伪造、盗用、倒卖强制检定印、证的，没收其非法检定印、证和全部违法所得，可并处2000元以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":52,"n":"第五十二条","txt":"计量监督管理人员违法失职，徇私舞弊，情节轻微的，给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":53,"n":"第五十三条","txt":"负责计量器具新产品定型鉴定、样机试验的单位，违反本细则第十七条第二款规定的，应当按照国家有关规定，赔偿申请单位的损失，并给予直接责任人员行政处分；构成犯罪的，依法追究刑事责任。"},{"i":54,"n":"第五十四条","txt":"计量检定人员有下列行为之一的，给予行政处分；构成犯罪的，依法追究刑事责任："},{"i":55,"n":"第五十五条","txt":"本细则规定的行政处罚，由县级以上地方人民政府计量行政部门决定。罚款1万元以上的，应当报省级人民政府计量行政部门决定。没收违法所得及罚款一律上缴国库。"},{"i":56,"n":"第五十六条","txt":"本细则下列用语的含义是："},{"i":57,"n":"第五十七条","txt":"中国人民解放军和国防科技工业系统涉及本系统以外的计量工作的监督管理，亦适用本细则。"},{"i":58,"n":"第五十八条","txt":"本细则有关的管理办法、管理范围和各种印、证标志，由国务院计量行政部门制定。"},{"i":59,"n":"第五十九条","txt":"本细则由国务院计量行政部门负责解释。"},{"i":60,"n":"第六十条","txt":"本细则自发布之日起施行。"}],"chechuanshuifashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国车船税法》（以下简称车船税法）的规定，制定本条例。"},{"i":2,"n":"第二条","txt":"车船税法第一条所称车辆、船舶，是指："},{"i":3,"n":"第三条","txt":"省、自治区、直辖市人民政府根据车船税法所附《车船税税目税额表》确定车辆具体适用税额，应当遵循以下原则："},{"i":4,"n":"第四条","txt":"机动船舶具体适用税额为："},{"i":5,"n":"第五条","txt":"游艇具体适用税额为："},{"i":6,"n":"第六条","txt":"车船税法和本条例所涉及的排气量、整备质量、核定载客人数、净吨位、千瓦、艇身长度，以车船登记管理部门核发的车船登记证书或者行驶证所载数据为准。"},{"i":7,"n":"第七条","txt":"车船税法第三条第一项所称的捕捞、养殖渔船，是指在渔业船舶登记管理部门登记为捕捞船或者养殖船的船舶。"},{"i":8,"n":"第八条","txt":"车船税法第三条第二项所称的军队、武装警察部队专用的车船，是指按照规定在军队、武装警察部队车船登记管理部门登记，并领取军队、武警牌照的车船。"},{"i":9,"n":"第九条","txt":"车船税法第三条第三项所称的警用车船，是指公安机关、国家安全机关、监狱、劳动教养管理机关和人民法院、人民检察院领取警用牌照的车辆和执行警务的专用船舶。"},{"i":10,"n":"第十条","txt":"节约能源、使用新能源的车船可以免征或者减半征收车船税。免征或者减半征收车船税的车船的范围，由国务院财政、税务主管部门商国务院有关部门制订，报国务院批准。"},{"i":11,"n":"第十一条","txt":"车船税由税务机关负责征收。"},{"i":12,"n":"第十二条","txt":"机动车车船税扣缴义务人在代收车船税时，应当在机动车交通事故责任强制保险的保险单以及保费发票上注明已收税款的信息，作为代收税款凭证。"},{"i":13,"n":"第十三条","txt":"已完税或者依法减免税的车辆，纳税人应当向扣缴义务人提供登记地的主管税务机关出具的完税凭证或者减免税证明。"},{"i":14,"n":"第十四条","txt":"纳税人没有按照规定期限缴纳车船税的，扣缴义务人在代收代缴税款时，可以一并代收代缴欠缴税款的滞纳金。"},{"i":15,"n":"第十五条","txt":"扣缴义务人已代收代缴车船税的，纳税人不再向车辆登记地的主管税务机关申报缴纳车船税。"},{"i":16,"n":"第十六条","txt":"纳税人缴纳车船税时，应当提供反映排气量、整备质量、核定载客人数、净吨位、千瓦、艇身长度等与纳税相关信息的相应凭证以及税务机关根据实际需要要求提供的其他资料。"},{"i":17,"n":"第十七条","txt":"车辆车船税的纳税人按照纳税地点所在的省、自治区、直辖市人民政府确定的具体适用税额缴纳车船税。"},{"i":18,"n":"第十八条","txt":"扣缴义务人应当及时解缴代收代缴的税款和滞纳金，并向主管税务机关申报。扣缴义务人向税务机关解缴税款和滞纳金时，应当同时报送明细的税款和滞纳金扣缴报告。扣缴义务人解缴税款和滞纳金的具体期限，由省、自治区、直辖市税务机关依照法律、行政法规的规定确定。"},{"i":19,"n":"第十九条","txt":"购置的新车船，购置当年的应纳税额自纳税义务发生的当月起按月计算。应纳税额为年应纳税额除以12再乘以应纳税月份数。"},{"i":20,"n":"第二十条","txt":"已缴纳车船税的车船在同一纳税年度内办理转让过户的，不另纳税，也不退税。"},{"i":21,"n":"第二十一条","txt":"车船税法第八条所称取得车船所有权或者管理权的当月，应当以购买车船的发票或者其他证明文件所载日期的当月为准。"},{"i":22,"n":"第二十二条","txt":"税务机关可以在车船登记管理部门、车船检验机构的办公场所集中办理车船税征收事宜。"},{"i":23,"n":"第二十三条","txt":"车船税按年申报，分月计算，一次性缴纳。纳税年度为公历1月1日至12月31日。"},{"i":24,"n":"第二十四条","txt":"临时入境的外国车船和香港特别行政区、澳门特别行政区、台湾地区的车船，不征收车船税。"},{"i":25,"n":"第二十五条","txt":"按照规定缴纳船舶吨税的机动船舶，自车船税法实施之日起5年内免征车船税。"},{"i":26,"n":"第二十六条","txt":"车船税法所附《车船税税目税额表》中车辆、船舶的含义如下："},{"i":27,"n":"第二十七条","txt":"本条例自2012年1月1日起施行。"}],"jinchukoushangpinjianyanfashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国进出口商品检验法》（以下简称商检法）的规定，制定本条例。"},{"i":2,"n":"第二条","txt":"海关总署主管全国进出口商品检验工作。"},{"i":3,"n":"第三条","txt":"海关总署应当依照商检法第四条规定，制定、调整必须实施检验的进出口商品目录（以下简称目录）并公布实施。"},{"i":4,"n":"第四条","txt":"出入境检验检疫机构对列入目录的进出口商品以及法律、行政法规规定须经出入境检验检疫机构检验的其他进出口商品实施检验（以下称法定检验）。"},{"i":5,"n":"第五条","txt":"进出口药品的质量检验、计量器具的量值检定、锅炉压力容器的安全监督检验、船舶（包括海上平台、主要船用设备及材料）和集装箱的规范检验、飞机（包括飞机发动机、机载设备）的适航检验以及核承压设备的安全检验等项目，由有关法律、行政法规规定的机构实施检验。"},{"i":6,"n":"第六条","txt":"进出境的样品、礼品、暂时进出境的货物以及其他非贸易性物品，免予检验。但是，法律、行政法规另有规定的除外。"},{"i":7,"n":"第七条","txt":"法定检验的进出口商品，由出入境检验检疫机构依照商检法第七条规定实施检验。"},{"i":8,"n":"第八条","txt":"出入境检验检疫机构根据便利对外贸易的需要，对进出口企业实施分类管理，并按照根据国际通行的合格评定程序确定的检验监管方式，对进出口商品实施检验。"},{"i":9,"n":"第九条","txt":"出入境检验检疫机构对进出口商品实施检验的内容，包括是否符合安全、卫生、健康、环境保护、防止欺诈等要求以及相关的品质、数量、重量等项目。"},{"i":10,"n":"第十条","txt":"出入境检验检疫机构依照商检法的规定，对实施许可制度和国家规定必须经过认证的进出口商品实行验证管理，查验单证，核对证货是否相符。"},{"i":11,"n":"第十一条","txt":"进出口商品的收货人或者发货人可以自行办理报检手续，也可以委托代理报检企业办理报检手续；采用快件方式进出口商品的，收货人或者发货人应当委托出入境快件运营企业办理报检手续。"},{"i":12,"n":"第十二条","txt":"进出口商品的收货人或者发货人办理报检手续，应当依法向出入境检验检疫机构备案。"},{"i":13,"n":"第十三条","txt":"代理报检企业接受进出口商品的收货人或者发货人的委托，以委托人的名义办理报检手续的，应当向出入境检验检疫机构提交授权委托书，遵守本条例对委托人的各项规定；以自己的名义办理报检手续的，应当承担与收货人或者发货人相同的法律责任。"},{"i":14,"n":"第十四条","txt":"海关总署建立进出口商品风险预警机制，通过收集进出口商品检验方面的信息，进行风险评估，确定风险的类型，采取相应的风险预警措施及快速反应措施。"},{"i":15,"n":"第十五条","txt":"出入境检验检疫机构工作人员依法执行职务，有关单位和个人应当予以配合，任何单位和个人不得非法干预和阻挠。"},{"i":16,"n":"第十六条","txt":"法定检验的进口商品的收货人应当持合同、发票、装箱单、提单等必要的凭证和相关批准文件，向报关地的出入境检验检疫机构报检；通关放行后20日内，收货人应当依照本条例第十八条的规定，向出入境检验检疫机构申请检验。法定检验的进口商品未经检验的，不准销售，不准使用。"},{"i":17,"n":"第十七条","txt":"法定检验的进口商品、实行验证管理的进口商品，海关按照规定办理海关通关手续。"},{"i":18,"n":"第十八条","txt":"法定检验的进口商品应当在收货人报检时申报的目的地检验。"},{"i":19,"n":"第十九条","txt":"除法律、行政法规另有规定外，法定检验的进口商品经检验，涉及人身财产安全、健康、环境保护项目不合格的，由出入境检验检疫机构责令当事人销毁，或者出具退货处理通知单，办理退运手续；其他项目不合格的，可以在出入境检验检疫机构的监督下进行技术处理，经重新检验合格的，方可销售或者使用。当事人申请出入境检验检疫机构出证的，出入境检验检疫机构应当及时出证。"},{"i":20,"n":"第二十条","txt":"法定检验以外的进口商品，经出入境检验检疫机构抽查检验不合格的，依照本条例第十九条的规定处理。"},{"i":21,"n":"第二十一条","txt":"对属于法定检验范围内的关系国计民生、价值较高、技术复杂的以及其他重要的进口商品和大型成套设备，应当按照对外贸易合同约定监造、装运前检验或者监装。收货人保留到货后最终检验和索赔的权利。"},{"i":22,"n":"第二十二条","txt":"国家对进口可用作原料的固体废物的国外供货商、国内收货人实行注册登记制度，国外供货商、国内收货人在签订对外贸易合同前，应当取得海关总署或者出入境检验检疫机构的注册登记。国家对进口可用作原料的固体废物实行装运前检验制度，进口时，收货人应当提供出入境检验检疫机构或者检验机构出具的装运前检验证书。"},{"i":23,"n":"第二十三条","txt":"进口机动车辆到货后，收货人凭出入境检验检疫机构签发的进口机动车辆检验证单以及有关部门签发的其他单证向车辆管理机关申领行车牌证。在使用过程中发现有涉及人身财产安全的质量缺陷的，出入境检验检疫机构应当及时作出相应处理。"},{"i":24,"n":"第二十四条","txt":"法定检验的出口商品的发货人应当在海关总署统一规定的地点和期限内，持合同等必要的凭证和相关批准文件向出入境检验检疫机构报检。法定检验的出口商品未经检验或者经检验不合格的，不准出口。"},{"i":25,"n":"第二十五条","txt":"在商品生产地检验的出口商品需要在口岸换证出口的，由商品生产地的出入境检验检疫机构按照规定签发检验换证凭单。发货人应当在规定的期限内持检验换证凭单和必要的凭证，向口岸出入境检验检疫机构申请查验。经查验合格的，由口岸出入境检验检疫机构签发货物通关单。"},{"i":26,"n":"第二十六条","txt":"法定检验的出口商品、实行验证管理的出口商品，海关按照规定办理海关通关手续。"},{"i":27,"n":"第二十七条","txt":"法定检验的出口商品经出入境检验检疫机构检验或者经口岸出入境检验检疫机构查验不合格的，可以在出入境检验检疫机构的监督下进行技术处理，经重新检验合格的，方准出口；不能进行技术处理或者技术处理后重新检验仍不合格的，不准出口。"},{"i":28,"n":"第二十八条","txt":"法定检验以外的出口商品，经出入境检验检疫机构抽查检验不合格的，依照本条例第二十七条的规定处理。"},{"i":29,"n":"第二十九条","txt":"出口危险货物包装容器的生产企业，应当向出入境检验检疫机构申请包装容器的性能鉴定。包装容器经出入境检验检疫机构鉴定合格并取得性能鉴定证书的，方可用于包装危险货物。"},{"i":30,"n":"第三十条","txt":"对装运出口的易腐烂变质食品、冷冻品的集装箱、船舱、飞机、车辆等运载工具，承运人、装箱单位或者其代理人应当在装运前向出入境检验检疫机构申请清洁、卫生、冷藏、密固等适载检验。未经检验或者经检验不合格的，不准装运。"},{"i":31,"n":"第三十一条","txt":"出入境检验检疫机构根据便利对外贸易的需要，可以对列入目录的出口商品进行出厂前的质量监督管理和检验。"},{"i":32,"n":"第三十二条","txt":"国家对进出口食品生产企业实施卫生注册登记管理。获得卫生注册登记的出口食品生产企业，方可生产、加工、储存出口食品。获得卫生注册登记的进出口食品生产企业生产的食品，方可进口或者出口。"},{"i":33,"n":"第三十三条","txt":"出入境检验检疫机构根据需要，对检验合格的进出口商品加施商检标志，对检验合格的以及其他需要加施封识的进出口商品加施封识。具体办法由海关总署制定。"},{"i":34,"n":"第三十四条","txt":"出入境检验检疫机构按照有关规定对检验的进出口商品抽取样品。验余的样品，出入境检验检疫机构应当通知有关单位在规定的期限内领回；逾期不领回的，由出入境检验检疫机构处理。"},{"i":35,"n":"第三十五条","txt":"进出口商品的报检人对出入境检验检疫机构作出的检验结果有异议的，可以自收到检验结果之日起15日内，向作出检验结果的出入境检验检疫机构或者其上级出入境检验检疫机构以至海关总署申请复验，受理复验的出入境检验检疫机构或者海关总署应当自收到复验申请之日起60日内作出复验结论。技术复杂，不能在规定期限内作出复验结论的，经本机构负责人批准，可以适当延长，但是延长期限最多不超过30日。"},{"i":36,"n":"第三十六条","txt":"海关总署或者出入境检验检疫机构根据进出口商品检验工作的需要，可以指定符合规定资质条件的国内外检测机构承担出入境检验检疫机构委托的进出口商品检测。被指定的检测机构经检查不符合规定要求的，海关总署或者出入境检验检疫机构可以取消指定。"},{"i":37,"n":"第三十七条","txt":"对检验机构的检验鉴定业务活动有异议的，可以向海关总署或者出入境检验检疫机构投诉。"},{"i":38,"n":"第三十八条","txt":"海关总署、出入境检验检疫机构实施监督管理或者对涉嫌违反进出口商品检验法律、行政法规的行为进行调查，有权查阅、复制当事人的有关合同、发票、账簿以及其他有关资料。出入境检验检疫机构对有根据认为涉及人身财产安全、健康、环境保护项目不合格的进出口商品，经本机构负责人批准，可以查封或者扣押。"},{"i":39,"n":"第三十九条","txt":"海关总署、出入境检验检疫机构应当根据便利对外贸易的需要，采取有效措施，简化程序，方便进出口。"},{"i":40,"n":"第四十条","txt":"出入境检验检疫机构依照有关法律、行政法规的规定，签发出口货物普惠制原产地证明、区域性优惠原产地证明、专用原产地证明。"},{"i":41,"n":"第四十一条","txt":"出入境检验检疫机构对进出保税区、出口加工区等海关特殊监管区域的货物以及边境小额贸易进出口商品的检验管理，由海关总署另行制定办法。"},{"i":42,"n":"第四十二条","txt":"擅自销售、使用未报检或者未经检验的属于法定检验的进口商品，或者擅自销售、使用应当申请进口验证而未申请的进口商品的，由出入境检验检疫机构没收违法所得，并处商品货值金额5%以上20%以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":43,"n":"第四十三条","txt":"擅自出口未报检或者未经检验的属于法定检验的出口商品，或者擅自出口应当申请出口验证而未申请的出口商品的，由出入境检验检疫机构没收违法所得，并处商品货值金额5%以上20%以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":44,"n":"第四十四条","txt":"销售、使用经法定检验、抽查检验或者验证不合格的进口商品，或者出口经法定检验、抽查检验或者验证不合格的商品的，由出入境检验检疫机构责令停止销售、使用或者出口，没收违法所得和违法销售、使用或者出口的商品，并处违法销售、使用或者出口的商品货值金额等值以上3倍以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":45,"n":"第四十五条","txt":"进出口商品的收货人、发货人、代理报检企业或者出入境快件运营企业、报检人员不如实提供进出口商品的真实情况，取得出入境检验检疫机构的有关证单，或者对法定检验的进出口商品不予报检，逃避进出口商品检验的，由出入境检验检疫机构没收违法所得，并处商品货值金额5%以上20%以下罚款。"},{"i":46,"n":"第四十六条","txt":"伪造、变造、买卖或者盗窃检验证单、印章、标志、封识、货物通关单或者使用伪造、变造的检验证单、印章、标志、封识、货物通关单，构成犯罪的，依法追究刑事责任；尚不够刑事处罚的，由出入境检验检疫机构责令改正，没收违法所得，并处商品货值金额等值以下罚款。"},{"i":47,"n":"第四十七条","txt":"擅自调换出入境检验检疫机构抽取的样品或者出入境检验检疫机构检验合格的进出口商品的，由出入境检验检疫机构责令改正，给予警告；情节严重的，并处商品货值金额10%以上50%以下罚款。"},{"i":48,"n":"第四十八条","txt":"进口或者出口国家实行卫生注册登记管理而未获得卫生注册登记的生产企业生产的食品的，由出入境检验检疫机构责令停止进口或者出口，没收违法所得，并处商品货值金额10%以上50%以下罚款。"},{"i":49,"n":"第四十九条","txt":"进口可用作原料的固体废物，国外供货商、国内收货人未取得注册登记，或者未进行装运前检验的，按照国家有关规定责令退货；情节严重的，由出入境检验检疫机构并处10万元以上100万元以下罚款。"},{"i":50,"n":"第五十条","txt":"提供或者使用未经出入境检验检疫机构鉴定的出口危险货物包装容器的，由出入境检验检疫机构处10万元以下罚款。"},{"i":51,"n":"第五十一条","txt":"提供或者使用未经出入境检验检疫机构适载检验的集装箱、船舱、飞机、车辆等运载工具装运易腐烂变质食品、冷冻品出口的，由出入境检验检疫机构处10万元以下罚款。"},{"i":52,"n":"第五十二条","txt":"擅自调换、损毁出入境检验检疫机构加施的商检标志、封识的，由出入境检验检疫机构处5万元以下罚款。"},{"i":53,"n":"第五十三条","txt":"从事进出口商品检验鉴定业务的检验机构违反国家有关规定，扰乱检验鉴定秩序的，由出入境检验检疫机构责令改正，没收违法所得，可以并处10万元以下罚款，海关总署或者出入境检验检疫机构可以暂停其6个月以内检验鉴定业务。"},{"i":54,"n":"第五十四条","txt":"代理报检企业、出入境快件运营企业违反国家有关规定，扰乱报检秩序的，由出入境检验检疫机构责令改正，没收违法所得，可以处10万元以下罚款，海关总署或者出入境检验检疫机构可以暂停其6个月以内代理报检业务。"},{"i":55,"n":"第五十五条","txt":"出入境检验检疫机构的工作人员滥用职权，故意刁难当事人的，徇私舞弊，伪造检验结果的，或者玩忽职守，延误检验出证的，依法给予行政处分；违反有关法律、行政法规规定签发出口货物原产地证明的，依法给予行政处分，没收违法所得；构成犯罪的，依法追究刑事责任。"},{"i":56,"n":"第五十六条","txt":"出入境检验检疫机构对没收的商品依法予以处理所得价款、没收的违法所得、收缴的罚款，全部上缴国库。"},{"i":57,"n":"第五十七条","txt":"当事人对出入境检验检疫机构、海关总署作出的复验结论、处罚决定不服的，可以依法申请行政复议，也可以依法向人民法院提起诉讼。"},{"i":58,"n":"第五十八条","txt":"出入境检验检疫机构实施法定检验、依法设立的检验机构办理检验鉴定业务，按照国家有关规定收取费用。"},{"i":59,"n":"第五十九条","txt":"本条例自2005年12月1日起施行。1992年10月7日国务院批准、1992年10月23日原国家进出口商品检验局发布的《中华人民共和国进出口商品检验法实施条例》同时废止。"}],"jinchujingdongzhiwujianyifashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国进出境动植物检疫法》（以下简称进出境动植物检疫法）的规定，制定本条例。"},{"i":2,"n":"第二条","txt":"下列各物，依照进出境动植物检疫法和本条例的规定实施检疫："},{"i":3,"n":"第三条","txt":"国务院农业行政主管部门主管全国进出境动植物检疫工作。"},{"i":4,"n":"第四条","txt":"国（境）外发生重大动植物疫情并可能传入中国时，根据情况采取下列紧急预防措施："},{"i":5,"n":"第五条","txt":"享有外交、领事特权与豁免的外国机构和人员公用或者自用的动植物、动植物产品和其他检疫物进境，应当依照进出境动植物检疫法和本条例的规定实施检疫；口岸动植物检疫机关查验时，应当遵守有关法律的规定。"},{"i":6,"n":"第六条","txt":"海关依法配合口岸动植物检疫机关，对进出境动植物、动植物产品和其他检疫物实行监管。具体办法由国务院农业行政主管部门会同海关总署制定。"},{"i":7,"n":"第七条","txt":"进出境动植物检疫法所称动植物疫区和动植物疫情流行的国家与地区的名录，由国务院农业行政主管部门确定并公布。"},{"i":8,"n":"第八条","txt":"对贯彻执行进出境动植物检疫法和本条例做出显著成绩的单位和个人，给予奖励。"},{"i":9,"n":"第九条","txt":"输入动物、动物产品和进出境动植物检疫法第五条第一款所列禁止进境物的检疫审批，由国家动植物检疫局或者其授权的口岸动植物检疫机关负责。"},{"i":10,"n":"第十条","txt":"符合下列条件的，方可办理进境检疫审批手续："},{"i":11,"n":"第十一条","txt":"检疫审批手续应当在贸易合同或者协议签订前办妥。"},{"i":12,"n":"第十二条","txt":"携带、邮寄植物种子、种苗及其他繁殖材料进境的，必须事先提出申请，办理检疫审批手续；因特殊情况无法事先办理的，携带人或者邮寄人应当在口岸补办检疫审批手续，经审批机关同意并经检疫合格后方准进境。"},{"i":13,"n":"第十三条","txt":"要求运输动物过境的，货主或者其代理人必须事先向国家动植物检疫局提出书面申请，提交输出国家或者地区政府动植物检疫机关出具的疫情证明、输入国家或者地区政府动植物检疫机关出具的准许该动物进境的证件，并说明拟过境的路线，国家动植物检疫局审查同意后，签发《动物过境许可证》。"},{"i":14,"n":"第十四条","txt":"因科学研究等特殊需要，引进进出境动植物检疫法第五条第一款所列禁止进境物的，办理禁止进境物特许检疫审批手续时，货主、物主或者其代理人必须提交书面申请，说明其数量、用途、引进方式、进境后的防疫措施，并附具有关口岸动植物检疫机关签署的意见。"},{"i":15,"n":"第十五条","txt":"办理进境检疫审批手续后，有下列情况之一的，货主、物主或者其代理人应当重新申请办理检疫审批手续："},{"i":16,"n":"第十六条","txt":"进出境动植物检疫法第十一条所称中国法定的检疫要求，是指中国的法律、行政法规和国务院农业行政主管部门规定的动植物检疫要求。"},{"i":17,"n":"第十七条","txt":"国家对向中国输出动植物产品的国外生产、加工、存放单位，实行注册登记制度。具体办法由国务院农业行政主管部门制定。"},{"i":18,"n":"第十八条","txt":"输入动植物、动植物产品和其他检疫物的，货主或者其代理人应当在进境前或者进境时向进境口岸动植物检疫机关报检。属于调离海关监管区检疫的，运达指定地点时，货主或者其代理人应当通知有关口岸动植物检疫机关。属于转关货物的，货主或者其代理人应当在进境时向进境口岸动植物检疫机关申报；到达指运地时，应当向指运地口岸动植物检疫机关报检。"},{"i":19,"n":"第十九条","txt":"向口岸动植物检疫机关报检时，应当填写报检单，并提交输出国家或者地区政府动植物检疫机关出具的检疫证书、产地证书和贸易合同、信用证、发票等单证；依法应当办理检疫审批手续的，还应当提交检疫审批单。无输出国家或者地区政府动植物检疫机关出具的有效检疫证书，或者未依法办理检疫审批手续的，口岸动植物检疫机关可以根据具体情况，作退回或者销毁处理。"},{"i":20,"n":"第二十条","txt":"输入的动植物、动植物产品和其他检疫物运达口岸时，检疫人员可以到运输工具上和货物现场实施检疫，核对货、证是否相符，并可以按照规定采取样品。承运人、货主或者其代理人应当向检疫人员提供装载清单和有关资料。"},{"i":21,"n":"第二十一条","txt":"装载动物的运输工具抵达口岸时，上下运输工具或者接近动物的人员，应当接受口岸动植物检疫机关实施的防疫消毒，并执行其采取的其他现场预防措施。"},{"i":22,"n":"第二十二条","txt":"检疫人员应当按照下列规定实施现场检疫："},{"i":23,"n":"第二十三条","txt":"对船舶、火车装运的大宗动植物产品，应当就地分层检查；限于港口、车站的存放条件，不能就地检查的，经口岸动植物检疫机关同意，也可以边卸载边疏运，将动植物产品运往指定的地点存放。在卸货过程中经检疫发现疫情时，应当立即停止卸货，由货主或者其代理人按照口岸动植物检疫机关的要求，对已卸和未卸货物作除害处理，并采取防止疫情扩散的措施；对被病虫害污染的装卸工具和场地，也应当作除害处理。"},{"i":24,"n":"第二十四条","txt":"输入种用大中家畜的，应当在国家动植物检疫局设立的动物隔离检疫场所隔离检疫45日；输入其他动物的，应当在口岸动植物检疫机关指定的动物隔离检疫场所隔离检疫30日。动物隔离检疫场所管理办法，由国务院农业行政主管部门制定。"},{"i":25,"n":"第二十五条","txt":"进境的同一批动植物产品分港卸货时，口岸动植物检疫机关只对本港卸下的货物进行检疫，先期卸货港的口岸动植物检疫机关应当将检疫及处理情况及时通知其他分卸港的口岸动植物检疫机关；需要对外出证的，由卸毕港的口岸动植物检疫机关汇总后统一出具检疫证书。"},{"i":26,"n":"第二十六条","txt":"对输入的动植物、动植物产品和其他检疫物，按照中国的国家标准、行业标准以及国家动植物检疫局的有关规定实施检疫。"},{"i":27,"n":"第二十七条","txt":"输入动植物、动植物产品和其他检疫物，经检疫合格的，由口岸动植物检疫机关在报关单上加盖印章或者签发《检疫放行通知单》；需要调离进境口岸海关监管区检疫的，由进境口岸动植物检疫机关签发《检疫调离通知单》。货主或者其代理人凭口岸动植物检疫机关在报关单上加盖的印章或者签发的《检疫放行通知单》、《检疫调离通知单》办理报关、运递手续。海关对输入的动植物、动植物产品和其他检疫物，凭口岸动植物检疫机关在报关单上加盖的印章或者签发的《检疫放行通知单》、《检疫调离通知单》验放。运输、邮电部门凭单运递，运递期间国内其他检疫机关不再检疫。"},{"i":28,"n":"第二十八条","txt":"输入动植物、动植物产品和其他检疫物，经检疫不合格的，由口岸动植物检疫机关签发《检疫处理通知单》，通知货主或者其代理人在口岸动植物检疫机关的监督和技术指导下，作除害处理；需要对外索赔的，由口岸动植物检疫机关出具检疫证书。"},{"i":29,"n":"第二十九条","txt":"国家动植物检疫局根据检疫需要，并商输出动植物、动植物产品国家或者地区政府有关机关同意，可以派检疫人员进行预检、监装或者产地疫情调查。"},{"i":30,"n":"第三十条","txt":"海关、边防等部门截获的非法进境的动植物、动植物产品和其他检疫物，应当就近交由口岸动植物检疫机关检疫。"},{"i":31,"n":"第三十一条","txt":"货主或者其代理人依法办理动植物、动植物产品和其他检疫物的出境报检手续时，应当提供贸易合同或者协议。"},{"i":32,"n":"第三十二条","txt":"对输入国要求中国对向其输出的动植物、动植物产品和其他检疫物的生产、加工、存放单位注册登记的，口岸动植物检疫机关可以实行注册登记，并报国家动植物检疫局备案。"},{"i":33,"n":"第三十三条","txt":"输出动物，出境前需经隔离检疫的，在口岸动植物检疫机关指定的隔离场所检疫。输出植物、动植物产品和其他检疫物的，在仓库或者货场实施检疫；根据需要，也可以在生产、加工过程中实施检疫。"},{"i":34,"n":"第三十四条","txt":"输出动植物、动植物产品和其他检疫物的检疫依据："},{"i":35,"n":"第三十五条","txt":"经启运地口岸动植物检疫机关检疫合格的动植物、动植物产品和其他检疫物，运达出境口岸时，按照下列规定办理："},{"i":36,"n":"第三十六条","txt":"输出动植物、动植物产品和其他检疫物，经启运地口岸动植物检疫机关检疫合格的，运往出境口岸时，运输、邮电部门凭启运地口岸动植物检疫机关签发的检疫单证运递，国内其他检疫机关不再检疫。"},{"i":37,"n":"第三十七条","txt":"运输动植物、动植物产品和其他检疫物过境（含转运，下同）的，承运人或者押运人应当持货运单和输出国家或者地区政府动植物检疫机关出具的证书，向进境口岸动植物检疫机关报检；运输动物过境的，还应当同时提交国家动植物检疫局签发的《动物过境许可证》。"},{"i":38,"n":"第三十八条","txt":"过境动物运达进境口岸时，由进境口岸动植物检疫机关对运输工具、容器的外表进行消毒并对动物进行临床检疫，经检疫合格的，准予过境。进境口岸动植物检疫机关可以派检疫人员监运至出境口岸，出境口岸动植物检疫机关不再检疫。"},{"i":39,"n":"第三十九条","txt":"装载过境植物、动植物产品和其他检疫物的运输工具和包装物、装载容器必须完好。经口岸动植物检疫机关检查，发现运输工具或者包装物、装载容器有可能造成途中散漏的，承运人或者押运人应当按照口岸动植物检疫机关的要求，采取密封措施；无法采取密封措施的，不准过境。"},{"i":40,"n":"第四十条","txt":"携带、邮寄植物种子、种苗及其他繁殖材料进境，未依法办理检疫审批手续的，由口岸动植物检疫机关作退回或者销毁处理。邮件作退回处理的，由口岸动植物检疫机关在邮件及发递单上批注退回原因；邮件作销毁处理的，由口岸动植物检疫机关签发通知单，通知寄件人。"},{"i":41,"n":"第四十一条","txt":"携带动植物、动植物产品和其他检疫物进境的，进境时必须向海关申报并接受口岸动植物检疫机关检疫。海关应当将申报或者查获的动植物、动植物产品和其他检疫物及时交由口岸动植物检疫机关检疫。未经检疫的，不得携带进境。"},{"i":42,"n":"第四十二条","txt":"口岸动植物检疫机关可以在港口、机场、车站的旅客通道、行李提取处等现场进行检查，对可能携带动植物、动植物产品和其他检疫物而未申报的，可以进行查询并抽检其物品，必要时可以开包（箱）检查。"},{"i":43,"n":"第四十三条","txt":"携带动物进境的，必须持有输出动物的国家或者地区政府动植物检疫机关出具的检疫证书，经检疫合格后放行；携带犬、猫等宠物进境的，还必须持有疫苗接种证书。没有检疫证书、疫苗接种证书的，由口岸动植物检疫机关作限期退回或者没收销毁处理。作限期退回处理的，携带人必须在规定的时间内持口岸动植物检疫机关签发的截留凭证，领取并携带出境；逾期不领取的，作自动放弃处理。"},{"i":44,"n":"第四十四条","txt":"邮寄进境的动植物、动植物产品和其他检疫物，由口岸动植物检疫机关在国际邮件互换局（含国际邮件快递公司及其他经营国际邮件的单位，以下简称邮局）实施检疫。邮局应当提供必要的工作条件。"},{"i":45,"n":"第四十五条","txt":"携带、邮寄进境的动植物、动植物产品和其他检疫物，经检疫不合格又无有效方法作除害处理的，作退回或者销毁处理，并签发《检疫处理通知单》交携带人、寄件人。"},{"i":46,"n":"第四十六条","txt":"口岸动植物检疫机关对来自动植物疫区的船舶、飞机、火车，可以登船、登机、登车实施现场检疫。有关运输工具负责人应当接受检疫人员的询问并在询问记录上签字，提供运行日志和装载货物的情况，开启舱室接受检疫。"},{"i":47,"n":"第四十七条","txt":"来自动植物疫区的船舶、飞机、火车，经检疫发现有进出境动植物检疫法第十八条规定的名录所列病虫害的，必须作熏蒸、消毒或者其他除害处理。发现有禁止进境的动植物、动植物产品和其他检疫物的，必须作封存或者销毁处理；作封存处理的，在中国境内停留或者运行期间，未经口岸动植物检疫机关许可，不得启封动用。对运输工具上的泔水、动植物性废弃物及其存放场所、容器，应当在口岸动植物检疫机关的监督下作除害处理。"},{"i":48,"n":"第四十八条","txt":"来自动植物疫区的进境车辆，由口岸动植物检疫机关作防疫消毒处理。装载进境动植物、动植物产品和其他检疫物的车辆，经检疫发现病虫害的，连同货物一并作除害处理。装运供应香港、澳门地区的动物的回空车辆，实施整车防疫消毒。"},{"i":49,"n":"第四十九条","txt":"进境拆解的废旧船舶，由口岸动植物检疫机关实施检疫。发现病虫害的，在口岸动植物检疫机关监督下作除害处理。发现有禁止进境的动植物、动植物产品和其他检疫物的，在口岸动植物检疫机关的监督下作销毁处理。"},{"i":50,"n":"第五十条","txt":"来自动植物疫区的进境运输工具经检疫或者经消毒处理合格后，运输工具负责人或者其代理人要求出证的，由口岸动植物检疫机关签发《运输工具检疫证书》或者《运输工具消毒证书》。"},{"i":51,"n":"第五十一条","txt":"进境、过境运输工具在中国境内停留期间，交通员工和其他人员不得将所装载的动植物、动植物产品和其他检疫物带离运输工具；需要带离时，应当向口岸动植物检疫机关报检。"},{"i":52,"n":"第五十二条","txt":"装载动物出境的运输工具，装载前应当在口岸动植物检疫机关监督下进行消毒处理。"},{"i":53,"n":"第五十三条","txt":"国家动植物检疫局和口岸动植物检疫机关对进出境动植物、动植物产品的生产、加工、存放过程，实行检疫监督制度。具体办法由国务院农业行政主管部门制定。"},{"i":54,"n":"第五十四条","txt":"进出境动物和植物种子、种苗及其他繁殖材料，需要隔离饲养、隔离种植的，在隔离期间，应当接受口岸动植物检疫机关的检疫监督。"},{"i":55,"n":"第五十五条","txt":"从事进出境动植物检疫熏蒸、消毒处理业务的单位和人员，必须经口岸动植物检疫机关考核合格。"},{"i":56,"n":"第五十六条","txt":"口岸动植物检疫机关可以根据需要，在机场、港口、车站、仓库、加工厂、农场等生产、加工、存放进出境动植物、动植物产品和其他检疫物的场所实施动植物疫情监测，有关单位应当配合。"},{"i":57,"n":"第五十七条","txt":"口岸动植物检疫机关根据需要，可以对运载进出境动植物、动植物产品和其他检疫物的运输工具、装载容器加施动植物检疫封识或者标志；未经口岸动植物检疫机关许可，不得开拆或者损毁检疫封识、标志。"},{"i":58,"n":"第五十八条","txt":"进境动植物、动植物产品和其他检疫物，装载动植物、动植物产品和其他检疫物的装载容器、包装物，运往保税区（含保税工厂、保税仓库等）的，在进境口岸依法实施检疫；口岸动植物检疫机关可以根据具体情况实施检疫监督；经加工复运出境的，依照进出境动植物检疫法和本条例有关出境检疫的规定办理。"},{"i":59,"n":"第五十九条","txt":"有下列违法行为之一的，由口岸动植物检疫机关处5000元以下的罚款："},{"i":60,"n":"第六十条","txt":"有下列违法行为之一的，由口岸动植物检疫机关处3000元以上3万元以下的罚款："},{"i":61,"n":"第六十一条","txt":"依照本条例第十七条、第三十二条的规定注册登记的生产、加工、存放动植物、动植物产品和其他检疫物的单位，进出境的上述物品经检疫不合格的，除依照本条例有关规定作退回、销毁或者除害处理外，情节严重的，由口岸动植物检疫机关注销注册登记。"},{"i":62,"n":"第六十二条","txt":"有下列违法行为之一的，依法追究刑事责任；尚不构成犯罪或者犯罪情节显著轻微依法不需要判处刑罚的，由口岸动植物检疫机关处2万元以上5万元以下的罚款："},{"i":63,"n":"第六十三条","txt":"从事进出境动植物检疫熏蒸、消毒处理业务的单位和人员，不按照规定进行熏蒸和消毒处理的，口岸动植物检疫机关可以视情节取消其熏蒸、消毒资格。"},{"i":64,"n":"第六十四条","txt":"进出境动植物检疫法和本条例下列用语的含义："},{"i":65,"n":"第六十五条","txt":"对进出境动植物、动植物产品和其他检疫物因实施检疫或者按照规定作熏蒸、消毒、退回、销毁等处理所需费用或者招致的损失，由货主、物主或者其代理人承担。"},{"i":66,"n":"第六十六条","txt":"口岸动植物检疫机关依法实施检疫，需要采取样品时，应当出具采样凭单；验余的样品，货主、物主或者其代理人应当在规定的期限内领回；逾期不领回的，由口岸动植物检疫机关按照规定处理。"},{"i":67,"n":"第六十七条","txt":"贸易性动物产品出境的检疫机关，由国务院根据情况规定。"},{"i":68,"n":"第六十八条","txt":"本条例自1997年1月1日起施行。"}],"daolujiaotonganquanfashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国道路交通安全法》（以下简称道路交通安全法）的规定，制定本条例。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内的车辆驾驶人、行人、乘车人以及与道路交通活动有关的单位和个人，应当遵守道路交通安全法和本条例。"},{"i":3,"n":"第三条","txt":"县级以上地方各级人民政府应当建立、健全道路交通安全工作协调机制，组织有关部门对城市建设项目进行交通影响评价，制定道路交通安全管理规划，确定管理目标，制定实施方案。"},{"i":4,"n":"第四条","txt":"机动车的登记，分为注册登记、变更登记、转移登记、抵押登记和注销登记。"},{"i":5,"n":"第五条","txt":"初次申领机动车号牌、行驶证的，应当向机动车所有人住所地的公安机关交通管理部门申请注册登记。"},{"i":6,"n":"第六条","txt":"已注册登记的机动车有下列情形之一的，机动车所有人应当向登记该机动车的公安机关交通管理部门申请变更登记："},{"i":7,"n":"第七条","txt":"已注册登记的机动车所有权发生转移的，应当及时办理转移登记。"},{"i":8,"n":"第八条","txt":"机动车所有人将机动车作为抵押物抵押的，机动车所有人应当向登记该机动车的公安机关交通管理部门申请抵押登记。"},{"i":9,"n":"第九条","txt":"已注册登记的机动车达到国家规定的强制报废标准的，公安机关交通管理部门应当在报废期满的2个月前通知机动车所有人办理注销登记。机动车所有人应当在报废期满前将机动车交售给机动车回收企业，由机动车回收企业将报废的机动车登记证书、号牌、行驶证交公安机关交通管理部门注销。机动车所有人逾期不办理注销登记的，公安机关交通管理部门应当公告该机动车登记证书、号牌、行驶证作废。"},{"i":10,"n":"第十条","txt":"办理机动车登记的申请人提交的证明、凭证齐全、有效的，公安机关交通管理部门应当当场办理登记手续。"},{"i":11,"n":"第十一条","txt":"机动车登记证书、号牌、行驶证丢失或者损毁，机动车所有人申请补发的，应当向公安机关交通管理部门提交本人身份证明和申请材料。公安机关交通管理部门经与机动车登记档案核实后，在收到申请之日起15日内补发。"},{"i":12,"n":"第十二条","txt":"税务部门、保险机构可以在公安机关交通管理部门的办公场所集中办理与机动车有关的税费缴纳、保险合同订立等事项。"},{"i":13,"n":"第十三条","txt":"机动车号牌应当悬挂在车前、车后指定位置，保持清晰、完整。重型、中型载货汽车及其挂车、拖拉机及其挂车的车身或者车厢后部应当喷涂放大的牌号，字样应当端正并保持清晰。"},{"i":14,"n":"第十四条","txt":"用于公路营运的载客汽车、重型载货汽车、半挂牵引车应当安装、使用符合国家标准的行驶记录仪。交通警察可以对机动车行驶速度、连续驾驶时间以及其他行驶状态信息进行检查。安装行驶记录仪可以分步实施，实施步骤由国务院机动车产品主管部门会同有关部门规定。"},{"i":15,"n":"第十五条","txt":"机动车安全技术检验由机动车安全技术检验机构实施。机动车安全技术检验机构应当按照国家机动车安全技术检验标准对机动车进行检验，对检验结果承担法律责任。"},{"i":16,"n":"第十六条","txt":"机动车应当从注册登记之日起，按照下列期限进行安全技术检验："},{"i":17,"n":"第十七条","txt":"已注册登记的机动车进行安全技术检验时，机动车行驶证记载的登记内容与该机动车的有关情况不符，或者未按照规定提供机动车第三者责任强制保险凭证的，不予通过检验。"},{"i":18,"n":"第十八条","txt":"警车、消防车、救护车、工程救险车标志图案的喷涂以及警报器、标志灯具的安装、使用规定，由国务院公安部门制定。"},{"i":19,"n":"第十九条","txt":"符合国务院公安部门规定的驾驶许可条件的人，可以向公安机关交通管理部门申请机动车驾驶证。"},{"i":20,"n":"第二十条","txt":"学习机动车驾驶，应当先学习道路交通安全法律、法规和相关知识，考试合格后，再学习机动车驾驶技能。"},{"i":21,"n":"第二十一条","txt":"公安机关交通管理部门应当对申请机动车驾驶证的人进行考试，对考试合格的，在5日内核发机动车驾驶证；对考试不合格的，书面说明理由。"},{"i":22,"n":"第二十二条","txt":"机动车驾驶证的有效期为6年，本条例另有规定的除外。"},{"i":23,"n":"第二十三条","txt":"公安机关交通管理部门对机动车驾驶人的道路交通安全违法行为除给予行政处罚外，实行道路交通安全违法行为累积记分（以下简称记分）制度，记分周期为12个月。对在一个记分周期内记分达到12分的，由公安机关交通管理部门扣留其机动车驾驶证，该机动车驾驶人应当按照规定参加道路交通安全法律、法规的学习并接受考试。考试合格的，记分予以清除，发还机动车驾驶证；考试不合格的，继续参加学习和考试。"},{"i":24,"n":"第二十四条","txt":"机动车驾驶人在一个记分周期内记分未达到12分，所处罚款已经缴纳的，记分予以清除；记分虽未达到12分，但尚有罚款未缴纳的，记分转入下一记分周期。"},{"i":25,"n":"第二十五条","txt":"机动车驾驶人记分达到12分，拒不参加公安机关交通管理部门通知的学习，也不接受考试的，由公安机关交通管理部门公告其机动车驾驶证停止使用。"},{"i":26,"n":"第二十六条","txt":"机动车驾驶人在机动车驾驶证的6年有效期内，每个记分周期均未达到12分的，换发10年有效期的机动车驾驶证；在机动车驾驶证的10年有效期内，每个记分周期均未达到12分的，换发长期有效的机动车驾驶证。"},{"i":27,"n":"第二十七条","txt":"机动车驾驶证丢失、损毁，机动车驾驶人申请补发的，应当向公安机关交通管理部门提交本人身份证明和申请材料。公安机关交通管理部门经与机动车驾驶证档案核实后，在收到申请之日起3日内补发。"},{"i":28,"n":"第二十八条","txt":"机动车驾驶人在机动车驾驶证丢失、损毁、超过有效期或者被依法扣留、暂扣期间以及记分达到12分的，不得驾驶机动车。"},{"i":29,"n":"第二十九条","txt":"交通信号灯分为：机动车信号灯、非机动车信号灯、人行横道信号灯、车道信号灯、方向指示信号灯、闪光警告信号灯、道路与铁路平面交叉道口信号灯。"},{"i":30,"n":"第三十条","txt":"交通标志分为：指示标志、警告标志、禁令标志、指路标志、旅游区标志、道路施工安全标志和辅助标志。"},{"i":31,"n":"第三十一条","txt":"交通警察的指挥分为：手势信号和使用器具的交通指挥信号。"},{"i":32,"n":"第三十二条","txt":"道路交叉路口和行人横过道路较为集中的路段应当设置人行横道、过街天桥或者过街地下通道。"},{"i":33,"n":"第三十三条","txt":"城市人民政府有关部门可以在不影响行人、车辆通行的情况下，在城市道路上施划停车泊位，并规定停车泊位的使用时间。"},{"i":34,"n":"第三十四条","txt":"开辟或者调整公共汽车、长途汽车的行驶路线或者车站，应当符合交通规划和安全、畅通的要求。"},{"i":35,"n":"第三十五条","txt":"道路养护施工单位在道路上进行养护、维修时，应当按照规定设置规范的安全警示标志和安全防护设施。道路养护施工作业车辆、机械应当安装示警灯，喷涂明显的标志图案，作业时应当开启示警灯和危险报警闪光灯。对未中断交通的施工作业道路，公安机关交通管理部门应当加强交通安全监督检查。发生交通阻塞时，及时做好分流、疏导，维护交通秩序。"},{"i":36,"n":"第三十六条","txt":"道路或者交通设施养护部门、管理部门应当在急弯、陡坡、临崖、临水等危险路段，按照国家标准设置警告标志和安全防护设施。"},{"i":37,"n":"第三十七条","txt":"道路交通标志、标线不规范，机动车驾驶人容易发生辨认错误的，交通标志、标线的主管部门应当及时予以改善。"},{"i":38,"n":"第三十八条","txt":"机动车信号灯和非机动车信号灯表示："},{"i":39,"n":"第三十九条","txt":"人行横道信号灯表示："},{"i":40,"n":"第四十条","txt":"车道信号灯表示："},{"i":41,"n":"第四十一条","txt":"方向指示信号灯的箭头方向向左、向上、向右分别表示左转、直行、右转。"},{"i":42,"n":"第四十二条","txt":"闪光警告信号灯为持续闪烁的黄灯，提示车辆、行人通行时注意瞭望，确认安全后通过。"},{"i":43,"n":"第四十三条","txt":"道路与铁路平面交叉道口有两个红灯交替闪烁或者一个红灯亮时，表示禁止车辆、行人通行；红灯熄灭时，表示允许车辆、行人通行。"},{"i":44,"n":"第四十四条","txt":"在道路同方向划有2条以上机动车道的，左侧为快速车道，右侧为慢速车道。在快速车道行驶的机动车应当按照快速车道规定的速度行驶，未达到快速车道规定的行驶速度的，应当在慢速车道行驶。摩托车应当在最右侧车道行驶。有交通标志标明行驶速度的，按照标明的行驶速度行驶。慢速车道内的机动车超越前车时，可以借用快速车道行驶。"},{"i":45,"n":"第四十五条","txt":"机动车在道路上行驶不得超过限速标志、标线标明的速度。在没有限速标志、标线的道路上，机动车不得超过下列最高行驶速度："},{"i":46,"n":"第四十六条","txt":"机动车行驶中遇有下列情形之一的，最高行驶速度不得超过每小时30公里，其中拖拉机、电瓶车、轮式专用机械车不得超过每小时15公里："},{"i":47,"n":"第四十七条","txt":"机动车超车时，应当提前开启左转向灯、变换使用远、近光灯或者鸣喇叭。在没有道路中心线或者同方向只有1条机动车道的道路上，前车遇后车发出超车信号时，在条件许可的情况下，应当降低速度、靠右让路。后车应当在确认有充足的安全距离后，从前车的左侧超越，在与被超车辆拉开必要的安全距离后，开启右转向灯，驶回原车道。"},{"i":48,"n":"第四十八条","txt":"在没有中心隔离设施或者没有中心线的道路上，机动车遇相对方向来车时应当遵守下列规定："},{"i":49,"n":"第四十九条","txt":"机动车在有禁止掉头或者禁止左转弯标志、标线的地点以及在铁路道口、人行横道、桥梁、急弯、陡坡、隧道或者容易发生危险的路段，不得掉头。"},{"i":50,"n":"第五十条","txt":"机动车倒车时，应当察明车后情况，确认安全后倒车。不得在铁路道口、交叉路口、单行路、桥梁、急弯、陡坡或者隧道中倒车。"},{"i":51,"n":"第五十一条","txt":"机动车通过有交通信号灯控制的交叉路口，应当按照下列规定通行："},{"i":52,"n":"第五十二条","txt":"机动车通过没有交通信号灯控制也没有交通警察指挥的交叉路口，除应当遵守第五十一条第（二）项、第（三）项的规定外，还应当遵守下列规定："},{"i":53,"n":"第五十三条","txt":"机动车遇有前方交叉路口交通阻塞时，应当依次停在路口以外等候，不得进入路口。"},{"i":54,"n":"第五十四条","txt":"机动车载物不得超过机动车行驶证上核定的载质量，装载长度、宽度不得超出车厢，并应当遵守下列规定："},{"i":55,"n":"第五十五条","txt":"机动车载人应当遵守下列规定："},{"i":56,"n":"第五十六条","txt":"机动车牵引挂车应当符合下列规定："},{"i":57,"n":"第五十七条","txt":"机动车应当按照下列规定使用转向灯："},{"i":58,"n":"第五十八条","txt":"机动车在夜间没有路灯、照明不良或者遇有雾、雨、雪、沙尘、冰雹等低能见度情况下行驶时，应当开启前照灯、示廓灯和后位灯，但同方向行驶的后车与前车近距离行驶时，不得使用远光灯。机动车雾天行驶应当开启雾灯和危险报警闪光灯。"},{"i":59,"n":"第五十九条","txt":"机动车在夜间通过急弯、坡路、拱桥、人行横道或者没有交通信号灯控制的路口时，应当交替使用远近光灯示意。"},{"i":60,"n":"第六十条","txt":"机动车在道路上发生故障或者发生交通事故，妨碍交通又难以移动的，应当按照规定开启危险报警闪光灯并在车后50米至100米处设置警告标志，夜间还应当同时开启示廓灯和后位灯。"},{"i":61,"n":"第六十一条","txt":"牵引故障机动车应当遵守下列规定："},{"i":62,"n":"第六十二条","txt":"驾驶机动车不得有下列行为："},{"i":63,"n":"第六十三条","txt":"机动车在道路上临时停车，应当遵守下列规定："},{"i":64,"n":"第六十四条","txt":"机动车行经漫水路或者漫水桥时，应当停车察明水情，确认安全后，低速通过。"},{"i":65,"n":"第六十五条","txt":"机动车载运超限物品行经铁路道口的，应当按照当地铁路部门指定的铁路道口、时间通过。"},{"i":66,"n":"第六十六条","txt":"警车、消防车、救护车、工程救险车在执行紧急任务遇交通受阻时，可以断续使用警报器，并遵守下列规定："},{"i":67,"n":"第六十七条","txt":"在单位院内、居民居住区内，机动车应当低速行驶，避让行人；有限速标志的，按照限速标志行驶。"},{"i":68,"n":"第六十八条","txt":"非机动车通过有交通信号灯控制的交叉路口，应当按照下列规定通行："},{"i":69,"n":"第六十九条","txt":"非机动车通过没有交通信号灯控制也没有交通警察指挥的交叉路口，除应当遵守第六十八条第（一）项、第（二）项和第（三）项的规定外，还应当遵守下列规定："},{"i":70,"n":"第七十条","txt":"驾驶自行车、电动自行车、三轮车在路段上横过机动车道，应当下车推行，有人行横道或者行人过街设施的，应当从人行横道或者行人过街设施通过；没有人行横道、没有行人过街设施或者不便使用行人过街设施的，在确认安全后直行通过。"},{"i":71,"n":"第七十一条","txt":"非机动车载物，应当遵守下列规定："},{"i":72,"n":"第七十二条","txt":"在道路上驾驶自行车、三轮车、电动自行车、残疾人机动轮椅车应当遵守下列规定："},{"i":73,"n":"第七十三条","txt":"在道路上驾驭畜力车应当年满16周岁，并遵守下列规定："},{"i":74,"n":"第七十四条","txt":"行人不得有下列行为："},{"i":75,"n":"第七十五条","txt":"行人横过机动车道，应当从行人过街设施通过；没有行人过街设施的，应当从人行横道通过；没有人行横道的，应当观察来往车辆的情况，确认安全后直行通过，不得在车辆临近时突然加速横穿或者中途倒退、折返。"},{"i":76,"n":"第七十六条","txt":"行人列队在道路上通行，每横列不得超过2人，但在已经实行交通管制的路段不受限制。"},{"i":77,"n":"第七十七条","txt":"乘坐机动车应当遵守下列规定："},{"i":78,"n":"第七十八条","txt":"高速公路应当标明车道的行驶速度，最高车速不得超过每小时120公里，最低车速不得低于每小时60公里。"},{"i":79,"n":"第七十九条","txt":"机动车从匝道驶入高速公路，应当开启左转向灯，在不妨碍已在高速公路内的机动车正常行驶的情况下驶入车道。"},{"i":80,"n":"第八十条","txt":"机动车在高速公路上行驶，车速超过每小时100公里时，应当与同车道前车保持100米以上的距离，车速低于每小时100公里时，与同车道前车距离可以适当缩短，但最小距离不得少于50米。"},{"i":81,"n":"第八十一条","txt":"机动车在高速公路上行驶，遇有雾、雨、雪、沙尘、冰雹等低能见度气象条件时，应当遵守下列规定："},{"i":82,"n":"第八十二条","txt":"机动车在高速公路上行驶，不得有下列行为："},{"i":83,"n":"第八十三条","txt":"在高速公路上行驶的载货汽车车厢不得载人。两轮摩托车在高速公路行驶时不得载人。"},{"i":84,"n":"第八十四条","txt":"机动车通过施工作业路段时，应当注意警示标志，减速行驶。"},{"i":85,"n":"第八十五条","txt":"城市快速路的道路交通安全管理，参照本节的规定执行。"},{"i":86,"n":"第八十六条","txt":"机动车与机动车、机动车与非机动车在道路上发生未造成人身伤亡的交通事故，当事人对事实及成因无争议的，在记录交通事故的时间、地点、对方当事人的姓名和联系方式、机动车牌号、驾驶证号、保险凭证号、碰撞部位，并共同签名后，撤离现场，自行协商损害赔偿事宜。当事人对交通事故事实及成因有争议的，应当迅速报警。"},{"i":87,"n":"第八十七条","txt":"非机动车与非机动车或者行人在道路上发生交通事故，未造成人身伤亡，且基本事实及成因清楚的，当事人应当先撤离现场，再自行协商处理损害赔偿事宜。当事人对交通事故事实及成因有争议的，应当迅速报警。"},{"i":88,"n":"第八十八条","txt":"机动车发生交通事故，造成道路、供电、通讯等设施损毁的，驾驶人应当报警等候处理，不得驶离。机动车可以移动的，应当将机动车移至不妨碍交通的地点。公安机关交通管理部门应当将事故有关情况通知有关部门。"},{"i":89,"n":"第八十九条","txt":"公安机关交通管理部门或者交通警察接到交通事故报警，应当及时赶赴现场，对未造成人身伤亡，事实清楚，并且机动车可以移动的，应当在记录事故情况后责令当事人撤离现场，恢复交通。对拒不撤离现场的，予以强制撤离。"},{"i":90,"n":"第九十条","txt":"投保机动车第三者责任强制保险的机动车发生交通事故，因抢救受伤人员需要保险公司支付抢救费用的，由公安机关交通管理部门通知保险公司。"},{"i":91,"n":"第九十一条","txt":"公安机关交通管理部门应当根据交通事故当事人的行为对发生交通事故所起的作用以及过错的严重程度，确定当事人的责任。"},{"i":92,"n":"第九十二条","txt":"发生交通事故后当事人逃逸的，逃逸的当事人承担全部责任。但是，有证据证明对方当事人也有过错的，可以减轻责任。"},{"i":93,"n":"第九十三条","txt":"公安机关交通管理部门对经过勘验、检查现场的交通事故应当在勘查现场之日起10日内制作交通事故认定书。对需要进行检验、鉴定的，应当在检验、鉴定结果确定之日起5日内制作交通事故认定书。"},{"i":94,"n":"第九十四条","txt":"当事人对交通事故损害赔偿有争议，各方当事人一致请求公安机关交通管理部门调解的，应当在收到交通事故认定书之日起10日内提出书面调解申请。"},{"i":95,"n":"第九十五条","txt":"公安机关交通管理部门调解交通事故损害赔偿争议的期限为10日。调解达成协议的，公安机关交通管理部门应当制作调解书送交各方当事人，调解书经各方当事人共同签字后生效；调解未达成协议的，公安机关交通管理部门应当制作调解终结书送交各方当事人。"},{"i":96,"n":"第九十六条","txt":"对交通事故损害赔偿的争议，当事人向人民法院提起民事诉讼的，公安机关交通管理部门不再受理调解申请。"},{"i":97,"n":"第九十七条","txt":"车辆在道路以外发生交通事故，公安机关交通管理部门接到报案的，参照道路交通安全法和本条例的规定处理。"},{"i":98,"n":"第九十八条","txt":"公安机关交通管理部门应当公开办事制度、办事程序，建立警风警纪监督员制度，自觉接受社会和群众的监督。"},{"i":99,"n":"第九十九条","txt":"公安机关交通管理部门及其交通警察办理机动车登记，发放号牌，对驾驶人考试、发证，处理道路交通安全违法行为，处理道路交通事故，应当严格遵守有关规定，不得越权执法，不得延迟履行职责，不得擅自改变处罚的种类和幅度。"},{"i":100,"n":"第一百条","txt":"公安机关交通管理部门应当公布举报电话，受理群众举报投诉，并及时调查核实，反馈查处结果。"},{"i":101,"n":"第一百零一条","txt":"公安机关交通管理部门应当建立执法质量考核评议、执法责任制和执法过错追究制度，防止和纠正道路交通安全执法中的错误或者不当行为。"},{"i":102,"n":"第一百零二条","txt":"违反本条例规定的行为，依照道路交通安全法和本条例的规定处罚。"},{"i":103,"n":"第一百零三条","txt":"以欺骗、贿赂等不正当手段取得机动车登记或者驾驶许可的，收缴机动车登记证书、号牌、行驶证或者机动车驾驶证，撤销机动车登记或者机动车驾驶许可；申请人在3年内不得申请机动车登记或者机动车驾驶许可。"},{"i":104,"n":"第一百零四条","txt":"机动车驾驶人有下列行为之一，又无其他机动车驾驶人即时替代驾驶的，公安机关交通管理部门除依法给予处罚外，可以将其驾驶的机动车移至不妨碍交通的地点或者有关部门指定的地点停放："},{"i":105,"n":"第一百零五条","txt":"机动车驾驶人有饮酒、醉酒、服用国家管制的精神药品或者麻醉药品嫌疑的，应当接受测试、检验。"},{"i":106,"n":"第一百零六条","txt":"公路客运载客汽车超过核定乘员、载货汽车超过核定载质量的，公安机关交通管理部门依法扣留机动车后，驾驶人应当将超载的乘车人转运、将超载的货物卸载，费用由超载机动车的驾驶人或者所有人承担。"},{"i":107,"n":"第一百零七条","txt":"依照道路交通安全法第九十二条、第九十五条、第九十六条、第九十八条的规定被扣留的机动车，驾驶人或者所有人、管理人30日内没有提供被扣留机动车的合法证明，没有补办相应手续，或者不前来接受处理，经公安机关交通管理部门通知并且经公告3个月仍不前来接受处理的，由公安机关交通管理部门将该机动车送交有资格的拍卖机构拍卖，所得价款上缴国库；非法拼装的机动车予以拆除；达到报废标准的机动车予以报废；机动车涉及其他违法犯罪行为的，移交有关部门处理。"},{"i":108,"n":"第一百零八条","txt":"交通警察按照简易程序当场作出行政处罚的，应当告知当事人道路交通安全违法行为的事实、处罚的理由和依据，并将行政处罚决定书当场交付被处罚人。"},{"i":109,"n":"第一百零九条","txt":"对道路交通安全违法行为人处以罚款或者暂扣驾驶证处罚的，由违法行为发生地的县级以上人民政府公安机关交通管理部门或者相当于同级的公安机关交通管理部门作出决定；对处以吊销机动车驾驶证处罚的，由设区的市人民政府公安机关交通管理部门或者相当于同级的公安机关交通管理部门作出决定。"},{"i":110,"n":"第一百一十条","txt":"当事人对公安机关交通管理部门及其交通警察的处罚有权进行陈述和申辩，交通警察应当充分听取当事人的陈述和申辩，不得因当事人陈述、申辩而加重其处罚。"},{"i":111,"n":"第一百一十一条","txt":"本条例所称上道路行驶的拖拉机，是指手扶拖拉机等最高设计行驶速度不超过每小时20公里的轮式拖拉机和最高设计行驶速度不超过每小时40公里、牵引挂车方可从事道路运输的轮式拖拉机。"},{"i":112,"n":"第一百一十二条","txt":"农业（农业机械）主管部门应当定期向公安机关交通管理部门提供拖拉机登记、安全技术检验以及拖拉机驾驶证发放的资料、数据。公安机关交通管理部门对拖拉机驾驶人作出暂扣、吊销驾驶证处罚或者记分处理的，应当定期将处罚决定书和记分情况通报有关的农业（农业机械）主管部门。吊销驾驶证的，还应当将驾驶证送交有关的农业（农业机械）主管部门。"},{"i":113,"n":"第一百一十三条","txt":"境外机动车入境行驶，应当向入境地的公安机关交通管理部门申请临时通行号牌、行驶证。临时通行号牌、行驶证应当根据行驶需要，载明有效日期和允许行驶的区域。"},{"i":114,"n":"第一百一十四条","txt":"机动车驾驶许可考试的收费标准，由国务院价格主管部门规定。"},{"i":115,"n":"第一百一十五条","txt":"本条例自2004年5月1日起施行。1960年2月11日国务院批准、交通部发布的《机动车管理办法》，1988年3月9日国务院发布的《中华人民共和国道路交通管理条例》，1991年9月22日国务院发布的《道路交通事故处理办法》，同时废止。"}],"youzhengfashishixize":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国邮政法》（以下简称《邮政法》）的规定，制定本实施细则。"},{"i":2,"n":"第二条","txt":"中华人民共和国邮电部（以下简称邮电部）是国务院邮政主管部门，管理全国邮政工作。"},{"i":3,"n":"第三条","txt":"市、县邮电局（含邮政局，下同）是全民所有制的经营邮政业务的公用企业（以下简称邮政企业），经邮电管理局授权，管理该地区的邮政工作。"},{"i":4,"n":"第四条","txt":"未经邮政企业委托，任何单位或者个人不得经营信函、明信片或者其他具有信件性质的物品的寄递业务，但国务院另有规定的除外。"},{"i":5,"n":"第五条","txt":"邮政企业委托其他单位或者个人代办邮政业务时，应当协商一致，并签订代办合同。"},{"i":6,"n":"第六条","txt":"凡使用我国邮政业务的一切单位或者个人统称邮政用户（以下简称用户）。"},{"i":7,"n":"第七条","txt":"邮政企业应当为用户提供迅速、准确、安全、方便的邮政服务，保障用户使用邮政的合法权益。"},{"i":8,"n":"第八条","txt":"因国家安全或者追查刑事犯罪需要，公安机关、国家安全机关、检察机关检查、扣留邮件，冻结汇款、储蓄存款时，必须依法向相关县或者县级以上的邮政企业、邮电管理局出具相应的检查、扣留、冻结通知书，并开列邮件、汇款、储蓄存款的具体节目，办理检查、扣留、冻结手续后，由邮政企业指派专人负责拣出，逐件登记后办理交接手续；对于不需要继续检查、扣留、冻结或者查明与案件无关的邮件、汇款、储蓄存款，应当及时退还邮政企业。邮件、汇款、储蓄存款在检查、扣留、冻结期间造成丢失、损毁的，由相关的公安机关、国家安全机关、检察机关负责赔偿。"},{"i":9,"n":"第九条","txt":"人民法院、检察机关依法没收国内邮件、汇款、储蓄存款时，必须出具法律文书，向相关县或者县级以上邮政企业、邮电管理局办理手续。没收进出口国际邮递物品应当由海关作出决定，并办理手续。"},{"i":10,"n":"第十条","txt":"有关单位依照法律规定需要收集、调取证据、查阅邮政业务档案时，必须凭相关邮政企业所在地的公安机关、国家安全机关、检察机关、人民法院出具的书面证明，并开列邮件具体节目，向相关县或者县级以上的邮政企业、邮电管理局办理手续。"},{"i":11,"n":"第十一条","txt":"任何单位或者个人不得从事下列行为妨害邮政工作的正常进行："},{"i":12,"n":"第十二条","txt":"邮政企业及分支机构的设置标准，由邮电部规定；邮政企业的设置或者撤销，由邮电部批准；分支机构的设置或者撤销，由邮电管理局批准，报邮电部备案。"},{"i":13,"n":"第十三条","txt":"地方各级人民政府应当将邮政企业及分支机构的设置和邮政设施的建设纳入城乡建设规划。"},{"i":14,"n":"第十四条","txt":"建设城市新区、独立工矿区、住宅区或者旧城区成片改造，应当同时规划和设置与之配套的邮政企业及分支机构和邮政设施。"},{"i":15,"n":"第十五条","txt":"邮政企业依法设置邮亭、邮政报刊亭、邮筒、信箱或者流动服务时，有关单位或者个人应当提供方便。"},{"i":16,"n":"第十六条","txt":"接收邮件的信报箱是居民楼房的配套设施，设计单位应当将其纳入民用住宅建筑设计标准。"},{"i":17,"n":"第十七条","txt":"较大的车站、机场、港口、饭店，应当在方便旅客的地方提供办理邮政业务的场所；邮政企业应当提供邮政业务服务。"},{"i":18,"n":"第十八条","txt":"任何单位因建设需要，征用、拆迁邮政企业及分支机构或者邮政设施时，应当与当地邮政企业协商，在保证邮政通信正常进行的情况下，应当将邮政企业及分支机构、邮政设施迁至适宜的地方或者另建，所需费用由征用、拆迁单位承担。"},{"i":19,"n":"第十九条","txt":"邮政企业经营国内、国际邮件的寄递业务和邮件的特快专递业务。"},{"i":20,"n":"第二十条","txt":"国内报刊发行业务是指报刊社委托邮政企业发行报纸、杂志的业务。"},{"i":21,"n":"第二十一条","txt":"报刊社委托邮政企业发行报刊时，应当根据报刊发行的范围向指定的邮政企业或者邮政报刊发行局，出具有关主管部门批准出版和领有报纸、期刊登记证的证明。邮政企业有接办发行能力的，应当与报刊社遵循平等互利、协商一致、等价有偿的原则，按照国家有关规定签订报刊发行合同。"},{"i":22,"n":"第二十二条","txt":"邮政储蓄、邮政汇兑业务是邮政企业为国家积聚资金、沟通经济往来所经办的金融业务，由邮电部统一管理，并按照国家有关规定，在金融业务上接受中国人民银行的指导。各相关银行应当为邮政企业办理的储蓄、汇兑业务提供便利。"},{"i":23,"n":"第二十三条","txt":"各项邮政业务的具体种类和邮件分类，由邮电部规定。"},{"i":24,"n":"第二十四条","txt":"邮政业务的基本资费是指邮政专营的国内平常信函、明信片的资费；非基本资费是指基本资费以外的邮政业务资费。"},{"i":25,"n":"第二十五条","txt":"制定和调整邮政业务资费的依据是："},{"i":26,"n":"第二十六条","txt":"邮资凭证是邮电部发行的，作为邮件纳费标志的有价证券，包括邮票，印在邮资信封、邮资明信片、邮资邮简上的邮票图案，邮资机打印的邮资符志。"},{"i":27,"n":"第二十七条","txt":"“万国邮政联盟”发行的国际回信券，可以根据国际统一规定，兑换成等于特定重量级别的特定类别资费的邮票，但是不得兑换现金。"},{"i":28,"n":"第二十八条","txt":"因工作需要，仿印邮票图案的，必须按照仿印邮票图案的有关规定，报经邮电部邮票主管部门或者有关邮电管理局审核、批准。"},{"i":29,"n":"第二十九条","txt":"印制通信使用的信封必须符合国家标准，并由当地邮电管理局监制。"},{"i":30,"n":"第三十条","txt":"印制明信片必须符合邮电部规定的规格标准。"},{"i":31,"n":"第三十一条","txt":"义务兵从部队发出的平常信函，免费寄递，其他军人不得免费寄递信函。义务兵寄递平常信函的监督管理办法由邮电部会同中国人民解放军有关部门制定。"},{"i":32,"n":"第三十二条","txt":"用户交寄邮件应当符合邮电部规定的准寄内容、封装规格、书写格式，并正确书写邮政编码，其中，用户交寄信函使用的信封，必须符合国家标准；邮件封面和邮政业务单式上不得印（写）有或者粘贴与邮件无关的文字或者其他物品；邮资凭证正面不得涂抹、覆盖其他物品；不得使用伪造、仿印、剪割拼补、加工去污的邮资凭证。"},{"i":33,"n":"第三十三条","txt":"禁止寄递或者在邮件内夹带下列物品："},{"i":34,"n":"第三十四条","txt":"国内限量寄递物品由邮电部会同国务院有关部门规定。"},{"i":35,"n":"第三十五条","txt":"对于违反禁寄、限寄规定寄递的物品，邮政企业或者分支机构应当根据其种类、性质、数量等分别作出下列处理："},{"i":36,"n":"第三十六条","txt":"新建的企业、事业、居民住宅，应当由单位或者居民住宅的主管部门到当地邮政企业或者分支机构办理邮件投递登记手续；单位更改名称、收件人变更地址，应当事先通知当地邮政企业或者分支机构，也可以办理邮件改寄新址手续。邮政企业应当公布登记地点和电话号码。"},{"i":37,"n":"第三十七条","txt":"邮件的投递方式，除邮电部另有规定外，按下列方式投递："},{"i":38,"n":"第三十八条","txt":"收件人领取给据邮件，收款人兑领汇款，应当向相关邮政企业或者分支机构交验本人有效证件，并在相关单式上盖章或者签名。"},{"i":39,"n":"第三十九条","txt":"收件人接收给据邮件时发现封皮破损，应当场声明，并核对内件。确属邮政企业或者分支机构的责任而造成内件短少、损毁的，或者由于邮政企业、分支机构的责任造成给据邮件丢失、损毁的，邮政企业或者分支机构应当按照规定予以赔偿。由于收件人所在单位收发人员的过失造成给据邮件丢失、损毁、内件短少者，相关收发人员应当承担规定的赔偿责任。"},{"i":40,"n":"第四十条","txt":"用户误收的邮件，应当及时退还邮政企业或者分支机构；用户误拆的邮件应当重封签章后退还邮政企业或者分支机构，并对误拆邮件的内容保守秘密。"},{"i":41,"n":"第四十一条","txt":"单位收发人员接收给据邮件时，应当认真点核无误后，在相关清单上盖章签收。"},{"i":42,"n":"第四十二条","txt":"邮电部、邮电管理局应当把邮件运输流向流量变化情况及时通告相关运输部门。各运输部门应当根据邮政通信需要，优先提供有效的车次、航班、舱容。"},{"i":43,"n":"第四十三条","txt":"邮政企业委托运输单位运送邮件，应当签订运邮协议。"},{"i":44,"n":"第四十四条","txt":"运输单位承运的邮件应当先于货物发运。因故临时停运或者改变运行时间、停靠位置时，运输单位应当及时通知邮政企业或者分支机构。"},{"i":45,"n":"第四十五条","txt":"载有邮件的船舶应当悬挂邮旗，各有关港口对于悬挂邮旗的船舶应当优先放行。"},{"i":46,"n":"第四十六条","txt":"运输单位承运邮件，除邮政企业或者分支机构派员押运者外，应当与邮政企业或者分支机构办理交接签收手续。"},{"i":47,"n":"第四十七条","txt":"执行邮件运输和投递任务的车、船、邮政工作人员通过桥梁、渡口、隧道、检查站时，有关方面应当优先放行。带有邮政专用标志的邮政车辆在运递邮件时，凭公安机关核发的通行证，可以不受禁行路线、禁停地段的限制。运邮车辆或者邮政工作人员在运递邮件途中违章，有关主管部门应当记录后放行，待其完成运递任务后，再行处理。"},{"i":48,"n":"第四十八条","txt":"邮政企业依据运输工具到站（港）、离站（港）时间和运递时限制订的作业时间表应当在变更前三日通知海关。海关应当按照邮政企业通知的作业时间表派员到场监管国际邮袋、查验进出口国际邮递物品；逾时不到场，延误运递时限造成的相关责任，由海关承担。"},{"i":49,"n":"第四十九条","txt":"用户交寄应当施行卫生检疫或者动植物检疫的邮件，必须附有检疫证书。检疫部门应当及时对邮件进行验放，以保证邮件的运递时限。"},{"i":50,"n":"第五十条","txt":"海关、检疫部门依法查验国际邮递物品或者检疫邮件，应当注意爱护；需要封存时，除向寄件人或者收件人发出通知外，应当同邮政企业或者分支机构履行交接手续，并负责保管，封存期不得超过四十五日。特殊情况需要延长封存期的，应当征得邮政企业或者分支机构及寄件人或者收件人的同意，并以不致造成被封存国际邮递物品或者邮件的损失为前提。被封存国际邮递物品或者邮件退还邮政企业或者分支机构时，邮政工作人员应当核对无误后予以签收。"},{"i":51,"n":"第五十一条","txt":"依法查验邮递物品或者对邮件实施检疫需要使用邮政企业或者分支机构的场地和房屋时，由邮政企业与有关部门根据工作需要和实际可能协商解决。"},{"i":52,"n":"第五十二条","txt":"由海关依法处理的无着进口国际邮包，海关应当支付相关邮政费用。"},{"i":53,"n":"第五十三条","txt":"出口国际邮件的海关关单的传递方式由海关总署与邮电部商定。"},{"i":54,"n":"第五十四条","txt":"违反本细则第十一条规定的，由有关部门按照国家有关规定根据情节轻重，予以处罚；违反治安管理有关规定的，由公安机关依照《中华人民共和国治安管理处罚条例》处罚。"},{"i":55,"n":"第五十五条","txt":"违反本细则第三十三条第三项规定，尚未造成严重后果的，由公安机关依照《中华人民共和国治安管理处罚条例》处理。"},{"i":56,"n":"第五十六条","txt":"伪造或者冒用邮政专用标志、邮政标志服或者邮政日戳、邮政夹钳、邮袋等邮政专用品的，由邮电管理局或其授权单位处以一千五百元以下罚款，并没收有关物品。"},{"i":57,"n":"第五十七条","txt":"以营利为目的，伪造邮资凭证，未经许可仿印邮票图案或者印制带有“中国人民邮政”字样明信片的，由邮电管理局或其授权单位处以五千元以下罚款，并没收非法所得和非法物品。"},{"i":58,"n":"第五十八条","txt":"邮政工作人员隐匿、毁弃、私拆、盗窃邮件，贪污、冒领用户款项的，邮政企业应当追回赃款赃物，可以并处罚款，还可以根据情节轻重，给予行政处分。具体办法由邮电部规定。"},{"i":59,"n":"第五十九条","txt":"违反本细则第四十一条第二款规定的，依照《邮政法》第三十六条规定追究责任。"},{"i":60,"n":"第六十条","txt":"违反本细则规定，构成犯罪的，由司法机关依法追究刑事责任。"},{"i":61,"n":"第六十一条","txt":"误收、误拆他人信件不予退还或者已退还但泄露信件内容，侵犯他人通信自由权利的，依照《邮政法》第三十六条规定追究责任。"},{"i":62,"n":"第六十二条","txt":"本细则所称公安机关、国家安全机关、检察机关是指县以上（含县级）公安机关、国家安全机关、检察机关。"},{"i":63,"n":"第六十三条","txt":"邮电部可以根据本细则制定有关规章。"},{"i":64,"n":"第六十四条","txt":"本细则由邮电部负责解释。"},{"i":65,"n":"第六十五条","txt":"本细则自发布之日起施行。"}],"jihuiyouxingshiweifashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国集会游行示威法》（以下简称《集会游行示威法》），制定本条例。"},{"i":2,"n":"第二条","txt":"各级人民政府应当依法保障公民行使集会、游行、示威的权利，维护社会安定和公共秩序，保障依法举行的集会、游行、示威不受任何人以暴力、胁迫或者其他非法手段进行扰乱、冲击和破坏。"},{"i":3,"n":"第三条","txt":"《集会游行示威法》第二条所称露天公共场所是指公众可以自由出入的或者凭票可以进入的室外公共场所，不包括机关、团体、企业事业组织管理的内部露天场所；公共道路是指除机关、团体、企业事业组织内部的专用道路以外的道路和水路。"},{"i":4,"n":"第四条","txt":"文娱、体育活动，正常的宗教活动，传统的民间习俗活动，由各级人民政府或者有关主管部门依照有关的法律、法规和国家其他有关规定进行管理。"},{"i":5,"n":"第五条","txt":"《集会游行示威法》第五条所称武器是指各种枪支、弹药以及其他可用于伤害人身的器械；管制刀具是指匕首、三棱刀、弹簧刀以及其他依法管制的刀具；爆炸物是指具有爆发力和破坏性能，瞬间可以造成人员伤亡、物品毁损的一切爆炸物品。"},{"i":6,"n":"第六条","txt":"依照《集会游行示威法》第七条第二款的规定，举行不需要申请的活动，应当维护交通秩序和社会秩序。"},{"i":7,"n":"第七条","txt":"集会、游行、示威由举行地的市、县公安局、城市公安分局主管。"},{"i":8,"n":"第八条","txt":"举行集会、游行、示威，必须有负责人。"},{"i":9,"n":"第九条","txt":"举行集会、游行、示威，必须由其负责人向本条例第七条规定的主管公安机关亲自递交书面申请；不是由负责人亲自递交书面申请的，主管公安机关不予受理。"},{"i":10,"n":"第十条","txt":"主管公安机关接到集会、游行、示威的申请书后，应当及时审查，在法定期限内作出许可或者不许可的书面决定；决定书应当载明许可的内容，或者不许可的理由。"},{"i":11,"n":"第十一条","txt":"申请举行集会、游行、示威要求解决具体问题的，主管公安机关应当自接到申请书之日起2日内将《协商解决具体问题通知书》分别送交集会、游行、示威的负责人和有关机关或者单位，必要时可以同时送交有关机关或者单位的上级主管部门。有关机关或者单位和申请集会、游行、示威的负责人，应当自接到公安机关的《协商解决具体问题通知书》的次日起2日内进行协商。达成协议的，协议书经双方负责人签字后，由有关机关或者单位及时送交主管公安机关；未达成协议或者自接到《协商解决具体问题通知书》的次日起2日内未进行协商，申请人坚持举行集会、游行、示威的，有关机关或者单位应当及时通知主管公安机关，主管公安机关应当依照本条例第十条规定的程序及时作出许可或者不许可的决定。"},{"i":12,"n":"第十二条","txt":"依照《集会游行示威法》第十五条的规定，公民不得在其居住地以外的城市发动、组织、参加当地公民的集会、游行、示威。本条所称居住地，是指公民常住户口所在地或者向暂住地户口登记机关办理了暂住登记并持续居住半年以上的地方。"},{"i":13,"n":"第十三条","txt":"主管公安机关接到举行集会、游行、示威的申请书后，在决定许可时，有下列情形之一的，可以变更举行集会、游行、示威的时间、地点、路线，并及时通知其负责人："},{"i":14,"n":"第十四条","txt":"集会、游行、示威的负责人对主管公安机关不许可的决定不服的，可以自接到不许可决定书之日起3日内向同级人民政府申请复议。人民政府应当自接到复议申请书之日起3日内作出维持或者撤销主管公安机关原决定的复议决定，并将《集会游行示威复议决定书》送达集会、游行、示威的负责人，同时将副本送作出原决定的主管公安机关。人民政府作出的复议决定，主管公安机关和集会、游行、示威的负责人必须执行。"},{"i":15,"n":"第十五条","txt":"集会、游行、示威的负责人在提出申请后接到主管公安机关的通知前，撤回申请的，应当及时到受理申请的主管公安机关办理撤回手续。"},{"i":16,"n":"第十六条","txt":"以国家机关、社会团体、企业事业组织的名义组织或者参加集会、游行、示威的，其负责人在递交申请书时，必须同时递交该国家机关、社会团体、企业事业组织负责人签署并加盖公章的证明文件。"},{"i":17,"n":"第十七条","txt":"对依法举行的集会，公安机关应当根据实际需要，派出人民警察维持秩序，保障集会的顺利举行。"},{"i":18,"n":"第十八条","txt":"负责维持交通秩序和社会秩序的人民警察，由主管公安机关指派的现场负责人统一指挥。人民警察现场负责人应当同集会、游行、示威的负责人保持联系。"},{"i":19,"n":"第十九条","txt":"游行队伍在行进中遇有前方路段临时发生自然灾害事故、交通事故及其他治安灾害事故，或者游行队伍之间、游行队伍与围观群众之间发生严重冲突和混乱，以及突然发生其他不可预料的情况，致使游行队伍不能按照许可的路线行进时，人民警察现场负责人有权临时决定改变游行队伍的行进路线。"},{"i":20,"n":"第二十条","txt":"主管公安机关临时设置的警戒线，应当有明显的标志，必要时还可以设置障碍物。"},{"i":21,"n":"第二十一条","txt":"《集会游行示威法》第二十三条所列不得举行集会、游行、示威的场所的周边距离，是指自上述场所的建筑物周边向外扩展的距离；有围墙或者栅栏的，从围墙或者栅栏的周边开始计算。不得举行集会、游行、示威的场所具体周边距离，由省、自治区、直辖市人民政府规定并予以公布。"},{"i":22,"n":"第二十二条","txt":"集会、游行、示威的负责人必须负责维持集会、游行、示威的秩序，遇有其他人加入集会、游行、示威队伍的，应当进行劝阻；对不听劝阻的，应当立即报告现场维持秩序的人民警察。人民警察接到报告后，应当予以制止。"},{"i":23,"n":"第二十三条","txt":"依照《集会游行示威法》第二十七条的规定，对非法举行集会、游行、示威或者在集会、游行、示威进行中出现危害公共安全或者严重破坏社会秩序情况的，人民警察有权立即予以制止。对不听制止，需要命令解散的，应当通过广播、喊话等明确方式告知在场人员在限定时间内按照指定通道离开现场。对在限定时间内拒不离去的，人民警察现场负责人有权依照国家有关规定，命令使用警械或者采用其他警用手段强行驱散；对继续滞留现场的人员，可以强行带离现场或者立即予以拘留。"},{"i":24,"n":"第二十四条","txt":"拒绝、阻碍人民警察依法执行维持交通秩序和社会秩序职务，应当给予治安管理处罚的，依照治安管理处罚法的规定予以处罚；构成犯罪的，依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"依照《集会游行示威法》第二十九条、第三十条的规定，需要依法追究刑事责任的，由举行地主管公安机关依照刑事诉讼法规定的程序办理。"},{"i":26,"n":"第二十六条","txt":"依照《集会游行示威法》第三十三条的规定予以拘留的，公安机关应当在24小时内进行讯问；需要强行遣回原地的，由行为地的主管公安机关制作《强行遣送决定书》，并派人民警察执行。负责执行的人民警察应当将被遣送人送回其居住地，连同《强行遣送决定书》交给被遣送人居住地公安机关，由居住地公安机关依法处理。"},{"i":27,"n":"第二十七条","txt":"依照《集会游行示威法》第二十八条、第三十条以及本条例第二十四条的规定，对当事人给予治安管理处罚的，依照治安管理处罚法规定的程序，由行为地公安机关决定和执行。被处罚人对处罚决定不服的，可以申请复议；对上一级公安机关的复议决定不服的，可以依照法律规定向人民法院提起诉讼。"},{"i":28,"n":"第二十八条","txt":"对于依照《集会游行示威法》第二十七条的规定被强行带离现场或者立即予以拘留的，公安机关应当在24小时以内进行讯问。不需要追究法律责任的，可以令其具结悔过后释放；需要追究法律责任的，依照有关法律规定办理。"},{"i":29,"n":"第二十九条","txt":"在举行集会、游行、示威的过程中，破坏公私财物或者侵害他人身体造成伤亡的，应当依法承担赔偿责任。"},{"i":30,"n":"第三十条","txt":"外国人在中国境内举行集会、游行、示威，适用本条例的规定。"},{"i":31,"n":"第三十一条","txt":"省、自治区、直辖市的人民代表大会常务委员会根据《集会游行示威法》制定的实施办法适用于本行政区域；与本条例相抵触的，以本条例为准。"},{"i":32,"n":"第三十二条","txt":"本条例具体应用中的问题由公安部负责解释。"},{"i":33,"n":"第三十三条","txt":"本条例自发布之日起施行。"}],"feijidongchuanbohaishanganquanhangxingzanxingguize":[{"i":1,"n":"第一条","txt":"凡使用人力、风力、拖力的非机动船，在海上从事运输、捕鱼或者其他工作，都应当遵守本规则。"},{"i":2,"n":"第二条","txt":"非机动船在夜间航行、锚泊的时候，应当在容易被看见的地方，悬挂明亮的白光环照灯一盏。如果因为天气恶劣或者受设备的限制，不能固定悬挂白光环照灯，必须将灯点好放在手边，以备应用；在与他船接近的时候，应当及早显示灯光或者手电筒的白色闪光或者火光，以防碰撞。"},{"i":3,"n":"第三条","txt":"非机动渔船，在白昼捕鱼的时候，应当在容易被看见的地方，悬挂竹篮一只，当发现他船驶近的时候，应当用适当信号指示渔具延伸方向；使用流网的渔船，还要在流网延伸末端的浮子上，系小红旗一面；在夜间捕鱼的时候，应当在容易被看见的地方，悬挂明亮的白光环照灯一盏，当发现他船驶近的时候，向渔具延伸方向，显示另一白光。"},{"i":4,"n":"第四条","txt":"非机动船在有雾、下雪、暴风雨或者其他任何视线不清楚的情况下，不论白昼或者夜间，都应当执行下列规定："},{"i":5,"n":"第五条","txt":"两艘帆船相互驶近，如有碰撞的危险，应当依照下列规定避让："},{"i":6,"n":"第六条","txt":"在航行中的非机动船，应当避让用网、曳绳钓或者拖网进行捕鱼作业的非机动渔船。"},{"i":7,"n":"第七条","txt":"非机动船应当避让下列的机动船："},{"i":8,"n":"第八条","txt":"非机动船与机动船相互驶近，如有碰撞危险，机动船应当避让非机动船。"},{"i":9,"n":"第九条","txt":"非机动船在海上遇难，需要他船或者岸上援救的时候，应当显示下列信号："},{"i":10,"n":"第十条","txt":"本规则经国务院批准后，由交通部、水产部联合发布施行。"}],"yusuanfashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国预算法》（以下简称预算法），制定本条例。"},{"i":2,"n":"第二条","txt":"县级以上地方政府的派出机关根据本级政府授权进行预算管理活动，不作为一级预算，其收支纳入本级预算。"},{"i":3,"n":"第三条","txt":"社会保险基金预算应当在精算平衡的基础上实现可持续运行，一般公共预算可以根据需要和财力适当安排资金补充社会保险基金预算。"},{"i":4,"n":"第四条","txt":"预算法第六条第二款所称各部门，是指与本级政府财政部门直接发生预算缴拨款关系的国家机关、军队、政党组织、事业单位、社会团体和其他单位。"},{"i":5,"n":"第五条","txt":"各部门预算应当反映一般公共预算、政府性基金预算、国有资本经营预算安排给本部门及其所属各单位的所有预算资金。"},{"i":6,"n":"第六条","txt":"一般性转移支付向社会公开应当细化到地区。专项转移支付向社会公开应当细化到地区和项目。"},{"i":7,"n":"第七条","txt":"预算法第十五条所称中央和地方分税制，是指在划分中央与地方事权的基础上，确定中央与地方财政支出范围，并按税种划分中央与地方预算收入的财政管理体制。"},{"i":8,"n":"第八条","txt":"县级以上地方各级政府应当根据中央和地方分税制的原则和上级政府的有关规定，确定本级政府对下级政府的财政管理体制。"},{"i":9,"n":"第九条","txt":"预算法第十六条第二款所称一般性转移支付，包括："},{"i":10,"n":"第十条","txt":"预算法第十六条第三款所称专项转移支付，是指上级政府为了实现特定的经济和社会发展目标给予下级政府，并由下级政府按照上级政府规定的用途安排使用的预算资金。"},{"i":11,"n":"第十一条","txt":"预算收入和预算支出以人民币元为计算单位。预算收支以人民币以外的货币收纳和支付的，应当折合成人民币计算。"},{"i":12,"n":"第十二条","txt":"预算法第二十七条第一款所称行政事业性收费收入，是指国家机关、事业单位等依照法律法规规定，按照国务院规定的程序批准，在实施社会公共管理以及在向公民、法人和其他组织提供特定公共服务过程中，按照规定标准向特定对象收取费用形成的收入。"},{"i":13,"n":"第十三条","txt":"转移性支出包括上解上级支出、对下级的税收返还和转移支付、调出资金以及按照财政部规定列入转移性支出的给予无隶属关系政府的无偿援助。"},{"i":14,"n":"第十四条","txt":"政府性基金预算收入包括政府性基金各项目收入和转移性收入。"},{"i":15,"n":"第十五条","txt":"国有资本经营预算收入包括依照法律、行政法规和国务院规定应当纳入国有资本经营预算的国有独资企业和国有独资公司按照规定上缴国家的利润收入、从国有资本控股和参股公司获得的股息红利收入、国有产权转让收入、清算收入和其他收入。"},{"i":16,"n":"第十六条","txt":"社会保险基金预算收入包括各项社会保险费收入、利息收入、投资收益、一般公共预算补助收入、集体补助收入、转移收入、上级补助收入、下级上解收入和其他收入。"},{"i":17,"n":"第十七条","txt":"地方各级预算上下级之间有关收入和支出项目的划分以及上解、返还或者转移支付的具体办法，由上级地方政府规定，报本级人民代表大会常务委员会备案。"},{"i":18,"n":"第十八条","txt":"地方各级社会保险基金预算上下级之间有关收入和支出项目的划分以及上解、补助的具体办法，按照统筹层次由上级地方政府规定，报本级人民代表大会常务委员会备案。"},{"i":19,"n":"第十九条","txt":"预算法第三十一条所称预算草案，是指各级政府、各部门、各单位编制的未经法定程序审查和批准的预算。"},{"i":20,"n":"第二十条","txt":"预算法第三十二条第一款所称绩效评价，是指根据设定的绩效目标，依据规范的程序，对预算资金的投入、使用过程、产出与效果进行系统和客观的评价。"},{"i":21,"n":"第二十一条","txt":"预算法第三十二条第三款所称预算支出标准，是指对预算事项合理分类并分别规定的支出预算编制标准，包括基本支出标准和项目支出标准。"},{"i":22,"n":"第二十二条","txt":"财政部于每年6月15日前部署编制下一年度预算草案的具体事项，规定报表格式、编报方法、报送期限等。"},{"i":23,"n":"第二十三条","txt":"中央各部门应当按照国务院的要求和财政部的部署，结合本部门的具体情况，组织编制本部门及其所属各单位的预算草案。"},{"i":24,"n":"第二十四条","txt":"财政部审核中央各部门的预算草案，具体编制中央预算草案；汇总地方预算草案或者地方预算，汇编中央和地方预算草案。"},{"i":25,"n":"第二十五条","txt":"省、自治区、直辖市政府按照国务院的要求和财政部的部署，结合本地区的具体情况，提出本行政区域编制预算草案的要求。"},{"i":26,"n":"第二十六条","txt":"县级以上地方各级政府各部门应当根据本级政府的要求和本级政府财政部门的部署，结合本部门的具体情况，组织编制本部门及其所属各单位的预算草案，按照规定报本级政府财政部门审核。"},{"i":27,"n":"第二十七条","txt":"县级以上地方各级政府财政部门审核本级各部门的预算草案，具体编制本级预算草案，汇编本级总预算草案，经本级政府审定后，按照规定期限报上一级政府财政部门。"},{"i":28,"n":"第二十八条","txt":"县级以上各级政府财政部门审核本级各部门的预算草案时，发现不符合编制预算要求的，应当予以纠正；汇编本级总预算草案时，发现下级预算草案不符合上级政府或者本级政府编制预算要求的，应当及时向本级政府报告，由本级政府予以纠正。"},{"i":29,"n":"第二十九条","txt":"各级政府财政部门编制收入预算草案时，应当征求税务、海关等预算收入征收部门和单位的意见。"},{"i":30,"n":"第三十条","txt":"财政部门会同社会保险行政部门部署编制下一年度社会保险基金预算草案的具体事项。"},{"i":31,"n":"第三十一条","txt":"各级政府财政部门应当依照预算法和本条例规定，制定本级预算草案编制规程。"},{"i":32,"n":"第三十二条","txt":"各部门、各单位在编制预算草案时，应当根据资产配置标准，结合存量资产情况编制相关支出预算。"},{"i":33,"n":"第三十三条","txt":"中央一般公共预算收入编制内容包括本级一般公共预算收入、从国有资本经营预算调入资金、地方上解收入、从预算稳定调节基金调入资金、其他调入资金。"},{"i":34,"n":"第三十四条","txt":"地方各级一般公共预算收入编制内容包括本级一般公共预算收入、从国有资本经营预算调入资金、上级税收返还和转移支付、下级上解收入、从预算稳定调节基金调入资金、其他调入资金。"},{"i":35,"n":"第三十五条","txt":"中央政府性基金预算收入编制内容包括本级政府性基金各项目收入、上一年度结余、地方上解收入。"},{"i":36,"n":"第三十六条","txt":"地方政府性基金预算收入编制内容包括本级政府性基金各项目收入、上一年度结余、下级上解收入、上级转移支付。"},{"i":37,"n":"第三十七条","txt":"中央国有资本经营预算收入编制内容包括本级收入、上一年度结余、地方上解收入。"},{"i":38,"n":"第三十八条","txt":"地方国有资本经营预算收入编制内容包括本级收入、上一年度结余、上级对特定事项的转移支付、下级上解收入。"},{"i":39,"n":"第三十九条","txt":"中央和地方社会保险基金预算收入、支出编制内容包括本条例第十六条规定的各项收入和支出。"},{"i":40,"n":"第四十条","txt":"各部门、各单位预算收入编制内容包括本级预算拨款收入、预算拨款结转和其他收入。"},{"i":41,"n":"第四十一条","txt":"各级政府应当加强项目支出管理。各级政府财政部门应当建立和完善项目支出预算评审制度。各部门、各单位应当按照本级政府财政部门的规定开展预算评审。"},{"i":42,"n":"第四十二条","txt":"预算法第三十四条第二款所称余额管理，是指国务院在全国人民代表大会批准的中央一般公共预算债务的余额限额内，决定发债规模、品种、期限和时点的管理方式；所称余额，是指中央一般公共预算中举借债务未偿还的本金。"},{"i":43,"n":"第四十三条","txt":"地方政府债务余额实行限额管理。各省、自治区、直辖市的政府债务限额，由财政部在全国人民代表大会或者其常务委员会批准的总限额内，根据各地区债务风险、财力状况等因素，并考虑国家宏观调控政策等需要，提出方案报国务院批准。"},{"i":44,"n":"第四十四条","txt":"预算法第三十五条第二款所称举借债务的规模，是指各地方政府债务余额限额的总和，包括一般债务限额和专项债务限额。一般债务是指列入一般公共预算用于公益性事业发展的一般债券、地方政府负有偿还责任的外国政府和国际经济组织贷款转贷债务；专项债务是指列入政府性基金预算用于有收益的公益性事业发展的专项债券。"},{"i":45,"n":"第四十五条","txt":"省、自治区、直辖市政府财政部门依照国务院下达的本地区地方政府债务限额，提出本级和转贷给下级政府的债务限额安排方案，报本级政府批准后，将增加举借的债务列入本级预算调整方案，报本级人民代表大会常务委员会批准。"},{"i":46,"n":"第四十六条","txt":"国务院可以将举借的外国政府和国际经济组织贷款转贷给省、自治区、直辖市政府。"},{"i":47,"n":"第四十七条","txt":"财政部和省、自治区、直辖市政府财政部门应当建立健全地方政府债务风险评估指标体系，组织评估地方政府债务风险状况，对债务高风险地区提出预警，并监督化解债务风险。"},{"i":48,"n":"第四十八条","txt":"县级以上各级政府应当按照本年度转移支付预计执行数的一定比例将下一年度转移支付预计数提前下达至下一级政府，具体下达事宜由本级政府财政部门办理。"},{"i":49,"n":"第四十九条","txt":"经本级政府批准，各级政府财政部门可以设置预算周转金，额度不得超过本级一般公共预算支出总额的1%。年度终了时，各级政府财政部门可以将预算周转金收回并用于补充预算稳定调节基金。"},{"i":50,"n":"第五十条","txt":"预算法第四十二条第一款所称结转资金，是指预算安排项目的支出年度终了时尚未执行完毕，或者因故未执行但下一年度需要按原用途继续使用的资金；连续两年未用完的结转资金，是指预算安排项目的支出在下一年度终了时仍未用完的资金。"},{"i":51,"n":"第五十一条","txt":"预算执行中，政府财政部门的主要职责："},{"i":52,"n":"第五十二条","txt":"预算法第五十六条第二款所称财政专户，是指财政部门为履行财政管理职能，根据法律规定或者经国务院批准开设的用于管理核算特定专用资金的银行结算账户；所称特定专用资金，包括法律规定可以设立财政专户的资金，外国政府和国际经济组织的贷款、赠款，按照规定存储的人民币以外的货币，财政部会同有关部门报国务院批准的其他特定专用资金。"},{"i":53,"n":"第五十三条","txt":"预算执行中，各部门、各单位的主要职责："},{"i":54,"n":"第五十四条","txt":"财政部门会同社会保险行政部门、社会保险费征收机构制定社会保险基金预算的收入、支出以及财务管理的具体办法。"},{"i":55,"n":"第五十五条","txt":"各级政府财政部门和税务、海关等预算收入征收部门和单位必须依法组织预算收入，按照财政管理体制、征收管理制度和国库集中收缴制度的规定征收预算收入，除依法缴入财政专户的社会保险基金等预算收入外，应当及时将预算收入缴入国库。"},{"i":56,"n":"第五十六条","txt":"除依法缴入财政专户的社会保险基金等预算收入外，一切有预算收入上缴义务的部门和单位，必须将应当上缴的预算收入，按照规定的预算级次、政府收支分类科目、缴库方式和期限缴入国库，任何部门、单位和个人不得截留、占用、挪用或者拖欠。"},{"i":57,"n":"第五十七条","txt":"各级政府财政部门应当加强对预算资金拨付的管理，并遵循下列原则："},{"i":58,"n":"第五十八条","txt":"财政部应当根据全国人民代表大会批准的中央政府债务余额限额，合理安排发行国债的品种、结构、期限和时点。"},{"i":59,"n":"第五十九条","txt":"转移支付预算下达和资金拨付应当由财政部门办理，其他部门和单位不得对下级政府部门和单位下达转移支付预算或者拨付转移支付资金。"},{"i":60,"n":"第六十条","txt":"各级政府、各部门、各单位应当加强对预算支出的管理，严格执行预算，遵守财政制度，强化预算约束，不得擅自扩大支出范围、提高开支标准；严格按照预算规定的支出用途使用资金，合理安排支出进度。"},{"i":61,"n":"第六十一条","txt":"财政部负责制定与预算执行有关的财务规则、会计准则和会计制度。各部门、各单位应当按照本级政府财政部门的要求建立健全财务制度，加强会计核算。"},{"i":62,"n":"第六十二条","txt":"国库是办理预算收入的收纳、划分、留解、退付和库款支拨的专门机构。国库分为中央国库和地方国库。"},{"i":63,"n":"第六十三条","txt":"中央国库业务应当接受财政部的指导和监督，对中央财政负责。"},{"i":64,"n":"第六十四条","txt":"各级国库应当及时向本级政府财政部门编报预算收入入库、解库、库款拨付以及库款余额情况的日报、旬报、月报和年报。"},{"i":65,"n":"第六十五条","txt":"各级国库应当依照有关法律、行政法规、国务院以及财政部、中国人民银行的有关规定，加强对国库业务的管理，及时准确地办理预算收入的收纳、划分、留解、退付和预算支出的拨付。"},{"i":66,"n":"第六十六条","txt":"各级国库必须凭本级政府财政部门签发的拨款凭证或者支付清算指令于当日办理资金拨付，并及时将款项转入收款单位的账户或者清算资金。"},{"i":67,"n":"第六十七条","txt":"各级政府财政部门、预算收入征收部门和单位、国库应当建立健全相互之间的预算收入对账制度，在预算执行中按月、按年核对预算收入的收纳以及库款拨付情况，保证预算收入的征收入库、库款拨付和库存金额准确无误。"},{"i":68,"n":"第六十八条","txt":"中央预算收入、中央和地方预算共享收入退库的办法，由财政部制定。地方预算收入退库的办法，由省、自治区、直辖市政府财政部门制定。"},{"i":69,"n":"第六十九条","txt":"各级政府应当加强对本级国库的管理和监督，各级政府财政部门负责协调本级预算收入征收部门和单位与国库的业务工作。"},{"i":70,"n":"第七十条","txt":"国务院各部门制定的规章、文件，凡涉及减免应缴预算收入、设立和改变收入项目和标准、罚没财物处理、经费开支标准和范围、国有资产处置和收益分配以及会计核算等事项的，应当符合国家统一的规定；凡涉及增加或者减少财政收入或者支出的，应当征求财政部意见。"},{"i":71,"n":"第七十一条","txt":"地方政府依据法定权限制定的规章和规定的行政措施，不得涉及减免中央预算收入、中央和地方预算共享收入，不得影响中央预算收入、中央和地方预算共享收入的征收；违反规定的，有关预算收入征收部门和单位有权拒绝执行，并应当向上级预算收入征收部门和单位以及财政部报告。"},{"i":72,"n":"第七十二条","txt":"各级政府应当加强对预算执行工作的领导，定期听取财政部门有关预算执行情况的汇报，研究解决预算执行中出现的问题。"},{"i":73,"n":"第七十三条","txt":"各级政府财政部门有权监督本级各部门及其所属各单位的预算管理有关工作，对各部门的预算执行情况和绩效进行评价、考核。"},{"i":74,"n":"第七十四条","txt":"各级政府财政部门应当每月向本级政府报告预算执行情况，具体报告内容、方式和期限由本级政府规定。"},{"i":75,"n":"第七十五条","txt":"地方各级政府财政部门应当定期向上一级政府财政部门报送本行政区域预算执行情况，包括预算执行旬报、月报、季报，政府债务余额统计报告，国库库款报告以及相关文字说明材料。具体报送内容、方式和期限由上一级政府财政部门规定。"},{"i":76,"n":"第七十六条","txt":"各级税务、海关等预算收入征收部门和单位应当按照财政部门规定的期限和要求，向财政部门和上级主管部门报送有关预算收入征收情况，并附文字说明材料。"},{"i":77,"n":"第七十七条","txt":"各部门应当按照本级政府财政部门规定的期限和要求，向本级政府财政部门报送本部门及其所属各单位的预算收支情况等报表和文字说明材料。"},{"i":78,"n":"第七十八条","txt":"预算法第六十六条第一款所称超收收入，是指年度本级一般公共预算收入的实际完成数超过经本级人民代表大会或者其常务委员会批准的预算收入数的部分。"},{"i":79,"n":"第七十九条","txt":"年度预算确定后，部门、单位改变隶属关系引起预算级次或者预算关系变化的，应当在改变财务关系的同时，相应办理预算、资产划转。"},{"i":80,"n":"第八十条","txt":"预算法第七十四条所称决算草案，是指各级政府、各部门、各单位编制的未经法定程序审查和批准的预算收支和结余的年度执行结果。"},{"i":81,"n":"第八十一条","txt":"财政部应当在每年第四季度部署编制决算草案的原则、要求、方法和报送期限，制发中央各部门决算、地方决算以及其他有关决算的报表格式。"},{"i":82,"n":"第八十二条","txt":"地方政府财政部门根据上级政府财政部门的部署，制定本行政区域决算草案和本级各部门决算草案的具体编制办法。"},{"i":83,"n":"第八十三条","txt":"各级政府财政部门、各部门、各单位在每一预算年度终了时，应当清理核实全年预算收入、支出数据和往来款项，做好决算数据对账工作。"},{"i":84,"n":"第八十四条","txt":"各单位应当按照主管部门的布置，认真编制本单位决算草案，在规定期限内上报。"},{"i":85,"n":"第八十五条","txt":"各级预算收入征收部门和单位应当按照财政部门的要求，及时编制收入年报以及有关资料并报送财政部门。"},{"i":86,"n":"第八十六条","txt":"各级政府财政部门应当根据本级预算、预算会计核算数据等相关资料编制本级决算草案。"},{"i":87,"n":"第八十七条","txt":"年度预算执行终了，对于上下级财政之间按照规定需要清算的事项，应当在决算时办理结算。"},{"i":88,"n":"第八十八条","txt":"县级以上地方各级政府应当自本级决算经批准之日起30日内，将本级决算以及下一级政府上报备案的决算汇总，报上一级政府备案；将下一级政府报送备案的决算汇总，报本级人民代表大会常务委员会备案。"},{"i":89,"n":"第八十九条","txt":"县级以上各级政府应当接受本级和上级人民代表大会及其常务委员会对预算执行情况和决算的监督，乡、民族乡、镇政府应当接受本级人民代表大会和上级人民代表大会及其常务委员会对预算执行情况和决算的监督；按照本级人民代表大会或者其常务委员会的要求，报告预算执行情况；认真研究处理本级人民代表大会代表或者其常务委员会组成人员有关改进预算管理的建议、批评和意见，并及时答复。"},{"i":90,"n":"第九十条","txt":"各级政府应当加强对下级政府预算执行情况的监督，对下级政府在预算执行中违反预算法、本条例和国家方针政策的行为，依法予以制止和纠正；对本级预算执行中出现的问题，及时采取处理措施。"},{"i":91,"n":"第九十一条","txt":"各部门及其所属各单位应当接受本级政府财政部门对预算管理有关工作的监督。"},{"i":92,"n":"第九十二条","txt":"各级政府审计部门应当依法对本级预算执行情况和决算草案，本级各部门、各单位和下级政府的预算执行情况和决算，进行审计监督。"},{"i":93,"n":"第九十三条","txt":"预算法第九十三条第六项所称违反本法规定冻结、动用国库库款或者以其他方式支配已入国库库款，是指："},{"i":94,"n":"第九十四条","txt":"各级政府、有关部门和单位有下列行为之一的，责令改正；对负有直接责任的主管人员和其他直接责任人员，依法给予处分："},{"i":95,"n":"第九十五条","txt":"预算法第九十七条所称政府综合财务报告，是指以权责发生制为基础编制的反映各级政府整体财务状况、运行情况和财政中长期可持续性的报告。政府综合财务报告包括政府资产负债表、收入费用表等财务报表和报表附注，以及以此为基础进行的综合分析等。"},{"i":96,"n":"第九十六条","txt":"政府投资年度计划应当和本级预算相衔接。政府投资决策、项目实施和监督管理按照政府投资有关行政法规执行。"},{"i":97,"n":"第九十七条","txt":"本条例自2020年10月1日起施行。"}],"feixingjibenguize":[{"i":1,"n":"第一条","txt":"为了维护国家领空主权，规范中华人民共和国境内的飞行活动，保障飞行活动安全有秩序地进行，制定本规则。"},{"i":2,"n":"第二条","txt":"凡辖有航空器的单位、个人和与飞行有关的人员及其飞行活动，必须遵守本规则。"},{"i":3,"n":"第三条","txt":"国家对境内所有飞行实行统一的飞行管制。"},{"i":4,"n":"第四条","txt":"国务院、中央军事委员会空中交通管制委员会领导全国的飞行管制工作。"},{"i":5,"n":"第五条","txt":"航空单位的负责人对本单位遵守本规则负责。机长对本空勤组成员遵守本规则负责。"},{"i":6,"n":"第六条","txt":"各航空单位在组织与实施飞行中，应当协调配合，通报有关情况。"},{"i":7,"n":"第七条","txt":"组织与实施飞行，应当按照飞行预先准备、飞行直接准备、飞行实施和飞行讲评等阶段进行。飞行阶段的具体内容和要求，由各航空管理部门自行规定。"},{"i":8,"n":"第八条","txt":"与飞行有关的所有单位、人员负有保证飞行安全的责任，必须遵守有关规章制度，积极采取预防事故的措施，保证飞行安全。"},{"i":9,"n":"第九条","txt":"飞行人员在飞行中，必须服从指挥，严格遵守纪律和操作规程，正确处置空中情况。遇到特殊情况，民用航空器的机长，为保证民用航空器及其所载人员的安全，有权对民用航空器作出处置；非民用航空器的机长（或者单座航空器飞行员，下同）在不能请示时，对于航空器的处置有最后决定权。"},{"i":10,"n":"第十条","txt":"各航空管理部门制定与飞行有关的规范，应当符合本规则的规定。"},{"i":11,"n":"第十一条","txt":"空域管理应当维护国家安全，兼顾民用、军用航空的需要和公众利益，统一规划，合理、充分、有效地利用空域。"},{"i":12,"n":"第十二条","txt":"空域的划设应当考虑国家安全、飞行需要、飞行管制能力和通信、导航、雷达设施建设以及机场分布、环境保护等因素。"},{"i":13,"n":"第十三条","txt":"空域的划设、调整，应当按照国家有关规定履行审批、备案手续。"},{"i":14,"n":"第十四条","txt":"机场飞行空域应当划设在航路和空中走廊以外。仪表（云中）飞行空域的边界距离航路、空中走廊以及其他空域的边界，均不得小于10公里。"},{"i":15,"n":"第十五条","txt":"航路分为国际航路和国内航路。"},{"i":16,"n":"第十六条","txt":"航线分为固定航线和临时航线。"},{"i":17,"n":"第十七条","txt":"国家重要的政治、经济、军事目标上空，可以划设空中禁区、临时空中禁区。"},{"i":18,"n":"第十八条","txt":"位于航路、航线附近的军事要地、兵器试验场上空和航空兵部队、飞行院校等航空单位的机场飞行空域，可以划设空中限制区。根据需要还可以在其他地区上空划设临时空中限制区。"},{"i":19,"n":"第十九条","txt":"位于机场、航路、航线附近的对空射击场或者发射场等，根据其射向、射高、范围，可以在上空划设空中危险区或者临时空中危险区。"},{"i":20,"n":"第二十条","txt":"空中禁区、空中限制区、空中危险区的划设、变更或者撤消，应当根据需要公布。"},{"i":21,"n":"第二十一条","txt":"空中走廊通常划设在机场密集的大、中城市附近地区上空。"},{"i":22,"n":"第二十二条","txt":"空中放油区的划设，按照国家有关规定执行。"},{"i":23,"n":"第二十三条","txt":"临时飞行空域的划设，由申请使用空域的航空单位提出方案，经有关飞行管制部门划定，并通报有关单位。"},{"i":24,"n":"第二十四条","txt":"在机场区域内必须严格执行国家有关保护机场净空的规定，禁止在机场附近修建影响飞行安全的射击靶场、建筑物、构筑物、架空线路等障碍物体。"},{"i":25,"n":"第二十五条","txt":"在距离航路边界30公里以内的地带，禁止修建影响飞行安全的射击靶场和其他设施。"},{"i":26,"n":"第二十六条","txt":"修建各种固定对空射击场或者炮兵射击靶场，必须报国务院、中央军事委员会批准。设立临时性靶场和射击点，经有关飞行管制部门同意后，由设立单位报所在省、自治区、直辖市人民政府和大军区审查批准。"},{"i":27,"n":"第二十七条","txt":"升放无人驾驶航空自由气球或者可能影响飞行安全的系留气球，须经有关飞行管制部门批准。具体管理办法由国务院、中央军事委员会空中交通管制委员会会同国务院民用航空主管部门、中国人民解放军空军拟定，报国务院、中央军事委员会批准实施。"},{"i":28,"n":"第二十八条","txt":"中华人民共和国境内的飞行管制，由中国人民解放军空军统一组织实施，各有关飞行管制部门按照各自的职责分工提供空中交通管制服务。"},{"i":29,"n":"第二十九条","txt":"飞行管制的基本任务是："},{"i":30,"n":"第三十条","txt":"在中华人民共和国境内，按照飞行管制责任划分为：飞行管制区、飞行管制分区、机场飞行管制区。"},{"i":31,"n":"第三十一条","txt":"各类管制区的划设，应当按照国家有关规定审批。"},{"i":32,"n":"第三十二条","txt":"各类管制区的飞行管制，由有关飞行管制部门按照职责分工实施。"},{"i":33,"n":"第三十三条","txt":"中华人民共和国境内特定地区以及执行特殊任务的飞行，应当执行特种飞行管制规定。"},{"i":34,"n":"第三十四条","txt":"担负飞行管制任务的航空管理部门及航空单位，应当按照各自的职责权限，根据本规则制定飞行管制的具体实施办法。"},{"i":35,"n":"第三十五条","txt":"所有飞行必须预先提出申请，经批准后方可实施。"},{"i":36,"n":"第三十六条","txt":"战斗飞行按照战斗命令执行，飞机起飞前或者起飞后必须及时通报飞行管制部门。"},{"i":37,"n":"第三十七条","txt":"对未经批准而起飞或者升空的航空器，有关单位必须迅速查明情况，采取必要措施，直至强迫其降落。"},{"i":38,"n":"第三十八条","txt":"转场航空器的起飞，机场区域内、外飞行的开始和结束，均应当遵守预定的时间；需要提前或者推迟起飞时间的，应当经上一级飞行管制部门的许可。"},{"i":39,"n":"第三十九条","txt":"组织与实施通用航空飞行活动，必须按照有关规定履行报批手续，并向当地飞行管制部门提出飞行申请。飞行申请的内容包括：任务性质、航空器型别、飞行范围、起止时间、飞行高度和飞行条件等。各航空单位应当按照批准的飞行计划组织实施。"},{"i":40,"n":"第四十条","txt":"航空器飞入相邻管制区前，飞行管制部门之间应当进行管制移交。管制移交应当按照程序管制或者雷达管制的有关规定实施。"},{"i":41,"n":"第四十一条","txt":"在中华人民共和国领空飞行的航空器，必须标明明显的识别标志，禁止无识别标志的航空器飞行。"},{"i":42,"n":"第四十二条","txt":"空中交通管制员、飞行指挥员（含飞行管制员，下同）应当按照国家有关规定，经过专门培训、考核，取得执照、证书后，方可上岗工作。"},{"i":43,"n":"第四十三条","txt":"机场区域是指机场和为该机场划定的一定范围的设置各种飞行空域的空间。"},{"i":44,"n":"第四十四条","txt":"机场区域内飞行，应当遵守机场使用细则。"},{"i":45,"n":"第四十五条","txt":"飞行人员飞行时，必须按照规定携带必备的资料、文书和证件。"},{"i":46,"n":"第四十六条","txt":"飞行准备以及保障飞行的准备工作，必须在飞行开始前完成。在各项准备和天气情况符合飞行要求时，飞行方可开始。"},{"i":47,"n":"第四十七条","txt":"昼间飞行，在航空器起飞、降落前，水平能见度小于2公里的，应当打开机场全部障碍标志灯；水平能见度小于1公里的，起飞时还应当打开跑道灯，着陆时还应当打开航空器着陆方向（着陆的反航向）上保障飞行的全部灯光。"},{"i":48,"n":"第四十八条","txt":"飞行人员自起飞前开车起到着陆后关车止，必须同空中交通管制员或者飞行指挥员保持无线电通信联络，并且严格遵守通信纪律。"},{"i":49,"n":"第四十九条","txt":"飞行员开车滑行，必须经空中交通管制员或者飞行指挥员许可。滑行或者牵引时，应当遵守下列规定："},{"i":50,"n":"第五十条","txt":"通常情况下，准备起飞的航空器，在起落航线第四转弯后无其他航空器进入着陆时，经空中交通管制员或者飞行指挥员许可，方可滑进跑道；跑道上无障碍物，方准起飞。"},{"i":51,"n":"第五十一条","txt":"机场的起落航线通常为左航线；若因地形、城市等条件的限制，或者为避免同邻近机场的起落航线交叉，也可以为右航线；起落航线的飞行高度，通常为300米至500米。"},{"i":52,"n":"第五十二条","txt":"航空器起飞后在机场区域内上升或者降落前在机场区域内下降，必须按照空中交通管制员或者飞行指挥员的指示进行。"},{"i":53,"n":"第五十三条","txt":"相邻机场的穿云上升航线、穿云下降航线互有交叉，飞行发生矛盾时，由负责该地区飞行管制的部门调整。"},{"i":54,"n":"第五十四条","txt":"航空器进行空域飞行时，应当按照规定的航线（航向）、高度、次序进入空域或者脱离空域，并且保持在规定的空域和高度范围内飞行。"},{"i":55,"n":"第五十五条","txt":"目视飞行时，飞行人员必须加强空中观察。航空器应当与云保持一定的水平距离和垂直距离。"},{"i":56,"n":"第五十六条","txt":"航空器进入着陆，应当经空中交通管制员或者飞行指挥员许可；不具备着陆条件的，不得勉强着陆。"},{"i":57,"n":"第五十七条","txt":"飞行人员在复杂气象条件下按仪表飞行，必须同时具备下列条件："},{"i":58,"n":"第五十八条","txt":"复杂气象条件下进入机场区域的飞行，必须经空中交通管制员或者飞行指挥员许可。空中交通管制员或者飞行指挥员允许航空器飞入机场区域时，应当及时向飞行员通报下列情况："},{"i":59,"n":"第五十九条","txt":"航空器在等待空域内，必须保持在规定的等待高度层并且按照空中交通管制员或者飞行指挥员指示的方法飞行，未经许可，不得自行改变。"},{"i":60,"n":"第六十条","txt":"航空器穿云下降必须按照该机场的仪表进近图或者穿云图进行。当下降到规定的最低高度或者决断高度仍不能以目视进行着陆时，应当立即停止下降，并且按照规定的航向上升至安全高度。"},{"i":61,"n":"第六十一条","txt":"航空器飞临降落机场时，机场的天气情况低于机长飞行的最低气象条件，且航空器无法飞往备降机场的，空中交通管制员或者飞行指挥员应当采取一切措施，指挥航空器安全降落。"},{"i":62,"n":"第六十二条","txt":"飞机在空中拖曳滑翔机时，拖曳飞机同滑翔机应当视为一个航空器。滑翔机飞行员应当服从拖曳飞机飞行员的指挥。"},{"i":63,"n":"第六十三条","txt":"机场区域内飞行的开始和结束的时间，其他任务飞行的航空器在该机场起飞和降落的时间，均应当及时报告上级飞行管制部门。"},{"i":64,"n":"第六十四条","txt":"航空器使用航路和航线，应当经负责该航路和航线的飞行管制部门同意。"},{"i":65,"n":"第六十五条","txt":"航路和固定航线地带应当设置必要的监视和导航设备。"},{"i":66,"n":"第六十六条","txt":"穿越航路和航线的飞行，应当明确穿越的地段、高度和时间，穿越时还应当保证与航路和航线飞行的航空器有规定的飞行间隔。"},{"i":67,"n":"第六十七条","txt":"飞行任务书是许可飞行人员进行转场飞行和民用航空飞行的基本文件。飞行任务书由驻机场航空单位或者航空公司的负责人签发。"},{"i":68,"n":"第六十八条","txt":"航路、航线飞行或者转场飞行前，驻机场航空单位或者航空公司的负责人应当亲自或者指定专人对飞行人员的飞行准备情况进行检查。飞行准备质量符合要求时，方可执行飞行任务。"},{"i":69,"n":"第六十九条","txt":"航路、航线飞行或者转场飞行的航空器的起飞，应当根据飞行人员和航空器的准备情况，起飞机场、降落机场和备降机场的准备情况以及天气情况等确定；有下列情况之一的，不得起飞："},{"i":70,"n":"第七十条","txt":"飞行人员在飞行中必须遵守有关的飞行规则和飞行任务书中的各项规定，服从飞行指挥，准确实施领航，保持规定的航行诸元，注意观察空中情况，按照规定及时报告航空器位置、飞行情况和天气情况，特别是危险天气现象及其发展情况。"},{"i":71,"n":"第七十一条","txt":"目视飞行时，航空器应当按照下列规定避让："},{"i":72,"n":"第七十二条","txt":"在与航路、固定航线交叉或者靠近的临时航线飞行时，飞行人员应当加强对空中的观察，防止与航路飞行的航空器相撞。当临时航线与航路、固定航线交叉时，水平能见度大于8公里的，应当按照规定的飞行高度通过；在云中飞行或者水平能见度小于8公里的，应当按照空中交通管制员或者飞行指挥员的指示通过。在靠近航路的航线上飞行时，应当与航路的边界保持规定的安全间隔。"},{"i":73,"n":"第七十三条","txt":"未配备复杂气象飞行设备的航空器，机长应当按照规定的飞行最低气象条件，在安全高度以上进行目视飞行，防止飞入云中。"},{"i":74,"n":"第七十四条","txt":"当天气情况不低于机长飞行的最低气象条件时，机长方可在300米以下进行目视飞行，飞行时航空器距离云层底部不得小于50米。"},{"i":75,"n":"第七十五条","txt":"航空器沿航路和固定航线飞行通过中途机场100至50公里前，除有协议的外，飞行人员应当向该机场的空中交通管制员或者飞行指挥员报告预计通过的时间和高度。中途机场的空中交通管制员或者飞行指挥员必须指挥在本机场区域内飞行的航空器避让过往航空器，保证其安全通过；无特殊原因，不得改变过往航空器的航线和高度。"},{"i":76,"n":"第七十六条","txt":"飞行中，飞行人员与地面联络中断，可以停止执行飞行任务，返回原机场或者飞往就近的备降机场降落。当保持原高度飞向备降机场符合飞行高度层配备规定时，仍保持原高度飞行；当保持原高度飞向备降机场不符合飞行高度层配备规定时，应当下降到下一层高度飞向备降机场；因飞行安全高度所限不能下降到下一层高度的，应当上升至上一层高度飞向备降机场。"},{"i":77,"n":"第七十七条","txt":"航路、航线飞行或者转场飞行的航空器，在起飞前或者在中途机场降落后需要继续飞行的，机长或者其代理人必须到机场飞行管制部门办理飞行手续，校对有关资料，经批准后方可起飞；航空器降落后需要连续起飞的，必须事先经中途机场飞行管制部门的许可。"},{"i":78,"n":"第七十八条","txt":"航路、航线飞行或者转场飞行的航空器到达预定机场后，其各项保障工作由驻该机场的有关部门按照规定或者协议负责。"},{"i":79,"n":"第七十九条","txt":"飞行间隔是为了防止飞行冲突，保证飞行安全，提高飞行空间和时间利用率所规定的航空器之间应当保持的最小安全距离。飞行间隔包括垂直间隔和水平间隔。水平间隔分为纵向间隔和横向间隔。"},{"i":80,"n":"第八十条","txt":"航路、航线飞行或者转场飞行的垂直间隔，按照飞行高度层配备。飞行高度层按照以下标准划分："},{"i":81,"n":"第八十一条","txt":"航路、航线飞行或者转场飞行的水平间隔，由中国人民解放军空军会同国务院民用航空主管部门拟定，报国务院、中央军事委员会空中交通管制委员会批准。"},{"i":82,"n":"第八十二条","txt":"飞行的安全高度是避免航空器与地面障碍物相撞的最低飞行高度。"},{"i":83,"n":"第八十三条","txt":"航路、航线飞行或者转场飞行的航空器，在航路中心线、航线两侧各25公里以内的最高标高不超过100米，大气压力不低于1000百帕（750毫米水银柱）的，允许在600米的高度层内飞行；当最高标高超过100米，大气压力低于1000百帕（750毫米水银柱）的，飞行最低的高度层必须相应提高，保证飞行的真实高度不低于安全高度。"},{"i":84,"n":"第八十四条","txt":"航路、航线飞行或者转场飞行的高度层，由批准本次飞行的负责人，通过飞行管制部门具体配备。"},{"i":85,"n":"第八十五条","txt":"在同一条航路、航线有数架（数批）航空器同时飞行并且互有影响的，应当分别将每架（每批）航空器配备在不同的高度层内；不能配备在不同高度层的，可以允许数架（数批）航空器在同一条航路、航线、同一个高度层内飞行，但是各架（各批）航空器之间应当保持规定的纵向间隔。"},{"i":86,"n":"第八十六条","txt":"航路、航线飞行或者转场飞行的航空器起飞前，应当将场面气压的数值调整到航空器上气压高度表的固定指标，使气压高度表的指针指到零的位置。"},{"i":87,"n":"第八十七条","txt":"在高原机场起飞前，航空器上气压高度表的气压刻度不能调整到机场场面气压数值的，应当将气压高度表的标准海平面气压值调整到固定指标（此时所指示的高度为假定零点高度），然后起飞和上升到规定的飞行高度。"},{"i":88,"n":"第八十八条","txt":"航路、航线飞行或者转场飞行时，因航空器故障、积冰、绕飞雷雨区等原因需要改变飞行高度层的，机长应当向飞行管制部门报告原因和当时航空器的准确位置，请求另行配备飞行高度层。飞行管制部门允许航空器改变飞行高度层时，必须明确改变的高度层以及改变高度层的地段和时间。"},{"i":89,"n":"第八十九条","txt":"组织实施飞行指挥应当根据本规则和有关规定进行，做到正确、及时和不间断。"},{"i":90,"n":"第九十条","txt":"飞行指挥员必须切实履行职责，维护机场、空中秩序和飞行纪律，并做到："},{"i":91,"n":"第九十一条","txt":"飞行指挥必须按照下列调配原则安排飞行次序："},{"i":92,"n":"第九十二条","txt":"在飞行期间，所有参加飞行和保障飞行的人员，必须服从飞行指挥员的指挥。"},{"i":93,"n":"第九十三条","txt":"驻在同一机场的军用航空器和民用航空器同时飞行时，必须实施统一指挥。军用航空单位派出飞行指挥员，民用航空单位派出飞行副指挥员。"},{"i":94,"n":"第九十四条","txt":"执行不同任务的航空器或者不同型别的航空器，在同一机场同时飞行的，应当根据具体情况安排优先起飞和降落的顺序。"},{"i":95,"n":"第九十五条","txt":"飞行指挥用无线电实施。指挥用语应当简短、明确、易懂、规范。"},{"i":96,"n":"第九十六条","txt":"现用机场应当设飞行管制室、起飞线塔台（指挥塔台）或者机场管制塔台，其位置应当有良好的视界，可观察到机场、净空地带以及航空器飞行和航空器在机场上的活动。"},{"i":97,"n":"第九十七条","txt":"作战飞行的指挥，按照中国人民解放军有关规定执行。"},{"i":98,"n":"第九十八条","txt":"飞行中的特殊情况，是指突然发生的危及飞行安全的情况。"},{"i":99,"n":"第九十九条","txt":"飞行人员、空中交通管制员、飞行指挥员和各类保障飞行的人员，对飞行中特殊情况的处置必须预有准备。飞行人员应当及时察觉飞行中出现特殊情况的各种征兆，熟练掌握在各种特殊情况下的操作程序和紧急处置方法；空中交通管制员或者飞行指挥员，应当熟知在不同的飞行条件下特殊情况的指挥措施和组织援救遇险航空器的方法；各类保障飞行的人员在任何情况下都应当恪尽职守，使各种保障设施经常处于良好状态，随时能为飞行人员、空中交通管制员、飞行指挥员正确处置特殊情况提供有利条件。"},{"i":100,"n":"第一百条","txt":"飞行中发生特殊情况，机长必须在保证航空器上人员生命安全的前提下，积极采取措施保全航空器。时间允许的，机长应当及时向空中交通管制员或者飞行指挥员报告所发生的情况和准备采取的措施，并且按照其指示行动。"},{"i":101,"n":"第一百零一条","txt":"在飞行中遇到严重危及航空器和人员安全的情况时，飞行人员应当利用一切手段，重复发出规定的遇险信号。其他航空器飞行人员在飞行中收到遇险信号，应当暂时停止使用无线电发信，必要时协助遇险航空器重复发出遇险信号。"},{"i":102,"n":"第一百零二条","txt":"军用航空器遇险时，有关部门应当及时报告当地政府和驻军。当地政府和驻军应当立即组织搜寻援救。在海上搜寻援救遇险航空器时，还应当报告国家海上搜寻援救组织和附近的海上搜寻援救组织，国家海上搜寻援救组织和附近的海上搜寻援救组织应当迅速进行搜寻和援救。"},{"i":103,"n":"第一百零三条","txt":"航空器在中华人民共和国境外遇险时，应当使用国际通用的遇险信号和频率。在海上飞行遇险时，设备允许的，还应当使用500千赫频率发出遇险信号。"},{"i":104,"n":"第一百零四条","txt":"通信、导航、雷达、气象和航行情报保障部门应当明确任务，认真履行职责，密切协同，周密组织与实施飞行保障工作。"},{"i":105,"n":"第一百零五条","txt":"各种通信、导航设备必须经常处于良好状态，主要设备应当配有备份，保证通信、导航的可靠性和稳定性。"},{"i":106,"n":"第一百零六条","txt":"飞行实施过程中，飞行人员、空中交通管制员、飞行指挥员应当按照通信、导航保障规定，正确使用通信、导航设备。"},{"i":107,"n":"第一百零七条","txt":"雷达保障部门应当对中华人民共和国境内的所有飞行提供保障。"},{"i":108,"n":"第一百零八条","txt":"雷达保障应当做到："},{"i":109,"n":"第一百零九条","txt":"飞行的气象保障工作由航空气象保障部门负责。"},{"i":110,"n":"第一百一十条","txt":"飞行气象保障的组织与实施，应当按照各航空单位的有关规定执行。"},{"i":111,"n":"第一百一十一条","txt":"航行情报部门，应当提供保证飞行安全、正常和效率所需要的各种航行情报资料。"},{"i":112,"n":"第一百一十二条","txt":"外国航空器飞入或者飞出中华人民共和国领空，或者在中华人民共和国境内飞行、停留，必须按照中华人民共和国的有关规定获得批准。"},{"i":113,"n":"第一百一十三条","txt":"外国航空器在中华人民共和国境内的航路、航线飞行时，由中华人民共和国国务院民用航空主管部门负责提供空中交通管制服务。"},{"i":114,"n":"第一百一十四条","txt":"外国航空器飞入或者飞出中华人民共和国领空，必须按照规定的航路飞入或者飞出。飞入或者飞出领空前20至15分钟，其机组必须向中华人民共和国有关空中交通管制部门报告，并取得飞入或者飞出领空的许可；未经许可，不得飞入或者飞出。"},{"i":115,"n":"第一百一十五条","txt":"未经批准擅自飞入或者飞出中华人民共和国领空的外国民用航空器，中华人民共和国有关机关有权采取必要措施，令其在指定的机场降落。"},{"i":116,"n":"第一百一十六条","txt":"违反本规则规定，《中华人民共和国民用航空法》及有关法规对其处罚有明确规定的，从其规定；无明确规定的，适用本章规定。"},{"i":117,"n":"第一百一十七条","txt":"未按本规则规定履行审批、备案或者其他手续的，由有关部门按照职责分工责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予行政处分或者纪律处分；构成犯罪的，依法追究刑事责任。"},{"i":118,"n":"第一百一十八条","txt":"飞行人员未按本规则规定履行职责的，由有关部门依法给予行政处分或者纪律处分；情节严重的，依法给予吊扣执照一个月至六个月的处罚，或者责令停飞一个月至三个月；构成犯罪的，依法追究刑事责任。"},{"i":119,"n":"第一百一十九条","txt":"空中交通管制员、飞行指挥员未按本规则规定履行职责的，由有关部门视情节给予批评教育、警告、记过、降职或者取消资格，免除职务的处分；构成犯罪的，依法追究刑事责任。"},{"i":120,"n":"第一百二十条","txt":"飞行保障部门及其人员未按本规则规定履行职责的，由有关航空管理部门视情节给予通报批评；对直接负责的主管人员或者其他责任人员依法给予行政处分或者纪律处分；构成犯罪的，依法追究刑事责任。"},{"i":121,"n":"第一百二十一条","txt":"中华人民共和国航空器在本国领海以外毗连区、专属经济区和公海上空飞行，中华人民共和国缔结或者参加的国际条约同本规则有不同规定的，适用国际条约的规定；但是，中华人民共和国声明保留的条款除外。"},{"i":122,"n":"第一百二十二条","txt":"拦截违反本规则的航空器所使用的信号和被拦截的航空器回答的信号，按照本规则附件三的规定执行。"},{"i":123,"n":"第一百二十三条","txt":"本规则下列用语的含义："},{"i":124,"n":"第一百二十四条","txt":"本规则自2001年8月1日零时起施行。国务院、中央军事委员会1977年4月21日颁发的《中华人民共和国飞行基本规则》同时废止。"}],"shipinanquanfashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国食品安全法》（以下简称食品安全法），制定本条例。"},{"i":2,"n":"第二条","txt":"食品生产经营者应当依照法律、法规和食品安全标准从事生产经营活动，建立健全食品安全管理制度，采取有效措施预防和控制食品安全风险，保证食品安全。"},{"i":3,"n":"第三条","txt":"国务院食品安全委员会负责分析食品安全形势，研究部署、统筹指导食品安全工作，提出食品安全监督管理的重大政策措施，督促落实食品安全监督管理责任。县级以上地方人民政府食品安全委员会按照本级人民政府规定的职责开展工作。"},{"i":4,"n":"第四条","txt":"县级以上人民政府建立统一权威的食品安全监督管理体制，加强食品安全监督管理能力建设。"},{"i":5,"n":"第五条","txt":"国家将食品安全知识纳入国民素质教育内容，普及食品安全科学常识和法律知识，提高全社会的食品安全意识。"},{"i":6,"n":"第六条","txt":"县级以上人民政府卫生行政部门会同同级食品安全监督管理等部门建立食品安全风险监测会商机制，汇总、分析风险监测数据，研判食品安全风险，形成食品安全风险监测分析报告，报本级人民政府；县级以上地方人民政府卫生行政部门还应当将食品安全风险监测分析报告同时报上一级人民政府卫生行政部门。食品安全风险监测会商的具体办法由国务院卫生行政部门会同国务院食品安全监督管理等部门制定。"},{"i":7,"n":"第七条","txt":"食品安全风险监测结果表明存在食品安全隐患，食品安全监督管理等部门经进一步调查确认有必要通知相关食品生产经营者的，应当及时通知。"},{"i":8,"n":"第八条","txt":"国务院卫生行政、食品安全监督管理等部门发现需要对农药、肥料、兽药、饲料和饲料添加剂等进行安全性评估的，应当向国务院农业行政部门提出安全性评估建议。国务院农业行政部门应当及时组织评估，并向国务院有关部门通报评估结果。"},{"i":9,"n":"第九条","txt":"国务院食品安全监督管理部门和其他有关部门建立食品安全风险信息交流机制，明确食品安全风险信息交流的内容、程序和要求。"},{"i":10,"n":"第十条","txt":"国务院卫生行政部门会同国务院食品安全监督管理、农业行政等部门制定食品安全国家标准规划及其年度实施计划。国务院卫生行政部门应当在其网站上公布食品安全国家标准规划及其年度实施计划的草案，公开征求意见。"},{"i":11,"n":"第十一条","txt":"省、自治区、直辖市人民政府卫生行政部门依照食品安全法第二十九条的规定制定食品安全地方标准，应当公开征求意见。省、自治区、直辖市人民政府卫生行政部门应当自食品安全地方标准公布之日起30个工作日内，将地方标准报国务院卫生行政部门备案。国务院卫生行政部门发现备案的食品安全地方标准违反法律、法规或者食品安全国家标准的，应当及时予以纠正。"},{"i":12,"n":"第十二条","txt":"保健食品、特殊医学用途配方食品、婴幼儿配方食品等特殊食品不属于地方特色食品，不得对其制定食品安全地方标准。"},{"i":13,"n":"第十三条","txt":"食品安全标准公布后，食品生产经营者可以在食品安全标准规定的实施日期之前实施并公开提前实施情况。"},{"i":14,"n":"第十四条","txt":"食品生产企业不得制定低于食品安全国家标准或者地方标准要求的企业标准。食品生产企业制定食品安全指标严于食品安全国家标准或者地方标准的企业标准的，应当报省、自治区、直辖市人民政府卫生行政部门备案。"},{"i":15,"n":"第十五条","txt":"食品生产经营许可的有效期为5年。"},{"i":16,"n":"第十六条","txt":"国务院卫生行政部门应当及时公布新的食品原料、食品添加剂新品种和食品相关产品新品种目录以及所适用的食品安全国家标准。"},{"i":17,"n":"第十七条","txt":"国务院食品安全监督管理部门会同国务院农业行政等有关部门明确食品安全全程追溯基本要求，指导食品生产经营者通过信息化手段建立、完善食品安全追溯体系。"},{"i":18,"n":"第十八条","txt":"食品生产经营者应当建立食品安全追溯体系，依照食品安全法的规定如实记录并保存进货查验、出厂检验、食品销售等信息，保证食品可追溯。"},{"i":19,"n":"第十九条","txt":"食品生产经营企业的主要负责人对本企业的食品安全工作全面负责，建立并落实本企业的食品安全责任制，加强供货者管理、进货查验和出厂检验、生产经营过程控制、食品安全自查等工作。食品生产经营企业的食品安全管理人员应当协助企业主要负责人做好食品安全管理工作。"},{"i":20,"n":"第二十条","txt":"食品生产经营企业应当加强对食品安全管理人员的培训和考核。食品安全管理人员应当掌握与其岗位相适应的食品安全法律、法规、标准和专业知识，具备食品安全管理能力。食品安全监督管理部门应当对企业食品安全管理人员进行随机监督抽查考核。考核指南由国务院食品安全监督管理部门制定、公布。"},{"i":21,"n":"第二十一条","txt":"食品、食品添加剂生产经营者委托生产食品、食品添加剂的，应当委托取得食品生产许可、食品添加剂生产许可的生产者生产，并对其生产行为进行监督，对委托生产的食品、食品添加剂的安全负责。受托方应当依照法律、法规、食品安全标准以及合同约定进行生产，对生产行为负责，并接受委托方的监督。"},{"i":22,"n":"第二十二条","txt":"食品生产经营者不得在食品生产、加工场所贮存依照本条例第六十三条规定制定的名录中的物质。"},{"i":23,"n":"第二十三条","txt":"对食品进行辐照加工，应当遵守食品安全国家标准，并按照食品安全国家标准的要求对辐照加工食品进行检验和标注。"},{"i":24,"n":"第二十四条","txt":"贮存、运输对温度、湿度等有特殊要求的食品，应当具备保温、冷藏或者冷冻等设备设施，并保持有效运行。"},{"i":25,"n":"第二十五条","txt":"食品生产经营者委托贮存、运输食品的，应当对受托方的食品安全保障能力进行审核，并监督受托方按照保证食品安全的要求贮存、运输食品。受托方应当保证食品贮存、运输条件符合食品安全的要求，加强食品贮存、运输过程管理。"},{"i":26,"n":"第二十六条","txt":"餐饮服务提供者委托餐具饮具集中消毒服务单位提供清洗消毒服务的，应当查验、留存餐具饮具集中消毒服务单位的营业执照复印件和消毒合格证明。保存期限不得少于消毒餐具饮具使用期限到期后6个月。"},{"i":27,"n":"第二十七条","txt":"餐具饮具集中消毒服务单位应当建立餐具饮具出厂检验记录制度，如实记录出厂餐具饮具的数量、消毒日期和批号、使用期限、出厂日期以及委托方名称、地址、联系方式等内容。出厂检验记录保存期限不得少于消毒餐具饮具使用期限到期后6个月。消毒后的餐具饮具应当在独立包装上标注单位名称、地址、联系方式、消毒日期和批号以及使用期限等内容。"},{"i":28,"n":"第二十八条","txt":"学校、托幼机构、养老机构、建筑工地等集中用餐单位的食堂应当执行原料控制、餐具饮具清洗消毒、食品留样等制度，并依照食品安全法第四十七条的规定定期开展食堂食品安全自查。"},{"i":29,"n":"第二十九条","txt":"食品生产经营者应当对变质、超过保质期或者回收的食品进行显著标示或者单独存放在有明确标志的场所，及时采取无害化处理、销毁等措施并如实记录。"},{"i":30,"n":"第三十条","txt":"县级以上地方人民政府根据需要建设必要的食品无害化处理和销毁设施。食品生产经营者可以按照规定使用政府建设的设施对食品进行无害化处理或者予以销毁。"},{"i":31,"n":"第三十一条","txt":"食品集中交易市场的开办者、食品展销会的举办者应当在市场开业或者展销会举办前向所在地县级人民政府食品安全监督管理部门报告。"},{"i":32,"n":"第三十二条","txt":"网络食品交易第三方平台提供者应当妥善保存入网食品经营者的登记信息和交易信息。县级以上人民政府食品安全监督管理部门开展食品安全监督检查、食品安全案件调查处理、食品安全事故处置确需了解有关信息的，经其负责人批准，可以要求网络食品交易第三方平台提供者提供，网络食品交易第三方平台提供者应当按照要求提供。县级以上人民政府食品安全监督管理部门及其工作人员对网络食品交易第三方平台提供者提供的信息依法负有保密义务。"},{"i":33,"n":"第三十三条","txt":"生产经营转基因食品应当显著标示，标示办法由国务院食品安全监督管理部门会同国务院农业行政部门制定。"},{"i":34,"n":"第三十四条","txt":"禁止利用包括会议、讲座、健康咨询在内的任何方式对食品进行虚假宣传。食品安全监督管理部门发现虚假宣传行为的，应当依法及时处理。"},{"i":35,"n":"第三十五条","txt":"保健食品生产工艺有原料提取、纯化等前处理工序的，生产企业应当具备相应的原料前处理能力。"},{"i":36,"n":"第三十六条","txt":"特殊医学用途配方食品生产企业应当按照食品安全国家标准规定的检验项目对出厂产品实施逐批检验。"},{"i":37,"n":"第三十七条","txt":"特殊医学用途配方食品中的特定全营养配方食品广告按照处方药广告管理，其他类别的特殊医学用途配方食品广告按照非处方药广告管理。"},{"i":38,"n":"第三十八条","txt":"对保健食品之外的其他食品，不得声称具有保健功能。"},{"i":39,"n":"第三十九条","txt":"特殊食品的标签、说明书内容应当与注册或者备案的标签、说明书一致。销售特殊食品，应当核对食品标签、说明书内容是否与注册或者备案的标签、说明书一致，不一致的不得销售。省级以上人民政府食品安全监督管理部门应当在其网站上公布注册或者备案的特殊食品的标签、说明书。"},{"i":40,"n":"第四十条","txt":"对食品进行抽样检验，应当按照食品安全标准、注册或者备案的特殊食品的产品技术要求以及国家有关规定确定的检验项目和检验方法进行。"},{"i":41,"n":"第四十一条","txt":"对可能掺杂掺假的食品，按照现有食品安全标准规定的检验项目和检验方法以及依照食品安全法第一百一十一条和本条例第六十三条规定制定的检验项目和检验方法无法检验的，国务院食品安全监督管理部门可以制定补充检验项目和检验方法，用于对食品的抽样检验、食品安全案件调查处理和食品安全事故处置。"},{"i":42,"n":"第四十二条","txt":"依照食品安全法第八十八条的规定申请复检的，申请人应当向复检机构先行支付复检费用。复检结论表明食品不合格的，复检费用由复检申请人承担；复检结论表明食品合格的，复检费用由实施抽样检验的食品安全监督管理部门承担。"},{"i":43,"n":"第四十三条","txt":"任何单位和个人不得发布未依法取得资质认定的食品检验机构出具的食品检验信息，不得利用上述检验信息对食品、食品生产经营者进行等级评定，欺骗、误导消费者。"},{"i":44,"n":"第四十四条","txt":"进口商进口食品、食品添加剂，应当按照规定向出入境检验检疫机构报检，如实申报产品相关信息，并随附法律、行政法规规定的合格证明材料。"},{"i":45,"n":"第四十五条","txt":"进口食品运达口岸后，应当存放在出入境检验检疫机构指定或者认可的场所；需要移动的，应当按照出入境检验检疫机构的要求采取必要的安全防护措施。大宗散装进口食品应当在卸货口岸进行检验。"},{"i":46,"n":"第四十六条","txt":"国家出入境检验检疫部门根据风险管理需要，可以对部分食品实行指定口岸进口。"},{"i":47,"n":"第四十七条","txt":"国务院卫生行政部门依照食品安全法第九十三条的规定对境外出口商、境外生产企业或者其委托的进口商提交的相关国家（地区）标准或者国际标准进行审查，认为符合食品安全要求的，决定暂予适用并予以公布；暂予适用的标准公布前，不得进口尚无食品安全国家标准的食品。"},{"i":48,"n":"第四十八条","txt":"进口商应当建立境外出口商、境外生产企业审核制度，重点审核境外出口商、境外生产企业制定和执行食品安全风险控制措施的情况以及向我国出口的食品是否符合食品安全法、本条例和其他有关法律、行政法规的规定以及食品安全国家标准的要求。"},{"i":49,"n":"第四十九条","txt":"进口商依照食品安全法第九十四条第三款的规定召回进口食品的，应当将食品召回和处理情况向所在地县级人民政府食品安全监督管理部门和所在地出入境检验检疫机构报告。"},{"i":50,"n":"第五十条","txt":"国家出入境检验检疫部门发现已经注册的境外食品生产企业不再符合注册要求的，应当责令其在规定期限内整改，整改期间暂停进口其生产的食品；经整改仍不符合注册要求的，国家出入境检验检疫部门应当撤销境外食品生产企业注册并公告。"},{"i":51,"n":"第五十一条","txt":"对通过我国良好生产规范、危害分析与关键控制点体系认证的境外生产企业，认证机构应当依法实施跟踪调查。对不再符合认证要求的企业，认证机构应当依法撤销认证并向社会公布。"},{"i":52,"n":"第五十二条","txt":"境外发生的食品安全事件可能对我国境内造成影响，或者在进口食品、食品添加剂、食品相关产品中发现严重食品安全问题的，国家出入境检验检疫部门应当及时进行风险预警，并可以对相关的食品、食品添加剂、食品相关产品采取下列控制措施："},{"i":53,"n":"第五十三条","txt":"出口食品、食品添加剂的生产企业应当保证其出口食品、食品添加剂符合进口国家（地区）的标准或者合同要求；我国缔结或者参加的国际条约、协定有要求的，还应当符合国际条约、协定的要求。"},{"i":54,"n":"第五十四条","txt":"食品安全事故按照国家食品安全事故应急预案实行分级管理。县级以上人民政府食品安全监督管理部门会同同级有关部门负责食品安全事故调查处理。"},{"i":55,"n":"第五十五条","txt":"县级以上人民政府应当完善食品安全事故应急管理机制，改善应急装备，做好应急物资储备和应急队伍建设，加强应急培训、演练。"},{"i":56,"n":"第五十六条","txt":"发生食品安全事故的单位应当对导致或者可能导致食品安全事故的食品及原料、工具、设备、设施等，立即采取封存等控制措施。"},{"i":57,"n":"第五十七条","txt":"县级以上人民政府食品安全监督管理部门接到食品安全事故报告后，应当立即会同同级卫生行政、农业行政等部门依照食品安全法第一百零五条的规定进行调查处理。食品安全监督管理部门应当对事故单位封存的食品及原料、工具、设备、设施等予以保护，需要封存而事故单位尚未封存的应当直接封存或者责令事故单位立即封存，并通知疾病预防控制机构对与事故有关的因素开展流行病学调查。"},{"i":58,"n":"第五十八条","txt":"国务院食品安全监督管理部门会同国务院卫生行政、农业行政等部门定期对全国食品安全事故情况进行分析，完善食品安全监督管理措施，预防和减少事故的发生。"},{"i":59,"n":"第五十九条","txt":"设区的市级以上人民政府食品安全监督管理部门根据监督管理工作需要，可以对由下级人民政府食品安全监督管理部门负责日常监督管理的食品生产经营者实施随机监督检查，也可以组织下级人民政府食品安全监督管理部门对食品生产经营者实施异地监督检查。"},{"i":60,"n":"第六十条","txt":"国家建立食品安全检查员制度，依托现有资源加强职业化检查员队伍建设，强化考核培训，提高检查员专业化水平。"},{"i":61,"n":"第六十一条","txt":"县级以上人民政府食品安全监督管理部门依照食品安全法第一百一十条的规定实施查封、扣押措施，查封、扣押的期限不得超过30日；情况复杂的，经实施查封、扣押措施的食品安全监督管理部门负责人批准，可以延长，延长期限不得超过45日。"},{"i":62,"n":"第六十二条","txt":"网络食品交易第三方平台多次出现入网食品经营者违法经营或者入网食品经营者的违法经营行为造成严重后果的，县级以上人民政府食品安全监督管理部门可以对网络食品交易第三方平台提供者的法定代表人或者主要负责人进行责任约谈。"},{"i":63,"n":"第六十三条","txt":"国务院食品安全监督管理部门会同国务院卫生行政等部门根据食源性疾病信息、食品安全风险监测信息和监督管理信息等，对发现的添加或者可能添加到食品中的非食品用化学物质和其他可能危害人体健康的物质，制定名录及检测方法并予以公布。"},{"i":64,"n":"第六十四条","txt":"县级以上地方人民政府卫生行政部门应当对餐具饮具集中消毒服务单位进行监督检查，发现不符合法律、法规、国家相关标准以及相关卫生规范等要求的，应当及时调查处理。监督检查的结果应当向社会公布。"},{"i":65,"n":"第六十五条","txt":"国家实行食品安全违法行为举报奖励制度，对查证属实的举报，给予举报人奖励。举报人举报所在企业食品安全重大违法犯罪行为的，应当加大奖励力度。有关部门应当对举报人的信息予以保密，保护举报人的合法权益。食品安全违法行为举报奖励办法由国务院食品安全监督管理部门会同国务院财政等有关部门制定。"},{"i":66,"n":"第六十六条","txt":"国务院食品安全监督管理部门应当会同国务院有关部门建立守信联合激励和失信联合惩戒机制，结合食品生产经营者信用档案，建立严重违法生产经营者黑名单制度，将食品安全信用状况与准入、融资、信贷、征信等相衔接，及时向社会公布。"},{"i":67,"n":"第六十七条","txt":"有下列情形之一的，属于食品安全法第一百二十三条至第一百二十六条、第一百三十二条以及本条例第七十二条、第七十三条规定的情节严重情形："},{"i":68,"n":"第六十八条","txt":"有下列情形之一的，依照食品安全法第一百二十五条第一款、本条例第七十五条的规定给予处罚："},{"i":69,"n":"第六十九条","txt":"有下列情形之一的，依照食品安全法第一百二十六条第一款、本条例第七十五条的规定给予处罚："},{"i":70,"n":"第七十条","txt":"除食品安全法第一百二十五条第一款、第一百二十六条规定的情形外，食品生产经营者的生产经营行为不符合食品安全法第三十三条第一款第五项、第七项至第十项的规定，或者不符合有关食品生产经营过程要求的食品安全国家标准的，依照食品安全法第一百二十六条第一款、本条例第七十五条的规定给予处罚。"},{"i":71,"n":"第七十一条","txt":"餐具饮具集中消毒服务单位未按照规定建立并遵守出厂检验记录制度的，由县级以上人民政府卫生行政部门依照食品安全法第一百二十六条第一款、本条例第七十五条的规定给予处罚。"},{"i":72,"n":"第七十二条","txt":"从事对温度、湿度等有特殊要求的食品贮存业务的非食品生产经营者，食品集中交易市场的开办者、食品展销会的举办者，未按照规定备案或者报告的，由县级以上人民政府食品安全监督管理部门责令改正，给予警告；拒不改正的，处1万元以上5万元以下罚款；情节严重的，责令停产停业，并处5万元以上20万元以下罚款。"},{"i":73,"n":"第七十三条","txt":"利用会议、讲座、健康咨询等方式对食品进行虚假宣传的，由县级以上人民政府食品安全监督管理部门责令消除影响，有违法所得的，没收违法所得；情节严重的，依照食品安全法第一百四十条第五款的规定进行处罚；属于单位违法的，还应当依照本条例第七十五条的规定对单位的法定代表人、主要负责人、直接负责的主管人员和其他直接责任人员给予处罚。"},{"i":74,"n":"第七十四条","txt":"食品生产经营者生产经营的食品符合食品安全标准但不符合食品所标注的企业标准规定的食品安全指标的，由县级以上人民政府食品安全监督管理部门给予警告，并责令食品经营者停止经营该食品，责令食品生产企业改正；拒不停止经营或者改正的，没收不符合企业标准规定的食品安全指标的食品，货值金额不足1万元的，并处1万元以上5万元以下罚款，货值金额1万元以上的，并处货值金额5倍以上10倍以下罚款。"},{"i":75,"n":"第七十五条","txt":"食品生产经营企业等单位有食品安全法规定的违法情形，除依照食品安全法的规定给予处罚外，有下列情形之一的，对单位的法定代表人、主要负责人、直接负责的主管人员和其他直接责任人员处以其上一年度从本单位取得收入的1倍以上10倍以下罚款："},{"i":76,"n":"第七十六条","txt":"食品生产经营者依照食品安全法第六十三条第一款、第二款的规定停止生产、经营，实施食品召回，或者采取其他有效措施减轻或者消除食品安全风险，未造成危害后果的，可以从轻或者减轻处罚。"},{"i":77,"n":"第七十七条","txt":"县级以上地方人民政府食品安全监督管理等部门对有食品安全法第一百二十三条规定的违法情形且情节严重，可能需要行政拘留的，应当及时将案件及有关材料移送同级公安机关。公安机关认为需要补充材料的，食品安全监督管理等部门应当及时提供。公安机关经审查认为不符合行政拘留条件的，应当及时将案件及有关材料退回移送的食品安全监督管理等部门。"},{"i":78,"n":"第七十八条","txt":"公安机关对发现的食品安全违法行为，经审查没有犯罪事实或者立案侦查后认为不需要追究刑事责任，但依法应当予以行政拘留的，应当及时作出行政拘留的处罚决定；不需要予以行政拘留但依法应当追究其他行政责任的，应当及时将案件及有关材料移送同级食品安全监督管理等部门。"},{"i":79,"n":"第七十九条","txt":"复检机构无正当理由拒绝承担复检任务的，由县级以上人民政府食品安全监督管理部门给予警告，无正当理由1年内2次拒绝承担复检任务的，由国务院有关部门撤销其复检机构资质并向社会公布。"},{"i":80,"n":"第八十条","txt":"发布未依法取得资质认定的食品检验机构出具的食品检验信息，或者利用上述检验信息对食品、食品生产经营者进行等级评定，欺骗、误导消费者的，由县级以上人民政府食品安全监督管理部门责令改正，有违法所得的，没收违法所得，并处10万元以上50万元以下罚款；拒不改正的，处50万元以上100万元以下罚款；构成违反治安管理行为的，由公安机关依法给予治安管理处罚。"},{"i":81,"n":"第八十一条","txt":"食品安全监督管理部门依照食品安全法、本条例对违法单位或者个人处以30万元以上罚款的，由设区的市级以上人民政府食品安全监督管理部门决定。罚款具体处罚权限由国务院食品安全监督管理部门规定。"},{"i":82,"n":"第八十二条","txt":"阻碍食品安全监督管理等部门工作人员依法执行职务，构成违反治安管理行为的，由公安机关依法给予治安管理处罚。"},{"i":83,"n":"第八十三条","txt":"县级以上人民政府食品安全监督管理等部门发现单位或者个人违反食品安全法第一百二十条第一款规定，编造、散布虚假食品安全信息，涉嫌构成违反治安管理行为的，应当将相关情况通报同级公安机关。"},{"i":84,"n":"第八十四条","txt":"县级以上人民政府食品安全监督管理部门及其工作人员违法向他人提供网络食品交易第三方平台提供者提供的信息的，依照食品安全法第一百四十五条的规定给予处分。"},{"i":85,"n":"第八十五条","txt":"违反本条例规定，构成犯罪的，依法追究刑事责任。"},{"i":86,"n":"第八十六条","txt":"本条例自2019年12月1日起施行。"}],"zhongguorenminjiefangjunshishizhiyeyishifabanfa":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国执业医师法》（以下简称《执业医师法》）的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"军队的医师工作由中国人民解放军总政治部、总后勤部主管。"},{"i":3,"n":"第三条","txt":"军队人员具有《执业医师法》第九条、第十条规定的条件的，可以参加医师资格考试。"},{"i":4,"n":"第四条","txt":"军队人员的医师资格考试成绩和有关考试信息由国务院卫生行政部门通报总后勤部卫生部。"},{"i":5,"n":"第五条","txt":"取得医师资格的军队医师，可以向所在军区级单位政治机关干部部门和后勤（联勤）机关卫生部门申请医师执业注册。"},{"i":6,"n":"第六条","txt":"未经执业注册取得军队医师执业证书的，不得在军队从事医师执业活动。"},{"i":7,"n":"第七条","txt":"军队医师注册后有《执业医师法》第十六条所列情形之一或者下列情形之一的，所在单位应当在30日内报告准予注册的机关，由该机关注销注册并收回军队医师执业证书："},{"i":8,"n":"第八条","txt":"军队医师在军区级单位内变动执业类别和执业范围的，应当到准予注册的机关办理变更注册手续。"},{"i":9,"n":"第九条","txt":"军队医师转业、复员以及离休、退休后由地方人民政府安置并继续从事医疗、预防、保健业务的，应当交回军队医师执业证书，并持军队原准予注册的机关出具的证明，到所在地县级以上人民政府卫生行政部门申请办理变更注册手续，领取医师执业证书。"},{"i":10,"n":"第十条","txt":"地方医师入伍后继续从事医疗、预防、保健业务的，应当交回医师执业证书，并持地方原准予注册的机关出具的证明，到所在军区级单位后勤（联勤）机关卫生部门申请办理变更注册手续，领取军队医师执业证书。"},{"i":11,"n":"第十一条","txt":"军区级单位政治机关干部部门和后勤（联勤）机关卫生部门应当于每年十二月底以前向总政治部干部部、总后勤部卫生部报告当年军队医师准予注册、注销注册和变更注册的有关情况。"},{"i":12,"n":"第十二条","txt":"军队医师除应当履行《执业医师法》第二十二条规定的义务外，还应当履行下列义务："},{"i":13,"n":"第十三条","txt":"军队医师不得有下列行为："},{"i":14,"n":"第十四条","txt":"军队医师的考核和培训由军区级单位政治机关干部部门、后勤（联勤）机关卫生部门，按照《执业医师法》和军队的有关规定组织实施。"},{"i":15,"n":"第十五条","txt":"军队医师有下列情形之一的，依照《中国人民解放军纪律条令》的有关规定，给予表彰或者奖励："},{"i":16,"n":"第十六条","txt":"军队人员以不正当手段取得医师执业证书的，由军队发给证书的部门予以吊销；对负有直接责任的主管人员和其他直接责任人员，依照《中国人民解放军纪律条令》的有关规定，给予处分。"},{"i":17,"n":"第十七条","txt":"军队医师有《执业医师法》第三十七条所列行为之一或者下列行为之一的，依照《中国人民解放军纪律条令》的有关规定，给予处分，军队团级以上单位后勤（联勤）机关卫生部门并可以责令暂停六个月以上一年以下执业活动；情节严重的，吊销执业证书；构成犯罪的，依法追究刑事责任："},{"i":18,"n":"第十八条","txt":"军队人员非医师行医的，依照《中国人民解放军纪律条令》的有关规定，给予处分；给患者造成损害的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":19,"n":"第十九条","txt":"1998年6月26日《执业医师法》公布前按照国家和军队有关规定取得卫生专业技术职务的军队人员，由所在团级以上单位政治机关干部部门、后勤（联勤）机关卫生部门或者团级以上医疗、预防、保健机构医务部门和政治部门报军区级单位政治机关干部部门、后勤（联勤）机关卫生部门认定，取得相应的医师资格。其中仍在军队医疗、预防、保健机构或者岗位从事医疗、预防、保健业务的医师，依照《执业医师法》和本办法的有关规定，由所在团级单位集体核报军区级单位政治机关干部部门、后勤（联勤）机关卫生部门，予以注册并发给军队医师执业证书。"},{"i":20,"n":"第二十条","txt":"在军队基层单位从事预防、保健和一般医疗服务的卫生员，由总后勤部另行制定管理办法。"},{"i":21,"n":"第二十一条","txt":"军队医疗、预防、保健机构聘用地方医师，必须经军区级单位后勤（联勤）机关卫生部门审核。所聘用人员必须依法取得医师资格，经聘用单位出具证明，到原执业注册的卫生行政部门办理变更执业注册手续，交回原医师执业证书，由军区级单位后勤（联勤）机关卫生部门办理执业注册手续。"},{"i":22,"n":"第二十二条","txt":"中国人民武装警察部队的医师工作适用本办法。"},{"i":23,"n":"第二十三条","txt":"本办法自公布之日起施行。"}],"zhongguorenminjiefangjunshishiyaopinguanlifabanfa":[{"i":1,"n":"第一条","txt":"为了加强军队药品管理，根据《中华人民共和国药品管理法》和其他有关法律规定，制定本办法。"},{"i":2,"n":"第二条","txt":"军队药品研制、生产（含配制，下同）、储备、供应、使用和监督管理活动，适用本办法。"},{"i":3,"n":"第三条","txt":"军队药品管理工作坚持中国共产党的领导，贯彻习近平强军思想，坚持风险管理、全程管控、军地协同的原则，科学严格监管，保障药品的安全、有效、可及。"},{"i":4,"n":"第四条","txt":"在中央军事委员会领导下，中央军事委员会后勤保障部负责组织指导军队药品监督管理工作，具体工作由中央军事委员会后勤保障部负责卫生工作的业务部门承办；中央军事委员会机关其他部门按照职责分工做好与药品有关的监督管理工作。"},{"i":5,"n":"第五条","txt":"中央军事委员会后勤保障部负责卫生工作的业务部门与国务院药品监督管理部门和省、自治区、直辖市人民政府药品监督管理部门建立注册审评、联合监管、专业培训、信息通报等工作协调机制，协同开展药品监督管理工作。"},{"i":6,"n":"第六条","txt":"军队药品专业技术机构依法承担军队药品监督管理所需的审评、检验、核查、监测与评价等工作。"},{"i":7,"n":"第七条","txt":"军队单位应当按照国家和军队药品追溯有关标准和规范加强管理，实现药品可追溯。"},{"i":8,"n":"第八条","txt":"对在军队药品研制、生产、储备、供应、使用和监督管理工作中做出突出贡献的单位和个人，按照国家和军队有关规定给予表彰、奖励。"},{"i":9,"n":"第九条","txt":"军队实行战备药品储备制度。"},{"i":10,"n":"第十条","txt":"军队建立军队基本药物目录，提高基本药物的储备和供给能力，满足军队人员伤病防治基本用药需求。"},{"i":11,"n":"第十一条","txt":"军队医疗机构、药材供应保障机构应当从药品上市许可持有人或者具有药品生产、经营资格的企业购进药品；但是，购进未实施审批管理的中药材除外。"},{"i":12,"n":"第十二条","txt":"军队医疗机构、药材供应保障机构购进药品，应当建立并执行进货检查验收制度，验明药品合格证明和其他标识，有真实、完整、可追溯的药品购进记录。"},{"i":13,"n":"第十三条","txt":"军队药材供应保障机构应当按照划定区域和指定任务，负责军队单位所需药品的供应保障。"},{"i":14,"n":"第十四条","txt":"军队药材供应保障机构从事药品供应保障活动，应当取得中央军事委员会后勤保障部负责卫生工作的业务部门核发的军队药材供应许可证；无军队药材供应许可证的，不得供应药品。"},{"i":15,"n":"第十五条","txt":"军队人员需要接种的疫苗，由军队疾病预防控制机构按照国家规定的疫苗采购渠道向疫苗上市许可持有人采购；对未纳入国家组织采购的疫苗，可以按照军队采购有关规定向疫苗上市许可持有人采购。疫苗上市许可持有人应当按照采购合同约定，向军队疾病预防控制机构或者其指定的军队单位供应疫苗。"},{"i":16,"n":"第十六条","txt":"军队医疗机构应当配备经过国家或者军队资格认定的药师或者其他药学技术人员，负责本单位的药品管理、处方审核和调配、合理用药指导等工作。"},{"i":17,"n":"第十七条","txt":"军队医疗机构应当坚持安全有效、经济合理的用药原则。"},{"i":18,"n":"第十八条","txt":"军队医疗机构配制制剂，应当取得中央军事委员会后勤保障部负责卫生工作的业务部门核发的军队医疗机构制剂许可证。"},{"i":19,"n":"第十九条","txt":"军队医疗机构配制的制剂应当在本单位使用。经中央军事委员会后勤保障部负责卫生工作的业务部门或者军兵种负责卫生工作的业务部门批准，可以在指定的军队医疗机构之间调剂使用。"},{"i":20,"n":"第二十条","txt":"发生重大灾情、疫情以及其他突发事件或者临床急需而市场上没有供应时，经中央军事委员会后勤保障部负责卫生工作的业务部门和国务院药品监督管理部门或者省、自治区、直辖市人民政府药品监督管理部门批准，医疗机构配制的制剂可以在指定的军队医疗机构和地方医疗机构之间调剂使用。"},{"i":21,"n":"第二十一条","txt":"军队特需药品，是指军队用于防治战伤和军事特殊环境引发疾病，以及满足军事行动特定作业人员需求的药品。"},{"i":22,"n":"第二十二条","txt":"投入生产的军队特需药品应当经过注册，取得中央军事委员会后勤保障部负责卫生工作的业务部门核发的批准证明文件。"},{"i":23,"n":"第二十三条","txt":"从事军队特需药品生产活动的单位，应当取得中央军事委员会后勤保障部负责卫生工作的业务部门核发的军队特需药品生产与配制许可证；其中，地方生产单位取得军队特需药品生产与配制许可证后，应当向所在省、自治区、直辖市人民政府药品监督管理部门备案。"},{"i":24,"n":"第二十四条","txt":"军队特需药品研制单位委托生产军队特需药品的，应当与符合条件的生产单位签订委托协议和质量协议，并对生产活动进行监督，确保军队特需药品质量安全。"},{"i":25,"n":"第二十五条","txt":"军队特需药品应当在军队内部使用；地方单位因特殊情况需要购进军队特需药品的，应当经国务院药品监督管理部门或者省、自治区、直辖市人民政府药品监督管理部门审核，并经中央军事委员会后勤保障部负责卫生工作的业务部门同意。"},{"i":26,"n":"第二十六条","txt":"中央军事委员会后勤保障部负责卫生工作的业务部门与国务院药品监督管理部门建立技术支持协作机制，为军队特需药品的审评、检验、核查、监测与评价等工作提供支撑。"},{"i":27,"n":"第二十七条","txt":"军队后勤保障部门应当对军队药品研制、生产、储备、供应、使用等活动进行监督检查，并对军队特需药品、医疗机构制剂以及国家有特殊管理规定的药品实施重点监督检查。"},{"i":28,"n":"第二十八条","txt":"中央军事委员会后勤保障部负责卫生工作的业务部门制定军队药品质量抽查检验计划，组织对军队单位生产、储备、供应、使用的药品以及委托生产的军队特需药品进行抽查检验。药品质量抽查检验结果按照规定向军队有关单位和地方有关药品监督管理部门通报。"},{"i":29,"n":"第二十九条","txt":"军队药品专业技术机构应当根据抽查检验任务和军队有关单位提出的药品质量检验需求，对相关药品进行质量检验，及时出具检验结论。"},{"i":30,"n":"第三十条","txt":"对药品质量检验结论有异议的，可以自收到药品质量检验结论之日起7日内向原军队药品专业技术机构或者其上一级药品专业技术机构申请复验。受理复验的军队药品专业技术机构应当在规定的时间内作出复验结论。"},{"i":31,"n":"第三十一条","txt":"对在军队医疗机构使用且有证据证明可能危害人体健康的药品及其有关材料，军队医疗机构应当立即停用，采取封存管控等措施，并逐级上报至中央军事委员会后勤保障部负责卫生工作的业务部门处理；其中，从地方单位购进的药品，由中央军事委员会后勤保障部负责卫生工作的业务部门协调国务院药品监督管理部门或者省、自治区、直辖市人民政府药品监督管理部门按照国家有关规定处理。"},{"i":32,"n":"第三十二条","txt":"军队医疗机构、药材供应保障机构、特需药品研制单位和生产单位，应当经常考察本单位所生产、供应、使用的药品质量、疗效和不良反应。发现疑似不良反应的，应当按照国家和军队有关规定报告并采取风险控制措施。"},{"i":33,"n":"第三十三条","txt":"中央军事委员会后勤保障部负责卫生工作的业务部门和军兵种负责卫生工作的业务部门应当对军队医疗机构配制的制剂和军队特需药品组织评估，发现疗效不确定、不良反应大或者因其他原因危害人体健康的，应当注销其批准证明文件。"},{"i":34,"n":"第三十四条","txt":"任何单位和个人不得以军队单位或者军队人员的名义、形象或者利用军队装备、设施等从事药品商业宣传。"},{"i":35,"n":"第三十五条","txt":"军队药品监督员应当参加国家或者地方药品检查员培训并取得相应资格，按照规定的职责从事军队药品监督工作。"},{"i":36,"n":"第三十六条","txt":"地方单位或者人员认为军队单位和人员违反本办法规定的，可以向县级以上地方人民政府承担药品监督管理职责的部门检举、控告，由省、自治区、直辖市人民政府药品监督管理部门通报中央军事委员会后勤保障部负责卫生工作的业务部门，中央军事委员会后勤保障部负责卫生工作的业务部门依法组织查处和通报。"},{"i":37,"n":"第三十七条","txt":"国家和军队对麻醉药品、精神药品、医疗用毒性药品、放射性药品、药品类易制毒化学品、疫苗和血液制品等有特殊管理规定的，依照其规定执行。"},{"i":38,"n":"第三十八条","txt":"未取得军队特需药品生产与配制许可证、军队药材供应许可证或者军队医疗机构制剂许可证生产、供应药品的，责令停止有关活动，没收违法生产、供应的药品和违法所得。"},{"i":39,"n":"第三十九条","txt":"军队医疗机构使用假药、劣药的，没收其使用的假药、劣药和违法所得，责令改正；情节严重的，有关责任人员有医疗卫生人员执业证书的，还应当吊销其执业证书。"},{"i":40,"n":"第四十条","txt":"军队单位和人员知道或者应当知道属于假药、劣药，而利用军队设施、运输工具为其提供储存、运输等便利条件的，扣押储存、运输的药品，按照有关规定处理，并没收全部储存、运输收入。"},{"i":41,"n":"第四十一条","txt":"伪造、变造、出租、出借、买卖军队特需药品生产与配制许可证、军队药材供应许可证、军队医疗机构制剂许可证、军队医疗机构制剂批准证明文件、军队特需药品批准证明文件的，没收违法所得；情节严重的，吊销相关许可证或者批准证明文件。"},{"i":42,"n":"第四十二条","txt":"提供虚假的证明、数据、资料、样品或者采取其他不正当手段骗取军队特需药品生产与配制许可、军队药材供应许可、军队医疗机构制剂许可或者军队特需药品注册、军队医疗机构制剂注册等许可的，撤销相关许可，10年内不受理其相应申请。"},{"i":43,"n":"第四十三条","txt":"军队医疗机构、药材供应保障机构、疾病预防控制机构从药品上市许可持有人或者具有药品生产、经营资格的企业以外的地方单位和个人购进药品的，责令改正，没收违法购进的药品和违法所得。"},{"i":44,"n":"第四十四条","txt":"军队医疗机构、药材供应保障机构未按照规定建立并执行药品进货检查验收制度、药品保管制度的，责令改正，给予警告。"},{"i":45,"n":"第四十五条","txt":"军队特需药品研制单位和生产单位、药材供应保障机构，未经批准向地方单位或者个人提供军队特需药品的，责令停止有关活动，限期追回药品，没收违法所得。"},{"i":46,"n":"第四十六条","txt":"军队单位和人员，收受药品上市许可持有人、药品生产企业、药品经营企业或者其代理人给予的财物或者其他不正当利益的，没收违法所得；情节严重的，有关责任人员有医疗卫生人员执业证书的，还应当吊销其执业证书。"},{"i":47,"n":"第四十七条","txt":"军队医疗机构配制假劣制剂的，责令停止配制，没收违法配制的制剂和违法所得，吊销相关制剂批准证明文件；情节严重的，吊销军队医疗机构制剂许可证，10年内不受理其相应申请。"},{"i":48,"n":"第四十八条","txt":"军队医疗机构将其配制的制剂在市场上销售或者未经批准调剂使用制剂的，责令改正，没收违法销售、使用的制剂和违法所得；情节严重的，吊销军队医疗机构制剂许可证。"},{"i":49,"n":"第四十九条","txt":"军队医疗机构、药材供应保障机构、特需药品研制单位和生产单位，未按照规定开展药品不良反应监测或者报告疑似药品不良反应的，责令改正，给予警告。"},{"i":50,"n":"第五十条","txt":"军队单位和人员违反本办法规定从事药品商业宣传的，责令改正，没收违法所得。"},{"i":51,"n":"第五十一条","txt":"违反本办法规定，有下列情形之一的，应当撤销相关许可："},{"i":52,"n":"第五十二条","txt":"军队药品专业技术机构违反本办法规定，有下列行为之一的，责令改正，给予警告，没收违法所得；情节严重的，撤销其检验资格："},{"i":53,"n":"第五十三条","txt":"对军队单位和人员违反本办法规定的处罚，由军队有关部门按照职责权限作出决定；撤销许可、吊销许可证或者批准证明文件的，由原批准、发证的部门作出决定。"},{"i":54,"n":"第五十四条","txt":"军队单位和人员、国家机关及其工作人员在军队药品管理工作中滥用职权、玩忽职守、徇私舞弊，或者有其他违反本办法规定行为的，对负有责任的领导人员和直接责任人员，依法依规给予处分。"},{"i":55,"n":"第五十五条","txt":"违反本办法规定，构成犯罪的，依法追究刑事责任。"},{"i":56,"n":"第五十六条","txt":"本办法所称军队医疗机构，包括军队医院、部队卫生机构、派驻门诊医疗机构和干休所门诊部等单位。"},{"i":57,"n":"第五十七条","txt":"本办法所称军队药品专业技术机构，是指军队设置的药品仪器监督检验总站、药品仪器监督检验站以及承担药品监测和评价任务的军队医疗机构、科研机构等单位。"},{"i":58,"n":"第五十八条","txt":"军队战备药品、医疗机构制剂、特需药品的具体管理办法，由中央军事委员会后勤保障部制定。"},{"i":59,"n":"第五十九条","txt":"中国人民武装警察部队的药品管理工作，适用本办法。"},{"i":60,"n":"第六十条","txt":"本办法自2025年6月1日起施行。"}],"yinzhukeziyezanxingguanliguize":[{"i":1,"n":"第一条","txt":"为加强社会治安，保障印铸刻字业的合法经营，防范不法分子伪造假冒，特制定本规则。"},{"i":2,"n":"第二条","txt":"凡经营铸造厂、制版社（制造钢印、铜版、胶版、石印版、珂罗版、火印、锌印、证明牌号等）、印刷局（以机械或化学材料印刷簿册、证券、商标等）、证章店、刻字店、刻字摊（雕刻戳记、印版、印章、胶皮印等）及所有上属性质之营业者，不论专营、兼营、公营、私营，（国家机关专用不以营业为目的者例外）或属何国籍，除法令另有规定者外，均依本规则管理之。"},{"i":3,"n":"第三条","txt":"公章刻制经营者取得市场监管部门核发的营业执照后，应当在5日内将以下信息材料向所在地县级人民政府公安机关备案："},{"i":4,"n":"第四条","txt":"凡在本规则颁布前，已开业之印铸刻字业，均须补办第三条规定之手续。"},{"i":5,"n":"第五条","txt":"凡经营印铸刻字业者，均须遵守下列事项："},{"i":6,"n":"第六条","txt":"公安机关可以通过网络等方式，便利公章刻制经营者备案，并应当向备案的公章刻制经营者免费提供或者协助其安装公章刻制信息备案系统软件。"},{"i":7,"n":"第七条","txt":"违反本规则第三条第一款、第三款规定的，由公安机关责令限期改正，予以警告；逾期不改正的，对公章刻制经营者处3000元以上3万元以下罚款。公章刻制经营者备案时提供虚假信息的，由公安机关责令限期改正，并处5000元以上1万元以下罚款；逾期不改正的，处1万元以上5万元以下罚款。"},{"i":8,"n":"第八条","txt":"凡遵照本规则各条规定进行报告、检举，因而查获重大罪犯、破获重大案件者，由公安局酌情予以名誉或物质奖励。"},{"i":9,"n":"第九条","txt":"省级以上人民公安机关，得依据本规则之精神，制定补充办法；县（市）级人民公安机关如有制定补充办法之必要时，须经省级人民公安机关批准。"},{"i":10,"n":"第十条","txt":"本规则经中央人民政府政务院政治法律委员会批准，由中央人民政府公安部发布施行。"}],"guowuyuanguanyuzaiwoguotongyishixingfadingjiliangde9034a":[],"guowuyuanguanyushishigongsifazhucezibendengjiguanl95cfc1":[{"i":1,"n":"第一条","txt":"为了加强公司注册资本登记管理，规范股东依法履行出资义务，维护市场交易安全，优化营商环境，根据《中华人民共和国公司法》（以下简称公司法），制定本规定。"},{"i":2,"n":"第二条","txt":"2024年6月30日前登记设立的公司，有限责任公司剩余认缴出资期限自2027年7月1日起超过5年的，应当在2027年6月30日前将其剩余认缴出资期限调整至5年内并记载于公司章程，股东应当在调整后的认缴出资期限内足额缴纳认缴的出资额；股份有限公司的发起人应当在2027年6月30日前按照其认购的股份全额缴纳股款。"},{"i":3,"n":"第三条","txt":"公司出资期限、注册资本明显异常的，公司登记机关可以结合公司的经营范围、经营状况以及股东的出资能力、主营项目、资产规模等进行研判，认定违背真实性、合理性原则的，可以依法要求其及时调整。"},{"i":4,"n":"第四条","txt":"公司调整股东认缴和实缴的出资额、出资方式、出资期限，或者调整发起人认购的股份数等，应当自相关信息产生之日起20个工作日内通过国家企业信用信息公示系统向社会公示。"},{"i":5,"n":"第五条","txt":"公司登记机关采取随机抽取检查对象、随机选派执法检查人员的方式，对公司公示认缴和实缴情况进行监督检查。"},{"i":6,"n":"第六条","txt":"公司未按照本规定调整出资期限、注册资本的，由公司登记机关责令改正；逾期未改正的，由公司登记机关在国家企业信用信息公示系统作出特别标注并向社会公示。"},{"i":7,"n":"第七条","txt":"公司因被吊销营业执照、责令关闭或者被撤销，或者通过其住所、经营场所无法联系被列入经营异常名录，出资期限、注册资本不符合本规定且无法调整的，公司登记机关对其另册管理，在国家企业信用信息公示系统作出特别标注并向社会公示。"},{"i":8,"n":"第八条","txt":"公司自被吊销营业执照、责令关闭或者被撤销之日起，满3年未向公司登记机关申请注销公司登记的，公司登记机关可以通过国家企业信用信息公示系统予以公告，公告期限不少于60日。"},{"i":9,"n":"第九条","txt":"公司的股东或者发起人未按照本规定缴纳认缴的出资额或者股款，或者公司未依法公示有关信息的，依照公司法、《企业信息公示暂行条例》的有关规定予以处罚。"},{"i":10,"n":"第十条","txt":"公司登记机关应当对公司调整出资期限、注册资本加强指导，制定具体操作指南，优化办理流程，提高登记效率，提升登记便利化水平。"},{"i":11,"n":"第十一条","txt":"国务院市场监督管理部门根据本规定，制定公司注册资本登记管理的具体实施办法。"},{"i":12,"n":"第十二条","txt":"上市公司依照公司法和国务院规定，在公司章程中规定在董事会中设置审计委员会，并载明审计委员会的组成、职权等事项。"},{"i":13,"n":"第十三条","txt":"本规定自公布之日起施行。"}],"guowuyuanshishiminzuquyuzizhifaruoganguiding":[{"i":1,"n":"第一条","txt":"为了帮助民族自治地方加快经济和社会的发展，增进民族团结，促进各民族共同繁荣，根据《中华人民共和国民族区域自治法》，制定本规定。"},{"i":2,"n":"第二条","txt":"各级人民政府应当加强《中华人民共和国民族区域自治法》以及相关法律、法规和民族政策的宣传教育，依法制订具体措施，保护少数民族的合法权益，妥善处理影响民族团结的问题，巩固和发展平等、团结、互助的社会主义民族关系，禁止破坏民族团结和制造民族分裂的行为。"},{"i":3,"n":"第三条","txt":"维护祖国统一和民族团结是公民的职责和义务。"},{"i":4,"n":"第四条","txt":"各级人民政府应当积极开展促进民族团结进步的各项活动，对为民族团结进步事业作出突出贡献的单位和个人，给予表彰和奖励。"},{"i":5,"n":"第五条","txt":"上级人民政府及其职能部门在制订经济和社会发展中长期规划时，应当听取民族自治地方和民族工作部门的意见，根据民族自治地方的特点和需要，支持和帮助民族自治地方加强基础设施建设、人力资源开发，扩大对外开放，调整、优化经济结构，合理利用自然资源，加强生态建设和环境保护，加速发展经济、教育、科技、文化、卫生、体育等各项事业，实现全面、协调、可持续发展。"},{"i":6,"n":"第六条","txt":"国家实施西部大开发战略，促进民族自治地方加快发展。未列入西部大开发范围的自治县，由其所在的省级人民政府在职权范围内比照西部大开发的有关政策予以扶持。"},{"i":7,"n":"第七条","txt":"上级人民政府应当根据民族自治地方的实际，优先在民族自治地方安排基础设施建设项目。"},{"i":8,"n":"第八条","txt":"国家根据经济和社会发展规划以及西部大开发战略，优先在民族自治地方安排资源开发和深加工项目。在民族自治地方开采石油、天然气等资源的，要在带动当地经济发展、发展相应的服务产业以及促进就业等方面，对当地给予支持。"},{"i":9,"n":"第九条","txt":"国家通过一般性财政转移支付、专项财政转移支付、民族优惠政策财政转移支付以及其他方式，充分考虑民族自治地方的公共服务支出成本差异，逐步加大对民族自治地方财政转移支付力度。上级人民政府有关部门各种专项资金的分配，应当向民族自治地方倾斜。"},{"i":10,"n":"第十条","txt":"国家设立各项专用资金，扶助民族自治地方发展经济和社会各项事业。"},{"i":11,"n":"第十一条","txt":"国家帮助民族自治地方拓宽间接和直接融资渠道，加大对民族自治地方的金融扶持力度。"},{"i":12,"n":"第十二条","txt":"国家完善扶持民族贸易、少数民族特需商品和传统手工业品生产发展的优惠政策，在税收、金融和财政政策上，对民族贸易、少数民族特需商品和传统手工业品生产予以照顾，对少数民族特需商品实行定点生产并建立必要的国家储备制度。"},{"i":13,"n":"第十三条","txt":"国家鼓励与外国接壤的民族自治地方依法与周边国家开展区域经济技术合作和边境贸易。"},{"i":14,"n":"第十四条","txt":"国家将边境地区建设纳入经济和社会发展规划，帮助民族自治地方加快边境地区建设，推进兴边富民行动，促进边境地区与内地的协调发展。"},{"i":15,"n":"第十五条","txt":"上级人民政府将人口较少民族聚居的地区发展纳入经济和社会发展规划，加大扶持力度，在交通、能源、生态环境保护与建设、农业基础设施建设、广播影视、文化、教育、医疗卫生以及群众生产生活等方面，给予重点支持。"},{"i":16,"n":"第十六条","txt":"国家加强民族自治地方的扶贫开发，重点支持民族自治地方贫困乡村以通水、通电、通路、通广播电视和茅草房危房改造、生态移民等为重点的基础设施建设和农田基本建设，动员和组织社会力量参与民族自治地方的扶贫开发。"},{"i":17,"n":"第十七条","txt":"国家鼓励、支持和引导民族自治地方发展非公有制经济，鼓励社会资本参与民族自治地方的基础设施、公用事业以及其他领域的建设和国有、集体企业改制。"},{"i":18,"n":"第十八条","txt":"国家组织和支持经济发达地区与民族自治地方的对口支援。通过劳动密集型和资源加工型产业的转移、技术转让、交流培训人才、加大资金投入、提供物资支持等多种方式，帮助民族自治地方加速经济、文化、教育、科技、卫生、体育事业的发展；鼓励和引导企业、高等院校和科研单位以及社会各方面力量加大对民族自治地方的支持力度。"},{"i":19,"n":"第十九条","txt":"国家帮助民族自治地方普及九年义务教育，扫除青壮年文盲，不断改善办学条件，大力支持民族自治地方有重点地办好寄宿制学校；在发达地区普通中学开设民族班或者开办民族中学，其办学条件、教学和管理水平要达到当地学校的办学标准和水平。"},{"i":20,"n":"第二十条","txt":"各级人民政府应当将民族自治地方义务教育纳入公共财政的保障范围。中央财政设立少数民族教育专项补助资金，地方财政相应安排少数民族教育专项补助资金。"},{"i":21,"n":"第二十一条","txt":"国家帮助和支持民族自治地方发展高等教育，办好民族院校和全国普通高等学校民族预科班、民族班。对民族自治地方的高等学校以及民族院校的学科建设和研究生招生，给予特殊的政策扶持。"},{"i":22,"n":"第二十二条","txt":"国家保障各民族使用和发展本民族语言文字的自由，扶持少数民族语言文字的规范化、标准化和信息处理工作；推广使用全国通用的普通话和规范汉字；鼓励民族自治地方各民族公民互相学习语言文字。"},{"i":23,"n":"第二十三条","txt":"国家帮助民族自治地方建立健全科技服务体系和科学普及体系。中央财政通过国家科技计划、科学基金、专项资金等方式，加大对民族自治地方科技工作的支持力度，积极支持和促进民族自治地方科技事业的发展。"},{"i":24,"n":"第二十四条","txt":"上级人民政府从政策和资金上支持民族自治地方少数民族文化事业发展，加强文化基础设施建设，重点扶持具有民族形式和民族特点的公益性文化事业，加强民族自治地方的公共文化服务体系建设，培育和发展民族文化产业。"},{"i":25,"n":"第二十五条","txt":"上级人民政府支持对少数民族非物质文化遗产和名胜古迹、文物等物质文化遗产的保护和抢救，支持对少数民族古籍的搜集、整理、出版。"},{"i":26,"n":"第二十六条","txt":"上级人民政府加大对民族自治地方公共卫生体系建设的资金投入以及技术支持，采取有效措施预防控制传染病、地方病和寄生虫病，建立并完善农村卫生服务体系、新型农村合作医疗制度和医疗救助制度，减轻民族自治地方贫困群众医疗费的负担；各级人民政府加大对民族医药事业的投入，保护、扶持和发展民族医药学，提高各民族的健康水平。"},{"i":27,"n":"第二十七条","txt":"上级人民政府应当按照国家有关规定，帮助民族自治地方加快社会保障体系建设，建立和完善养老、失业、医疗、工伤、生育保险和城市居民最低生活保障等制度，形成与当地经济和社会发展水平相适应的社会保障体系。"},{"i":28,"n":"第二十八条","txt":"上级人民政府及其工作部门领导人员中应当合理配备少数民族干部；民族自治地方人民政府及其工作部门应当依法配备实行区域自治的民族和其他民族领导干部，在公开选拔、竞争上岗配备领导干部时，可以划出相应的名额和岗位，定向选拔少数民族干部。"},{"i":29,"n":"第二十九条","txt":"上级人民政府指导民族自治地方制订人才开发规划，采取各种有效措施，积极培养使用实行区域自治的民族和其他民族的各级各类人才。"},{"i":30,"n":"第三十条","txt":"各级人民政府民族工作部门对本规定的执行情况实施监督检查，每年将监督检查的情况向同级人民政府报告，并提出意见和建议。"},{"i":31,"n":"第三十一条","txt":"对违反国家财政制度、财务制度，挪用、克扣、截留国家财政用于民族自治地方经费的，责令限期归还被挪用、克扣、截留的经费，并依法对直接负责的主管人员和其他直接责任人员给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"各级人民政府行政部门违反本规定，不依法履行职责，由其上级行政机关或者监察机关责令改正。"},{"i":33,"n":"第三十三条","txt":"本规定所称上级人民政府，是指民族自治地方的上级人民政府。"},{"i":34,"n":"第三十四条","txt":"国务院有关部门、自治区和辖有自治州、自治县的省、直辖市人民政府在职权范围内，根据本规定制订具体办法，并将执行情况向国务院报告。"},{"i":35,"n":"第三十五条","txt":"本规定自2005年5月31日起施行。"}],"guowuyuanduiquexubaoliudexingzhengshenpixiangmushe467b32":[],"waiguominyonghangkongqifeixingguanliguize":[{"i":1,"n":"第一条","txt":"外国民用航空器飞入或者飞出中华人民共和国国界和在中华人民共和国境内飞行或者停留时，必须遵守本规则。"},{"i":2,"n":"第二条","txt":"外国民用航空器只有根据中华人民共和国政府同该国政府签订的航空运输协定或者其他有关文件，或者通过外交途径向中华人民共和国政府申请，在得到答复接受后，才准飞入或者飞出中华人民共和国国界和在中华人民共和国境内飞行。"},{"i":3,"n":"第三条","txt":"外国民用航空器及其空勤组成员和乘客，在中华人民共和国境内飞行或者停留时，必须遵守中华人民共和国的法律和有关入境、出境、过境的法令规章。"},{"i":4,"n":"第四条","txt":"外国民用航空器飞入或者飞出中华人民共和国国界和在中华人民共和国境内飞行，必须服从国务院民用航空主管部门各有关的空中交通管制部门的管制，并且遵守有关飞行的各项规章。"},{"i":5,"n":"第五条","txt":"外国民用航空器根据中华人民共和国政府同该国政府签订的航空运输协定，可以在中华人民共和国境内按照协定中规定的航线进行定期航班飞行和加班飞行。"},{"i":6,"n":"第六条","txt":"外国民用航空器在中华人民共和国境内进行定期航班飞行和加班飞行以外的一切不定期飞行，必须预先提出申请，在得到答复接受后，才能进行。"},{"i":7,"n":"第七条","txt":"不定期飞行的申请，应当包括下列内容："},{"i":8,"n":"第八条","txt":"外国民用航空器在中华人民共和国境内进行不定期飞行时，由国务院民用航空主管部门指派飞行人员（包括领航员和无线电通信员）随机引导，如果许可中有特别规定的，依照规定。"},{"i":9,"n":"第九条","txt":"在中华人民共和国境内飞行的外国民用航空器，必须具有国籍标志和登记标志。没有国籍标志和登记标志的外国民用航空器，禁止在中华人民共和国境内飞行。"},{"i":10,"n":"第十条","txt":"在中华人民共和国境内飞行的外国民用航空器，应当具有下列文件："},{"i":11,"n":"第十一条","txt":"外国民用航空器飞入或者飞出中华人民共和国国界，必须从规定的空中走廊或者进出口通过。禁止偏离空中走廊或者进出口。"},{"i":12,"n":"第十二条","txt":"外国民用航空器飞入或者飞出中华人民共和国国界前二十至十五分钟，其空勤组必须向国务院民用航空主管部门有关的空中交通管制部门报告：航空器的呼号，预计飞入或者飞出国界的时间和飞行的高度，并且取得飞入或者飞出国界的许可。没有得到许可，不得飞入或者飞出国界。"},{"i":13,"n":"第十三条","txt":"外国民用航空器飞越中华人民共和国国界和中华人民共和国境内规定的位置报告点，应当立即向国务院民用航空主管部门有关的空中交通管制部门作位置报告。位置报告的内容："},{"i":14,"n":"第十四条","txt":"外国民用航空器飞入或者飞出中华人民共和国国界后，如果因为天气变坏、航空器发生故障或者其他特殊原因不能继续飞行，允许其从原航路及空中走廊或者进出口返航。此时，空勤组应当向国务院民用航空主管部门有关的空中交通管制部门报告：航空器呼号，被迫返航的原因，开始返航的时间，飞行的高度，以及返航后预定降落的机场。在中华人民共和国境内，如果没有接到国务院民用航空主管部门有关的空中交通管制部门的指示，通常应当在原高度层的下一反航向的高度层上返航；如果该高度层低于飞行的安全高度，则应当在原高度层的上一反航向的高度层上返航。"},{"i":15,"n":"第十五条","txt":"外国民用航空器在没有同国务院民用航空主管部门有关的空中交通管制部门沟通无线电联络以前，禁止飞入或者飞出中华人民共和国国界和在中华人民共和国境内飞行。"},{"i":16,"n":"第十六条","txt":"外国民用航空器在中华人民共和国境内飞行，如果与国务院民用航空主管部门有关的空中交通管制部门的航空电台通信联络中断时，其空勤组应当设法与其他航空电台或者空中其他航空器沟通联络，传递飞行情报。如果仍然无法恢复联络，则该航空器应当按照下列规定飞行："},{"i":17,"n":"第十七条","txt":"中华人民共和国境内航空器飞行的目视气象条件：能见度不少于八公里，航空器距离云的垂直距离不少于三百米，航空器距离云的水平距离不少于一千五百米。"},{"i":18,"n":"第十八条","txt":"飞行的安全高度是保证航空器不致与地面障碍物相撞的最低的飞行高度。"},{"i":19,"n":"第十九条","txt":"外国民用航空器在中华人民共和国境内飞行，必须在规定的飞行高度或者高度层上进行。"},{"i":20,"n":"第二十条","txt":"外国民用航空器在中华人民共和国境内每次飞行的高度或者高度层，由国务院民用航空主管部门有关的空中交通管制部门指定。"},{"i":21,"n":"第二十一条","txt":"外国民用航空器在中华人民共和国境内必须沿规定的航路飞行。禁止偏离航路。"},{"i":22,"n":"第二十二条","txt":"在中华人民共和国境内飞行的外国民用航空器，其空勤组如果不能判定航空器的位置时，应当立即报告国务院民用航空主管部门有关的空中交通管制部门。"},{"i":23,"n":"第二十三条","txt":"目视飞行时航空器相遇，应当按照下列规定避让："},{"i":24,"n":"第二十四条","txt":"外国民用航空器在中华人民共和国境内飞行时，应当按照国务院民用航空主管部门规定的无线电通信的方式和无线电频率，同国务院民用航空主管部门有关的空中交通管制部门保持不间断地守听，以便及时地进行通信联络。"},{"i":25,"n":"第二十五条","txt":"在中华人民共和国境内飞行的外国民用航空器，应当在国务院民用航空主管部门指定的机场降落。降落前应当取得降落机场的空中交通管制部门的许可；降落后，没有经过许可，不得起飞。"},{"i":26,"n":"第二十六条","txt":"外国民用航空器的空勤组必须在起飞前做好飞行准备工作，机长或其代理人至少要在预计起飞前一小时向国务院民用航空主管部门有关的空中交通管制部门提交飞行计划。"},{"i":27,"n":"第二十七条","txt":"中华人民共和国境内机场的起落航线飞行通常为左航线。起落航线的飞行高度，通常为三百米至五百米。进行起落航线飞行时，禁止超越同型或者速度相接近的航空器。航空器之间的纵向间隔，一般应当保持在二千米以上，并且还要考虑航空器尾流的影响。经过机场空中交通管制员许可，大速度航空器可以在第三转弯前从外侧超越小速度航空器，其横向间隔不得小于五百米。除被迫必须立即降落的航空器外，任何航空器不得从内侧超越前面的航空器。"},{"i":28,"n":"第二十八条","txt":"外国民用航空器在航空站区域内目视气象条件下飞行时，其空勤组应当进行严密的空中观察，防止与其他航空器碰撞；如果发生碰撞，航空器的机长应负直接责任。"},{"i":29,"n":"第二十九条","txt":"外国民用航空器在中华人民共和国境内的机场起飞或者降落，高度表拨正程序按照下列规定进行："},{"i":30,"n":"第三十条","txt":"外国民用航空器在中华人民共和国境内起飞或者降落时，应当遵守国务院民用航空主管部门规定的机场气象最低条件。当机场的天气实况低于机场气象最低条件时，航空器不得起飞或者着陆。在紧急情况下，如果航空器的机长决定低于机场气象最低条件着陆，须对其决定和由此产生的后果负完全的责任。"},{"i":31,"n":"第三十一条","txt":"在中华人民共和国境内的航路上或者起飞、降落机场附近有威胁航空器飞行的危险天气时，国务院民用航空主管部门有关的空中交通管制部门可以向外国民用航空器的机长提出推迟起飞、返航或者飞往备降机场的建议；航空器的机长对此类建议有最后的决定权并对其决定负责。"},{"i":32,"n":"第三十二条","txt":"在中华人民共和国境内飞行的外国民用航空器，如果发现可能危及飞行安全的严重故障时，国务院民用航空主管部门的有关部门有权制止该航空器继续飞行，并且通知其登记国；该航空器可否继续飞行，由航空器登记国确定。"},{"i":33,"n":"第三十三条","txt":"外国民用航空器在中华人民共和国境内飞行时，无论在任何情况下，均不准飞入中华人民共和国划定的空中禁区。国务院民用航空主管部门对飞入空中禁区的外国民用航空器的机长，将给予严肃处理，并且对该航空器飞入空中禁区所产生的一切后果，不负任何责任。"},{"i":34,"n":"第三十四条","txt":"在特殊情况下，国务院民用航空主管部门公布临时关闭有关的航路或者机场时，与该航路或者机场飞行有关的外国民用航空器，必须根据国务院民用航空主管部门的航行通告或者有关的空中交通管制部门的通知，修订飞行计划。"},{"i":35,"n":"第三十五条","txt":"在中华人民共和国境内飞行的外国民用航空器，除遇险情况下的跳伞外，只有得到国务院民用航空主管部门有关的空中交通管制部门的许可，并且在指定的条件下，才可以向地面投掷物品、喷洒液体和使用降落伞。"},{"i":36,"n":"第三十六条","txt":"在中华人民共和国境内飞行的外国民用航空器，如果发生严重危及航空器和机上人员安全，并且需要立即援助的情况时，其空勤组应当立即向国务院民用航空主管部门有关的空中交通管制部门发出遇险信号，以便及时进行搜寻和援救。遇险信号以无线电话发出时用“MAYDAY”，以无线电报发出时用“SOS”。遇险航空器在发出遇险信号后，应当尽可能将航空器呼号，遇险性质，现在的位置、高度、航向和机长的意图在遇险通信中发出。遇险通信应当在当时使用的地空无线电通信频率上发出；必要时，按照国务院民用航空主管部门有关的空中交通管制部门的通知，将通信频率转到紧急频率上继续进行联络。这种紧急频率在航行资料汇编中提供。"},{"i":37,"n":"第三十七条","txt":"在中华人民共和国境内飞行的外国民用航空器，如果发生可能危及航空器或者机上人员安全，但不需要立即援助的情况时，其空勤组应当立即向国务院民用航空主管部门有关的空中交通管制部门发出紧急信号。紧急信号以无线电话发出时用“PAN”，以无线电报发出时用“XXX”。遇有紧急情况的航空器，在发出紧急信号后，还应当将航空器呼号，紧急情况的性质，现在的位置、高度、航向和机长的意图在紧急通信中发出。紧急通信应当在当地使用的地空无线电通信频率上发出；必要时，按照国务院民用航空主管部门有关的空中交通管制部门的通知，将通信频率转到紧急频率上继续进行联络。这种紧急频率在航行资料汇编中提供。"},{"i":38,"n":"第三十八条","txt":"飞入或者飞出中华人民共和国国界的外国民用航空器，必须在指定的设有海关和边防检查站的机场降落或者起飞。"},{"i":39,"n":"第三十九条","txt":"在中华人民共和国境内的外国民用航空器（包括其必须具备的文件以及空勤组成员、乘客和所载物品），应受中华人民共和国有关机关的检查。"},{"i":40,"n":"第四十条","txt":"在中华人民共和国境内飞行的外国民用航空器，禁止载运爆炸物、易燃物、武器、弹药以及中华人民共和国政府规定的其他违禁品。"},{"i":41,"n":"第四十一条","txt":"外国民用航空器在飞行中，如果空勤组成员或者乘客患急病，空勤组应当报告有关的空中交通管制部门，以便在降落后取得协助为病员进行必要的医疗。"},{"i":42,"n":"第四十二条","txt":"在中华人民共和国境内飞行的外国民用航空器，如果违反本规则，中国人民解放军防空值班飞机可以强迫其在指定机场降落。违反国务院民用航空主管部门有关的空中交通管制部门的指示，以违反本规则论。"},{"i":43,"n":"第四十三条","txt":"飞入或者飞出中华人民共和国国界和在中华人民共和国境内飞行或者停留的外国民用航空器，其空勤组成员和乘客，如果违反本规则，由国务院民用航空主管部门或者其他主管机关根据具体情况给予罚款及其他处分；情节重大的由中华人民共和国人民法院处理。"},{"i":44,"n":"第四十四条","txt":"本规则经中华人民共和国国务院批准后，由国务院民用航空主管部门发布施行。"}],"waiguojifeijunyongchuanbotongguoqiongzhouhaixiaguaf80045":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国政府关于领海的声明》，琼州海峡是中国的内海，一切外国籍军用船舶不得通过，一切外国籍非军用船舶如需通过，必须按照本规则的规定申请批准。"},{"i":2,"n":"第二条","txt":"为便利对琼州海峡进行管理，设“中华人民共和国琼州海峡管理处”（以下简称琼州海峡管理处）。"},{"i":3,"n":"第三条","txt":"琼州海峡管理处对琼州海峡管理的区域（以下简称管理区）暂定如下：木栏头灯桩（约北纬二十度零九分三十七秒、东经一百一十度四十一分）与生狗吼沙灯桩（约北纬二十度二十六分、东经一百一十度三十分二十二秒）联线（简称东线）以西，尾角灯桩（约北纬二十度十三分三十秒、东经一百零九度五十五分三十秒）与临高角灯桩（约北纬二十度零零分二十二秒、东经一百零九度四十二分零六秒）联线（简称西线）以东的水域。"},{"i":4,"n":"第四条","txt":"外国籍非军用船舶如需通过琼州海峡，必须办理以下手续："},{"i":5,"n":"第五条","txt":"琼州海峡管理处对于已经批准通过海峡的外国籍非军用船舶，认为必要时，可以临时通知禁止通过。"},{"i":6,"n":"第六条","txt":"外国籍非军用船舶通过管理区的时间，一律以白天为限，均应在日出后进入管理区，日落前全部通过管理区。琼州海峡管理处根据申请过峡外国籍非军用船舶的航速，核准其进出海峡的具体时间。"},{"i":7,"n":"第七条","txt":"外国籍非军用船舶进出琼州海峡一律走中水道，但经琼州海峡管理处特别许可的不在此限。"},{"i":8,"n":"第八条","txt":"外国籍非军用船舶通过管理区时，应在下列规定的航区范围内航行：自东线距木栏头灯桩四浬处至西线距临高角灯桩四浬处联线以北，自东线距木栏头灯桩六浬处至排尾角灯桩正南四浬处继至西线距临高角灯桩十四浬处联线以南的水域。"},{"i":9,"n":"第九条","txt":"外国籍非军用船舶通过琼州海峡，必须严格按照所报时间及规定的航区通行。在进入管理区和在管理区通行时，如见有从岸上或舰艇上发出的信号，应立即回答并无条件地执行信号要求。由于不遵守上述规定而发生的后果概由船方自行负责。"},{"i":10,"n":"第十条","txt":"外国籍非军用船舶通过琼州海峡时，不得使用雷达。如在航行中遇浓雾、暴雨等视线恶劣的情况，需要使用雷达时，应向琼州海峡管理处提出报告，说明理由以及当时的船位、航速等，经批准后方准使用。如当时情况紧急，危及船舶航行安全时，可以一面申报一面使用，并在事后，将使用起迄时间和经过情况详细报告琼州海峡管理处备案。"},{"i":11,"n":"第十一条","txt":"外国籍非军用船舶通过琼州海峡时，不准进行照像、测量以及其他违反中华人民共和国法令的行为。"},{"i":12,"n":"第十二条","txt":"外国籍非军用船舶违反本规则，按下列规定处理："}],"shishifanwaiguozhicaifadeguiding":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国对外关系法》、《中华人民共和国反外国制裁法》（以下简称反外国制裁法）等法律，制定本规定。"},{"i":2,"n":"第二条","txt":"反外国制裁工作贯彻总体国家安全观，维护国家主权、安全、发展利益，保护我国公民、组织的合法权益。"},{"i":3,"n":"第三条","txt":"外国国家违反国际法和国际关系基本准则，以各种借口或者依据其本国法律对我国进行遏制、打压，对我国公民、组织采取歧视性限制措施，干涉我国内政的，或者外国国家、组织、个人实施、协助、支持危害我国主权、安全、发展利益的行为的，国务院有关部门根据反外国制裁法和本规定，有权决定将有关组织、个人及与其相关的组织、个人列入反制清单、采取反制措施。"},{"i":4,"n":"第四条","txt":"国务院有关部门在实施反外国制裁法和本规定过程中，有权开展相应调查和对外磋商。"},{"i":5,"n":"第五条","txt":"国务院有关部门作出采取反制措施的决定，应当明确反制措施的适用对象、具体反制措施、施行日期等。"},{"i":6,"n":"第六条","txt":"反外国制裁法第六条第一项中的不予签发签证、不准入境、注销签证或者驱逐出境，由国务院外交、国家移民管理等有关部门，依照职责权限实施。"},{"i":7,"n":"第七条","txt":"反外国制裁法第六条第二项中的查封、扣押、冻结，由国务院公安、财政、自然资源、交通运输、海关、市场监督管理、金融管理、知识产权等有关部门，依照职责权限实施。"},{"i":8,"n":"第八条","txt":"反外国制裁法第六条第三项中的禁止或者限制我国境内的组织、个人与其进行有关交易、合作等活动，包括但不限于教育、科技、法律服务、环保、经贸、文化、旅游、卫生、体育领域的活动，由国务院教育、科技、司法行政、生态环境、商务、文化和旅游、卫生健康、体育行政等有关部门，依照职责权限实施。"},{"i":9,"n":"第九条","txt":"反外国制裁法第六条第四项中的其他必要措施，包括但不限于禁止或者限制从事与我国有关的进出口活动，禁止或者限制在我国境内投资，禁止向其出口相关物项，禁止或者限制向其提供数据、个人信息，取消或者限制其相关人员在我国境内工作许可、停留或者居留资格，处以罚款。"},{"i":10,"n":"第十条","txt":"国务院外交、商务、发展改革、司法行政等部门按照各自职责和任务分工，负责承担反外国制裁工作协调机制相关工作。国务院有关部门加强对反制措施确定和实施的协同配合和信息共享。"},{"i":11,"n":"第十一条","txt":"国务院有关部门作出采取、暂停、变更或者取消有关反制措施决定的，应当通过其官方网站等途径发布并及时更新。"},{"i":12,"n":"第十二条","txt":"反制措施需要国务院其他部门实施的，作出采取、暂停、变更或者取消反制措施决定的国务院有关部门应当按照相关程序，将反制措施的决定通报负责实施的国务院有关部门。"},{"i":13,"n":"第十三条","txt":"国务院有关部门对不依法执行反制措施的，有权责令改正，禁止或者限制其从事政府采购、招标投标以及有关货物、技术的进出口或者国际服务贸易等活动，禁止或者限制其从境外接收或者向境外提供数据、个人信息，禁止或者限制其出境、在我国境内停留居留等。"},{"i":14,"n":"第十四条","txt":"采取反制措施的决定公布后，被采取反制措施的组织、个人可以向作出采取反制措施决定的国务院有关部门申请暂停、变更或者取消有关反制措施，申请时应当提供其改正行为、采取措施消除行为后果等方面的事实和理由。"},{"i":15,"n":"第十五条","txt":"作出采取反制措施决定的国务院有关部门可以根据实际情况组织评估反制措施的执行情况和效果。"},{"i":16,"n":"第十六条","txt":"采取反制措施的决定公布后，有关组织、个人在特殊情况下确需与被采取反制措施的组织、个人进行被禁止或者限制的相关活动的，应当向作出采取反制措施决定的国务院有关部门提供相应的事实和理由，经同意可以与被采取反制措施的组织、个人进行相关活动。"},{"i":17,"n":"第十七条","txt":"对执行或者协助执行外国国家对我国公民、组织采取的歧视性限制措施的，国务院有关部门有权进行约谈，责令改正，采取相应处理措施。"},{"i":18,"n":"第十八条","txt":"任何组织和个人执行或者协助执行外国国家对我国公民、组织采取的歧视性限制措施，侵害我国公民、组织合法权益的，我国公民、组织有权依法向人民法院提起诉讼，要求停止侵害、赔偿损失。"},{"i":19,"n":"第十九条","txt":"外国国家、组织或者个人通过推动、实施诉讼等手段危害我国主权、安全、发展利益的，国务院有关部门有权决定将参与诉讼和判决执行等活动的上述主体及与其相关的组织、个人列入反制清单，采取限制入境，查封、扣押、冻结在我国境内的财产，禁止或者限制与其进行有关交易、合作等反制措施，并保留采取强制执行财产以及其他更严厉反制措施的权利。"},{"i":20,"n":"第二十条","txt":"鼓励支持律师事务所、公证机构等专业服务机构为反外国制裁提供法律服务，包括协助相关组织、个人为执行反制措施实施风险控制管理，代理我国公民、组织就相关组织、个人因执行或者协助执行外国国家歧视性限制措施侵害合法权益向人民法院提起诉讼，办理相关公证业务等。"},{"i":21,"n":"第二十一条","txt":"在实施反外国制裁法和本规定过程中，涉及司法协助相关工作的，由国务院司法行政部门会同主管机关依照我国有关法律、缔结或者参加的国际条约办理。"},{"i":22,"n":"第二十二条","txt":"本规定自公布之日起施行。"}],"zhengwuyuanguanyuzhongyangrenminzhengfusuoshugejig475917":[],"cunzhuanghejizhenguihuajiansheguanlitiaoli":[{"i":1,"n":"第一条","txt":"为加强村庄、集镇的规划建设管理，改善村庄、集镇的生产、生活环境，促进农村经济和社会发展，制定本条例。"},{"i":2,"n":"第二条","txt":"制定和实施村庄、集镇规划，在村庄、集镇规划区内进行居民住宅、乡（镇）村企业、乡（镇）村公共设施和公益事业等的建设，必须遵守本条例。但是，国家征用集体所有的土地进行的建设除外。"},{"i":3,"n":"第三条","txt":"本条例所称村庄，是指农村村民居住和从事各种生产的聚居点。"},{"i":4,"n":"第四条","txt":"村庄、集镇规划建设管理，应当坚持合理布局、节约用地的原则，全面规划，正确引导，依靠群众，自力更生，因地制宜，量力而行，逐步建设，实现经济效益、社会效益和环境效益的统一。"},{"i":5,"n":"第五条","txt":"地处洪涝、地震、台风、滑坡等自然灾害易发地区的村庄和集镇，应当按照国家和地方的有关规定，在村庄、集镇总体规划中制定防灾措施。"},{"i":6,"n":"第六条","txt":"国务院建设行政主管部门主管全国的村庄、集镇规划建设管理工作。"},{"i":7,"n":"第七条","txt":"国家鼓励村庄、集镇规划建设管理的科学研究，推广先进技术，提倡在村庄和集镇建设中，结合当地特点，采用新工艺、新材料、新结构。"},{"i":8,"n":"第八条","txt":"村庄、集镇规划由乡级人民政府负责组织编制，并监督实施。"},{"i":9,"n":"第九条","txt":"村庄、集镇规划的编制，应当遵循下列原则："},{"i":10,"n":"第十条","txt":"村庄、集镇规划的编制，应当以县域规划、农业区划、土地利用总体规划为依据，并同有关部门的专业规划相协调。"},{"i":11,"n":"第十一条","txt":"编制村庄、集镇规划，一般分为村庄、集镇总体规划和村庄、集镇建设规划两个阶段进行。"},{"i":12,"n":"第十二条","txt":"村庄、集镇总体规划，是乡级行政区域内村庄和集镇布点规划及相应的各项建设的整体部署。"},{"i":13,"n":"第十三条","txt":"村庄、集镇建设规划，应当在村庄、集镇总体规划指导下，具体安排村庄、集镇的各项建设。"},{"i":14,"n":"第十四条","txt":"村庄、集镇总体规划和集镇建设规划，须经乡级人民代表大会审查同意，由乡级人民政府报县级人民政府批准。"},{"i":15,"n":"第十五条","txt":"根据社会经济发展需要，依照本条例第十四条的规定，经乡级人民代表大会或者村民会议同意，乡级人民政府可以对村庄、集镇规划进行局部调整，并报县级人民政府备案。涉及村庄、集镇的性质、规模、发展方向和总体布局重大变更的，依照本条例第十四条规定的程序办理。"},{"i":16,"n":"第十六条","txt":"村庄、集镇规划期限，由省、自治区、直辖市人民政府根据本地区实际情况规定。"},{"i":17,"n":"第十七条","txt":"村庄、集镇规划经批准后，由乡级人民政府公布。"},{"i":18,"n":"第十八条","txt":"农村村民在村庄、集镇规划区内建住宅的，应当先向村集体经济组织或者村民委员会提出建房申请，经村民会议讨论通过后，按照下列审批程序办理："},{"i":19,"n":"第十九条","txt":"兴建乡（镇）村企业，必须持县级以上地方人民政府批准的设计任务书或者其他批准文件，向县级人民政府建设行政主管部门申请选址定点，县级人民政府建设行政主管部门审查同意并出具选址意见书后，建设单位方可依法向县级人民政府土地管理部门申请用地，经县级以上人民政府批准后，由土地管理部门划拨土地。"},{"i":20,"n":"第二十条","txt":"乡（镇）村公共设施、公益事业建设，须经乡级人民政府审核、县级人民政府建设行政主管部门审查同意并出具选址意见书后，建设单位方可依法向县级人民政府土地管理部门申请用地，经县级以上人民政府批准后，由土地管理部门划拨土地。"},{"i":21,"n":"第二十一条","txt":"在村庄、集镇规划区内，凡建筑跨度、跨径或者高度超出规定范围的乡（镇）村企业、乡（镇）村公共设施和公益事业的建筑工程，以及二层（含二层）以上的住宅，必须由取得相应的设计资质证书的单位进行设计，或者选用通用设计、标准设计。"},{"i":22,"n":"第二十二条","txt":"建筑设计应当贯彻适用、经济、安全和美观的原则，符合国家和地方有关节约资源、抗御灾害的规定，保持地方特色和民族风格，并注意与周围环境相协调。"},{"i":23,"n":"第二十三条","txt":"承担村庄、集镇规划区内建筑工程施工任务的单位，必须具有相应的施工资质等级证书或者资质审查证书，并按照规定的经营范围承担施工任务。"},{"i":24,"n":"第二十四条","txt":"施工单位应当按照设计图纸施工。任何单位和个人不得擅自修改设计图纸；确需修改的，须经原设计单位同意，并出具变更设计通知单或者图纸。"},{"i":25,"n":"第二十五条","txt":"施工单位应当确保施工质量，按照有关的技术规定施工，不得使用不符合工程质量要求的建筑材料和建筑构件。"},{"i":26,"n":"第二十六条","txt":"乡（镇）村企业、乡（镇）村公共设施、公益事业等建设，在开工前，建设单位和个人应当向县级以上人民政府建设行政主管部门提出开工申请，经县级以上人民政府建设行政主管部门对设计、施工条件予以审查批准后，方可开工。"},{"i":27,"n":"第二十七条","txt":"县级人民政府建设行政主管部门，应当对村庄、集镇建设的施工质量进行监督检查。村庄、集镇的建设工程竣工后，应当按照国家的有关规定，经有关部门竣工验收合格后，方可交付使用。"},{"i":28,"n":"第二十八条","txt":"县级以上人民政府建设行政主管部门，应当加强对村庄、集镇房屋的产权、产籍的管理，依法保护房屋所有人对房屋的所有权。具体办法由国务院建设行政主管部门制定。"},{"i":29,"n":"第二十九条","txt":"任何单位和个人都应当遵守国家和地方有关村庄、集镇的房屋、公共设施的管理规定，保证房屋的使用安全和公共设施的正常使用，不得破坏或者损毁村庄、集镇的道路、桥梁、供水、排水、供电、邮电、绿化等设施。"},{"i":30,"n":"第三十条","txt":"从集镇收取的城市维护建设税，应当用于集镇公共设施的维护和建设，不得挪作他用。"},{"i":31,"n":"第三十一条","txt":"乡级人民政府应当采取措施，保护村庄、集镇饮用水源；有条件的地方，可以集中供水，使水质逐步达到国家规定的生活饮用水卫生标准。"},{"i":32,"n":"第三十二条","txt":"未经乡级人民政府批准，任何单位和个人不得擅自在村庄、集镇规划区内的街道、广场、市场和车站等场所修建临时建筑物、构筑物和其他设施。"},{"i":33,"n":"第三十三条","txt":"任何单位和个人都应当维护村容镇貌和环境卫生，妥善处理粪堆、垃圾堆、柴草堆，养护树木花草，美化环境。"},{"i":34,"n":"第三十四条","txt":"任何单位和个人都有义务保护村庄、集镇内的文物古迹、古树名木和风景名胜、军事设施、防汛设施，以及国家邮电、通信、输变电、输油管道等设施，不得损坏。"},{"i":35,"n":"第三十五条","txt":"乡级人民政府应当按照国家有关规定，对村庄、集镇建设中形成的具有保存价值的文件、图纸、资料等及时整理归档。"},{"i":36,"n":"第三十六条","txt":"在村庄、集镇规划区内，未按规划审批程序批准而取得建设用地批准文件，占用土地的，批准文件无效，占用的土地由乡级以上人民政府责令退回。"},{"i":37,"n":"第三十七条","txt":"在村庄、集镇规划区内，未按规划审批程序批准或者违反规划的规定进行建设，严重影响村庄、集镇规划的，由县级人民政府建设行政主管部门责令停止建设，限期拆除或者没收违法建筑物、构筑物和其他设施；影响村庄、集镇规划，尚可采取改正措施的，由县级人民政府建设行政主管部门责令限期改正，处以罚款。"},{"i":38,"n":"第三十八条","txt":"有下列行为之一的，由县级人民政府建设行政主管部门责令停止设计或者施工、限期改正，并可处以罚款："},{"i":39,"n":"第三十九条","txt":"有下列行为之一的，由乡级人民政府责令停止侵害，可以处以罚款；造成损失的，并应当赔偿："},{"i":40,"n":"第四十条","txt":"擅自在村庄、集镇规划区内的街道、广场、市场和车站等场所修建临时建筑物、构筑物和其他设施的，由乡级人民政府责令限期拆除，并可处以罚款。"},{"i":41,"n":"第四十一条","txt":"损坏村庄、集镇内的文物古迹、古树名木和风景名胜、军事设施、防汛设施，以及国家邮电、通信、输变电、输油管道等设施的，依照有关法律、法规的规定处罚。"},{"i":42,"n":"第四十二条","txt":"违反本条例，构成违反治安管理行为的，依照治安管理处罚条例的规定处罚；构成犯罪的，依法追究刑事责任。"},{"i":43,"n":"第四十三条","txt":"村庄、集镇建设管理人员玩忽职守、滥用职权、徇私舞弊的，由所在单位或者上级主管部门给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":44,"n":"第四十四条","txt":"当事人对行政处罚决定不服的，可以自接到处罚决定通知之日起15日内，向作出处罚决定机关的上一级机关申请复议；对复议决定不服的，可以自接到复议决定之日起15日内，向人民法院提起诉讼。当事人也可以自接到处罚决定通知之日起15日内，直接向人民法院起诉。当事人逾期不申请复议，也不向人民法院提起诉讼，又不履行处罚决定的，作出处罚决定的机关可以申请人民法院强制执行或者依法强制执行。"},{"i":45,"n":"第四十五条","txt":"未设镇建制的国营农场场部、国营林场场部及其基层居民点的规划建设管理，分别由国营农场、国营林场主管部门负责，参照本条例执行。"},{"i":46,"n":"第四十六条","txt":"省、自治区、直辖市人民政府可以根据本条例制定实施办法。"},{"i":47,"n":"第四十七条","txt":"本条例由国务院建设行政主管部门负责解释。"},{"i":48,"n":"第四十八条","txt":"本条例自一九九三年十一月一日起施行。"}],"fakuanjuedingyufakuanshoujiaofenlishishibanfa":[{"i":1,"n":"第一条","txt":"为了实施罚款决定与罚款收缴分离，加强对罚款收缴活动的监督，保证罚款及时上缴国库，根据《中华人民共和国行政处罚法》（以下简称行政处罚法）的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"罚款的收取、缴纳及相关活动，适用本办法。"},{"i":3,"n":"第三条","txt":"作出罚款决定的行政机关应当与收缴罚款的机构分离；但是，依照行政处罚法的规定可以当场收缴罚款的除外。"},{"i":4,"n":"第四条","txt":"罚款必须全部上缴国库，任何行政机关、组织或者个人不得以任何形式截留、私分或者变相私分。"},{"i":5,"n":"第五条","txt":"经中国人民银行批准有代理收付款项业务的商业银行、信用合作社（以下简称代收机构），可以开办代收罚款的业务。"},{"i":6,"n":"第六条","txt":"行政机关应当依照本办法和国家有关规定，同代收机构签订代收罚款协议。"},{"i":7,"n":"第七条","txt":"行政机关作出罚款决定的行政处罚决定书应当载明代收机构的名称、地址和当事人应当缴纳罚款的数额、期限等，并明确对当事人逾期缴纳罚款是否加处罚款。"},{"i":8,"n":"第八条","txt":"代收机构代收罚款，应当向当事人出具罚款收据。"},{"i":9,"n":"第九条","txt":"当事人逾期缴纳罚款，行政处罚决定书明确需要加处罚款的，代收机构应当按照行政处罚决定书加收罚款。"},{"i":10,"n":"第十条","txt":"代收机构应当按照代收罚款协议规定的方式、期限，将当事人的姓名或者名称、缴纳罚款的数额、时间等情况书面告知作出行政处罚决定的行政机关。"},{"i":11,"n":"第十一条","txt":"代收机构应当按照行政处罚法和国家有关规定，将代收的罚款直接上缴国库。"},{"i":12,"n":"第十二条","txt":"国库应当按照《中华人民共和国国家金库条例》的规定，定期同财政部门和行政机关对账，以保证收受的罚款和上缴国库的罚款数额一致。"},{"i":13,"n":"第十三条","txt":"代收机构应当在代收网点、营业时间、服务设施、缴款手续等方面为当事人缴纳罚款提供方便。"},{"i":14,"n":"第十四条","txt":"财政部门应当向代收机构支付手续费，具体标准由财政部制定。"},{"i":15,"n":"第十五条","txt":"法律、法规授权的具有管理公共事务职能的组织和依法受委托的组织依法作出的罚款决定与罚款收缴，适用本办法。"},{"i":16,"n":"第十六条","txt":"本办法由财政部会同中国人民银行组织实施。"},{"i":17,"n":"第十七条","txt":"本办法自1998年1月1日起施行。"}],"xingzhengfaguizhidingchengxutiaoli":[{"i":1,"n":"第一条","txt":"为了规范行政法规制定程序，保证行政法规质量，根据宪法、立法法和国务院组织法的有关规定，制定本条例。"},{"i":2,"n":"第二条","txt":"行政法规的立项、起草、审查、决定、公布、解释，适用本条例。"},{"i":3,"n":"第三条","txt":"制定行政法规，应当坚持中国共产党的领导，贯彻落实党的路线方针政策和决策部署。"},{"i":4,"n":"第四条","txt":"制定政治方面法律的配套行政法规，应当按照有关规定及时报告党中央。"},{"i":5,"n":"第五条","txt":"制定行政法规，应当完整准确全面贯彻新发展理念，统筹发展和安全，注重立法与改革、发展、稳定相协同，注重保障和促进社会公平正义，优化法治化营商环境，服务高质量发展和高水平对外开放，建设法治政府，推进国家治理体系和治理能力现代化。"},{"i":6,"n":"第六条","txt":"制定行政法规，应当坚持科学立法、民主立法、依法立法，增强立法的系统性、整体性、协同性、时效性。"},{"i":7,"n":"第七条","txt":"制定行政法规，应当适应改革需要，引导、推动、规范、保障相关改革。"},{"i":8,"n":"第八条","txt":"对党和国家工作大局急需、人民群众迫切期盼，调整范围单一、有关方面没有较大争议的行政法规，应当快速响应，优化工作方式，加快相关立法工作。"},{"i":9,"n":"第九条","txt":"行政法规应当备而不繁，逻辑严密，条文明确、具体，用语准确、简洁，具有可操作性。"},{"i":10,"n":"第十条","txt":"国务院于每年年初编制本年度的立法工作计划。"},{"i":11,"n":"第十一条","txt":"国务院有关部门认为需要制定行政法规的，应当于国务院编制年度立法工作计划前，向国务院报请立项。"},{"i":12,"n":"第十二条","txt":"国务院有关部门报送行政法规立项申请，应当说明依据的党的路线方针政策和决策部署、立法项目的必要性和可行性、所要解决的主要问题、拟确立的主要制度及预期实施效果、有关风险评估及防范应对措施、已开展的工作情况等。"},{"i":13,"n":"第十三条","txt":"国务院法治部门拟订国务院年度立法工作计划时，应当结合立法项目的成熟程度、紧迫程度，突出重点领域、新兴领域、涉外领域，统筹兼顾，加强评估论证。"},{"i":14,"n":"第十四条","txt":"承担起草任务的国务院有关部门应当严格贯彻执行立法工作计划，抓紧工作，按照要求向国务院报送送审稿；报送国务院前，应当送国务院法治部门进行前置评估。国务院法治部门应当提出前置评估意见。起草部门应当认真研究处理，并在报送国务院的材料中对前置评估意见研究处理情况作出说明。"},{"i":15,"n":"第十五条","txt":"国务院有关部门起草的拟报请国务院批准印发的文件涉及立法项目的，应当征求国务院法治部门意见。"},{"i":16,"n":"第十六条","txt":"行政法规由国务院组织起草。国务院年度立法工作计划确定行政法规由国务院的一个部门或者几个部门具体负责起草工作，也可以确定由国务院法治部门起草或者组织起草。"},{"i":17,"n":"第十七条","txt":"起草行政法规，应当符合本条例第三条至第七条的规定，并符合下列要求："},{"i":18,"n":"第十八条","txt":"起草行政法规，应当坚持和发展全过程人民民主，拓展人民群众有序参与立法途径。起草部门应当通过多种方式深入调查研究，总结实践经验，广泛听取有关机关、组织和公民的意见。起草与经营主体生产经营活动密切相关的行政法规，应当听取有关企业和行业协会商会的意见。听取意见可以采取召开座谈会、论证会、听证会等多种形式。"},{"i":19,"n":"第十九条","txt":"起草行政法规，起草部门应当就涉及其他部门的职责或者与其他部门关系紧密的规定，与有关部门充分协商，涉及部门职责分工、行政许可、财政支持、税收优惠政策的，应当征得机构编制、财政、税务等相关部门同意。"},{"i":20,"n":"第二十条","txt":"起草行政法规，起草部门应当对涉及有关管理体制、政策等需要国务院决策的重大问题提出解决方案，报国务院决定。"},{"i":21,"n":"第二十一条","txt":"起草部门向国务院报送的送审稿，应当由起草部门主要负责人签发。"},{"i":22,"n":"第二十二条","txt":"起草部门将送审稿报送国务院审查时，应当一并报送送审稿的说明和有关材料。修改行政法规的，还应当报送修改前后的对照文本。"},{"i":23,"n":"第二十三条","txt":"报送国务院的送审稿，由国务院法治部门负责审查。国务院法治部门应当完善政府立法审查制度，提高审查质效。"},{"i":24,"n":"第二十四条","txt":"送审稿有下列情形之一的，国务院法治部门可以缓办或者退回，并书面告知起草部门："},{"i":25,"n":"第二十五条","txt":"国务院法治部门应当将送审稿或者送审稿涉及的主要问题发送国务院有关部门、地方人民政府、有关组织和专家等各方面征求意见。国务院有关部门、地方人民政府应当在规定期限内反馈书面意见，并加盖本单位或者本单位办公厅（室）印章。国务院法治部门认为送审稿中涉及合宪性问题的，应当征求全国人民代表大会常务委员会有关工作机构意见。"},{"i":26,"n":"第二十六条","txt":"国务院法治部门应当就送审稿涉及的主要问题，深入基层进行实地调查研究，听取基层有关机关、组织和公民的意见。"},{"i":27,"n":"第二十七条","txt":"送审稿涉及重大利益调整的，国务院法治部门应当进行论证咨询，广泛听取有关方面的意见。论证咨询可以采取座谈会、论证会、听证会、委托研究等多种形式。"},{"i":28,"n":"第二十八条","txt":"国务院有关部门对送审稿涉及的主要制度、政策、管理体制、权限分工等有不同意见的，国务院法治部门应当进行协调，力求达成一致意见。对有较大争议的重要立法事项，国务院法治部门可以委托有关专家、教学科研单位、社会组织进行评估。"},{"i":29,"n":"第二十九条","txt":"国务院法治部门应当认真研究各方面的意见，与起草部门协商后，对送审稿进行修改，形成行政法规草案和对草案的说明。"},{"i":30,"n":"第三十条","txt":"行政法规草案由国务院法治部门主要负责人提出提请国务院常务会议审议的建议；对调整范围单一、各方面意见一致或者依据法律制定的配套行政法规草案，可以采取传批方式，由国务院法治部门直接提请国务院审批。"},{"i":31,"n":"第三十一条","txt":"行政法规草案由国务院常务会议审议，或者由国务院审批。"},{"i":32,"n":"第三十二条","txt":"国务院法治部门应当根据国务院对行政法规草案的审议意见，对行政法规草案进行修改，形成草案修改稿，报请总理签署国务院令公布施行。"},{"i":33,"n":"第三十三条","txt":"行政法规签署公布后，及时在国务院公报和中国政府法制信息网以及在全国范围内发行的报纸上刊载。国务院法治部门应当及时汇编出版行政法规的国家正式版本，并纳入国家行政法规库。"},{"i":34,"n":"第三十四条","txt":"行政法规应当自公布之日起30日后施行；但是，涉及国家安全、外汇汇率、货币政策的确定以及公布后不立即施行将有碍行政法规施行的，可以自公布之日起施行。"},{"i":35,"n":"第三十五条","txt":"行政法规在公布后的30日内由国务院办公厅报全国人民代表大会常务委员会备案。"},{"i":36,"n":"第三十六条","txt":"行政法规有下列情形之一的，由国务院解释："},{"i":37,"n":"第三十七条","txt":"国务院各部门和省、自治区、直辖市人民政府可以向国务院提出行政法规解释要求。"},{"i":38,"n":"第三十八条","txt":"对属于行政工作中具体应用行政法规的问题，省、自治区、直辖市人民政府法治部门以及国务院有关部门法治机构请求国务院法治部门解释的，国务院法治部门可以研究答复；其中涉及重大问题的，由国务院法治部门提出意见，报国务院同意后答复。"},{"i":39,"n":"第三十九条","txt":"行政法规的名称一般称“条例”，也可以称“规定”、“办法”等。国务院根据全国人民代表大会及其常务委员会的授权决定制定的行政法规，称“暂行条例”或者“暂行规定”。"},{"i":40,"n":"第四十条","txt":"行政法规根据内容需要，可以分章、节、条、款、项、目。章、节、条的序号用中文数字依次表述，款不编序号，项的序号用中文数字加括号依次表述，目的序号用阿拉伯数字依次表述。"},{"i":41,"n":"第四十一条","txt":"行政法规明确要求对专门事项作出配套的具体规定的，国务院有关部门应当自行政法规施行之日起1年内作出规定；行政法规对配套的具体规定制定期限另有规定的，从其规定。国务院有关部门未能在期限内作出配套的具体规定的，应当向国务院说明情况。"},{"i":42,"n":"第四十二条","txt":"国务院可以根据经济社会发展、全面深化改革需要，就行政管理等领域的特定事项，决定授权在规定期限和范围内暂时调整或者暂时停止适用行政法规的部分规定。"},{"i":43,"n":"第四十三条","txt":"国务院法治部门应当根据全面深化改革、经济社会发展需要以及上位法规定，报国务院同意后及时组织开展行政法规清理工作。国务院有关部门可以根据工作需要，向国务院法治部门提出行政法规清理建议。"},{"i":44,"n":"第四十四条","txt":"国务院法治部门或者国务院有关部门可以组织对有关行政法规或者行政法规中的有关规定进行立法后评估，并把评估结果作为修改、废止有关行政法规的重要参考。"},{"i":45,"n":"第四十五条","txt":"行政法规的修改、废止程序适用本条例的有关规定。"},{"i":46,"n":"第四十六条","txt":"行政法规的外文正式译本和民族语言文本，由国务院法治部门审定。"},{"i":47,"n":"第四十七条","txt":"拟订国务院提请全国人民代表大会或者全国人民代表大会常务委员会审议的法律草案，参照本条例的有关规定办理。"},{"i":48,"n":"第四十八条","txt":"本条例自2026年7月1日起施行。"}],"guihuahuanjingyingxiangpingjiatiaoli":[{"i":1,"n":"第一条","txt":"为了加强对规划的环境影响评价工作，提高规划的科学性，从源头预防环境污染和生态破坏，促进经济、社会和环境的全面协调可持续发展，根据《中华人民共和国环境影响评价法》，制定本条例。"},{"i":2,"n":"第二条","txt":"国务院有关部门、设区的市级以上地方人民政府及其有关部门，对其组织编制的土地利用的有关规划和区域、流域、海域的建设、开发利用规划（以下称综合性规划），以及工业、农业、畜牧业、林业、能源、水利、交通、城市建设、旅游、自然资源开发的有关专项规划（以下称专项规划），应当进行环境影响评价。"},{"i":3,"n":"第三条","txt":"对规划进行环境影响评价，应当遵循客观、公开、公正的原则。"},{"i":4,"n":"第四条","txt":"国家建立规划环境影响评价信息共享制度。"},{"i":5,"n":"第五条","txt":"规划环境影响评价所需的费用应当按照预算管理的规定纳入财政预算，严格支出管理，接受审计监督。"},{"i":6,"n":"第六条","txt":"任何单位和个人对违反本条例规定的行为或者对规划实施过程中产生的重大不良环境影响，有权向规划审批机关、规划编制机关或者环境保护主管部门举报。有关部门接到举报后，应当依法调查处理。"},{"i":7,"n":"第七条","txt":"规划编制机关应当在规划编制过程中对规划组织进行环境影响评价。"},{"i":8,"n":"第八条","txt":"对规划进行环境影响评价，应当分析、预测和评估以下内容："},{"i":9,"n":"第九条","txt":"对规划进行环境影响评价，应当遵守有关环境保护标准以及环境影响评价技术导则和技术规范。"},{"i":10,"n":"第十条","txt":"编制综合性规划，应当根据规划实施后可能对环境造成的影响，编写环境影响篇章或者说明。"},{"i":11,"n":"第十一条","txt":"环境影响篇章或者说明应当包括下列内容："},{"i":12,"n":"第十二条","txt":"环境影响篇章或者说明、环境影响报告书（以下称环境影响评价文件），由规划编制机关编制或者组织规划环境影响评价技术机构编制。规划编制机关应当对环境影响评价文件的质量负责。"},{"i":13,"n":"第十三条","txt":"规划编制机关对可能造成不良环境影响并直接涉及公众环境权益的专项规划，应当在规划草案报送审批前，采取调查问卷、座谈会、论证会、听证会等形式，公开征求有关单位、专家和公众对环境影响报告书的意见。但是，依法需要保密的除外。"},{"i":14,"n":"第十四条","txt":"对已经批准的规划在实施范围、适用期限、规模、结构和布局等方面进行重大调整或者修订的，规划编制机关应当依照本条例的规定重新或者补充进行环境影响评价。"},{"i":15,"n":"第十五条","txt":"规划编制机关在报送审批综合性规划草案和专项规划中的指导性规划草案时，应当将环境影响篇章或者说明作为规划草案的组成部分一并报送规划审批机关。未编写环境影响篇章或者说明的，规划审批机关应当要求其补充；未补充的，规划审批机关不予审批。"},{"i":16,"n":"第十六条","txt":"规划编制机关在报送审批专项规划草案时，应当将环境影响报告书一并附送规划审批机关审查；未附送环境影响报告书的，规划审批机关应当要求其补充；未补充的，规划审批机关不予审批。"},{"i":17,"n":"第十七条","txt":"设区的市级以上人民政府审批的专项规划，在审批前由其环境保护主管部门召集有关部门代表和专家组成审查小组，对环境影响报告书进行审查。审查小组应当提交书面审查意见。"},{"i":18,"n":"第十八条","txt":"审查小组的专家应当从依法设立的专家库内相关专业的专家名单中随机抽取。但是，参与环境影响报告书编制的专家，不得作为该环境影响报告书审查小组的成员。"},{"i":19,"n":"第十九条","txt":"审查小组的成员应当客观、公正、独立地对环境影响报告书提出书面审查意见，规划审批机关、规划编制机关、审查小组的召集部门不得干预。"},{"i":20,"n":"第二十条","txt":"有下列情形之一的，审查小组应当提出对环境影响报告书进行修改并重新审查的意见："},{"i":21,"n":"第二十一条","txt":"有下列情形之一的，审查小组应当提出不予通过环境影响报告书的意见："},{"i":22,"n":"第二十二条","txt":"规划审批机关在审批专项规划草案时，应当将环境影响报告书结论以及审查意见作为决策的重要依据。"},{"i":23,"n":"第二十三条","txt":"已经进行环境影响评价的规划包含具体建设项目的，规划的环境影响评价结论应当作为建设项目环境影响评价的重要依据，建设项目环境影响评价的内容可以根据规划环境影响评价的分析论证情况予以简化。"},{"i":24,"n":"第二十四条","txt":"对环境有重大影响的规划实施后，规划编制机关应当及时组织规划环境影响的跟踪评价，将评价结果报告规划审批机关，并通报环境保护等有关部门。"},{"i":25,"n":"第二十五条","txt":"规划环境影响的跟踪评价应当包括下列内容："},{"i":26,"n":"第二十六条","txt":"规划编制机关对规划环境影响进行跟踪评价，应当采取调查问卷、现场走访、座谈会等形式征求有关单位、专家和公众的意见。"},{"i":27,"n":"第二十七条","txt":"规划实施过程中产生重大不良环境影响的，规划编制机关应当及时提出改进措施，向规划审批机关报告，并通报环境保护等有关部门。"},{"i":28,"n":"第二十八条","txt":"环境保护主管部门发现规划实施过程中产生重大不良环境影响的，应当及时进行核查。经核查属实的，向规划审批机关提出采取改进措施或者修订规划的建议。"},{"i":29,"n":"第二十九条","txt":"规划审批机关在接到规划编制机关的报告或者环境保护主管部门的建议后，应当及时组织论证，并根据论证结果采取改进措施或者对规划进行修订。"},{"i":30,"n":"第三十条","txt":"规划实施区域的重点污染物排放总量超过国家或者地方规定的总量控制指标的，应当暂停审批该规划实施区域内新增该重点污染物排放总量的建设项目的环境影响评价文件。"},{"i":31,"n":"第三十一条","txt":"规划编制机关在组织环境影响评价时弄虚作假或者有失职行为，造成环境影响评价严重失实的，对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":32,"n":"第三十二条","txt":"规划审批机关有下列行为之一的，对直接负责的主管人员和其他直接责任人员，依法给予处分："},{"i":33,"n":"第三十三条","txt":"审查小组的召集部门在组织环境影响报告书审查时弄虚作假或者滥用职权，造成环境影响评价严重失实的，对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":34,"n":"第三十四条","txt":"规划环境影响评价技术机构弄虚作假或者有失职行为，造成环境影响评价文件严重失实的，由国务院环境保护主管部门予以通报，处所收费用1倍以上3倍以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":35,"n":"第三十五条","txt":"省、自治区、直辖市人民政府可以根据本地的实际情况，要求本行政区域内的县级人民政府对其组织编制的规划进行环境影响评价。具体办法由省、自治区、直辖市参照《中华人民共和国环境影响评价法》和本条例的规定制定。"},{"i":36,"n":"第三十六条","txt":"本条例自2009年10月1日起施行。"}],"guizhangzhidingchengxutiaoli":[{"i":1,"n":"第一条","txt":"为了规范规章制定程序，保证规章质量，根据立法法的有关规定，制定本条例。"},{"i":2,"n":"第二条","txt":"规章的立项、起草、审查、决定、公布、解释，适用本条例。"},{"i":3,"n":"第三条","txt":"制定规章，应当贯彻落实党的路线方针政策和决策部署，遵循立法法确定的立法原则，符合宪法、法律、行政法规和其他上位法的规定。"},{"i":4,"n":"第四条","txt":"制定政治方面法律的配套规章，应当按照有关规定及时报告党中央或者同级党委（党组）。"},{"i":5,"n":"第五条","txt":"制定规章，应当切实保障公民、法人和其他组织的合法权益，在规定其应当履行的义务的同时，应当规定其相应的权利和保障权利实现的途径。"},{"i":6,"n":"第六条","txt":"制定规章，应当体现全面深化改革精神，科学规范行政行为，促进政府职能向宏观调控、市场监管、社会管理、公共服务、环境保护等方面转变。"},{"i":7,"n":"第七条","txt":"规章的名称一般称“规定”、“办法”，但不得称“条例”。"},{"i":8,"n":"第八条","txt":"规章用语应当准确、简洁，条文内容应当明确、具体，具有可操作性。"},{"i":9,"n":"第九条","txt":"涉及国务院两个以上部门职权范围的事项，制定行政法规条件尚不成熟，需要制定规章的，国务院有关部门应当联合制定规章。"},{"i":10,"n":"第十条","txt":"国务院部门内设机构或者其他机构认为需要制定部门规章的，应当向该部门报请立项。"},{"i":11,"n":"第十一条","txt":"报送制定规章的立项申请，应当对制定规章的必要性、所要解决的主要问题、拟确立的主要制度等作出说明。"},{"i":12,"n":"第十二条","txt":"国务院部门法制机构，省、自治区、直辖市和设区的市、自治州的人民政府法制机构（以下简称法制机构），应当对制定规章的立项申请和公开征集的规章制定项目建议进行评估论证，拟订本部门、本级人民政府年度规章制定工作计划，报本部门、本级人民政府批准后向社会公布。"},{"i":13,"n":"第十三条","txt":"国务院部门，省、自治区、直辖市和设区的市、自治州的人民政府，应当加强对执行年度规章制定工作计划的领导。对列入年度规章制定工作计划的项目，承担起草工作的单位应当抓紧工作，按照要求上报本部门或者本级人民政府决定。"},{"i":14,"n":"第十四条","txt":"部门规章由国务院部门组织起草，地方政府规章由省、自治区、直辖市和设区的市、自治州的人民政府组织起草。"},{"i":15,"n":"第十五条","txt":"起草规章，应当深入调查研究，总结实践经验，广泛听取有关机关、组织和公民的意见。听取意见可以采取书面征求意见、座谈会、论证会、听证会等多种形式。"},{"i":16,"n":"第十六条","txt":"起草规章，涉及社会公众普遍关注的热点难点问题和经济社会发展遇到的突出矛盾，减损公民、法人和其他组织权利或者增加其义务，对社会公众有重要影响等重大利益调整事项的，起草单位应当进行论证咨询，广泛听取有关方面的意见。"},{"i":17,"n":"第十七条","txt":"起草部门规章，涉及国务院其他部门的职责或者与国务院其他部门关系紧密的，起草单位应当充分征求国务院其他部门的意见。"},{"i":18,"n":"第十八条","txt":"起草单位应当将规章送审稿及其说明、对规章送审稿主要问题的不同意见和其他有关材料按规定报送审查。"},{"i":19,"n":"第十九条","txt":"规章送审稿由法制机构负责统一审查。法制机构主要从以下方面对送审稿进行审查："},{"i":20,"n":"第二十条","txt":"规章送审稿有下列情形之一的，法制机构可以缓办或者退回起草单位："},{"i":21,"n":"第二十一条","txt":"法制机构应当将规章送审稿或者规章送审稿涉及的主要问题发送有关机关、组织和专家征求意见。"},{"i":22,"n":"第二十二条","txt":"法制机构应当就规章送审稿涉及的主要问题，深入基层进行实地调查研究，听取基层有关机关、组织和公民的意见。"},{"i":23,"n":"第二十三条","txt":"规章送审稿涉及重大利益调整的，法制机构应当进行论证咨询，广泛听取有关方面的意见。论证咨询可以采取座谈会、论证会、听证会、委托研究等多种形式。"},{"i":24,"n":"第二十四条","txt":"有关机构或者部门对规章送审稿涉及的主要措施、管理体制、权限分工等问题有不同意见的，法制机构应当进行协调，力求达成一致意见。对有较大争议的重要立法事项，法制机构可以委托有关专家、教学科研单位、社会组织进行评估。"},{"i":25,"n":"第二十五条","txt":"法制机构应当认真研究各方面的意见，与起草单位协商后，对规章送审稿进行修改，形成规章草案和对草案的说明。说明应当包括制定规章拟解决的主要问题、确立的主要措施以及与有关部门的协调情况等。"},{"i":26,"n":"第二十六条","txt":"法制机构起草或者组织起草的规章草案，由法制机构主要负责人签署，提出提请本部门或者本级人民政府有关会议审议的建议。"},{"i":27,"n":"第二十七条","txt":"部门规章应当经部务会议或者委员会会议决定。"},{"i":28,"n":"第二十八条","txt":"审议规章草案时，由法制机构作说明，也可以由起草单位作说明。"},{"i":29,"n":"第二十九条","txt":"法制机构应当根据有关会议审议意见对规章草案进行修改，形成草案修改稿，报请本部门首长或者省长、自治区主席、市长、自治州州长签署命令予以公布。"},{"i":30,"n":"第三十条","txt":"公布规章的命令应当载明该规章的制定机关、序号、规章名称、通过日期、施行日期、部门首长或者省长、自治区主席、市长、自治州州长署名以及公布日期。"},{"i":31,"n":"第三十一条","txt":"部门规章签署公布后，及时在国务院公报或者部门公报和中国政府法制信息网以及在全国范围内发行的报纸上刊载。"},{"i":32,"n":"第三十二条","txt":"规章应当自公布之日起30日后施行；但是，涉及国家安全、外汇汇率、货币政策的确定以及公布后不立即施行将有碍规章施行的，可以自公布之日起施行。"},{"i":33,"n":"第三十三条","txt":"规章解释权属于规章制定机关。"},{"i":34,"n":"第三十四条","txt":"规章应当自公布之日起30日内，由法制机构依照立法法和《法规规章备案条例》的规定向有关机关备案。"},{"i":35,"n":"第三十五条","txt":"国家机关、社会团体、企业事业组织、公民认为规章同法律、行政法规相抵触的，可以向国务院书面提出审查的建议，由国务院法制机构研究并提出处理意见，按照规定程序处理。"},{"i":36,"n":"第三十六条","txt":"依法不具有规章制定权的县级以上地方人民政府制定、发布具有普遍约束力的决定、命令，参照本条例规定的程序执行。"},{"i":37,"n":"第三十七条","txt":"国务院部门，省、自治区、直辖市和设区的市、自治州的人民政府，应当根据全面深化改革、经济社会发展需要以及上位法规定，及时组织开展规章清理工作。对不适应全面深化改革和经济社会发展要求、不符合上位法规定的规章，应当及时修改或者废止。"},{"i":38,"n":"第三十八条","txt":"国务院部门，省、自治区、直辖市和设区的市、自治州的人民政府，可以组织对有关规章或者规章中的有关规定进行立法后评估，并把评估结果作为修改、废止有关规章的重要参考。"},{"i":39,"n":"第三十九条","txt":"规章的修改、废止程序适用本条例的有关规定。"},{"i":40,"n":"第四十条","txt":"编辑出版正式版本、民族文版、外文版本的规章汇编，由法制机构依照《法规汇编编辑出版管理规定》的有关规定执行。"},{"i":41,"n":"第四十一条","txt":"本条例自2002年1月1日起施行。"}],"zhongdaxingzhengjuecechengxuzanxingtiaoli":[{"i":1,"n":"第一条","txt":"为了健全科学、民主、依法决策机制，规范重大行政决策程序，提高决策质量和效率，明确决策责任，根据宪法、地方各级人民代表大会和地方各级人民政府组织法等规定，制定本条例。"},{"i":2,"n":"第二条","txt":"县级以上地方人民政府（以下称决策机关）重大行政决策的作出和调整程序，适用本条例。"},{"i":3,"n":"第三条","txt":"本条例所称重大行政决策事项（以下简称决策事项）包括："},{"i":4,"n":"第四条","txt":"重大行政决策必须坚持和加强党的全面领导，全面贯彻党的路线方针政策和决策部署，发挥党的领导核心作用，把党的领导贯彻到重大行政决策全过程。"},{"i":5,"n":"第五条","txt":"作出重大行政决策应当遵循科学决策原则，贯彻创新、协调、绿色、开放、共享的发展理念，坚持从实际出发，运用科学技术和方法，尊重客观规律，适应经济社会发展和全面深化改革要求。"},{"i":6,"n":"第六条","txt":"作出重大行政决策应当遵循民主决策原则，充分听取各方面意见，保障人民群众通过多种途径和形式参与决策。"},{"i":7,"n":"第七条","txt":"作出重大行政决策应当遵循依法决策原则，严格遵守法定权限，依法履行法定程序，保证决策内容符合法律、法规和规章等规定。"},{"i":8,"n":"第八条","txt":"重大行政决策依法接受本级人民代表大会及其常务委员会的监督，根据法律、法规规定属于本级人民代表大会及其常务委员会讨论决定的重大事项范围或者应当在出台前向本级人民代表大会常务委员会报告的，按照有关规定办理。"},{"i":9,"n":"第九条","txt":"重大行政决策情况应当作为考核评价决策机关及其领导人员的重要内容。"},{"i":10,"n":"第十条","txt":"对各方面提出的决策事项建议，按照下列规定进行研究论证后，报请决策机关决定是否启动决策程序："},{"i":11,"n":"第十一条","txt":"决策机关决定启动决策程序的，应当明确决策事项的承办单位（以下简称决策承办单位），由决策承办单位负责重大行政决策草案的拟订等工作。决策事项需要两个以上单位承办的，应当明确牵头的决策承办单位。"},{"i":12,"n":"第十二条","txt":"决策承办单位应当在广泛深入开展调查研究、全面准确掌握有关信息、充分协商协调的基础上，拟订决策草案。"},{"i":13,"n":"第十三条","txt":"决策事项涉及决策机关所属部门、下一级人民政府等单位的职责，或者与其关系紧密的，决策承办单位应当与其充分协商；不能取得一致意见的，应当向决策机关说明争议的主要问题，有关单位的意见，决策承办单位的意见、理由和依据。"},{"i":14,"n":"第十四条","txt":"决策承办单位应当采取便于社会公众参与的方式充分听取意见，依法不予公开的决策事项除外。"},{"i":15,"n":"第十五条","txt":"决策事项向社会公开征求意见的，决策承办单位应当通过政府网站、政务新媒体以及报刊、广播、电视等便于社会公众知晓的途径，公布决策草案及其说明等材料，明确提出意见的方式和期限。公开征求意见的期限一般不少于30日；因情况紧急等原因需要缩短期限的，公开征求意见时应当予以说明。"},{"i":16,"n":"第十六条","txt":"决策事项直接涉及公民、法人、其他组织切身利益或者存在较大分歧的，可以召开听证会。法律、法规、规章对召开听证会另有规定的，依照其规定。"},{"i":17,"n":"第十七条","txt":"听证会应当按照下列程序公开举行："},{"i":18,"n":"第十八条","txt":"决策承办单位应当对社会各方面提出的意见进行归纳整理、研究论证，充分采纳合理意见，完善决策草案。"},{"i":19,"n":"第十九条","txt":"对专业性、技术性较强的决策事项，决策承办单位应当组织专家、专业机构论证其必要性、可行性、科学性等，并提供必要保障。"},{"i":20,"n":"第二十条","txt":"决策承办单位组织专家论证，可以采取论证会、书面咨询、委托咨询论证等方式。选择专家、专业机构参与论证，应当坚持专业性、代表性和中立性，注重选择持不同意见的专家、专业机构，不得选择与决策事项有直接利害关系的专家、专业机构。"},{"i":21,"n":"第二十一条","txt":"省、自治区、直辖市人民政府应当建立决策咨询论证专家库，规范专家库运行管理制度，健全专家诚信考核和退出机制。"},{"i":22,"n":"第二十二条","txt":"重大行政决策的实施可能对社会稳定、公共安全等方面造成不利影响的，决策承办单位或者负责风险评估工作的其他单位应当组织评估决策草案的风险可控性。"},{"i":23,"n":"第二十三条","txt":"开展风险评估，可以通过舆情跟踪、重点走访、会商分析等方式，运用定性分析与定量分析等方法，对决策实施的风险进行科学预测、综合研判。"},{"i":24,"n":"第二十四条","txt":"风险评估结果应当作为重大行政决策的重要依据。决策机关认为风险可控的，可以作出决策；认为风险不可控的，在采取调整决策草案等措施确保风险可控后，可以作出决策。"},{"i":25,"n":"第二十五条","txt":"决策草案提交决策机关讨论前，应当由负责合法性审查的部门进行合法性审查。不得以征求意见等方式代替合法性审查。"},{"i":26,"n":"第二十六条","txt":"送请合法性审查，应当提供决策草案及相关材料，包括有关法律、法规、规章等依据和履行决策法定程序的说明等。提供的材料不符合要求的，负责合法性审查的部门可以退回，或者要求补充。"},{"i":27,"n":"第二十七条","txt":"合法性审查的内容包括："},{"i":28,"n":"第二十八条","txt":"负责合法性审查的部门应当及时提出合法性审查意见，并对合法性审查意见负责。在合法性审查过程中，应当组织法律顾问、公职律师提出法律意见。决策承办单位根据合法性审查意见进行必要的调整或者补充。"},{"i":29,"n":"第二十九条","txt":"决策承办单位提交决策机关讨论决策草案，应当报送下列材料："},{"i":30,"n":"第三十条","txt":"决策草案应当经决策机关常务会议或者全体会议讨论。决策机关行政首长在集体讨论的基础上作出决定。"},{"i":31,"n":"第三十一条","txt":"重大行政决策出台前应当按照规定向同级党委请示报告。"},{"i":32,"n":"第三十二条","txt":"决策机关应当通过本级人民政府公报和政府网站以及在本行政区域内发行的报纸等途径及时公布重大行政决策。对社会公众普遍关心或者专业性、技术性较强的重大行政决策，应当说明公众意见、专家论证意见的采纳情况，通过新闻发布会、接受访谈等方式进行宣传解读。依法不予公开的除外。"},{"i":33,"n":"第三十三条","txt":"决策机关应当建立重大行政决策过程记录和材料归档制度，由有关单位将履行决策程序形成的记录、材料及时完整归档。"},{"i":34,"n":"第三十四条","txt":"决策机关应当明确负责重大行政决策执行工作的单位（以下简称决策执行单位），并对决策执行情况进行督促检查。决策执行单位应当依法全面、及时、正确执行重大行政决策，并向决策机关报告决策执行情况。"},{"i":35,"n":"第三十五条","txt":"决策执行单位发现重大行政决策存在问题、客观情况发生重大变化，或者决策执行中发生不可抗力等严重影响决策目标实现的，应当及时向决策机关报告。"},{"i":36,"n":"第三十六条","txt":"有下列情形之一的，决策机关可以组织决策后评估，并确定承担评估具体工作的单位："},{"i":37,"n":"第三十七条","txt":"依法作出的重大行政决策，未经法定程序不得随意变更或者停止执行；执行中出现本条例第三十五条规定的情形、情况紧急的，决策机关行政首长可以先决定中止执行；需要作出重大调整的，应当依照本条例履行相关法定程序。"},{"i":38,"n":"第三十八条","txt":"决策机关违反本条例规定的，由上一级行政机关责令改正，对决策机关行政首长、负有责任的其他领导人员和直接责任人员依法追究责任。"},{"i":39,"n":"第三十九条","txt":"决策承办单位或者承担决策有关工作的单位未按照本条例规定履行决策程序或者履行决策程序时失职渎职、弄虚作假的，由决策机关责令改正，对负有责任的领导人员和直接责任人员依法追究责任。"},{"i":40,"n":"第四十条","txt":"决策执行单位拒不执行、推诿执行、拖延执行重大行政决策，或者对执行中发现的重大问题瞒报、谎报或者漏报的，由决策机关责令改正，对负有责任的领导人员和直接责任人员依法追究责任。"},{"i":41,"n":"第四十一条","txt":"承担论证评估工作的专家、专业机构、社会组织等违反职业道德和本条例规定的，予以通报批评、责令限期整改；造成严重后果的，取消评估资格、承担相应责任。"},{"i":42,"n":"第四十二条","txt":"县级以上人民政府部门和乡级人民政府重大行政决策的作出和调整程序，参照本条例规定执行。"},{"i":43,"n":"第四十三条","txt":"省、自治区、直辖市人民政府根据本条例制定本行政区域重大行政决策程序的具体制度。"},{"i":44,"n":"第四十四条","txt":"本条例自2019年9月1日起施行。"}],"chongxinzujianzhongcaijigoufangan":[{"i":1,"n":"第一条","txt":"为了规范本仲裁委员会的行为，保证公正、及时地仲裁经济纠纷，保护当事人的合法权益，根据《中华人民共和国仲裁法》（以下简称仲裁法），制定本章程。"},{"i":2,"n":"第二条","txt":"平等主体的公民、法人和其他组织之间发生合同纠纷和其他财产权益纠纷，可以依法向本仲裁委员会申请仲裁。"},{"i":3,"n":"第三条","txt":"本仲裁委员会（以下简称仲裁委员会）会址设在××市。"},{"i":4,"n":"第四条","txt":"仲裁委员会由主任1人、副主任2至4人和委员7至11人组成。其中，驻会专职组成人员1至2人，其他组成人员均为兼职。"},{"i":5,"n":"第五条","txt":"仲裁委员会每届任期3年。任期届满，更换1/3组成人员。"},{"i":6,"n":"第六条","txt":"新一届仲裁委员会组成人员由上一届仲裁委员会主任会议商市人民政府有关部门、商会后提名，由市人民政府聘任。"},{"i":7,"n":"第七条","txt":"仲裁委员会会议由主任或者主任委托的副主任主持。每次会议须有2/3以上的组成人员出席，方能举行。修改章程或者对仲裁委员会作出解散决议，须经全体组成人员的2/3以上通过，其他决议须经出席会议组成人员的2/3以上通过。"},{"i":8,"n":"第八条","txt":"仲裁委员会会议的主要职责是："},{"i":9,"n":"第九条","txt":"仲裁委员会主任、副主任和秘书长组成主任会议，在仲裁委员会会议闭会期间，负责仲裁委员会的重要日常工作。"},{"i":10,"n":"第十条","txt":"仲裁委员会可以根据需要设立专家咨询机构，为仲裁委员会和仲裁员提供对疑难问题的咨询意见。"},{"i":11,"n":"第十一条","txt":"仲裁委员会会议作出解散决议并经市人民政府同意，仲裁委员会应当终止。"},{"i":12,"n":"第十二条","txt":"仲裁委员会下设办事机构。办事机构在仲裁委员会秘书长领导下负责处理仲裁委员会的日常工作。"},{"i":13,"n":"第十三条","txt":"办事机构工作人员，由仲裁委员会主任会议决定聘用。"},{"i":14,"n":"第十四条","txt":"仲裁员名单由仲裁委员会主任会议提出，经仲裁委员会会议审议通过后，由仲裁委员会聘任，发给聘书。"},{"i":15,"n":"第十五条","txt":"仲裁委员会按照不同专业设立仲裁员名册。"},{"i":16,"n":"第十六条","txt":"仲裁员应当严格遵守仲裁规则的规定，保证当事人行使仲裁规则规定的权利。"},{"i":17,"n":"第十七条","txt":"仲裁员应当平等对待双方当事人，不得代表或者偏袒任何一方当事人。"},{"i":18,"n":"第十八条","txt":"仲裁员接受案件后，应当认真、详细审阅当事人提交的全部证据和材料，做好审理的准备工作。"},{"i":19,"n":"第十九条","txt":"仲裁员开庭审理仲裁案件的，应当充分听取双方当事人的陈述，认真查明事实。"},{"i":20,"n":"第二十条","txt":"仲裁员经仲裁庭或者仲裁委员会同意会见当事人、代理人，应当在仲裁委员会办公地点进行；未经仲裁庭或者仲裁委员会同意的，仲裁员不得私自会见任何一方当事人、代理人，不得单独接受一方当事人、代理人提供的证据、材料或者与一方当事人、代理人交谈有关仲裁案件的情况。"},{"i":21,"n":"第二十一条","txt":"仲裁员应当在案件审理终结后及时进行合议，并按规定制作仲裁裁决书。"},{"i":22,"n":"第二十二条","txt":"仲裁员应当严格保守仲裁秘密，不得对外界透露案件审理过程、仲裁庭合议情况、案件涉及的商业秘密等内容。"},{"i":23,"n":"第二十三条","txt":"仲裁员有下列情形之一的，仲裁委员会应当予以解聘："},{"i":24,"n":"第二十四条","txt":"仲裁员私自会见当事人、代理人，或者接受当事人、代理人的请客送礼，或者在仲裁案件时有索贿受贿，徇私舞弊，枉法裁决行为的，应当依法承担法律责任，仲裁委员会应当将其除名。"},{"i":25,"n":"第二十五条","txt":"仲裁委员会的财务实行独立核算。"},{"i":26,"n":"第二十六条","txt":"仲裁委员会的经费来源是："},{"i":27,"n":"第二十七条","txt":"仲裁委员会终止，应当对财产进行清算。清算后，剩余财产归国家所有。"},{"i":28,"n":"第二十八条","txt":"本章程由仲裁委员会负责解释。"},{"i":29,"n":"第二十九条","txt":"本章程自市人民政府批准之日起生效。"},{"i":30,"n":"第一条","txt":"为了保证公正、及时地仲裁经济纠纷，保护当事人的合法权益，根据《中华人民共和国仲裁法》（以下简称仲裁法）和《中华人民共和国民事诉讼法》（以下简称民事诉讼法）的有关规定，制定本暂行规则。"},{"i":31,"n":"第二条","txt":"平等主体的公民、法人和其他组织之间发生合同纠纷和其他财产权益纠纷，可以依法向本仲裁委员会申请仲裁。"},{"i":32,"n":"第三条","txt":"当事人采用仲裁方式解决纠纷，应当双方自愿，达成仲裁协议。没有仲裁协议，一方申请仲裁的，本仲裁委员会不予受理。"},{"i":33,"n":"第四条","txt":"仲裁协议包括合同中订立的仲裁条款和以其他书面方式在纠纷发生前或者纠纷发生后达成的请求仲裁的协议。"},{"i":34,"n":"第五条","txt":"仲裁协议独立存在，合同的变更、解除、终止或者无效，不影响仲裁协议的效力。"},{"i":35,"n":"第六条","txt":"当事人对仲裁协议的效力有异议的，可以请求本仲裁委员会作出决定或者请求人民法院作出裁定。一方请求本仲裁委员会作出决定，另一方请求人民法院作出裁定的，由人民法院裁定。"},{"i":36,"n":"第七条","txt":"当事人申请仲裁应当符合下列条件："},{"i":37,"n":"第八条","txt":"申请人申请仲裁，应当向本仲裁委员会递交仲裁协议、仲裁申请书及副本。"},{"i":38,"n":"第九条","txt":"仲裁申请书应当载明下列事项："},{"i":39,"n":"第十条","txt":"本仲裁委员会收到仲裁申请书之日起5日内，认为符合受理条件的，应当受理，并通知当事人，也可以当即受理，并通知当事人；认为不符合受理条件的，应当书面通知当事人不予受理，并说明理由。"},{"i":40,"n":"第十一条","txt":"本仲裁委员会受理仲裁申请后，应当在15日内将本暂行规则和仲裁员名册送达申请人，并将仲裁申请书副本和暂行规则、仲裁员名册送达被申请人。"},{"i":41,"n":"第十二条","txt":"申请人可以放弃或者变更仲裁请求。被申请人可以承认或者反驳仲裁请求，有权提出反请求。"},{"i":42,"n":"第十三条","txt":"一方当事人因另一方当事人的行为或者其他原因，可能使裁决不能执行或者难以执行的，可以申请财产保全。"},{"i":43,"n":"第十四条","txt":"当事人、法定代理人可以委托律师和其他代理人进行仲裁活动。委托律师和其他代理人进行仲裁活动的，应当向本仲裁委员会提交授权委托书。"},{"i":44,"n":"第十五条","txt":"仲裁庭可以由3名仲裁员或者1名仲裁员组成。由3名仲裁员组成的，设首席仲裁员。"},{"i":45,"n":"第十六条","txt":"当事人约定由3名仲裁员组成仲裁庭的，应当各自选定或者各自委托本仲裁委员会主任指定1名仲裁员，第三名仲裁员由当事人共同选定或者共同委托本仲裁委员会主任指定。第三名仲裁员是首席仲裁员。"},{"i":46,"n":"第十七条","txt":"当事人自收到受理仲裁通知之日起15日内没有约定仲裁庭的组成方式或者选定仲裁员的，由本仲裁委员会主任指定。"},{"i":47,"n":"第十八条","txt":"仲裁庭组成后，本仲裁委员会应当自仲裁庭组成之日起5日内，将仲裁庭的组成情况书面通知当事人，也可以在仲裁庭组成当日将仲裁庭的组成情况书面通知当事人。"},{"i":48,"n":"第十九条","txt":"仲裁员有下列情形之一的，必须回避，当事人也有权提出回避申请："},{"i":49,"n":"第二十条","txt":"当事人提出回避申请，应当说明理由，在首次开庭前提出。回避事由在首次开庭后知道的，可以在最后一次开庭终结前提出。"},{"i":50,"n":"第二十一条","txt":"仲裁员是否回避，由本仲裁委员会主任决定；仲裁委员会主任担任仲裁员时，由本仲裁委员会会议决定。"},{"i":51,"n":"第二十二条","txt":"仲裁员因回避或者其他原因不能履行职责的，应当依照仲裁法和本暂行规则的规定重新选定或者指定仲裁员。"},{"i":52,"n":"第二十三条","txt":"仲裁员私自会见当事人、代理人，或者接受当事人、代理人请客送礼，情节严重的，或者仲裁员在仲裁案件时有索贿受贿，徇私舞弊，枉法裁决行为的，应当依法承担法律责任，本仲裁委员会应当将其除名。"},{"i":53,"n":"第二十四条","txt":"仲裁应当开庭进行。当事人协议不开庭的，仲裁庭可以根据仲裁申请书、答辩书以及其他材料作出裁决。"},{"i":54,"n":"第二十五条","txt":"仲裁不公开进行。当事人协议公开的，可以公开进行，但是涉及国家秘密的除外。"},{"i":55,"n":"第二十六条","txt":"仲裁委员会应当在仲裁庭开庭10日前将开庭日期通知双方当事人；双方当事人经商仲裁庭同意，可以提前开庭。当事人有正当理由的，可以在开庭前7日内请求延期开庭；是否延期，由仲裁庭决定。"},{"i":56,"n":"第二十七条","txt":"申请人经书面通知，无正当理由不到庭或者未经仲裁庭许可中途退庭的，可以视为撤回仲裁申请。"},{"i":57,"n":"第二十八条","txt":"当事人应当对自己的主张提供证据。"},{"i":58,"n":"第二十九条","txt":"书证应当提交原件。物证应当提交原物。提交原件或者原物确有困难的，可以提交复制品、照片、副本、节录本。"},{"i":59,"n":"第三十条","txt":"仲裁庭对专门性问题认为需要鉴定的，可以交由当事人约定的鉴定部门鉴定，也可以由仲裁庭指定的鉴定部门鉴定。"},{"i":60,"n":"第三十一条","txt":"证据应当在开庭时出示，当事人可以互相质证。"},{"i":61,"n":"第三十二条","txt":"在证据可能灭失或者以后难以取得的情况下，当事人可以申请证据保全。当事人申请证据保全的，本仲裁委员会应当将当事人的申请提交证据所在地的基层人民法院。"},{"i":62,"n":"第三十三条","txt":"当事人在仲裁过程中有权进行辩论。辩论终结时，首席仲裁员或者独任仲裁员应当征询当事人的最后意见。"},{"i":63,"n":"第三十四条","txt":"仲裁庭应当将开庭情况记入笔录。当事人和其他仲裁参与人认为对自己陈述的记录有遗漏或者差错的，有权申请补正；如果不予补正，应当记录该申请。"},{"i":64,"n":"第三十五条","txt":"当事人申请仲裁后，可以自行和解。达成和解协议的，可以请求仲裁庭根据和解协议作出裁决书，也可以撤回仲裁申请。"},{"i":65,"n":"第三十六条","txt":"当事人达成和解协议，撤回仲裁申请后反悔的，可以根据仲裁协议申请仲裁。"},{"i":66,"n":"第三十七条","txt":"仲裁庭在作出裁决前，可以先行调解。当事人自愿调解的，仲裁庭应当调解。调解不成的，仲裁庭应当及时作出裁决。"},{"i":67,"n":"第三十八条","txt":"调解书应当写明仲裁请求和当事人协议的结果。调解书由仲裁员签名，加盖本仲裁委员会印章，送达双方当事人。"},{"i":68,"n":"第三十九条","txt":"裁决应当按照多数仲裁员的意见作出，少数仲裁员的不同意见可以记入笔录。仲裁庭不能形成多数意见时，裁决应当按照首席仲裁员的意见作出。"},{"i":69,"n":"第四十条","txt":"仲裁庭仲裁纠纷时，其中一部分事实已经清楚，可以就该部分先行裁决。"},{"i":70,"n":"第四十一条","txt":"仲裁庭应当在仲裁庭组成后4个月内作出仲裁裁决。有特殊情况需要延长的，由首席仲裁员或者独任仲裁员报经本仲裁委员会主任批准，可以适当延长。"},{"i":71,"n":"第四十二条","txt":"裁决书应当写明仲裁请求、争议事实、裁决理由、裁决结果、仲裁费用的负担和裁决日期。"},{"i":72,"n":"第四十三条","txt":"裁决书经仲裁员签名后，仲裁委员会应当加盖本仲裁委员会印章。"},{"i":73,"n":"第四十四条","txt":"裁决书自作出之日起发生法律效力。"},{"i":74,"n":"第四十五条","txt":"对裁决书中的文字、计算错误或者对仲裁庭已经裁决但在裁决书中遗漏的事项，仲裁庭应当补正；当事人自收到裁决书之日起30日内，可以请求仲裁庭补正。"},{"i":75,"n":"第四十六条","txt":"当事人提出证据证明裁决有下列情形之一的，可以自收到仲裁裁决书之日起6个月内向本仲裁委员会所在地的中级人民法院申请撤销裁决："},{"i":76,"n":"第四十七条","txt":"当事人应当在仲裁裁决书确定的期限内履行裁决。未确定履行期限的，当事人应当立即履行。"},{"i":77,"n":"第四十八条","txt":"法律对仲裁时效有规定的，从其规定；法律对仲裁时效没有规定的，适用诉讼时效的规定。"},{"i":78,"n":"第四十九条","txt":"除当事人另有约定或者仲裁庭另有要求外，仲裁文书、通知、材料可以直接送达当事人、代理人，或者以邮寄、传真、电报等方式送达当事人、代理人。"},{"i":79,"n":"第五十条","txt":"期间以时、日、月、年计算。期间开始的时和日，不计算在期间内。"},{"i":80,"n":"第五十一条","txt":"当事人因不可抗拒的事由或者其他正当理由耽误期限的，在障碍消除后的10日内，可以申请顺延期限；是否准许，由本仲裁委员会或者仲裁庭决定。"},{"i":81,"n":"第五十二条","txt":"仲裁员报酬由本仲裁委员会按照仲裁员办理仲裁案件的工作时间、难易程度、争议大小等情况确定。"},{"i":82,"n":"第五十三条","txt":"本暂行规则自  年月 日起生效。"}]};
